window.__HRC_SHARD({"shard":"coi-ukraine","builtAt":"2026-10-23T22:07:26+00:00","documents":[{"rec_id":"recuoVcramRP6ZmSB","doc_id":"COI Ukraine - Official report - 18.10.2022","symbol":"A/77/533","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2022-10-18","year":2022,"bodies":["COI Ukraine"],"paragraphCount":117,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 18-10-2022 - Official document - A_77_533 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recossC69zLk92qJ6","doc_id":"COI Ukraine - Unofficial Annex - 29.08.2023","symbol":"A/HRC/52/CRP.4","title":"Conference room paper of the Independent International Commission of Inquiry on Ukraine","type":"Unofficial Annex","date":"2023-08-29","year":2023,"bodies":["COI Ukraine"],"paragraphCount":1002,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 29-08-2023 - Official report - A_HRC_52_CRP.4 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recXaNYqw5G1g6GC0","doc_id":"COI Ukraine - Official report - 25.09.2023","symbol":"A/HRC/52/62","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2023-09-25","year":2023,"bodies":["COI Ukraine"],"paragraphCount":118,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 25-09-2023 - Official document - A_HRC_52_62 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rectWzP7iekU235fu","doc_id":"COI Ukraine - Official report - 19.10.2023","symbol":"A/78/540","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2023-10-19","year":2023,"bodies":["COI Ukraine"],"paragraphCount":115,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 19-10-2023 - Official document - A_78_540 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recsSTV76B4zKE8f6","doc_id":"COI Ukraine - Official report - 18.03.2024","symbol":"A/HRC/55/66","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2024-03-18","year":2024,"bodies":["COI Ukraine"],"paragraphCount":112,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 18-03-2024 - Official document - A_HRC_55_66 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec1uYjjr0orynFeu","doc_id":"COI Ukraine - Official report - 25.10.2024","symbol":"A/79/549","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2024-10-25","year":2024,"bodies":["COI Ukraine"],"paragraphCount":107,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 25-10-2024 - Official document - A_79_549 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recnkiaWE3B1FiOOY","doc_id":"COI Ukraine - Official report - 11.03.2025","symbol":"A/HRC/58/67","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2025-03-11","year":2025,"bodies":["COI Ukraine"],"paragraphCount":91,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 11-03-2025 - Official report - A_HRC_58_67 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recuDQl6wBnWJRbIS","doc_id":"COI Ukraine - Unofficial Annex - 28.05.2025","symbol":"A/HRC/59/CRP.2","title":"'They are hunting us’: systematic drone attacks targeting civilians in Kherson","type":"Unofficial Annex","date":"2025-05-28","year":2025,"bodies":["COI Ukraine"],"paragraphCount":64,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 28-05-2025 - Official report - A_HRC_59_CRP.2 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recfpYcoZVA1lSABR","doc_id":"COI Ukraine - Official report - 21.10.2025","symbol":"A/80/497","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2025-10-21","year":2025,"bodies":["COI Ukraine"],"paragraphCount":91,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 21-10-2025 - Official report - A_80_497 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recugxpx8PnTwalHJ","doc_id":"COI Ukraine - CRP - 09.03.2026","symbol":"A/HRC/61/CRP.8","title":"\"I am still looking for my daughter\": crimes against humanity committed by Russian authorities against children from Ukraine","type":"CRP","date":"2026-03-09","year":2026,"bodies":["COI Ukraine"],"paragraphCount":76,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/COI Ukraine - 09-03-2026 - CRP - A_HRC_61_CRP.8 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recFgrSZhEmSTQra7","doc_id":"COI Ukraine - Official report - 09.03.2026","symbol":"A/HRC/61/61","title":"Report of the Independent International Commission of Inquiry on Ukraine","type":"Official report","date":"2026-03-09","year":2026,"bodies":["COI Ukraine"],"paragraphCount":89,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Ukraine - 30-03-2026 - Official report - A_HRC_61_61 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-77-533-u0000","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":null,"seq":0,"section":null,"text":"The Secretary-General has the honour to transmit to the General Assembly the\nreport of the Independent International Commission of Inquiry on Ukraine, submitted\nin accordance with paragraph 11 (f) of Human Rights Council resolution 49/1, on the\nsituation of human rights in Ukraine stemming from the Russian aggression.","unnumbered":true},{"id":"a-77-533-u0001","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":null,"seq":1,"section":null,"text":"Summary\nIn the present report, the Independent International Commission of Inquiry on\nUkraine refers to findings about events during late February and March 2022 in the\nfour provinces of Kyiv, Chernihiv, Kharkiv and Sumy, as requested by the Human\nRights Council in its resolution S-34/1.\nDuring this first phase of its investigations, the Commission has found that war\ncrimes and violations of human rights and international humanitarian law have been\ncommitted in Ukraine since 24 February 2022. Russian armed forces are responsible\nfor the vast majority of the violations identified.\nUkrainian forces have also committed international humanitarian law violations\nin some cases, including two incidents that qualify as war crimes.\nThe Commission, composed of three experts, applies a “reasonable grounds to\nconclude” standard of proof in reaching its conclusions, based on a body of verified\ninformation.\nThe relentless use of explosive weapons with wide area effects in populated\nareas has killed and injured scores of civilians and devastated ent ire neighbourhoods.\nThe Commission documented indiscriminate attacks using cluster munitions,\nunguided rockets and air strikes in the context of attempts by Russian armed forces\nto capture towns and smaller settlements.\nThese weapon systems are highly likely to have indiscriminate effects and cause\nsignificant harm to civilians. Indeed, most of the verified deaths since the outset of\nthe hostilities have been caused by these weapons. Residential buildings, schools and\nhospitals, among other parts of the civilian infrastructure, have been damaged or destroyed.\nThe Commission also found that Russian armed forces had shot at civilians\nattempting to flee, and that during the conduct of hostilities, the parties had deployed\ntheir military assets and troops in ways that can endanger civilians, in contravention\nof international humanitarian law.\nFurthermore, the Commission documented patterns of summary executions,\nunlawful confinement, torture, ill-treatment, and rape and other sexual violence\ncommitted in areas occupied by Russian armed forces across the four provinces on\nwhich it focused. People have been detained, some have been unlawfully deported to\nthe Russian Federation, and many are still reported missing. Sexual violence has\naffected victims of all ages. Victims, including children, were sometimes forced to\nwitness the crimes.\nChildren have become the victims of the full spectrum of violations investigated\nby the Commission, including indiscriminate attacks, torture and rape, suffering the\npredictable psychological consequences.\nThese violations continue to have a devastating effect on victims and survivors.\nSignificantly, victims emphasized the essential role of justice and accountability. In\nthis regard, the Commission recommends enhanced coordination of international and\nnational accountability efforts to improve effectiveness and prevent harm to victims\nand witnesses. The Commission, consistent with its mandate, will seek to contribute\nto the identification of those responsible.","unnumbered":true},{"id":"a-77-533-p0001","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"1","seq":2,"section":null,"text":"The Independent International Commission of Inquiry on Ukraine submits\nherewith its first report to the General Assembly on the progress of its work and\npreliminary findings."},{"id":"a-77-533-p0002","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"2","seq":3,"section":null,"text":"In its resolution 49/1 of 4 March 2022, the Human Rights Council decided to\nurgently establish an independent international commission of inquiry to investigate\nall alleged violations and abuses of human rights and violatio ns of international\nhumanitarian law and related crimes in the context of the aggression against Ukraine\nby the Russian Federation. The Council mandated the Commission to establish the\nfacts, circumstances and root causes of such violations, and, where pos sible, to\nidentify those responsible, as well as to make recommendations, in particular on\naccountability measures."},{"id":"a-77-533-p0003","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"3","seq":4,"section":null,"text":"The Human Rights Council called upon the Commission to collect, consolidate\nand analyse evidence, including through field engagement and in cooperation with\njudicial and other entities, and to provide it with an oral update at its fifty -first session\nand a comprehensive written report at its fifty-second session and to submit a report\nto the General Assembly at its seventy-seventh session."},{"id":"a-77-533-p0004","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"4","seq":5,"section":null,"text":"On 30 March 2022, the President of the Human Rights Council announced the\nappointment of Erik Møse (Norway), Jasminka Džumhur (Bosnia and Herzegovina)\nand Pablo de Greiff (Colombia) to serve as the three independent members of the\nCommission, with Mr. Møse serving as Chair."},{"id":"a-77-533-p0005","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"5","seq":6,"section":null,"text":"In its resolution S-34/1 of 12 May 2022, on the deteriorating human rights\nsituation in Ukraine, the Council further requested the Commission to conduct an\ninquiry to address the events in the areas of the provinces of Kyiv, Chernihiv, Kharkiv\nand Sumy in late February and in March 2022, including their gender dimension, with\na view to holding those responsible to account, and to include its findings in its report\nto the Council.\nII. Methods of work\nA.   Mandate and methodology of the Commission"},{"id":"a-77-533-p0006","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"6","seq":7,"section":null,"text":"The Commission considers all violations and abuses of human rights and\nviolations of international humanitarian law and related crimes committed in Ukraine\nwithin its internationally recognized borders, as well as outside its territory, provided\nsuch events occurred in the context of the aggression against Ukraine by the Russian\nFederation. Guided by the principles of independence, impartiality, objectivity and\nintegrity, the Commission examines allegations of violations regardless of the identity\nor nationality of the alleged responsible individual or entity. In addition to making\nrecommendations regarding criminal accountability and identifying responsible\nindividuals or entities where possible, the Commission will make recommendations\nabout other dimensions of accountability to which victims have rights."},{"id":"a-77-533-p0007","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"7","seq":8,"section":null,"text":"The Commission adopts a victim-centred approach in all aspects of its work,\nstrictly respecting the “do no harm” principle, including in relation to guarantees\nregarding the confidentiality of the information received and the protection of victims\nand witnesses."},{"id":"a-77-533-p0008","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"8","seq":9,"section":null,"text":"Given the large number of allegations of violations and abuses of human rights\nand violations of international humanitarian law falling under its mandate, the limited\nresources and time available and the challenges in gaining access to certain victims,\nwitnesses and areas affected by the hostilities, the Commission cannot possibly\nexamine all reported incidents. It focuses on incidents selected based on the gravity\nof the allegations, their significance in demonstrating patterns of alleged violations,\nthe access to victims, witnesses and supporting documentation, and the geographic\nlocations of the incidents. Particular consideration is given to the gender dimensions\nof violations and their impact on women, children and people affected by\nintersectional inequalities."},{"id":"a-77-533-p0009","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"9","seq":10,"section":null,"text":"The findings rely primarily on first-hand information, including interviews with\nwitnesses and victims of alleged violations and abuses. The Commission seeks further\ncorroboration from available primary and secondary sources from States, United\nNations agencies, funds and programmes, civil society organizations, media and other\nrelevant actors. It also issued a call for submission of information and documentation\nrelevant to its mandate."},{"id":"a-77-533-p0010","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"10","seq":11,"section":null,"text":"Consistent with the standard of proof followed by most international\ncommissions of inquiry, the Commission includes findings in its report when, based\non a body of verified information, an objective and ordinary prudent observer would\nhave reasonable grounds to conclude that the facts took place as described. It draws\nlegal conclusions when there are reasonable grounds to conclude that the facts meet\nall the elements of a violation or abuse and, where possible, that an individual or\nentity is responsible for the violation or abuse."},{"id":"a-77-533-p0011","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"11","seq":12,"section":null,"text":"At the time of submission of the present report, the Commission had travelled\nto Ukraine five times and visited 27 cities, towns an d settlements to conduct its\ninquiry into the events. The team collected and preserved evidence of violations and\nrelated crimes."},{"id":"a-77-533-p0012","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"12","seq":13,"section":null,"text":"In preparing the report, the Commission relied on 191 interviews with 110\nwomen and 81 men, conducted in person and remotely, inspected sites of destruction,\ngraves, places of detention and torture, as well as weapon remnants, and consulted a\nlarge number of documents and reports. It met with Government authorities,\ninternational organizations, civil society and other relevan t stakeholders."},{"id":"a-77-533-p0013","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"13","seq":14,"section":null,"text":"The Commission expresses its gratitude to those who shared their – often-\ntraumatic – experiences and appreciates the assistance provided by Governments,\nUnited Nations agencies, funds and programmes, and civil society organizations.\nB.       Legal framework"},{"id":"a-77-533-p0014","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"14","seq":15,"section":null,"text":"Pursuant to Human Rights Council resolution 49/1, international human rights\nlaw, international humanitarian law and international criminal law constitute the laws\napplicable to the mandate of the Commission."},{"id":"a-77-533-p0015","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"15","seq":16,"section":null,"text":"As for international human rights law, both Ukraine and the Russian Federation\nare party to seven of the nine core human rights instruments. 1 Ukraine is also party to\nanother core human rights treaty, namely, the Convention for the Protection of All\nPersons from Enforced Disappearance. Both States have ratified the Optional\nProtocol to the Convention on the Rights of the Child on the involvement of children\nin armed conflict."},{"id":"a-77-533-p0016","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"16","seq":17,"section":null,"text":"With regard to international humanitarian law, both Ukraine and the Russian\nFederation are party to, among others, the four Geneva Conventions of 1949. 2\nUkraine acceded to Additional Protocols I, II and III of the Geneva Conventions,\nwhile the Russian Federation acceded to Additional Protocol s I and II and signed\nAdditional Protocol III. Along with treaty law, the Commission will apply customary\ninternational humanitarian law. Relevant provisions and rules of international\nhumanitarian law are also binding upon non-State actors that may be involved in the\nconflict."},{"id":"a-77-533-p0017","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"17","seq":18,"section":null,"text":"The situation in Ukraine is an international armed conflict, pursuant to common\narticle 2 of the four Geneva Conventions, owing to the armed hostilities existing\nbetween the two States, through their respective armed forces or ot her actors acting\non their behalf."},{"id":"a-77-533-p0018","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"18","seq":19,"section":null,"text":"In terms of international criminal law, the Commission will apply the relevant\ninternational treaties and customary international law. Neither Ukraine nor the\nRussian Federation are parties to the Rome Statute of the International Criminal\nCourt. However, the Court has jurisdiction in Ukraine, pursuant to two declarations\nlodged by Ukraine and referrals by States parties to the Rome Statute. 3 The Rome\nStatute provides detailed elements for some of the alleged crimes. The ratification of\nthe Statute by a majority of the States Members of the United Nations reflects, on the\nwhole, the definition of these crimes under customary international law. 4 Where the\nCourt is found to lack jurisdiction, the Commission will apply the elements of crimes\nwithin the Rome Statute, as long as they reflect customary international law.\nC.       Cooperation and coordination"},{"id":"a-77-533-p0019","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"19","seq":20,"section":null,"text":"In accordance with Human Rights Council resolution 49/1, the Commission\nexpects to receive full cooperation from a broad range of actors in the course of its\ninvestigations. It has sought cooperation and dialogue with the Governments of\nUkraine and the Russian Federation to, among other things, secure access to the areas\nwhere it conducts its investigations and to obtain responses regarding particular\naspects of its inquiry. It provided the Governments of both States with advance copies\nof the preliminary findings."},{"id":"a-77-533-p0020","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"20","seq":21,"section":null,"text":"The Commission appreciates the cooperation extended by the Government of\nUkraine. It regrets that attempts to establish meaningful communication with\nauthorities of the Russian Federation have been unsuccessful and will persist in its\nefforts in this regard."},{"id":"a-77-533-p0021","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"21","seq":22,"section":null,"text":"The work of the Commission builds on that of the human rights monitoring\nmission in Ukraine and the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR). To ensure its independence and impartiality, the\nCommission follows well-established processes for such cooperation and conducts its\nown investigations independently and separately from any United Nations or other\nentity."},{"id":"a-77-533-p0022","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"22","seq":23,"section":null,"text":"In the view of the Commission, sound coordination between entities engaged in\nthe documentation of the violations and crimes in Ukraine is key to ensurin g\nefficiency and avoiding duplication of efforts and the retraumatization of victims and\nwitnesses. It has therefore engaged with the Office of the Prosecutor of the\nInternational Criminal Court, as well as with other relevant international and national\nentities.\nD.       Accountability and sharing of information and evidence"},{"id":"a-77-533-p0023","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"23","seq":24,"section":null,"text":"Information and documentation collected by the Commission will be shared\nwith competent investigative, prosecutorial and judicial authorities to facilitate and\nexpedite criminal proceedings, under conditions of fairness, due process,\nnon-applicability of the death penalty and compliance with the relevant human rights\nstandards. The consent of witnesses and other interlocutors for external uses of the\ninformation is fundamental in handling such requests. The Commission uses\nprotocols for informed consent from the victims and witnesses during its\ninvestigations. In each case, risks to victims, witnesses or information providers and\nrespect for confidentiality is considered."},{"id":"a-77-533-p0024","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"24","seq":25,"section":"III. Events since 24 February 2022","text":"On 24 February 2022, the President of the Russian Federation, Vladimir Putin,\ndisclosed the launching of a “special military operation” to “seek the demilitarization\nand de-Nazification” of Ukraine. 5 On the same date, Russian armed forces 6 crossed\nvarious border points into Ukraine, including from Belarus, and launched attacks by\nland, air and sea. During the preceding days, President Putin had recognized the\nprovinces of Donetsk and Luhansk, in eastern Ukraine, as independent republics. The\nFederation Council of Russia subsequently approved the military operation in\nUkraine."},{"id":"a-77-533-p0025","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"25","seq":26,"section":"III. Events since 24 February 2022","text":"Calls for an immediate cessation of the hostilities followed. After a draft\nresolution demanding that the Russian Federation cease its use of force against\nUkraine failed to pass in the Security Council owing to a veto by the Russian\nFederation, the General Assembly, in its resolution ES-11/1 of 2 March 2022,\ndemanded that the Russian Federation immediately cease its use of force against\nUkraine and immediately, completely and unconditionally withdraw all of its military\nforces from the territory of Ukraine. In its resolution 49/1 of 4 March 2022, the\nHuman Rights Council stressed the urgent need for the Russian Federation to\nimmediately cease its military hostilities against Ukraine. On 16 March 2022, the\nInternational Court of Justice ordered the Russian Federation to suspend the military\noperations. 7 States and provincial bodies condemned the military operation, called for\nits cessation and imposed far-reaching economic sanctions and other measures. Direct\nand indirect negotiation attempts have not yielded success thus far.\nB.       Military operations"},{"id":"a-77-533-p0026","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"26","seq":27,"section":"III. Events since 24 February 2022","text":"The Ukrainian authorities declared martial law and ordered a general\nmobilization. Military strikes using explosive weapons had been launched by armed\nforces of the Russian Federation across Ukraine, includ ing in areas situated far from\nthe front lines, causing significant civilian casualties and large -scale destruction of\nresidential buildings and critical infrastructure."},{"id":"a-77-533-p0027","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"27","seq":28,"section":"III. Events since 24 February 2022","text":"On the northern front, on 24 February 2022, Russian armed forces advanced\ntowards Kyiv and captured key areas to the north and west of the city. They\nsurrounded Chernihiv and subjected the city to heavy airstrikes and artillery fire,\nwhich severed it from essential supply and evacuation routes."},{"id":"a-77-533-p0028","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"28","seq":29,"section":"III. Events since 24 February 2022","text":"By the end of March 2022, the offensive on Kyiv had stalled. As Russian armed\nforces withdrew from localities that they had occupied temporarily, dozens of dead\npeople and large-scale destruction were uncovered. Following these reports, the\nGeneral Assembly adopted resolution ES-11/3, in which it called for the Russian\nFederation to be suspended from the Human Rights Council."},{"id":"a-77-533-p0029","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"29","seq":30,"section":"III. Events since 24 February 2022","text":"In north-eastern Ukraine, the cities of Kharkiv and Sumy quickly became the\nscenes of heavy urban warfare. Shelling pounded residential and other key buildings\nand led to large-scale destruction. By April 2022, Russian armed forces had\nwithdrawn from the Sumy area. In May 2022, a Ukrainian counter-offensive forced\nRussian armed forces to retreat from Kharkiv. Nevertheless, artillery strikes on the\ncity of Kharkiv and localities nearby continued in the next phase of the operations."},{"id":"a-77-533-p0030","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"30","seq":31,"section":"III. Events since 24 February 2022","text":"In southern Ukraine, Russian armed forces attacked the provinces of Kherson,\nMykolaiv and Zaporizhzhia and occupied several cities and localities. On 26 February\n2022, Russian armed forces launched an offensive on Mariupol. The city suffered\nfrom constant shelling, which led to large-scale destruction. For weeks, heavy\nfighting hampered repeated efforts to evacuate civilians and curtailed the access of\ninhabitants to basic necessities. Tens of thousands of civilians fled. On 20 May 2022,\nthe Russian Federation declared that it had gained full control of the city."},{"id":"a-77-533-p0031","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"31","seq":32,"section":"III. Events since 24 February 2022","text":"Meanwhile, on 19 April 2022, a second phase of the war began. This phase\nconcentrated mainly on the Donetsk and Luhansk Provinces and on the southern front.\nThere was intense, weeks-long fighting in and around the city of Sievierodonetsk,\nuntil its eventual capture by Russian armed forces in June, and in Zaporizhzhia\nProvince. Fighting also raged in Kharkiv Province until September 2022, when\nUkrainian armed forces, 8 in a counter-offensive, recovered large swaths of territory."},{"id":"a-77-533-p0032","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"32","seq":33,"section":"III. Events since 24 February 2022","text":"The conduct of military operations from within or around the Chernobyl and\nZaporizhzhia nuclear plants and the threat by the Russian Federation of use of its\nnuclear capabilities became a major concern for the international community.\nC.       Impact on civilians"},{"id":"a-77-533-p0033","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"33","seq":34,"section":"III. Events since 24 February 2022","text":"Civilian casualties continue to grow. As at 17 October 2022, OHCHR had\nrecorded 6,306 people killed and 9,602 wounded in all of Ukraine since 24 February\n2022. From 24 February to 31 March 2022, in the four provinces under the\nCommission’s investigation, 1,237 civilians, including 112 children, were killed,\naccording to OHCHR. Actual figures are likely to be much higher. Months of fighting\nhave gravely impacted the country’s infrastructure, with thousands of residential\nbuildings, as well as medical and education facilities, destroyed or severely damaged.\nAs of mid-October 2022, millions had lost homes and livelihoods, and were forced to\nflee. Over 7 million people from Ukraine have sought refuge abroad and over\n6 million are internally displaced. In most of the affected areas within Ukraine,\nessential supplies are lacking, and there are access challenges for humanitarian\nassistance."},{"id":"a-77-533-p0034","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"34","seq":35,"section":"III. Events since 24 February 2022","text":"Some people, however, have remained in their homes. Older persons, in\nparticular, have remained, despite the danger, because they may have no place to go,\nwish to protect their homes, may not want to burden their families or may be\nprevented from leaving because of disabilities. Many of them are trapped on or near\nthe front lines and are isolated and in critical need of food, water, heating and medical\nand mental health support. Their difficulties will be exacerbated in the winter."},{"id":"a-77-533-p0035","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"35","seq":36,"section":"III. Events since 24 February 2022","text":"The ongoing hostilities have hampered people’s enjoyment of their human rights\nand fundamental freedoms. Countless allegations of violations and abuses of human\nrights and international humanitarian law and related crimes ha ve been reported. On\n28 February 2022, the Prosecutor of the International Criminal Court opened an\ninvestigation into allegations of war crimes, crimes against humanity and genocide. 9\nNumerous other international and national entities have initiated inve stigations of\nallegations of crimes committed in Ukraine.\nIV. Violations of international law"},{"id":"a-77-533-p0036","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"36","seq":37,"section":"III. Events since 24 February 2022","text":"The Commission has thus far carried out investigations in the provinces of Kyiv,\nChernihiv, Kharkiv and Sumy and has focused on the events in February an d March\n2022, as specified in Human Rights Council resolution S-34/1. The Commission has\nconcentrated on behaviour during the conduct of hostilities, including the use of\nexplosive weapons and the destruction of hospitals and schools, and on violations of\npersonal integrity, including executions, torture and ill-treatment, unlawful\nconfinement, and sexual and gender-based violence. It has also investigated violations\naffecting children."},{"id":"a-77-533-p0037","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"37","seq":38,"section":"III. Events since 24 February 2022","text":"During its inquiry, the Commission established that human rights and\ninternational humanitarian law violations, as well as related crimes, have been\ncommitted in all provinces on which it has focused thus far.\nA.        Conduct of hostilities"},{"id":"a-77-533-p0038","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"38","seq":39,"section":"1. Overview","text":"The Commission found that violations of human rights and international\nhumanitarian law and war crimes had been committed during the conduct of\nhostilities. The Commission documented the indiscriminate use of explosive weapons\nin populated areas that were under attack by Russian armed forces. The Commission\nalso found that Russian armed forces attacked civilians attempting to flee. There were\nalso examples of both parties to the armed conflict, although to different degrees,\nfailing to protect civilians or civilian objects against the effects of attacks, by locating\nmilitary objects and forces within or near densely populated areas."},{"id":"a-77-533-p0039","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"39","seq":40,"section":"2. Impact of explosive weapons on civilian areas","text":"According to OHCHR, the use of explosive weapons with wide-area effects in\npopulated areas caused 1,495 deaths and injuries in the four provinces during the\nperiod under review, which represents 70 per cent of the civilians killed and injured\nin those areas. The actual numbers are likely to be higher. The Commission has\nindependently investigated attacks with explosive weapons. Such attacks had vast\nconsequences in the provinces of its focus, for instance in the cities of Chernihiv,\nSumy and Kharkiv, and impacted all segments of the population."},{"id":"a-77-533-p0040","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"40","seq":41,"section":"2. Impact of explosive weapons on civilian areas","text":"Attacks with explosive weapons had a devastating effect on buildings and\ninfrastructure. Thousands of residential buildings, schools, hospitals and facilities\nhosting essential infrastructure in the four provinces have been damaged or destroyed.\nThe Commission observed first-hand the extent of the damage in all 27 settlements it\nvisited. In Chernihiv, the Commission saw dozens of houses and other buildings that\nhad been destroyed or damaged during the attempt by Russian armed forces to take\nthe city. In Kharkiv, explosive weapons devastated entire areas of the city."},{"id":"a-77-533-p0041","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"41","seq":42,"section":"2. Impact of explosive weapons on civilian areas","text":"Fighting and attacks affected a significant number of hospitals, which generally\nhave protected status under international humanitarian law. The Commission\ndocumented damage to or destruction of five hospitals, three in Ch ernihiv, one in\nSumy and one in Kharkiv. Four of the hospitals were operating when they were hit by\nexplosive weapons. Three were severely or completely damaged, which impacted\naccess by the civilian population to health services. 10"},{"id":"a-77-533-p0042","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"42","seq":43,"section":"2. Impact of explosive weapons on civilian areas","text":"The Commission also documented attacks with explosive weapons that affected\neducational institutions. It visited seven such institutions, where it observed the\ndamage first-hand."},{"id":"a-77-533-p0043","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"43","seq":44,"section":"2. Impact of explosive weapons on civilian areas","text":"The extensive use of explosive weapons has caused immediate and long -lasting\ntrauma and damage and has severely disrupted people’s lives, forcing them to flee or\nlive in fear. One older woman, who fled as hostilities raged in the Kharkiv area, told\nthe Commission: “I don’t live, I just exist; I have nothing left in my soul”."},{"id":"a-77-533-p0044","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"44","seq":45,"section":"3. Indiscriminate attacks with explosive weapons","text":"The Commission has concluded that several attacks with explosive weapons that\nit investigated were indiscriminate and that feasible precautions to reduce civilian\nharm were not taken, in violation of international humanitarian law. Indiscriminate\nattacks are those which are not directed at a specific military objective or employ a\nmethod or means of combat which cannot be directed at a specific military objective\nor the effects of which cannot be limited, as required by international humanitarian\nlaw."},{"id":"a-77-533-p0045","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"45","seq":46,"section":"3. Indiscriminate attacks with explosive weapons","text":"Such attacks are particularly challenging to investigate and to attribute to a\nperpetrator, according to the Commission’s standard of proof, because they occur in\nthe context of fluid and rapidly evolving situations, and the parties to the armed\nconflict use similar weapon systems. The Commission’s investigations are ongoing.\nThe evidence obtained thus far strongly suggests that the Russian armed forces have\ncommitted indiscriminate attacks."},{"id":"a-77-533-p0046","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"46","seq":47,"section":"3. Indiscriminate attacks with explosive weapons","text":"The indiscriminate attacks documented thus far took place in areas controlled\nby the Ukrainian armed forces during attempts by the Russian armed forces to capture\nthose areas. In the city of Chernihiv, for example, when Russian armed forces\nsurrounded the city between 25 February 11 and 31 March 2022, multiple\nindiscriminate attacks with the use of explosive weapons occurred. In Sumy, attacks\noccurred in the context of repeated attempts by Russian armed forces to seize the city\nthrough ground battles and airstrikes."},{"id":"a-77-533-p0047","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"47","seq":48,"section":"3. Indiscriminate attacks with explosive weapons","text":"In reaching the conclusion that the attacks were indiscriminate, the Commission\nhas taken into account the potential existence of military objectives. In some of the\ncases, the Commission collected credible information about the presence of Ukrainian\narmed forces, which might have been the intended target of the attack, at or near the\nimpact locations. Nevertheless, the type and number of munitions used in the attacks\nimpacted civilians and civilian objects in a wider area, beyond the apparent military\nobjective. They therefore constituted indiscriminate attacks."},{"id":"a-77-533-p0048","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"48","seq":49,"section":"3. Indiscriminate attacks with explosive weapons","text":"The Commission documented indiscriminate attacks with the use of cluster\nmunitions, which affect a large area and are therefore indiscriminate when used in\npopulated areas. For instance, in the city of Chernihiv, on 17 March 2022, an attack\nwith cluster munitions struck the Chernihiv Regional Children’s Hospital at a time\nwhen some of the victims were queuing for water on the premises of the hospital. It\nkilled several civilians and injured dozens, including four children."},{"id":"a-77-533-p0049","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"49","seq":50,"section":"3. Indiscriminate attacks with explosive weapons","text":"The Commission documented indiscriminate attacks with the use of unguided\nrockets, which cannot be precisely targeted, affect a large area when fired in salvos\nand are therefore indiscriminate when used in populated area s. On 16 March 2022,\nseveral munitions, including unguided rockets, struck an area in Chernihiv where\nmore than 200 civilians were queuing for bread near a supermarket and killed at least\n14 civilians and injured 26. 12"},{"id":"a-77-533-p0050","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"50","seq":51,"section":"3. Indiscriminate attacks with explosive weapons","text":"Significant civilian harm, both in terms of casualties and damage to buildings\nand infrastructure, resulted from indiscriminate airstrikes using multiple unguided\nbombs in populated areas. On 3 March 2022, an airplane dropped several unguided\nbombs on a residential area near the intersection of Chornovola and Kruhova streets\nin the city of Chernihiv, killing at least 14 civilians and injuring dozens. The\nCommission saw large craters and destruction, indicating that at least six munitions\nstruck within an area of about 130 metres, causing significant damage to the\ninfrastructure. Around the same time, also in Chernihiv, an airplane dropped several\nunguided bombs in the Podusivka district, about 2 kilometres east of the first attack,\nkilling at least six civilians, including one child. The i mpact of the attack spanned\nover 500 metres and affected a large area, which included two schools and residential\nbuildings. In both cases, the Commission identified potential military objectives in\nthe vicinity, which might have been the intended target. However, the area impacted\nwas much larger and the attacks were therefore indiscriminate."},{"id":"a-77-533-p0051","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"51","seq":52,"section":"3. Indiscriminate attacks with explosive weapons","text":"On 7 March 2022, in the city of Sumy, an airstrike dropped at least two bombs\non a residential area, killing at least 15 civilians and injuring 6. The Commission saw\ntwo impact sites, where six houses were entirely destroyed. Other residential\nbuildings were significantly damaged in a radius of more than 100 meters from where\nthe bombs landed. The only potential military objective identified in the vicinity was\na mobilization office, which, according to residents, was not in use at that time."},{"id":"a-77-533-p0052","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"52","seq":53,"section":"4. Endangering civilians","text":"The Commission has found that, in several cases, Russian armed forces appear\nto have deliberately positioned their troops or equipment in residential areas or near\ncivilians to reduce the likelihood of attacks. Russian armed forces also forced\ncivilians to remain inside or in the proximity of their positions, exposing them to\nsignificant risk."},{"id":"a-77-533-p0053","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"53","seq":54,"section":"4. Endangering civilians","text":"In the village of Kozarovychi, in Kyiv Province, an old woman reported that\nwhen Russian armed forces arrived in late February, soldiers came to her house with\norders to find hiding places for their vehicles. The woman and other local residents\ntold the Commission that Russian armed forces placed military vehicles between\nresidential houses, in backyards and in garages and shot at Ukrainian positions from\nbetween the houses. In the village of Lypivka, in Kyiv Province, a woman and her\ndaughter said that when Russian armed forces occupied the area on 28 February,\nsoldiers parked one military vehicle identified as a tank next to their house while the\nwoman and her daughter hid in the basement."},{"id":"a-77-533-p0054","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"54","seq":55,"section":"4. Endangering civilians","text":"Russian armed forces used a similar tactic in March 2022, in the village of\nYahidne, in Chernihiv Province, where they placed military vehicles between houses\nand fired at Ukrainian positions from people’s backyards. In add ition, the soldiers\nconfined 365 civilians in the basement of a school, while they established their\nheadquarters on the ground floor of the same building. Russian armed forces launched\nattacks on Ukrainian positions from the grounds of the school, placing hundreds of\ncivilians confined in the building at significant risk (see paras. 78 and 79 below)."},{"id":"a-77-533-p0055","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"55","seq":56,"section":"4. Endangering civilians","text":"The Commission also documented that in areas controlled by Ukrainian armed\nforces, particularly during the first phase of the hostilities, on some occasi ons, there\nwas a lack of separation between armed forces and civilians, which placed civilians\nat risk. In the city of Chernihiv, residents stated that, although schools 18 and 21 were\nused to distribute humanitarian aid to the civilian population and school staff had\nwritten “children” on the walls of one of the school buildings, Territorial Defence\nForces of the Ukrainian armed forces had set up headquarters in school 18 and their\nmembers were also present at school 21. Both military pe rsonnel and civilians were\namong those killed and injured when an airstrike hit both schools and nearby houses\non 3 March 2022. By not separating civilians from their personnel, the Ukrainian\narmed forces in this case failed to protect civilians under their control from the effects\nof attacks."},{"id":"a-77-533-p0056","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"56","seq":57,"section":"5. Attacks on civilians","text":"The Commission found numerous cases in which Russian armed forces shot at\ncivilians trying to flee to safety and obtain food or other necessities, which resulted\nin the killing or injury of the victims. In the cases documented, the victims wore\ncivilian clothes, drove civilian cars and were unarmed. Most of the incidents took\nplace during daylight, which means that their civilian appearance should have been\nclear to the attacker. Under international humanitarian law, in case of doubt, a person\nshall be considered to be a civilian. Attacks intentionally targeting civilians are war\ncrimes."},{"id":"a-77-533-p0057","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"57","seq":58,"section":"5. Attacks on civilians","text":"Several of the attacks took place as civilians came across Russian military\nconvoys that were on the move. Soldiers shot civilians using assault rifles or, in some\ncases, vehicle-mounted weapons. Those attacks show disregard for the requirement\nunder international humanitarian law to verify that targets are neither civilians nor\ncivilian objects. In some cases, these were deliberate."},{"id":"a-77-533-p0058","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"58","seq":59,"section":"5. Attacks on civilians","text":"Several incidents took place along the E40 highway in Kyiv Province, also\nreferred to as the Zhytomyr highway, as Russian armed forces established control\nover sections of it in late February and March 2022. On 28 Februa ry 2022, around\nnoon, soldiers in a military convoy on the highway opened fire at four civilians who\nwere attempting to flee through the fields. One woman was injured in the leg. On\n1 March 2022, at approximately 10 a.m., soldiers opened fire on a civilian car near\nKopyliv. The couple in the car, both in their sixties, managed to escape uninjured. On\n3 March 2022, also around 10 a.m., a married couple and their two children came\nunder attack near the village of Motyzhyn. The two adults died in the attack. A 9-year-\nold girl survived, while her sister, aged 15, was wounded and is still missing. Other\norganizations have documented additional similar incidents in the same area,\ndemonstrating that these cases were not isolated."},{"id":"a-77-533-p0059","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"59","seq":60,"section":"5. Attacks on civilians","text":"The Commission has received reports of such incidents in multiple locations in\nall four provinces covered in the present report, suggesting a clear pattern. For\nexample, a Russian military convoy attacked a civilian car in the village of\nShevchenkove, in Kyiv Province, killing two civilians, one man and one woman, on\n8 March. A military convoy opened fire on a civilian car near the village of Vyrivka,\nin Sumy Province, on 27 February, killing a man and injuring his adult son. Soldiers\nof the Russian armed forces allegedly shot at two civilian cars as people were trying\nto leave in the village of Stepanky, in Kharkiv Province, on 27 March, killing a\nwoman and a girl. One of the cars was marked with a sign saying “children”.\nB.   Violations against personal integrity"},{"id":"a-77-533-p0060","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"60","seq":61,"section":"1. Overview","text":"Violations of human rights and international humanitarian law against people’s\npersonal integrity have been committed in towns and settlements that Russian armed\nforces occupied in the four provinces. These violations included summary executi ons,\ntorture, ill-treatment, sexual and gender-based violence, unlawful confinement and\ndetention in inhumane conditions, and forced deportations. Such acts also amount to\nwar crimes."},{"id":"a-77-533-p0061","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"61","seq":62,"section":"1. Overview","text":"The Commission also found two cases in which Ukrainian armed forces shot,\nwounded and tortured persons hors de combat, which are war crimes. While few in\nnumbers, such cases will continue to be the object of the Commission’s attention."},{"id":"a-77-533-p0062","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"62","seq":63,"section":"1. Overview","text":"Residents of the localities visited told the Commission that in late February or\nearly March 2022, Russian armed forces arrived in their settlements and often\ndeployed in local schools, administration buildings or residential houses. In most\nplaces, soldiers went door to door in search for “nazis” or “banderovtsy”, which are\nderogatory terms often used by officials of the Russian Federation to describe\nsupporters of the Government of Ukraine. In many cases, they confiscated people’s\nphones."},{"id":"a-77-533-p0063","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"63","seq":64,"section":"1. Overview","text":"In the places that Russian armed forces had occupied, local residents described\nwidespread looting and, at times, wanton destruction. Residents spoke of soldiers\nstealing food and alcohol, personal belongings, valuables, computers and household\nitems, such as washing machines and microwaves, from stores and houses. Soldiers\nfrequently seemed under the influence of alcohol or intoxicated."},{"id":"a-77-533-p0064","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"64","seq":65,"section":"1. Overview","text":"According to the interviewed interlocutors, the behaviour of soldiers of the\nRussian armed forces differed. The Commission has also received reports that some\nRussian armed forces servicemen helped people escape from captivity, interfered with\nattempts of others to commit sexual violence or provided medical assistance to people\ninjured by attacks."},{"id":"a-77-533-p0065","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"65","seq":66,"section":"2. Summary executions","text":"Investigations in the provinces of Kyiv, Chernihiv, Kharkiv and Sumy reveal a\npattern of summary executions in areas temporarily occupied by Russian armed forces\nin February and March 2022, which are violations of the right to life and war crimes."},{"id":"a-77-533-p0066","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"66","seq":67,"section":"2. Summary executions","text":"Many summary executions occurred in Bucha, in Kyiv Province. Local and\ninternational organizations and media outlets have gathered and published extensive\ndocumentation on the events in Bucha. The Commission interviewed a local official\nwho was among the first on the scene after Russian armed forces withdrew. He told\nthe Commission that he saw eight dead bodies in the backyard of the house where the\nsoldiers had established their base. Some of them had their hands tied behind their\nbacks and presented signs of torture. He also saw more than 10 dead bodies of\ncivilians lying on the street. In another incident, five bodies were found in a basement,\nwith their hands behind their backs and gunshot wounds. A woman confirmed that her\nadult son was among the five bodies."},{"id":"a-77-533-p0067","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"67","seq":68,"section":"2. Summary executions","text":"Summary executions took place in numerous other localities. The Commission\nis investigating credible allegations of similar executions in 16 other towns and\nsettlements, involving 49 victims. The majority are men of fighting age, but the total\nincludes two women and one 14-year-old boy. The cases are located in all four\nprovinces under the Commission’s initial focus, suggesting a wide geographical\npattern."},{"id":"a-77-533-p0068","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"68","seq":69,"section":"2. Summary executions","text":"The summary executions verified by the Commission occurred in places where\nRussian armed forces took positions for an extended period of time, close to the front\nlines. This was the case in settlements situated north of Kyiv, where Russian armed\nforces were forced to halt their advance; to the south of Chernihiv, while Russian\narmed forces were launching offensives to capture the city; and close to the separation\nline between Russian armed forces and Ukrainian armed forces in Sumy Province. At\nthe time of writing of the present report, the Commission had not been able to access\ncertain areas of Kharkiv Province because of the continuing precariousness of the\nsecurity situation."},{"id":"a-77-533-p0069","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"69","seq":70,"section":"2. Summary executions","text":"In the cases that the Commission investigated, several elements, often in\ncombination, indicated that the victims were executed. A common element was that\nvictims were last seen in the custody or the presence of Russian armed forces. The\nbodies of the victims were exhumed from separate or mass graves or recovered from\nhouses or basements that the Russian armed forces had occupied. Some victims’ dead\nbodies were found with hands tied behind their back, a clear indication that the victim\nwas in custody and posed no threat at the time of death."},{"id":"a-77-533-p0070","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"70","seq":71,"section":"2. Summary executions","text":"According to witnesses and survivors, some of the perpetrators accused the\nvictims of transmitting information to Ukrainian armed forces, of collaborating with\nthe Ukrainian armed forces or of other contributions to the fighting against Russian\narmed forces. In a case documented in the village of Vyshneve, in Chernihiv Province,\nwhich was occupied by Russian armed forces from 28 February to 4 April 2022,\nwitnesses reported that, on 18 March 2022, as they searched for individuals behind\nan attack on one of their convoys, Russian armed forces arrested three adult brothers.\nThey tied the victims’ hands behind their backs, blindfolded them and beat them\nseverely for three days, after which they shot and buried them in a shallow grave.\nTwo of the brothers died and the third was injured but survived."},{"id":"a-77-533-p0071","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"71","seq":72,"section":"2. Summary executions","text":"The Commission’s investigations show that the cause of death of the victims is\nconsistent with methods typically used during executions: gunshot wounds to th e\nheads, blunt trauma or slit throats. In some cases, there was also evidence of torture\non the bodies, such as bruises, wounds and fractures (see paras. 81 –85 below)."},{"id":"a-77-533-p0072","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"72","seq":73,"section":"2. Summary executions","text":"A case that illustrates several of these patterns, is the killing of six men in the\nvillage of Staryi Bykiv, in Chernihiv Province. Witnesses detailed how Russian armed\nforces apprehended several local residents on 27 February 2022, the day they took\ncontrol of the village, as they were searching for people who had operated a drone\nthat killed one of their soldiers. The perpetrators took the men to their base. Relatives\nheard screams and gunshots from where the soldiers had detained the victims. The\nnext day, they saw the bodies of six men lying on the street where the incident took\nplace, but were not permitted to access the location until nine days later, when Russian\narmed forces finally allowed them to pick up the bodies. The bodies had multiple\ngunshot wounds, stab wounds and broken ribs, and one had a slit throat."},{"id":"a-77-533-p0073","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"73","seq":74,"section":"2. Summary executions","text":"While summary executions were mainly perpetrated following unlawful\ndetention, the Commission also documented cases in which victims were executed in\npublic places as others were watching. In the village of Vesele, in Kharkiv Province,\ntwo witnesses reported that soldiers of the Russian armed forces beat and shot dead a\nperson whom they dragged off a bus that was transporting people to the Russian\nFederation. After the execution, the perpetrators told the other passengers that the\nvictim had been shot and killed because he had been transmitting information to the\nUkrainian armed forces."},{"id":"a-77-533-p0074","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"74","seq":75,"section":"2. Summary executions","text":"The violent loss of a close family member has a profound effect on the survivors.\nFamilies described the trauma, anguish and anger they felt as a consequence of such\nevents. The mother of a man executed in Kyiv Province stated: “I still wake up at\nnight, stand in the dark and scream, call for my son and cry out of pain”."},{"id":"a-77-533-p0075","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"75","seq":76,"section":"3. Unlawful confinement, inhumane treatment and forcible transfers","text":"In late February and March 2022, Russian armed forces unlawfully confined\nlarge numbers of civilians in areas which they controlled, which is a violation of the\nright to liberty and a war crime. Victims included local authorities, Government\npersonnel, veterans of the Ukrainian armed forces, volunteers evacuating civilians\nand civilians who seem to have been randomly arrested. While the majority were\nyoung or middle-aged men, women, children and older persons were also confined.\nIn several cases, perpetrators searched the houses and the phones of t he victims."},{"id":"a-77-533-p0076","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"76","seq":77,"section":"3. Unlawful confinement, inhumane treatment and forcible transfers","text":"Russian armed forces detained individuals in makeshift facilities established in\nbuildings they had occupied, such as the basement of a school, an industrial facility,\nan agricultural facility, a train station, an airport and various dwelli ngs. Victims were\noften not informed of the reasons behind their detention and these acts were not\nreviewed by a judicial authority. Their families were not informed of their\nwhereabouts and some are still reported missing."},{"id":"a-77-533-p0077","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"77","seq":78,"section":"3. Unlawful confinement, inhumane treatment and forcible transfers","text":"In the majority of cases, the detention took place under conditions so severe that\nthe confinement amounted to inhuman conditions, which is a violation of the right to\nbe treated with humanity and with respect for the inherent dignity of the human person\nduring deprivation of liberty and a war crime. Detention was frequently prolonged\nand facilities were cramped and overcrowded, at times with dozens of people forced\nto share a small space and to sleep on the floor. Men, women and children were held\ntogether in the same space. There was a lack of light, ventilation and heating during\nthe freezing March temperatures. Some were confined in a metal cellar. Access to\nfood, water and medical care was limited, and sanitary conditions were lacking.\nUnlawful confinement was often the precursor to execution, sexual violence, torture\nand ill-treatment."},{"id":"a-77-533-p0078","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"78","seq":79,"section":"3. Unlawful confinement, inhumane treatment and forcible transfers","text":"In the village of Yahidne, in Chernihiv Province, soldiers of the Russian armed\nforces confined 365 civilians, including 70 children, for 28 days in the basement of a\nlocal school, where they had established their position in March 2022. Victims\nreported that soldiers threatened to shoot them if they did not assemble in the\nbasement. Soldiers demanded that residents hand in all their phones. The conditions\nof detention were inhumane. According to the victims, the space was so crowded that\nsome were forced to stand or sleep on chairs for weeks. There was no light or\nventilation, and the air was hot and suffocating. Water was dripping from ceilings and\nwalls and there were no showers or toilets."},{"id":"a-77-533-p0079","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"79","seq":80,"section":"3. Unlawful confinement, inhumane treatment and forcible transfers","text":"The soldiers degraded and violated the dignity of the detainees. There was very\nlimited access to food and water, and close to no access to medical care. The victims\nhad to seek permission to exit the premises or to use the toilet, which was only given\nsporadically. In the yard, the soldiers randomly shot near the victims to scare them.\nTen older persons died during the confinement as a result of the inhumane conditions,\nand others developed health problems. The Commission visited the basement and saw\nthe writings of the confined victims on the wall listing the names of those who had\ndied."},{"id":"a-77-533-p0080","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"80","seq":81,"section":"3. Unlawful confinement, inhumane treatment and forcible transfers","text":"In some of the cases documented by the Commission, after initial detention in\nUkraine, individuals were forcibly transferred and unlawfully deported through\nBelarus, or directly, to the Russian Federation, which is a violation of international\nhumanitarian law. In the Russian Federation, victims were further held in detention\nfacilities. Some victims stated that during their transit in Belarus, Russian armed\nforces registered them and provided them with Russian Federation identity cards.\nWitnesses reported seeing dozens of Ukrainian detainees in detention facilities in the\nRussian Federation. Many people are still missing from the areas that were under the\noccupation of Russian armed forces. For example, the Commission received from\nlocal residents in Dymer a list of 58 people still missing in Kyiv Province. Many of\nthem were last seen in the custody of Russian armed forces. While relatives have\nreceived confirmation that some of them are in detention in the Russian Federation,\nthe fate of many is still unknown."},{"id":"a-77-533-p0081","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"81","seq":82,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"The Commission has documented many cases of torture and ill-treatment\ncommitted by Russian armed forces, which is a violation of the prohibition against\ntorture and other cruel, inhuman or degrading treatment or punishment and a war\ncrime. Perpetrators targeted local authorities or employees of the local administration,\nveterans of the Ukrainian armed forces and volunteers helping Ukrainian armed\nforces. They also targeted individuals evacuating civilians. Torture and ill -treatment\noccurred during unlawful confinement in detention facilities in Ukraine and in the\nRussian Federation. The victims were mostly men, but included women as well."},{"id":"a-77-533-p0082","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"82","seq":83,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"According to victims, Russian armed forces carried out long interrogation\nsessions, sometimes lasting for days, which were combined with threats, intimidation,\nill-treatment, sexual violence and torture. These were aimed at extracting information\nabout the Ukrainian armed forces and their positions and local resistance groups, or\nto identify collaborators with Ukrainian armed forces. Perpetrators also accused\nvictims of sharing information with Ukrainian arme d forces and committing attacks\nand sabotage against Russian armed forces. Victims reported that soldiers called the\nvictims “fascists” and “livestock”."},{"id":"a-77-533-p0083","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"83","seq":84,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"Russian armed forces inflicted severe physical and mental pain and suffering\nupon the victims during detention in Ukraine. Some of the treatments administered\nincluded tying of hands or handcuffing, tying of legs, blindfolding with cloth, tape or\nbags placed on heads, severe and prolonged beatings with rifle butts or batons, electric\nshocks with tasers, threats of execution or mock executions and prolonged exposure\nto cold. In some cases, victims were executed after torture (see paras. 69 –72 above).\nOne of the victims who had been detained and tortured by Russian armed forces in\nKyiv Province told the Commission that throughout the detention, during which\ntorture was continuous, it was as if the “body shut down and switched to a survival\nmode”. Victims also described acts of forced nudity for prolonged periods in front of\nothers, which amount to sexual violence."},{"id":"a-77-533-p0084","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"84","seq":85,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"After transfer to and detention in the Russian Federation, victims described how\nthey were stripped naked again, were forced to stand naked in front of others for\nhours, or had hands and feet tied, and underwent long beating sessions. One victi m\nwas severely beaten for two days after refusing to declare support for the Russian\nFederation on camera. Another victim was forced to stand naked and shout “glory to\nRussia” while being beaten, and described beatings as “punishment for speaking\nUkrainian” and “not remembering the lyrics of the anthem of the Russian Federation”."},{"id":"a-77-533-p0085","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"85","seq":86,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"Survivors sustained short-term and long-term injuries and trauma, such as\nbroken facial bones, ribs, knees and fingers, bruises or injuries leading to the inability\nto walk."},{"id":"a-77-533-p0086","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"86","seq":87,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"The Commission has also documented two cases in which Ukrainian armed\nforces shot, wounded and tortured captured soldiers of the Russian armed forces,\nwhich are war crimes. Upon their capture, these soldiers acquired prisoner-of-war\nstatus and were protected under international humanitarian law. The Office of the\nGeneral Prosecutor of Ukraine informed the Commission that his office had opened\ncriminal proceedings regarding both cases."},{"id":"a-77-533-p0087","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"87","seq":88,"section":"4. Torture, ill-treatment and wounding of protected persons","text":"In the first case, in Mala Rohan, in Kharkiv Province, between 24 and 26 March\n2022, soldiers of the Ukrainian armed forces deliberately shot three captured soldiers\nof the Russian armed forces in the legs at close range and beat one of them with a\nrifle butt, while interrogating them. In the second case, near Dmytrivka, in Kyiv\nProvince, around 29 March 2022, a soldier of the Ukrainian armed forces shot three\ntimes at close range and wounded an already wounded soldier of the Russian armed\nforces. A video shows other motionless soldiers of the Russian armed for ces nearby,\nincluding one with his hands tied behind his back and an apparent wound to his head,\nsuggesting that he had likely been executed."},{"id":"a-77-533-p0088","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"88","seq":89,"section":"5. Sexual and gender-based violence","text":"The Commission investigated cases of rape committed by some soldiers o f the\nRussian armed forces during the period under review in localities that came under\ntheir control, which are war crimes. Victims ranged from 4 to over 80 years old.\nPerpetrators raped the women and girls in their homes or took them and raped them\nin unoccupied dwellings. In most cases, these acts also amount to torture and cruel or\ninhumane treatment for the victims and for relatives who were forced to watch. Other\nincidents of sexual violence were also documented against women, men and girls.\nThe Commission continues to investigate the extent to which sexual and gender-based\nviolence constituted a widespread pattern."},{"id":"a-77-533-p0089","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"89","seq":90,"section":"5. Sexual and gender-based violence","text":"Cases relating to sexual and gender-based violence are challenging to\ninvestigate. Victims face obstacles in reporting such violation s. Because of the current\nsecurity situation and forced displacement, victims have difficulties accessing\nappropriate health care, psychological support services and law enforcement offices\nin a timely fashion. Furthermore, it is not always possible to doc ument forensically\nthe existence of rape and the full extent of the victims’ trauma. Autopsy reports often\nfocus on the immediate cause of death rather than the entirety of the trauma sustained\nby the victims because of a lack of resources, families’ reque sts that the post-mortem\nexamination not be carried out or the condition of the remains."},{"id":"a-77-533-p0090","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"90","seq":91,"section":"5. Sexual and gender-based violence","text":"In Kyiv Province, in March 2022, two Russian soldiers entered a home, raped a\n22-year-old woman several times, committed acts of sexual violence on her husband\nand forced the couple to have sexual intercourse in their presence. Then one of the\nsoldiers forced their 4-year-old daughter to perform oral sex on him, which is rape.\nThe Commission is currently investigating three other credible allegations of Russian\narmed forces raping women and teenage girls in the same village. In another village,\nRussian armed forces took a woman out of her house and forced her to go to a\nneighbouring house, where one of the soldiers of the Russian armed forces had shot\ndead a man who had tried to defend his wife. Two soldiers took both women to another\nhouse that served as their base. The soldiers proceeded to different rooms to rape and\nsexually assault the two women."},{"id":"a-77-533-p0091","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"91","seq":92,"section":"5. Sexual and gender-based violence","text":"In another village in Kyiv Province, at the beginning of March 2022, a soldier\nof the Russian armed forces entered the house of a 50-year-old woman. After shooting\nher husband, who tried to interfere, he took the woman to a nearby empty house where\nhe raped her until another Russian armed forces military unit arrived and took him\naway. Her husband died of his injuries two days later, as he could not be taken to the\nhospital. The Commission is investigating another case of alleged sexual violence in\nthe same time period in the same neighbourhood."},{"id":"a-77-533-p0092","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"92","seq":93,"section":"5. Sexual and gender-based violence","text":"In a nearby village, at the beginning of March 2022, two Russian armed forces\nservicemen repeatedly raped a 33-year-old woman after killing her husband. One of\nthe alleged perpetrators has been identified, and criminal proceedings have been\ninitiated in absentia against him. The Commission is investigating another incident\nthat occurred later that month in the same village. A 56-year-old woman explained\nhow two of the three Russian armed forces servicemen who broke into her home gang -\nraped her as the third one watched while masturbating. They stole food and money\nfrom her. She learned a couple of weeks later that, in a separate incident, her husband\nhad been tortured and executed."},{"id":"a-77-533-p0093","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"93","seq":94,"section":"5. Sexual and gender-based violence","text":"In Chernihiv Province and another province, the Commission has b een\ninvestigating two cases of rape of women over 80 years old. An 83 -year-old woman\ndescribed how, while her village was occupied by Russian armed forces, she was\nraped by a Russian armed forces serviceman in her house, where her physically\ndisabled husband was also present. In another instance, neighbours found the body of\nan older woman, partially undressed and with blood around her vagina. At the request\nof the family, the authorities did not perform a full autopsy."},{"id":"a-77-533-p0094","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"94","seq":95,"section":"5. Sexual and gender-based violence","text":"Also in Chernihiv Province, in March 2022, Russian armed forces occupied a\nhome for more than a week. The unit commander repeatedly sexually abused a\n16-year-old girl during that time and threatened to kill other family members who\ntried to protect her. Two of the Russian armed forces se rvicemen were subsequently\nidentified."},{"id":"a-77-533-p0095","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"95","seq":96,"section":"5. Sexual and gender-based violence","text":"There was also an instance in Chernihiv Province, in March 2022, in which a\nRussian armed forces serviceman broke into a house, threatened the inhabitants with\nhis weapon and attempted to rape a woman in front of her 3-year-old son. The\nneighbours, alerted by the noise, ran to the house, while others went to alert his\ncommander."},{"id":"a-77-533-p0096","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"96","seq":97,"section":"5. Sexual and gender-based violence","text":"In Kharkiv Province, the Commission is investigating two cases of repeated rape\nof an adolescent girl over a three-month period, allegedly by a soldier of the Russian\narmed forces, and repeated rape, reportedly by a Russian armed forces serviceman,\nof a 31-year-old woman who was taking shelter in a school basement."},{"id":"a-77-533-p0097","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"97","seq":98,"section":"5. Sexual and gender-based violence","text":"In several incidents documented by the Commission, Russian armed forc es\ncommitted sexual violence against men and women under their custody, often\nresorting to forced nudity in a coercive and humiliating environment."},{"id":"a-77-533-p0098","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"98","seq":99,"section":"5. Sexual and gender-based violence","text":"Survivors and their families remain deeply traumatized by the ordeal they\nendured. One victim told the Commission “this experience is very shameful for me\nand I am extremely scared and intimidated”. In addition, the stigma that continues to\nsurround sexual violence requires patience until victims feel safe enough and\nadequately cared for to speak out about what happened. Some victims refuse to speak.\nSome have considered suicide. One psychologist working with survivors said that “all\nvictims with whom I am working are blaming themselves for being spotted by\nperpetrators and being raped”.\nC.        Impact on children"},{"id":"a-77-533-p0099","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"99","seq":100,"section":"5. Sexual and gender-based violence","text":"The events of late February and March 2022 in the four provinces had a\ndevastating and continuing impact on children’s rights and lives. Children of all ages\nwere killed or wounded in their homes, shelters, streets and playgrounds. OHCHR\nhas verified the deaths of 112 children, including 36 girls, 62 boys and 14 whose sex\ncould not be determined, in the four provinces during the period under review."},{"id":"a-77-533-p0100","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"100","seq":101,"section":"5. Sexual and gender-based violence","text":"Many children died as a consequence of attacks with explosive weapons in\npopulated areas (see paras. 44–51 above). The Commission investigated attacks in\nwhich children were victims. On 25 February 2022, in the town of Okhtyrka, in Sumy\nProvince, for example, two attacks with explosive weapons killed a 7 -year-old girl\nand injured an 8-year-old boy. On 7 March 2022, in the city of Sumy, an attack killed\nfour children between the ages of 6 and 16. In the city of Chernihiv, several airstrikes\nkilled one boy and injured seven children on 3 March 2022."},{"id":"a-77-533-p0101","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"101","seq":102,"section":"5. Sexual and gender-based violence","text":"The Commission documented cases in which violations of the personal integrity\nof children had been committed. In one case, a 14-year-old boy was found dead\ntogether with his neighbour. Both had injuries to their heads consistent with gunshot\nwounds, suggesting that they were executed (see paras. 67–71 above)."},{"id":"a-77-533-p0102","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"102","seq":103,"section":"5. Sexual and gender-based violence","text":"Moreover, the Commission has found that Russian armed forces unlawfully\nconfined children in inhumane conditions. In one case, 70 children were among 365\ncivilians confined for 28 days by Russian armed forces in the basement of a s chool in\nYahidne, in Chernihiv Province, where the soldiers had established their base (see\nparas. 78 and 79 above). Some children fell sick and had no access to medication. The\nyoungest child was only six weeks old."},{"id":"a-77-533-p0103","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"103","seq":104,"section":"5. Sexual and gender-based violence","text":"The Commission confirmed cases of sexual violence in which Russian armed\nforces raped girls when entering or occupying civilian homes. Further, a 4 -year-old\ngirl could hear her mother screaming while she was raped in the adjacent room. Such\nacts also amount to torture."},{"id":"a-77-533-p0104","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"104","seq":105,"section":"5. Sexual and gender-based violence","text":"The hostilities have had a significant impact on children’s right to education.\nAttacks with explosive weapons have damaged or destroyed hundreds of schools and\nkindergartens in the four provinces, according to the Ukrainian authorities. The\nCommission independently documented damage to seven such institutions (see\npara. 42 above). Airstrikes on Chernihiv on 3 March 2022, for example, severely\ndamaged schools 18 and 21, where more than 1,200 pupils had studied previously."},{"id":"a-77-533-p0105","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"105","seq":106,"section":"5. Sexual and gender-based violence","text":"One reason for the extensive damage and destruction to schools is that both the\nRussian armed forces and the Ukrainian armed forces used some of the schools for\nmilitary purposes. 13 The Commission documented one case in which a school in\nKharkiv Province was first occupied by Russian armed forces an d then subsequently\nby Ukrainian forces. While international law does not prohibit military forces from\nusing schools, the presence of military personnel on school premises and their\nutilization for military purposes puts schools at risk of being attacked as military\nobjectives."},{"id":"a-77-533-p0106","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"106","seq":107,"section":"5. Sexual and gender-based violence","text":"The Commission has also examined cases of wanton damage to schools and\nschool equipment. The headmaster of lycée 1 in Hostomel, in Kyiv Province, told the\nCommission that the Russian armed forces that had occupied the village h ad\ndestroyed more than 250 computers, furniture and virtually all of the windows and\ndoors in the school, and had shared photos of the destruction."},{"id":"a-77-533-p0107","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"107","seq":108,"section":"5. Sexual and gender-based violence","text":"The combined effects of the damage and destruction of educational institutions,\nthe massive displacement of pupils and teachers and the fact that a large number of\nschools do not meet the mandated school safety requirements, including adequate\nbomb shelters, mean that a large number of Ukrainian children had to attend classes\nonline when the school year started. Although the Ukrainian authorities have\ndeveloped extensive content for remote schooling, many children, especially in rural\nareas, do not have access to the equipment, electricity or mobile and internet\nconnectivity that would allow them to attend classes remotely, and their right to\neducation is therefore compromised."},{"id":"a-77-533-p0108","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"108","seq":109,"section":"5. Sexual and gender-based violence","text":"The war forced thousands of children to flee, uprooted them from their daily life\nand, in many cases, separated them from their fathers, who either joined the fighting\nor could not leave with their families. Those who stayed were exposed to explosions\nand air raid sirens, and many witnessed traumatic events, including the killing or\nmaiming of parents and loved ones. Parents, family members and aid workers\ndescribed how all these factors had had a deep psychological effect on children. Some\nare afraid of loud noises, of being alone and of men, particularly men in uniform.\nParents also described how their children had difficulty sleeping and experienced\nnightmares. After an attack with explosive weapons in a residential area of Kharkiv a\nmother described how the attack had impacted her daughter, saying “she is very\ntraumatized and will only sleep in the corridor; she also goes to the corridor every\ntime she hears sirens during the daytime and starts to shake”.\nV. Concluding observations"},{"id":"a-77-533-p0109","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"109","seq":110,"section":"5. Sexual and gender-based violence","text":"Based on its investigations of the events in Kyiv, Chernihiv, Kharkiv and Sumy\nin late February and March 2022, the Commission has found reasonable grounds to\nconclude that an array of war crimes and violations of human rights and international\nhumanitarian law have been committed in Ukraine since 24 February 2022. As\ndetailed in the present report, Russian armed forces are responsible for the vast\nmajority of the violations identified by the Commission. The Commission has also\nfound instances in which Ukrainian armed forces have violated international\nhumanitarian law, including two situations in which they committed war crimes.\nWhile few in number, such cases will continue to be the object of the Commission’s\nattention."},{"id":"a-77-533-p0110","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"110","seq":111,"section":"5. Sexual and gender-based violence","text":"The impact of these violations on the people in Ukraine is immense. The loss of\nlives is in the thousands. The destruction of infrastructure, which includes the\ndestruction not only of physical objects, but also of what families have built or\ninvested to ensure their comfort and safety in the future, has been immense. Some\npeople whose homes have been damaged by explosive weapons have no choice but\nto remain in their homes with makeshift walls and windows, as winter approac hes.\nThey have to cope with the consequences of the loss of friends, relatives and\nimmediate family members and large-scale destruction."},{"id":"a-77-533-p0111","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"111","seq":112,"section":"5. Sexual and gender-based violence","text":"Family members who lost loved ones have expressed a strong need for justice\nto be done. A stepfather whose son was killed in Bucha told the Commission: “I used\nto want to find those who were responsible and kill them, but now I want the guilty\nto be put on trial and I want the truth to come out”."},{"id":"a-77-533-p0112","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"112","seq":113,"section":"5. Sexual and gender-based violence","text":"In this connection, more than ever, sound coordination of the multi ple national\nand international accountability initiatives in Ukraine is key to guaranteeing strict\nadherence to the relevant standards for the collection of evidence and for its use in\njudicial processes that satisfy due process guarantees. The Commission expresses its\nhope that such coordination will become more established."},{"id":"a-77-533-p0113","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"113","seq":114,"section":"VI. Next steps","text":"Having paid particular attention to violations committed in the four areas\nspecified in Human Rights Council resolution S-34/1, the Commission will gradually\ndevote more of its resources to the broader temporal, geographical and thematic\nframework set forth in Council resolution 49/1."},{"id":"a-77-533-p0114","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"114","seq":115,"section":"VI. Next steps","text":"The issues of interest will include possible violations in filtration camps, alleged\nforced transfers of people and conditions under which expedited adoptions of children\nare allegedly taking place, as well as changes in local administration and so -called\nreferendums, the consequences of which are becoming clearer given recent events."},{"id":"a-77-533-p0115","rec_id":"recuoVcramRP6ZmSB","symbol":"A/77/533","n":"115","seq":116,"section":"VI. Next steps","text":"The Commission will continue to act in a victim-centred way, which it interprets\nnot only in terms of doing no harm to victims, but also, and more positively, in terms\nof making recommendations concerning forms of accountability that supplement\ncriminal accountability, including measures of recognition, reparation, rehabilitation,\nreconstruction and, importantly, guarantees of non-repetition."},{"id":"a-hrc-52-crp-4-u0000","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":null,"seq":0,"section":null,"text":"Summary\nIn resolution 49/1, dated 4 March 2022, the Human Rights Council condemned the\nhuman rights violations and abuses and violations of international humanitarian law resulting\nfrom the aggression against Ukraine by the Russian Federation and decided to establish an\nIndependent International Commission of Inquiry to investigate all alleged violations and\nabuses of human rights and violations of international humanitarian law, and related crimes.\nThe Commission has determined that the use of armed force by the Russian Federation\nagainst Ukraine was an act of aggression as defined in General Assembly resolution 3314\n(XXIX).\nThe present report is a detailed account of all the evidence gathered and analysed by\nthe Commission since its creation, which was presented in its March 2023 report to the\nHuman Rights Council (A/HRC/52/62), and it includes a description of a select number of\ncases underpinning those findings. Furthermore, the present report also contains more\nextensive discussions of some general topics, including accountability.\nAs at the end of the first year of its mandate, the Commission of Inquiry on Ukraine\nhas concluded that a wide range of grave human rights and humanitarian law violations and\ncorresponding crimes, many amounting to war crimes, and some of them possibly to crimes\nagainst humanity, have been committed in many regions of Ukraine and in the Russian\nFederation.\nBased on a substantial body of evidence, the Commission has found that in areas\nwhich came under their control, Russian authorities committed wilful killings, attacks on\ncivilians, unlawful confinement, torture, rape, and unlawful transfers and deportations of\nprotected persons, which are war crimes.\nThe Commission has concluded that torture used by Russian authorities has been\nwidespread and systematic and may amount to crimes against humanity, if confirmed by\nfurther investigations. They have targeted specific groups of people and used similar methods\nof torture across various detention facilities they held in Ukraine and in the Russian\nFederation. Torture was frequently perpetrated in combination with interrogation sessions,\nto extract information or confessions, or to intimidate or punish the victims. The Commission\nhas examined closely a number of detention facilities where torture was routinely\nperpetrated.\nIt has also found a pattern of summary executions in towns and villages that were\nclose to the frontlines, where Russian armed forces came into frequent contact with local\nresidents. It documented cases of rape and sexual violence committed by Russian authorities\nduring forced visits to victims’ houses and during detention.","unnumbered":true},{"id":"a-hrc-52-crp-4-u0001","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":null,"seq":1,"section":null,"text":"In two instances investigated, Ukrainian authorities shot, wounded, and ill-treated\ndetainees.\nAttacks carried out with explosive weapons in populated areas caused large-scale\ndevastation and suffering. Many such attacks were carried out by Russian armed forces with\nan apparent disregard for possible harm to civilians and impacted civilian objects or areas\nwith visible large civilian concentrations. The Commission has concluded that Russian\narmed forces committed indiscriminate and disproportionate attacks, in violation of\ninternational humanitarian law, some of which amounted to the war crime of excessive\nincidental death, injury, or damage.\nThe large-scale attacks launched by Russian armed forces against Ukrainian critical\ninfrastructure starting 10 October 2022, including energy-related installations caused\nelectricity outages, sometimes affecting millions of people across the country. The\nCommission has found that the attacks were widespread and systematic and may amount to\ncrimes against humanity, if confirmed by further investigations.\nIn a small number of indiscriminate attacks committed with explosive weapons in\nIzium city, Ukrainian armed forces were likely responsible, in violation of international\nhumanitarian law.\nThe Commission has assessed that the holding of the so-called referendums regarding\nthe incorporation of occupied territories in the Donetsk, Kherson, Luhansk, and Zaporizhzhia\nregions into the Russian Federation was in violation of international humanitarian law. It\nreceived reports regarding a climate of fear and coercion prevailing at that time. The\nCommission also documented instances of coercion, threats, unlawful confinement and\nforcible transfers of local officials and public service employees, including school personnel,\nto force them to cooperate.\nThe Commission’s investigations have shown that Ukrainian children have been\ntransferred or deported to Russian-occupied areas or to the Russian Federation. In some of\nthe cases the Commission has investigated, this amounted to war crimes. Where this led to\nprolonged family separations, Russian authorities in addition violated their obligation under\ninternational humanitarian law to facilitate the reunion of families dispersed as a result of the\narmed conflict. The Commission also examined measures which Russian authorities took\nwith the apparent aim of facilitating long-term placement of Ukrainian children in the\nRussian Federation and underscores, in this connection, the child’s right to preserve his or\nher identity and family relations.\nFinally, in virtue of its mandate, the Commission has looked at possible root causes,\nas well as at patterns of past violations and crimes committed in Ukraine, which are related\nto the current context. It has provided an account of the devastating impact of the armed\nconflict on civilian lives and on the enjoyment of a wide range of human rights.\nThe Commission calls for an immediate end to all grave violations and crimes. It\nrecommends investigation and prosecution of all allegations of international crimes,\nviolations of human rights and international humanitarian law and describes various ways to\nachieve criminal accountability. The Commission is of the view that accountability includes\nboth judicial and non-judicial measures, such as recognition, reparation, rehabilitation and\nreconstruction, which take into account the needs of the victims and survivors.\nComprehensive accountability is paramount.\nDisclaimer: In conformity with its report 23 March 2023 to the Human Rights Council\n(A/HRC/52/62), the Commission has considered in this conference room paper events which\noccurred until 31 January 2023. In a few situations, and where relevant for its analysis, it has\nincluded some important developments and updates which have occurred after this date.","unnumbered":true},{"id":"a-hrc-52-crp-4-p0001","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"1","seq":2,"section":"I. Introduction, mandate and reporting","text":"In its resolution 49/11 adopted on 4 March 2022, the Human Rights Council expressed\ngrave concern at the ongoing human rights crisis in Ukraine, the increasing reports of civilian\ncasualties, and the damage to and destruction of residential areas and civilian infrastructure.\nIt decided to urgently establish an Independent International Commission of Inquiry to\ninvestigate all alleged violations and abuses of human rights and violations of international\nhumanitarian law, and related crimes in the context of the Russian Federation’s aggression\nagainst Ukraine."},{"id":"a-hrc-52-crp-4-p0002","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"2","seq":3,"section":"I. Introduction, mandate and reporting","text":"The Council mandated the Commission to ascertain the facts, circumstances, and root\ncauses of such violations, and, where possible, to identify those responsible, as well as to\nmake recommendations, in particular on accountability measures. It called upon the\nCommission to collect, preserve, and analyse evidence, including through field engagement\nand in cooperation with judicial and other entities."},{"id":"a-hrc-52-crp-4-p0003","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"3","seq":4,"section":"I. Introduction, mandate and reporting","text":"On 30 March 2022, the President of the Human Rights Council announced the\nappointment of Erik Møse (Norway), Jasminka Džumhur (Bosnia and Herzegovina)2 and\nPablo de Greiff (Colombia) as the three independent members of the Commission, with Mr.\nMøse serving as chair."},{"id":"a-hrc-52-crp-4-p0004","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"4","seq":5,"section":"I. Introduction, mandate and reporting","text":"In resolution S-34/13 on the deteriorating human rights situation in Ukraine, adopted\non 12 May 2022, the Council further requested the Commission to conduct an inquiry to\naddress the events in Chernihiv, Kharkiv, Kyiv, and Sumy regions in late February and in\nMarch 2022, including their gender dimension, with a view to holding those responsible to\naccount."},{"id":"a-hrc-52-crp-4-p0005","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"5","seq":6,"section":"I. Introduction, mandate and reporting","text":"As requested by the Human Rights Council, on 23 September 2022, the Commission\npresented an oral update4 and on 18 October 2022, submitted a report5 to the General\nAssembly covering events that took place in February and March 2022 in the four regions\nmentioned above. The present detailed report and the report6 submitted to the Human Rights\nCouncil during its fifty-second session, in March 2023, are based on all the evidence gathered\nand analysed by the Commission since its creation until 31 January 2023."},{"id":"a-hrc-52-crp-4-p0006","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"6","seq":7,"section":"I. Introduction, mandate and reporting","text":"To conduct its investigations, the Commission has travelled eight times to Ukraine\nand visited 56 cities, towns, and settlements. It also travelled to Estonia and Georgia to meet\nwith people who fled from areas affected by the armed conflict. The Commission conducted\n610 interviews with 595 persons (348 women and 247 men) in person and remotely;\ninspected sites of destruction, graves, places of detention and torture, as well as weapon\nremnants, and consulted a large number of documents and other sources. It met with\nvictims and witnesses, Government authorities, international organizations, civil society\norganizations, and other relevant stakeholders, and received and reviewed written\nsubmissions, including 38 letters from teenage children."},{"id":"a-hrc-52-crp-4-p0007","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"7","seq":8,"section":"I. Introduction, mandate and reporting","text":"In its work, the Commission is guided by the principles of independence, impartiality,\nobjectivity, and integrity. It adopts a victim-centred approach and a strict respect of the “do\nno harm” principle, in particular regarding guarantees of confidentiality of the information\nreceived and the safety and the protection of victims and witnesses, and other interlocutors."},{"id":"a-hrc-52-crp-4-p0008","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"8","seq":9,"section":"I. Introduction, mandate and reporting","text":"The Commission expresses its gratitude to all those who shared their experiences,\ntestimonies and other valuable information. It appreciates the assistance provided by\nGovernments, United Nations agencies, funds and programmes, other international\norganizations, non-governmental entities, and experts, and is grateful for the answers to its\ncall for submissions.7"},{"id":"a-hrc-52-crp-4-p0009","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"9","seq":10,"section":"A. Scope","text":"The Commission has considered all violations and abuses of human rights and\nviolations of international humanitarian law and related crimes committed in Ukraine within\nits internationally recognized borders, as well as outside of Ukraine’s territory, as long as\nsuch events occurred in the context of the aggression against Ukraine by the Russian\nFederation."},{"id":"a-hrc-52-crp-4-p0010","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"10","seq":11,"section":"A. Scope","text":"As outlined above, the Commission prioritized events in the Chernihiv, Kharkiv,\nKyiv, and Sumy regions in late February and March 2022, in conformity with resolution S-\n34/1. Apart from specific references in this resolution, the Commission’s general mandate\ndoes not contain geographic or temporal boundaries for its investigations. It has, to the extent\npossible (see paras. 32-34), focused on violations committed in all territories affected by the\narmed conflict. It has taken into account events and patterns of violations which also go back\nin time, provided that they contribute to identifying root causes of violations committed in\nthe present context."},{"id":"a-hrc-52-crp-4-p0011","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"11","seq":12,"section":"A. Scope","text":"As requested by resolution 49/1, the Commission has formulated recommendations\non accountability issues. In doing so, it has, in accordance with established United Nations\npractice, based its efforts on a conception of accountability which includes criminal justice\nand other forms of accountability, such as truth-telling, reparations, and guarantees of non-\nrecurrence."},{"id":"a-hrc-52-crp-4-p0012","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"12","seq":13,"section":"B. Methodology","text":"The Commission has examined a large number of alleged violations of human rights\nand violations of international humanitarian law, and related crimes falling under its mandate.\nIt has investigated incidents regardless of the identity or nationality, citizenship, or place of\norigin of the alleged responsible individual or entity. The Commission has aimed at\nidentifying the party, and where possible, the individuals responsible for the alleged\nviolations and related crimes which it documents, and their units."},{"id":"a-hrc-52-crp-4-p0013","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"13","seq":14,"section":"B. Methodology","text":"Given the vast number of allegations, the limited resources and time available, the\nchallenges to access certain victims, witnesses, and areas affected by the hostilities, the\nparticular challenges related to the investigations of certain issues, as well as logistical\nconstraints, the Commission could not possibly examine all reported incidents. It has focused\non incidents based on their gravity, their significance in demonstrating patterns of alleged\nviolations, the access to victims, witnesses and supporting documentation, and the\ngeographic location of the incidents."},{"id":"a-hrc-52-crp-4-p0014","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"14","seq":15,"section":"B. Methodology","text":"In its investigations, the Commission has paid particular attention to the gender\ndimension of crimes and violations and has found that some of them were committed against\nmen, women, boys, and girls because of their gender roles. Such violence refers to any type\nof harm that is perpetrated against an individual or a group of people based on gender\nconsiderations.8 In addition, the Commission has given particular consideration to the impact\nof violations on children, older persons, and individuals affected by intersectional\ninequalities."},{"id":"a-hrc-52-crp-4-p0015","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"15","seq":16,"section":"B. Methodology","text":"The examples and incidents outlined in this report are therefore only a small sample\nof the allegations which the Commission has examined. No conclusions or inferences can be\nmade where this report does not cover certain thematic or geographic areas. Nevertheless,\nthe Commission considers that the report illustrates some of the main patterns of violations\nobserved in the context of the armed conflict in Ukraine."},{"id":"a-hrc-52-crp-4-p0016","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"16","seq":17,"section":"C. Standard of proof and fact-finding methods","text":"The Commission has followed the best practices and methodologies for human rights\nfact-finding.9 Consistent with the standard of proof followed by most international\ncommissions of inquiry, the Commission has included findings in its report when, based on\na body of verified information, an objective and ordinary prudent observer would have\n“reasonable grounds to conclude” that the facts took place as described. It has drawn legal\nconclusions when there are reasonable grounds to conclude that the facts meet all the\nelements of a violation or abuse, and, where possible, that an individual or entity is\nresponsible for the violation or abuse. The established methodology for this standard of proof\nrequires at least one credible direct source of information, independently corroborated by at\nleast one or more additional credible sources of information."},{"id":"a-hrc-52-crp-4-p0017","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"17","seq":18,"section":"C. Standard of proof and fact-finding methods","text":"Findings of the Commission rely primarily on first-hand information, including\ninformation collected through interviews with victims and witnesses of alleged violations\nand abuses. It has prioritized field-visits to examine sites of violations and abuses and\nphysical evidence and in-person interviews. The Commission has also relied on remote\ninterviews, photographs, video-recordings, statements by parties to the conflict, satellite\nimagery, documents, reports, statistics, and other similar information from reliable sources.\nIt has compared the information collected with information generated by States, United\nNations agencies, funds and programmes, civil society organizations, media, and other\nrelevant actors. On 29 June 2022, the Commission issued a call for submissions of\ninformation and documentation relevant to its mandate."},{"id":"a-hrc-52-crp-4-p0018","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"18","seq":19,"section":"C. Standard of proof and fact-finding methods","text":"All the incidents and patterns included in the Commission’s reports are those for\nwhich it considered that there are reasonable grounds to conclude that they occurred as\ndescribed. Additionally, the Commission has indicated in the text when there are allegations\nor credible reports relevant to understanding the patterns of violations and related crimes\nunder its purview, but which it has so far not been able to verify due to a series of constraints."},{"id":"a-hrc-52-crp-4-p0019","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"19","seq":20,"section":"D. Victim-centred approach","text":"At all times during its fact-finding, the Commission has aimed at ensuring respect for\nthe safety, security, and well-being of the victims. In-person interviews were conducted in\nsafe and private settings. Remote interviews were carried out through secure channels of\ncommunication. Reports contain information provided by interlocutors only when they\ngranted informed consent and where disclosure would not lead to any identification or result\nin harm. All the information provided by victims and witnesses, as well as other sensitive\ninterlocutors, has been stored securely and in accordance with the United Nations policies on\ninformation sensitivity, classification, and handling."},{"id":"a-hrc-52-crp-4-p0020","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"20","seq":21,"section":"D. Victim-centred approach","text":"To avoid retraumatizing victims and witnesses, a strict respect for their well-being,\nprivacy and security is key. In this regard, the Commission is of the view that entities engaged\nin the documentation of the violations and crimes should coordinate their efforts to avoid\nunnecessarily reinterviewing victims and ensure that an appropriate referral to support\nservices is available."},{"id":"a-hrc-52-crp-4-p0021","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"21","seq":22,"section":"D. Victim-centred approach","text":"In its work and during the formulation of its recommendations, the Commission has\npaid particular attention to factors relevant to the situation of victims and witnesses. It has\nconsidered the needs of the victims, the importance of accountability, as well as of measures\nof recognition, reparation, rehabilitation, reconstruction, and guarantees of non-repetition."},{"id":"a-hrc-52-crp-4-p0022","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"22","seq":23,"section":"E. Cooperation with Governments","text":"Since the outset, the Commission has sought cooperation and dialogue with the\nGovernments of Ukraine and the Russian Federation. It has shared advance copies of its\nwritten reports with both States and invited them to provide comments."},{"id":"a-hrc-52-crp-4-p0023","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"23","seq":24,"section":"E. Cooperation with Governments","text":"The Commission is grateful for the access during its travels to Ukraine, where it met\nwith members of the Government and local authorities, and for the written responses to its\nqueries."},{"id":"a-hrc-52-crp-4-p0024","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"24","seq":25,"section":"E. Cooperation with Governments","text":"It regrets that its attempts to establish meaningful communication with the Russian\nFederation have been unsuccessful, as its notes verbales and letters have remained\nunanswered. A Russian governmental institution has referred material to the Commission,\nwhich it has examined."},{"id":"a-hrc-52-crp-4-p0025","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"25","seq":26,"section":"E. Cooperation with Governments","text":"The Commission has also received collaboration from other Governments which had\ninformation relevant to its mandate or that hosted persons from Ukraine. This included visits\nto Estonia and Georgia."},{"id":"a-hrc-52-crp-4-p0026","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"26","seq":27,"section":"F. Cooperation and coordination with entities and accountability initiatives","text":"Sound coordination between entities engaged in the documentation of violations,\nabuses, and related crimes in Ukraine is key to ensure efficiency, avoid the duplication of\nefforts, and the retraumatizing of victims and witnesses (see para. 20). The Commission has\ntherefore engaged with relevant international and national entities. To ensure its\nindependence and impartiality, it follows well-established processes for such cooperation and\nconducts its own investigations independently and separately from any United Nations or\nother entities."},{"id":"a-hrc-52-crp-4-p0027","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"27","seq":28,"section":"F. Cooperation and coordination with entities and accountability initiatives","text":"Consistent with its mandate, the Commission has built on the work of OHCHR and\nof the United Nations Human Rights Monitoring Mission in Ukraine. It has also held regular\nmeetings with the Office of the Prosecutor of the International Criminal Court and has\nengaged with the Office for Democratic Institutions and Human Rights of the Organization\nfor Security and Cooperation in Europe, the European Union Agency for Criminal Justice\nCooperation and the Atrocity Crimes Advisory Group."},{"id":"a-hrc-52-crp-4-p0028","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"28","seq":29,"section":"F. Cooperation and coordination with entities and accountability initiatives","text":"The Commission intends its work to contribute to current and future accountability\nefforts regarding crimes committed in Ukraine. Where relevant, information and\ndocumentation it has collected will be shared with competent investigative, prosecutorial,\nand judicial authorities to facilitate and expedite criminal proceedings. The sharing will occur\nunder conditions of fairness, due process, non-applicability of the death penalty, and\ncompliance with other relevant human rights standards. The consent of witnesses and other\ninterlocutors for external uses of the information is fundamental in handling such requests."},{"id":"a-hrc-52-crp-4-p0029","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"29","seq":30,"section":"G. Outreach and communication","text":"Throughout its mandate, the Commission has considered it important to engage with\nall relevant stakeholders to enhance awareness regarding its mandate and increase the\nvisibility of its work. It has participated in relevant high-level events, such as the United\nNations Security Council Arria-formula meeting on “Ensuring accountability for atrocities\ncommitted in Ukraine” on 26 April 2022, the Meeting of the Organization for Security and\nCooperation in Europe Human Dimension Committee on 5 July 2022, and the side event on\n“Examining options of accountability for Ukraine” held by the Public International Law &\nPolicy Group on the margins of the 51 st session of the Human Rights Council on 27\nSeptember 2022. In connection with the submission of its report to the Human Rights Council\nin March 2023, the Commission also participated in the side event “Ukraine: Accountability\nfor war crimes and serious human rights violations”, on 21 March 2023. It has established\nongoing communication with the diplomatic community, civil society organizations,\ninitiatives, and academia."},{"id":"a-hrc-52-crp-4-p0030","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"30","seq":31,"section":"G. Outreach and communication","text":"The Commission has developed a media and communication strategy. It has held five\npress conferences in Kyiv, Geneva, and Vienna, handled more than 150 queries from\njournalists, researchers, and individuals, and conducted 55 media interviews that resulted in\nmore than 480 press clippings. The webpage of the Commission is updated with background\ninformation, as well as reports, statements, and activities."},{"id":"a-hrc-52-crp-4-p0031","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"31","seq":32,"section":"H. Secretariat","text":"The Commission has received the support of a secretariat of 24 professional staff,\nbased in Vienna. Most of the staff was in place in July 2022. The Secretariat has maintained\na repository governed by United Nations rules on information sensitivity, classification and\nhandling to allow safe and secure storage, as well as efficient processing and analysis of the\ndocumentation and information collected by the Commission."},{"id":"a-hrc-52-crp-4-p0032","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"32","seq":33,"section":"I. Challenges","text":"During its mandate, the Commission has faced a series of challenges in its ability to\nconduct investigations in some of the areas affected by the armed conflict. It has not obtained\naccess to the Russian Federation and to areas under the control of Russian authorities.10 At\nthe time of writing the present report, written requests sent to this effect remained unanswered\n(see para. 23)."},{"id":"a-hrc-52-crp-4-p0033","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"33","seq":34,"section":"I. Challenges","text":"Other difficulties were due to dire security conditions, which impeded the\nCommission’s travel to certain areas. Some areas could only be visited during daytime and\ninvolved long-distance travel. The Commission also faced considerable logistical difficulties,\nin particular with regards to the availability of vehicles and drivers during its visits to\nUkraine."},{"id":"a-hrc-52-crp-4-p0034","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"34","seq":35,"section":"I. Challenges","text":"Specific aspects of the investigations were also challenging. Owing to a fluid security\nsituation, it was often not possible to examine sites of events immediately after their\noccurrence. Later visits posed challenges related to the availability, preservation,\nindependence, and accuracy of evidence. Forensic reports were not always comprehensive.\nTrauma, social stigma, and risks of marginalisation of certain categories of victims, in\nparticular in cases of sexual violence, are a source of additional constraints."},{"id":"a-hrc-52-crp-4-p0035","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"35","seq":36,"section":"III. Legal framework","text":"Pursuant to resolution 49/1, international human rights law, international\nhumanitarian law, and international criminal law constitute the law applicable to the mandate\nof the Commission."},{"id":"a-hrc-52-crp-4-p0036","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"36","seq":37,"section":"III. Legal framework","text":"As for international human rights law, both Ukraine and the Russian Federation are\nparty to the same seven United Nations core human rights instruments. 11 Ukraine is\nadditionally party to another core human rights treaty, namely the International Convention\nfor the Protection of All Persons from Enforced Disappearance. Both States have ratified the\nOptional Protocol to the Convention on the Rights of the Child on the involvement of children\nin armed conflict."},{"id":"a-hrc-52-crp-4-p0037","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"37","seq":38,"section":"III. Legal framework","text":"Regarding international humanitarian law, both Ukraine and the Russian Federation\nare party to, among others, the four Geneva Conventions of 1949.12 Ukraine acceded to\nAdditional Protocols I, II and III of the Geneva Conventions, while the Russian Federation\nacceded to Additional Protocols I, II and signed Additional Protocol III. Along with treaty\nlaw, the Commission is also applying customary international humanitarian law. Relevant\nprovisions and rules of international humanitarian law are also binding upon non-State actors\nthat may be involved in the conflict."},{"id":"a-hrc-52-crp-4-p0038","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"38","seq":39,"section":"III. Legal framework","text":"The situation in Ukraine is an international armed conflict, pursuant to common article\n2 of the four Geneva Conventions, due to armed hostilities existing between two States,\nthrough their respective armed forces or other actors acting on their behalf."},{"id":"a-hrc-52-crp-4-p0039","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"39","seq":40,"section":"III. Legal framework","text":"In terms of international criminal law, the Commission will apply relevant\ninternational treaties and customary international law. Neither Ukraine nor the Russian\nFederation are State Parties to the Rome Statute of the International Criminal Court (ICC).\nHowever, the ICC has jurisdiction in Ukraine, pursuant to two declarations lodged by\nUkraine and referrals by ICC State Parties. 13 The Rome Statute and its Elements of Crimes\nprovide detailed elements for some of the alleged crimes. The Statute’s ratification by a\nmajority of the Member States of the United Nations reflects, on the whole, the definition of\nthese crimes under customary international law.14 Where the ICC is found to lack jurisdiction,\nthe Commission will apply the elements of crimes within the Rome Statute so long as they\nreflect customary international law."},{"id":"a-hrc-52-crp-4-p0040","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"40","seq":41,"section":"A. Root causes of violations, abuses, and crimes","text":"Human Rights Council’s resolution 49/1, in paragraph 11(a), has requested the\nCommission to examine root causes of violations and abuses of human rights and violations\nof international humanitarian law which are under its investigations. The Commission has\nreviewed possible factors that may have enabled or facilitated the present developments, and\nwhich are part of the context in which they arose."},{"id":"a-hrc-52-crp-4-p0041","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"41","seq":42,"section":"1. Narratives to justify interventions","text":"To justify the launch of an armed attack on Ukraine on 24 February 2022, President\nPutin referred, among other issues, to historical reasons and protection imperatives of Russian\ncitizens and speakers abroad. On 21 February 2022, in a declaration explaining the motives\nbehind the Russian Federation’s actions, President Putin stated: “I would like to emphasise\nagain that Ukraine is not just a neighbouring country for us. It is an inalienable part of our\nown history, culture and spiritual space.” He added: “Since time immemorial, the people\nliving in the south-west of what has historically been Russian land have called themselves\nRussians and Orthodox Christians.”15 In his 24 February 2022 statement regarding the launch\nof a “special military operation” in Ukraine, President Putin noted that “[i]ts purpose is to\nprotect people who have been subjected to abuse and genocide by the Kiev regime for eight\nyears.”16"},{"id":"a-hrc-52-crp-4-p0042","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"42","seq":43,"section":"1. Narratives to justify interventions","text":"The narrative based on historical politics and protection imperatives has been crafted\nand strengthened by President Putin over two decades to attempt to validate, both\ndomestically and in his foreign policy, military interventions, not only in Ukraine, but also\nin Chechnya and in Georgia.17 It is based on an instrumentalization of the view that the\nRussian Federation has a perceived obligation to protect Russians and Russian speakers\nabroad."},{"id":"a-hrc-52-crp-4-p0043","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"43","seq":44,"section":"1. Narratives to justify interventions","text":"This was, for example, the case during the Russian Federation’s annexation of\nAutonomous Republic of Crimea (Crimea) in March 2014. President Putin then declared\n“Crimea has always been an inseparable part of Russia” and underscored that “the residents\nof Crimea and Sevastopol turned to Russia for help in defending their rights and lives”. 18\nShortly after the annexation, he reiterated his stance on interventions on behalf of Russian\nindividuals: “I would like to make it clear to all: our country will continue to actively defend\nthe rights of Russians, our compatriots abroad, using the entire range of available means –\nfrom political and economic to operations under international humanitarian law and the right\nof self-defence.”19 In April 2014, in a dedicated television programme called “Direct Line\nwith Vladimir Putin”, President Putin made reference to a controversial account of history,\npointing to “the legitimate rights and interests of ethnic Russians and Russian-speakers in the\nsoutheast of Ukraine” and stressed “I would like to remind you that what was called\nNovorossiya (New Russia) back in the tsarist days – Kharkov, Lugansk, Donetsk, Kherson,\nNikolayev and Odessa – were not part of Ukraine back then. These territories were given\nto Ukraine in the 1920s by the Soviet government. ”20"},{"id":"a-hrc-52-crp-4-p0044","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"44","seq":45,"section":"2. Centralisation of powers in the Russian Federation and erosion of the civic space","text":"In the Russian Federation, the concentration of numerous state prerogatives in the\nhands of the presidency has eroded a possible checks and balances system and has insulated\nthe presidency from accountability.21 Political dissent and freedom of speech have often been\nsystematically and brutally quashed; members of the opposition and protestors have been\narrested.22 The government runs and controls media and television channels, and thereby\nlargely shapes the public understanding of domestic and world events. 23 These factors have\nbeen detrimental for independent civil society development inside the country and have\nresulted in a shrinking civic space.24"},{"id":"a-hrc-52-crp-4-p0045","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"45","seq":46,"section":"2. Centralisation of powers in the Russian Federation and erosion of the civic space","text":"The control of the political sphere by the executive has supressed genuine\ndissemination of information, understanding, criticism, and domestic opposition to the armed\nconflicts waged by the Russian Federation – and presently to the conflict in Ukraine. Since\nthe outset of the February 2022 armed conflict in Ukraine, further restrictions have been\nenacted to curb protests and other manifestations of the civil society, thereby limiting rights\nof association, expression, freedom of the press, and even access to justice and to education.\nThousands of cases of harassment and persecution of journalists have been reported, and\nhundreds of Russian journalists and activists have been detained for reporting on the\narmed conflict in Ukraine or protesting against the conscription. 25"},{"id":"a-hrc-52-crp-4-p0046","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"46","seq":47,"section":"3. A cycle of military interventions","text":"The 24 February 2022 armed attack on Ukraine has been launched against a\nbackground of past military interventions of the Russian Federation in Chechnya, Georgia,\nSyria, and earlier in Ukraine (starting in 2014), with disregard for international law and\ninternational condemnations. Grave violations of international humanitarian law and\ninternational human rights law committed during these armed conflicts have been widely\ndocumented. Accountability for these violations and crimes has been largely lacking, which\nhas paved the way for further military interventions and atrocities."},{"id":"a-hrc-52-crp-4-p0047","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"47","seq":48,"section":"3. A cycle of military interventions","text":"Relating to the 1999 armed conflict in Chechnya, the then United Nations\nCommission of Human Rights expressed its grave concern, in particular at reports indicating\n“disproportionate and indiscriminate use of Russian military force, including attacks against\ncivilians”, and underlined the “need to respect the principle of proportionality and to observe\ninternational human rights and humanitarian law in situations of conflict and in activities\nundertaken against terrorism”.26 With regards to the 2008 armed conflict in Georgia, the\nEuropean Court for Human Rights concluded that grave human rights violations had been\ncommitted in areas that fell under the jurisdiction of the Russian Federation. 27 States and\nregional organizations condemned the Russian Federation’s military intervention in Syria, in\nsupport of the Syrian Government, and notably the aerial bombardments in which scores of\ncivilians were killed.28 The Independent International Commission of Inquiry on the Syrian\nArab Republic found that the Russian Federation’s aircrafts participated in indiscriminate\nattacks in civilian areas.29"},{"id":"a-hrc-52-crp-4-p0048","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"48","seq":49,"section":"4. Russian armed forces and a culture of impunity and violence","text":"As mentioned above, Russian armed forces and associated groups operate against a\nlegacy of gross violations of human rights and related crimes, which were widespread 30,\nreproduced in all armed conflicts, tolerated – and at times even rewarded - by the hierarchy.31\nIn its resolution relating to the military intervention in Chechnya, the Commission on Human\nRights requested the Russian Federation “to disseminate, and ensure that the military at all\nlevels has a knowledge of, basic principles of human rights and international humanitarian\nlaw”.32 In 2022, the Human Rights Committee expressed concern about the “lack of\ninvestigation of alleged violations of the Covenant committed during the armed conflicts in\nwhich the State party has been involved” referring to past situations in Georgia and Ukraine.33\nSimilarly, in 2015, the Committee had also expressed concern regarding the “limited progress\nin investigating serious past and ongoing human rights violations” referring to situations in\nChechnya and Georgia. 34 In its 2021 ruling on a case pitting Georgia versus the Russian\nFederation, the European Court for Human Rights has concluded that “the investigations\ncarried out by the Russian authorities were neither prompt nor effective nor independent”. 35\nRegarding crimes committed in Georgia, the Prosecutor of the ICC had determined in 2015\nthat “no concrete and progressive steps have been taken in Russia to ascertain the criminal\nresponsibility of those involved in the alleged crimes” related to particular potential cases. 36"},{"id":"a-hrc-52-crp-4-p0049","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"49","seq":50,"section":"4. Russian armed forces and a culture of impunity and violence","text":"In the absence of checks and balances at state level, these are also lacking among\nRussian military ranks. Many of the practices, which are legacies of the Soviet army, such as\nthe perception of human losses as inevitable costs of the war and the attitude towards\npopulations in occupied territories, have generally not been condemned within the armed\nforces.37 Violence is also a reflection of the inner functioning of the army, where senior\ncommanders routinely neglect or abuse junior ranks. 38 Further challenges are posed by the\ndifferential treatment and training of groups from different nationalities or ethnicities,39 the\nhurried mobilisation of large numbers of ill-trained and ill-prepared troops, and the\noutsourcing of the war to additional groups and units, such as the military and security\ncontractors of the Wagner Group, with its own history of crimes and violations, and affiliated\narmed groups of the former self-proclaimed ‘republics’ in the Donetsk and Luhansk\nregions.40 These underlying factors are to be seen in conjunction with the propagation of a\nnarrative regarding the presence and the role of neo-Nazis in various facets of Ukrainian\nsociety.41 Years of dehumanizing propaganda revolving around “cleansing Ukraine from\nNazi elements” taught to Russian soldiers, have further contributed to aggressive behaviour\nand violence.42"},{"id":"a-hrc-52-crp-4-p0050","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"50","seq":51,"section":"B. Brief overview of significant events and patterns of reported violations","text":"The present armed conflict in Ukraine unfolds against a legacy of significant past\nevents and reports of serious human rights violations and abuses, and violations of\ninternational humanitarian law. The Commission has reviewed such events and patterns of\ngrave violations documented by the United Nations and other entities since 2013, to garner a\nbetter understanding of the current developments."},{"id":"a-hrc-52-crp-4-p0051","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"51","seq":52,"section":"1. Maidan events and other protests","text":"From 21 November 2013 to 22 February 2014, large-scale protests took place on the\nIndependence Square (Maidan) square, in Kyiv; subsequently, riots and violent clashes\noccurred in other cities of Ukraine. Protests were initially triggered by the refusal of the then\nPresident of Ukraine Victor Yanukovych to sign a negotiated association agreement with the\nEuropean Union, as he had opted instead for a further rapprochement with the Russian\nFederation. This was perceived as a major setback by pro-Europe Ukrainians, who favoured\ncloser political and economic ties with the European Union.43 The protests augmented in\nintensity and turned violent following the adoption by the parliament of a series of laws that\nlimited freedom of peaceful assembly and expression, as well as the excessive use of force\nby security forces and the associated impunity.44 Protesters called for the resignation of Mr.\nYanukovych and his government, and for overall change.45"},{"id":"a-hrc-52-crp-4-p0052","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"52","seq":53,"section":"1. Maidan events and other protests","text":"In January and February 2014, at the height of the protests in Kyiv, violence and\nexcessive use of force by the police and other law enforcement agencies resulted in the death\nof 108 protestors and other individuals and 13 law enforcement officers. On 2 May 2014 in\nOdesa, it was reported that deliberate inaction in the face of the violence, ill-preparedness or\nnegligence on the part of various authorities contributed to the death of 48 people. There have\nbeen reports of additional deaths, a large number of injuries, torture, ill-treatment, and\nenforced disappearances in the context of these events.46"},{"id":"a-hrc-52-crp-4-p0053","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"53","seq":54,"section":"1. Maidan events and other protests","text":"National investigations found that Mr. Yanukovych and nine senior officials\n“organized terrorist acts and attacks against protestors”. 47 In the majority of cases, violence\nhad reportedly been instigated or perpetrated by law enforcement officials48 and the so-called\n“titushky”, who worked closely with law enforcement agencies. 49 In a preliminary\nexamination of the situation, the Office of the Prosecutor of the International Criminal Court\nstated that “the information available tends to indicate that … the excessive use of force …\nwas actively promoted or encouraged by the Ukrainian authorities” and that perpetrators\n“targeted individuals on the basis of their actual or perceived political affiliation (namely\ntheir opposition to the Yanukovych Government)”.50"},{"id":"a-hrc-52-crp-4-p0054","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"54","seq":55,"section":"1. Maidan events and other protests","text":"Reports indicate that progress in prosecution and trial efforts regarding the Maidan\nevents had been slow and limited. 51 One particular obstacle was the fleeing of many of the\nsuspects to the Russian Federation, or territories it has been occupying since 2014, where\nsome of them reportedly obtained Russian citizenship and became unreachable for the\nUkrainian justice authorities. Other challenges relate to the loss of essential evidence due to\nthe failure of law enforcement authorities to collect or preserve it immediately after the\nevents, the overall complexity of the cases, and the release of some of the alleged perpetrators\nfrom custody.52"},{"id":"a-hrc-52-crp-4-p0055","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"55","seq":56,"section":"2. Occupation of the Autonomous Republic of Crimea and the city of Sevastopol","text":"Starting 23 February 2014, after rejecting the ousting by the Ukrainian Parliament of\nthe then President Yanukovych in Kyiv, pro-Russian groups in Crimea53 blocked key\ninfrastructure, airports, military installations, and took control of official buildings and\nstrategic facilities, with the support of Russian armed forces. 54 In a meeting with heads of\nsecurity agencies during the night of 22 and 23 February 2014, President Putin stated that he\ntook the decision to “start working on the return of Crimea to the Russian Federation”.55 On\n16 March 2014, Russian authorities held a so-called referendum on the incorporation of\nCrimea and the city of Sevastopol into the Russian Federation and subsequently announced\nthat a large majority voted in favour. On 18 March 2014, the Russian Federation and the\n“Republic of Crimea” signed a “treaty” regarding the “accession” of Crimea and the city of\nSevastopol to the Russian Federation.56"},{"id":"a-hrc-52-crp-4-p0056","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"56","seq":57,"section":"2. Occupation of the Autonomous Republic of Crimea and the city of Sevastopol","text":"Following these events, an array of restrictions and violations and abuses of human\nrights and international humanitarian law have been reportedly committed by Russian\nauthorities in Crimea. The recognition of Russian citizenship for those who had documented\npermanent residence in Crimea resulted in regressive effects on the enjoyment of human\nrights for those residents who refused to or were unable to acquire this citizenship because\nthey did not fulfil the legal criteria, with reports of harassment and intimidation. 57 Russian\ncourts issued hundreds of deportation orders to Ukrainian citizens residing in Crimea without\nRussian Federation passports.58"},{"id":"a-hrc-52-crp-4-p0057","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"57","seq":58,"section":"2. Occupation of the Autonomous Republic of Crimea and the city of Sevastopol","text":"Occupation authorities reportedly imposed Russian laws, including criminal law\ndesigned to fight terrorism, extremism and separatism,59 in violation of international\nhumanitarian law. Conscriptions of thousands of male Crimean residents into the Russian\narmed forces, transfers of detainees from Crimea to remote areas in the Russian Federation, 60\nand large-scale expropriations without compensation had been documented.61 Russian\nbecame the predominant language of instruction, and restrictions in terms of the availability\nof Ukrainian language in schools in Crimea have been imposed. 62"},{"id":"a-hrc-52-crp-4-p0058","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"58","seq":59,"section":"2. Occupation of the Autonomous Republic of Crimea and the city of Sevastopol","text":"In numerous cases, Russian authorities in Crimea reportedly persecuted, arrested,\ntortured, ill-treated, and detained individuals and charged them with terrorism, extremism,\nespionage, affiliation with groups banned in the Russian Federation, sabotage or “anti-\nRussian” activities, or involvement in the Crimean self-defense.63 Courts penalized political\ndissent, which also appeared to be designed to serve as warnings to others. Victims of such\nviolations were principally pro-Ukrainian activists and journalists and individuals belonging\nto minority groups, in particular Crimean Tatars. There were reports of violations of the\nfreedom of expression and information, including harassment of media and blockage of\nUkrainian internet sites, and violations of freedom of religion and belief, such as intimidation\nand harassment of religious communities. 64"},{"id":"a-hrc-52-crp-4-p0059","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"59","seq":60,"section":"3. Situation in Donetsk and Luhansk regions","text":"In April 2014, pro-Russian armed groups started seizing and occupying public and\nadministrative buildings in parts of the Donetsk and Luhansk regions, in eastern Ukraine. On\n7 and 27 April 2014, respectively, these groups announced the establishment of the so-called\n“Donetsk People’s Republic” and “Luhansk People’s Republic”. This went along with a\nreported inflow of foreign fighters and heavy weaponry from the Russian Federation. 65\nStarting April 2014, the Government of Ukraine launched an anti-terrorist operation in the\naffected regions.66"},{"id":"a-hrc-52-crp-4-p0060","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"60","seq":61,"section":"3. Situation in Donetsk and Luhansk regions","text":"Consequent to these developments, large-scale violations and abuses of human rights\nand of international humanitarian law were documented in the eastern regions of Ukraine,\nboth in areas controlled by Russian authorities and in territories under Ukrainian Government\ncontrol. Many of those occurred in the context of armed hostilities. The majority of civilian\ncasualties were reportedly caused by the indiscriminate shelling of populated areas. Other\nviolations included killings of civilians who were not taking part in hostilities, enforced\ndisappearances, dozens of executions of individuals hors de combat, and thousands of cases\nof arbitrary deprivation of liberty coupled with inhuman conditions of detention, torture and\nill-treatment, sometimes leading to death.67"},{"id":"a-hrc-52-crp-4-p0061","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"61","seq":62,"section":"3. Situation in Donetsk and Luhansk regions","text":"Concerns regarding accountability for violations and crimes in the context of the\narmed conflict in the east of the country have been reported, both in relation to human rights\nviolations perpetrated by Government forces and human rights abuses perpetrated by armed\ngroups.68 According to reports, accountability was particularly lacking for cases of killings\nand alleged summary executions committed in the conflict zone in eastern Ukraine, and each\nparty to the armed conflict mainly focused on documenting violations committed by the other\nparty. This was compounded with difficulties related to the lack of evidence in specific cases\nand the identification of the alleged perpetrators. 69"},{"id":"a-hrc-52-crp-4-p0062","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"62","seq":63,"section":"3. Situation in Donetsk and Luhansk regions","text":"In the former so-called Donetsk and Luhansk People’s Republics, parallel law\nenforcement entities and structures have reportedly considered some cases and held ‘trials’\nin conflict-related cases. However, detailed information on this matter is not available. 70\nAmong concerns expressed regarding these trials were the inherent lack of independence and\nimpartiality of ‘tribunals’, the bias of the judges,71 the reliance on confessions obtained\nthrough torture and coercion, as well as a series of other violations of fair trial rights.72 Some\nof the investigations mainly focused on acts committed by armed groups which had been\ndisbanded or otherwise re-organized.73"},{"id":"a-hrc-52-crp-4-p0063","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"63","seq":64,"section":"3. Situation in Donetsk and Luhansk regions","text":"Ukrainian institutions have reportedly carried out some investigations and trials\nregarding crimes allegedly perpetrated by Ukrainian military forces and security services in\nconflict-related cases. However, progress has been reportedly slow. Challenges have\nincluded protracted investigations and trials, an insufficient number of judges, alleged\ninterference with the independence of judges, including pressuring and harassing judges\nhandling such cases, forced confessions, and the pronouncing of verdicts in absentia.74"},{"id":"a-hrc-52-crp-4-p0064","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"64","seq":65,"section":"3. Situation in Donetsk and Luhansk regions","text":"Civic space has been highly restricted in the areas controlled by Russian authorities\nin eastern Ukraine.75 This was coupled with misinformation and hate propaganda against\nUkrainian Government institutions.76 Reports documented media channels broadcasting in\nUkrainian being shut-off by the self-proclaimed authorities and attacks by armed groups on\nlocal media offices.77 Armed groups reportedly instilled a climate of fear, with abductions,\nattacks, persecutions, and unlawful detentions, targeting journalists, bloggers and other\nmedia personnel expressing pro-Ukrainian views, with an overall lack of accountability. 78\nIll-treatment and sexual harassment in detention were also recorded.79"},{"id":"a-hrc-52-crp-4-p0065","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"65","seq":66,"section":"4. Incidents in territory under Ukrainian Government control","text":"In this context, in other regions of Ukraine, some violations of the rights to freedom\nof opinion and freedom of expression, freedom of peaceful assembly and association,\nfreedom of religion or belief and the right to non-discrimination were also documented\nconcerning the Ukrainian authorities.80 Attacks against journalists, media professionals, civil\nsociety activists, or those representing alternative social or political opinion have become\nincreasingly visible, particularly in 2018 - 2019.81 Some journalists or media broadcasters\nwere attacked due to their alleged ‘separatist’ views, for criticising local authorities or law\nenforcement officials, or for being “pro-Russian”.82 In 2021, it was reported that several\ndecisions of the National Security and Defense Council of Ukraine led to the closure of some\nmedia outlets and television channels, which possibly amounted to undue restrictions on the\nright to freedom of expression.83 An increase in incidents targeting political parties belonging\nto the opposition was also documented.84"},{"id":"a-hrc-52-crp-4-p0066","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"66","seq":67,"section":"1. Military and security developments","text":"On 24 February 2022, Russian Federation President Vladimir Putin declared that he\nhad decided to conduct a “special military operation” in Ukraine to seek its “demilitarization\nand de-Nazification”. President Putin referred to the operation as an act of “self-defence”,\nwhich, he stated, is directed against “those who have taken Ukraine hostage and are trying to\nUkraine, 16 February – 31 July 2020, paras. 69 and 72; OHCHR, Report on the Human Rights\nSituation in Ukraine, 1 August 2020 – 31 January 2021, paras. 58-59; OHCHR, Report on the Human\nRights Situation in Ukraine, 1 August 2021 – 31 January 2022, para. 60.\nuse it against our country and its people”.85 On the same day, Russian armed forces crossed\nvarious border points into Ukraine, and launched attacks by land, air, and sea. During the\npreceding months, the Russian Federation had amassed tens of thousands of troops and heavy\nweaponry at Ukraine’s borders, including in Belarus. 86"},{"id":"a-hrc-52-crp-4-p0067","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"67","seq":68,"section":"1. Military and security developments","text":"Consequently, Ukrainian President Volodymyr Zelenskyy introduced martial law, in\nvirtue of which authorities can impose a number of restrictions, including curfews,\nexpropriations, verification measures, restrict the freedom of movement, prohibit rallies, and\nban activities of political parties.87 Among other measures, a travel ban for most men of\nfighting age88 and a general mobilisation have been announced. 89 The Ukrainian Parliament\nregularly extended the bills on martial law and general mobilisation."},{"id":"a-hrc-52-crp-4-p0068","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"68","seq":69,"section":"1. Military and security developments","text":"Since the outset and throughout the armed conflict, military strikes using explosive\nweapons with wide area effects have been carried out in major Ukrainian cities with\nsignificant populations, including in areas situated far from frontlines. They have caused\nscores of civilian deaths and casualties, and large-scale destruction.90 Humanitarian relief\ncould hardly reach affected areas during intense periods of fighting or occupation, while\ncivilians could not satisfy basic needs.91\na)    Offensive towards Kyiv, sieges and fighting in and around major cities"},{"id":"a-hrc-52-crp-4-p0069","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"69","seq":70,"section":"1. Military and security developments","text":"In a first phase of the armed conflict, on the northern front, Russian armed forces\nadvanced towards Kyiv from several directions, including from within Belarus, conducted\nstrikes on the capital, but fell short of capturing it.92 Russian troops took the Hostomel airport\nand set up positions in towns and settlements to the north and west of the city. On the way to\nKyiv, the Russian armed forces surrounded Chernihiv, which became the scene of heavy\nairstrikes and artillery fire.93 On 25 February 2022, a representative of the Russian\nFederation’ Ministry of Defence declared that its armed forces had “blocked” the city. 94"},{"id":"a-hrc-52-crp-4-p0070","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"70","seq":71,"section":"1. Military and security developments","text":"By the end of March 2022, the offensive towards Kyiv had stalled. After Ukrainian\narmed forces regained control of areas north of Kyiv and Russian troops withdrew from\nlocalities they had temporarily occupied, allegations of grave human rights and international\nhumanitarian law violations and large-scale destruction arose. Dozens of bodies of dead\ncivilians were found in Bucha, in the Kyiv region, and other settlements.95"},{"id":"a-hrc-52-crp-4-p0071","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"71","seq":72,"section":"1. Military and security developments","text":"In north-eastern Ukraine, Kharkiv and Sumy cities quickly became the scenes of\nheavy urban warfare. Shelling pounded residential and other key buildings and led to large-\nscale destruction. While fighting in and around Kharkiv continued, by April 2022, Russian\narmed forces withdrew from the area around Sumy city."},{"id":"a-hrc-52-crp-4-p0072","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"72","seq":73,"section":"1. Military and security developments","text":"Starting on 28 February 2022, Russian armed forces attempted to capture the city of\nIzium, in the Kharkiv region. On 24 March 2022, the Russian Federation Ministry of Defence\ndeclared that Izium was under the full control of its forces.96 However, combat continued and\non 1 April 2022, Ukrainian officials conceded that Russian armed forces had acquired control\nof the city.97"},{"id":"a-hrc-52-crp-4-p0073","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"73","seq":74,"section":"1. Military and security developments","text":"In south-eastern Ukraine, as of 24 February 2022, Russian armed forces with Russian-\naffiliated armed groups from the former self-proclaimed Donetsk People’s Republic,\nlaunched attacks on the city of Mariupol from within Russian-controlled areas in the Donetsk\nregion and from occupied Crimea. They laid siege to the city and gradually gained control of\nswaths of territory, as attacks intensified, with unremitting air raids and artillery\nbombardments, leading to large-scale destruction. Heavy fighting hampered evacuation\nefforts and curtailed access to basic necessities for civilians. 98"},{"id":"a-hrc-52-crp-4-p0074","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"74","seq":75,"section":"1. Military and security developments","text":"In the south, the city of Kherson became the first major Ukrainian city to fall on 2\nMarch 2022. Russian armed forces gradually occupied surrounding localities. In\nneighbouring Zaporizhzhia region, they seized Melitopol, Berdiansk, and Enerhodar, where\nthe Zaporizhzhia Nuclear Power Plant is situated.99\nb)    Fighting in eastern Ukraine and seizure of Mariupol"},{"id":"a-hrc-52-crp-4-p0075","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"75","seq":76,"section":"1. Military and security developments","text":"A second phase of the armed conflict was initiated on 18 April 2022, with the launch\nof the “Battle for Donbas”, which, according to Sergei Lavrov, Minister of Foreign Affairs\nof the Russian Federation, was aimed at the “full liberation” of the then so-called Donetsk\nand Luhansk People’s Republics.100 The offensive of the Russian armed forces further\nconcentrated on these regions and other eastern areas, with the support of affiliated armed\ngroups. Weeks-long fighting revolved in and around Sievierodonetsk and Lysychansk cities,\nuntil their capture by Russian armed forces in June and July 2022 respectively, as well as\naround Sloviansk, in the Donetsk region.101"},{"id":"a-hrc-52-crp-4-p0076","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"76","seq":77,"section":"1. Military and security developments","text":"The siege of Mariupol continued until 20 May 2022, when the Russian Federation\ndeclared that it had gained full control of the city.102 Mariupol became one of the worst-hit\nareas. Ukrainian authorities estimated that thousands of civilians had been killed103 and that\na large number of the city’s residential buildings, houses, and civilian facilities had been\ndestroyed, while many other buildings had been damaged beyond repair.104 The full extent\nof casualties and of the damage to civilian objects has been impossible to assess at this time.\nc)    Ukrainian armed forces counter-offensive, strikes on critical infrastructure"},{"id":"a-hrc-52-crp-4-p0077","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"77","seq":78,"section":"1. Military and security developments","text":"During a third phase of the armed conflict, a change in the battlefield dynamics could\nbe noted. Ukrainian forces led counter-offensive operations in Kharkiv, Donetsk, Luhansk,\nand Kherson regions, and retook hundreds of settlements in the northeast, east, and south.105"},{"id":"a-hrc-52-crp-4-p0078","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"78","seq":79,"section":"1. Military and security developments","text":"On 21 September 2022, President Putin signed a decree announcing a partial military\nmobilization, with immediate effect.106 Prior to this announcement, the Russian Parliament\namended the law on military service to strengthen the punishment for avoidance of military\nservice. The Parliament also adopted a law allowing for the mobilization of persons convicted\nof serious crimes.107 On 28 October 2022, Russian Defence Minister Sergei Shoigu\nannounced that the task to mobilize 300,000 men had been completed.108"},{"id":"a-hrc-52-crp-4-p0079","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"79","seq":80,"section":"1. Military and security developments","text":"On 19 October 2022, President Putin adopted a decree imposing martial law in\nRussian occupied regions of Donetsk, Kherson, Luhansk, and Zaporizhzhia, in Ukraine. The\ndecree foresaw the possibility of implementing a range of measures, such as curfews,\nproperty seizures, internment, and restrictions on freedom of movement, freedom of\nassociation, and activities of political parties and other public associations. 109"},{"id":"a-hrc-52-crp-4-p0080","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"80","seq":81,"section":"1. Military and security developments","text":"Regarding battlefield developments, in September 2022, Ukrainian armed forces\ncontinued the counter-offensive they had started in the Kharkiv region in May 2022.\nPopulations from recovered cities and settlements, as well as Ukrainian authorities, reported\nlarge-scale atrocities, such as unlawful killings, summary executions, torture, sexual\nviolence, and unlawful confinement, during occupation. 110"},{"id":"a-hrc-52-crp-4-p0081","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"81","seq":82,"section":"1. Military and security developments","text":"Hostilities continued in the Donetsk and Luhansk regions. In October 2022, Ukrainian\narmed forces recovered the control of the city of Lyman and of other villages, in the Donetsk\nregion.111 Heavy fighting revolved near Bakhmut, Avdiivka, and Vuhledar. In Luhansk\nregion, combat took place in the vicinity of Svatove and Kreminna."},{"id":"a-hrc-52-crp-4-p0082","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"82","seq":83,"section":"1. Military and security developments","text":"On 10 October 2022, two days after an explosion caused damage to the Crimean\nBridge connecting the Russian Federation with Crimea, the Russian Federation launched a\nwave of missile and uncrewed aerial vehicles attacks targeting Ukraine’s critical\ninfrastructure.112 President Putin declared that the Russian Federation launched “a massive\nstrike” on “energy, military command and communications facilities of Ukraine”.113 During\nthe subsequent weeks and months, further similarly intense and large-scale attacks with\nmissiles and unmanned aerial vehicles were carried out.114 The attacks affected numerous\nregions of Ukraine, targeted energy-related infrastructure, and reportedly hit residential\nbuildings, education and healthcare facilities,115 and killed and injured civilians.116 As a\nconsequence, millions were left without heating, electricity, and water for certain periods of\ntime, during cold months.117"},{"id":"a-hrc-52-crp-4-p0083","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"83","seq":84,"section":"1. Military and security developments","text":"In the south, missile strikes hit the cities of Mykolaiv and Zaporizhzhia.118 Military\nactivities and shelling repeatedly occurred at the Zaporizhzhia Nuclear Power Plant.119 In\nNovember 2022, Ukrainian armed forces retook control of the Kherson city area, while\nRussian armed forces gradually withdrew. Ukrainian authorities have found evidence of\nalleged human rights violations and crimes committed while the area was under occupation,\nincluding summary executions, torture, sexual violence, and unlawful confinement.\nd)     Nuclear risks"},{"id":"a-hrc-52-crp-4-p0084","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"84","seq":85,"section":"1. Military and security developments","text":"The armed conflict has triggered serious concerns for the safety of two of Ukraine’s\nnuclear plants. In March 2022, Russian armed forces took control of the Chernobyl Nuclear\nPower Plant, the surrounding exclusion zone, and of the Zaporizhzhia Nuclear Power Plant -\nEurope’s largest such facility.120 The deployment of military personnel and assets at those\nfacilities sparked fears of a major nuclear accident.121 At the end of March 2022, Russian\narmed forces returned the Chernobyl Nuclear Power Plant to Ukrainian personnel, 122 but\nremained in control of the Zaporizhzhia Nuclear Power Plant. The International Atomic\nEnergy Agency (IAEA) highlighted the risks of a nuclear disaster, after repeated incidents of\nshelling and explosions at the site of the plant.123 The IAEA, other United Nations bodies,\nand States repeatedly called for the establishment of a nuclear security protection zone around\nthe facility and for the complete halt of all military activity in the area. 124"},{"id":"a-hrc-52-crp-4-p0085","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"85","seq":86,"section":"1. Military and security developments","text":"In October 2022, President Putin signed a decree instructing to take Zaporizhzhia\nNuclear Power Plant facilities into Russian state property. 125 The Russian Federation\nestablished a state organization for the operation of the plant and demanded that Ukrainian\nstaff running the facility sign new contracts with this new entity. The IAEA has emphasised\nthat the plant is Ukrainian and has highlighted the stressful and difficult working conditions\nfor the Ukrainian staff operating it, with the potential of a negative impact on nuclear\nsafety.126\ne)     Threats and allegations of use of weapons of mass destruction"},{"id":"a-hrc-52-crp-4-p0086","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"86","seq":87,"section":"1. Military and security developments","text":"Since the outset of the armed conflict, fears loomed regarding the potential of a spread\nor escalation.127 On 27 February 2022, referring to sanctions targeting the Russian Federation,\nPresident Putin ordered the deterrent forces to be on high combat alert.128 On 22 September\n2022, referring to a threat coming from “the West”, he warned that the Russian Federation\nwould “use all means at its disposal to defend Russia”, including nuclear weapons. 129 The\nUnited Nations, intergovernmental and regional organizations, and States denounced the\n“unacceptable nuclear rhetoric”.130"},{"id":"a-hrc-52-crp-4-p0087","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"87","seq":88,"section":"1. Military and security developments","text":"Russian Federation representatives accused Ukraine of developing nuclear or\nbiological weapons. During Security Council meetings in March, May, and October 2022,\nthe Russian Federation claimed that biological weapons programmes existed in Ukraine. In\nOctober 2022, the Russian Federation also alleged that Ukraine was preparing to detonate a\n“dirty bomb” on its territory. Member States rejected these claims as unsubstantiated. 131\nf)     Support from Belarus"},{"id":"a-hrc-52-crp-4-p0088","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"88","seq":89,"section":"1. Military and security developments","text":"During the months prior to 24 February 2022, the Russian Federation amassed troops\nand military assets in Belarus. Russian armed forces launched hostilities on the “northern\nfront” in Ukraine from within Belarus.132 In late February 2022, the Government of Belarus\nwarned that sanctions against the Russian Federation would “instigate the third world war”.133\nIt has been reported that Belarus, among other things, allowed the Russian Federation to fire\nmissiles from its territory, enabled transportation of Russian military personnel, heavy\nweapons, and military transporters, allowed Russian military aircraft to fly over its airspace\ninto Ukraine, providing refuelling points, and allowed it to use its infrastructure, such as\nairfields, fueling stations, and storage facilities.134 States and intergovernmental\norganizations condemned this support and imposed sanctions against the Belarusian\nregime.135 In October 2022, Belarusian President Lukashenko claimed that following an\n“aggravation of tensions” on the Belarus-Ukraine border, Belarus and the Russian Federation\nwould deploy a joint military group.136"},{"id":"a-hrc-52-crp-4-p0089","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"89","seq":90,"section":"2. Political context","text":"International organizations and forums, regional bodies, and States condemned in the\nstrongest terms the military invasion, called for its cessation, and imposed far-reaching\neconomic sanctions and other measures."},{"id":"a-hrc-52-crp-4-p0090","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"90","seq":91,"section":"2. Political context","text":"On 25 February 2022, a draft resolution demanding that the Russian Federation cease\nits use of force against Ukraine was vetoed by the Russian Federation at the United Nations\nSecurity Council.137 Consequently, on 27 February 2022, “[t]aking into account that the lack\n127 United Nations, “Ukraine war: Risks of spillover ‘remain all too real’, Security Council hears”, press\nrelease, 16 November 2022.\n128 Official website of the President of the Russian Federation, “Meeting with Sergei Shoigu and Valery\nGerasimov”, 27 February 2022.\n129 Official website of the President of the Russian Federation, “Address by the President of the Russian\nFederation”, 21 September 2022.\n130 S/PV.9135; The North Atlantic Treaty Organization, Press conference by NATO Secretary General\nJens Stoltenberg following the meetings of NATO Defence Ministers, 13 October 2022.\n131 See S/PV.8999, S/PV.9033, S/PV.9171.\n132 European Council, Council of the European Union (EU), Belarus' role in the Russian military\naggression of Ukraine: Council imposes sanctions on additional 22 individuals and further restrictions\non trade, 2 March 2022.\n133 BELTA News, “Lukashenka on sanctions pressure on Russia: pushing for a third world war”, 27\nFebruary 2022. (available only in Russian)\n134 European Council, Belarus' role in the Russian military aggression of Ukraine, Council imposes\nsanctions on additional 22 individuals and further restrictions on trade, 2 March 2022.\n135 European Council, EU restrictive measures against Belarus; EU Sanctions Map, Belarus.\n136 BELTA News, “Lukashenka warned Ukraine against a possible strike on Belarus”, 10 October\n2022. (available only in Russian)\n137 S/2022/155, S/PV.8979.\nof unanimity of its permanent members”, the Security Council referred the matter to the\nUnited Nations General Assembly.138 On 2 March 2022, during an emergency special\nsession, the General Assembly adopted the resolution “aggression against Ukraine”, which\ndemanded “that the Russian Federation immediately cease its use of force against Ukraine”\nand “immediately, completely and unconditionally withdraw all of its military forces from\nthe territory of Ukraine”.139 On 4 March 2022, in its resolution on the “Situation of human\nrights in Ukraine stemming from the Russian aggression”, the United Nations Human Rights\nCouncil stressed “the urgent need for the Russian Federation to immediately cease its military\nhostilities against Ukraine”.140 On 16 March 2022, in proceedings instituted by Ukraine,\nthe International Court of Justice ordered the Russian Federation to “suspend the military\noperations”.141 Amid widespread condemnation following atrocities uncovered in Bucha, the\nGeneral Assembly adopted a resolution calling for the Russian Federation to be suspended\nfrom the Human Rights Council.142"},{"id":"a-hrc-52-crp-4-p0091","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"91","seq":92,"section":"2. Political context","text":"On a regional level, on 24 February 2022, the European Council of the European\nUnion condemned in the strongest possible terms the Russian Federations’ unprecedented\nmilitary aggression against Ukraine. The European Union has adopted successive packages\nof sanctions targeting the Russian Federation and Belarus.143 Also on 24 February 2022,\nOrganization for Security and Co-operation in Europe parliamentarians referred to “the\nRussian Federation’s military operation in Ukraine” as “indefensible” and a “gross violation\nof international law”, and urged an immediate end to the hostilities. 144 On 3 March 2022, 45\nStates of the Organization for Security and Co-operation in Europe invoked the Moscow\nMechanism to “address the human rights and humanitarian impacts of the Russian\nFederation’s invasion and acts of war, supported by Belarus, on the people of Ukraine”.145\nOn 16 March 2022, the Committee of Ministers of the Council of Europe adopted a decision\nby which the Russian Federation ceased to be a member of the Council of Europe. 146\nb)     Negotiation attempts"},{"id":"a-hrc-52-crp-4-p0092","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"92","seq":93,"section":"2. Political context","text":"Attempts to engage the Russian Federation and Ukraine in meaningful negotiations\nhave not yielded success.147 Both State’s preconditions for negotiations have evolved over\ntime. They have refused to negotiate as long as the current presidents are in power.148 Russian\nofficials have declared that the “special military operation” will continue until initial goals\nare met149, one of them being “to remove” the Kyiv regime. 150 Ukrainian officials have\nexpressed no confidence that the Russian regime will keep its promises, emphasizing that\n138 S/RES/2623(2022).\n139 A/RES/ES-11/1.\n140 A/HRC/RES/49/1.\n141 Allegations of Genocide under the Convention on the Prevention and Punishment of the Crime of\nGenocide (Ukraine v. Russian Federation), Provisional Measures, Order of 16 March 2022, I.C.J.\nReports 2022, p. 211.\n142 A/RES/ES-11/3.\n143 European Council, Special meeting of the European Council, 24 February 2022.\n144 Organization for Security and Co-operation in Europe, “OSCE parliamentarians condemn Russian\nmilitary action in Ukraine, call for de-escalation at Vienna Winter Meeting”, press release, 24\nFebruary 2022.\n145 Organization for Security and Co-operation in Europe, “Ukraine appoints mission of experts\nfollowing invocation of the OSCE’s Moscow Mechanism”, press release, 15 March 2022.\n146 Council of Europe, Committee of Ministers, Decision, Consequences of the aggression of the\nRussian Federation against Ukraine (Procedure under Article 8 of the Statute),\nCM/Del/Dec(2022)1428ter/2.3, 16 March 2022.\n147 United Nations, “Ukraine invasion: Guterres appeals for ‘immediate humanitarian ceasefire’”, press\nrelease, 28 March 2022.\n148 See official website of the President of Ukraine, “Address by President Zelenskyy - We are taking\nour decisive step by signing Ukraine's application for accelerated accession to NATO”, 30 September\n2022; RIA Novosti, “The Kremlin commented on Kyiv’s refusal to dialogue with Moscow”, 4\nOctober 2022. (available only in Russian)\n149 See Interfax, “Peskov said that negotiations with Zelensky can only go on about Kyiv's fulfilment of\nMoscow's conditions”, 4 September 2022 (available only in Russian); Interfax, “Peskov, when asked\nabout Putin's confidence in the military command, said that the NWO would continue”, 12 September\n2022. (available only in Russian).\n150 Euronews, “Moscow's goal is to remove 'unacceptable' Kyiv regime, says Russia's top diplomat”, 26\nJuly 2022.\none key prerequisite for negotiations is the withdrawal of the Russian Federation from\nUkrainian territories.151 After the Russian Federation’s “annexation” of four partially\noccupied Ukrainian regions, President Zelenskyy signed a decree on the “impossibility of\nnegotiations with Russian President Putin”.152 President Putin called for negotiations but\nunderscored that the “annexation” decision will not be revised, as it reflects “the choice of\nthe people.”153 On 15 November 2022, President Zelenskyy outlined ten pre-conditions to\nend the armed conflict, which included the full withdrawal of Russian troops from Ukraine’s\nterritory, the restoration of Ukraine’s territorial integrity, and justice. 154\nc)     Annexation of territories"},{"id":"a-hrc-52-crp-4-p0093","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"93","seq":94,"section":"2. Political context","text":"On 21 February 2022, President Putin “recognized the independence of the Donbass\nPeople’s Republics”, in eastern Ukraine, and stated that this had been done to “stop this\nnightmare – a genocide against the millions of people living there who are pinning their hopes\nonly on Russia”.155 At the outset of the armed conflict, Russian armed forces took control of\nparts of Kherson and Zaporizhzhia regions. From the early days of Russia’s occupation,\nreports began to emerge that Russian armed forces were abducting, torturing, and even\nexecuting local government officials. Local sources claimed that a large number of local\ngovernment officials, including mayors had been abducted. 156 It is reported that Russian\nauthorities installed military-civilian authorities which created previously non-existent\n“regional governments” in Kherson and Zaporizhzhia regions, with personnel including both\nresidents of the regions and Russian authorities.157 Between 23 and 27 September 2022, the\nRussian Federation158 organized so-called referendums in the occupied areas of Donetsk,\nKherson, Luhansk, and Zaporizhzhia, on their incorporation into the Russian Federation. On\n30 September 2022, President Putin and the de facto authorities of the four regions signed\n“treaties” on their “accession” to the Russian Federation.159 International organizations have\nwidely condemned the so-called referendums and the illegal annexation (see paras. 675 -\n678).160"},{"id":"a-hrc-52-crp-4-p0094","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"94","seq":95,"section":"3. Consequences for the civilian population","text":"Over a year the armed conflict has had a devastating toll on the civilian population.\nThe lives of millions of Ukrainians have been upended by the loss, disappearance, the\ndisplacement of their relatives, the destruction of cities and villages, and the lack of access\nto basic necessities. As of 15 February 2023, OHCHR had recorded 8,006 civilians killed\nand 13,287 injured in Ukraine since 24 February 2022. Of adult civilian casualties whose sex\nwas known, 61.1 per cent were men and 39.9 per cent were women. OHCHR believes that\nthe actual figures are considerably higher.161"},{"id":"a-hrc-52-crp-4-p0095","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"95","seq":96,"section":"3. Consequences for the civilian population","text":"In addition to the human losses, the armed conflict in Ukraine has caused a population\ndisplacement not seen in Europe since the Second World War. As of 21 February 2023,\nUNHCR reported about eight million refugees from Ukraine across Europe, of which around\n90 per cent were women and children.162 In addition, about 5.4 million people are currently\ndisplaced across Ukraine.163"},{"id":"a-hrc-52-crp-4-p0096","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"96","seq":97,"section":"3. Consequences for the civilian population","text":"Large-scale attacks have destroyed residential buildings, hospitals, schools, and\ncurtailed people’s access to heat, electricity, food, and water. While the effect of the\nhostilities is particularly visible along frontlines, the whole country is deeply affected. 164\nPeople face harsh living conditions, particularly during the cold months. Nearly 18 million\npeople in Ukraine are in need of humanitarian assistance. 165"},{"id":"a-hrc-52-crp-4-p0097","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"97","seq":98,"section":"3. Consequences for the civilian population","text":"The armed hostilities have also posed considerable challenges to food transport,\nexports, and supplies within and beyond Ukraine, raising concern for food security\nworldwide. The ‘Black Sea Grain Initiative’ agreement reached by Ukraine and the Russian\nFederation on 22 July 2022, following facilitation by the United Nations and Türkiye, has\nallowed some maritime exports through three Ukrainian Black Sea ports to resume.166"},{"id":"a-hrc-52-crp-4-p0098","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"98","seq":99,"section":"3. Consequences for the civilian population","text":"The impact of the armed conflict is severe and differs for various categories of\npersons. Some vulnerable groups, such as older persons, children, persons with disabilities,\nand persons belonging to minorities, have been particularly affected (see paras. 823-834).\nPeople live in a climate of uncertainty and fear. Survivors are coping with the physical,\npsychological, and socio-economic consequences of violent events and large-scale damage.\nThe armed conflict has undermined access to the most basic human rights, such as the right\nto health, education, adequate housing, food, and water."},{"id":"a-hrc-52-crp-4-p0099","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"99","seq":100,"section":"3. Consequences for the civilian population","text":"Countless allegations of violations and abuses of human rights and international\nhumanitarian law, and related international crimes, have been reported. Numerous\ninternational and national entities have initiated investigations (see section VII). For instance,\nthe Office of the Ukrainian Prosecutor General has opened investigations into thousands of\nalleged war crimes and on 2 March 2022, the Prosecutor of the International Criminal\nCourt opened an investigation into allegations of war crimes, crimes against humanity, and\ngenocide.167 The high number and the complexity of the cases, as well as the lack of\ncooperation by Russian Federation authorities, are among the challenges faced during the\ninvestigations and prosecutions of these violations and crimes."},{"id":"a-hrc-52-crp-4-p0100","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"100","seq":101,"section":"D. Act of aggression","text":"Human Rights Council resolution 49/1 – establishing the Commission’s mandate –\nis based on the premise of “the aggression against Ukraine by the Russian Federation”. 168\nThis is also stated in Human Rights Council resolution S-34/1, which supplements the\nCommission’s initial mandate.169 Both resolutions refer to General Assembly resolution ES-\n11/1, which “deplores in the strongest terms the aggression by the Russian Federation against\nUkraine in violation of Article 2(4) of the Charter”.170 The Commission’s mandate is to,\namong other things, “investigate all alleged violations and abuses of human rights and\nviolations of international humanitarian law, and related crimes in the context of the\naggression against Ukraine by the Russian Federation”."},{"id":"a-hrc-52-crp-4-p0101","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"101","seq":102,"section":"D. Act of aggression","text":"Independence and impartiality are two of the principles underpinning the\nCommission’s mandate.171 In line with these principles, a commission of inquiry has inherent\nauthority to interpret its mandate. Precedent exists for a mechanism to reach its own\nconclusions about the characterization of the situation as stated in its mandating resolution. 172\nConsequently, the Commission has independently assessed whether the situation in Ukraine\nis an act of “aggression against Ukraine by the Russian Federation” as stated in resolution\n49/1."},{"id":"a-hrc-52-crp-4-p0102","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"102","seq":103,"section":"D. Act of aggression","text":"In General Assembly resolution 3314 (XXIX),173 adopted by consensus, aggression is\ndefined as “the use of armed force by a State against the sovereignty, territorial integrity or\npolitical independence of another State, or in any other manner inconsistent with the Charter\nof the United Nations”.174 The resolution provides a non-exhaustive list of acts that qualify\nas an act of aggression.175"},{"id":"a-hrc-52-crp-4-p0103","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"103","seq":104,"section":"D. Act of aggression","text":"If an act of aggression occurs, the resolution holds that a “war of aggression is a crime\nagainst international peace”, and it “gives rise to international responsibility”.176 Further,\n“[n]o territorial acquisition or special advantage resulting from aggression is or shall be\nrecognized as lawful”.177 Aggression is considered as the “most serious and dangerous form\nof the illegal use of force, being fraught, in the conditions created by the existence of all types\nof weapons of mass destruction, with the possible threat of a world conflict and all its\ncatastrophic consequences”.178"},{"id":"a-hrc-52-crp-4-p0104","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"104","seq":105,"section":"D. Act of aggression","text":"The Commission has concluded that the use of armed force by the Russian Federation\nagainst Ukraine was an act of aggression as defined in General Assembly resolution 3314\n(XXIX). It has found reasonable grounds to conclude that the following non-exhaustive list\nof acts each qualify as an act of aggression against Ukraine: the invasion or attack by the\narmed forces of the Russian Federation against the territory of Ukraine; 179 the attack by the\narmed forces of the Russian Federation on the land, sea and air forces of Ukraine; 180 the\nbombardment and use of weapons by the armed forces of the Russian Federation against the\nterritory of Ukraine;181 and the military occupation by the Russian Federation of Ukrainian\nterritory, however temporary, resulting from the abovementioned invasion or attack. 182 In this\nreport, the Commission’s main focus remains on the Russian Federation’s conduct on and\nafter 24 February 2022, but this does not preclude the potential existence of previous acts of\naggression."},{"id":"a-hrc-52-crp-4-p0105","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"105","seq":106,"section":"D. Act of aggression","text":"The Russian Federation acknowledged that it launched a “special military operation”\nagainst Ukraine on and after 24 February 2022, but it justifies this action with various\nsubmissions including that it was acting in accordance with article 51 of the United Nations\nCharter.183 General Assembly resolution 3314 (XXIX) states that “[n]o consideration of\nwhatever nature, whether political, economic, military or otherwise, may serve as a\njustification for aggression”.184 Consequently, the Commission will only consider the\nRussian Federation’s claim that its conduct was consistent with article 51 of the United\nNations Charter."},{"id":"a-hrc-52-crp-4-p0106","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"106","seq":107,"section":"D. Act of aggression","text":"Article 51 of the United Nations Charter states that “[n]othing in the present Charter\nshall impair the inherent right of individual or collective self-defence if an armed attack\noccurs against a Member of the United Nations, until the Security Council has taken measures\nnecessary to maintain international peace and security. Measures taken by Members in the\nexercise of this right of self-defence shall be immediately reported to the Security Council\nand shall not in any way affect the authority and responsibility of the Security Council under\nthe present Charter to take at any time such action as it deems necessary in order to maintain\nor restore international peace and security”."},{"id":"a-hrc-52-crp-4-p0107","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"107","seq":108,"section":"D. Act of aggression","text":"The Russian Federation was not subject to an armed attack by Ukraine prior to 24\nFebruary 2022. Much of the Russian Federation’s claim is about perceived threats against it\nand, to an extent, alludes to a potential forthcoming attack. 185 Further, these assertions are\nnot limited to Ukraine, but encompass other States and the North Atlantic Treaty\nOrganization (NATO), of which Ukraine is not a member State. 186 Such assertions do not\ndemonstrate an imminent armed attack against the Russian Federation, let alone such\nan attack by Ukraine. These assertions are unsubstantiated and do not fulfil the requirements\nof article 51. The Commission has therefore concluded that the Russian Federation’s claim\nof acting in accordance with article 51 is without merit and therefore the right of self-defence\nwithin article 51 is unavailable to the Russian Federation in these circumstances. 187"},{"id":"a-hrc-52-crp-4-p0108","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"108","seq":109,"section":"V. Violations of international law","text":"The Commission aimed, in its operations, to ensure a broad thematic and geographic\ncoverage in its investigations. It has focused on investigating behaviour during the conduct\nof hostilities and violations of personal integrity, including summary executions, torture and\nill-treatment, detention, and sexual and gender-based violence. The Commission has also\nlooked into violations of the laws of occupation and transfers of children. It has found that\nviolations of human rights and international humanitarian law, as well as related crimes, have\nbeen committed across Ukraine, and in the Russian Federation.188"},{"id":"a-hrc-52-crp-4-p0109","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"109","seq":110,"section":"V. Violations of international law","text":"In all the cases examined, the Commission has sought to identify individual\nperpetrators of violations and crimes, the units deployed in the concerned areas, and their\nchain of command. It has attempted to determine whether the crimes were committed in\nfurtherance of orders or policies at a higher level. The Commission has developed a separate\nlist of identified perpetrators and military units responsible for crimes and violations."},{"id":"a-hrc-52-crp-4-p0110","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"110","seq":111,"section":"1. Overview","text":"The use of explosive weapons in populated areas has been the main cause of civilian\ndeaths in the war in Ukraine. OHCHR estimated that 90.3 per cent of civilian casualties have\nbeen caused by explosive weapons.189 Such attacks have damaged or destroyed thousands of\nresidential buildings, hospitals, schools, and critical infrastructure. In cities particularly\naffected by the fighting, entire neighbourhoods have been decimated. The Commission is\nstruck by the level of destruction in Mariupol, where detailed accounts from survivors,\nsatellite imagery, photographs and video footage show that large parts of the city have been\nerased."},{"id":"a-hrc-52-crp-4-p0111","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"111","seq":112,"section":"1. Overview","text":"Some of the explosive weapons’ attacks were conducted in the context of Russian\narmed forces’ attempts to capture towns or cities, while others struck areas far from\nfrontlines. Russian armed forces’ waves of attacks systematically targeting power plants and\nother energy-related installations in Ukraine, which intensified considerably since October\n2022, have struck almost all the regions of Ukraine. These attacks have, during certain\nperiods, deprived large portions of the civilian population of not only electricity, but also\nwater, heating, telecommunications, means of preserving food and cooking, causing great\nharm and suffering, in particular during the cold months."},{"id":"a-hrc-52-crp-4-p0112","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"112","seq":113,"section":"1. Overview","text":"In its examination of the conduct of hostilities, the Commission has investigated the\nimpact of hostilities and of individual attacks with explosive weapons in populated areas in\nterritory under Ukrainian Government control and in areas controlled by Russian armed\nforces; the waves of strikes targeting Ukraine’s critical infrastructure launched starting 10\nOctober 2022; and conduct which has endangered the population through locating military\npersonnel and equipment in civilian areas."},{"id":"a-hrc-52-crp-4-p0113","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"113","seq":114,"section":"1. Overview","text":"The Commission has investigated in more detail 25 individual attacks with explosive\nweapons in populated areas in nine regions of Ukraine. These attacks have impacted a variety\nof civilian objects and places where civilians were present, and have caused deaths, injuries,\nand considerable harm. The use of certain types of weapons has been particularly lethal in\npopulated areas, as they could not be directed at a military objective, were inaccurate, or\nstruck a wide area."},{"id":"a-hrc-52-crp-4-p0114","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"114","seq":115,"section":"1. Overview","text":"Under international humanitarian law, indiscriminate attacks are prohibited. They are\nattacks which are not directed at a specific military objective and those which employ a\nmethod or means of combat which cannot be directed at a specific military objective or the\neffects of which cannot be limited as required by international humanitarian law.\nConsequently, they are of a nature to strike military objectives and civilians or civilian objects\nwithout distinction.190 Disproportionate attacks are also prohibited and are considered\nindiscriminate.191 Disproportionate attacks are ones which may be expected to cause\nincidental loss of civilian life, injury to civilians, damage to civilian objects, or a combination\nthereof, which would be excessive in relation to the concrete and direct military advantage\nanticipated.192 Further, it is a war crime to intentionally launch such an attack in the\nknowledge that such attack will cause excessive loss of life, injury to civilians or damage to\ncivilian objects.193"},{"id":"a-hrc-52-crp-4-p0115","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"115","seq":116,"section":"1. Overview","text":"The Commission has concluded that a majority of attacks it has investigated were\nindiscriminate, as they, among other things, used a method or means which could not be\ndirected at a specific military objective or their effects could not be limited as required.\nRussian armed forces were responsible or likely responsible for most of the attacks. In some\ncases, it found that they failed to take feasible precautions to verify that objectives were\nneither civilians nor civilian objects.194 Several attacks were also disproportionate, as they\nwere initiated with an apparent disregard for the presence of large concentrations of civilians\nor objects with special protection, which caused excessive harm and suffering. Ukrainian\narmed forces were likely responsible for a few indiscriminate attacks."},{"id":"a-hrc-52-crp-4-p0116","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"116","seq":117,"section":"1. Overview","text":"Further, the Commission has investigated the large-scale attacks against Ukraine’s\ncritical infrastructure which Russian armed forces launched from 10 October 2022. The\nattacks took a hard toll on the civilian population, as they deprived millions of basic\nnecessities and services, including during the cold months. The Commission found that they\nconstitute the war crime of excessive incidental death, injury or damage."},{"id":"a-hrc-52-crp-4-p0117","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"117","seq":118,"section":"1. Overview","text":"Crimes against humanity are enumerated acts that are committed as part of a\nwidespread or systematic attack directed against any civilian population, with knowledge of\nthe attack.195 The attacks on Ukraine’s critical infrastructure have been carried out in waves\nof hundreds of long-range missiles and drones, striking almost all of Ukraine’s regions, and\nsystematically targeting powerplants and other infrastructure critical for the transmission of\nelectricity and the generation of heat across the country. The Commission has found that\nthese attacks were widespread and systematic and has considered whether they may amount\nto a crime against humanity of other inhumane acts. Further time and resources are needed\nto investigate the attacks to clarify if the accumulated impact of the attacks becomes\ncomparable to one of the enumerated acts of crimes against humanity, and to what extent the\npolicy was directed against the civilian population.196"},{"id":"a-hrc-52-crp-4-p0118","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"118","seq":119,"section":"1. Overview","text":"The Commission has also found situations in which both parties to the armed conflict\nfailed to protect civilians or civilian objects against the effects of attacks by locating military\nobjects and forces within or near densely populated areas."},{"id":"a-hrc-52-crp-4-p0119","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"119","seq":120,"section":"1. Overview","text":"In this regard, international humanitarian law prescribes that parties to the armed\nconflict shall, to the maximum extent feasible, avoid locating military objectives within or\nnear densely populated areas, and endeavour to remove civilians and civilian objects under\ntheir control from the vicinity of military objectives. 197"},{"id":"a-hrc-52-crp-4-p0120","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"120","seq":121,"section":"1. Overview","text":"As part of its investigations into attacks conducted with the use of explosive weapons,\nthe Commission inspected the sites of attacks, where possible; heard testimonies from\nwitnesses and survivors; as well as authenticated and analysed relevant photographs, satellite\nimagery, and video footage. It submitted detailed questions to both parties to the conflict.\nRegretfully, lack of access to certain areas has hampered some aspects of its investigations.\nDue to the vast multitude of such attacks, in addition to particular challenges in investigating\nthem, the situations outlined below are only a small sample."},{"id":"a-hrc-52-crp-4-p0121","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"121","seq":122,"section":"1. Overview","text":"In addition, the Commission has not investigated in detail the 29 July 2022 incident\nthat killed more than 50 Ukrainian prisoners of war at a detention facility in Olenivka,\nDonetsk region, because a dedicated fact-finding mission was established by the Secretary-\nGeneral of the United Nations to do so shortly after the attack. 198 It notes with regret,\nhowever, that conditions were not met for the mission to deploy to the site, leading to the\n192 Additional Protocol I to the Geneva Conventions, articles 51(5)(b) and 57(2)(a)(iii)-(b).\n193 Additional Protocol I to the Geneva Conventions, articles 51(5)(b), 57(2)(a)(iii)-(b), and 85(3)(b)\nand (5). See also Rome Statute, article 8(2)(b)(iv).\n194 See Additional Protocol I of the Geneva Conventions, article 57(2).\n195 Rome Statute, article 7(1).\n196 See Crime against humanity of other inhumane acts, Rome Statute, article 7(1)(k).\n197 Additional Protocol I to the Geneva Conventions, article 58.\n198 United Nations Secretary-General, “Members of Fact-finding Mission regarding Incident at\nOlenivka, Ukraine, on 29 July 2022”, 22 August 2022.\ndisbanding of the mission in early January 2023.199 The Commission is of the view that an\ninvestigation is required due to the gravity of the case."},{"id":"a-hrc-52-crp-4-p0122","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"122","seq":123,"section":"2. Impact of hostilities and attacks with explosive weapons","text":"Attacks with explosive weapons in populated areas have inflicted considerable\ncivilian harm. The Commission has observed first-hand the damage to buildings and\ninfrastructure in virtually all places it visited. It was particularly struck by the extent of the\ndestruction that it saw in the cities of Chernihiv, Izium, and Kharkiv. While it has not been\nable to visit the city of Mariupol, in Donetsk region, the Commission has reviewed hundreds\nof photos and videos from the city and satellite imagery analysis of destroyed buildings. It\nhas interviewed over 30 civilians who were in the city during heavy fighting and the Russian\narmed forces’ siege of the city, starting early March 2022. The witnesses reported frequent\nand intensive shelling and airstrikes, including on civilian buildings, and described explosive\nweapons use during these periods in the city as “constant”, “non-stop”, and “never-ending”.\nPhotos and videos from Mariupol and satellite imagery corroborate the widespread\ndestruction of residential areas. As of 12 May 2022, 32 per cent of buildings in two of\nMariupol’s main districts, the Livoberezhnyi and Zhovtnevyi districts, had sustained damage\nthat was visible on satellite imagery."},{"id":"a-hrc-52-crp-4-p0123","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"123","seq":124,"section":"2. Impact of hostilities and attacks with explosive weapons","text":"Many civilians are believed to have died during the siege of Mariupol;200 the actual\nnumber cannot be verified at present. Witnesses recounted attacks that struck the buildings\nwhere they lived or nearby residential buildings. They told the Commission that they saw\npeople being killed in attacks with explosive weapons, dead bodies on the streets, and graves\nin residential areas. A woman recounted how she had to evacuate from Mariupol without\nbeing able to bury her nine-year-old daughter, who was killed by shelling on their home. One\nman reported that a neighbour killed during the siege, together with many other people, had\nbeen buried in the playground of a nearby kindergarten. One woman told the Commission\nthat she had sheltered in three different places in Mariupol and that she had to leave all of\nthem because of constant attacks. She shared the shock she had when she emerged from one\nof the shelters, as everything was in ruins and she could not recognize areas of the city."},{"id":"a-hrc-52-crp-4-p0124","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"124","seq":125,"section":"2. Impact of hostilities and attacks with explosive weapons","text":"During the siege, from the first days of March 2022, civilians were in addition left\nwithout basic services such as water, gas and electricity, in cold weather. Residents prepared\nfood and gathered water outside, which also exposed them to risks of shelling. Extended\nperiods of hardship have taken both a deep physical and psychological toll. Witnesses\nrecounted the immense difficulties and fear during their attempts to evacuate under fire,\nwhich compounded their trauma. A witness described the passing of over 15 checkpoints in\n15 hours to reach a safe area, as he fled with his family from Mariupol. The full effects of\nthese compound factors will only manifest themselves over time."},{"id":"a-hrc-52-crp-4-p0125","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"125","seq":126,"section":"2. Impact of hostilities and attacks with explosive weapons","text":"Attacks carried out with explosive weapons in urban areas have affected educational\ninstitutions and hospitals throughout Ukraine. They have damaged or destroyed thousands of\nresidential buildings, over 3000 educational institutions201 and more than 600 medical\nfacilities.202 The Commission has collected witness accounts about the damage or destruction\nof more than 30 educational institutions in the regions of Chernihiv, Dnipropetrovsk,\nDonetsk, Kharkiv, Kherson, Kyiv, and Sumy. Fighting and attacks also affected a significant\nnumber of hospitals, which generally have protected status under international humanitarian\nlaw.203 The World Health Organization recorded 611 incidents of attacks by heavy weapons\nfrom 24 February 2022 to 1 February 2023 impacting medical facilities, patients, or\npersonnel.204 The Commission has also documented that fighting and attacks led to the\ndestruction or damage of five hospitals, including three in Chernihiv, one in Kharkiv, and\none in Sumy regions."},{"id":"a-hrc-52-crp-4-p0126","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"126","seq":127,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has investigated attacks carried out with explosive weapons in\nterritory controlled by the Government of Ukraine. These attacks have impacted civilians and\ncivilian objects, causing large numbers of casualties and destruction. They have been carried\nout with explosive weapons with wide-area effects, which have the potential to cause\nconsiderable civilian harm when employed in populated areas. The Commission has\ndetermined many of the documented attacks to be indiscriminate, as they, among other things,\nused a method or means which were not directed at a specific military objective or their\neffects could not be limited as required. Several attacks were disproportionate, as they were\ninitiated with an apparent disregard for the presence of large concentrations of civilians or of\ncivilian objects with special protection, which caused excessive harm and damage."},{"id":"a-hrc-52-crp-4-p0127","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"127","seq":128,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Some widely reported examples of such attacks, which the Commission has also\ninvestigated, are the 16 March 2022 attack carried out during the siege of Mariupol on the\ncity’s Drama Theatre, that killed and injured a large number of people; the 8 April 2022\nattack on the Kramatorsk train station, in the Donetsk region, in which 59 people were killed\nand 92 were injured; the 27 June 2022 attack on a shopping mall in Kremenchuk, Poltava\nregion, that killed 21 and injured dozens; and the 14 January 2023 attack on a residential\nbuilding in Dnipro, Dnipropetrovsk region, which killed 44 civilians and injured at least 81\n(see case descriptions starting para. 145).205 The attacks documented are just a small sample\nof the multitude of attacks with explosive weapons since the beginning of the invasion. They\nare also distinct from the large-scale attacks on Ukraine’s critical infrastructure installations\nwhich will be examined in a separate section below."},{"id":"a-hrc-52-crp-4-p0128","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"128","seq":129,"section":"3. Unlawful attacks with the use of explosive weapons","text":"As regards their general context, some of these attacks have been carried out at the\nfrontlines, when Russian armed forces attempted to capture localities and attacked,\nsurrounded, or laid sieges to urban areas. This was the case, among other localities, in\nChernihiv, Izium and Mariupol cities, which became the scenes of heavy fighting and where\na large number of attacks with explosive weapons were carried out. Other such attacks have\nimpacted civilian objects in cities and towns far away from the frontlines. This is the case,\nfor example, of attacks in Dnipro, Kremenchuk, and Serhiivka."},{"id":"a-hrc-52-crp-4-p0129","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"129","seq":130,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In each case, the Commission has sought to determine the party responsible for the\nattack. To this end, it has reviewed and analysed a combination of factors, including the\ncontext and circumstances of each of the attacks, accounts of witnesses and other\nstakeholders, the examination of the site of the attacks, weapons remnants, craters, the impact\nand damage produced, the direction of the attacks, the minimum and maximum range of the\nweapons systems employed, as well as other relevant information that it has obtained in the\ncourse of its investigations. The Commission has concluded that Russian armed forces\nperpetrated or likely perpetrated most of the attacks investigated, that struck areas which were\nunder Ukrainian Government control.\ni)    Indiscriminate attacks"},{"id":"a-hrc-52-crp-4-p0130","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"130","seq":131,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The majority of the attacks documented have been found to be indiscriminate. They\nhave impacted civilians or civilian objects, including residential buildings, hospitals, schools,\na hotel, shops, a theatre, a pharmacy, a kindergarten, and a train station. At times, a military\ntarget could not be identified in the area of the attack. Where a military target could be\nidentified, the attacking party employed explosive weapons which are unguided, or\ninaccurate, or are designed to strike a wide area, such as bombs dropped during airstrikes,\nmissiles, cluster munitions, and artillery rockets, in populated areas which were controlled\nby Ukrainian armed forces at the time of the attacks."},{"id":"a-hrc-52-crp-4-p0131","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"131","seq":132,"section":"3. Unlawful attacks with the use of explosive weapons","text":"As described above, indiscriminate attacks are those which are not directed at a\nspecific military objective and those which employ a method or means of combat which\ncannot be directed at a specific military objective or the effects of which cannot be limited as\nrequired by international humanitarian law. Consequently, they are of a nature to strike\nmilitary objectives and civilians or civilian objects without distinction. 206"},{"id":"a-hrc-52-crp-4-p0132","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"132","seq":133,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In each case, the Commission has attempted to identify a potential military target in\nthe vicinity of the impact sites of the attacks.207 Such targets included, for example, military\nbases or deployments of military personnel or equipment, or other objects of military value.\nWhile the Commission has found military objectives in some of the attacks it has examined,\nit did not identify possible military targets in all the situations."},{"id":"a-hrc-52-crp-4-p0133","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"133","seq":134,"section":"3. Unlawful attacks with the use of explosive weapons","text":"For example, in the case of the 9 March 2022 attack that struck the Mariupol Primary\nand Sanitation Aid Centre No. 3, often referred to as Maternity Ward No. 3, the Commission\nfound that the hospital was functioning at the time of the attack and did not find any military\ntarget in its vicinity. In the case of an attack carried out on 17 March 2022 that struck a\nresidential area in Chernihiv city, which comprised the Chernihiv Regional Children’s\nHospital, and killed and injured several civilians, the Commission did not find evidence of\nmilitary targets in the area. Regarding the abovementioned January 2023 missile attack on a\nresidential building in Dnipro city, the Commission also did not identify a military target near\nthe impact site of the attack."},{"id":"a-hrc-52-crp-4-p0134","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"134","seq":135,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In situations in which a military objective could be identified in the general area of\nthe attacks, the Commission has nevertheless found that the attacking party used weapons\nthat were too powerful to limit their effects, as required, or inaccurate or designed to cover a\nlarge area. When used in populated areas, such weapons are likely to strike military objectives\nand civilian objects without distinction, and therefore to inflict considerable damage. It has\nidentified three types of weapons that were used in the attacks it has documented."},{"id":"a-hrc-52-crp-4-p0135","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"135","seq":136,"section":"3. Unlawful attacks with the use of explosive weapons","text":"For some of the attacks with the highest civilian casualties, the Commission has\nconcluded that the weapons employed had the characteristics of long-range anti-ship Kh-22\nor Kh-32 missiles, which are launched from aircraft. Experience shows that, fired in pairs or\nmore at the same target, these types of missiles appear as particularly inaccurate against\ntargets on land. In some situations, missiles presumably intended to strike the same target\nlanded several hundred meters apart. For example, the Commission has documented the 1\nJuly 2022 attack in which two missiles struck the town of Serhiivka, in Odesa region, and\ndestroyed both a hotel and a nine-story residential building, killing 22 civilians."},{"id":"a-hrc-52-crp-4-p0136","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"136","seq":137,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In several other attacks, the weapons used were air-dropped unguided high-explosive\nbombs. While in some cases they appear to have hit their targets, they often also appear to\nmiss. In addition, they cause a large zone of blast and fragmentation that may inflict damage\nto civilian objects and military objectives without distinction. In one example, on 3 March\n2022, an aircraft dropped multiple unguided high-explosive bombs on an intersection in\nChernihiv city, possibly targeting a small checkpoint staffed by Ukrainian Territorial\nDefence Forces at that location. However, the bombs fell in an area of 130 m in diameter\naround the intersection, killing at least 15 people, and injuring dozens of civilians."},{"id":"a-hrc-52-crp-4-p0137","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"137","seq":138,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Finally, the Commission has also documented attacks carried out with cluster\nmunitions and multiple launch rocket systems. These weapons are intended to attack an area\nand are therefore inherently indiscriminate when used in areas with a civilian population. For\ninstance, in the case of the April 2022 attack on Kramatorsk train station, the Commission\nfound that a train with Ukrainian military equipment, which could have been the likely target,\nwas stationed there more than one hour before the attack. However, the attack perpetrated\nwith cluster munitions impacted an area with a large concentration of civilians hoping to\nevacuate, reaching beyond a possible military target, and killed dozens."},{"id":"a-hrc-52-crp-4-p0138","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"138","seq":139,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has concluded that Russian armed forces have committed, and in\nsome cases are likely to have committed, indiscriminate attacks, in violation of international\nhumanitarian law.208 The many examples of attacks impacting civilians and civilian objects,\nwith explosive weapons that cannot be directed at a specific military objective, or the effects\nof which cannot be limited, show a pattern of disregard for the requirement to maintain the\ndistinction between military objectives and civilians.\nii)     Disproportionate attacks and lack of feasible precautions"},{"id":"a-hrc-52-crp-4-p0139","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"139","seq":140,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has assessed whether the attacking party took requisite feasible\nprecautions to minimize civilian harm. However, some of the attacks were initiated regardless\nof the presence of large numbers of civilians or objects with special protection, which caused\nexcessive harm and damage. In some cases, dozens or even hundreds of civilians were present\nat or near the presumed target at the time of the attack. In other cases, the attacks impacted\nwell known civilian objects. The Commission found that some of the attacks were\ndisproportionate in relation to a possible military advantage."},{"id":"a-hrc-52-crp-4-p0140","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"140","seq":141,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Under international humanitarian law, those who plan or decide upon an attack must,\namong other things, do everything feasible to verify that the objectives to be attacked are\nneither civilians nor civilian objects, but are military objectives. Further, they should take all\nfeasible precautions in the choice of means and methods of attack with a view to avoiding or\nminimizing incidental loss of civilian life, injury to civilians and damage to civilian objects.\nThey should refrain from launching any attack which may be expected to cause such harm to\ncivilians, damage to civilian objects, or a combination thereof, which would be excessive in\nrelation to the concrete and direct military advantage anticipated. Precautions also include\neffective advance warning of an attack which may affect a civilian population, unless\ncircumstances do not permit it.209"},{"id":"a-hrc-52-crp-4-p0141","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"141","seq":142,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In several cases, attacks struck places with large concentrations of civilians. For\ninstance, in March 2022, several hundreds of civilians were sheltering in the Drama Theatre\nin Mariupol, at the time it came under attack, as the theatre had become one of the gathering\npoints for attempts to evacuate civilians from Mariupol. Similarly, in April 2022, at the time\nof the attack on the Kramatorsk train station, a very large crowd of people had gathered there\nwith the hope to evacuate. These attacks have caused an excessive harm to civilians in\nrelation to a possible military advantage and the Commission has found them to be\ndisproportionate. The party launching the attacks had the obligation to take feasible\nprecautions and refrain from launching them."},{"id":"a-hrc-52-crp-4-p0142","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"142","seq":143,"section":"3. Unlawful attacks with the use of explosive weapons","text":"There are also examples of attacks which struck functioning medical facilities. This\nwas the case of the 9 March 2022 attack against Maternity Ward No. 3 in Mariupol, in which\nat least one pregnant woman and her unborn child were killed; and of the 1 March, 6 March,\nand 7 March 2022 strikes on the Izium Central City Hospital. Hospitals have special\nprotection under international humanitarian law.210 The party conducting these attacks had\nthe prior obligation to take feasible precautions and verify whether the objective of the attack\nwas civilian and if it had a protected status."},{"id":"a-hrc-52-crp-4-p0143","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"143","seq":144,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has therefore concluded that in some cases, Russian armed forces\nhave committed or likely committed attacks which were disproportionate in relation to a\npossible military advantage, in violation of international humanitarian law. It has found that\nseveral of the attacks were initiated with an apparent disregard for the presence of large\nconcentrations of civilians or objects with special protection under international humanitarian\nlaw, which caused excessive harm and damage. It also found that in several cases, the\nattacking party failed to take feasible precautions to verify whether the objectives were\ncivilian or benefitted from special protection."},{"id":"a-hrc-52-crp-4-p0144","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"144","seq":145,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Finally, in addition to the indiscriminate attacks in Mariupol, which are violations of\ninternational humanitarian law, the Commission is investigating whether the Russian armed\nforces’ attacks and siege of the city from February to May 2022 may also amount to a crime\nagainst humanity.211 As described above, the Commission reviewed photos, videos and\nsatellite imagery of destroyed buildings in Mariupol for that time period and interviewed over\n30 civilians from the city. The witnesses reported, among other things, frequent and intensive\nbombardment and lack of basic services such as water, gas and electricity during the siege\n(see paras. 122-124). As the Commission has not had access to the Donetsk region including\nMariupol, and the relevant events took place in an extended period of time in a complex\nsituation of urban warfare, it lacks the basis to make a determination of crimes against\nhumanity, but recommends that this be further investigated given indications that such crimes\nmay have taken place.\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0145","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"145","seq":146,"section":"3. Unlawful attacks with the use of explosive weapons","text":"As stated above, the Commission has found a pattern of indiscriminate attacks\nlaunched or likely launched by Russian armed forces with explosive weapons in populated\nareas. Of those, some were also disproportionate. Below, the Commission will outline\nillustrations of the main cases it has documented. For each case, it has sought to determine\nthe general context of the attacks, whether civilians or civilian objects were affected, the\npotential presence of military objectives at or near the impact sites, the weapons system used,\nwhether feasible precautions were taken, and which party was responsible.\nAttacks with anti-ship missiles"},{"id":"a-hrc-52-crp-4-p0146","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"146","seq":147,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has investigated three attacks which were likely carried out with\npowerful and inaccurate long-range anti-ship missiles of the Kh-22 or Kh-32 type212 in\ndensely populated areas in Dnipro and Kremenchuk cities and in the town of Serhiivka. It\nhas also reviewed videos apparently showing attacks with the use of such missiles in\npopulated areas in two other locations."},{"id":"a-hrc-52-crp-4-p0147","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"147","seq":148,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Kh-22 or Kh-32 missiles have been assessed as inaccurate, particularly when used\nagainst ground targets instead of against aircraft carriers, which they were originally designed\nto attack. The targeting systems of Kh-22 and Kh-32 missiles include a radar which identifies\nand homes in on large objects. In all the attacks that the Commission has examined, which\nwere carried out with missiles bearing the characteristics of Kh-22 or Kh-32 anti-ship\nmissiles, they have impacted large buildings or the vicinity of large buildings."},{"id":"a-hrc-52-crp-4-p0148","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"148","seq":149,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the weapon used in the attacks were likely Kh-\n22 or Kh-32 missiles based on analysis of video footage and photos of weapon remnants. The\ndocumented attacks carried out with such missiles led to a large number of civilian casualties\nand significant destruction. In combination with other relevant factors, the Commission has\nconcluded that these attacks were indiscriminate, in violation of international humanitarian\nlaw.213"},{"id":"a-hrc-52-crp-4-p0149","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"149","seq":150,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Open-source information indicates that at the time of the investigated attacks, the\nRussian armed forces unit which was deployed closest to the Ukrainian border and had the\nmeans to deliver an attack with Kh-22 or Kh-32 type missiles, was the 52nd Heavy Bomber\nLong-Range Aviation Regiment located at the Shaykovka airbase in the Kaluga region, in\nthe Russian Federation."},{"id":"a-hrc-52-crp-4-p0150","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"150","seq":151,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has reviewed satellite imagery which shows multiple objects with\nthe characteristic shape of Kh-22 or Kh-32 missiles at the Shaykovka airbase, in the Russian\nFederation, in late June 2022, the time period when two of the attacks described below took\nplace. A comparison with imagery from different days shows that several of these objects\nwere being moved around the airbase and some appear missing after the attacks."},{"id":"a-hrc-52-crp-4-p0151","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"151","seq":152,"section":"3. Unlawful attacks with the use of explosive weapons","text":"For example, objects with the shape of a Kh-22 or Kh-32 missile can be seen on the\nairfield next to several aircraft on 13, 23 and 25 June 2022. In imagery from 28 June 2022,\nhowever, the day after Kh-22 or Kh-32 missiles struck the city of Kremenchuk, some of the\nobjects are no longer visible. Imagery from just before and after the 1 July 2022 attack on the\ntown of Serhiivka shows similar reduction of visible missiles. Cloud cover did not allow for\na similar analysis in connection with the attack in Dnipro. Based on these elements, it is likely\nthat the 52nd Regiment carried out at least the attacks in Kremenchuk and Serhiivka\ndescribed below.214\nKremenchuk city, Poltava region, 27 June 2022"},{"id":"a-hrc-52-crp-4-p0152","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"152","seq":153,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 27 June 2022, in the afternoon, two missiles struck the centre of Kremenchuk city,\nPoltava region. One missile impacted a shopping mall, causing a fire, and another missile\nstruck about 500 m away, on the compound of the Kredmash road machinery factory.\nAccording to local authorities, 21 civilians, including 11 women and 10 men, were killed,\nand dozens were injured."},{"id":"a-hrc-52-crp-4-p0153","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"153","seq":154,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, Kremenchuk was 180 km from the frontline. The\nKremenchuk Oil Refinery, located in the outskirts of the city, was repeatedly attacked with\nmissiles in April, May, and June 2022.215"},{"id":"a-hrc-52-crp-4-p0154","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"154","seq":155,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the weapons used in the attack had the\ncharacteristics of Kh-22 or Kh-32 missiles. 216 Footage from two separate security\nsurveillance cameras posted online, each show a missile in flight just before impact. Their\ndistinctive shape and trajectory in the security surveillance footage, as well as their\ncharacteristics in photos of weapon remnants and videos obtained after the attack, are\nconsistent with the known characteristics of the Kh-22 or Kh-32 missiles. The Commission\nhas also geolocated the impact sites of the missiles, which are about 500 m apart,\ndemonstrating the inaccurate nature of this weapon."},{"id":"a-hrc-52-crp-4-p0155","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"155","seq":156,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Russian authorities acknowledged that they had attacked the road machinery factory\nin Kremenchuk, but claimed that they had targeted a hangar storing weapons and ammunition\nwith high-precision air-based weapons and that the detonation of the ammunition caused a\nfire which spread to a “non-functioning” shopping mall next to the factory.217 The\nCommission has found no evidence to support the claim that ammunition and weapons were\nstored in the area. Witness accounts and videos of the immediate aftermath do not suggest\npossible secondary explosions or weapon remnants, which would have been consistent with\ndetonation of arms or ammunition."},{"id":"a-hrc-52-crp-4-p0156","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"156","seq":157,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Evidence from the immediate aftermath of the attack indicates that the shopping mall\nwas operational at the time of the attack. The Commission has established that the damage to\nthe shopping mall and the civilian casualties were caused by a direct hit on the building, and\nnot by fire spreading from elsewhere. Security surveillance footage of the strike and satellite\nimagery indicate that one missile hit the north-eastern corner of the shopping mall, about 50\nm from the factory compound."},{"id":"a-hrc-52-crp-4-p0157","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"157","seq":158,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The factual circumstances of the attack show that an inaccurate missile was used in a\npopulated area, and that it struck a functional shopping mall, causing numerous civilian\ncasualties and damage to a civilian object. Russian authorities have acknowledged that they\nperpetrated an attack in the area. The Commission has therefore concluded that Russian\narmed forces carried out an indiscriminate attack in Kremenchuk on 27 June 2022 and failed\nto take feasible precautions such as verifying the objective to be attacked and regarding the\nchoice of means and methods of attack. These are violations of international humanitarian\nlaw.218\nSerhiivka town, Odesa region, 1 July 2022"},{"id":"a-hrc-52-crp-4-p0158","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"158","seq":159,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 1 July 2022, after midnight, a missile struck the town of Serhiivka and destroyed\nthe Godji hotel. Another missile struck about 230 m north of the hotel, next to a nine-story\nresidential building, which it destroyed. The Commission has obtained the personal data of\n22 civilians killed in the attack: 13 women, eight men, and a 12-year-old boy. Dozens of\npeople, including six children, were injured."},{"id":"a-hrc-52-crp-4-p0159","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"159","seq":160,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, the frontline was located about 100 km from Serhiivka, a\ntown on the Black Sea. Russian armed forces appear to have been carrying out attacks along\nthe coast during that period, including an attack the same day, about 70 km away. The day\n215 See “Russian forces again attack Ukraine’s biggest oil refinery in Kremenchuk”, The Kyiv\nIndependent, 12 May 2022; Ukrinform, “Russians launch missile strike on Kremenchuk oil refinery”,\n18 June, 2022.\n216 The Kh-32 missile is a physically similar upgraded variant of the Kh-22 missile.\n217 Ministry of Defence of the Russian Federation, “Report on the progress of the special military\noperation in Ukraine”, 28 June 2022. “Telegram message available only in Russian)\nbefore, Russian armed forces announced the withdrawal from Zmiinyi Island, which is about\n85 km from Serhiivka.219"},{"id":"a-hrc-52-crp-4-p0160","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"160","seq":161,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission reviewed images of weapon remnants and the damage at the impact\nsite and found them to be consistent with the known characteristics of the Kh-22 or Kh-32\nmissiles. Ukrainian authorities have informed the Commission that six Kh-22 missiles were\nlaunched in the attack that struck Serhiivka."},{"id":"a-hrc-52-crp-4-p0161","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"161","seq":162,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The missile impacted a populated area. The Commission has not identified any\npotential military targets in the immediate vicinity of the impact sites. There appears to be a\nUkrainian military base, located about 3.5 km north-east of the impact site. However, satellite\nimagery from before and after 1 July 2022 does not show any damage to or near the site of\nthis military base."},{"id":"a-hrc-52-crp-4-p0162","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"162","seq":163,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In relation to the attack, Dmitry Peskov, Press Secretary of President Putin, did not\nexplicitly deny responsibility, but stated that Russian armed forces “do not attack civilian\ntargets”, only “military ammunition storages, factories that produce and repair equipment,\nammunition storage, places for the training of mercenaries.”220"},{"id":"a-hrc-52-crp-4-p0163","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"163","seq":164,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the strike, the likely identification of the weapons as Kh-22\nor Kh-32 missiles, and their use in a populated area, causing numerous civilian casualties,\nthe Commission has concluded that Russian armed forces likely carried out an indiscriminate\nattack with inaccurate and powerful missiles in Serhiivka on 1 July 2022, and failed to take\nfeasible precautions such as verifying the objective to be attacked and regarding the choice\nof means and methods of attack. These are violations of international humanitarian law. 221\nDnipro city, Dnipropetrovsk region, 14 January 2023"},{"id":"a-hrc-52-crp-4-p0164","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"164","seq":165,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 14 January 2023, in the afternoon, a missile struck a residential building at\nNaberezhnaya Peremoha Street 118, in Dnipro city, causing a significant part of it to collapse.\nAccording to local authorities, at least 44 people, including six children, were killed, and at\nleast 81 were injured."},{"id":"a-hrc-52-crp-4-p0165","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"165","seq":166,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, the frontline was located about 100 km from Dnipro. In\nDnipro, missiles appear to have struck the Prydniprovska Thermal Power Plant on four\nprevious occasions during waves of Russian attacks against energy installations across the\ncountry. The power plant is located about four kilometres from the apartment building that\nwas hit."},{"id":"a-hrc-52-crp-4-p0166","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"166","seq":167,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the weapon used in the attack had the\ncharacteristics of Kh-22 or Kh-32 missiles. One video from the attack shows that the missile\nstruck the building at a steep angle, a typical characteristic of the Kh-22 or Kh-32 missile.\nPhotos of the weapon remnants found at the impact sites and the damage from the attack are\nconsistent with the known characteristics of the Kh-22 or Kh-32 missiles."},{"id":"a-hrc-52-crp-4-p0167","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"167","seq":168,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The missile struck a populated area. The Commission has not identified any obvious\nmilitary targets in the immediate vicinity of the impact site. The apartment building was hit\nin the context of a massive missile attack by Russian armed forces against Ukraine’s “military\ncommand and control system and associated energy facilities” on 14 January 2023, as\nreported by the Russian Ministry of Defence.222 The Ukrainian Air Force Command reported\nthat 38 missiles had been fired against targets in Ukraine on that day, out of which 25 had\nbeen intercepted."},{"id":"a-hrc-52-crp-4-p0168","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"168","seq":169,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has considered whether attempts to intercept the missile by\nUkrainian Air Defence Forces caused it to fall on the residential building, as claimed by an\n219 Ministry of Defence of the Russian Federation, “Summary of the Ministry of Defence of the Russian\nFederation on the progress of the special military operation on the territory of Ukraine”, 30 June\n2022. (available only in Russian)\nexternal adviser to the President of Ukraine in the immediate aftermath.223 Proponents of this\ntheory pointed to allegations of two explosions and the potential presence of more than one\nimpact site near the apartment building. The Commission has not found evidence to support\nthis theory. Witnesses interviewed heard only one explosion, and local residents verified that\nthere was only one impact site in the immediate vicinity of the apartment building. The flight\nof the missile, as seen on a video obtained by the Commission, does not appear to show an\ninterference in the trajectory of the missile."},{"id":"a-hrc-52-crp-4-p0169","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"169","seq":170,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In the aftermath, the Press Secretary of the Russian President stated that Russian\narmed forces do not attack residential buildings and social infrastructure, but only military\ntargets. He also referred to the abovementioned allegations that the missile hit the building\ndue to Ukrainian air defence, seemingly not excluding that the missile was Russian. 224"},{"id":"a-hrc-52-crp-4-p0170","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"170","seq":171,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the strike, the likely identification of the weapon as a Kh-22\nor Kh-32 missile, its use in a populated area, causing numerous civilian casualties and\ndamage to a civilian object, the Commission has concluded that Russian armed forces likely\ncarried out an indiscriminate attack with inaccurate and powerful missiles in Dnipro on 14\nJanuary 2023, and failed to take feasible precautions such as verifying the objective to be\nattacked and regarding the choice of means and methods of attack. These are violations of\ninternational humanitarian law.225\nAttacks with bombs dropped from aircraft"},{"id":"a-hrc-52-crp-4-p0171","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"171","seq":172,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has investigated several attacks carried out or likely carried out with\nair-dropped bombs in populated areas. The attacks described below took place in the cities\nof Chernihiv, Izium, Mariupol, and Sumy. These attacks led to a large number of civilian\ncasualties and significant destruction. Witnesses described how they saw or heard an airplane\nflying above the area at the time of the attack. In one case, video footage showed several\nprojectiles falling in a line and in close succession, a pattern indicative of an attack with\nunguided air-dropped bombs. The damage at the impact sites was also consistent with the use\nof air-dropped bombs. The Commission has concluded that the five attacks described below\nwere unlawful.\nChernihiv city, Chernihiv region, 3 March 2022\nFirst airstrike"},{"id":"a-hrc-52-crp-4-p0172","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"172","seq":173,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 3 March 2022, at around 12.15 p.m., two airstrikes with multiple munitions struck\nthe centre of Chernihiv city. One of the two strikes impacted a residential area near the\nintersection of Chernovola and Kruhova streets, significantly damaging three multi-story\nresidential buildings, a pharmacy, and the Chernihiv Regional Cardiac Centre. The\nCommission observed the damage during its visit to the area. It has obtained a list of 15\npeople who were killed in the attack (seven men and eight women); the total number is likely\nhigher. Dozens were injured."},{"id":"a-hrc-52-crp-4-p0173","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"173","seq":174,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At that time, Russian armed forces were launching numerous attacks against the city\nuntil the end of March 2022. They surrounded the city as they attempted to take control of it.\nA spokesperson for the Russian Ministry of Defence declared that Russian armed forces had\nimposed a blockade on the city on 25 February 2022.226"},{"id":"a-hrc-52-crp-4-p0174","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"174","seq":175,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was an airstrike. Several witnesses\nsaid that they heard an airplane before the attack and one witness located at a distance said\nshe saw the plane fly low over the houses after the attack. A video of the attack analysed by\nthe Commission shows several projectiles falling towards the intersection in a line and in\nclose succession, a pattern indicative of an attack with unguided air-dropped bombs. The\ndamage to buildings and impact craters are consistent with the use of such bombs.\n223 The external adviser to the President of Ukraine subsequently said that his claim was based on\ninformation from an individual in Dnipro with knowledge of anti-aircraft systems who said that he\nheard two explosions, one of which sounded like an anti-aircraft weapon.\n224 Rosbalt, “Peskov did not see the conflict between the Ministry of Defence and the Wagner PMC,\nSevastopol is being attacked by drones, Ukraine has become a \"weapons laboratory\" of the United\nStates”, 16 January 2023. (available only in Russian)\n225 Additional Protocol I to the Geneva Conventions, articles 51(4)-(5) and 57(2).\n226 Ministry of Defence of the Russian Federation, “Briefing by the official representative of the\nRussian ministry of Defence”, 25 February 2022. (available only in Russian)"},{"id":"a-hrc-52-crp-4-p0175","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"175","seq":176,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack impacted a populated area. The Commission has found that there was likely\nsome Ukrainian military presence in the vicinity at the time of the attack. Witnesses reported\nthat there was a checkpoint at the intersection, which was staffed by members of the\nUkrainian Territorial Defence Forces, as well as a small presence of Territorial Defence\nForces in the area."},{"id":"a-hrc-52-crp-4-p0176","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"176","seq":177,"section":"3. Unlawful attacks with the use of explosive weapons","text":"However, at the time of the attack, a large number of civilians were gathered on the\nstreets nearby, queuing for bread and in front of a pharmacy, where people had to wait outside\ndue to COVID-19 restrictions. There were also several medical institutions in the immediate\nvicinity. Given the nature of the populated urban area, Russian armed forces should have\nknown or assumed that a large number of civilians could have been in the area and should\nhave taken feasible precautions to verify their presence and to avoid harming them."},{"id":"a-hrc-52-crp-4-p0177","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"177","seq":178,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack and the use of multiple unguided munitions in a\npopulated area, where a significant number of civilians were present, causing numerous\ncivilian casualties and damage to civilian objects, the Commission has concluded that\nRussian armed forces conducted an indiscriminate, disproportionate attack in the area of the\nChornovola and Kruhova streets intersection in Chernihiv city on 3 March 2022 and failed\nto take feasible precautions such as the choice of means and methods of attack with a view\nto minimize civilian harm. These are violations of international humanitarian law. 227\nSecond airstrike"},{"id":"a-hrc-52-crp-4-p0178","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"178","seq":179,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At about the same time as the attack described above, another attack struck the Stara\nPodusivka district of Chernihiv, about two kilometres away, and severely damaged two\nschools and several houses in a residential area. The Commission has found that six civilians,\nincluding a 14-year-old boy, were killed in the residential area, and that several people were\nkilled in the schools, the latter including some members of the Territorial Defence Forces."},{"id":"a-hrc-52-crp-4-p0179","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"179","seq":180,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was an airstrike, based on the\nextensive damage and on accounts from witnesses that they heard an aircraft flying above."},{"id":"a-hrc-52-crp-4-p0180","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"180","seq":181,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Several local residents interviewed by the Commission reported military presence at\nthe two schools. School 18, in particular, appeared to function as a gathering point for the\nUkrainian Territorial Defence Forces and local residents reported that several among their\nmembers were killed there during the attack. This is consistent with the Commission’s own\nobservations. During its visit, the Commission observed several improvised defence\npositions made of sandbags and tires along the perimeter of that school. Residents also said\nthat volunteers were cooking and gathering items for Ukrainian Territorial Defence Forces\nat School 21 and that at times a significant number of armed personnel gathered there.\nFinally, obituaries posted on the internet confirm that several members of Territorial Defence\nForces were killed at the two schools during the attack (see para. 286)."},{"id":"a-hrc-52-crp-4-p0181","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"181","seq":182,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has, however, not found any evidence of military presence in the\nresidential area north of School 21 that was also struck. At least two bombs fell in this area,\nabout 100-200 m from the school. This distance is similar to the distance between bombs that\nfell in the abovementioned attack on Chernihiv carried out on the same day, which\ndemonstrates how inaccurate unguided air-dropped bombs can be."},{"id":"a-hrc-52-crp-4-p0182","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"182","seq":183,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has also considered if Russian armed forces did everything feasible\nto verify whether there were civilians present in the schools that were attacked. Local\nresidents said that people from the neighbourhood had started using School 21 as a bomb\nshelter on 25 February 2022 and that they had written “children” in large letters above the\nentrance to the school to indicate that there were civilians there. They said that civilians were\ncoming and going to the school every day and that, by one estimate, up to 200 persons were\nsheltering on the ground floor and in the basement of the school at the time of the attack. The\nCommission believes that a proper assessment of whether civilians were present should have\nalerted the Russian armed forces to the presence of a large group of civilians at school 21 and\nthat they should have refrained from attacking it."},{"id":"a-hrc-52-crp-4-p0183","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"183","seq":184,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack and the use of multiple unguided munitions in a\npopulated area, where a significant number of civilians were present, causing numerous\ncivilian casualties and damage to civilian objects, the Commission has concluded that\n227 Additional Protocol I to the Geneva Conventions, articles 51(4)-(5) and 57(2).\nRussian armed forces conducted an indiscriminate attack in a densely populated area in the\nStara Podusivka district of Chernihiv city on 3 March 2022 and failed to take feasible\nprecautions such as the choice of means and methods of attack with a view to minimize\ncivilian harm. These are violations of international humanitarian law. 228\nSumy city, Sumy region, 7 March 2022"},{"id":"a-hrc-52-crp-4-p0184","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"184","seq":185,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 7 March 2022, in the late evening, an attack struck a residential area between\nRomenska and Spartak streets, in Sumy city, completely destroyed six houses, and damaged\nresidential buildings in at least five neighbouring streets. The Commission has obtained a list\nof 14 persons, comprising seven women, three men and four boys, who were killed in the\nattack.229"},{"id":"a-hrc-52-crp-4-p0185","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"185","seq":186,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, Russian armed forces were attempting to take the city and\nhad encircled it."},{"id":"a-hrc-52-crp-4-p0186","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"186","seq":187,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that that attack was carried out with unguided air-\ndropped bombs, based on witness accounts of the sound of an aircraft flying above,\nexamination of weapon remnants, and the damage on the ground. During an inspection of the\narea, the Commission identified two large impact sites, located about 50 m apart. The\nCommission has received credible information that an aircraft, possibly the same that\nattacked the residential area, attacked two other sites further north shortly after the attack on\nthe residential area. The damage to these sites also appears to be consistent with air-dropped\nbombs. This is consistent with information from the Ukrainian authorities that they detected\nand tracked “airborne targets” crossing the airspace from Russia to Ukraine in the direction\nof Sumy around 10.31 p.m. on 7 March 2022."},{"id":"a-hrc-52-crp-4-p0187","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"187","seq":188,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack impacted a populated area. The Commission has not been able to identify\nany likely military targets in the immediate vicinity. According to residents, a mobilization\noffice was located about 350 m from the impact sites, but it was not in use at the time of the\nattack."},{"id":"a-hrc-52-crp-4-p0188","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"188","seq":189,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack, the use of unguided munitions in a populated area,\ncausing numerous civilian casualties and damage to civilian objects, the Commission has\nconcluded that Russian armed forces conducted an indiscriminate attack with air-dropped\nunguided bombs in Sumy city on 7 March 2022, and failed to take feasible precautions such\nas the choice of means and methods of attack with a view to minimize civilian harm. These\nare violations of international humanitarian law.230\nIzium city, Kharkiv region, 9 March 2022"},{"id":"a-hrc-52-crp-4-p0189","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"189","seq":190,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In the morning of 9 March 2022, an attack struck two residential buildings at\nPershotravneva Street 2 and Khlibozavodska Street 3 in Izium city and killed more than 50\npersons who were sheltering in their basements. During a visit to the area, the Commission\nobserved that the midsections of two six-story apartment buildings had collapsed."},{"id":"a-hrc-52-crp-4-p0190","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"190","seq":191,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, fighting was ongoing in Izium. Russian armed forces\ncontrolled the left (northern) bank of the Siverskyi Donets river, and Ukrainian armed forces\ncontrolled the right (southern) bank. The two apartment buildings that were hit were located\nnext to a bridge in the Ukrainian-controlled part of the city."},{"id":"a-hrc-52-crp-4-p0191","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"191","seq":192,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was likely carried out with an\nairstrike. One witness recounted that she heard an airplane overhead a few seconds before\nthe explosion. An employee of the State Emergency Services who participated in the recovery\nof the bodies, told the Commission that weapon remnants from a high-explosive unguided\nair-dropped bomb were found among the ruins of the buildings, but that Russian armed forces\nwho subsequently took over the area did not allow them to collect the remnants or to take\nphotos. While the damage observed is consistent with air-dropped munitions, further\ninvestigation is required to conclusively identify the weapon.\n228 Additional Protocol I to the Geneva Conventions, articles 51(4)-(5) and 57(2).\n229 The Commission’s report to the General Assembly on 18 October 2022 (A/77/533) indicated that the\nattack killed 15 people. Further investigation has established that one of the 15 people was killed in an\nairstrike the same night in a different area.\n230 Additional Protocol I to the Geneva Conventions, articles 51(4)-(5) and 57(2)."},{"id":"a-hrc-52-crp-4-p0192","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"192","seq":193,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack impacted a populated area. Residents reported that as heavy fighting broke\nout from across the river in the morning before the attack, they saw Ukrainian soldiers around\nthe apartment block and some of the weapons fire coming from a residential apartment block\nless than 100 m from Khlebozavodska Street 3. Residents of the latter building stated that\nthey sought shelter in the basement of that building and that Ukrainian forces were trying to\nhelp them evacuate when the attack took place. Based on the casualties, it is clear that dozens\nof civilians were also sheltering in Pershotravneva Street 2."},{"id":"a-hrc-52-crp-4-p0193","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"193","seq":194,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Given the circumstances of the attack, including Russian armed forces fighting from\nacross the river, the presence of Ukrainian soldiers in and around the buildings that were hit,\nand the direct impact on the two buildings, the Commission assessed that Russian armed\nforces likely carried out the attack on the two residential buildings. While the Ukrainian\nsoldiers fighting from or near the apartment buildings were legitimate targets, Russian armed\nforces should have known or assumed that there may still have been civilians in the buildings\nand the forces should have taken feasible precautions to minimize harming civilians. The\ninformation currently available to the Commission does not allow it to draw firm conclusions\nwhether, in this situation, Ukrainian armed forces fulfilled its obligations to protect civilians,\nin particular to avoid locating soldiers within or near densely populated areas. 231"},{"id":"a-hrc-52-crp-4-p0194","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"194","seq":195,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack and the use of powerful munitions in a populated\narea, where a significant number of civilians were present, causing numerous civilian\ncasualties and damage to civilian objects, the Commission has concluded that Russian armed\nforces likely conducted an indiscriminate attack with air-dropped bombs in Izium city on 9\nMarch 2022 and failed to take feasible precautions such as the choice of means and methods\nof attack with a view to minimize civilian harm. These are violations of international\nhumanitarian law.232\nMariupol city, Donetsk region, 9 March 2022"},{"id":"a-hrc-52-crp-4-p0195","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"195","seq":196,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 9 March 2022, an attack struck the grounds of the Primary Medical and Sanitary\nAid Centre No. 3, known as Maternity Hospital No. 3, in Mariupol city, significantly\ndamaging the maternity and children’s wing of the hospital. The attack was widely reported\nin local and international media. At least one pregnant woman and her unborn child were\nkilled in the attack."},{"id":"a-hrc-52-crp-4-p0196","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"196","seq":197,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, intense fighting was ongoing in Mariupol. Ukrainian armed\nforces controlled the part of the city where the hospital was situated."},{"id":"a-hrc-52-crp-4-p0197","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"197","seq":198,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was carried out with an airstrike.\nSeveral witnesses told the Commission that they heard an airplane overhead before the\nimpact. The crater in the courtyard and the damage caused in the attack are also consistent\nwith an airstrike."},{"id":"a-hrc-52-crp-4-p0198","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"198","seq":199,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area. In the aftermath of the attack, Russian Government\nofficials claimed that the hospital was not functional and that it was being used for military\npurposes, referring to information from local residents.233 The Commission has not found\nany support for these allegations. Witnesses interviewed confirmed that the hospital was\nfunctioning at that time and added that the oncology building of the hospital, located next to\nthe maternity wing, was at the time used to treat wounded Ukrainian soldiers. It follows from\ninternational humanitarian law that the hospital does not lose its protected status if wounded\nsoldiers are nursed there, nor are wounded soldiers – who are receiving medical treatment\nand no longer taking active part in hostilities (i.e., hors de combat) – legitimate targets.234\nWitnesses said that apart from a few soldiers guarding the oncology department, there was\nno military presence or equipment at the hospital."},{"id":"a-hrc-52-crp-4-p0199","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"199","seq":200,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In his daily briefing on 10 March 2022, a spokesperson for the Russian Ministry of\nDefence said, regarding the strike on Primary Medical and Sanitary Aid Centre No. 3, that\nthe “Russian aviation had no missions of hitting targets on the ground in the Mariupol\narea”.235"},{"id":"a-hrc-52-crp-4-p0200","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"200","seq":201,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack, the use of powerful munitions in a populated area,\ncausing civilian casualties and damage to a civilian object with special protection, the\nCommission has concluded that Russian armed forces conducted an indiscriminate attack on\nthe Primary Medical and Sanitary Aid Centre No. 3, in Mariupol, on 9 March 2022. They\nalso failed to take feasible precautions such as to verify whether the objective was a civilian\nobject subject to special protection. These are violations of international humanitarian law. 236\nMariupol city, Donetsk region, 16 March 2022"},{"id":"a-hrc-52-crp-4-p0201","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"201","seq":202,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 16 March 2022, in the morning, an attack struck the Donetsk Academic Regional\nDrama Theatre in Mariupol city, significantly damaging large sections of the building. The\nattack was widely reported in local and international media. Reports about the number of\ncasualties vary widely. Initial reports suggested that several hundreds of people were killed."},{"id":"a-hrc-52-crp-4-p0202","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"202","seq":203,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At that time, intense fighting was ongoing in Mariupol. Ukrainian armed forces\ncontrolled the area of the city where the theatre was situated."},{"id":"a-hrc-52-crp-4-p0203","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"203","seq":204,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was carried out with at least one high-\nexplosive bomb delivered from an aircraft. Several witnesses confirmed hearing or seeing\nairplanes just before or at the time of the attack on the theatre. The damage to the theatre is\nconsistent with the use of air-dropped bombs."},{"id":"a-hrc-52-crp-4-p0204","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"204","seq":205,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area. Several hundred civilians were sheltering in the\ntheatre at the time of the attack, as it was one of the gathering points for attempts to evacuate\ncivilians from Mariupol and planned evacuations were postponed. Witnesses estimate that\non the day of the attack, there were 500 to 600 civilians in all parts of the building. Satellite\nimagery shows that the word “children” had been written in large letters on the ground in\nfront of the theatre to signal their presence there."},{"id":"a-hrc-52-crp-4-p0205","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"205","seq":206,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In the aftermath of the attack, Russian Government officials claimed that the Azov\nbattalion had used the upper floors as firing positions, holding civilians hostage. While some\nwitnesses said that they occasionally saw a few Ukrainian soldiers around the theatre, the\nCommission has found no evidence of significant military presence there. Moreover, with\nhundreds of civilians in the building, the presence of a few soldiers should not have led to\nthose planning or deciding upon the attack to consider it to be a proportionate attack. Rather,\nthe expected incidental civilian harm would be excessive in relation to the concrete and direct\nmilitary advantage anticipated.237"},{"id":"a-hrc-52-crp-4-p0206","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"206","seq":207,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has considered whether the attack was intended to strike another\ntarget. It has collected information suggesting that Ukrainian armed forces were present in\nbuildings about 150 m from the theatre and that they were conducting attacks from those\nlocations. Nevertheless, the theatre is set apart from other buildings by roads, parking spaces,\nand a park. Because of this and since the air strike impacted the theatre directly, landing in\nthe middle of the building, the Commission has found it most likely that the theatre was the\nintended target of the attack."},{"id":"a-hrc-52-crp-4-p0207","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"207","seq":208,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack, the use of powerful munitions in a populated area,\nwhere a significant number of civilians were present, causing numerous civilian casualties\nand damage to a civilian object, the Commission has concluded that Russian armed forces\nconducted an indiscriminate, disproportionate attack that struck the Mariupol Drama Theatre\non 9 March 2022 and failed to take feasible precautions such as the choice of means and\nmethods of attack with a view to minimize civilian harm. These are violations of international\nhumanitarian law.238\n235 Ministry of Defence of the Russian Federation, “Briefing by Russian Defence Ministry”, 10 March\n2022. (Telegram message available only in Russian).\nAttacks with cluster munitions"},{"id":"a-hrc-52-crp-4-p0208","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"208","seq":209,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has investigated several attacks carried out with cluster munitions\nin populated areas. The three attacks described below took place in Chernihiv and\nKramatorsk cities and Okhtyrka town, and they led to civilian casualties and destruction of\ncivilian objects. Cluster munitions are inherently indiscriminate when used in populated\nareas. During its inspection of impact sites, the Commission noted small craters with\nsurrounding scatter patterns consistent with the use of cluster munitions. The descriptions\nprovided by witnesses, of multiple small explosions, are also consistent which the type of\nexplosions created by cluster munitions. In two of the cases described below, the Commission\nhas concluded that Russian armed forces were responsible for the attacks, which were\nindiscriminate.\nOkhtyrka town, Sumy region, 25 February 2022"},{"id":"a-hrc-52-crp-4-p0209","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"209","seq":210,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 25 February 2022, an attack struck a residential area and Sonechko Kindergarten\nin Okhtyrka city, Sumy region. The Commission has gathered the names of five persons, four\nmen and one woman, who were killed in the attack; furthermore, at least three victims were\ninjured, including an eight-year-old boy."},{"id":"a-hrc-52-crp-4-p0210","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"210","seq":211,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, there was heavy fighting between Russian and Ukrainian\narmed forces for control of the city. While Russian armed forces had managed to reach its\ncentre, and an area close to the kindergarten the day before, Ukrainian armed forces had\nrepelled the attack and remained in control on 25 February. The area that came under attack\nwas therefore controlled by Ukrainian armed forces at the time."},{"id":"a-hrc-52-crp-4-p0211","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"211","seq":212,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was carried out with cluster\nmunitions. During its visit to the area, it observed small impact craters with surrounding\nscatter patterns consistent with the use of cluster munitions in the asphalt. Photos that were\nposted on the Internet, and that the Commission geolocated, show the cargo section of a 220-\nmm Uragan (“Hurricane”) cluster munition rocket stuck in the ground about 200 m from the\nkindergarten. This is also consistent with witness accounts."},{"id":"a-hrc-52-crp-4-p0212","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"212","seq":213,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area. Although the kindergarten was not operational on\n25 February 2022, civilians were using its basement as a shelter. The Commission has\nidentified two possible military targets in the vicinity of the kindergarten but has not been\nable to verify whether the cluster munition attack affected either of these locations. The\nheadquarters of the 91st Separate Operations Support Regiment of the Ukrainian armed\nforces was located about 600 m to the east-southeast of the kindergarten. An attack on this\nfacility on the following day resulted in the reported death of 70 servicemen of the Ukrainian\narmed forces. Another Ukrainian facility, which had been used, at least in the past, to store\nmilitary equipment, was located 300 m to the north-east of the kindergarten."},{"id":"a-hrc-52-crp-4-p0213","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"213","seq":214,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has not been able to conclusively establish who was responsible for\nthe attack. The military situation then prevailing in Okhtyrka and the presence of Ukrainian\nmilitary bases in the vicinity, suggest that these were the likely targets and that Russian armed\nforces were responsible. To the Commission’s knowledge, there were no Russian armed\nforces in the affected area at the time of the attack. The analysis of the angle of a cargo section\nof a cluster munition stuck in the ground nearby indicated that the attack was fired from a\nwest-northwest direction, which had been under the control of the Ukrainian armed forces.\nHowever, multiple reports indicate that Russian armed forces were seen north-west of\nOkhtyrka in the days following the attack, making it possible that they were in the potential\nlaunch area also at the relevant time. Nevertheless, the Commission has not been able to\nestablish with certainty which forces were located in the launch area at the time of the attack."},{"id":"a-hrc-52-crp-4-p0214","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"214","seq":215,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the above, the Commission has concluded that a cluster munition attack took\nplace in Okhtyrka on 25 February 2022 but has not been able to establish who was responsible\nfor the attack.\nChernihiv city, Chernihiv region, 17 March 2022"},{"id":"a-hrc-52-crp-4-p0215","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"215","seq":216,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 17 March 2022, an attack239 struck a residential area in Chernihiv city, including\nthe Chernihiv Regional Children’s Hospital; it killed several civilians and injured dozens."},{"id":"a-hrc-52-crp-4-p0216","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"216","seq":217,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At that time, Russian armed forces were launching numerous attacks against\nChernihiv with a wide range of weapons, until the end of March 2022. The city was under\nUkrainian armed forces control."},{"id":"a-hrc-52-crp-4-p0217","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"217","seq":218,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was carried out using cluster\nmunitions. Witnesses described hearing one explosion in the air and then many small\nexplosions on the ground, which is indicative of a cluster munition attack. During a visit to\nthe area, the Commission documented several impact craters with surrounding scatter\npatterns on hard surfaces around the hospital, and damage to the hospital walls, which are\nconsistent with the use of cluster munitions. Medical staff showed fragments that were found\nafter the attack that are also consistent with characteristics of cluster munitions. The\nCommission reviewed photos and videos of unexploded submunitions and the cluster\nmunition cargo section that had been used in the attack. It has identified these as 220-mm\n9M27K-series Uragan cluster munition rockets. Photographs obtained suggest that at least\nfour such rockets were used."},{"id":"a-hrc-52-crp-4-p0218","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"218","seq":219,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area. The Commission has found no evidence of military\ntargets in that area at the time of the attack. According to medical staff, the hospital was\noperational at that time, with dozens of patients, including eight children in intensive care. In\naddition, about 200 persons, including families and older persons, had sought shelter in the\nhospital. That morning, many civilians were also queueing for water which was being\ndistributed on the grounds of the hospital."},{"id":"a-hrc-52-crp-4-p0219","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"219","seq":220,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has analysed damage from the attack and weapon remnants,\nincluding the damage on the hospital grounds and a cargo section from one of the cluster\nmunition rockets stuck in the ground about 300 meters from the hospital. The available\nevidence suggests that the attack was launch from the south, south-east, or east of the\nhospital. The 9M27K-series Uragan rocket, identified above as the weapon used in the attack,\nhas a range of 10 to 35 km. While the Commission has not been able to exclude the possibility\nthat Ukrainian armed forces were located in some of the potential launch areas, frontline\nreports, satellite imagery, and testimony from local residents show that Russian armed forces\nwere at the time present in areas to the south and east of Chernihiv and within firing range\nwith Uragan rockets from the hospital."},{"id":"a-hrc-52-crp-4-p0220","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"220","seq":221,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Documents left behind by Russian armed forces list the 55th Separate Motorized Rifle\nBrigade, the 74th Separate Guards Motorized Rifle Brigade, and the 228th Motorized Rifle\nRegiment as present in the relevant area. The Commission has collected information about\nthe identity of the commanders of these units."},{"id":"a-hrc-52-crp-4-p0221","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"221","seq":222,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack, the use of cluster munitions in a populated area,\nwhere a significant number of civilians were present, causing numerous civilian casualties\nand damage to civilian objects, the Commission has concluded that Russian armed forces\nlikely conducted an indiscriminate attack in Chernihiv city on 17 March 2022, and failed to\ntake feasible precautions such as the choice of means and methods of attack with a view to\nminimize civilian harm. These are violations of international humanitarian law. 240\nKramatorsk city, Donetsk region, 8 April 2022"},{"id":"a-hrc-52-crp-4-p0222","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"222","seq":223,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In the morning on 8 April 2022, an attack struck the area around the train station in\nKramatorsk city, Donetsk region; it killed 59 persons, namely 38 women, 15 men, 3 girls and\n3 boys, and injured 92 persons."},{"id":"a-hrc-52-crp-4-p0223","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"223","seq":224,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At the time of the attack, the closest frontline between Russian and Ukrainian forces\nran a semi-circle about 60-75 km to the southeast, east, north, and northwest of Kramatorsk."},{"id":"a-hrc-52-crp-4-p0224","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"224","seq":225,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the train station was attacked with cluster\nmunitions. Several witnesses who were present during the attack described multiple small\nexplosions, which are typical of a cluster munition attack. Using available photos and videos,\n239 The Commission reported on this attack in its report to the General Assembly (A/77/533, para. 48). It\nhas since continued the investigation to establish responsibility.\nthe Commission identified eight locations affected by such small explosions around the train\nstation. In two locations, the explosions left a shallow indentation on hard surfaces with a\nsurrounding scarring pattern, characteristics that are indicative of a cluster munition attack.\nPhotos and videos from the aftermath of the attack also show a large missile remnant lying\non a patch of grass in front of the train station. Based on the above, the Commission\ndetermined that the weapon used in the attack had characteristics of a 9M79-1 series Tochka\nU ballistic missile with a 9N123K cluster munition warhead."},{"id":"a-hrc-52-crp-4-p0225","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"225","seq":226,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area. At that time, the train station in Kramatorsk city\nwas teeming with civilians. The State Emergency Service of Ukraine and Ukrainian Railways\nhad been organizing evacuations for civilians from eastern Ukraine, including seven trains\nthe day before the attack. More evacuation trains were expected on the day of the attack. A\nlarge crowd of people had gathered at the train station, hoping to evacuate. They included\nolder persons, people with disabilities, and families with children."},{"id":"a-hrc-52-crp-4-p0226","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"226","seq":227,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has also found that there was a train with military equipment at the\nstation before the attack. Two witnesses, interviewed separately, observed a train with\nmilitary vehicles on the morning of the attack. One of them said that the train departed about\none hour before the attack. The Commission obtained a photo of the train with military\nvehicles, taken by a family member of one of the witnesses."},{"id":"a-hrc-52-crp-4-p0227","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"227","seq":228,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Ukrainian and Russian armed forces have blamed each other for the attack. Since the\nTochka-U missile has a range of 120 km, the launch of the missile could have originated\nfrom territory controlled by both armed forces. Since the position of the tail section and its\nrelative location to the submunition impacts are not always reliable indications of the\ndirection of the attack with this kind of weapon, the Commission has not been able to\nestablish the direction of the attack based on the physical evidence on the ground."},{"id":"a-hrc-52-crp-4-p0228","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"228","seq":229,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Both armed forces are reported to have this type of missile in their arsenal. While the\nRussian Ministry of Defence stated in 2019 that it had introduced the Iskander-M, replacing\nthe Tochka-U missile,241 the Commission is not aware of any evidence that the Tochka-U\nmissiles and their related equipment were destroyed. On the contrary, it has compiled videos,\nphotos, and other information of multiple sightings of Tochka-U related equipment in Belarus\nand Russian-occupied areas in Ukraine. This includes a sighting of Tochka-U equipment in\nthe relevant area around the time of the 8 April 2022 attack."},{"id":"a-hrc-52-crp-4-p0229","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"229","seq":230,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has noted that a key military objective of the Russian armed forces\nat the time of the attack was to disrupt the delivery of weapons and ammunition by train to\nUkrainian armed forces in the east. In its 8 April 2022 daily update, for example, the Russian\nMinistry of Defence said that “[h]igh-precision missiles launched from the Donetsk region\non train stations in Pokrovsk, Slovyansk, Barvenkovo destroyed weapons and military\nequipment of the reserves of Ukrainian troops that arrived in the Donbass”. 242 Slovyansk is\nlocated just 12 km north of Kramatorsk. The Russian Ministry of Defence posted similar\nupdates about attacks on other train stations with “accumulation of Ukrainian military\nequipment” on 6 and 7 April 2022.243 Given the presence of military equipment at the\nKramatorsk train station, attacking the train station would be consistent with Russian armed\nforces’ overall objective at that time."},{"id":"a-hrc-52-crp-4-p0230","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"230","seq":231,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack and the use of cluster munitions in a populated area,\nwhere a significant number of civilians were present, causing numerous civilian casualties\nand damage; also considering the presence of Ukrainian military equipment at the train\nstation prior to the attack, and the objectives of Russian armed forces at the time, the\nCommission has concluded that Russian armed forces likely launched an indiscriminate,\ndisproportionate attack using cluster munitions on the Kramatorsk train station on 8 April\n2022 and that they failed to take feasible precautions such as the choice of means and methods\n241 Ministry of Defence of the Russian Federation, “Artillery operators of the combined arms army of\nthe Western Military District will adopt the latest Iskander-M OTRK”, 19 November 2019.\n242 Ministry of Defence of the Russian Federation, “Briefing by Russian Defence Ministry”, 8 April\n2022. (Telegram message available only in Russian). Pokrovsk and Barvenkovo are 60 and 50 km,\nrespectively, from Kramatorsk.\nof attack with a view to minimize civilian harm. These are violations of international\nhumanitarian law.244\nAttacks with artillery rockets"},{"id":"a-hrc-52-crp-4-p0231","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"231","seq":232,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has investigated attacks carried out with unguided artillery rockets\nin Chernihiv and Marhanets cities. This weapon system consists of artillery rockets fired from\na multiple launch rocket system. These attacks affected large areas and led to civilian\ncasualties and destruction of civilian objects. The Commission has determined that BM-21\nGrad-type rockets were likely used, based on accounts of witnesses and an analysis of videos\nand photos of the impact sites. The Commission has concluded that the attacks were carried\nout with rocket artillery in urban areas were indiscriminate.245\nChernihiv city, Chernihiv region, 16 March 2022"},{"id":"a-hrc-52-crp-4-p0232","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"232","seq":233,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 16 March 2022, in the morning, several munitions struck a residential area,\nincluding the Soyuz Supermarket in Dotsenka Street, in Chernihiv city. The attack killed at\nleast 14 persons, seven of whom were 70 years or older."},{"id":"a-hrc-52-crp-4-p0233","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"233","seq":234,"section":"3. Unlawful attacks with the use of explosive weapons","text":"At that time, Russian armed forces were launching numerous attacks against the city,\nuntil the end of March. The city was under Ukrainian armed forces control, but almost fully\nencircled by the attacking Russian forces."},{"id":"a-hrc-52-crp-4-p0234","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"234","seq":235,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has found it likely that two different weapons were used in the\nattack. One crater and the damage to a wall near the supermarket suggest that the site was\nstruck by an artillery shell. In addition, damage to buildings and photos of weapon remnants\nindicate that several unguided artillery rockets, likely 122 mm Grad rockets, also struck the\nneighbourhood. In the latter case, accounts from witnesses indicate that multiple explosions\ntook place at almost the same time, which is consistent with the use of unguided artillery\nrockets."},{"id":"a-hrc-52-crp-4-p0235","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"235","seq":236,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area. According to the Commission’s interviews, a large\ncrowd of people had gathered around the supermarket at that time. Some were standing in\nline on the eastern side of the supermarket, waiting to buy bread. Others were queuing to\nenter the supermarket or to receive pensions at the post office. Many of those present were\nolder people."},{"id":"a-hrc-52-crp-4-p0236","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"236","seq":237,"section":"3. Unlawful attacks with the use of explosive weapons","text":"There are indications that there might have been legitimate military targets in the\nvicinity at the time of the attack. Witness accounts collected by other organizations suggest\nthat Ukrainian armed forces used the nearby Berezovyi Hai park to attack Russian armed\nforces. This is consistent with videos posted later on social media, which show extensive\ndamage in the park and to nearby residential buildings, indicating that the park was a frequent\ntarget of attacks. Furthermore, this was supported by news and information about the city on\na website, which described the park as “one of the important defensive outposts during the\ndefense of Chernihiv” after Russian forces withdrew from Chernihiv region. While the\nsupermarket is a few hundred meters from the entrance of the park, many of the buildings\nthat were struck by 122 mm Grad rockets were located right next to the park, which would\nbe consistent with the park being the intended target of the attack."},{"id":"a-hrc-52-crp-4-p0237","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"237","seq":238,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Russian Ministry of Defence denied responsibility for the attack, claiming that\nthe dead persons were either “victims of terror by Ukrainian nationalists,” or that the videos\nwere “another production” by the Ukrainian security services. The Ministry further stated\nthat the videos contained no indications of explosions, that windows were intact, and that\nthere was no damage to walls.246 The Commission visited the site of the attack and reviewed\nmultiple photos and videos showing craters in the ground, damage to buildings, and destroyed\nwindows."},{"id":"a-hrc-52-crp-4-p0238","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"238","seq":239,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was launched from a position to the\nnorth-east of the impact site. The crater and the damage to the wall and a gate from the\nartillery shell that struck near the supermarket suggest that the shell arrived from the north-\neast. Likewise, all the BM-21 Grad rocket impacts on buildings struck walls that were facing\n244 Additional Protocol I to the Geneva Conventions, articles 51(4)-(5) and 57(2).\n245 Additional Protocol I to the Geneva Conventions, article 51(4)-(5).\n246 Ministry of Defence of the Russian Federation, “Briefing by Russian Defence Ministry”, 16 March\n2022.\neither in a northern, or north-eastern direction, showing that the attack came from that\ndirection."},{"id":"a-hrc-52-crp-4-p0239","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"239","seq":240,"section":"3. Unlawful attacks with the use of explosive weapons","text":"A document found at an abandoned command post of the Center Group of Forces of\nthe Russian armed forces, indicates that on 6 March 2022, the forward command post of the\n35th Separate Guards Motorized Rifle Brigade was located in Terekhivka village, about 14\nkm north-east of Chernihiv. Satellite imagery published by a non-governmental organization\nand taken on 17 March 2022 shows at least two artillery firing lines, two and four kilometres\nfurther north-east. These firing lines were within the maximum range of the weapons that\nstruck around Dotsenka Street on 17 March 2022."},{"id":"a-hrc-52-crp-4-p0240","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"240","seq":241,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack, the use of rocket artillery in a populated area, where\na significant number of civilians were present, causing numerous civilian casualties and\ndamage to civilian objects, the Commission has concluded that Russian armed forces\nconducted an indiscriminate attack in Chernihiv city on 16 March 2022 using weapons,\nincluding unguided artillery rockets. They also failed to take feasible precautions, such as the\nchoice of means and methods of attack with a view to minimize civilian harm. These are\nviolations of international humanitarian law.247\nMarhanets city, Dnipropetrovsk region, 10 August 2022"},{"id":"a-hrc-52-crp-4-p0241","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"241","seq":242,"section":"3. Unlawful attacks with the use of explosive weapons","text":"During the night of 9 to 10 August 2022, an attack struck Marhanets, damaging several\nbuildings, including at least one school. It killed at least 11 civilians, all men, and injured 11\n– eight men and three women."},{"id":"a-hrc-52-crp-4-p0242","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"242","seq":243,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Marhanets is located on the right bank of the Dnipro River. At the time of the attack,\nRussian armed forces were in control of the territory on the left bank."},{"id":"a-hrc-52-crp-4-p0243","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"243","seq":244,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has determined that the attack was carried out with weapons which\nhad characteristics consistent with a multiple launch rocket system. Residents described the\nattack as lasting for a long time, with a large number of impacts. Witness accounts and photos\nand videos of the impact sites show that the attack affected a large area, as well as medium-\nsized craters and holes in the wall, where munitions have struck directly. Taken together,\nthese indications on the duration of the attack, the size of the area affected, and the type of\ndamage caused, point to an attack with a multiple launch rocket system, likely BM-21 Grad\nrockets."},{"id":"a-hrc-52-crp-4-p0244","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"244","seq":245,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The attack struck a populated area of the city, which included residential buildings, a\nschool, and a dormitory. The Commission has received videos and photographs of significant\ndamage to two civilian homes that were hit directly."},{"id":"a-hrc-52-crp-4-p0245","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"245","seq":246,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has assessed that the attack came from a south-southwest direction\nbased on an analysis of the photos and videos of the impact sites. Residents told the\nCommission that there had been frequent attacks with explosive weapons in Marhanets since\nmid-2022. They could see some of the attacks coming from the direction of the Zaporizhzhia\nNuclear Power Plant, in Enerhodar, which is about 14 km away on the opposite side of the\nriver and therefore within the maximum range of 122 mm Grad rockets. According to an\nemployee of the plant, Russian armed forces frequently attacked Marhanets from locations\nnear the plant, including with multiple launch rocket systems."},{"id":"a-hrc-52-crp-4-p0246","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"246","seq":247,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attack, the use of rocket artillery in a populated area,\ncausing civilian casualties and damage to civilian objects, the Commission has concluded\nthat Russian armed forces conducted an indiscriminate attack on a populated area in\nMarhanets on 10 August 2022, and failed to take feasible precautions such as the choice of\nmeans and methods of attack with a view to minimize civilian harm. These are violations of\ninternational humanitarian law.248\nb)     Attacks in areas controlled by Russian armed forces"},{"id":"a-hrc-52-crp-4-p0247","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"247","seq":248,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission documented several instances of cluster munitions and rocket-\ndelivered anti-personnel mines use in attacks in populated areas when they were under the\ncontrol of Russian armed forces. Both types of weapons are indiscriminate when employed\nin populated areas. Ukraine, unlike the Russian Federation, is a state party to the Convention\non the Prohibition of the Use, Stockpiling, Production and Transfer of Anti-Personnel Mines\nand on their Destruction, which bans use of anti-personnel mines."},{"id":"a-hrc-52-crp-4-p0248","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"248","seq":249,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has reviewed incidents in Izium city, Kharkiv region, which Russian\narmed forces took control of from 24 March to 10 September 2022, and in Donetsk city, in\nthe Donetsk region. During its visits to Izium, residents told the Commission that cluster\nmunitions were frequently used both during the battle for the city and the Russian occupation.\nLocal residents, including medical staff and people involved in burials, provided information\nabout several cluster munition attacks that happened during the Russian occupation."},{"id":"a-hrc-52-crp-4-p0249","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"249","seq":250,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Also during visits to Izium city, the Commission documented the use of anti-personnel\nmines at the time when the city was under Russian armed forces’ control. Residents and\nmedical staff reported that on multiple occasions, mines were scattered over populated areas.\nInformation from residents and photos posted on social media indicate that mines were used\nin Izium city at least from July to September 2022. Residents and medical staff said that use\nwas particularly widespread in late August and early September, just before or as Russian\narmed forces withdrew from the city. They led to grave civilian injuries."},{"id":"a-hrc-52-crp-4-p0250","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"250","seq":251,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has so far not been able to conclusively attribute responsibility for\nthe incidents it has investigated in the areas which were under Russian armed forces’ control.\nThe context in which they happened and the fact that they occurred on several occasions,\nindicate that they were likely launched by Ukrainian armed forces."},{"id":"a-hrc-52-crp-4-p0251","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"251","seq":252,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission’s investigation of incidents in areas controlled by Russian armed\nforces at the time of the attacks has been severely hampered by its lack of access to those\nlocations. The Commission’s numerous requests for access have not yielded any response,\nneither from the de facto authorities in these areas, nor from the Russian authorities. The\nCommission’s investigation has also been challenging because of fewer photos and videos\nof incidents in areas controlled by Russian armed forces. Residents reported that attempting\nto take photos or videos of the aftermath of attacks involved significant security risks.\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0252","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"252","seq":253,"section":"3. Unlawful attacks with the use of explosive weapons","text":"In this section, the Commission will provide illustrations of some incidents it has\ndocumented. For each incident, the Commission has sought to determine the general context,\nwhether civilians or civilian objects were affected, the potential presence of military\nobjectives at or near the impact sites, the weapons systems used, and the party responsible.\nAs noted above, the Commission faced particular challenges in documenting these incidents.\nAttacks with cluster munitions\nIzium city, Kharkiv region, three instances"},{"id":"a-hrc-52-crp-4-p0253","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"253","seq":254,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission investigated three attacks that caused civilian casualties in Izium\ncity during the period it was under Russian armed forces control. In two of these cases, there\nwas clear physical evidence of the use of cluster munitions."},{"id":"a-hrc-52-crp-4-p0254","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"254","seq":255,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 9 May 2022, in the evening, an attack struck the First Microdistrict in Izium,\naccording to several local residents; they stated that three persons were killed and six were\ninjured, including a 10-year-old boy. The Commission has determined that the attack was\nlikely carried out with cluster munitions based upon the indentations in the ground and the\nscarring pattern. One resident said that a “rocket with holes that fired cluster munition”, a\nlikely reference to the cargo section of a 220-mm Uragan rocket, had been stuck in the yard\nof her building and was removed by Russian soldiers after two weeks. Another resident,\nwhose friend was killed in the incident, showed damage to the walls in his house and a small\ncrater outside his gate, with surrounding scatter pattern characteristic of a submunition\nexplosion."},{"id":"a-hrc-52-crp-4-p0255","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"255","seq":256,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 16 July 2022, around 11 a.m., an attack struck the Pidhirky district in Izium,\naccording to residents. Several submunitions impacted Kindergarten No. 13, where about\n250 persons from the neighbourhood, including many children, had sought shelter. A 60-\nyear-old man who sat in the garden was killed at the entrance to the basement. A 60-year-old\nwoman who was about 200 m away was also killed. According to witnesses, she was among\na large crowd of older persons who were waiting outside a newly opened branch of a Russian\nbank to receive pensions from the Russian authorities. Medical staff stated that many older\npersons injured in that attack were hospitalized on that day. The Commission has determined\nthat the attack was likely carried out with cluster munitions based upon the indentations in\nthe ground and the surround scarring pattern. It has documented damage to the wall next to\nthe entrance to the basement of the kindergarten, consistent with the use of cluster munition\nand a small impact crater in the asphalt with a surrounding scatter pattern typical of a\nsubmunition explosion. Two persons who were outside when the attack happened said that\nthey heard small explosions in the air."},{"id":"a-hrc-52-crp-4-p0256","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"256","seq":257,"section":"3. Unlawful attacks with the use of explosive weapons","text":"On 14 July 2022, around 11 a.m., an attack struck the area around the central market\nin Izium, according to local residents; a 60-year-old woman told the Commission that she\nwas injured in her knee in the attack, and that two of her neighbours, both in their seventies,\nsustained injuries in the attack. The witnesses confirmed the attack and reported that it was\ncarried out with cluster munitions."},{"id":"a-hrc-52-crp-4-p0257","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"257","seq":258,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Based on the context of the attacks, the use of cluster munitions in a populated area,\nwhere a significant number of civilians were present, causing civilian casualties and damage,\nthe Commission has concluded that Ukrainian armed forces likely launched an indiscriminate\nattack using cluster munitions in Izium on 9 May and 16 July 2022, and that they failed to\ntake feasible precautions such as the choice of means and methods of attack with a view to\nminimize civilian harm. These are violations of international humanitarian law.249 The attack\non 14 July 2022 appears to be similar to the above two attacks.\nDonetsk city, Donetsk region, 14 March 2022"},{"id":"a-hrc-52-crp-4-p0258","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"258","seq":259,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Russian Ministry of Defence said on 14 March 2022 that a cluster munition\nmissile struck Donetsk city earlier that day, killing 20 civilians and injuring 28.250 Photos and\nvideos from Donetsk city posted on various social media channels on 14 March 2022 and\nafterwards show at least seven people in civilian clothes who appear to be injured and 13\npeople who appear to be lifeless. The footage also shows the remnants of a Tochka-U ballistic\nmissile and impact craters in asphalt with surround scatter patterns indicative of a cluster\nmunition attack. One man in uniform said in a video that air defence intercepted the missile\nand that is why it landed where it did."},{"id":"a-hrc-52-crp-4-p0259","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"259","seq":260,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Ukrainian authorities denied that they were responsible in media statements. In\nresponse to a written question, the authorities said that they have no information about the 14\nMarch 2022 incident in Donetsk city."},{"id":"a-hrc-52-crp-4-p0260","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"260","seq":261,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Without access to the area and in absence of communication with Russian authorities,\nthe Commission has not been able to attribute responsibility for the attack or to determine\nwhether the incident violated international humanitarian law.\nUse of anti-personnel mines\nIzium city, Kharkiv region, multiple instances"},{"id":"a-hrc-52-crp-4-p0261","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"261","seq":262,"section":"3. Unlawful attacks with the use of explosive weapons","text":"The Commission has investigated incidents involving the use of anti-personnel mines\nin Izium during the period in which the city was under Russian armed forces control."},{"id":"a-hrc-52-crp-4-p0262","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"262","seq":263,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Several local residents told the Commission that they saw anti-personnel mines or\nwere injured by them on 9 and 10 September 2022 in the western part of Izium. Witnesses\nstated that on 9 September 2022, mines fell on their neighbourhood behind the Povorotka\nsupermarket in north-western Izium. They explained that Russian armed forces had been\nlocated in the adjacent forest, and while Russian forces had started withdrawing by then,\nthere were still some soldiers left. One local resident said that several vehicles used by\nRussian armed forces were damaged by the mines. At least two civilians were subsequently\ninjured when stepping on mines."},{"id":"a-hrc-52-crp-4-p0263","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"263","seq":264,"section":"3. Unlawful attacks with the use of explosive weapons","text":"One married couple told the Commission that in a neighbourhood a bit further south,\nmines fell around midday the following day. They heard short blasts and the sound of plastic\nobjects falling on rooftops. When the man went out, he stepped on a mine, which exploded,\nseverely injuring his leg. He saw several mines lying around him. A neighbour went to seek\nhelp but was shot at by Russian soldiers. The neighbour eventually managed to bring the\ninjured man to the hospital where medical staff had to amputate his leg. Another local resident\nin the same area said that he started seeing mines in his neighbourhood in late August or early\nSeptember 2022. He had destroyed nine mines himself and showed the Commission two\nunexploded mines that were still lying in his backyard."},{"id":"a-hrc-52-crp-4-p0264","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"264","seq":265,"section":"3. Unlawful attacks with the use of explosive weapons","text":"While civilians continued to be injured by anti-personnel mines in and around Izium,\nthe Commission is not aware of any allegations that they were used after Russian armed\nforces withdrew from the city."},{"id":"a-hrc-52-crp-4-p0265","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"265","seq":266,"section":"3. Unlawful attacks with the use of explosive weapons","text":"After inspection of unexploded mines, photographs, and weapon remnants, the\nCommission has identified them as antipersonnel high-explosive landmines (PFM in\nRussian), also called “butterfly mines”. The Commission has seen photos of weapon\nremnants found in Izium that indicate that PFM mines had been delivered by 220-mm Uragan\nrockets with a range of 10 to 35 km. The Commission has not been able to establish the\ndirection from where the rockets were fired. Both Ukrainian and Russian armed forces were\nstationed within striking distance of Izium."},{"id":"a-hrc-52-crp-4-p0266","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"266","seq":267,"section":"3. Unlawful attacks with the use of explosive weapons","text":"Given the military context in Izium and the repeated use of PFM mines, including in\nareas with presence of Russian armed forces, the Commission has concluded that it is likely\nthat the PFM mines in Izium were used by Ukrainian armed forces. In addition to being\nviolations of international humanitarian law251 – an indiscriminate attack and failure to take\nfeasible precautions – this would be a violation of the Convention on the Prohibition of the\nUse, Stockpiling, Production and Transfer of Anti-Personnel Mines and on their\nDestruction.252"},{"id":"a-hrc-52-crp-4-p0267","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"267","seq":268,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"The Commission has investigated the series of large-scale attacks on energy-related\ninstallations in Ukraine. Since the beginning of the Russian Federation’s invasion of Ukraine,\nboth Russian and Ukrainian armed forces, albeit to a very different degree, had carried out\nattacks on energy-related installations in each other’s countries. Although Russian armed\nforces had been carrying out strikes on Ukrainian energy facilities since the first days of the\ninvasion, such attacks were expanded onto a large scale from 10 October 2022. For the\npurposes of its investigations, the Commission has focused on the period from 10 October to\n26 January 2023."},{"id":"a-hrc-52-crp-4-p0268","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"268","seq":269,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Prior to 10 October 2022, attacks by the Russian armed forces impacted, among\nothers, oil refineries and electric sub-stations related to railways. These early attacks affected\ncivilians in many ways, including those trying to flee, as well as created fuel shortages during\nthe spring and summer 2022."},{"id":"a-hrc-52-crp-4-p0269","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"269","seq":270,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"After 10 October 2022, two days after an explosion on the Kerch Bridge, the energy-\nrelated infrastructure in Ukraine became an explicitly declared target of ramped-up attacks.253\nOn that date, President Putin declared that “at the proposal of the Defence Ministry\nand in accordance with the plan of Russia’s General Staff, a massive strike was launched\nwith long-range precision air, sea and land-based weapons against Ukrainian energy, military\nand communications facilities”.254 The large-scale attacks on energy-related infrastructure\nwere carried out with hundreds of long-range missiles and drones equipped with explosives\nand struck objectives in 20 of Ukraine’s 24 regions. They targeted many of the installations\nwhich are indispensable to the survival of the civilian population, such as electric substations\nand power plants. Many of these installations are thermal plants as well, meaning they\nproduced both electricity and heating for entire urban areas, where individual dwellings do\nnot have heating systems of their own but depend on the thermal energy produced by the\nplants."},{"id":"a-hrc-52-crp-4-p0270","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"270","seq":271,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"As mentioned above, international humanitarian law requires that parties distinguish\nbetween military objectives and civilian objects.255 In principle, an energy-related facility\nmay have both military and civilian purposes, i.e., it can be dual-use. However, given the\nwidespread and intensive nature of the waves of attacks, the Commission has determined that\nthe attacks likely included facilities that were not for military purposes or dual-use. Further,\na dual-use facility does not automatically become a lawful military target. The Russian armed\nforces were required to confirm that each targeted facility made an effective contribution to\nUkraine’s military action and that attacking it offered a definite military advantage (i.e., not\npotential).256 Even if deemed to be a lawful military objective, from this perspective, the\nRussian armed forces were required to assess the proportionality of each attack. In particular,\nthey were prohibited from launching an attack which may be expected to cause incidental\nloss of civilian life, injury to civilians, damage to civilian objects, or a combination thereof,\nwhich would be excessive in relation to the concrete and direct military advantage\nanticipated.257 Moreover, intentionally launching such an attack with knowledge of its\nexpected excessive nature is a war crime (i.e., war crime of excessive incidental death, injury\nor damage).258"},{"id":"a-hrc-52-crp-4-p0271","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"271","seq":272,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"The large-scale attacks launched by Russian armed forces on Ukraine’s infrastructure\nstarting 10 October 2022 were distinct from previous attacks on energy facilities. The\nintensity, geographical scope, and type of installations targeted lead the Commission to\nconclude that the objective of the large-scale attacks was not just to damage or destroy\nindividual energy installations, which could serve a military purpose, but also to disrupt and\ndestabilize the entire energy system in Ukraine. The scale of the disruption is of a nature to\ninflict significant harm to the civilian population.\nWidespread and systematic character of the attacks"},{"id":"a-hrc-52-crp-4-p0272","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"272","seq":273,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"The Commission has found that the large-scale attacks launched between 10 October\n2022 and 26 January 2023, which it has examined in closer detail, were widespread and\nsystematic. First, the Commission’s own investigations as well as information from the\nUkrainian authorities show that the attacks struck energy-related installations across 20 of\nUkraine’s 24 regions and were therefore widespread."},{"id":"a-hrc-52-crp-4-p0273","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"273","seq":274,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Second, the intensity of the attacks led the Commission to assess that they were\nsystematic. As of the end of January 2023, Russian armed forces had launched at least 13\nwaves of attacks, using hundreds of long-range missiles and drones equipped with explosives,\nto target Ukraine’s energy-related installations. Such large-scale attacks took place in 2022\non 10 October, 11 October, 17 October, 31 October, 15 November, 23 November, 5\nDecember, 16 December, 19 December, 29 December and 31 December; in 2023 on 14\nJanuary and 26 January.259 While Ukrainian air defence shot down many of these weapons,\na significant number hit their targets. Ukrainian authorities have shared with the Commission\na list of 159 attacks that damaged or destroyed 79 energy-related installations across the\ncountry between 10 October 2022 and 12 January 2023. Photographs and videos of the\nimpact sites corroborate dozens of these attacks."},{"id":"a-hrc-52-crp-4-p0274","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"274","seq":275,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Finally, while attacks prior to 10 October 2022 focused mainly on fuel installations\nand electric infrastructure related to the railway system, attacks after that date targeted\nsystematically powerplants and other infrastructure critical for the transmission of electricity\nand the generation of heat across Ukraine.\nCivilian harm"},{"id":"a-hrc-52-crp-4-p0275","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"275","seq":276,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Russian authorities provided some indications regarding the anticipated military\nadvantage of the attacks after 10 October 2022. On 1 December 2022, for example, Russian\nforeign minister Sergey Lavrov stated in a press conference that the attacks were intended to\nknock out of service “the energy facilities that are important for the operation of the Ukrainian\narmed forces and for the delivery of a huge number of Western weapons, which are sent to\nUkraine to kill Russians”.260"},{"id":"a-hrc-52-crp-4-p0276","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"276","seq":277,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Nevertheless, the Commission is deeply concerned that inflicting civilian harm may\nhave been one of the objectives of the waves of attacks. Just a few days before the start of\nthe official heating season in Ukraine, the attacks targeted many of the installations which\nare indispensable to the survival of the civilian population. Statements of Russian\ngovernment officials since 10 October 2022 clearly indicated that the intended targets of\nthese attacks were energy facilities. In addition to the abovementioned declaration of\nPresident Putin, in October and November 2022, the Russian Ministry of Defence frequently\npublished similar statements in the daily updates."},{"id":"a-hrc-52-crp-4-p0277","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"277","seq":278,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"The attacks have, among other things, impacted electricity-related installations, which\ncaused outages, sometimes affecting millions of people across the country. Some of the\ntargets included power-generating installations as well as transmission substations, which\nplay a vital role in distributing electricity to some of the country’s regions. Their damage or\ndestruction led to a disruption of the transmission of electricity in numerous areas. Following\nthe attacks on 10 October 2022, for example, more than four million consumers were\ntemporarily disconnected from the electricity supply. Even more significantly, the attack of\n23 November 2022 deprived two-thirds of Ukrainian consumers of access to electricity, and\nit took a week to restore power to 80 per cent of them.261 Several installations attacked were\nalso directly related to the centralized heating system, which could have fatal effects on\ncivilians, particularly during the cold winter months. In addition, the disruption of the\ntransmission of electricity had an impact on health, education, and other key services."},{"id":"a-hrc-52-crp-4-p0278","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"278","seq":279,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Russian authorities could have reasonably assessed that considerable civilian harm\nwould follow from the attacks. Despite public information about the harm suffered by the\ncivilian population in the aftermath of the first few waves of attacks, Russian authorities\ncontinued to perpetrate several other waves of such attacks.\nDisproportionate attacks"},{"id":"a-hrc-52-crp-4-p0279","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"279","seq":280,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"The Commission has considered whether the waves of attacks targeting Ukraine’s\nenergy-related infrastructure, which were initiated on 10 October 2022, were\ndisproportionate, as they inflicted considerable and predictable civilian harm, given the\nessential nature of electricity and heating for civilian life."},{"id":"a-hrc-52-crp-4-p0280","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"280","seq":281,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"At the very least, after the first waves of attacks, the Russian authorities knew that\nsubsequent similar waves of attacks would cause incidental death or injury to civilians or\ndamage to civilian objects, and that such death, injury or damage would be of such an extent\nas to be clearly excessive in relation to the concrete and direct overall military advantage\nanticipated. If the intended object of the attack was the civilian population or civilian objects,\nthe attack would amount to additional war crimes."},{"id":"a-hrc-52-crp-4-p0281","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"281","seq":282,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"The Commission has therefore found reasonable grounds to conclude that the waves\nof attacks on Ukraine’s energy-related infrastructure launched starting 10 October 2022 by\nRussian armed forces was disproportionate and a violation of international humanitarian law.\nThe Commission has also concluded that the Russian armed forces and their leadership\nshould have known, based upon public information available to them, that the attacks would\ncause harm to civilians and damage civilian objects that would be excessive in relation to the\nanticipated military advantage. Consequently, the Russian armed forces committed the war\ncrime of excessive incidental death, injury, or damage.\n260 The Ministry of Foreign Affairs of the Russian Federation, “Foreign Minister Sergey Lavrov’s news\nconference on European security issues”, 1 December 2022.\n261 Stawomir Matuszak, “On the verge of blackout: Ukraine facing attacks on its electricity generation\nsystem”, Centre for Eastern studies 18 January 2023."},{"id":"a-hrc-52-crp-4-p0282","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"282","seq":283,"section":"4. Large-scale attacks against the Ukrainian energy-related infrastructure","text":"Due to the nature of the attacks, the Commission found that the attacks may amount\nto the crime against humanity of other inhumane acts, in addition to the violations of\ninternational humanitarian law and war crimes. The Commission has determined that Russian\narmed forces attacked the Ukrainian energy-related infrastructure starting on 10 October\n2022 in both a widespread and systematic manner. As discussed above, the attacks were\nwidespread as they were large-scale and launched against a significant number of targets over\na broad geographical area. The attacks were also systematic as they were organized and\nspecifically focused on the energy and heating infrastructure. Further time and resources are\nneeded to investigate the attacks to clarify if their accumulated impact becomes comparable,\nas it possibly can, given their magnitude, to one of the enumerated acts of crimes against\nhumanity, and to what extent the policy was directed against the civilian population. 262"},{"id":"a-hrc-52-crp-4-p0283","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"283","seq":284,"section":"5. Endangering civilians","text":"The Commission has found that, during the conduct of hostilities, both parties have,\nin some instances, exposed civilians to significant risks through the positioning of troops or\nequipment in or near civilian buildings, where civilians were present. International\nhumanitarian law prescribes that parties to the armed conflict shall, to the maximum extent\nfeasible, avoid locating military objectives within or near densely populated areas, and\nendeavor to remove civilians and civilian objects under their control from the vicinity of\nmilitary objectives.263"},{"id":"a-hrc-52-crp-4-p0284","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"284","seq":285,"section":"5. Endangering civilians","text":"The Commission documented situations in which Russian armed forces, on repeated\noccasions, deliberately deployed in residential areas, and, at times, forced civilians to remain\nthere or in proximity. In Kozarovychi village, Kyiv region, an older woman reported that\nwhen Russian armed forces arrived in the village in late February 2022, soldiers came to her\nhouse with orders to find hiding places for their vehicles. The woman and other local\nresidents told the Commission that Russian armed forces placed military vehicles between\nhouses, in backyards, and in garages, and shot at Ukrainian positions from between the\nhouses. In Lypivka village, Kyiv region, a woman and her daughter said that when Russian\narmed forces took control of the area on 28 February 2022, they parked one military vehicle\nthey identified as a tank next to their house, while the family was hiding in the basement."},{"id":"a-hrc-52-crp-4-p0285","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"285","seq":286,"section":"5. Endangering civilians","text":"Russian armed forces used a similar tactic in March 2022, in Yahidne village,\nChernihiv region, where they placed military vehicles between houses and fired at Ukrainian\npositions from people’s backyards. In addition, the soldiers forced the entire village, 365\ncivilians, to stay in the basement of the school while they established their headquarters on\nthe ground floor of the same building. With hundreds of civilians located in the building,\nRussian armed forces launched attacks on Ukrainian positions, also from the grounds of the\nschool, placing civilians at significant risk (see paras. 541-543)."},{"id":"a-hrc-52-crp-4-p0286","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"286","seq":287,"section":"5. Endangering civilians","text":"The Commission has further found that in areas controlled by Ukrainian armed forces,\nparticularly during the first phase of the hostilities, on some occasions, there was also a lack\nof separation between armed forces and civilians, which placed civilians at risk. In Chernihiv\ncity, residents stated that while schools 18 and 21 were used to distribute humanitarian aid to\nthe civilian population and school staff had written “children” on the walls of one of the\nschool buildings, Ukrainian Territorial Defence Forces had set up headquarters in school 18\nand their members were also present at school 21. Both military and civilians were among\nthose killed and wounded when an airstrike hit both schools and nearby houses on 3 March\n2022. By not separating civilians from their personnel, the Ukrainian armed forces in this\ncase failed to, among other things, take necessary precautions to protect civilians under their\ncontrol against the dangers resulting from military operations."},{"id":"a-hrc-52-crp-4-p0287","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"287","seq":288,"section":"5. Endangering civilians","text":"The Commission has concluded that the parties, although to a different extent, have\nendangered civilians by not taking requisite precautions to the maximum extent feasible –\nsuch as avoiding locating military objectives within or near densely populated areas – and\nhave thereby violated international humanitarian law.264\nb)     The situation at the Zaporizhzhia Nuclear Power Plant"},{"id":"a-hrc-52-crp-4-p0288","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"288","seq":289,"section":"5. Endangering civilians","text":"Military operations at or near the Zaporizhzhia Nuclear Power Plant, in Enerhodar,\nZaporizhzhia region, have significantly endangered the plant, prompting the risk of a serious\nnuclear incident. International humanitarian law prescribes that a nuclear plant, among other\nthings, shall not be made the object of attack if such attack may cause the release of dangerous\nforces and consequent severe losses among the civilian population. Further, armed forces\nshall endeavour to avoid locating any military objectives in its vicinity.265"},{"id":"a-hrc-52-crp-4-p0289","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"289","seq":290,"section":"5. Endangering civilians","text":"On 4 March 2022, Russian armed forces launched an attack on the power plant and\nheavy fighting erupted as they attempted to take control of it. The Commission has spoken\nto witnesses confirming that there was heavy fighting in the vicinity of the facility on that\nnight. Videos posted on social media, including by a staff member of the plant, show that a\nfire broke out as a consequence of the attack and inflicted damage to parts of the plant."},{"id":"a-hrc-52-crp-4-p0290","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"290","seq":291,"section":"5. Endangering civilians","text":"Russian armed forces placed military equipment in and near the facility. Satellite\nimagery from 29 August 2022 shows military equipment less than 150 m from a reactor.\nRussian armed forces have also been launching attacks from near the plant and have thereby\nplaced the facility at risk for retaliatory attacks. For example, the 10 August 2022 attack on\nMarhanets city described above (see paras. 241-246) was launched from the vicinity of the\nplant."},{"id":"a-hrc-52-crp-4-p0291","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"291","seq":292,"section":"5. Endangering civilians","text":"Witnesses interviewed by the Commission and public statements of the IAEA have\nconfirmed that there have been numerous incidents of shelling near the powerplant. The\nIAEA warned that the use of military force at or near the nuclear facility could lead to a\nserious nuclear incident.266 It is not only direct attacks on the powerplant that pose a risk. The\nplant requires power supply for the cooling systems and other essential safety functions. It\nrelies on four 750 kilovolt power lines providing electricity supply, as well as one back-up\n330 kilovolt powerline and fuel-powered generators for emergency use. Damage to energy\ninstallations have sometimes forced the powerplant to rely on its generators, leaving it\nextremely vulnerable. Loss of cooling systems can lead to a meltdown, and the release of\nradiation into the atmosphere."},{"id":"a-hrc-52-crp-4-p0292","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"292","seq":293,"section":"5. Endangering civilians","text":"While the Commission has not been, at this stage, in a position to determine which\nparty was responsible for attacks on the power plant and the connected power lines, it has\nestablished that Russian armed forces had launched an armed attack to take control of the\nplant and has placed military equipment in and near the facility."},{"id":"a-hrc-52-crp-4-p0293","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"293","seq":294,"section":"1. Personal integrity violations committed by Russian authorities","text":"The Commission has documented patterns of wilful killings, unlawful confinement,\ntorture, rape, sexual and gender-based violence and unlawful transfers and deportations of\ndetainees in the areas that came under the control of Russian authorities in Ukraine.\nViolations were also committed against persons deported from Ukraine to the Russian\nFederation."},{"id":"a-hrc-52-crp-4-p0294","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"294","seq":295,"section":"1. Personal integrity violations committed by Russian authorities","text":"On the basis of its investigations, the Commission noted certain elements which are\ncommon to the different patterns of violations that it has identified:"},{"id":"a-hrc-52-crp-4-p0295","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"295","seq":296,"section":"1. Personal integrity violations committed by Russian authorities","text":"In cases of summary executions and torture, perpetrators mostly targeted persons for\nany form of real or perceived support of Ukrainian armed forces, or for any action directed\nagainst Russian armed forces."},{"id":"a-hrc-52-crp-4-p0296","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"296","seq":297,"section":"1. Personal integrity violations committed by Russian authorities","text":"During Russian armed forces’ initial control of localities in Ukraine, many of the\nwilful killings, unlawful confinement, rapes, and sexual violence were committed in the\ncontext of house-to-house searches, which were aimed at locating supporters of the Ukrainian\narmed forces or finding weapons."},{"id":"a-hrc-52-crp-4-p0297","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"297","seq":298,"section":"1. Personal integrity violations committed by Russian authorities","text":"When Russian authorities controlled areas during longer periods of time, they\nestablished dedicated detention facilities, used more diverse methods of torture, and in\naddition, targeted persons who refused to cooperate. A wider array of perpetrators have been\ninvolved in the commission of unlawful confinement, torture, and sexual and gender-based\nviolence, according to victims and witnesses. Such perpetrators included Russian armed\nforces, the Federal Security Service of the Russian Federation,267 the National Guard of\nRussia268 and its subordinate units, and Russian-affiliated armed groups of the former self-\nproclaimed ‘republics’.\na)     Summary executions\n1)     Overview"},{"id":"a-hrc-52-crp-4-p0298","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"298","seq":299,"section":"1. Personal integrity violations committed by Russian authorities","text":"Evidence collected by the Commission shows a widespread pattern of summary\nexecutions in areas that Russian armed forces controlled. It has examined 84 credible\nallegations about the summary execution of at least 142 men, eight women, and one boy in\n43 localities in six regions. This section focuses on the four regions where the Commission\nhas had access; Chernihiv, Kharkiv, Kyiv and Sumy."},{"id":"a-hrc-52-crp-4-p0299","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"299","seq":300,"section":"1. Personal integrity violations committed by Russian authorities","text":"International humanitarian law prohibits the wilful or intentional killing of persons\nprotected under the Geneva Conventions, such as civilians or combatants hors de combat.269\nSuch killing constitutes a war crime. Similarly, international human rights law holds that no\none shall be arbitrarily deprived of their life.270"},{"id":"a-hrc-52-crp-4-p0300","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"300","seq":301,"section":"1. Personal integrity violations committed by Russian authorities","text":"The highest number of allegations collected so far came from the Kyiv region,\nincluding from the town of Bucha, which became notorious because of the high number of\ncivilians killed and executed there. Most of the executions documented in the areas which\nthe Commission has visited took place during the first months of the armed conflict. While\nthe geographical and temporal distribution of summary executions will likely change as more\ninformation surfaces, the number of summary executions in the Kyiv region is striking, and\nfurther investigation is required to understand the underlying reasons."},{"id":"a-hrc-52-crp-4-p0301","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"301","seq":302,"section":"1. Personal integrity violations committed by Russian authorities","text":"The Commission has categorized a killing as a summary execution based on an overall\nanalysis of the following factors: method of killing, in particular done within direct or close\nproximity to the victim, for example, a gunshot to the head, slit throat, or strangulation;\nwhether the victim was last seen in the custody of a party to the conflict or whether there is\nevidence that the victim was under the control of the perpetrator before death, such as,\nblindfolds over the victims’ eyes, the victims’ hands or legs were tied, or indications of ill-\ntreatment or torture; and whether information is available regarding a possible motive of the\nperpetrator for the execution."},{"id":"a-hrc-52-crp-4-p0302","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"302","seq":303,"section":"1. Personal integrity violations committed by Russian authorities","text":"Regretfully, the Commission has not been able to access some of the areas which were\naffected by ongoing hostilities, or which were under Russian armed forces control. The\nsituations outlined below are therefore only a small sample of the cases which the\nCommission has been able to document.\n2)     Situations in which summary executions were committed"},{"id":"a-hrc-52-crp-4-p0303","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"303","seq":304,"section":"1. Personal integrity violations committed by Russian authorities","text":"The Commission has verified and corroborated the execution of 68 persons in 17\nlocalities. All the summary executions described in this section took place in areas that were\nunder the control of Russian armed forces at the relevant times in Chernihiv, Kharkiv, Kyiv\nand Sumy regions."},{"id":"a-hrc-52-crp-4-p0304","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"304","seq":305,"section":"1. Personal integrity violations committed by Russian authorities","text":"In more than half of the cases documented, witnesses last saw the victims in the\ncustody of Russian armed forces before their death. In a few cases, eyewitnesses observed\nRussian armed forces carry out the executions. In both situations, there are reasonable\ngrounds to conclude that Russian armed forces are responsible for these executions."},{"id":"a-hrc-52-crp-4-p0305","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"305","seq":306,"section":"1. Personal integrity violations committed by Russian authorities","text":"In the remaining cases, the victims’ bodies were found at or near locations that\nRussian armed forces used as bases, such as farms, forests, basements or courtyards of private\nhouses and public buildings, and a basement of a children’s camp. In these cases, the\nCommission has concluded that Russian armed forces were likely responsible based on the\nlocation where the bodies were found."},{"id":"a-hrc-52-crp-4-p0306","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"306","seq":307,"section":"1. Personal integrity violations committed by Russian authorities","text":"In the cases investigated by the Commission, accounts of survivors, witnesses,\nrelatives, and in one case, a Russian armed forces soldier, suggest that perpetrators mostly\npursued victims for real or perceived support of Ukrainian armed forces. They targeted\nvictims for being members of or helping the Ukrainian armed forces or the Ukrainian\nTerritorial Defence Forces, for suspicion of passing information about the movement of\nRussian armed forces to the Ukrainian armed forces, for any other type of association with\ncurrent or former military personnel, or for any behaviour that might have been deemed\nsuspicious at the time. This is consistent with the profile of the victims. In the cases\ninvestigated, almost all victims were men, the majority aged between 30 and 50. In the few\nexceptions documented, the victims were women, or a 14-year-old boy accompanying a man\nof fighting age."},{"id":"a-hrc-52-crp-4-p0307","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"307","seq":308,"section":"1. Personal integrity violations committed by Russian authorities","text":"Many of the executions occurred in towns and villages that were close to the\nfrontlines, where Russian armed forces came into frequent contact with local residents. Most\nof the executions took place within the first couple of weeks after Russian armed forces\nassumed control over a place. Executions were also carried out after Russian armed forces\nstationed in a given location came under attack."},{"id":"a-hrc-52-crp-4-p0308","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"308","seq":309,"section":"1. Personal integrity violations committed by Russian authorities","text":"Perpetrators intercepted some of the victims on the street, as they were seemingly\ncarrying out routine activities. In certain cases, executions occurred in the context of house-\nto-house searches or house visits, during which Russian armed forces looked for individuals\ncooperating with Ukrainian armed forces or who possessed weapons or military attires. This\nis consistent with the above-described pattern in which perpetrators targeted people for their\nreal or perceived support of Ukrainian armed forces."},{"id":"a-hrc-52-crp-4-p0309","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"309","seq":310,"section":"1. Personal integrity violations committed by Russian authorities","text":"For instance, the Commission documented a case in which on 12 March 2022, after\nRussian armed forces visited several houses in a street of village Andriivka, in Kyiv region,\nthe bodies of three men were found dead, one in his garden, and two others in their respective\nhouses, all three with gunshot wounds in the back of their heads. The two latter men had in\naddition gunshot wounds to their knees and had their hands tied behind their backs (see case\ndescriptions starting para. 317)."},{"id":"a-hrc-52-crp-4-p0310","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"310","seq":311,"section":"1. Personal integrity violations committed by Russian authorities","text":"The Commission has reviewed multiple medical documents and photos of bodies\nwhich show that the most common method of killing was gunshot to the head from close\nrange. Other victims died of multiple gunshot injuries to torso, or their throat was slit."},{"id":"a-hrc-52-crp-4-p0311","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"311","seq":312,"section":"1. Personal integrity violations committed by Russian authorities","text":"In many of the cases, there is evidence that Russian armed forces kept the victims in\ncustody, often in places where they set up temporary bases, prior to the execution. In a\nnumber of cases investigated, one or several of the victims had their hands tied behind their\nbacks, or their feet tied. The material used were zip ties, nylon ropes, plastic cords, or other\ntypes of improvised textiles."},{"id":"a-hrc-52-crp-4-p0312","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"312","seq":313,"section":"1. Personal integrity violations committed by Russian authorities","text":"In a few cases, witnesses indicated that victims were killed on the spot. This occurred,\nfor example, in an incident on 3 March 2022, in Havronshchyna village, Kyiv region, in\nwhich a resident saw through his window a group of five soldiers interrogating two men in\ncivilian clothes in front of a shop. After a while, they led one of the two men behind the shop\nand the witness heard two gunshots. Later the same day, another witness and a few local men\nfound the body of the young man behind the shop. Similarly, on the night from 28 to 29\nMarch 2022, near village Vesele, Kharkiv region, witnesses who were on buses bringing\ncivilians to the Russian Federation described seeing a group of Russian soldiers taking two\nyoung men off the buses, interrogating them, beating them heavily, and shooting one of the\nmen in the head."},{"id":"a-hrc-52-crp-4-p0313","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"313","seq":314,"section":"1. Personal integrity violations committed by Russian authorities","text":"In some instances, the execution was preceded by interrogation and torture or ill-\ntreatment. Where available, the Commission reviewed photos of the bodies of the victims\nand noted traces of blunt force traumas on head, face, torso, and legs. Some of the victims\nalso had traces of blood, gunshot wounds to the legs, and broken bones. These suggest torture\nor ill-treatment prior to death. In a widely reported case from 23 March 2022, where the head\nof the Motyzhyn village, in Kyiv region, was detained and subsequently executed alongside\nwith her family, a witness who participated in the exhumation of the bodies, reported that the\nhusband of the head of the village had broken hands, while her adult son had a gunshot wound\nin his knee."},{"id":"a-hrc-52-crp-4-p0314","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"314","seq":315,"section":"1. Personal integrity violations committed by Russian authorities","text":"One victim who survived torture and a subsequent execution attempt in March 2022,\nin Vyshneve, Chernihiv region, reported that one of the perpetrators, a Russian soldier,\nthreatened to cut off his ears and told him: “If you don’t say who blew up the convoy, I will\nkill you, you’d be my 82nd killed khokhol,” using a Russian derogatory term for Ukrainians.\nThe two brothers of the victim had been tortured and executed by the same perpetrators.\nAnother survivor described hearing a man being interrogated and beaten for one and a half\nhours, his arms broken, and legs shot, before he was killed."},{"id":"a-hrc-52-crp-4-p0315","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"315","seq":316,"section":"1. Personal integrity violations committed by Russian authorities","text":"The violent death of a close family member, and especially the knowledge that this\nwas preceded by torture or ill-treatment, has a profound impact on the families. Those\ninterviewed by the Commission spoke of their pain, anger and struggle to come to terms with\ntheir loss. One woman whose husband disappeared during the occupation of the village by\nRussian armed forces and whose burned body was later found in a cellar of a private house,\nshared the following with the Commission: “I cry every single day. I had a husband, a good\nman, hardworking, caring, wonderful father and grandfather. … His grandson cries “Where’s\nmy grandfather?” How do you explain what happened to a four-year-old child? I’ve lost my\nhusband, my house, and my work. How should I go on living?”."},{"id":"a-hrc-52-crp-4-p0316","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"316","seq":317,"section":"1. Personal integrity violations committed by Russian authorities","text":"Based on the body of evidence it has collected, the Commission has concluded that\nRussian armed forces have committed numerous wilful killings of civilians or persons hors\nde combat in multiple locations that came under their control, which are war crimes and\nviolations of the right to life.271\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0317","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"317","seq":318,"section":"1. Personal integrity violations committed by Russian authorities","text":"As stated above, the Commission has found a pattern of summary executions\ncommitted by Russian armed forces in areas which came under their control. In this section,\nthe Commission will provide illustrations of the cases it has documented. The context and\ncircumstances of each case are described. The Commission has included corroborated\ninformation about units present in the relevant area, even if it has not established a link\nbetween that unit and the violation. Where the Commission has found a direct link between\na unit and the violation, this is specified.\nAndriivka village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0318","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"318","seq":319,"section":"1. Personal integrity violations committed by Russian authorities","text":"Russian armed forces entered Andriivka on 26 February 2022. They occupied the\nvillage until 31 March 2022. The Commission has collected information indicating that the\nRussian armed forces 64th Separate Guards Motor Rifle Brigade was based in the village. In\naddition to the case described below, there are credible allegations regarding the killings of\nat least eight local men that bear signs of executions that occurred during the occupation of\nthe village.\nExecutions on Slobody Street"},{"id":"a-hrc-52-crp-4-p0319","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"319","seq":320,"section":"1. Personal integrity violations committed by Russian authorities","text":"According to witnesses, during their occupation of the Andriivka village, Russian\nsoldiers were searching residential houses for weapons, uniforms, or any other indication that\nwould link residents with the Ukrainian armed forces."},{"id":"a-hrc-52-crp-4-p0320","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"320","seq":321,"section":"1. Personal integrity violations committed by Russian authorities","text":"Ruslan Yaremchuk272 (born 1975) was last seen alive on 11 March 2022. His body\nwas found by residents five days later in his garden on Slobody Street. According to\nwitnesses, he had a gunshot wound in the back of his head. This is confirmed by medical\ndocuments reviewed by the Commission, which indicate perforating gunshot wound to the\nhead as the main cause of death. Yeremchuk’s mobile phone, destroyed by a gunshot, was\nfound next to his body."},{"id":"a-hrc-52-crp-4-p0321","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"321","seq":322,"section":"1. Personal integrity violations committed by Russian authorities","text":"The Commission has also documented that two other identified men were killed in\ntheir respective houses in the same street on 12 March 2022. Information collected indicates\nthat both died of gunshot wounds to their heads, in the same way as Yeremchuk. In addition,\nthe men appeared to have gunshot wounds to their knees and had their hands tied behind their\nbacks. One neighbour told a news outlet that he saw how several soldiers arrived in a military\nvehicle with the letter “V”, entered the houses of the two men, after which he heard gunshots."},{"id":"a-hrc-52-crp-4-p0322","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"322","seq":323,"section":"1. Personal integrity violations committed by Russian authorities","text":"Using photos that Russian soldiers in Andriivka took with the phone of a local\nresident, journalists identified two soldiers from the 64th Separate Guards Motor Rifle\nBrigade. By analyzing obituaries of Russian soldiers killed in Ukraine, the Commission\nverified that the 64th Brigade was stationed in Andriivka. In a recorded phone conversation\nwith a journalist in July 2022, one of the soldiers described witnessing the execution of two\nmen and said that he had shot a third one himself. He said that he executed the man because\nhe suspected him of providing information about the movement of Russian armed forces to\nUkrainian armed forces, which led to an attack that killed several of his fellow soldiers. His\ndescription of the killings is consistent with the killing of the three men on Slobody Street.\nThe Commission has collected information about the commanders of the 64th brigade,\nincluding one commander who might have been involved in the executions described above.\nBucha town, Kyiv region"},{"id":"a-hrc-52-crp-4-p0323","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"323","seq":324,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 3 March 2022, after several failed attempts, Russian armed forces entered Bucha.\nThey remained in control of the town until their withdrawal on 31 March 2022. Information\ncollected by the Commission indicates that forces from several Russian armed forces units\nwere located in the town, including the 234th Guards Airborne Assault Regiment and the 104th\nGuards Airborne Assault Regiment of the 76th Guards Airborne Assault Division; the 5th\nSeparate Guards Tank Brigade of the 36th Combined Arms Army; and the 147th Guards Self-\nPropelled Artillery Regiment of the 2nd Guards Motor Rifle Division.\nExecutions at Yablunska Street"},{"id":"a-hrc-52-crp-4-p0324","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"324","seq":325,"section":"1. Personal integrity violations committed by Russian authorities","text":"In a well-documented case, eight men were found bearing signs of execution in an\nadministrative building at Yablunska Street 144 after Russian armed forces left the town."},{"id":"a-hrc-52-crp-4-p0325","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"325","seq":326,"section":"1. Personal integrity violations committed by Russian authorities","text":"According to media reports, Russian soldiers detained nine men, eight of them\nmembers of the Ukrainian Territorial Defence during a house-to-house search on 4 March\n2022. The soldiers looked for certain tattoos and forced the men to take off their winter\njackets and shoes, after which they brought them to the administration building. The soldiers\neventually brought the men to the courtyard, where they shot dead seven of them. The body\nof one more man was already lying in the courtyard with a gunshot wound to the head."},{"id":"a-hrc-52-crp-4-p0326","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"326","seq":327,"section":"1. Personal integrity violations committed by Russian authorities","text":"The media reports were based on interviews with one man who was wounded but\nsurvived the killing, closed circuit television footage of the soldiers bringing the men to their\nbase, drone footage showing the presence of Russian soldiers, military vehicles, the bodies\nof the killed men at Yablunska Street 144, and photos and videos of the bodies in the\ncourtyard."},{"id":"a-hrc-52-crp-4-p0327","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"327","seq":328,"section":"1. Personal integrity violations committed by Russian authorities","text":"In addition, the Commission interviewed a witness who was one of the first to enter\nBucha after Russian forces withdrew. He confirmed seeing eight bodies in the courtyard of\nYablunska Street 144. The witness shared with the Commission a video and several photos\nfrom the crime scene, which shows the bodies of eight men dressed in civilian clothes,\nmissing jackets and shoes. At least two men have their hands visibly tied behind their backs,\nand at least five victims have obvious gunshot injuries, three of them in the head, which is\nconsistent with the general pattern identified by the Commission."},{"id":"a-hrc-52-crp-4-p0328","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"328","seq":329,"section":"1. Personal integrity violations committed by Russian authorities","text":"Based on an analysis of the calls made by Russian soldiers on 4 March 2022 from two\nof the victims’ mobile phones, as well as of the items left behind by soldiers stationed at\nYablunska Street 144, journalists found strong indications that the perpetrators of the crime\nwere from the 234th Guards Airborne Assault Regiment. The Commission has independently\nconfirmed that forces from the 234 th Regiment were stationed in Bucha during the\noccupation.\nExecutions at children’s camp"},{"id":"a-hrc-52-crp-4-p0329","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"329","seq":330,"section":"1. Personal integrity violations committed by Russian authorities","text":"Family members last spoke with Volodymyr Leonidovych Boichenko (born 1987) on\n8 March 2022 and with Dmytro Vasylovych Shulmeister (born 1968) and Serhii Viktorovych\nMatyoshko (born 1981) on 12 March 2022. At the time, all three men were in Hostomel town,\nabout three kilometres from Bucha. Then the men’s mobile phones stopped working."},{"id":"a-hrc-52-crp-4-p0330","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"330","seq":331,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 4 April 2022, the bodies of Boichenko, Shulmeister and Matyoshko, together with\ntwo other identified men, were found in the basement of a building in a children's camp called\n“Promenystyi” or “Radiant” at Vokzalna Street 123 in Bucha.273"},{"id":"a-hrc-52-crp-4-p0331","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"331","seq":332,"section":"1. Personal integrity violations committed by Russian authorities","text":"Photos from the basement reviewed by the Commission show the bodies of five men\nin civilian clothes on their knees while facing a wall; four of them have their hands tied\nbehind their backs with a plastic zip tie. Bloodstains are visible on the ground and on the\nwall, and there are several bullet casings noticeable on the ground, indicating that the men\nwere shot. The injuries suggest that the victims were shot dead at close range, with at least\ntwo types of firearms."},{"id":"a-hrc-52-crp-4-p0332","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"332","seq":333,"section":"1. Personal integrity violations committed by Russian authorities","text":"Medical documents reviewed by the Commission show that Boichenko, Shulmeister\nand one of the two identified men died of multiple gunshot and shrapnel injuries to the torso,\nwhile the cause of death of Matyoshko were perforating gunshot injuries to the limbs and\ntorso with injury of internal organs. Photos from the morgue of two of the victims obtained\nby the Commission also show signs of repetitive blunt force trauma on the head and on the\ntorso, suggesting ill-treatment prior to death."},{"id":"a-hrc-52-crp-4-p0333","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"333","seq":334,"section":"1. Personal integrity violations committed by Russian authorities","text":"A witness told family members of two of the victims that Russian soldiers attacked\nand then detained the men as they were helping to evacuate residents. The Commission has\nnot been able to verify this information."},{"id":"a-hrc-52-crp-4-p0334","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"334","seq":335,"section":"1. Personal integrity violations committed by Russian authorities","text":"Items found at the camp by Ukrainian authorities and others corroborate the\nallegations that the children’s camp was used by Russian armed forces: discarded Russian\nuniforms, positions for military vehicles dug into the ground, boxes from Russian military\nrations, as well as civilian cars with white letter “V” sprayed on them. In an interview with a\nnews outlet, a man claimed that Russian soldiers had held and tortured him in this camp in\nearly March 2022, further corroborating the fact that Russian soldiers were using the premises\nat the time when the five men were killed.\nMass grave between Myrotske and Vorzel"},{"id":"a-hrc-52-crp-4-p0335","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"335","seq":336,"section":"1. Personal integrity violations committed by Russian authorities","text":"When many civilians evacuated from Bucha, Artur Oleksiiovych Rudenko (born\n1995) decided to stay to take care of his grandfather. On 11 March 2022, Rudenko told a\nfamily member on the phone that he was heading to his grandfather’s, about a kilometre\naway, with some food. That was the last time Rudenko’s family member spoke with him."},{"id":"a-hrc-52-crp-4-p0336","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"336","seq":337,"section":"1. Personal integrity violations committed by Russian authorities","text":"Rudenko’s body was found three months later, on 13 June 2022, in a forest area\nbetween villages Vorzel and Myrotske, a few kilometres from Bucha, in a mass grave\ntogether with six other bodies. Bucha, Vorzel and Myrotske were all under occupation by\nRussian armed forces at the time of Rudenko’s disappearance."},{"id":"a-hrc-52-crp-4-p0337","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"337","seq":338,"section":"1. Personal integrity violations committed by Russian authorities","text":"The six other victims found in the mass grave were all men, aged between 20 and 50\naccording to the police, but at the time of writing, only one other man had been identified.\nThe police told Rudenko’s family member that his hands were tied behind his back. Photos\nof the body reviewed by the Commission show presence of a nylon rope fastened at the wrist\narea of each hand."},{"id":"a-hrc-52-crp-4-p0338","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"338","seq":339,"section":"1. Personal integrity violations committed by Russian authorities","text":"The authorities were not able to establish Rudenko’s cause of death due to the\ndecomposition of the body. The photos of the body reviewed by the Commission suggest\nblunt force injury to the upper arm and chest regions."},{"id":"a-hrc-52-crp-4-p0339","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"339","seq":340,"section":"1. Personal integrity violations committed by Russian authorities","text":"The photos of the body also show that Rudenko had a tattoo of an owl which,\naccording to his family member, might have been the reason why he was targeted by the\nRussian armed forces, since an owl is used in insignia of Ukraine’s Defence Intelligence.\nHostomel town, Kyiv region"},{"id":"a-hrc-52-crp-4-p0340","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"340","seq":341,"section":"1. Personal integrity violations committed by Russian authorities","text":"Hostomel Airport was attacked from the early hours of the armed conflict and Russian\narmed forces were in control of the town for most of the month of March, until their\nwithdrawal on 31 March 2022. Information collected by the Commission indicates that\nseveral units of Russian armed forces were located in the town, including the 331st Guards\nAirborne Regiment of the 98th Guards Airborne Division; the 31st Guards Air Assault\nBrigade; and the 106th Guards Airborne Division.\nExecution at Sviato-Pokrovska Street"},{"id":"a-hrc-52-crp-4-p0341","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"341","seq":342,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 6 March 2022, Russian armed forces took over a residential house on Sviato-\nPokrovska Street 134 in Hostomel. Oleksii Oleksandrovych Kaluzhin (born 1992), who was\nstaying with his family in the neighbouring house, went outside to see what was happening.\nA witness recounted seeing Kaluzhin talking to Russian soldiers on the street. Kaluzhin asked\nthe witness to bring over his stepfather Andriy Ivanovych Vaskiv (born 1970), which he did."},{"id":"a-hrc-52-crp-4-p0342","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"342","seq":343,"section":"1. Personal integrity violations committed by Russian authorities","text":"When a relative went looking for the men later that day, she noticed a puddle of blood\nin front of the gate at house no. 134. However, Russian soldiers stationed in the house denied\nhaving apprehended the men. Another relative recalled seeing traces of blood, a hat, and a\nbroken phone in front of the same gate on 11 March 2022."},{"id":"a-hrc-52-crp-4-p0343","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"343","seq":344,"section":"1. Personal integrity violations committed by Russian authorities","text":"The bodies of Kaluzhin and Vaskiv were found one month later in the yard of the\nhouse on Sviato-Pokrovska Street 134. Photos of the bodies show that their hands were tied\nbehind their backs with a plastic cord. Both men had gunshot wounds to their heads. The tied\nhands and gunshot wounds to their heads are consistent with the overall pattern that the\nCommission has identified."},{"id":"a-hrc-52-crp-4-p0344","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"344","seq":345,"section":"1. Personal integrity violations committed by Russian authorities","text":"The victims’ relative mentioned that both men were passing information about\nRussian troops’ movement to the Ukrainian armed forces, and suspects that this is why they\nwere killed.\nExecution at Rekunova Street"},{"id":"a-hrc-52-crp-4-p0345","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"345","seq":346,"section":"1. Personal integrity violations committed by Russian authorities","text":"In the early hours of 13 March 2022, Serhii Volodymyrovych Zakhliupanyi (born\n1983), who was sheltering with other civilians in the basement of a building on Rekunova\nStreet 9, in Hostomel town, went outside to look for his dog who had run away. A resident\nwho was sheltering there told the Commission that when Zakhliupanyi returned to the\nbasement, Russian soldiers came after him. After having ordered him to undress to look for\ntattoos, they took him away."},{"id":"a-hrc-52-crp-4-p0346","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"346","seq":347,"section":"1. Personal integrity violations committed by Russian authorities","text":"Zakhliupanyi’s body was found about a week later in a garage on Rekunova Street.\nAccording to the witness who found the body, Zakhliupanyi was lying on his stomach,\nwearing only a t-shirt, underwear, and socks. His hands were behind his back, as if they had\nbeen tied previously, but untied later. His head was covered with a piece of fabric. The\nwitness recalled that Zakhliupanyi had had an “oseledets” – a traditional Ukrainian style of\nhaircut that features a long lock of hair left on the top of an otherwise shaved head."},{"id":"a-hrc-52-crp-4-p0347","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"347","seq":348,"section":"1. Personal integrity violations committed by Russian authorities","text":"According to a medical certificate, Zakhliupanyi died of multiple gunshot wounds to\nthe head and chest. A relative of the victim mentioned that three bullets were found on the\nground under his body, indicating that he was shot in the garage.\nHavronshchyna village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0348","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"348","seq":349,"section":"1. Personal integrity violations committed by Russian authorities","text":"Around 26 February 2022, Russian military vehicles with a white letter “V” appeared\nin Havronshchyna and Russian armed forces set up a base in the premises of a golf club on\nthe outskirts of the village. Russian soldiers withdrew from the area on 30 March 2022.\nExecutions near the house of culture"},{"id":"a-hrc-52-crp-4-p0349","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"349","seq":350,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 3 March 2022, around noon, a resident saw through his window a group of five\nsoldiers interrogating two men274 in civilian clothes in front of a shop on Kyivska street, near\nthe house of culture, in Havronshchyna. After a while, the soldiers let the older man go, while\nthe younger man was forced to lie down and undress from the waist up. Two soldiers then\nled him behind the shop, and the witness heard two gunshots."},{"id":"a-hrc-52-crp-4-p0350","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"350","seq":351,"section":"1. Personal integrity violations committed by Russian authorities","text":"Another witness saw Russian soldiers breaking into the shop and heard several shots\nshortly thereafter. He said that soon after that, four Russian soldiers appeared at his house\nlocated nearby, forced him to lie on the ground, and briefly interrogated him. Later in the\nday, the witness and a few local men found the body of the young man behind the shop.\nMedical documents reviewed by the Commission show that he was shot in the head and neck."},{"id":"a-hrc-52-crp-4-p0351","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"351","seq":352,"section":"1. Personal integrity violations committed by Russian authorities","text":"A few minutes after the above incident, the first witness saw the same five soldiers\nshooting from automatic weapons at a target not visible to him in front of his gate, not far\nfrom the shop. The soldiers then looked closer at the object of their attack, exchanged a few\nwords, and left in the direction of the shop. Later on the same day, the first witness and local\nmen found at this location the body of Volodymyr Ivanovych Patsan (born 1952), an\nemployee at a dam near the village. He was last seen that morning, as he left his home to\ncycle to the shop hoping to find bread."},{"id":"a-hrc-52-crp-4-p0352","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"352","seq":353,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 3 March 2022, residents also found the body of the father of the young man killed\nbehind the shop. The body was found close to the building of the house of culture, across the\nstreet from the shop. According to the medical documents, he died of “gunshot injury of the\nleft thigh”. The Commission has not been able to establish with certainty the identity of the\nolder man whom the Russian soldiers interrogated in front of the shop."},{"id":"a-hrc-52-crp-4-p0353","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"353","seq":354,"section":"1. Personal integrity violations committed by Russian authorities","text":"Finally, another resident found a fourth body behind the building of the house of\nculture on 5 March 2022. It belonged to a man who went missing on or around 3 March 2022.\nThe Commission reviewed the photos of the body and concluded that the victim most\nprobably died of a gunshot injury to the back of the head.\nKolonshchyna village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0354","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"354","seq":355,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 1 March 2022, Russian armed forces entered Kolonshchyna. They were mostly\nstationed in the surrounding villages and only occupied a few empty houses on the edge of\nthe village. Russian soldiers withdrew from the area on 30 March 2022.\nExecution near a house outside of the village"},{"id":"a-hrc-52-crp-4-p0355","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"355","seq":356,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 10 March 2022, at around noon, Serhii Stanislavovych Sverblianskyi (born 1979)\nleft home together with his neighbour, a 14-year-old boy, to walk to a friend’s empty house\nto charge an accumulator with solar panels. Sverbliyanskiy and his wife had a medium-sized\nanimal farm that depended on electricity, which was cut in late February 2022 after a plane\nwas shot down over the village, taking down the electric wires as it fell. Due to the cold\nweather, Sverbliyanskiy was wearing warm camouflage fleece trousers. He attached a white\ncloth to the bicycle on which he carried the accumulator."},{"id":"a-hrc-52-crp-4-p0356","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"356","seq":357,"section":"1. Personal integrity violations committed by Russian authorities","text":"The bodies of Sverbliyanskiy and the boy were found on 15 March 2022, close to the\nhouse with the solar panels. According to medical documents reviewed by the Commission,\nSverbliyanskiy died of perforating gunshot wound to the head, while the cause of death of\nthe 14-year-old boy was an open head injury, also consistent with a gunshot wound.\nMotyzhyn village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0357","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"357","seq":358,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 27 February 2022, Russian armed forces arrived in Motyzhyn and stayed until 27\nMarch 2022. The village was partly occupied, but the Ukrainian Territorial Defence Forces\nappear to have been active during this period. After some defeats, Russian soldiers turned\nagainst those from the local population whom they suspected of supporting the Ukrainian\narmed forces."},{"id":"a-hrc-52-crp-4-p0358","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"358","seq":359,"section":"1. Personal integrity violations committed by Russian authorities","text":"Ukrainian authorities have established that the 37th Motorized Rifle Brigade had been\nbased in Motyzhyn. In a press release, the Office of the General Prosecutor of Ukraine\nidentified eight Russian soldiers as responsible for the execution, killings, and torture in the\nvillage. Of these soldiers, five belonged to the 37th Motorized Rifle Brigade, and three to the\nWagner Group.\nExecutions in a forest and at a farm"},{"id":"a-hrc-52-crp-4-p0359","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"359","seq":360,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 23 March 2022, Russian soldiers detained the head of the village, Olha Petrivna\nSukhenko, her husband Ihor and her adult son Oleksandr. They were interrogated and\neventually executed. A witness who was himself held, interrogated, and tortured at a farm\nnortheast of Motyzhyn, where Russian armed forces set up a base, recounted how the soldiers\ntold him: “Your Olga Petrovna, she also first said that they are only feeding old ladies here.\nBut once we started to beat her, once we shot her in the legs, she confessed everything: about\nTerritorial Defence Forces, about the weapons.”"},{"id":"a-hrc-52-crp-4-p0360","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"360","seq":361,"section":"1. Personal integrity violations committed by Russian authorities","text":"On the same day, 23 March 2022, two identified men275, both members of the\nTerritorial Defence Forces and armed, left from Boyarka to Motyzhyn to distribute\nhumanitarian aid. Their relatives subsequently lost contact with them."},{"id":"a-hrc-52-crp-4-p0361","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"361","seq":362,"section":"1. Personal integrity violations committed by Russian authorities","text":"The bodies of Sukhenko, her husband and her son, as well as that of one of the two\nmembers of the Territorial Defence Forces, were found in a makeshift grave in a forest\nnortheast of Motyzhyn. According to a witness who participated in the exhumation of the\nbodies, Sukhenko was shot in the back, her husband had a gunshot wound in his head and his\nhands were broken. Their son had gunshot wound in his knee and in the side of his torso, and\na red cloth wrapped around his head. The body of the member of the Territorial Defence\nForces was bruised and in part naked. His relative, who also participated in the exhumation,\nrecalled that the man’s hands were tied with a plastic zip tie, he had a gunshot wound in his\nforehead and his body was covered with bruises."},{"id":"a-hrc-52-crp-4-p0362","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"362","seq":363,"section":"1. Personal integrity violations committed by Russian authorities","text":"The Commission visited the site of the grave and a few meters away, observed a\nbunker made of wood and dirt, dug-up holes spread through the woods, as well as an empty\nammunition box. These findings are consistent with the claim that Russian armed forces and\nmilitary vehicles had been stationed there."},{"id":"a-hrc-52-crp-4-p0363","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"363","seq":364,"section":"1. Personal integrity violations committed by Russian authorities","text":"The body of the second member of the Territorial Defence Forces was found\naccidentally by a journalist under the rubble of a destroyed house at a farm that Russian\narmed forces used as a base. Photos reviewed by the Commission show that the man’s hands\nwere tied, and his trousers and underwear were pulled down to his ankles. Three gunshot\nwounds are clearly visible on the back of his head, and the pattern of injury on the head, neck,\nand gluteal region is highly suggestive of ill-treatment before death. According to a witness\nwho saw the body when it was found, the victim also had gunshot wounds in his knees, and\nhis face was injured beyond recognition."},{"id":"a-hrc-52-crp-4-p0364","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"364","seq":365,"section":"1. Personal integrity violations committed by Russian authorities","text":"Finally, the body of an unidentified man was found in a manhole on the grounds of\nthe farm. According to a witness, who was held in the same manhole, Russian soldiers\ninterrogated the victim during one hour and a half, beat him, shot him in his legs, and broke\nhis arms, before finally killing him. A photo of the victim reviewed by the Commission shows\na pattern of injury on the left arm and the torso, which is consistent with ill-treatment or\ntorture prior to death."},{"id":"a-hrc-52-crp-4-p0365","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"365","seq":366,"section":"1. Personal integrity violations committed by Russian authorities","text":"The witness who was held in the manhole was arrested around the same time as the\nother victims - on 24 March 2022. He was beaten, interrogated, threatened with execution,\nand brought to the farm. There, he was placed in the manhole for 48 hours, during which he\nreceived no food or water. The space was so confined that he could neither sit nor stand, and\nafter two days he was not able to walk. Russian soldiers that detained him stressed the\nimportance of him being blindfolded: “The most important thing is that you don’t see\nanything, because if you do, you won’t leave this place alive.” The witness survived thanks\nto some of the Russian soldiers, who took him out of the manhole, and gave him food. When\nthe Russian armed forces were withdrawing from Motyzhyn, the same soldiers refused to\nfollow instructions and instead of killing him, they let him go.\n275 The Commission knows the names of the two other men. Their families have not wished that they be\nmade public.\nPeremoha village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0366","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"366","seq":367,"section":"1. Personal integrity violations committed by Russian authorities","text":"Russian armed forces entered Peremoha on 28 February 2022 and remained in control\nof the village until the end of March 2022."},{"id":"a-hrc-52-crp-4-p0367","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"367","seq":368,"section":"1. Personal integrity violations committed by Russian authorities","text":"Journalists found indications regarding the presence of two Russian armed forces units\nin Peremoha: the 2nd Guards Combined Arms Army and the 15th Brigade Motorised Rifle\nCompany. The Commission obtained a document which indicates that the 21 st Brigade had a\nforward command post in the village at least from 6 March 2022.\nExecutions at the post office"},{"id":"a-hrc-52-crp-4-p0368","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"368","seq":369,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 1 March 2022, Russian soldiers stopped and interrogated two men as they were\npassing the building of the village council. One of the men noticed that another group of\nsoldiers was walking nearby with his younger relative Yuriy Krasnozhon (born 1988), his\nhands tied behind his back and his face bearing signs of beating. He tried to protest, but the\nsoldiers beat him, put him on the ground, tied his hands and put his hat inside his mouth.\nThey did the same with the other man – Ivan Tretiak (born 1981) and led the three of them\nto the building of the post office. There, the soldiers brought Krasnozhon and Tretiak to the\nbasement and ordered the older relative to show them the house of a suspected member of\nthe Ukrainian Territorial Defence Forces. While they were walking, shelling started, and he\nmanaged to escape."},{"id":"a-hrc-52-crp-4-p0369","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"369","seq":370,"section":"1. Personal integrity violations committed by Russian authorities","text":"A news outlet interviewed another survivor, who was detained on 28 February 2022\nand similarly brought to the building of the post office. He said that he was interrogated,\nthreatened, and witnessed the execution of two other civilian men who were already in the\nbasement when he was brought there. He said that he overheard Russian soldiers discussing\nabout their intention to destroy the building to hide the evidence of the killings."},{"id":"a-hrc-52-crp-4-p0370","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"370","seq":371,"section":"1. Personal integrity violations committed by Russian authorities","text":"The bodies of Krasnozhon and Tretyak, together with those of six other men, were\nfound in the ruins of the post office building, which exploded sometime in March 2022. All\nbut one body had been identified. However, due to the explosion, the cause of death of the\nvictims could not be established. According to a resident of Peremoha interviewed by the\nCommission, at least three of the men were members of the Ukrainian Territorial Defence\nForces.\nShevchenkove village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0371","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"371","seq":372,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 8 March 2022, Russian armed forces entered Shevchenkove village and controlled\nit until 30 March 2022.\nExecutions on Hoholivska Street"},{"id":"a-hrc-52-crp-4-p0372","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"372","seq":373,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 17 March 2022, Oleh Yevheniyovych Mironov (born 1971) went to the centre of\nShevchenkove village to see whether evacuation of civilians would be possible. He did not\ncome back home."},{"id":"a-hrc-52-crp-4-p0373","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"373","seq":374,"section":"1. Personal integrity violations committed by Russian authorities","text":"A week later, on 24 March 2022, Eduard Viktorovych Shpylovyi (born 1974) left his\nhouse in Bohdanivka village, about 12 km east from Shevchenkove. He did not come back\nhome."},{"id":"a-hrc-52-crp-4-p0374","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"374","seq":375,"section":"1. Personal integrity violations committed by Russian authorities","text":"On the following day, 25 March 2022, a third identified man (born 1980)276 left home\nto collect humanitarian aid near the railway tracks. He did not return. A relative of the man\ninquired with Russian soldiers about his whereabouts. They did not reply to the question, but\ncorrectly named the street where he and his family lived. The relative took this as an\nindication that the man was in their custody."},{"id":"a-hrc-52-crp-4-p0375","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"375","seq":376,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 25 March 2022, witnesses saw the brothers Vitaliy and Mykola Vasyliovych Korol\n(born 1978 and 1979) entering their house accompanied by five soldiers. The soldiers\nappeared in the house again on the following day, this time only with Mykola."},{"id":"a-hrc-52-crp-4-p0376","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"376","seq":377,"section":"1. Personal integrity violations committed by Russian authorities","text":"After the withdrawal of Russian forces from Shevchenkove village in the beginning\nof April 2022, the owner of a house on Hoholivska Street 21 found six bodies in an outdoor\ncellar near his house, not far from the railway tracks. Five of them were identified as Oleh\nMironov, Eduard Shpilovyi, the third identified man, and Vitaliy and Mykola Korol."},{"id":"a-hrc-52-crp-4-p0377","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"377","seq":378,"section":"1. Personal integrity violations committed by Russian authorities","text":"All the victims were wearing civilian clothes and four bodies had visible white ribbon\non their sleeves, underlining their civilian status. Photos of the bodies, as well as medical\ndocuments, show that Eduard Shpylovyi, the third identified man and the Korol brothers were\nshot in the head, while Oleh Mironov died of gunshot wounds to the torso and lower limbs."},{"id":"a-hrc-52-crp-4-p0378","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"378","seq":379,"section":"1. Personal integrity violations committed by Russian authorities","text":"The house where the bodies were found, was vandalized, and looted. Dozens of empty\nboxes of Russian military rations, military boots, and mattresses found by the owner indicate\nthat it was used by Russian soldiers during their occupation of Shevchenkove village.\nExecution on Lesi Ukrainky Street"},{"id":"a-hrc-52-crp-4-p0379","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"379","seq":380,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 24 March 2022, at around 2 p.m., Serhii Serhiiovych Mykhailichenko (born 1983)\nleft his home to go to the train station where a bread distribution had been announced.\nAccording to a witness, a group of Russian soldiers, accompanied by residents of the village\ncollaborating with them, called on Mykhailichenko and asked him to follow them. They\nwalked with him back to his home where two witnesses saw Mykhailichenko handing them\na weapon, after which the Russian soldiers and the residents left. The witness briefly talked\nto Mykhailichenko, who was still shaken and kept repeating “They almost killed me!”. A few\nminutes later, one of the residents who previously accompanied Russian soldiers returned\nand asked Mykhailichenko to follow him. A few seconds later, two witnesses confirmed\nhearing two gunshots. One eyewitness saw the victim falling down after the shots, though\ncould not see who had fired the weapon, as Mykhailichenko was taller than the person who\naccompanied him."},{"id":"a-hrc-52-crp-4-p0380","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"380","seq":381,"section":"1. Personal integrity violations committed by Russian authorities","text":"An uninhabited house about 50 m from Mykhailichenko’s was set on fire on the\nafternoon of the same day, shortly after the above events. The next day, residents found a\nburned body in the remains of the house. A close relative identified the remains as those of\nMykhailichenko.\nVyshehrad village, Kyiv region"},{"id":"a-hrc-52-crp-4-p0381","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"381","seq":382,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 4 March 2022, Russian armed forces arrived to Vyshehrad village and began a\nhouse-to-house search. They occupied several houses in the village and, according to several\naccounts, set up a camp in the nearby forest. A woman reported that Russian soldiers had\nbrought her to this camp after injuring her. Another witness saw the location after the\ndeparture of Russian armed forces and reported the presence of burned military vehicles,\ndugouts, and items looted from his own house, located on the edge of the village.\nExecutions on the western edge of the village"},{"id":"a-hrc-52-crp-4-p0382","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"382","seq":383,"section":"1. Personal integrity violations committed by Russian authorities","text":"Serhii Ivanovych Kislitskyi (born 1983) and Stanislav Viktorovych Holian (born\n1982) were construction workers living in a house they were renovating on the western edge\nof the village, less than 100 m from the forest. The owner of the house was last in telephone\ncontact with the men on 27 February 2022, whereas Holian’s close relative last spoke to him\non 1 March 2022. Two neighbours recalled seeing the men around 3 March 2022, just before\nRussian forces arrived."},{"id":"a-hrc-52-crp-4-p0383","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"383","seq":384,"section":"1. Personal integrity violations committed by Russian authorities","text":"When a resident of the village asked permission from Russian soldiers to check on\nKislitskyi and Holian, they told him to stay away from the house, which was by then taken\nover by Russian armed forces. Another neighbour inquired with Russian soldiers about what\nhappened to the two men. They told him that they had heard that the men were shot dead in\nthe forest by another group of Russian soldiers who carried out the sweep operation in the\nvillage on 4 March 2022."},{"id":"a-hrc-52-crp-4-p0384","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"384","seq":385,"section":"1. Personal integrity violations committed by Russian authorities","text":"Kislitskyi’s and Holian’s bodies were found buried about 20 m from each other in the\nVyshehrad’s forest on 27 May 2022 and in early June 2022, respectively. Both men were\nbarefoot, wearing civilian clothes, and their bodies were in a state of decomposition. Medical\ncertificates show that both men died of perforating gunshot wounds to the head. Furthermore,\nphotos from the exhumation of Serhii Kislitskyi reviewed by the Commission show multiple\nblunt force traumas to the torso of the victim suggesting ill-treatment or torture prior to death."},{"id":"a-hrc-52-crp-4-p0385","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"385","seq":386,"section":"1. Personal integrity violations committed by Russian authorities","text":"Yuriy Hryhorovych Makeev (born 1960) lived across the street from Kislitskyi and\nHolian. His family last spoke with him on 3 March 2022. His body was found a few days\nlater. He was lying on his bed with signs of beating and multiple bruises, especially in the\nabdominal area, and a gunshot wound to his head. A resident of Vyshehrad recounted how a\nRussian soldier staying at her house admitted that his group killed Makeev, claiming that he\ntried to throw a Molotov cocktail at them."},{"id":"a-hrc-52-crp-4-p0386","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"386","seq":387,"section":"1. Personal integrity violations committed by Russian authorities","text":"In addition to the cases described, there are credible allegations that at least one more\nman was shot dead on the day of the arrival of Russian armed forces into the village.\nIvanivka village, Chernihiv region"},{"id":"a-hrc-52-crp-4-p0387","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"387","seq":388,"section":"1. Personal integrity violations committed by Russian authorities","text":"Russian armed forces entered the village of Ivanivka on 5 March 2022 and controlled\nit until 30 March 2022. The Commission collected information indicating that forces from\nthe 74th Separate Guards Motorized Rifle Brigade were located in the village.\nExecutions at an agricultural complex"},{"id":"a-hrc-52-crp-4-p0388","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"388","seq":389,"section":"1. Personal integrity violations committed by Russian authorities","text":"Russian armed forces established one of their bases in the area of an agricultural\ncomplex on the outskirts of Ivanivka village. After they withdrew from the area, bodies of\nfour men were found in the area of the complex. Two were identified as Serhii Yevheniiovych\nKorinev (born 1988) and Maksym Volodymyrovych Ternov (born 1981); the identity of the\nremaining two victims is not known."},{"id":"a-hrc-52-crp-4-p0389","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"389","seq":390,"section":"1. Personal integrity violations committed by Russian authorities","text":"Serhii Korinev disappeared on 9 March 2022, after stepping out of his family’s house\non Shcherbyny Street to smoke. His body was found on 31 March 2022 in a small building\nin the agricultural complex. The hands were tied with a zip tie; his head was wrapped in a\ndirty bandana, which, when removed, revealed a gunshot wound to the head. According to\none witness who saw Korinev’s body when it was found, his face was purple and so swollen\nthat his mother had to recognize him by his shoes. He had bruises on his face and body and\ninjuries on his hands. A copy of the medical report obtained by the Commission indicates\nperforating gunshot wound to the head with skull fracture as Korinev’s cause of death."},{"id":"a-hrc-52-crp-4-p0390","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"390","seq":391,"section":"1. Personal integrity violations committed by Russian authorities","text":"Maksym Ternov left his home in Cherkasy on 13 March 2022 with the plan to drive\nto Chernihiv. The following morning, his family heard from him for the last time. One\nresident of the village Yahidne saw Ternov as he was brought by Russian soldiers to the\nbasement of a school where 365 civilians were confined by Russian forces for several weeks\n(see paras. 541-543). The witness reported that Ternov spent one night in the school basement\nand was seen standing outside the following morning. Ternov’s body was found at the\nbeginning of April 2022, about 300 m from that of Korinev, in a small building of the same\nagricultural complex in Ivanivka. Ternov’s hands and feet were tied, his face was covered\nwith bruises and blood. From the photos reviewed by the Commission, including from the\nmorgue, Ternov’s body bore multiple blunt force traumas on his head and torso, suggesting\nill-treatment or torture prior to his death. A witness who saw Ternov’s body when it was\nfound spoke of a visible gunshot injury to his head. Indeed, “gunshot wound to the head with\ncranial bone injury” was the main cause of his death based on the copy of the medical report\nwhich the Commission has obtained."},{"id":"a-hrc-52-crp-4-p0391","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"391","seq":392,"section":"1. Personal integrity violations committed by Russian authorities","text":"The body of one of the unknown men was found about 200 m from the body of\nKorinev, and the body of the other unknown man was found nearby the building where the\nbody of Ternov was uncovered. Those who discovered the first body described it as that of a\nman with his hands tied with the same type of zip tie as Korinev, his face covered in blood,\nwith bruises on both his face and body. There was no obvious cause of death. The body of\nthe second man appeared naked and was in an advanced state of decomposition. The\nCommission reviewed a photo of the body and assessed that it might have been set afire after\nthe death and exposed to stray animals.\nStaryi Bykiv village, Chernihiv region"},{"id":"a-hrc-52-crp-4-p0392","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"392","seq":393,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 27 February 2022, Russian armed forces entered Staryi Bykiv village and\ncontrolled it until 31 March 2022. A document that journalists found at the base of the\nRussian armed forces in Vyshneve, Chernihiv region, indicates that the forward command\npost of the 30th Separate Motorized Rifle Brigade was located in adjacent Novyi Bykiv\nvillage on 6 March 2022.\nExecution on Tsentralna Street"},{"id":"a-hrc-52-crp-4-p0393","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"393","seq":394,"section":"1. Personal integrity violations committed by Russian authorities","text":"On the day of their arrival to Staryi Bykiv village, Russian armed forces apprehended\nsix local men at their homes: Volodymyr Hryhorovych Putiata (born 1975), Oleksandr\nVolodymyrovych Mohyrchuk (born 1983), and four other identified men. 277 The soldiers\nwere looking for those who had operated a drone that killed one of their soldiers earlier that\nday."},{"id":"a-hrc-52-crp-4-p0394","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"394","seq":395,"section":"1. Personal integrity violations committed by Russian authorities","text":"Later the same day, relatives went to the place Russian armed forces used, to search\nfor the missing men. Soldiers told them that the men would be released after being\ninterrogated. About 20 minutes later, the relatives heard screams coming from the base,\nfollowed by gunshots."},{"id":"a-hrc-52-crp-4-p0395","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"395","seq":396,"section":"1. Personal integrity violations committed by Russian authorities","text":"The next morning, witnesses saw the bodies of the six men lying on the street, about\n300 m from where their relatives had heard the gunshots. The victims had multiple gunshot\nwounds, stab wounds, blunt traumas, a slit throat, and broken ribs. This is confirmed by\nmedical documents of two of the victims and other evidence reviewed by the Commission.\nIt took nine days before Russian soldiers allowed the relatives to recover and bury the bodies.\nYahidne village, Chernihiv region"},{"id":"a-hrc-52-crp-4-p0396","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"396","seq":397,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 3 March 2022, Russian military vehicles with white circles painted on them\nentered Yahidne village. Russian armed forces occupied the village until 30 March 2022. The\nCommission collected information indicating that forces from several units were located in\nor near the town, including the 55 th Separate Motorized Rifle Brigade, the 74th Separate\nGuards Motorized Rifle Brigade, and the 228th Motorized Rifle Regiment.\nExecution at Vyshneva Street"},{"id":"a-hrc-52-crp-4-p0397","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"397","seq":398,"section":"1. Personal integrity violations committed by Russian authorities","text":"Relatives were last in contact with Viktor Mykhailovych Shevchenko (born 1971) in\nthe afternoon of 3 March 2022, the day Russian armed forces entered Yahidne village.\nAccording to a neighbour, a group of Russian soldiers parked their military vehicles in\nShevchenko’s yard and moved into his house."},{"id":"a-hrc-52-crp-4-p0398","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"398","seq":399,"section":"1. Personal integrity violations committed by Russian authorities","text":"Another neighbour recounted that the following day, a group of Russian soldiers\ninquired about the presence of Ukrainian armed forces in the village. According to him, the\nsoldiers said that they had shot Shevchenko when they found a military uniform and a photo\nof him in it, suggesting that he had served in the military."},{"id":"a-hrc-52-crp-4-p0399","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"399","seq":400,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 21 March 2022, the first witness saw Russian soldiers digging the ground behind\nthe barn near Shevchenko’s house. About two hours later, a soldier informed the witness that\nthey had buried Shevchenko and explained that he had been ill for a long time. However,\nmedical documents reviewed by the Commission show that the victim died of a perforating\ngunshot wound to the head."},{"id":"a-hrc-52-crp-4-p0400","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"400","seq":401,"section":"1. Personal integrity violations committed by Russian authorities","text":"The witness later saw a makeshift grave in the victim’s yard. There was a plate with\nthe victim’s full name, his date of birth and date of death – 3 March 2022.\nExecution at Yabluneva Street"},{"id":"a-hrc-52-crp-4-p0401","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"401","seq":402,"section":"1. Personal integrity violations committed by Russian authorities","text":"A video technician (born 1991) at the television broadcaster Ditinets, was sheltering\nwith his family in the basement of a house in Yahidne village. A close relative reported to a\n277 The Commission knows the name of the four men but has not been able to establish contact with\ntheir families.\nnews outlet that Russian soldiers took the man away on 5 March 2022 after they discovered\nthat he had a phone."},{"id":"a-hrc-52-crp-4-p0402","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"402","seq":403,"section":"1. Personal integrity violations committed by Russian authorities","text":"On 9 March 2022, a resident accompanied by Russian soldiers noticed a body lying\nunder a tree. After she recognized the body as a resident of Yahidne, the soldiers asked her\nto identify two more bodies located in the basement of a house nearby, on Yabluneva Street"},{"id":"a-hrc-52-crp-4-u0404","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":null,"seq":404,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"witness, who was brought to the same basement by Russian soldiers to bury the bodies. He\nstated that both men had gunshot injuries to their heads and their bodies, and their faces bore\ntraces of beating. The unidentified man had his hands tied, similar to many other victims of\nexecutions.","unnumbered":true},{"id":"a-hrc-52-crp-4-p0403","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"403","seq":405,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"According to a witness with good knowledge of the house on Yabluneva Street 26, in\nthe basement of which the bodies were found, it had been at that time occupied by Russian\nsoldiers from Tuva.\nBilka village, Sumy region"},{"id":"a-hrc-52-crp-4-p0404","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"404","seq":406,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"A large contingent of Russian armed forces arrived in Bilka village on 2 March 2022\nand set up base at a farm located on a small hill on the western outskirts. They left the farm\non 16 March 2022.\nExecutions at a farm"},{"id":"a-hrc-52-crp-4-p0405","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"405","seq":407,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Oleg Volodymyrovych Malenko (born 1977) left from nearby Oleksyne village, to\nreturn to his house in Bilka in the early evening of 3 March 2022. He never arrived. On\n17 March 2022, the day after Russian armed forces vacated the farm, residents discovered\nMalenko’s body in a nearby field. Photos and witness descriptions of the body show that his\nhands and feet were tied together with a green rope. He had a gunshot wound to the head\nbehind the ear and three oval bruises on the anterior neck. A relative who washed the body\nnoticed further bruises on his legs, ribs, and groin. An analysis of the available photographs\nsuggests manual strangulation and that death was then caused by a gunshot wound to the\nhead."},{"id":"a-hrc-52-crp-4-p0406","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"406","seq":408,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Mykola Ivanovych Savchenko (born 1976) left his house in Bilka in the morning of\n3 March 2022. He never returned. One resident who spoke with Savchenko on the phone that\nmorning, said that he was planning to go to the farm. On 20 March 2022, Ukrainian armed\nforces, who had taken over the farm when the Russian armed forces left, guided residents to\nan adjacent field where they had discovered Savchenko’s body. According to photos and\nwitness descriptions of the body, he was lying face down with a woollen hat pulled over his\neyes. There were significant traces of blood on his face. There were two gunshot wounds to\nthe chest. Two spent bullet cases were lying on the ground near the body, suggesting that he\nwas shot at close range.\nTrostianets town, Sumy region"},{"id":"a-hrc-52-crp-4-p0407","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"407","seq":409,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Russian armed forces entered Trostianets town on 24 February 2022 and remained in\ncontrol until 26 March 2022.\nExecution at “Kernel”"},{"id":"a-hrc-52-crp-4-p0408","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"408","seq":410,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Viktoria Volodymyrovna Ivanova (born 1969) was a member of a group that was\nrecording and sharing information about Russian troop movements with Ukrainian armed\nforces. On 13 March 2022, Ivanova left her house to go for a walk at the local cemetery but\ndid not return home. On the following day, a close relative went looking for her. Russian\nsoldiers at a checkpoint nearby told him that they indeed saw Ivanova the previous day, but\nthey did not allow her to enter the cemetery and sent her back."},{"id":"a-hrc-52-crp-4-p0409","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"409","seq":411,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On the day Ivanova disappeared, men in Russian military uniforms detained four male\nresidents from Trostianets, including at least one who was a member of same group as her.\nThey brought the men to TOV Kononivskyi Elevator, an agricultural facility referred to as\nthe “Kernel”, interrogated and beat at least two of them, and released them after less than 24\nhours. One of them recalled hearing gunshots while detained at Kernel."},{"id":"a-hrc-52-crp-4-p0410","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"410","seq":412,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Two months later, on 19 May 2022, a worker of the Kernel facility found Ivanova’s\ndecomposed body in a makeshift grave on the grounds of the facility. Medical documents\nreviewed by the Commission show that she died of a gunshot wound to the head.\nHusarivka village, Kharkiv region"},{"id":"a-hrc-52-crp-4-p0411","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"411","seq":413,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Russian armed forces entered Husarivka village sometime in early March 2022, and\na group of soldiers set up base in the first four houses on Oksana Petrusenko Street. They\nremained in control of the village until 26 March 2022. The Commission collected\ninformation indicating that forces from the 18th Guards Motor Rifle Division of the 11th\nArmy Corps were located there.\nExecutions on Oksana Petrusenko Street"},{"id":"a-hrc-52-crp-4-p0412","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"412","seq":414,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 13 March 2022, Russian soldiers stationed at Oksana Petrusenko Street asked a\ngroup of farm workers, including Yehor Volodymyrovych Zhyrovkin (born 1985) and\nOleksandr Volodymyrovych Tarusin (born 1982), to feed cattle at a nearby milk farm. The\nRussian armed forces came under shelling while the men were tending to the animals. They\naccused them of having directed the fire and detained them. Not long thereafter, a witness\naccompanied by Russian soldiers near that location heard a series of gunshots. As he entered\nthe first house on Oksana Petrusenko Street, he saw five men whom he recognized as the said\nfarm workers, lying on the ground in the yard, screaming with pain from gunshot wounds in\ntheir legs. Soldiers placed the witness in a cellar, from where he subsequently heard more\ngunshots. When the soldiers took him out shortly afterwards, he saw five lifeless bodies lying\nin the yard."},{"id":"a-hrc-52-crp-4-p0413","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"413","seq":415,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Two days after the above events, on 15 March 2022, Mykola Mykhailovych Pisarev\n(born 1965) and Oleksandr Oleksiiovych Pokhodenko (born 1978) left their apartment in the\ncentre of the village and walked to the house of a relative, which was located about 200 m\nfrom the milk farm. They did not return."},{"id":"a-hrc-52-crp-4-p0414","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"414","seq":416,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 7 April 2022, three bodies burned beyond recognition were found in an outdoor\ncellar of the second house on Oksana Petrusenko Street. As of January 2023, they had not\nbeen identified. Two weeks later, on 22 April 2022, less than 200 m away, two more burned\nbodies were found in a similar outdoor cellar of another house. The forensic analysis showed\nthat they were the bodies of Pisarev and Pokhodenko. The Commission reviewed medical\ndocuments which show that Pisarev died of stab wounds to the neck and subsequent blood\nloss whereas Pokhodenko was shot in the chest.\nKapytolivka village, Kharkiv region"},{"id":"a-hrc-52-crp-4-p0415","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"415","seq":417,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Russian armed forces entered Kapytolivka village on 7 March 2022. At the end of\nMarch or beginning of April, they were joined by forces from the so-called Luhansk People’s\nRepublic. They remained in control of the village until around 9 September 2022.\nExecution in a forest"},{"id":"a-hrc-52-crp-4-p0416","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"416","seq":418,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 23 March 2022, Ivan Hryhorovych Shabelnik (born 1971) and Leonid Vasilievych\nTaran (born 1946) left their house in Kapytolivka and walked to the forest to collect\npinecones for the fire. They did not return. Their relatives searched for them in the village\nand wrote a letter to the Military Prosecutor based in Izium, but with no result."},{"id":"a-hrc-52-crp-4-p0417","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"417","seq":419,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"A man who was detained on 24 March 2022 by soldiers from the so-called Luhansk\nPeople’s Republic told the relatives of Shabelnik and Taran that he saw the two men in one\nof the four adjacent houses that the forces occupied on Luhovaya Street. The witness said\nthat the soldiers took Shabelnik upstairs several times and he could hear screams every time.\nHe further reported that two days later, the soldiers brought a third man to the basement and\nbeat him several times. The man was reportedly a veteran of the former Anti-Terrorist\nOperation in East Ukraine. The witness was then released."},{"id":"a-hrc-52-crp-4-p0418","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"418","seq":420,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The bodies of Shabelnik and Taran, in a state of decomposition, were found in August\n2022 in a forest south of Kapytolivka. Medical documents reviewed by the Commission show\nthat Shabelnik died of chest trauma and multiple broken ribs, while Taran died of gunshot\nwounds. The body of the third man who was also seen in detention was found in the same\nplace.\nVesele village, Kharkiv region\nExecution next to a bus"},{"id":"a-hrc-52-crp-4-p0419","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"419","seq":421,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On the night from 28 to 29 March 2022, three buses bringing about 90 civilians to\nBelgorod, Russian Federation, stopped near the village Vesele, about 8 km from the border.\nTwo witnesses on separate buses described seeing a group of Russian soldiers taking two\nyoung men off a bus. They interrogated the men next to the bus and beat them heavily,\nincluding with rifle butts. One man was then taken about 100 m further away, made to kneel\nand shot in the head. One witness said that she then covered her face with her hands and did\nnot see what happened to the other man, but people on the bus told her that he was also shot\nand killed."},{"id":"a-hrc-52-crp-4-p0420","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"420","seq":422,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"According to one witness, after the incident, a Russian soldier entered the bus and\nexplained that the killed man was a soldier, and he was shot for passing information about\nRussian positions to Ukrainian armed forces."},{"id":"a-hrc-52-crp-4-p0421","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"421","seq":423,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The incidents described above are only a sample of the cases which the Commission\nexamined in detail, among the multiple allegations of killings of civilians and persons\nprotected under the international humanitarian law. The killings were committed in areas that\ncame under the control of Russian armed forces; at the time they were in control. The victims\nwere intercepted in the street or during house searches and visits. The executions were often\npreceded by confinement, ill-treatment, or torture. The hands of some of the victims were\ntied and a recurring cause of death was a gunshot to the head. The Commission has found\nthat Russian armed forces were the perpetrators or the likely perpetrators. In many of the\ndescribed cases, the victims were last seen in their presence, and in other cases, the bodies of\nthe victims were found in locations used by them. Based on all the examined circumstances,\nthe Commission has concluded that Russian armed forces have perpetrated wilful killings,\nwhich is a war crime.\nb)     Attacks on civilians on the move\n1)    Overview"},{"id":"a-hrc-52-crp-4-p0422","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"422","seq":424,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found a pattern of attacks committed against civilians on the\nmove in towns, villages, or on highways, in some of the areas that came under Russian armed\nforces control. It has recorded credible allegations regarding at least 46 incidents in which\nsoldiers fired with small arms upon civilian vehicles in 27 locations across Ukraine."},{"id":"a-hrc-52-crp-4-p0423","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"423","seq":425,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Under international humanitarian law, indiscriminate attacks are prohibited.\nIndiscriminate attacks include those which are not directed at a specific military objective\nand those which employ a method or means of combat which cannot be accurately directed\nat a specific military objective or the effects of which cannot be limited as required by\ninternational humanitarian law. Consequently, they are of a nature to strike military\nobjectives and civilians or civilian objects without distinction.278 Additionally, those who\nplan or decide upon an attack must, among other things, do everything feasible to verify that\nthe objectives to be attacked are neither civilians nor civilian objects, but are military\nobjectives. An effective advance warning must be given of attacks which may affect the\ncivilian population, unless circumstances do not permit.279 Moreover, intentionally making\nthe civilian population or individual civilians the object of an attack is a war crime.280"},{"id":"a-hrc-52-crp-4-p0424","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"424","seq":426,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In all the reviewed cases, the victims were dressed in civilian clothes and were driving\nin civilian vehicles. They came under attack as they were attempting to flee from areas\naffected by the armed conflict or were attending to their routine activities. The incidents\ninvestigated generally occurred when Russian armed forces entered new localities or\nencountered the victims on their way, or when civilian vehicles drove past or near locations\nwhere the Russian armed forces were deployed or stationed. Some of the attacks against\ncivilian vehicles took place at the same location, suggesting that the same units perpetrated\nseveral attacks."},{"id":"a-hrc-52-crp-4-p0425","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"425","seq":427,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In several incidents, soldiers opened fire immediately, as soon the vehicles of the\nvictims came in their sight, and on some occasions, regardless of the fact that civilians came\nout of their vehicles, attempted to seek shelter, or to warn the soldiers that they are civilians.\nThis indicates that the perpetrators did not take feasible efforts to verify that the objectives\nwere not civilian, as prescribed by international humanitarian law. Some of the attacks also\nappeared to be deliberate attacks on civilians.\n2)    Specific situations in which civilians on the move were attacked"},{"id":"a-hrc-52-crp-4-p0426","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"426","seq":428,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has documented 18 cases in which soldiers fired upon civilian\nvehicles, killing 26 civilians, namely eight women, 14 men, one girl and three boys, and\ninjuring two women, two men and two girls. These incidents took place in February and\nMarch 2022, in or around ten towns and villages of the Kyiv, Kharkiv, and Sumy regions,\nwith a majority in the Kyiv region. The actual number of attacks on civilian cars and resulting\ncasualties is likely much higher, including in other regions."},{"id":"a-hrc-52-crp-4-p0427","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"427","seq":429,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The evidence gathered indicates that Russian armed forces carried out the attacks or\nlikely carried out the attacks. According to victims’ and witness’ testimonies, some of the\nattacks were perpetrated by Russian military convoys, as they entered new localities or\nencountered civilians on their way. Other attacks came from Russian armed forces positions\nor temporary deployments. The persons impacted were civilians trying to evacuate, or\ncarrying out daily life activities, such as driving to their homes, looking for food and other\nnecessities, and visiting relatives. Soldiers mainly used small arms and light weapons."},{"id":"a-hrc-52-crp-4-p0428","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"428","seq":430,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Several of the attacks investigated took place in the same locations, suggesting that\nsome military units were responsible for multiple incidents. Some of them occurred on the\nE40 highway, in Kyiv and Kharkiv regions. In two villages, attacks also occurred in the same\nlocation or in close proximity. For instance, the Commission has documented four separate\nattacks on civilian vehicles, on 16, 17, and 18 March 2022, on the E40 highway near Rohan\nvillage, in Kharkiv region, in which three men and one woman were killed. At that time,\nRussian armed forces were stationed on a neighbouring hill (see case descriptions starting\npara. 435)."},{"id":"a-hrc-52-crp-4-p0429","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"429","seq":431,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In all the cases investigated, the victims were wearing civilian clothes, were not\narmed, and were driving civilian vehicles. All but one attack occurred in daylight when the\ncivilian status of the victims and of their vehicles should have been apparent to the attacker.\nIn two cases, the cars had signs with the word “children” taped to the windows. In two\nsituations, soldiers stopped shooting only after the victims shouted repeatedly that they were\ncivilians."},{"id":"a-hrc-52-crp-4-p0430","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"430","seq":432,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Some of the attacks seemed deliberate, for example when soldiers opened fire on\ncivilian cars that posed no risk to them, because they had stopped, turned around, or were\ndriving away from them. In some instances, the attackers shot regardless of the fact that the\ncivilians left the cars and sought shelter or were attempting to flee."},{"id":"a-hrc-52-crp-4-p0431","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"431","seq":433,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In one of the documented cases, on 5 March 2022, five adults and two boys were\nattempting to flee from the town of Bucha in two cars, after Russian armed forces took control\nof the area. When the families saw a military vehicle with the letter “V” painted on it stationed\nahead of them, they parked the cars on the side of the road. Without warning, the military\nvehicle opened fire on them, killing one woman, one man, and the two boys. In another case,\non 28 February 2022, as four civilians were driving in a car on the E40 highway, in Kyiv\nregion, they saw a military convoy with the letter “V” painted in white on vehicles driving\ntowards them. They turned around and parked their car at a gas station. After hearing shelling,\nthey ran out of the vehicles to a nearby field. Soldiers from within the convoy fired at them\nfor about 10 minutes, injuring one of the women, and threw a grenade in their direction."},{"id":"a-hrc-52-crp-4-p0432","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"432","seq":434,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the cases investigated, there were no indications that the attackers took steps to\nverify that the target was a military objective.281 This is illustrated by the fact that on some\noccasions, the soldiers opened fire as soon as they saw the civilian vehicles, which gave them\nno time to verify the target. In the vast majority of cases, attacks took place without warning,\nand when it was given, it was immediately followed by the attack, rendering the warning\nmoot."},{"id":"a-hrc-52-crp-4-p0433","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"433","seq":435,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In one example, on 28 February 2022, in the village of Katiuzhanka, in Kyiv region,\nfour civilians driving in a car encountered a convoy of Russian military vehicles on their way.\nThe driver stopped and tried to turn the car around, but the vehicle was fired upon from the\ndirection of the convoy, without warning. One man and one woman were killed, and a 13-\nyear-old girl was injured."},{"id":"a-hrc-52-crp-4-p0434","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"434","seq":436,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has concluded that Russian armed forces have committed or are\nlikely to have committed indiscriminate attacks against civilians and civilian objects\nincluding some resulting in civilian deaths, which are violations of international humanitarian\nlaw and violations of the right to life.282 They also did not take requisite precautions, such as\ndoing everything feasible to verify that the objectives to be attacked were not civilians or\ncivilian objects, and giving an effective advance warning.283 The attacks that appear to\nintentionally target civilians amount to war crimes.284\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0435","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"435","seq":437,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"This section provides illustrations of the attacks on civilians on the move that it has\ndocumented. The context and circumstances of each case are described. The Commission has\nincluded information it has managed to corroborate about units present in the relevant area,\neven if it has not established a link between that unit and the violation.\nBucha town, Kyiv region, 5 March 2022"},{"id":"a-hrc-52-crp-4-p0436","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"436","seq":438,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 5 March 2022, two days after the Russian armed forces took control of the town\nof Bucha, the Chikmarev285 family and the Tovchak family, altogether five adults and two\nboys, left their homes at around 8 a.m. to flee to Western Ukraine. They were wearing civilian\nclothes and used two white cars with windows that were not tinted. The first car had a sign\nwith the word “children” written on the front and on both sides."},{"id":"a-hrc-52-crp-4-p0437","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"437","seq":439,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"When the cars were approaching the UTEM factory on Chkalova Street in Bucha, the\nfamilies spotted a military vehicle stationed on the opposite side of the road from the factory,\nabout 150-200 m ahead. The vehicle had the letter “V” painted on it, a common marking of\nRussian military vehicles during the armed hostilities in Ukraine. One of the victims\nidentified it as a “BMD,” an infantry fighting vehicle. The two cars parked on the side of the\nroad. Without warning, the military vehicle opened fire on them, killing Marharyta\nChikmareva (born 1988), nine-year-old Matvii, and four-year-old Klym in the first car, and\nOleh Tovchak (born 1960) in the second car."},{"id":"a-hrc-52-crp-4-p0438","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"438","seq":440,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Among the victims, two women suffered minor injuries and hid in a nearby building.\nOne man was more seriously injured but managed to crawl to a nearby park. From there, he\nsaw the Russian military vehicle approaching the cars, after which the first car exploded.\nAbout half an hour later, Bucha residents found the husband, provided him with first aid and\ntook him to a hospital where part of his leg had to be amputated."},{"id":"a-hrc-52-crp-4-p0439","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"439","seq":441,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed two survivors of the attack and reviewed documents, as\nwell as photos and video of the cars. The photos show that the cars were civilian; the first car\nis burned and two charred remains corresponding to those of children below the age of 12\nare visible in the backseat; the damage to the second car is consistent with an attack with a\nlight weapon."},{"id":"a-hrc-52-crp-4-p0440","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"440","seq":442,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"According to the local authorities and an investigation conducted by a news outlet,\nthe military vehicle, which was left behind in Bucha, belonged to the 104 th Guards Assault\nRegiment of the 76th Guards Assault Brigade. The Commission has corroborated the\ninformation that the 104th Regiment was stationed in Bucha with other sources.\nBucha town, Kyiv region, 6 March 2022"},{"id":"a-hrc-52-crp-4-p0441","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"441","seq":443,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 6 March 2022, at around 10 a.m., three neighbours in civilian clothes were driving\nin a black Dacia Lodgy with a big “Uber” sign along Zhovtneva Street, in Bucha town. The\nman and the woman in the front seats, both in their 50s, were going to a store, hoping to find\nsome food. Their 60-year-old neighbour caught a ride with them to join his wife who was\ntaking shelter in a school basement."},{"id":"a-hrc-52-crp-4-p0442","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"442","seq":444,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"As they were approaching the intersection of Zhovtneva and Vokzalna Streets, they\nsuddenly heard gunfire, and the car was hit without warning. The man who was driving was\nshot in the right side of his hip and the woman was injured in her eye by glass from the broken\nwindshield. The driver stopped at the intersection of Zhovtneva and Dymytrova Streets. All\nthree civilians got out of the car and hid behind it. The victims saw two Russian soldiers who\ncontinued to shoot in their direction as they approached the car. One of the victims shouted\nat them repeatedly that they were civilians and that two persons were injured. The soldiers\neventually stopped shooting. They interrogated the civilians, verified their identity\ndocuments and their phones, and finally allowed them to drive to the hospital to seek medical\nhelp. As they were leaving, the civilians noticed several Russian military vehicles parked\nabout 100-150 m from where the car was attacked."},{"id":"a-hrc-52-crp-4-p0443","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"443","seq":445,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed all three persons who were in the car, two of them still\nrecovering from the injuries they suffered. The video of the car after the attack, which the\nCommission has reviewed, shows damage that is suggestive of an attack by small arms from\nthe front and left side, which is consistent with the description of the events by the three\nsurvivors.\nKatiuzhanka village, Kyiv region, 25 February 2022"},{"id":"a-hrc-52-crp-4-p0444","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"444","seq":446,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 25 February 2022, after Russian armed forces entered Katiuzhanka village, three\ncivilian vehicles were fired upon on three separate occasions, killing four men and one\nwoman. The Commission reviewed photos and videos taken after the attacks, which show\nthat the vehicles were civilian. In two cases, the victims, in civilian clothes, were still inside\nthe cars."},{"id":"a-hrc-52-crp-4-p0445","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"445","seq":447,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At around 11 a.m., a military convoy that had stopped at the intersection of Taras\nShevchenko and Kyivska Streets opened fire on a 43-year-old man wearing civilian clothes\nand driving a white Tavria, as he turned right from Taras Shevchenko Street. The man was\nkilled on the spot, and the car with the body inside was later set on fire. The upward deformed\nroof of the car and multiple shrapnel holes visible in the photos before the car burned down,\nare suggestive of use of small arms and light weapons."},{"id":"a-hrc-52-crp-4-p0446","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"446","seq":448,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Approximately at 1 p.m., a Russian soldier standing in front of a supermarket at the\nsame intersection opened fire on a second car, as it was approaching from Kyivska Street.\nVasylyna Oleksiivna Levandovska (born 1961) and an identified man (born 1969), wearing\ncivilian clothes and driving a white minivan T4, were then on the way from Vladimirovka\nvillage to buy some food in Katiuzhanka. The soldier first fired an automatic weapon into the\nair above the minivan. The vehicle slowed down but did not stop. The soldier subsequently\nfired directly at it, instantly killing the man, who was driving, and injuring Levandovska. The\nsoldier then inspected the vehicle and re-joined other soldiers at the parking lot in front of\nthe supermarket. Levandovska died a few hours later in a school basement where she was\nbrought by residents after the departure of Russian forces from the place of the incident."},{"id":"a-hrc-52-crp-4-p0447","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"447","seq":449,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The damage on the white minivan – about a dozen bullet holes on the hood and some\nmore on the front left fender – is consistent with an attack by automatic firearm from the\ndirection of the supermarket, which was front left from the car. The Commission reviewed\nmedical documents indicating that the man in the white minivan died of gunshot injury to the\nchest, while the cause of death of Levandovska was a gunshot injury to the lower limbs."},{"id":"a-hrc-52-crp-4-p0448","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"448","seq":450,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the afternoon on the same day, a military vehicle opened fire on another civilian\ncar on Kyivska Street, about 500 m from the intersection with Taras Shevchenko Street. Two\nmen, wearing civilian clothes and driving a white Ford Escort, were on their way to buy food\nand credit their phones. They died on the spot. The type of impact and multiple shrapnel holes\nsuggest an explosion inside the car, caused most likely by a light weapon.\nKatiuzhanka village, Kyiv region, 28 February 2022"},{"id":"a-hrc-52-crp-4-p0449","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"449","seq":451,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 28 February 2022, at around 5 p.m., a family of four, composed of two men, one\nwoman and a 13-year-old girl, left their relatives’ house on Poshtova Street to drive home on\nVyshhorodska Street. They were driving a white Hyundai Sonata with a big “Bolt” sign on\nthe side. As they approached the intersection with Taras Shevchenko Street, they encountered\na convoy of Russian military vehicles. When the driver stopped the car and tried to turn it\naround, the convoy opened fire on them without warning. The man in the driver’s seat and\nthe woman on the passenger’s seat were killed. The 13-year-old girl, although injured,\nmanaged to get out of the car together with the second man who was unharmed. The car\nsubsequently caught fire."},{"id":"a-hrc-52-crp-4-p0450","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"450","seq":452,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed the relatives of the victims who confirmed hearing the\nsound of gunfire and were the first to arrive to the place of the incident. A short video they\nshared with the Commission shows a civilian vehicle on fire, with two bodies lying on the\nground, one partly burned and still burning. This is consistent with the account of the events\nby the surviving man, who pulled the bodies out of the car and unsuccessfully tried to\nextinguish the flames on the other man’s body. Medical documents reviewed by the\nCommission indicate that the woman died of gunshot injury to the chest, and that the 13-\nyear-old girl was hospitalized on 1 March 2022, with injury to her right arm and hip.\nPeremoha village, Kyiv region, 11 March 2022"},{"id":"a-hrc-52-crp-4-p0451","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"451","seq":453,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 11 March 2022, at around noon, 17 civilians, including children, fled from their\nhomes in the village of Peremoha, which was occupied by Russian armed forces since\n28 February 2022. They drove to the south, towards the village of Hostroluchchia, which at\nthe time was under the control of Ukrainian armed forces. The convoy consisted of five\ncivilian cars: an old Moskvitch, a black Opel Astra, a dark red Dacia Logan, a silver Kia, and\na white Volkswagen. All cars had a white cloth wrapped around the side mirrors, to indicate\nthat they had civilians on board."},{"id":"a-hrc-52-crp-4-p0452","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"452","seq":454,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"As they exited Peremoha, they passed a Russian armed forces checkpoint, where\nsoldiers advised them to keep the windows open, so that everyone could see they were\ncivilians. After about a five to 10 minutes’ drive on a road surrounded by open fields, the\nconvoy was attacked from several directions, including from the back. At least four civilians\nwere killed: Tetiana Makarivna Scherbyna (born 1970), Petro Petrovych Scherbyna (born\n1957), Elisei Yevhenovych Riabokon, a 14-year-old boy, all three in the second car, and an\nunidentified 18-year-old young man, in the fifth car."},{"id":"a-hrc-52-crp-4-p0453","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"453","seq":455,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed survivors of the attack and reviewed documents, as well\nas photo and video evidence. Medical documents for three of the killed civilians indicate that\nthey died of multiple gunshot injuries to the chest, head, and torso. Photos and a video of the\nblack Opel Astra, in which three of the victims were killed, show multiple bullet holes on the\nleft rear door and signs of the use of explosive weapons in the back of the car.\nShevchenkove village, Kyiv region, 8 March 2022"},{"id":"a-hrc-52-crp-4-p0454","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"454","seq":456,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 8 March 2022, around 11 a.m., a convoy of Russian military vehicles entered the\nvillage of Shevchenkove. At that time, Yulia Oleksiivna Vashenko (born 1984) and an\nidentified man (born 1980) were at the market on Kyivska Street. Hearing the approaching\nconvoy, they packed the food they were selling at the market in and drove away in their light\nblue Opel. The military vehicles soon caught up with them and opened fire at the car from\nthe back, killing both Vashenko and the man. A few minutes later, about 500 m from the\nplace of the incident, another car – a black Subaru – owned by the head of the village, was\nattacked and partly run over by a military vehicle."},{"id":"a-hrc-52-crp-4-p0455","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"455","seq":457,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed three witnesses and reviewed a video interview by a\nnews outlet of one more witness. It reviewed photos and videos showing the two vehicles\nafter the attacks. According to the evidence, both vehicles were civilian and the victims were\nwearing civilian clothes. At least 15 bullet holes are visible on the back of the blue Opel,\nwhich is consistent with the account that the car was attacked from the back, and suggests\nthat the perpetrators used small arms. While one photo of the car also shows shrapnel damage\non the windshield, the Commission clarified with a witness that this damage was caused only\nlater by incoming shelling."},{"id":"a-hrc-52-crp-4-p0456","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"456","seq":458,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Video footage shows that the black Subaru was almost completely destroyed, with\nvisible marks on the road where a military vehicle ran over it. There are at least 18 bullet\nholes visible on the remains of the front bumper and the windshield, suggesting that similar\nsmall arms were used as in the attack described above.\nVyrivka village, Sumy region, 27 February 2022"},{"id":"a-hrc-52-crp-4-p0457","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"457","seq":459,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 27 February 2022, at around noon, a man, a woman and their adult son set out on\nthe road in a dark blue sedan, fleeing from Konotop city to Mitchenky village, located about\n20 km to the west. As they were driving on a side road near the Vyrivka train station, they\nwere overtaken by a large military convoy. Without warning, one of the military vehicles\nopened fire at the car. Oleksandr Mykolaiovych Liutenko (born 1975) in the passenger’s seat\nwas hit in his left shoulder and neck and died soon after. His son, who was driving, was\ninjured in the hand."},{"id":"a-hrc-52-crp-4-p0458","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"458","seq":460,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed the survivors of the incident and reviewed photos of the\ncar, which show three bullet holes in the windshield, two in the hood and at least three in the\nback of the car, consistent with the use of small arms. The location of the damage matches\nthe description of the attack by the survivors.\nVilkhivka village, Kharkiv region, 27 March 2022"},{"id":"a-hrc-52-crp-4-p0459","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"459","seq":461,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 27 March 2022, around 10:30 a.m., two families living in the village of Stepanky\nwere forced out of their houses by Russian soldiers. They set out on the road towards Kharkiv\nas part of a convoy consisting of three vehicles: a yellow minivan Mercedes with an older\nwoman, her son and daughter-in-law, and their nine-year-old daughter; a green Zhiguli with\ntwo men; and a black Geely with an older woman, her husband, their daughter and son-in-\nlaw, and their 13-year-old granddaughter. The last car had the sign “children” on the back\nwindshield."},{"id":"a-hrc-52-crp-4-p0460","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"460","seq":462,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The cars drove north to Vilkhivka village, where they took Ukrainska Street in order\nto join Tsentralna Street – the main road to Kharkiv. As they turned left at the intersection,\nthey saw two military vehicles in front of them on both sides of the road, not more than 100\nm away. The civilian vehicles immediately stopped. Without any warning, soldiers on the\nmilitary vehicles opened fire at them from either semi-automatic or automatic rifles. An older\nwoman in the first car and 13-year-old Marharyta Andriivna Horbyk in the third car were\nwounded. One of the civilians screamed at the soldiers to stop shooting, which they did, and\nthey let the convoy pass. The older woman died on the way to Kharkiv. The girl died three\ndays later in a hospital in the city."},{"id":"a-hrc-52-crp-4-p0461","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"461","seq":463,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The situation was volatile in the village at that time. Between 25 and 27 March 2022,\nUkrainian armed forces launched a counterattack to regain control of the area. Russian armed\nforces however remained at least partly in control until 28 March 2022, which is also\nillustrated by the fact that during that period, they forced dozens of residents to leave their\nhomes and walk north to the village of Verkhnia Rohanka village, from where they were\ntaken by bus to the Russian Federation. Given the fluid military situation, the Commission\nhas not been able to establish who was responsible for the attack.\nE40 highway, Kyiv region"},{"id":"a-hrc-52-crp-4-p0462","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"462","seq":464,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has documented three incidents on or in the vicinity of E40 highway,\nalso known as the Zhytomyr highway, in the Kyiv region. The highway connects Kyiv with\nWestern Ukraine and was used by many civilians from the parts of the Kyiv region, which\nwere then occupied by Russian armed forces, to flee to safety. The Commission has recorded\ncredible allegations of at least five additional similar incidents, that took place close to Kyiv."},{"id":"a-hrc-52-crp-4-p0463","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"463","seq":465,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In January 2023, Ukrainian authorities publicly identified the 5 th Separate Tank\nBrigade of the 36th Combined Arms Army of the Russian armed forces as responsible for\nattacks on ten civilian cars on Zhytomyr highway between 4 and 25 March 2022, which killed\n13 civilians and injured six. According to the authorities, Russian soldiers were based in the\nvillage of Berezivka and near the village of Myla. The Commission has corroborated that the\n5th Tank Brigade was stationed in the area.\nE40 near Kolonshchyna village, Kyiv region, 28 February 2022"},{"id":"a-hrc-52-crp-4-p0464","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"464","seq":466,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 28 February 2022, at around 11:30 a.m., two women and two men left\nKolonshchyna village in a light-coloured civilian car, hoping to reach Western Ukraine. All\nof them were wearing civilian clothes. When they turned right on to E40 highway, they saw\na military convoy with the letter “V” painted in white on the vehicles driving towards them\nabout 500 m away. They decided it was safer to turn the car around and parked at a nearby\ngas station."},{"id":"a-hrc-52-crp-4-p0465","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"465","seq":467,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"After about 10 to 15 military vehicles of the convoy had passed the station, the\ncivilians suddenly heard a sound of shelling coming from the front of the convoy. Afraid that\nthe convoy might fire at their car, the four civilians left the car and three of them ran to a\nnearby field. At this point, the convoy started to shoot in their direction. The gunfire lasted\nfor about 10 minutes and injured one of the women. The soldiers then threw a grenade into\nthe field, which set it on fire. The civilians managed to get into their car and eventually found\ntheir way back to Kolonshchyna."},{"id":"a-hrc-52-crp-4-p0466","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"466","seq":468,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Medical documents reviewed by the Commission show that one of the four civilians\nsuffered a non-perforating gunshot wound to the left thigh and on 11 March 2022 underwent\nsurgery that removed a bullet from her leg.\nE40 near Kopyliv village, Kyiv region, 1 March 2022"},{"id":"a-hrc-52-crp-4-p0467","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"467","seq":469,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 1 March 2022, at around 10 a.m., a man and a woman, both in their 60s, fled from\ntheir home in Berezivka village, located next to the E40 highway, to drive to Western\nUkraine. As they passed Motyzhyn village in their beige Citroen, they noticed several\nmilitary vehicles on the road surrounded by men in uniforms. The civilians slowed down and\napproached the soldiers."},{"id":"a-hrc-52-crp-4-p0468","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"468","seq":470,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"When they were about 40 m away, a soldier opened fire on the car. The woman in the\npassenger seat ducked and was not injured when a bullet hit the windshield on her side. The\ndriver then accelerated, and more bullets hit the wheel and the trunk of the car. They\ncontinued driving and passed at least two other cars with visible bullet holes."},{"id":"a-hrc-52-crp-4-p0469","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"469","seq":471,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"When they noticed a second group of soldiers, they steered the car into a forest nearby.\nThere they spent 21 days, too scared to move in any direction, until they finally made their\nway to the village of Kolonshchyna."},{"id":"a-hrc-52-crp-4-p0470","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"470","seq":472,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission reviewed photos of the car, which showed damage from small arms\nconsistent with the victims’ account.\nE40 near Severynivka village, Kyiv region, 3 March 2022"},{"id":"a-hrc-52-crp-4-p0471","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"471","seq":473,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 3 March 2022, a family of four decided to leave the village of Severynivka and\njoin their relatives in Western Ukraine. While the village itself was not at the time occupied\nby Russian armed forces, the electricity was cut a few days earlier, and they could hear\nexplosions nearby. They set out at around 10 a.m. in two cars: one identified woman (born\n1980) in a silver Mazda with their nine-year-old daughter, and her identified husband (born\n1980) in a silver KIA with their 15-year-old daughter."},{"id":"a-hrc-52-crp-4-p0472","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"472","seq":474,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"They drove to the E40 highway and turned west. In an interview to a news outlet, the\nyounger daughter recalled seeing Russian military vehicles on the highway. After turning\nsouth towards Motyzhyn village, about 1.5 km from the highway, the cars were attacked. The\nwoman and the man were severely injured and died shortly after. The older daughter was\nshot in the leg. After about two hours, the two girls were picked by Russian military vehicles\nand driven to a Russian military base. They left the younger girl with an older couple in a\nvillage nearby and told her that they will take her older sister to Belarus for medical treatment.\nAs of 15 February 2023, the older sister was still missing."},{"id":"a-hrc-52-crp-4-p0473","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"473","seq":475,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed relatives of the victims, as well as residents of the\nvillage, who took care of the nine-year-old girl. The Commission also reviewed video footage\nfrom the place of the incident taken in early April 2022, when the bodies and the damaged\ncars were found. The footage shows that the victims were wearing civilian clothes at the time\nof the attack and that the vehicles were civilian. The damage on the left rear door and the rear\nfender on the silver Mazda is suggestive of the use of small arms and it appears that the silver\nKIA was pushed off the road.\nE40 highway, Kharkiv region"},{"id":"a-hrc-52-crp-4-p0474","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"474","seq":476,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has documented four separate attacks on civilian vehicles in which\nthree men and one woman were killed on the E40 highway, in the Kharkiv region, near a Sun\nOil gas station, in the vicinity of Rohan village.286"},{"id":"a-hrc-52-crp-4-p0475","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"475","seq":477,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the time of the attacks, Russian armed forces were stationed on a hill south of\nneighbouring Mala Rohan village, about 1.5 km north of the highway, and about 3.5 km from\nthe Sun Oil gas station. They withdrew from the area after heavy fighting between 25 and\n27 March 2022.\nE40 near Rohan village, Kharkiv region, 16-18 March 2022"},{"id":"a-hrc-52-crp-4-p0476","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"476","seq":478,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 16 March 2022, at around 9 a.m., Yurii Ivanovych Vasiliiev (born 1980) and\nDenys Ivanovych Cherkov (born 1982) left Kamiana Yaruha village and set out on E40\nhighway towards Kharkiv, driving a yellow Renault Kangoo. They were planning to collect\nfood that could be distributed in the village. Both were wearing civilian clothes. At around\n10 a.m. their families lost contact with them."},{"id":"a-hrc-52-crp-4-p0477","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"477","seq":479,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On the same day, at around 3 p.m., Andrii Valeriiovych Moznichenko (born 1985)\nand Nataliia Mykolaivna Makar (born 1984) left Kharkiv, where they had dropped off\nrelatives trying to flee the area at the train station and bought some food. They were returning\nby E40 highway to Vvedenka village, driving a grey Kia jeep. They were wearing civilian\nclothes. Their relatives lost contact with them shortly after."},{"id":"a-hrc-52-crp-4-p0478","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"478","seq":480,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On 17 March 2022, a resident of Kamiana Yaruha village went looking for Vasiliiev\nand Cherkov. About two kilometres after the last checkpoint staffed by the Ukrainian armed\nforces, he came across several damaged and burned cars near the gas station Sun Oil. Among\nthem, he recognized the yellow Renault. Inside the burned car, there were charred remains of\na human body on the passenger seat. Vasiliiev’s burned body was on the ground next to the\ncar. Near another destroyed car, the witness found the body of Moznichenko. Inside the car,\nthere was Makar’s burned body. The witness did not manage to recover the bodies as he came\nunder fire from the direction of Mala Rohan village (north, north-west of the E40)."},{"id":"a-hrc-52-crp-4-p0479","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"479","seq":481,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"On the following day, 18 March 2022, between 8 and 9 a.m., a civilian man drove a\nbread delivery van from Kharkiv city to Chuhuiv city along the E40 highway. Near the Sun\nOil gas station, he noticed several burning cars. When he turned around to drive back to\nKharkiv city, the right side of his van that was pointing in the direction of Mala Rohan village\nwas hit, leaving a large hole. The man managed to escape on foot."},{"id":"a-hrc-52-crp-4-p0480","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"480","seq":482,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"There are indications that several other vehicles were attacked in the same way at the\nsame location. Video footage from the scene shows about ten damaged vehicles on a stretch\nof the E40 highway near the Sun Oil station, including the yellow Renault Kangoo."},{"id":"a-hrc-52-crp-4-p0481","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"481","seq":483,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission interviewed witnesses and relatives of the victims, and reviewed\ndocuments, photos and video footage from the place of the incident. Medical documents\nindicate that Vasiliiev and Cherkov died of blast injuries, Makar died of an explosion and\nshrapnel injury, and Moznichenko died of multiple injuries to head, torso and limbs.\nc)    Unlawful confinement, unlawful transfers and deportations, torture and inhuman treatment\n1)    Overview"},{"id":"a-hrc-52-crp-4-p0482","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"482","seq":484,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found a pattern of widespread unlawful confinement in areas\ncontrolled by Russian armed forces. Wide categories of persons of different ages and\noccupations were detained, at times in groups. The Commission has identified detention\nfacilities where Russian authorities detained large numbers of people for long periods of time\nand used torture and ill-treatment in six regions in Ukraine and in the Russian Federation."},{"id":"a-hrc-52-crp-4-p0483","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"483","seq":485,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In international humanitarian law, confining a protected person, such as a civilian,\nwithout lawful reason, is a war crime.287 Such confinement is also a violation of the right to\nliberty and security of person, under international human rights law. 288 In addition, the\ndetaining authority is under an obligation to fulfil certain procedural requirements, 289 provide\nhumane treatment,290 and not deprive protected persons of their civilian status.291 Moreover,\ntransferring or deporting a protected person such as a civilian to another location within the\ncurrent territory or to another State without a lawful basis is a war crime. 292"},{"id":"a-hrc-52-crp-4-p0484","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"484","seq":486,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the cases examined, lawful reasons for the confinement of civilians often appeared\nto be lacking. In all situations, procedural requirements for detention were not met, which\nalso rendered them unlawful, and conditions were consistently inhuman. Detention was\nfrequently a precursor to executions and torture. In some situations, perpetrators have\nunlawfully transferred detainees within Ukraine or have deported them to detention facilities\nin the Russian Federation. Many are still reported missing."},{"id":"a-hrc-52-crp-4-p0485","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"485","seq":487,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission also found that Russian authorities have widely used torture or\ninhuman treatment against both civilians and prisoners of war in seven regions of Ukraine\nand in the Russian Federation. As Russian authorities consolidated control over certain areas,\nthe Commission found that more diverse, but similar methods of torture were used in\ndedicated detention facilities across Ukraine."},{"id":"a-hrc-52-crp-4-p0486","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"486","seq":488,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"International humanitarian law and international human rights law prohibit torture and\nother cruel, inhuman, or degrading treatment or punishment.293 Inflicting severe physical or\nmental pain or suffering upon a person for such purposes as obtaining information or a\nconfession, or to punish, coerce or intimidate, or for any reason based on discrimination of\nany kind, can constitute the war crime of torture. Rape and sexual violence can constitute\ntorture."},{"id":"a-hrc-52-crp-4-p0487","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"487","seq":489,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims and witnesses reported that perpetrators inflicted severe physical and mental\npain and suffering. Torture has been frequently perpetrated during long interrogation\nsessions, with the aim of extracting information, confessions, intimidating, or punishing the\nvictims. It was particularly severe against current or former members of Ukrainian armed\nforces and associated persons, and at times against their relatives. In some cases, torture was\nfollowed by executions or resulted in the death of the victims."},{"id":"a-hrc-52-crp-4-p0488","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"488","seq":490,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In addition to the war crime of torture and the respective violation of human rights,\nthe Commission has investigated whether the conduct of the Russian authorities may also\namount to the crime against humanity of torture. A crime against humanity is an enumerated\nact – such as torture – when committed as part of a widespread or systematic attack directed\nagainst any civilian population, with knowledge of the attack 294 and pursuant to or in\nfurtherance of a State or organizational policy.295"},{"id":"a-hrc-52-crp-4-p0489","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"489","seq":491,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has determined that the Russian authorities’ use of torture was both\nwidespread and systematic against, among others, civilians.296 In terms of widespread,297 the\nconduct occurred in the seven regions of Ukraine so far investigated by the Commission,\naffecting significant numbers of detained individuals. As for systematic, 298 the Commission\nfound three main indications based upon the evidence thus far supporting this determination.\nFirst, while the unlawful confinement affected broad categories of persons, the victims of\ntorture seemed to have been selected deliberately; they were those suspected of sharing\ninformation with the Ukrainian forces, supporting Ukrainian military efforts, or those who\nhad a family member affiliated with the Ukrainian forces. Second, there was an underlying\nmotivation to punish, intimidate, coerce or obtain information from those perceived to be\nsupporting the Ukrainian armed forces and authorities. Perpetrators also called some of these\nparticular victims “nazis”, “fascists” or “terrorists”, thereby providing additional pretext and\nmotivation to torture them. Third and most importantly, in areas under prolonged Russian\ncontrol, torture methods that required advance preparation or planning were present and\napplied, such as electric shocks including the method of the “call to Lenin”, as described\nbelow (see paras. 521-533)."},{"id":"a-hrc-52-crp-4-p0490","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"490","seq":492,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Continued investigation is needed to establish whether there are sufficient indications\nof a State or organizational policy encouraging such attacks against the civilian population.\nBased upon the abovementioned indications of systematic torture, it is likely that there is an\nunderlying policy. The Commission would conclude that the Russian authorities committed\nthe crime against humanity of torture in the event that such a policy is inferred from further\nevidence.\n2)    Unlawful confinement"},{"id":"a-hrc-52-crp-4-p0491","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"491","seq":493,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has received allegations regarding the unlawful confinement of\nhundreds of persons by Russian authorities in areas under their occupation. It documented\nsuch cases in the Chernihiv, Donetsk, Kharkiv, Kherson, Kyiv, Sumy, and Zaporizhzhia\nregions, in Ukraine, and in the Russian Federation. Men and women of all ages, as well as\nchildren and older persons, became the victims of detention. The Commission also found that\nRussian authorities maintained makeshift and dedicated detention facilities where they\nconfined large numbers of persons for long periods of time and used torture in Chernihiv,\nDonetsk, Kharkiv, Kherson, Kyiv and Zaporizhzhia regions, in Ukraine, and in the Russian\nFederation. Lawful reasons for detention often seemed to be lacking and procedural\nrequirements were violated. Conditions of detention were inhuman, with frequent prolonged\nconfinement. Detention often went together with interrogations, executions, and torture or\nill-treatment."},{"id":"a-hrc-52-crp-4-p0492","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"492","seq":494,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In international humanitarian law, confining a protected person, such as a civilian,\nwithout lawful reason, is a war crime.299 Confining a protected person does not deprive them\nof their civilian status; such status is dependent upon, among other things, whether they were\nparticipating in hostilities.300 Further, such confinement is also a violation of the right to\nliberty and security of person, under international human rights law. 301 In addition, the\ndetaining authority is under an obligation to fulfil procedural requirements, such as promptly\ninforming the detainee, in a language they understand, of the reasons why the measures have\nbeen taken.302 Detainees should be treated humanely and protected from life-threatening\nconditions.303"},{"id":"a-hrc-52-crp-4-p0493","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"493","seq":495,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Most of the cases of unlawful confinement investigated by the Commission during\nthe first weeks of the armed conflict, were committed by Russian armed forces. In the areas\noccupied for longer periods of time, Russian authorities, including personnel of the Federal\nSecurity Service of the Russian Federation, the National Guard of Russia, the Special Purpose\nPolice Squad,304 the Special Rapid Response Unit,305 and Russian-aligned armed groups of\nthe former so-called Donetsk and Luhansk People’s Republics, locally appointed officials,\nand local residents supporting Russian armed forces, also reportedly detained individuals.\nThis was in particular the case in Kharkiv, Kherson and Zaporizhzhia regions. Where\npossible, the Commission has attempted to identify perpetrators, their leaders and units on\nthe ground, as well as their higher hierarchy.\ni)      Victims of confinement"},{"id":"a-hrc-52-crp-4-p0494","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"494","seq":496,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Perpetrators targeted a broad category of people. Most of the persons detained were\nyoung or middle-aged men. Women, children, and older people were also detained. Victims\nwere from various backgrounds and included law enforcement employees, persons formerly\nassociated with Ukrainian armed forces and Territorial Defence Forces, veterans of the\nformer Anti-Terrorist Operation, local officials, activists and journalists, teachers and school\ndirectors, priests, one doctor, employees of the Zaporizhzhia Nuclear Power Plant, volunteers\nevacuating civilians, and others. It also occurred that persons have been confined alongside\nwith their relatives. On one occasion, a large group of individuals was unlawfully detained\nin a single location – namely 365 persons."},{"id":"a-hrc-52-crp-4-p0495","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"495","seq":497,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In some instances, Russian authorities appeared to have actively searched for specific\nindividuals. In one example, perpetrators waited for the victim as he was leaving his\nworkplace and detained him. In another case, a local resident collaborating with the Russian\narmed forces called the victim for a meeting, during which the latter was detained. In one\nmore situation, Russian authorities visited a victim at his home and subsequently at his\nworkplace, where they detained him. At times, detentions occurred with the support of local\nresidents –whether willing or as a result of coercion. Some former detainees told the\nCommission that during confinement, perpetrators forced them to give information about\nothers."},{"id":"a-hrc-52-crp-4-p0496","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"496","seq":498,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has investigated cases in which Russian armed forces detained\npersons who were influential in their communities in order to coerce them and the local\nresidents to cooperate. In this regard, one emblematic case is the detention of the Mayor of\nMelitopol at the Palace of Culture of Melitopol, in Zaporizhzhia region, in March 2022. In\nanother situation, the head of a rural community in the Kherson region was detained by\nRussian armed forces who broke in her home in August 2022. The Commission has obtained\nthe names of 27 heads of territorial communities of Kherson region who have been reportedly\ndetained by Russian authorities."},{"id":"a-hrc-52-crp-4-p0497","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"497","seq":499,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"During detention, Russian authorities often searched the houses, phones, computers,\nsocial media accounts of the detainees, and sometimes confiscated electronic devices,\nvehicles, and money.\nii)     Places where detention was initiated"},{"id":"a-hrc-52-crp-4-p0498","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"498","seq":500,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Russian armed forces often detained people during house-to-house sweep operations,\nas they searched for individuals who supported Ukrainian armed forces. Such operations\nwere usually carried out after Russian armed forces had arrived at a new place or after they\nsuffered significant losses. Detentions also occurred at the victims’ workplaces."},{"id":"a-hrc-52-crp-4-p0499","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"499","seq":501,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In other cases, detention started at checkpoints or so-called filtration points manned\nby Russian armed forces, or in the street. In areas under their control, Russian armed forces\nestablished a ‘filtration’ system, mainly at checkpoints and border points, to screen persons\nby verifying their documents, mobile phones, and at times, interrogating them. There have\nbeen reports that at filtration points, Russian armed forces ordered men and women to\nundress, fully or partially, to verify the presence of specific tattoos, believing this indicated\nthat a person belonged to certain military units or groups (see paras. 615-617). In some areas,\nRussian armed forces have set up filtration points in the premises of schools, cultural houses,\nor police stations. The overall procedure of filtration, including the waiting time, could take\nup to several days. If during the process, suspicions arose that a person maintained\nconnections with Ukrainian armed forces or Ukrainian officials, filtration could lead to\ndetention. This could also be the case if the person had a certain type of tattoos.\niii)     Status of the victims and reasons for confinement"},{"id":"a-hrc-52-crp-4-p0500","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"500","seq":502,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In most of the documented cases, perpetrators accused the detainees of assisting\nUkrainian armed forces, participating in the Territorial Defence Forces, or of being members\nof the local resistance against the occupation. In many cases, however, according to\ninformation available to the Commission, the victims were not or no longer engaged in such\nactivities at the relevant times. Hence, they retained their civilian status and their\nconfinement, if valid reasons were absent, was unlawful. In some situations, family members\nof detained persons told the Commission that Russian authorities had given civilians the\nstatus of prisoner of war, while there was no evidence that the detainees were combatants or\nwere directly participating in hostilities at the relevant times. This led them to lose their\nprotected status. Depriving civilians of their protected status is unlawful. 306"},{"id":"a-hrc-52-crp-4-p0501","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"501","seq":503,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Some victims or witnesses, however, told the Commission that at the relevant times,\nthey had been collecting and sharing information with Ukrainian armed forces or had in other\nways assisted the Ukrainian armed forces. In such cases, these persons may lose their civilian\nprotections and the detention would likely not be considered unlawful under international\nhumanitarian law. In any case, international humanitarian law prohibits torture, regardless of\nthe status of the victim."},{"id":"a-hrc-52-crp-4-p0502","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"502","seq":504,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has in addition documented numerous cases in which Russian\nauthorities confined civilians based on information or indications that do not appear as lawful\ngrounds. Some people were detained because of having relatives in the Security Service of\nUkraine, Ukrainian law enforcement agencies, or the former Anti-Terrorist Operation. Other\nreasons invoked by Russian authorities included refusing to cooperate with the occupying\npower, for example teachers and school principals who refused to work under the occupying\nauthorities’ measures, protesting against the occupation, posting on social media, having a\npro-Ukrainian position, refusing to vote in so-called referenda, their religious affiliation, or\nwearing certain types of tattoos. These cannot be considered as valid reasons for confinement."},{"id":"a-hrc-52-crp-4-p0503","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"503","seq":505,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In one case, Russian armed forces confined 365 people for 28 days in the basement of\na school in inhuman conditions in Yahidne village, Chernihiv region. These forces claimed\nthat they carried out the confinement for the safety of the large civilian group. However, such\na claim is meritless given that Russian armed forces had established a military base in the\nsame school, which transformed it into a military objective, and therefore endangered the\ncivilians detained in the basement, in violation of international humanitarian law. 307\niv)      Procedural requirements"},{"id":"a-hrc-52-crp-4-p0504","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"504","seq":506,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities consistently violated procedural\nrequirements relating to confinement. Documented detentions lasted from three days to over\nnine months. In none of the examined cases did a judicial or administrative body review the\ndetention, as far as the Commission has been able to establish. At times, perpetrators did not\ncommunicate reasons for detention. In some cases, they exercised torture or psychological\npressure to force those detained to acknowledge allegations levelled against them. A local\nbusinessman who had been detained in Balakliia, in the Kharkiv region, told the Commission\nthat for 15 days, he did not know the reasons for his detention, and it was hard; he stated\n“they wanted to kill people morally”."},{"id":"a-hrc-52-crp-4-p0505","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"505","seq":507,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Families were frequently not informed of the whereabouts of their detained relatives,\nincluding in cases in which detainees were transferred to a different location in Ukraine, the\nRussian Federation, or Belarus. This rendered efforts to secure the release of detainees, for\ninstance through prisoner exchanges, particularly cumbersome.\nv)    Detention facilities"},{"id":"a-hrc-52-crp-4-p0506","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"506","seq":508,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission identified detention facilities where Russian authorities detained\nlarge numbers of persons for long periods of time in Chernihiv, Donetsk, Kharkiv, Kherson,\nKyiv and Zaporizhzhia regions, all in Ukraine, and in the Russian Federation. It focused its\ninvestigations on 14 such places and has received allegations regarding numerous other such\nfacilities. It visited some of these locations accompanied by former detainees who described\nthe conditions and their experience there. The actual number of detention places is likely\nmuch higher as it is challenging to obtain and verify information about places of confinement\nin areas that are under occupation or cannot be accessed because of security concerns."},{"id":"a-hrc-52-crp-4-p0507","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"507","seq":509,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Detention facilities investigated in detail were held in the School of Yahidne village,\nChernihiv region; the Volnovakha Correctional Colony No.120, aka Olenivka penal colony,\nand pre-trial detention facility No.5 (SIZO-5) in Donetsk city, Donetsk region; the Police\nStation and Railway Polyclinic in Izium city, Kharkiv region; the Police Department, Printing\nHouse “Baldruk”, and Transport Company in Balakliia city, Kharkiv region; the Nova\nKakhovka Police Station in Kherson Region; the Alians-Service metal plant, usually referred\nto as “Viknaland”, in the southern part of Dymer town, Kyiv region; the Police Station in\nEnerhodar and a garage in Melitopol, both in Zaporizhzhia region; the pre-trial detention\nfacility No.1 (SIZO-1) in Kursk region and the pre-trial detention facility No. 2 (SIZO-2) in\nBryansk region, in the Russian Federation."},{"id":"a-hrc-52-crp-4-p0508","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"508","seq":510,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Some detention places were improvised, for example, in the basement of a school, an\nindustrial or an agricultural facility, a train station, an airport, garages, and other dwellings.\nMakeshift facilities were common during the first weeks of occupation, as Russian armed\nforces gained control of certain areas."},{"id":"a-hrc-52-crp-4-p0509","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"509","seq":511,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In localities where the Russian authorities remained for longer periods, they\nestablished more formal facilities in police offices, pre-trial detention facilities, a medical\ninstitution, a school, and a printing house. Those in charge organized cells and, in some cases,\nallocated specific rooms for interrogation and torture.\nv)    Conditions of confinement"},{"id":"a-hrc-52-crp-4-p0510","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"510","seq":512,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In nearly all the detention facilities investigated by the Commission, the conditions\nwere lacking basic protection and requirements. Detention often occurred in cramped and\novercrowded cells, with persons forced to share small spaces, to sleep on the floor, or to take\nturns to sleep. On some occasions, men, women, and children were held together. In one\ninstance, 10 older persons died during confinement in a school basement because of\ninhumane conditions and other detainees, including children, had to share the same space\nwith the bodies of the deceased."},{"id":"a-hrc-52-crp-4-p0511","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"511","seq":513,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In numerous detention facilities, there was a lack of light and ventilation, and victims\ndescribed difficulties to breathe. Absence of heating in freezing temperatures was reported.\nSome detainees were confined in a metal cellar or placed outside in cold temperatures. In\nmany of the facilities, sanitary conditions were lacking, and buckets were used as a toilet.\nDetainees had to seek permission to take out the excrement from the cell. There was limited\nor no possibility to wash. Access to food, water, and medical care for some was limited or\nnone."},{"id":"a-hrc-52-crp-4-p0512","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"512","seq":514,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims described receiving spoiled soup, leftovers, porridge or pieces of bread, and\ndirty water in bottles. In some detention facilities, food was brought by family members.\n3)    Unlawful transfers and deportations"},{"id":"a-hrc-52-crp-4-p0513","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"513","seq":515,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has reviewed situations concerning men and women who were\ninitially confined in Ukraine, and then forcibly transferred within Ukraine or unlawfully\ndeported to the Russian Federation, on some occasions through Belarus. Of those, the\nCommission interviewed nine men and two women."},{"id":"a-hrc-52-crp-4-p0514","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"514","seq":516,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Under international humanitarian law, transferring or deporting a protected person\nsuch as a civilian to another location within the current territory or to another State without\na lawful basis is a war crime.308"},{"id":"a-hrc-52-crp-4-p0515","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"515","seq":517,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Former detainees who had been deported told the Commission that in the Russian\nFederation, they were confined in pre-trial facilities in Kursk and Bryansk regions. The\nCommission reviewed additional allegations regarding similar confinement, after\ndeportations, in detention facilities in other regions of the Russian Federation. The victims\ninterviewed stated that dozens of Ukrainians were detained in such facilities. Some of them\nwere reportedly released after a while, including through prisoner exchanges. Many more\nwere still detained at the time when the Commission’s interlocutors were liberated. Victims\nshared detailed accounts of torture in those facilities (see paras. 561-566)."},{"id":"a-hrc-52-crp-4-p0516","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"516","seq":518,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In one case, in March 2022, Russian armed forces detained a civilian man who helped\nevacuations from conflict-affected areas in Kozarovychi village, in Kyiv region. Perpetrators\nconfined him near Dymer locality, in Kyiv region, and subsequently transferred him to a\ndetention facility in Hostomel Airport, also in Kyiv region. From there, Russian armed forces\ntransferred him in military trucks, alongside with other detainees, to Belarus. There, he was\nissued a document which stated that he “counteracted a special military operation conducted\nin accordance with the procedure established by the President of the Russian Federation” and\nwas further transported by military vehicle to a pre-trial detention facility in the Russian\nFederation. During the transportation, two Russian officers stated that before the 2022-armed\nconflict, the facility had been emptied in order to host Ukrainian detainees. The Commission\nalso interviewed a woman, who was detained and transferred as part of the same group. She\ncorroborated the previous account. Both victims were tortured during their detention in the\nRussian Federation."},{"id":"a-hrc-52-crp-4-p0517","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"517","seq":519,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In two other cases, Russian armed forces detained two men from Hrebenykivka, and\nanother man from Trostianets, and confined them in a makeshift detention facility in\nBoromlia village, in Sumy region. One of the victims was a Ukrainian official. The\nperpetrators detained them in a metal cellar and subjected them to torture. Subsequently, they\ndeported the men, together with other detainees, to the Russian Federation, and confined\nthem in a facility not far from the border. There, Russian authorities asked the Ukrainian\nofficial “why was Okhtyrka resisting, while Russians want to liberate them”."},{"id":"a-hrc-52-crp-4-p0518","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"518","seq":520,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission also received numerous similar testimonies regarding transfers of\ndetainees by Russian authorities from areas under their control to locations in Ukraine. In\nsome cases, after releasing detainees, Russian authorities expelled them from occupied areas\nto territories under Ukrainian Government control, with no right to return. The Commission\ndocumented such situations in the Kharkiv, Kherson and Zaporizhzhia regions. The victims\nwere school principals, teachers, employees of the State Emergency Service of Ukraine, and\nmanagement of the Zaporizhzhia Nuclear Power Plant, who had been detained as they refused\nto co-operate with the Russian authorities. In some cases, detainees were forced to denounce\nUkrainian authorities on video. Perpetrators dropped the detainees at checkpoints, from\nwhere they had to walk in a grey zone to reach territories under Ukrainian Government\ncontrol. This endangered their lives (see para. 710).\n4)    Missing persons"},{"id":"a-hrc-52-crp-4-p0519","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"519","seq":521,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Numerous persons detained in areas that were under Russian occupation were still\nmissing several months after they were detained. Family members who reached out to\nRussian authorities regarding the whereabouts of missing persons reported that they did not\nreceive a response. For example, in Dymer town, Kyiv region, the Commission received a\nlist of 58 people from different places in the region, who had not returned after having been\nlast seen in custody of Russian armed forces. Relatives have received confirmation that some\nof these persons were in detention in the Russian Federation, but the fate of many remained\nunknown for long periods of time. In Kharkiv region, interlocutors told the Commission that\ntheir attempts to acquire information from Russian authorities in occupied territories on the\nwhereabouts of their family members did not yield results, and that after the withdrawal of\nRussian armed forces from certain areas, they had no information about the fate of their\nfamily members. In the Kherson region, after the Russian Federation relocated the local\npopulation and retreated from the right bank to the left bank of the Dnipro river, they also\ntransferred people who were in detention. As a consequence, family members told the\nCommission that they lost contact with relatives who were in detention facilities."},{"id":"a-hrc-52-crp-4-p0520","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"520","seq":522,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Some family members received information that their detained relatives were in the\nRussian Federation, but could not ascertain their exact whereabouts. In other cases, people\nreceived letters from their family members months after they went missing. Although the\nletters did not contain any address or location, they were stamped with “Russian Post – Free\nof Charge”, indicating that they were being held in the Russian Federation.\n5)    Torture and inhuman treatment"},{"id":"a-hrc-52-crp-4-p0521","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"521","seq":523,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found a widespread pattern of torture and inhuman treatment\ncommitted by Russian authorities against persons they detained in Chernihiv, Donetsk,\nKharkiv, Kherson, Kyiv, Sumy, and Zaporizhzhia regions, in Ukraine, and in the Russian\nFederation. Torture has been prevalent against certain categories of people. Most victims\nwere men. Both civilians and prisoners of war were tortured. Torture or inhuman treatment\nwere frequently perpetrated in combination with interrogation sessions, to extract\ninformation or confessions, or to intimidate or punish the victims. As Russian authorities\nconsolidated control over certain areas, the Commission found that more diverse, but similar\nmethods of torture were used systematically in detention facilities which they held across\nvarious regions of Ukraine. In some cases, torture was a precursor to execution, was so severe\nthat it led to death, or consisted of sexual and gender-based violence (see para. 509-601)."},{"id":"a-hrc-52-crp-4-p0522","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"522","seq":524,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"International humanitarian law and international human rights law prohibit torture and\nother cruel, inhuman, or degrading treatment or punishment. 309 Inflicting severe physical or\nmental pain or suffering upon a person with the purpose of obtaining information or a\nconfession, or to punish, coerce or intimidate, or for any reason based on discrimination of\nany kind, can constitute the war crime of torture. Rape and other sexual violence can\nconstitute torture. The threat or witnessing of such may also constitute torture depending\nupon the circumstances. Further, conduct that may not rise to the level of severity of torture\nbut still involve severe physical or mental pain or suffering may constitute the war crime of\ninhuman treatment. This war crime does not need to be committed with a specific purpose,\nas requisite for the war crime of torture."},{"id":"a-hrc-52-crp-4-p0523","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"523","seq":525,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims subjected to detention and torture in the first few weeks after the Russian\ninvasion mostly claimed that the perpetrators belonged to the Russian armed forces. In areas\nthat Russian armed forces controlled for a longer period, victims mentioned a wider range of\nperpetrators, including the National Guards of Russia, and its under-subordinate units, the\nSpecial Purpose Police Squad and Special Rapid Response Unit. The Federal Security\nService of the Russian Federation, Russian-affiliated armed groups of the former so-called\nDonetsk and Luhansk People’s Republics were also mentioned by victims as interrogators\nwho inflicted torture. In the Russian Federation, according to victims, the prison guards along\nwith special security services were inflicting torture, while the interrogation sessions were\nled by special forces, including the Federal Security Service of the Russian Federation and\nthe Investigation Committee of the Russian Federation.\ni)     Victims of torture and interrogation sessions"},{"id":"a-hrc-52-crp-4-p0524","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"524","seq":526,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Persons targeted with torture included current and former members of the Ukrainian\narmed forces or their relatives, volunteers evacuating civilians, veterans of the former Anti-\nTerrorist Operation, local authorities, employees of the local administration, retired and\nactive law enforcement personnel, employees of Zaporizhzhia Nuclear Power Plant,\nparticipants in rallies against the occupation, a journalist, local business owners, and other\ncivilians with pro-Ukrainian positions. Torture was particularly harsh against persons\nassociated with Ukrainian armed forces."},{"id":"a-hrc-52-crp-4-p0525","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"525","seq":527,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"According to accounts of victims and witnesses, perpetrators used torture against\npersons whom they accused of sharing information with Ukrainian armed forces or providing\nany form of support to the Ukrainian armed forces, as well as of committing attacks and\nsabotage against Russian armed forces. Torture was generally aimed at obtaining information\nabout Ukrainian armed forces and their positions, identifying people supporting Ukrainian\narmed forces and other Ukrainian officials, extracting confessions, forcing victims to\ncollaborate, or inflicting punishments upon the victims for real or perceived sabotage or\ncooperation with Ukrainian armed forces or Ukrainian officials."},{"id":"a-hrc-52-crp-4-p0526","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"526","seq":528,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In most of the cases, long interrogation sessions took place, sometimes lasting for\ndays, which were combined with torture, ill-treatment, threats, and sexual and, in some cases,\ngender-based violence. Victims were often brought to the places of detention or interrogation\nand kept hands tied or handcuffed, legs tied, eyes blindfolded with hoodie or tape, and had\nclothes or bags placed on their heads. Former detainees reported that they were asked about\nthe movement, positions, and supporters of Ukrainian armed forces, locations of Territorial\nDefence Forces and their numbers. Witnesses described hearing loud and “unbearable”\nscreams of their co-detainees during interrogation sessions. One victim explained how, after\ninterrogation and the administration of electric shocks, perpetrators requested him to sit and\nwrite his “confession”. Former detainees reported that during interrogation and torture\nsessions, Russian armed forces referred to them as “fascists”, “nazis”, “livestock”,\n“terrorists”, or “supporters of terrorists preventing the liberation process”. On several\noccasions, they forced the detainees to say: “glory to Russia” and “glory to Putin”. One victim\nwho had been in the Olenivka penal colony, reported that perpetrators held “denazification\nsessions”, during which they forced the victims to lie down, stepped on their heads and legs,\nand beat them.\nii)   Methods of torture"},{"id":"a-hrc-52-crp-4-p0527","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"527","seq":529,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Perpetrators inflicted severe physical and mental pain and suffering upon the victims.\nThose who underwent torture during the first weeks of the armed conflict and in makeshift\ndetention facilities in Ukraine, described beatings with rifle butts or batons, electric shocks\nwith tasers, rape, mock executions, and prolonged exposure to cold. In some cases, victims\nwere executed after torture."},{"id":"a-hrc-52-crp-4-p0528","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"528","seq":530,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In areas which Russian armed forces controlled for longer periods of time and in more\nestablished detention facilities, the Commission has documented the use of additional, more\ndiverse, but similar methods of torture across detention facilities which Russian authorities\nheld in various regions of Ukraine. These methods involved sessions of electric shocks,\nhanging and strangling with cables, and suffocating with plastic bags. Former detainees\ndescribed electric shocks with a military field phone called “tapik” connected to an electricity\ncable, or with clips on feet or fingers or men’s genitals. This was referred to as a “call to\nLenin” or “call to Putin”. Victims also reported that they were hung to the ceiling using a\nrope, with hands tied behind the back, a method called “parrot position”. Furthermore,\nperpetrators also raped women while in detention, which, in the cases reviewed, amounted to\ntorture. Some victims stated that gas masks were placed on their heads, so that their screams\nwould not be heard, or to suffocate them. Former detainees witnessed the death of co-\ndetainees following severe torture. One victim who had been in the Olenivka penal colony\nstated: “The detainees were made to squat and were beaten up. If you were silent, they would\nbeat you up and if you screamed, they would beat you up as well. So, in any case you would\nget beaten up. Once a guy screamed and he was beaten for two hours nonstop; it was really\nscary to listen to.”"},{"id":"a-hrc-52-crp-4-p0529","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"529","seq":531,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"According to persons who were detained in the Russian Federation, confinement was\nin some situations initiated with an “acceptance procedure”, or “priyomka” in Russian, during\nwhich both men and women were forced to stay naked in front of others for prolonged times.\nVictims stated that they were submitted to electric shocks, beatings with a baton, and\nsuffocation with plastic bags. A former detainee reported beatings as a “punishment for\nspeaking Ukrainian” and for “not remembering the lyrics of the anthem of the Russian\nFederation”. Perpetrators forced Ukrainian nationals to memorize and sing the Russian\nFederation anthem and other Russian patriotic songs, to kiss and apologize to portraits of\nhistorical persons of the Russian Federation or the Union of Soviet Socialist Republics, and\nthreatened to beat them if they refused. “I felt so helpless and angry when singing songs and\nkissing the photos, but I and all others preferred to do it instead of being beaten”, said a\nformer detainee."},{"id":"a-hrc-52-crp-4-p0530","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"530","seq":532,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims of torture sustained short-term and long-term injuries and trauma, including\nbroken facial bones, ribs, knees, hands, and fingers, bruises, or injuries leading to the inability\nor difficulty to walk. One victim reported that on the ninth day of severe torture, he started\nthrowing up blood and fell in a coma. One couple stated that upon release, after ten days of\ntorture, one of them had a blue face from bruises, while the other had the face covered in\nblood. The majority of detainees reported a deep psychological impact from torture on their\nlives.\niii)     Widespread and systematic use of torture"},{"id":"a-hrc-52-crp-4-p0531","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"531","seq":533,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has investigated whether the conduct of the Russian authorities may\nalso amount to the crime against humanity of torture. A crime against humanity is\nan enumerated act – such as torture – when committed as part of a widespread or systematic\nattack directed against any civilian population, with knowledge of the attack.310 Such an\nattack is defined as a course of conduct involving the multiple commission of enumerated\nacts against any civilian population, pursuant to or in furtherance of a State or organizational\npolicy to commit such attack.311 For the policy, the State or organization must actively\npromote or encourage such an attack against a civilian population.312"},{"id":"a-hrc-52-crp-4-p0532","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"532","seq":534,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The body of evidence collected has allowed the Commission to determine that the\nRussian authorities’ use of torture was both widespread and systematic. 313 It has found that\ntorture was used in the seven regions of Ukraine where it has so far led investigations and\nthat significant numbers of detained individuals have been affected, which are indicative of\na widespread conduct. The Commission has also found three main indications which led it to\ndetermine that torture was systematic. First, perpetrators specifically targeted persons they\nsuspected of sharing information with the Ukrainian forces, supporting Ukrainian military\nefforts, or those who had a family member affiliated with the Ukrainian forces. Second, there\nwas an underlying motivation to punish, intimidate, coerce or obtain information from those\nperceived to be supporting the Ukrainian armed forces and authorities. Perpetrators also\ncalled some of these particular victims “nazis”, “fascists”, or “terrorists”, thereby providing\nadditional pretext and motivation to torture them. Third and most importantly, in areas under\nprolonged Russian control, torture methods that required advance preparation or planning\nwere present and applied, such as electric shocks including the method of the “call to Lenin”,\nas mentioned above."},{"id":"a-hrc-52-crp-4-p0533","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"533","seq":535,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Continued investigation is needed to establish whether there are sufficient indications\nof a State or organizational policy encouraging such attacks against the civilian population.\nBased upon the abovementioned indications of systematic torture, it is likely that there is an\nunderlying policy. The Commission would conclude that the Russian authorities committed\nthe crime against humanity of torture in the event that further evidence points to such a policy.\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0534","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"534","seq":536,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"As stated above, the Commission has established a pattern of widespread unlawful\nconfinement in areas controlled by Russian armed forces. It has collected detailed first-hand\ntestimonies from former detainees regarding both makeshift and more established detention\nfacilities maintained by Russian authorities in areas they controlled in Ukraine and in the\nRussian Federation. Within those detention centres, the evidence has shown widespread\ntorture, ill-treatment, and inhuman conditions."},{"id":"a-hrc-52-crp-4-p0535","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"535","seq":537,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission describes below some of these detention facilities. In this section,\nthe descriptions are based on the detailed accounts of at least three independent first-hand\ntestimonies. In many cases, former detainees listed the names of other people held together\nwith them, providing independent corroboration of their detention. The Commission has\ncollected information about the identity of perpetrators and their units. Given the scale of\nthese violations, this section will be limited to some illustrations.\nMakeshift detention facilities in Ukraine\n“Viknaland”, Dymer town, Kyiv region"},{"id":"a-hrc-52-crp-4-p0536","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"536","seq":538,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities maintained a makeshift detention\nfacility at the Alians-Service metal plant, often referred to as “Viknaland”, in the southern\npart of Dymer town, Kyiv region, when they controlled the area between 5 and 28 March\n2022. It documented inhuman conditions, ill-treatment, and torture in this facility, based on\ndetailed accounts from 10 people who were detained at the plant."},{"id":"a-hrc-52-crp-4-p0537","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"537","seq":539,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The conditions of confinement were inhuman. According to former detainees, women\nand men, sometimes more than 40 at a time, were held in a room of about 20 square m,\nmaking the space overcrowded. There was no light and no heating in the room, detainees\nwere sleeping on the concrete floor, and a bucket served as toilet. Food was poor and made\nmany of them sick."},{"id":"a-hrc-52-crp-4-p0538","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"538","seq":540,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Five former detainees said that they were subjected to various forms of ill-treatment\nand torture in the facility and eight said that they heard or saw Russian armed forces torture\nand ill-treat others. The methods of torture included severe beatings with rifles, electric\nshocks with tasers, mock executions, and threats of execution of family members. Several\npeople reported that they or others sustained severe injuries from the treatment, including lost\nteeth, broken ribs, legs, or fingers."},{"id":"a-hrc-52-crp-4-p0539","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"539","seq":541,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"One of the victims was a 44-year-old man, who told the Commission that Russian\nsoldiers interrogated him to extract information about Ukrainian armed forces, beat him with\nrifles and gave him multiple electric shocks with a taser. His hands were tied and eyes\nblindfolded. A 38-year-old woman stated that she was interrogated by four soldiers for\nseveral hours about the position of Ukrainian armed forces and about ways to cross the\nfrontline, during which she was beaten with a baton on her back and her arms. Other detainees\nconfirmed that they saw these two detainees in this facility."},{"id":"a-hrc-52-crp-4-p0540","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"540","seq":542,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The former detainees and other residents who interacted with the forces at the plant\ndescribed them as “military police”, based on their appearance. There are also indications\nthat the 83rd Guards Air Assault Brigade were involved in running the detention facility. One\nof the former detainees heard that soldiers who released a group of detainees on 11 March\n2022, told them that they should say that the “83 military brigade” had released them if they\nwere stopped at any checkpoints. Journalists who visited the site after Russian armed forces\nhad left, found documents apparently belonging to the 83 rd Brigade.\nSchool basement, Yahidne village, Chernihiv region"},{"id":"a-hrc-52-crp-4-p0541","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"541","seq":543,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission found that in March 2022, Russian armed forces used the basement\nof a school in Yahidne village, Chernihiv region, as a makeshift detention facility. There,\nthey confined in inhuman conditions 365 people for 28 days. When Russian armed forces\narrived in Yahidne in early March 2022, some residents initially sought shelter in the\nbasement of the local school voluntarily. Soon, however, the Russian armed forces started\nforcing others to go there, and eventually confined 365 people, including at least 70 children.\nThe Commission collected the testimonies of eight residents from Yahidne and inspected the\nschool."},{"id":"a-hrc-52-crp-4-p0542","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"542","seq":544,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The conditions of confinement were inhuman. The space was extremely crowded and\nthere was no room for everybody to lie down. There was no light except for candles, torches\nand kerosene lamps. It was unbearably hot, with no ventilation and lack of oxygen. People\nreceived food once or twice per day. There was close to no access to health care and\nmedication, and limited access to toilet and washing facilities. The detainees had to use a\nbucket as a toilet, or to seek permission to exit the premises or to use the toilet outside, which\nwas only given sporadically. In the yard of the school, the soldiers randomly shot near the\ndetainees to scare them. As a consequence of these conditions, 10 older persons died during\ndetention. These conditions severely impacted the health of some of the others."},{"id":"a-hrc-52-crp-4-p0543","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"543","seq":545,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission collected information indicating that forces from several units were\nlocated in or near Yahidne, including in the school. These forces comprised the 55th Separate\nMotorized Rifle Brigade, the 74th Separate Guards Motorized Rifle Brigade, and the 228th\nMotorized Rifle Regiment.\nRailway Polyclinic, Izium city, Kharkiv region"},{"id":"a-hrc-52-crp-4-p0544","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"544","seq":546,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities established a makeshift detention\nfacility at the abandoned Railway Polyclinic located at Zavodska Street 35b, in Izium city,\nKharkiv region. It visited the facility and documented inhuman conditions, ill-treatment, and\ntorture there, based on testimonies of five persons who were held there for up to 14 days in\nJune-July 2022."},{"id":"a-hrc-52-crp-4-p0545","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"545","seq":547,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The conditions of confinement at the facility were inhuman. According to former\ndetainees, they were held in several garages of about 16 square meters in size, with up to 16\npersons in one garage. There were no windows, the detainees slept on the concrete floor, and\nthere was only a bucket for toilet, which they could empty only every three days. Food was\npoor. One woman was held in a storage room in one of the buildings."},{"id":"a-hrc-52-crp-4-p0546","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"546","seq":548,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Three former detainees testified about ill-treatment and torture at the facility,\nincluding electric shocks with a military field phone called “tapik” connected to fingers, toes,\nor genitals; suffocation using gas masks; as well as rape, beating, and hanging with a rope."},{"id":"a-hrc-52-crp-4-p0547","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"547","seq":549,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Among them was a couple, a 53-year-old man and a 52-year-old woman. The man\ntold the Commission that they were detained for ten days at the facility, because their son\nwas serving in Ukrainian law enforcement and because they refused to work for the\nadministration appointed by Russian authorities. He reported that perpetrators tortured him\nfor two hours during the afternoons. Once he was hit against the wall so hard that he lost\nconsciousness. Perpetrators ordered him to wear a gas mask, to cut off his oxygen supply.\nThe woman recounted being subjected to torture and sexual violence. She told the\nCommission that she scratched her name on the wall of the facility, which the Commission\nobserved during its inspection.\nEstablished detention facilities in Ukraine\nPolice Department, Izium city, Kharkiv region"},{"id":"a-hrc-52-crp-4-p0548","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"548","seq":550,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities maintained a detention facility at\nthe Police Department in Izium city, Kharkiv region. It documented inhuman conditions, ill-\ntreatment, and torture in this facility and detentions that lasted from five to 50 days. The\nfindings of the Commission are based on testimonies of four detainees and the Commission’s\nown observations during a visit to the location."},{"id":"a-hrc-52-crp-4-p0549","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"549","seq":551,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The conditions of confinement at the facility were inhuman. Former detainees said\nthat they were mainly held in cells in the basement, while women were kept on the ground\nfloor. The cells were about four to five square meters in size, with two to four persons in each\ncell, a wooden bench to sleep on, and no natural light. A bucket was used for toilet, while\nsome detainees were given only a bottle for urine. There was no option to wash and limited\nto no access to food. The detainees’ description of the facility matched the Commission’s\nobservations at the site."},{"id":"a-hrc-52-crp-4-p0550","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"550","seq":552,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Three of the four former detainees recounted being subjected to electric shocks with\na military field phone connected to fingers or toes, beatings, including with objects, and being\nhung by their hands with rope from the ceiling. They listed different types of injuries from\ntheir ill-treatment and torture, including a broken arm, broken ribs, and problems with\nkidneys."},{"id":"a-hrc-52-crp-4-p0551","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"551","seq":553,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Among the detainees, a 67-year-old man told the Commission that he had been\nconfined in August 2022, following accusations that he had cooperated with the Ukrainian\narmed forces and had blown up a school that Russian armed forces had used as a base and\nmiliary hospital. He was interrogated several times, during which perpetrators beat him all\nover his body and electrocuted him with a device connected to his fingers. The first\ninterrogation session left him with a broken arm and incapable of walking on his heels. On\nthe ninth day of his detention, he was beaten so badly, that he lost consciousness. Another\ndetainee who was held in the neighbouring cell confirmed that the 67-year-old man was\ntortured and lost consciousness. He was eventually brought to the local hospital. A local\ndoctor confirmed that he had been hospitalized and had barely survived. The Commission\nreviewed medical documents confirming that his arm had been broken and observed stiches\non his left arm and that the mobility of that arm, hand, and fingers were reduced.\nPolice Department, Balakliia town, Kharkiv region"},{"id":"a-hrc-52-crp-4-p0552","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"552","seq":554,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities maintained a detention facility at\nthe Police Department in Balakliia town, Kharkiv region. It documented inhuman conditions,\nill-treatment, and torture in this facility. Most detentions lasted about two weeks, while one\nman was held there for 95 days. The findings of the Commission are based on accounts from\n13 former detainees."},{"id":"a-hrc-52-crp-4-p0553","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"553","seq":555,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The conditions of confinement at the facility were inhuman. The former detainees said\nthat they were mainly held in four cells of about five square m in size, containing a few\nwooden benches for sleeping. There were often six to eight people in each cell. The were no\nwindows, natural light, or proper ventilation, making the cells unbearably hot. Detainees were\nbrought to the toilet twice per day, in the morning and in the evening. There was no possibility\nto wash. Food was poor. Five women who had been detained there said that they were held\nin a separate room and that their conditions were somewhat better, with more and better food\nand with windows in their room. The detainees’ description of the facility was in conformity\nwith the Commission’s observations during its visit."},{"id":"a-hrc-52-crp-4-p0554","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"554","seq":556,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Five of the former detainees described sustained beatings, beatings with objects, and\nelectric shocks using a military field phone connected to fingers or toes. Detainees reported\nthat at least two of them suffered a broken rib and arm. One young woman told the\nCommission that one of the soldiers raped her (see para. 609). Former detainees also said that\nthe perpetrators forced them to record videos saying that they were ready to cooperate with\nthe Russian armed forces, that they hated the Ukrainian armed forces, or that they were\ngrateful to the Russian Federation for the liberation of their town."},{"id":"a-hrc-52-crp-4-p0555","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"555","seq":557,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Among the detainees, a 45-year-old man told the Commission that he was detained\nafter being accused of being a spotter for the Ukrainian armed forces. The perpetrators\ninterrogated him, asked him to identify spotters, and beat him with a rubber baton on his head\nand face until he was bleeding in three places. They also gave him electric shocks with a taser\non different parts of his body. According to the victim, the perpetrators were not interested\nin his answers. A second detainee who had shared the cell with the man confirmed that he\nhad been tortured, and both witnesses mentioned the same call sign for one of the\nperpetrators."},{"id":"a-hrc-52-crp-4-p0556","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"556","seq":558,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"During its visit, the Commission observed the words “Smerch” and “Orlan” written\non garages and on a schedule which listed the days when “Smerch,” “Orlan,” and “LNR”\ncould use an improvised washing facility in the backyard. “Smerch,” and “Orlan” likely refer\nto Special Purpose Police Squad forces from two cities in the Russian Federation, Samara\nand Togliatti, respectively, suggesting that they were located at the police station. Other\ninformation which the Commission has obtained independently confirms that Special\nPurpose Mobile Unit forces from Samara and Togliatti were located in Balakliia town during\nthe occupation. The Commission has identified the Russian armed forces’ military\ncommandant in Balakliia who likely played a key role in managing the interaction between\nRussian armed forces and civilians, including those detained at the police station.\nPolice Department, Enerhodar city, Zaporizhzhia region"},{"id":"a-hrc-52-crp-4-p0557","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"557","seq":559,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities maintained a detention facility at\nthe Police Department in Enerhodar city, Zaporizhzhia region. It documented inhuman\nconditions, ill-treatment, and torture in this facility. Four detainees who had been confined in\nthis centre between March and August 2022 were interviewed; their periods of confinement\nlasting from one to 53 days."},{"id":"a-hrc-52-crp-4-p0558","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"558","seq":560,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The conditions of confinement at the facility were inhuman. It consisted of three cells\nof about 10 m2 each, and one additional cell for women. Twelve to 20 people were held at a\ntime in each of the cells, making it overcrowded. Each room had one latrine and two beds\nand no space to sleep for all. Detainees washed with a water bottle on top of the latrine.\nVentilation was lacking. The detainees were mainly fed with what their relatives brought for\nthem."},{"id":"a-hrc-52-crp-4-p0559","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"559","seq":561,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Four former detainees recounted how they and other detainees were subjected to\ninterrogations accompanied by beatings with batons, rifle butts, or a cable, electric shocks\nreferred to as “a call to Lenin”, strangling with a cable, and shooting with rubber bullets,\nincluding near the ears of the victims. Interrogators reportedly referred to one of the victims\nas a “terrorist” and a “nazi”. Former detainees also witnessed the death of three persons\nfollowing torture, including one employee of the Zaporizhzhia Nuclear Power Plant."},{"id":"a-hrc-52-crp-4-p0560","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"560","seq":562,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"One of the detainees, a 45-year-old man, told the Commission that during\ninterrogation, the perpetrators questioned him about the names of officials of the Security\nService of Ukraine. He said that he was electrocuted at least five times with a military field\nphone and was shot with a rubber bullet. As the result of the torture, he sustained bruises on\nhis body and face and six broken ribs and required prolonged medical treatment. Two other\nformer detainees confirmed to the Commission that the man was detained and tortured at the\npolice station. Additionally, all three witnesses mentioned the same call sign for two of the\nperpetrators, and two of the witnesses mentioned the same call sign or name for four other\nperpetrators.\nDetention facilities in the Russian Federation\nSIZO-1, Kursk city, Kursk region, Russian Federation"},{"id":"a-hrc-52-crp-4-p0561","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"561","seq":563,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities transferred and held detainees\nfrom Ukraine in SIZO-1, in Kursk city, Kursk region, in the Russian Federation. The facility\nfalls under the Federal Penitentiary Service Directorate for the Kursk region. The\nCommission has documented ill-treatment and torture at this facility based on testimonies of\n11 former detainees who were confined there between March and October 2022."},{"id":"a-hrc-52-crp-4-p0562","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"562","seq":564,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Former detainees delivered testimonies regarding a violent “admission procedure”,\nduring which they were forced to sing Russian songs, were subjected to forced nudity, electric\nshocks using a taser, suffocation using plastic bags, beatings with fists or objects, and to stand\nfor prolonged periods of time. Three former detainees described how they were placed in a\nroom where they received threats of being burned alive. Some detainees were threatened with\nsexual violence."},{"id":"a-hrc-52-crp-4-p0563","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"563","seq":565,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Among the victims, a 26-year-old woman told the Commission that when she was\nbrought to SIZO-1 in April 2022, prison guards tied her hands and blindfolded her. They beat\nher, gave her electric shocks on her back, shoulder, legs, and neck, and stood on her spine\nwhile she was lying on the ground. She said that she passed out a few times from the beatings,\nbut they woke her up again to continue. After a registration procedure, they took her to\nanother room where they suffocated her with a plastic bag and then locked her in a small\nroom with a piece of burning paper, saying that they would turn on the gas so that she would\nburn alive. The woman also recounted being forced to learn by heart and sing the Russian\nanthem and other songs multiple times per day and kiss photos of war veterans and Russian\nleaders. For example, she mentioned having to sing the songs “Katyusha” and “Uncle Vova”,\nthat other detainees in this facility also specifically recall being forced to learn and sing.\nSIZO-2, Novozybkov city, Bryansk region, Russian Federation"},{"id":"a-hrc-52-crp-4-p0564","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"564","seq":566,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that Russian authorities transferred and held Ukrainian\ndetainees in SIZO-2, in Novozybkov city, Bryansk region, in the Russian Federation. The\nfacility falls under the Federal Penitentiary Service Directorate for the Bryansk region. The\nCommission has documented ill-treatment and torture in this facility, based on testimonies\nof seven former detainees who were confined there between March and September 2022, for\na duration of up to 42 days. Former detainees said that they saw several hundred detainees\nfrom Ukraine in the facility, both men and women."},{"id":"a-hrc-52-crp-4-p0565","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"565","seq":567,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The seven former detainees interviewed by the Commission described an abusive\n“admission procedure” upon arrival to the facility, interrogation, being forced to learn\nRussian songs and being punished if they failed, electric shocks with tasers, beatings, forced\nnudity, and being forced to stand for prolonged periods of time. Two detainees told the\nCommission that they suffered from physical and psychological problems due to the\ndetention."},{"id":"a-hrc-52-crp-4-p0566","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"566","seq":568,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Among the victims, a 44-year-old man reported to the Commission about the\n“admission procedure”, during which he was stripped naked, forced to stand against a wall\nwith his legs spread, and shout “glory to Russia” while being beaten, mostly on his calves\nand lower back. The guards forced the detainees to learn by heart the lyrics of the Russian\nanthem and other songs and beat them if they could not recall the lyrics. A woman who was\ndetained and released together with the man confirmed that he had been detained in the\nfacility.\nd)     Sexual and gender-based violence\n1)    Overview"},{"id":"a-hrc-52-crp-4-p0567","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"567","seq":569,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The evidence gathered by the Commission indicates that Russian authorities have\ncommitted sexual and gender-based violence, often committed with brutality, and in\ncombination with other grave violations, across areas they controlled in Ukraine and in the\nRussian Federation. It has documented cases of sexual and gender-based violence, including\nrape, threat of rape, sexual slavery, and forced nudity involving women, men, and girls, of\nan age range from 4 to over 80, in nine regions of Ukraine, and in the Russian Federation."},{"id":"a-hrc-52-crp-4-p0568","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"568","seq":570,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Rape, sexual violence and sexual slavery are war crimes.314 Rape and other forms of\nsexual violence may also amount to torture.315 Sexual and gender-based violence also\nconstitutes human rights violations, such as those contained in international human rights\ntreaties, including the right to be protected from torture or cruel, inhuman or degrading\ntreatment,316 the right to equality,317 and the right to health.318"},{"id":"a-hrc-52-crp-4-p0569","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"569","seq":571,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In areas that have fallen under the occupation of the Russian armed forces since\n24 February 2022, the Commission has documented many instances of rape and sexual and\ngender-based violence committed during house searches and forced visits carried out by\nRussian armed forces. Sexual violence often went together with other grave violations and\ncrimes, such as summary executions, torture, and ill-treatment. It has also documented that\nRussian authorities used sexual violence, including rape and threat of rape, against Ukrainian\nprisoners of war and detained civilians, as a method of torture. Moreover, in some situations,\nthey imposed forced nudity, which can be a form of sexual violence, during controls at check\npoints and filtration points, and in detention."},{"id":"a-hrc-52-crp-4-p0570","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"570","seq":572,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims and witnesses have pointed to differences in behaviour between soldiers and\nunits of Russian armed forces. In many cases, they described violent, degrading, humiliating,\nand intimidating behaviour of perpetrators towards the victims. In a few cases, the\nCommission also received reports that Russian commanders or soldiers have intervened to\nstop or have told victims and witnesses that they have punished perpetrators of sexual\nviolence."},{"id":"a-hrc-52-crp-4-p0571","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"571","seq":573,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Sexual and gender-based violence has severely impacted victims, their families, and\ncommunities. It has caused internal and cross-border displacement and eroded family and\ncommunity networks: some women survivors decided to leave their families, homes, and\ncommunities because of the shame and stigma associated with rape. Most survivors of sexual\nand gender-based violence documented by the Commission received some psychological\nsupport. The Commission ensured that all the survivors it had contacted were referred to\nadequate services, if they were not receiving such before."},{"id":"a-hrc-52-crp-4-p0572","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"572","seq":574,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Office of the Prosecutor General of Ukraine has been developing a prosecution\nand investigation strategy on conflict-related sexual violence. As of 27 January 2023, the\nProsecution services of Ukraine were seized of 166 cases of sexual violence relating to the\nongoing armed conflict, 11 of which concerned a child victim. Some of the alleged\nperpetrators have been identified and proceedings were initiated. The Commission\ninvestigated some of these cases."},{"id":"a-hrc-52-crp-4-p0573","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"573","seq":575,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Due to security and other constraints, the Commission did not have physical access to\nsome areas of Ukraine and to some victims. It is therefore unable to describe the full spectrum\nof sexual and gender-based violence linked to the armed conflict. Particular challenges in\ndocumenting such violations were due to various factors, including fear or shame of\nreporting, and to the fact that some victims were not yet ready to share their experiences.\nAdditional obstacles were caused by the displacement of victims, the trauma following the\nevents and the taboos associated with discussing and reporting these issues. For these reasons,\nthe Commission believes that the actual number of cases of sexual and gender-based violence\nis higher.\n2)      Situations in which sexual and gender-based violence was committed"},{"id":"a-hrc-52-crp-4-p0574","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"574","seq":576,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has identified two main situations in which Russian authorities\ncommitted sexual violence: during house searches or forced visits carried out by Russian\narmed forces in areas that came under their control, and against victims they had confined. It\nhas also found that Russian authorities imposed forced nudity, which can be a form of sexual\nviolence, in detention, at checkpoints, and filtration points. Sexual violence committed during\nhouse searches appears to have been more prevalent during the first two months of the armed\nconflict, with a majority of cases in Kyiv region, as Russian armed forces first deployed to\nor consolidated control over certain areas. Sexual violence in detention was perpetrated\nthroughout the armed conflict."},{"id":"a-hrc-52-crp-4-p0575","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"575","seq":577,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Both men and women have been victims of sexual violence. In the cases of rapes\ncommitted during house searches, the majority of victims were women, including older\nwomen and girls in rural areas, who did not manage to evacuate before Russian armed forces\narrived in their areas or had no financial or logistical resources to go to safety. Some of them\nremained due to care-taking obligations of older relatives. In the cases of sexual violence\ncommitted in detention, the majority of victims were men, both civilians and prisoners of\nwar."},{"id":"a-hrc-52-crp-4-p0576","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"576","seq":578,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Most of the survivors who engaged with the Commission asked that their privacy be\nrespected and that their village not be named. For this reason, most of the cases in this section\nonly refer to the region in which the incident occurred and do not indicate the exact dates of\nthe events.\ni)     Sexual and gender-based violence during house searches"},{"id":"a-hrc-52-crp-4-p0577","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"577","seq":579,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission’s investigation shows that in the areas that came under their control,\nRussian armed forces committed rape, attempted rape, sexual violence, sexual slavery, as\nwell as the corresponding human rights violations. These crimes and violations were often\naccompanied by other violations, committed against the victims of rape or their relatives,\nsuch as wilful killing of civilians, torture, outrages upon personal dignity, and unlawful\nconfinement. The Commission documented such violations and crimes in Chernihiv,\nKharkiv, Kherson, and Kyiv regions, with a majority in Kyiv region, mainly during the first\ntwo months of the armed conflict."},{"id":"a-hrc-52-crp-4-p0578","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"578","seq":580,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Rape, sexual violence and sexual slavery are war crimes. 319 For rape, the perpetrator,\namong other things, invaded the body of a person by conduct resulting in penetration,\nhowever slight, of any part of the body of the victim or of the perpetrator with a sexual organ,\nor of the anal or genital opening of the victim with any object or any other part of the body.320\nSexual violence involves, among other things, a grave act of a sexual nature, but does not\nrequire penetration of a person’s body.321 For sexual slavery, the perpetrator exercised any or\nall of the powers attaching to the right of ownership over a person, such as by purchasing,\nselling, lending or bartering such a person, or by imposing on them a similar deprivation of\nliberty, and caused the person to engage in acts of a sexual nature. 322 Rape and other forms\nof sexual violence may also amount to torture.323 Sexual and gender-based violence also\nconstitutes human rights violations, such as those contained in international human rights\ntreaties, including the right to be protected from torture or cruel, inhuman or degrading\ntreatment,324 the right to equality,325 and the right to health.326"},{"id":"a-hrc-52-crp-4-p0579","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"579","seq":581,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Many of the instances of rape and sexual violence documented by the Commission\ntook place in the course of operations during which Russian armed forces went from house\nto house, looking for persons collaborating or sympathizing with Ukrainian authorities. There\nare instances in which several rapes were allegedly committed in the same village."},{"id":"a-hrc-52-crp-4-p0580","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"580","seq":582,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The majority of victims were women who were alone at home. Rapes were committed\nat gunpoint, with extreme brutality and with acts of torture, such as beatings and strangling.\nPerpetrators at times threatened to kill the victim or her family if she resisted. In some cases,\nmore than one soldier raped the same victim, or the perpetrator raped the victim several times.\nIn one incident, the victim was pregnant and begged, in vain, the soldiers to spare her; she\nhad a miscarriage a few days later (see case descriptions starting para. 586)."},{"id":"a-hrc-52-crp-4-p0581","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"581","seq":583,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In some instances, perpetrators also executed or tortured husbands and other male\nrelatives, who tried to interfere. Family members, including children, and relatives were\nsometimes forced to watch perpetrators rape their loved ones. If they were not in the same\nroom, they could hear their ordeal without the possibility to intervene. Victims reported on\noccurrences in which perpetrators also stole money, phones or other belongings."},{"id":"a-hrc-52-crp-4-p0582","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"582","seq":584,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In one case, the control and power exercised over the victim was such that the\nperpetrator’s behaviour amounted to sexual slavery. In March 2022, in a village in the\nChernihiv region, Russian armed forces occupied the home of the victim for 20 days. Every\nnight, the unit commander slept with a 16-year-old girl, raped, strangled, and beat her; he\nthreatened to kill her relatives and have soldiers of his unit gang rape her. The Commission\nhas received allegations regarding two other cases in which Russian armed forces exercised\ntheir power over members of two families, requesting them to cook or do their laundry, while\nregularly raping and abusing a woman and a 14-year-old-girl, respectively."},{"id":"a-hrc-52-crp-4-p0583","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"583","seq":585,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Interlocutors often mentioned that Russian soldiers occupying villages were under the\ninfluence of alcohol, which was especially the case of younger soldiers. This was reported\nby survivors from Chernihiv, Kherson, Kyiv and Zaporizhzhia regions. Under international\nlaw, voluntary intoxication is not recognised as a ground for excluding criminal\nresponsibility.327"},{"id":"a-hrc-52-crp-4-p0584","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"584","seq":586,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Some women resorted to tactics to avoid attracting Russian soldiers’ attention when\nthey had to go out, such as wearing dirty and baggy clothes and not doing their hair. When\nRussian soldiers were checking homes or shelters, some inhabitants hid younger women by\nfear the soldiers would take them away and sexually abuse them.\n321\nElements of Crimes of the International Criminal Court, p. 20 (article 8(2)(b)(xxii)-6, war crime of\nsexual violence).\n322 Elements of Crimes of the International Criminal Court, p. 19 (article 8(2)(b)(xxii)-2, war crime of\nsexual slavery).\n323 For example, ICTY, Prosecutor v. Delalić et al., Case No. IT-96-21-T, Judgement, 16 November\n1998, paras. 475-496; ICTR, Prosecutor v. Akayesu, Case No. ICTR-96-4T, Judgement, 2 September\n1998, para. 687.\n324 International Covenant on Civil and Political Rights, article 7; Convention against Torture and Other\nCruel, Inhuman or Degrading Treatment or Punishment, article 1; Convention on the Rights of the\nChild, articles 19 and 37 (a).\n325 Convention on the Elimination of All Forms of Discrimination against Women, articles 1 to 5.\n326 International Covenant on Economic, Social and Cultural Rights, article 12; Convention on the\nElimination of All Forms of Discrimination against Women, article 12; Convention on the Rights of\nthe Child, articles 24 and 39.\n327 Rome Statute of the International Criminal Court, article 31(1)(b) states that intoxication may be a\nground for excluding criminal responsibility, with the exception of voluntary intoxication."},{"id":"a-hrc-52-crp-4-p0585","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"585","seq":587,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims shared feelings of shame, anger and fear with the Commission. One woman\nstated: “I am an old woman, I am a mother and grandmother, and I am a widow, but even I\nwas so scared that Russian soldiers would come for me and rape me. I did not understand\nwhy they spotted me, why that prison-guard-looking soldier stopped me and harassed me”.\nPsychologists who assisted victims told the Commission that survivors believed that Russian\nsoldiers committed rapes to humiliate the victims; one of the survivors reportedly stated: “it\nwas done just to humiliate us as human beings”. Another psychologist and a lawyer\nsupporting survivors of rape mentioned that Russian soldiers used xenophobic and vulgar\nexpressions while they raped two girls.\nCase descriptions\nKyiv region"},{"id":"a-hrc-52-crp-4-p0586","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"586","seq":588,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, in a village in the Kyiv region, two Russian soldiers entered a home\nof a young couple and their four-year-old daughter. The soldiers raped the woman several\ntimes and forced the man to watch. The perpetrators then committed various acts of sexual\nviolence on the husband, mocking and humiliating him. They subsequently forced the couple\nto have sexual intercourse in their presence and threatened to kill them if they did not obey.\nTheir little girl was in an adjacent room and heard the screams of her mother during the whole\ntime. One of the soldiers then went to the other room and forced the four-year-old girl to\nperform oral sex on him. The little girl is now scared of men in uniform."},{"id":"a-hrc-52-crp-4-p0587","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"587","seq":589,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, a Russian soldier entered the home of a couple in a village in the Kyiv\nregion. As the husband was trying to protect his wife, the soldier shot him several times in\nthe abdomen, and took the wife to a nearby house. He threatened to kill her, ordered her to\nundress, and raped her. As he was doing so, other soldiers arrived and took him away. When\nshe returned to her home, she found her husband seriously wounded. She was unable to take\nhim to the hospital because of the fighting. He died of his injuries two days later. Witnesses\nalleged that the perpetrator was involved in similar acts in the neighbourhood."},{"id":"a-hrc-52-crp-4-p0588","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"588","seq":590,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, in a village in the Kyiv region, four Russian soldiers broke into a 47-\nyear-old woman’s house. She recollected that the soldiers were “dirty, smelly, and drunk.”\nShe told the Commission that one of the soldiers asked for her name, and then ordered the\nother three to wait for him outside of the house. He raped her several times and beat her with\nhis rifle. She lived on the outskirts of the village and could not call for help."},{"id":"a-hrc-52-crp-4-p0589","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"589","seq":591,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the beginning of March 2022, in a village in the Kyiv region, nine Russian soldiers\nvisited a couple’s home a first time. Later, two soldiers returned. While the wife was hiding\nin the shelter with her four-year-old son, her husband went to open the door. She heard a\ngunshot. The soldiers ordered her out of the shelter. After threatening to kill her in front of\nher son, one of the soldiers ordered the woman to take off her clothes. The two soldiers raped\nher multiple times. Being intoxicated, they fell asleep. The victim took this opportunity to\nrun away with her son. She saw the body of her husband lying in the family yard. In June\n2022, the Ukrainian authorities initiated proceedings in absentia against a soldier from the\n239th Regiment of the 90th Guards Tank Division of the Armed Forces of the Russian\nFederation for the rape and murder. The Commission has independently collected\ninformation showing that the 239th Regiment was located near the village in early March."},{"id":"a-hrc-52-crp-4-p0590","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"590","seq":592,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, in the same village in the Kyiv region, three Russian soldiers forced\ntheir way into a woman’s home. She was alone, as her husband had left a few days before to\nhelp the Ukrainian military. The three soldiers went into the basement and stole food and\nmoney. Two of them raped the woman in turns and choked her, while the third soldier\nwatched masturbating. The victim later found out that her husband had been tortured and\nexecuted by Russian armed forces about 15 km away. The victim said that she had suicidal\nthoughts in the aftermath."},{"id":"a-hrc-52-crp-4-p0591","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"591","seq":593,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, in another village in the Kyiv region, three Russian soldiers, acting\nunder the influence of alcohol, forced their way into the home of a three-month pregnant\nwoman. They started to interrogate her about Ukrainian armed forces positions in the area.\nThey beat her and tortured her, breaking several of her teeth with the butt of a rifle and\npouring burning liquid on her skin. Two of the soldiers then raped her while continuing to\nbeat and choke her to the point that she lost consciousness several times. She kept repeating\nto them she was pregnant and begged them to spare her. She had a miscarriage a few days\nlater. The Ukrainian authorities launched an investigation into the incident and identified two\nof the perpetrators."},{"id":"a-hrc-52-crp-4-p0592","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"592","seq":594,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has been investigating other serious allegations of sexual violence\ncommitted during the same period in another village of the Kyiv region. The allegations\ninclude the gang rape of a woman and her teenage daughter, as well as forced nudity of two\nmen in front of a woman relative. A 66-year-old woman from this village told the\nCommission how she was sexually harassed by a Russian soldier, who was around 50 years\nold, while she was trying to fetch water with one of her female neighbours. The soldier\nstopped them on the road, grabbed her upper arm, and said aggressively: “your green eyes\nare driving me crazy, bitch!”. He asked her to invite him for tea, to “have good time”. He\nheld his rifle pointed at her and kept his finger on the trigger all the time while talking to her\nand threatened that he would kill her. The husband of one of the women arrived and they\neventually managed to talk their way out. The victim told the Commission that she perceived\nthe soldier’s comments and actions as a threat of rape and murder.\nChernihiv region"},{"id":"a-hrc-52-crp-4-p0593","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"593","seq":595,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, in a village in the Chernihiv region, Russian armed forces occupied a\nhome for 20 days. Every night, the unit commander slept with a 16-year-old girl, raped,\nstrangled, and beat her; he threatened to kill her relatives and have soldiers of his unit gang\nrape her. In addition to the war crimes of rape, torture and unlawful confinement, the conduct\nof the perpetrators also amounts to sexual slavery. When the commander was assaulting the\nvictim and her brother tried to intervene, the soldiers kept him with cuffs on his hands outside\nand beat him, each night, for several nights. The Ukrainian authorities identified two of the\nperpetrators as belonging to the 80th Tank Regiment of the 90th Guards Tank Division and\nconvicted two of them in absentia.328 The Commission has independently collected\ninformation showing that the 80th Tank Regiment was located near the village in early March\n2022. In the same village, in March 2022, a resident found the body of an 82-year-old woman\nin her apartment. He said that she was half naked with blood around her genitals, suggesting\nthat she might have been subjected to sexual violence before her death. Her family refused\nto report the case to the police or to request a post-mortem examination."},{"id":"a-hrc-52-crp-4-p0594","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"594","seq":596,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, in a village in the Chernihiv region, an intoxicated Russian soldier\nattempted to rape a young woman in front of her three-year-old son. One of her relatives\ninterrupted the soldier, as he was trying to undress the victim. The relative’s screams\ntriggered the soldier to discharge his firearm, which prompted the neighbours to seek help\nfrom other Russian soldiers stationed nearby, who came and took him away. The day after\nthe incident, a sergeant came to verify what had happened. He apologised and promised to\ncontrol his men.\nKharkiv region"},{"id":"a-hrc-52-crp-4-p0595","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"595","seq":597,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the middle of March 2022, in a village in the Kharkiv region, then under Russian\narmed forces control, some soldiers forced their way into the basement of a school, in which\nabout 40 inhabitants, mostly women and girls, were sheltering. One of the soldiers, who was\narmed, ordered everyone to line up. He took one of the women into one of the empty\nclassrooms. At gunpoint, he ordered her to undress and raped her several times. He also\nslashed her cheek and neck and cut off some of her hair."},{"id":"a-hrc-52-crp-4-p0596","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"596","seq":598,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has investigated other allegations concerning rape and sexual\nviolence committed in the Kharkiv region. In one of these situations, starting March 2022, a\nRussian armed forces commander reportedly sexually abused and raped a 14-year-old girl\nliving with her mother and her 17-year-old brother, during almost four months, in exchange\nfor protection, food, and medicine. The whole family ultimately managed to escape. In\nanother situation, at the beginning of July 2022, several drunk Russian soldiers came to the\nhouse of a 72-year-old woman. One young Russian serviceman reportedly beat her,\nundressed her, pushed her onto the bed, unsuccessful attempted to penetrate her, and forced\nher to perform oral sex on him. The Commission was told that his fellow soldiers arrived and\n328 Office of the General Prosecutor of Ukraine, “Two more soldiers of the Russian Federation were\nsentenced for brutal treatment of civilians and sexual violence against a minor”, 2 November 2022.\n(available only in Ukrainian)\ntold him that they had to go. The woman lodged a complaint at the Russian armed forces’\nlocal office and was subsequently invited on two occasions to review photos of possible\nperpetrators.\nKherson region"},{"id":"a-hrc-52-crp-4-p0597","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"597","seq":599,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the end of April 2022, in a village in the Kherson region, a Russian soldier\napproached a couple who were feeding a neighbour’s animals and introduced himself as the\ncommandant of the area. The woman felt very uncomfortable, as she could feel that he was\nlooking at her. The commandant asked her whether she had children. She answered\nnegatively. A few days later, the commandant and some of his men presented themselves at\ntheir home. The soldiers undressed the husband partially and one of them said that they were\ntaking him to the nearby school, which they used as a detention place. When the woman tried\nto interfere, the commandant grabbed her saying he would take her with him because she\nneeded “psychological assistance, as she was too stressed”. The husband’s mother tried to\nfollow her daughter-in-law, but the commandant ordered her to stay at her home and fired a\nshot near her head. The soldiers took the husband to the school, tied him up to a chair,\nquestioned, and beat him so violently that he had difficulties breathing. One soldier poured\nhot water onto him and beat his fingers with a knife handle. During this time, the commandant\nbrought the woman to another room of the school, from where she could hear her husband\nscream. The commandant threatened to kill her husband or make him “invalid” if she did not\nagree to have sex with him. He further said that if she did not agree, he would rape her in a\nforced and painful manner, make her his frontline wife, and when he would be tired of her,\nshe would become someone else’s wife. The commandant raped the woman and told her that\nin case she became pregnant, she should call the baby “Aleksandra” or “Aleksander” and\ngave her his call sign."},{"id":"a-hrc-52-crp-4-p0598","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"598","seq":600,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has also investigated a situation in the middle of March 2022, in a\nvillage of the Kherson region. Two Russian soldiers entered a home where two girls, aged\n12 and 16, were present. One of the soldiers, intoxicated, called for the 16-year-old, and\nordered her to undress. The second soldier tried to intervene, but to no avail. The attacker\nreportedly assaulted the adolescent girl, strangled her, said he would kill her, adding “either\nyou sleep with me now or I will bring 20 more men”, and raped her. He tried to rape her\nagain, but other soldiers prevented him.\nii)    Sexual and gender-based violence in detention"},{"id":"a-hrc-52-crp-4-p0599","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"599","seq":601,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found numerous instances of sexual and gender-based violence\ncommitted by Russian authorities and persons supporting them in detention facilities, or\notherwise during detention. This included rape and sexual violence as war crimes, which can\nalso amount to torture. In some cases, perpetrators threatened detainees with rape and sexual\nviolence. Victims were both women and men, with a majority of men, and both civilians and\nprisoners of war. Cases were documented in Donetsk, Kharkiv, Kherson, Kyiv, Luhansk\nregions, in Ukraine, and in the Russian Federation."},{"id":"a-hrc-52-crp-4-p0600","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"600","seq":602,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In addition to being war crimes, rape and other forms of sexual violence may also\namount to torture.329 Torture involves, among other things, the intentional infliction of\n“severe pain or suffering, whether physical or mental”. 330 Threats of rape in certain\ncircumstances may also cause severe mental pain or suffering amounting to torture or\ninhuman treatment."},{"id":"a-hrc-52-crp-4-p0601","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"601","seq":603,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The evidence collected shows that rape and sexual violence that amount to torture,\nand the threat of such, have been important aspects of the torture which has been exercised\nby Russian authorities during detention. Such acts consisted of rape, electric shocks on\ngenitals, and exercising traction on the penis. According to victims, the purpose of such\ntreatment was to extract information or confessions, to force the victims to cooperate or sign\ndocuments, to punish, intimidate, or humiliate the victims, as individuals or as a group. The\nCommission also reviewed cases in which Russian authorities committed sexual violence\namounting to torture in other circumstances shown on authenticated open-source videos, and\nit has analysed signs of such acts on photographs of bodies of deceased victims."},{"id":"a-hrc-52-crp-4-p0602","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"602","seq":604,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims shared accounts regarding cases of detention in inhuman conditions, some of\nwhich have a gender aspect. In several cases, men and women were detained in the same\ncells. Inhuman conditions were mainly a consequence of inadequate access to hygiene.\nFormer detainees overwhelmingly reported on the lack of proper access to a toilet during\ndetention. Toilets often consisted of a bucket in the corner of the room, or a bottle for urine.\nAccess to water for hygiene was also limited or non-existent. When it was available, there\nwas no privacy. Such conditions can lead to serious infections and diseases, women being\nmore prone to them because of their anatomy. Some women restricted their water and food\nintake out of shame to use the toilet in front of others. Menstruating women also suffered\nbecause of the lacking hygiene (see para. 511)."},{"id":"a-hrc-52-crp-4-p0603","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"603","seq":605,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims and witnesses who shared their traumatic experiences expressed feelings of\nhumiliation. In addition to the use of dehumanising terms to address detainees, perpetrators\nused sexual slurs towards women. For example, at the Izium Railway Hospital Russian\nauthorities routinely addressed a woman in sexualised terms.\nCase descriptions\nSexual violence committed during torture"},{"id":"a-hrc-52-crp-4-p0604","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"604","seq":606,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Victims of torture in detention facilities maintained by Russian authorities described\nmethods of torture using sexual and gender-based violence, both in Ukraine and in the\nRussian Federation. One former prisoner of war detained in the Olenivka penal colony,\nDonetsk region, indicated that Russian armed forces used such methods as electric shocks on\nmen’s genitals or lifting them with a rope tied to their genitals, to force them to sign self-\nincriminating documents. One man detained at the Izium Railway Hospital, Kharkiv region,\ntold the Commission that Russian authorities attempted to put clips to administer\nelectroshocks on his genitals but had to discontinue as he lost consciousness. In the pre-trial\ndetention facility No. 5 (SIZO-5) in Donetsk city, electric shocks on genitals were also\nreportedly used."},{"id":"a-hrc-52-crp-4-p0605","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"605","seq":607,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the end of March 2022, in Kherson city, Russian armed forces unlawfully confined\na priest. During confinement, they tied his hands and hooded him, beat and strangled him,\nundressed him, threatened to rape him using a baton, and, according to the victim, attempted\nto penetrate his anus; all in order to force him to make statements in which he would agree\nto cooperate with Russian-appointed authorities."},{"id":"a-hrc-52-crp-4-p0606","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"606","seq":608,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the end of March 2022, in Motyzhyn village, Kyiv region, after the withdrawal of\nthe Russian armed forces, two members of the Ukrainian Territorial Defence Forces who had\nbeen detained, were found dead, with shots in the head. Their bodies were undressed from\nthe waist down and showed signs of torture. One of the bodies bore signs consistent with\nsexual violence (see paras. 360-363)."},{"id":"a-hrc-52-crp-4-p0607","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"607","seq":609,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission analysed a video which emerged in April 2022, showing seven dead\nbodies in what appear to be Ukrainian uniforms, lined up on the ground. One of them, lying\non his belly, had his pants pulled down to his ankles and underwear pulled down to his knees\nand presented signs highly suggestive of sexual violence."},{"id":"a-hrc-52-crp-4-p0608","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"608","seq":610,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the end of July 2022, three videos circulated which appear to show four Russian\nsoldiers emasculating and killing a person who appears to be a wounded Ukrainian prisoner\nof war. The prisoner, lying face down on the ground, had his hands tied at the back, each leg\ntied to a rope, and a part of his uniform cut at the buttocks’ level. The soldiers gagged him,\nand two of them kicked him with their feet on the head and on his back. One of the soldiers\ncut his underwear with a cutter and emasculated the victim with the same tool. One of the\nsoldiers then shot the victim in the head and two of them dragged his body towards a nearby\nditch. After analysing all the information at its disposal, the Commission identified two of\nthe suspected perpetrators on the video and the unit to which they belong – the “Akhmat-\nSpecial Rapid Response Unit” of the Russian armed forces, as well as its likely command\nstructure.\nRape and threats of rape and sexual violence"},{"id":"a-hrc-52-crp-4-p0609","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"609","seq":611,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has documented cases in which Russian authorities raped women\nduring confinement. A young woman who had been detained in July 2022, in the Police\nDepartment of Balakliia, in Kharkiv region (see paras. 552-556), by Russian armed forces,\ntold the Commission that in an interrogation room, a Russian soldier undressed her forcefully,\ninsulted her, and started to touch her all over her body. He raped her, ordered her to be silent,\nand threatened that otherwise he would call his colleague to rape her too. Subsequently, he\ntold her to not tell anyone, as otherwise he “will not be so kind anymore”, adding that he\nknew her name and where she lived. Another guard was standing at the door when she came\nout of the room and made sarcastic comments."},{"id":"a-hrc-52-crp-4-p0610","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"610","seq":612,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"A 52-year-old woman who had been detained together with her husband by Russian\narmed forces, in July 2022, in a detention facility in the Railway Polyclinic in Izium, Kharkiv\nregion, told the Commission that in the detention facility, Russian authorities took her to an\ninterrogation room. There, they undressed her forcefully. They touched her on different parts\nof her body. They called her “whore”. The commander ordered her to perform oral sex on\nhim. He told her that in the future, each time she heard a knock on the door, she needed to\nundress quickly, turn around and face the wall, and wait for further orders. She later\noverheard that the commander told her husband that he had raped her and that “she had liked\nit”. The victim also underwent electric shocks and was hanged with hands tied behind her\nback (see para. 528)."},{"id":"a-hrc-52-crp-4-p0611","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"611","seq":613,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"During confinement, Russian authorities also in some instances threatened detainees\nwith rape and sexual violence. A woman told the Commission that in June 2022, Russian\narmed forces had detained her together with her 16-year-old daughter in the Printing House\nof Balakliia, Kharkiv region. During interrogation, after the perpetrators disliked her answers,\nthey stated that “now the real interrogation had started” and asked her if she wanted to see\nhow her daughter was raped. The woman, who had a heart condition, collapsed, and required\nhospitalization. A Ukrainian woman reported to the Commission how, at the end of March\n2022, Russian armed forces detained her after searching her home, confined her first in\nUkraine, deported her to the Russian Federation, and detained her again in SIZO-1, in Kursk\ncity (see 561-563). There, Russian authorities placed her in a room with male detainees. They\ncommented how they could easily kill her, that no one would be looking for her, how they\ncould rape her, and no one would be punished for that, adding that they could throw her body\nat the border, and everyone would think that she was raped and killed by Ukrainians. Former\nprisoners of war in the Olenivka penal colony and SIZO-5 in Donetsk city, both in Donetsk\nregion, told the Commission that they were threatened “to be put on the bottle”, which is a\neuphemism for rape.\nInhuman conditions"},{"id":"a-hrc-52-crp-4-p0612","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"612","seq":614,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Conditions of detention were consistently inhuman during unlawful confinement,\nwhich, in some instances, disproportionately affected victims depending on their gender and\nsex. In Yahidne village, Chernihiv region, where 365 civilians were unlawfully confined in\nthe basement of a school, victims described that toilets consisted of buckets that the detainees\nhad to use in front of everybody. As a consequence, women restricted their water and food\nintake. One woman told the Commission that her mother was hardly eating or drinking, out\nof shame to use the toilet in front of others. When water was available to wash, there was no\nprivacy (see paras. 541-543)."},{"id":"a-hrc-52-crp-4-p0613","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"613","seq":615,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the Olenivka penal colony, Donetsk region, one victim explained that the barracks\nwere so crowded that some prisoners had to sleep in the toilet. At some point, detainees were\nreportedly not allowed to defecate, as the sewage system was not functioning. In case\ndetainees could not hold themselves, they were allegedly severely beaten by the guards; as a\nresult, some avoided eating. At times, detainees were reportedly only authorised to use the\ntoilet for one minute. Some detainees had to get medical attention as a consequence. Former\nprisoners explained that they were also not allowed to use toilets during transport. A man\ndetained during one night in Boromlia, Sumy region, explained that he was not allowed to\nuse the toilet."},{"id":"a-hrc-52-crp-4-p0614","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"614","seq":616,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"One victim told the Commission that in the Manhush Police Office, Donetsk region,\nwomen were not allowed to close the door while on the toilet, as guards allegedly were afraid\nthey would attempt suicide. In the Olenivka penal colony and SIZO-5 in Donetsk city,\ndetained women reportedly did not have access to hygienic pads or tampons and were not\nallowed to wash during their menstruation. Most of the time, there was no access to hygienic\npaper. In the Makiivka temporary detention facility, in the Donetsk region, a former detainee\ntold the Commission that they were provided with Ukrainian books to use as toilet paper.\niii)     Forced nudity"},{"id":"a-hrc-52-crp-4-p0615","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"615","seq":617,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has found that in a variety of situations, Russian armed forces\nordered people to fully or partially undress, as part of detention and interrogation processes,\nor to verify the presence of tattoos. Victims were men, women, and one 17-year-old boy. The\nCommission documented such cases in Donetsk, Kharkiv, and Kyiv regions in Ukraine and\nin the Russian Federation."},{"id":"a-hrc-52-crp-4-p0616","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"616","seq":618,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Forcing someone to remain naked, including for prolonged periods, can be a form of\nsexual violence, which may constitute a war crime.331 Forced nudity may also be qualified as\noutrages upon personal dignity as a war crime, namely for an act that severely humiliates,\ndegrades or otherwise violates the dignity of one or more persons. 332 Strip-searches in an\ninstitutional setting, often in connection with a detention procedure, are only valid when\nperformed for a specific function and for a legal purpose within an authorised framework."},{"id":"a-hrc-52-crp-4-p0617","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"617","seq":619,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the cases investigated, forced nudity went beyond possible security requirements\nand was part of a process of ill-treatment and humiliation. Russian armed forces ordered\nforced nudity when they stopped people at filtration points, checkpoints, or in the streets, and\nduring detention. Sometimes, victims were told to undress up to the waist, sometimes they\nhad to remove all the clothes, except the underwear, and other times they had to fully undress.\nIn detention, Russian armed forces subjected women and men to intimate searches, in a\nhumiliating environment. Some victims reported that they were forced to undress or remain\nnaked for long periods of time, during a so-called “acceptance procedure” or during\ninterrogation (see paras. 562 and 565).\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0618","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"618","seq":620,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, Russian armed forces arrested a woman in Demydiv, Kyiv region.\nShe told the Commission that male soldiers stripped her fully naked, tied her hands, placed a\nbag on her head, and transported her to a detention place, while she was still fully naked.\nThere, they beat and interrogated her and gave her some clothes only the next day. In a nearby\nvillage, in March 2022, another witness told the Commission that he heard of several cases\nin which Russian soldiers fully undressed residents at a checkpoint and put them on the\nground for 10-15 minutes."},{"id":"a-hrc-52-crp-4-p0619","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"619","seq":621,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"At the end of March 2022, one man went through a filtration process as part of a group\nevacuating from Mariupol. He explained that Russian armed forces told him to remove all\nhis clothes so they could check whether he had tattoos. They checked his wife in a separate\nroom; she was allowed to keep her underwear. Other men and women from the same group\nunderwent the same process. Children were not subjected to this procedure, with the\nexception of a 17-year-old boy who looked “suspicious” to the Russian armed forces."},{"id":"a-hrc-52-crp-4-p0620","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"620","seq":622,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Also at the end of March 2022, one man was detained by Russian armed forces in the\nstreet of Balakliia city, Kharkiv region. He stated that upon checking his documents, the\nsoldiers discovered that he had served in the military and requested him to undress. They\nsubsequently brought him to a makeshift detention facility, where they asked him to undress\nagain."},{"id":"a-hrc-52-crp-4-p0621","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"621","seq":623,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In May 2022, two men who had been detained in the Olenivka penal colony, Donetsk\nregion, were forced to undress upon arrival. Some of the detainees were told to bend forward.\nThe process was humiliating."},{"id":"a-hrc-52-crp-4-p0622","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"622","seq":624,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, a woman who was deported by Russian armed forces to SIZO-2\nsituated in the Bryansk region, in the Russian Federation, told the Commission that upon\narrival, she was forced to undress in front of everyone. Also in March 2022, another woman\nwas subject to similar treatment at a detention facility in Glushkovo village, in the Russian\nFederation."},{"id":"a-hrc-52-crp-4-p0623","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"623","seq":625,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In the middle of March 2022, in Kyiv region, Russian armed forces detained a priest.\nHe explained to the Commission that they forced him to undress fully, as they were looking\nfor marks of weapons’ use on his skin. They beat him, interrogated him, and ordered him to\nparade naked for one hour in the streets of his village. He mentioned that one co-detainee\nwas also ordered to fully undress.\niv)    Sexual and gender-based violence against people belonging to the lesbian, gay,\nbisexual, transgender and intersex community"},{"id":"a-hrc-52-crp-4-p0624","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"624","seq":626,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission has received reports of violations of human rights targeting people\nbelonging to the lesbian, gay, bisexual, transgender and intersex (LGBTI)333 community\nbecause of their sexual orientation or gender identity. It examined reports of such violations\ncommitted during various situations, including during attacks on the premises of LGBTI\norganizations, at checkpoints, during a house search, and at one victim’s workplace. Victims\nhave been at particular risk at checkpoints, where armed forces carried out inspections,\nincluding of telephones, and were likely to discover the sexual orientation of the victims. The\nCommission documented one such case in Kyiv and examined reports of additional cases in\nKherson and Donetsk regions.\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0625","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"625","seq":627,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In late February 2022, the premises and staff of the “LGBT Human Rights Nash Svit\ncentre in Kyiv” were attacked twice. The first time, under the pretext of a flashing light\ncoming from the organization’s apartment, about ten members of a Ukrainian Territorial\nDefence Forces broke into the premises, where two gay couples were staying. After searching\nthe apartment and making comments about their sexual orientation, the attackers took the\nfour men to a nearby police station where the police officers forced them to stay in a stressful\nposition, insulted them because of their sexual orientation, and physically ill-treated them.\nMen who identified themselves as members of the Security Service of Ukraine interrogated\nthem and forced them to give access to their electronic devices. The victims were then\ndetained in a garage and released the next morning without further explanation. The next\nnight, a dozen men, most with automatic weapons and dressed in uniform, some with\n“Territorial Defence” markings, broke into the same premises, shouted homophobic slurs at\nthe same four men, and threatened to kill them. They ordered the four men to lie face down\non the floor, tied their hands behind their backs, and threatened to kill them while holding\nweapons to their heads. The attackers took some electronic devices, forced one of the victims\nto open a safe, and stole a large sum of money. After the attackers had left, the victims called\nthe police, who only came the next morning. Ukrainian authorities have identified some of\nthe attackers."},{"id":"a-hrc-52-crp-4-p0626","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"626","seq":628,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In March 2022, at a checkpoint near Posad-Pokrovske, Kherson region, Russian\nsoldiers reportedly detained two men because of their perceived sexual orientation, and\nrobbed them, ill-treated them, and shot at their vehicle. Also in March 2022, in Kherson city,\na patrol of the Russian armed forces reportedly stopped several men who had left the Kherson\nAIDS centre with medicine. During a documents verification and a search procedure, they\nfound AIDS drugs. The soldiers allegedly came to the conclusion that the men were gay,\ninsulted them on their sexual orientation and HIV status, and threatened to rape and kill them;\nthey also stole money from them."},{"id":"a-hrc-52-crp-4-p0627","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"627","seq":629,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In April 2022, Russian armed forces reportedly detained about 50 traders, including\ntwo men aged 48 and 17, at the wholesale vegetable market in Velyki Kopani village and\nconfined them near the town of Oleshky, both in Kherson region. They allegedly subjected\nthe detainees to abuse and ill-treatment, and threatened to rape the two men, who in the view\nof the Russian soldiers, had a homosexual orientation."},{"id":"a-hrc-52-crp-4-p0628","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"628","seq":630,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In May 2022, in Kherson city, Russian armed forces allegedly attacked the premises\nof the LGBTI organization “Insha”. Also in May 2022, in a small village in Kherson region,\nRussian armed forces reportedly burst into the house of a lesbian couple and requested to\nspend the night there. After they understood that the two women were a couple, the soldiers\nstarted to question them on their sexual orientation and allegedly raped them."},{"id":"a-hrc-52-crp-4-p0629","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"629","seq":631,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In May 2022, in Donetsk city, a new supervisor appointed by Russian authorities,\nreportedly subjected a woman to persistent sexual harassment because of her sexual\norientation.\n3)    Challenges in reporting and investigating sexual and gender-based violence"},{"id":"a-hrc-52-crp-4-p0630","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"630","seq":632,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Owing to various challenges, sexual and gender-based violence is generally under-\nreported and the Commission believes that this is the case also in the current armed conflict.\nThe culture of silence that surrounds sexual violence, linked to gender stereotypes, stigma,\nsocial ostracism, religious and family considerations – real or perceived – makes survivors\nreluctant to speak out, or report to the authorities, or seek medical services, especially in rural\nareas."},{"id":"a-hrc-52-crp-4-p0631","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"631","seq":633,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Consequently, at the time of the Commission’s investigations, many victims of sexual\nand gender-based violence and their families were not yet willing to make their cases public\nor known to authorities; a situation that victims themselves, mental health professionals,\njournalists and local officials confirmed to the Commission. In addition to this reluctance to\nreport, victims, witnesses, authorities, and psychologists informed the Commission that many\nwomen and girls victims have left their village, or even the country, because of the fear of\nstigma or of being blamed for having been sexually assaulted. Another reason for the under-\nreporting of sexual violence was the fear of some victims that the perpetrators will come back\nor that Russian agents will transmit this information to authorities in the Russian Federation."},{"id":"a-hrc-52-crp-4-p0632","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"632","seq":634,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Male survivors, both civilian and military, are also likely to choose not to report such\na crime, and generally remain reluctant to mention sexual violence. Survivors of sexual\ntorture will be more inclined to report torture than the sexual aspect of it."},{"id":"a-hrc-52-crp-4-p0633","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"633","seq":635,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Media reporting practices regarding situations in which sexual violence has been\ncommitted can be harmful.334 Although reporting on sexual violence in the current conflict\nhas been mostly ethical, some survivors have expressed distress after tactless media coverage.\nSuch reports can have a direct bearing on them in reinforcing stereotypes and the stigma\nattached to sexual violence, notably through allowing the identification of the survivors or\nthrough reporting differently the ordeal of men and women."},{"id":"a-hrc-52-crp-4-p0634","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"634","seq":636,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Owing to the context of the ongoing armed conflict, in many cases survival needs take\npriority over other concerns. Several psychologists working with survivors of sexual and\ngender-based violence told the Commission that some victims do not consider their traumatic\nexperience to be a serious violation of human rights and crime because of the context of the\ncurrent conflict. They explained that women who have children and relatives to take care of\nneed to attend to their basic needs and protect them. Therefore, it is of utmost importance to\ngive victims sufficient time and space to come forward."},{"id":"a-hrc-52-crp-4-p0635","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"635","seq":637,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Sometimes victims are in a state of confusion and may not identify a violation if it\nwas committed in exchange for food, a transfer out of a dangerous area, or access to health\nand medicine; in some situations, victims may even feel gratitude to the perpetrators and\nrefuse to identify them because they protected them from others, spared their daughter or did\nnot kill them."},{"id":"a-hrc-52-crp-4-p0636","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"636","seq":638,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Finally, it is not always possible to document forensically the existence of rape and\nthe full extent of the victims’ traumas, as in some areas, access to such specialised services\nis lacking, or displacement has impacted the access to victims. Forensic reports cannot always\ndocument sexual violence owing to a variety of reasons, such as heavy workloads or focus\non the immediate cause of death, rather than the entirety of the trauma sustained by the\nvictims or the condition of the remains.\n4)    Impact of sexual and gender-based violence and access to services"},{"id":"a-hrc-52-crp-4-p0637","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"637","seq":639,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Survivors of sexual and gender-based violence generally face devastating direct long-\nterm impacts on their physical conditions, including physical pain, miscarriage, unwanted\npregnancy, and sexually transmitted diseases. Sexual and gender-based violence may also\nresult in severe psychological trauma, depression and suicidal thoughts. In addition, survivors\nface socio-economic challenges, as they often lose their economic income and social\nnetworks when they flee their communities due to the security situation or the sense of shame\nand extra attention they face. Some survivors even face difficulties in relating with close\nfamily members or relatives."},{"id":"a-hrc-52-crp-4-p0638","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"638","seq":640,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"For example, the Commission spoke with a survivor whose situation sheds light on\nthe multi-layered impacts sexual gender-based violence may have. The sole breadwinner of\nher family, the victim explained that she suffers serious physical and socio-economic\nconsequences from the rape she experienced while being pregnant. Following complications\ndue to the rape and a subsequent miscarriage, she needs gynaecological treatment.\nFurthermore, in March 2022, her home was destroyed, and she had to entrust her three\nchildren to a relative who is now in a neighbouring country. The survivor had to move to a\ncollective shelter in Kyiv. She also lost her work, as her former employer had closed down.\nShe faced difficulties finding a new job, because she was wounded during the attack on her\nand now suffers from a speech impairment."},{"id":"a-hrc-52-crp-4-p0639","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"639","seq":641,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"The Commission received many accounts of psychological trauma resulting from\nsexual and gender-based violence. Some survivors of rape or relatives forced to watch\nsomeone close to them being raped expressed that they are suffering from trauma and have\nhad suicidal thoughts, or even attempted suicide. One man explained that shortly after\nRussian armed forces committed sexual violence on him in public, humiliating him, his hair\nand beard turned completely white overnight. Another survivor, whose husband was also\nkilled by Russian soldiers, said that her daughter and her new-born grandson she cares for\nsaved her from suicide and that she was now living for them. A young girl victim of rape by\na Russian soldier is now scared at the sight of persons in uniform."},{"id":"a-hrc-52-crp-4-p0640","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"640","seq":642,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Rape and sexual violence also affect social and economic aspects of the life of\nsurvivors, with women being disproportionally impacted because of pre-existing economic\ninequalities.335 In a case documented by the Commission, a victim of rape whose husband\nwas executed, explained that she is now the only breadwinner in her family. But since she\nlost her job because of the current economic situation and everyone in the village knows that\nshe was raped, she had to move to another place, with all the economic implications that this\nentails."},{"id":"a-hrc-52-crp-4-p0641","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"641","seq":643,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Despite the setup of specific services, including mobile and remote services, access to\nsexual and reproductive health services in Ukraine has become challenging because of attacks\nagainst health facilities, infrastructure, and displacement. In some of the neighbouring\ncountries hosting many Ukrainian refugees, access to sexual and reproductive health services\nalso appeared to be challenging, which adds anxiety and trauma to the victims of rape and\nsexual violence. Many refugees have indicated they have an urgent need for health and legal\nservices.336"},{"id":"a-hrc-52-crp-4-p0642","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"642","seq":644,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"In addition, those services should take into account gender disparities among those\nseeking help. A psychologist told the Commission that men who survived sexual violence\ntend to seek help later, share their experience with more difficulties, and take longer to\nrecover. She explained how strong gender stereotypes that still prevail in Ukrainian society 337\nhave a negative impact on people’s health and well-being: “In Ukraine, strong men are not\nsupposed to be victims of sexual violence.”"},{"id":"a-hrc-52-crp-4-p0643","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"643","seq":645,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"It is nevertheless essential to underline that many Ukrainian civil society\norganizations, international non-governmental and governmental organizations that support\nvictims of sexual and gender-based violence provide services to survivors inside and outside\nUkraine, face-to-face or remote. Most of the time services are comprehensive and include\nreproductive health and other health care, psychological and social support, as well as legal\naid. However, some organizations can only afford to support individuals for a finite number\nof sessions or a limited time. Similarly, some mobile services established in order to reach\nrural areas and recently liberated zones are not permanently available, leading to uneven\naccess. Psychologists, who also cope with the consequence of the conflict, explained that they\nwere themselves overwhelmed and in need of psychological support."},{"id":"a-hrc-52-crp-4-p0644","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"644","seq":646,"section":"26. She identified one of them as the video technician. The Commission interviewed another","text":"Stress provoked by the conflict, loss, displacement, and change in the socio-economic\nsituation can lead to an increase in domestic violence.338 Tackling domestic violence was a\npriority in Ukraine before the war. The recording of domestic violence cases had decreased\ndue to the conflict.339 In its Concluding observations on the ninth periodic report of Ukraine,\nthe Committee on the Elimination of Discrimination against Women has recommended\nadditional measures to tackle domestic violence.340 On 1 November 2022, Ukraine acceded\nto the Istanbul Convention on preventing and combating violence against women and\ndomestic violence.341"},{"id":"a-hrc-52-crp-4-p0645","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"645","seq":647,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"In accordance with its mandate, the Commission has investigated allegations of\nviolations and crimes, irrespective of which party to the armed conflict was believed to be\nresponsible. In this context, it has examined allegations of personal integrity violations\ncommitted by Ukrainian authorities and persons affiliated with them. It has so far been able\nto document two incidents concerning the unlawful killing, wounding, or torture of captured\nRussian soldiers in the Kharkiv and Kyiv regions and has considered a third incident in\nLuhansk region. The victims were men with prisoner of war status."},{"id":"a-hrc-52-crp-4-p0646","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"646","seq":648,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Under international humanitarian law, prisoners of war must at all times be humanely\ntreated and protected, particularly against acts of violence or intimidation and against insults\nand public curiosity.342 The wounded shall receive, to the fullest extent practicable and with\nthe least possible delay, the medical care and attention required by their condition. 343\nMoreover, it is unlawful to torture, wound or kill prisoners of war or persons hors de\ncombat.344 Such conduct amounts to war crimes.345 Conversely, it is prohibited to commit\nperfidy, such as feigning an intent to surrender or feigning an incapacitation by wounds. 346"},{"id":"a-hrc-52-crp-4-p0647","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"647","seq":649,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Two of the cases documented were described in the Commission’s report to the United\nNations General Assembly on 18 October 2022.347 Investigations into these and other\nincidents have continued, and the Commission has been able to establish new elements,\nincluding related to the identity of the perpetrators. In the two incidents, it has concluded that\nthe people responsible either officially belonged to the Ukrainian armed forces or fought\nclosely with them when the incidents described below took place. In the third case, Ukrainian\narmed forces killed a number of Russian soldiers in the context of what appeared to be an\nattempt to surrender, but further investigation is needed to determine whether violations took\nplace (see case descriptions starting para. 649)."},{"id":"a-hrc-52-crp-4-p0648","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"648","seq":650,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Ukrainian authorities have responded to questions from the Commission related\nto these incidents. In a written response dated 30 September 2022, the Office of the\nProsecutor General of Ukraine informed the Commission that it had launched investigations\ninto allegations of ill-treatment of Russian prisoners of war in the incidents in villages Mala\nRohan, Kharkiv region, and Dmytrivka, Kyiv region, as described below. In response to\nfurther questions, on 27 January 2023, the Office of the Prosecutor General of Ukraine said\nthat it had initiated pre-trial investigations in those cases. It further stated that no objective\ndata supporting the involvement of Ukrainian military servicemen had been established at\nthat time, but the investigations were continuing.\nCase descriptions\nMala Rohan village, Kharkiv region, 24-26 March 2022"},{"id":"a-hrc-52-crp-4-p0649","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"649","seq":651,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Starting on 27 March 2022, a video circulated that shows a group of armed soldiers\nstanding over five apparently captured soldiers lying on the ground. They interrogate the\ncaptured soldiers and sometimes beat and kick them. Most of the captured soldiers appear\nwounded in their legs. The video further shows an individual shooting three additional\nstanding soldiers one by one in their legs from close range. They fall to the ground.\nAfterwards the shooter hits the third shot victim on the head with his rifle butt. The\ninterrogation of the captured soldiers has continued during this time."},{"id":"a-hrc-52-crp-4-p0650","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"650","seq":652,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Commission has established that the incident took place at the Malorohansk Dairy\nPlant in Mala Rohan village, Kharkiv region. Heavy fighting took place in that area in the\ndays before the video was made public, as Ukrainian armed forces launched an offensive that\nresulted in the withdrawal of Russian armed forces on 27 March 2022."},{"id":"a-hrc-52-crp-4-p0651","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"651","seq":653,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"While the Commission has not been able to conclusively determine what happened to\nall the captured soldiers, there are strong indications that at least some of them died. An\nundated video from a compilation of footage, among other details, shows other captured\nsoldiers and parts of the dairy plant on fire at night. Another video filmed on the dairy plant\non 28 March 2022 shows the remains of three burned corpses in the same location as the one\nwhere the captured soldiers were lying. Separately, a woman from the Russian Federation\nhas claimed in a media interview that one of the captives is her adopted son, who was reported\nmissing on 29 April 2022 in the course of his military service."},{"id":"a-hrc-52-crp-4-p0652","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"652","seq":654,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Commission has established that the unit most likely responsible for the incident\nis the “Slobozhanshchyna” volunteer unit, which was assembled partially from a disbanded\npolice battalion by its former commander after Russian armed forces invaded Ukraine on\n24 February 2022. It has also identified the commander of the unit. Other videos from the\ndairy plant show him together with some of the captured soldiers who are later seen being\nill-treated and tortured in the original video. The Commission has confirmed that this unit\nand its commander had been fighting together with the Ukrainian armed forces in the\noffensive to re-take Mala Rohan. It has not been able to determine whether the unit was\nformally integrated into the Ukrainian armed forces at the time of the incident."},{"id":"a-hrc-52-crp-4-p0653","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"653","seq":655,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"In addition, the Commission has examined videos and evidence suggesting that at\nleast three other captured Russian soldiers were subjected to similar treatment around the\nsame period in the same general area, possibly by the same unit. It recommends further\ninvestigations into these allegations.\nDmytrivka village, Kyiv region, around 29 March 2022"},{"id":"a-hrc-52-crp-4-p0654","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"654","seq":656,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"On 30 March 2022, a video emerged in which one soldier is shooting three times from\nclose range at the upper body of an already wounded soldier lying on the ground. The video\nalso shows three other motionless soldiers nearby in large puddles of blood, including one\nwith hands tied behind his back and a gunshot wound to his head, suggesting that he had\nlikely been executed. Several damaged military vehicles are visible at a distance and one\nmilitary vehicle with the letter “V” painted on it can be seen closer by. The faces of three\nsoldiers walking among the motionless bodies are clearly visible in the footage."},{"id":"a-hrc-52-crp-4-p0655","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"655","seq":657,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Commission has geolocated the video to a road close to Dmytrivka village, Kyiv\nregion. This incident took place in the context of a Ukrainian attack on a convoy of Russian\nmilitary vehicles. Ukrainian media outlets and other journalists reported on the attack and\nshowed footage from the site, including one video in which one of the Ukrainian soldiers\nfrom the initial video and the bodies of the Russian soldiers on the ground can be seen. On 2\nApril 2022, the Ukrainian Ministry of Defence published on social media a video showing a\ndestroyed convoy of Russian military vehicles on the same road under the heading\n“[j]ewellery work by Ukrainian forces in the Kyiv region”."},{"id":"a-hrc-52-crp-4-p0656","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"656","seq":658,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Based on indications in the video and other contextual information, the Commission\nhas concluded that the victims were Russian soldiers, and that the perpetrators belonged to\nthe Ukrainian armed forces or fought closely together with them. In the video, the\nperpetrators are wearing blue armbands and repeat “glory to Ukraine” several times. At least\nthree of the motionless bodies are wearing white armbands, usually worn by Russian soldiers,\nand the letter “V” is a common symbol on Russian military vehicles."},{"id":"a-hrc-52-crp-4-p0657","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"657","seq":659,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"In media coverage, the Georgian Legion, a military unit of mostly ethnic Georgian\nvolunteers under the control of the Ukrainian armed forces and the 114th Separate Territorial\nDefence Brigade (military unit A7042) of the Ukrainian armed forces, have been mentioned\nas participating in the abovementioned attack on the Russian military vehicles.348\nMakiivka village, Luhansk region, 11 November 2022"},{"id":"a-hrc-52-crp-4-p0658","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"658","seq":660,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Commission has analysed two videos relating to the surrender and death of a\ngroup of Russian soldiers on 11 November 2022. The first video shows a group of Russian\nsoldiers in the process of surrendering to a small group of Ukrainian armed forces. The\nsurrendering soldiers are seen coming out of a house with their hands behind their heads and\nlying down next to each other in the courtyard. The video apparently further shows that one\nof the surrendering soldiers opens fire on the Ukrainian armed forces, as he is stepping out\nof the house. The video then stops. The second video is a drone footage of the courtyard shot\nsometime after the first video. It shows nine soldiers lying on the ground. All of them appear\nmotionless, and several have blood pooling around their bodies, including near their heads,\nthat was not visible in the first video."},{"id":"a-hrc-52-crp-4-p0659","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"659","seq":661,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Commission has established that the incident took place at a farm near Makiivka\nvillage, Luhansk region. At that time, Ukrainian armed forces were retaking control of the\nvillage from Russian armed forces. A Ukrainian journalist describing the incident named\nboth the Ukrainian and Russian military units likely involved. 349"},{"id":"a-hrc-52-crp-4-p0660","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"660","seq":662,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Without further information, the Commission has not been able to conclude whether\nviolations took place in this incident. It has identified several hypotheses of possible\nviolations committed by both parties in this context. Some of them are outlined below."},{"id":"a-hrc-52-crp-4-p0661","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"661","seq":663,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The incident possibly shows a violation of the prohibition of perfidy, in this case\nfeigning surrender, by the Russian soldier who appears to be shooting."},{"id":"a-hrc-52-crp-4-p0662","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"662","seq":664,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The Commission has investigated whether the Russian soldiers lying on the ground\nalso feigned their surrender and therefore were still combatants, whether they were genuinely\nsurrendering and were either killed by accident in the ensuing shootout, or unlawfully killed."},{"id":"a-hrc-52-crp-4-p0663","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"663","seq":665,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"The drone footage shows most of the soldiers lying generally in the same position as\nin the first video, which suggests that they did not attempt – or did not have time – to move\nor to reach for weapons lying nearby. This could be an indication that the other soldiers were\nsincere in their attempts to surrender."},{"id":"a-hrc-52-crp-4-p0664","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"664","seq":666,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"In such a tense situation, with a soldier unexpectedly opening fire during a surrender,\nthe ensuing exchange of fire would likely injure and kill several of the soldiers lying on the\nground, even if they were sincere in their attempt to surrender."},{"id":"a-hrc-52-crp-4-p0665","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"665","seq":667,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"However, the Commission does not find it very likely that all the soldiers lying on the\nground were instantly killed in such a situation, particularly since they were lying in a row,\npartially covering each other. The Commission also notes that the drone footage shows\npooling of blood near the head of several of the soldiers, which could be an indication that\nsome of them were killed by gunshot to the head.\n348 Meduza, “Verified video appears to show Ukrainian troops killing Russian captives. Here’s what we\nknow about it.”; 8 April 2022.\n349 “New details of the battle for the village of Makiivka, Luhansk region”, New Voice, 24 November\n2022. (available only in Ukrainian and Russian)"},{"id":"a-hrc-52-crp-4-p0666","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"666","seq":668,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Without further information, the Commission has not been able to conclude whether\nany violation took place. It recommends further investigations of the incident.\nb) Alleged torture and ill-treatment of suspected collaborators"},{"id":"a-hrc-52-crp-4-p0667","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"667","seq":669,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Since 24 February 2022, the Ukrainian authorities have opened thousands of\ninvestigations into allegations of collaboration and treason in the context of the armed\nconflict.350 The Commission has collected and examined dozens of accounts from lawyers,\nformer detainees, and detainees’ relatives related to detentions under charges of high treason,\ncollaborative activity, and support for the aggressor state. It has reviewed allegations\nconcerning torture, ill-treatment, violations of procedural rights, and inhuman conditions\ncommitted by Ukrainian authorities during the detention of persons accused of collaboration."},{"id":"a-hrc-52-crp-4-p0668","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"668","seq":670,"section":"2. Personal integrity violations committed by Ukrainian authorities","text":"Witnesses reported beatings, mock executions, and threats to harm the detainee or\ntheir families. The Commission received reports concerning violations of procedural rights\nrelating to detention. For example, it was informed that law-enforcement officials frequently\ndid not produce arrest warrants and that some detainees were held incommunicado, sometime\nfor several days, according to lawyers. Sleep and food deprivation during detention have also\nbeen reported. The Commission is concerned about these allegations. However, at the time\nof the writing of this report, it has not been in a position to corroborate them."},{"id":"a-hrc-52-crp-4-p0669","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"669","seq":671,"section":"1. Overview","text":"The Commission has collected and reviewed allegations of violations of international\nlaw in the territories which the Russian Federation has occupied and placed under its\nauthority. It has examined the context and circumstances in which Russian-backed de facto\nauthorities organized and held so-called referendums in the occupied territories of Donetsk,\nKherson, Luhansk, and Zaporizhzhia regions on their annexation to the Russian Federation\nin September 2022. The Commission has documented a series of violations of international\nlaw committed by Russian authorities, including associated persons, in these areas with the\naim of forcing certain categories of persons to cooperate."},{"id":"a-hrc-52-crp-4-p0670","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"670","seq":672,"section":"1. Overview","text":"Under international humanitarian law, the Russian Federation was the Occupying\nPower of the four Ukrainian territories at the relevant times.351 An Occupying Power has the\nobligation to respect the laws in force in the country, unless absolutely prevented. 352\nInternational humanitarian law prohibits physical or moral coercion against protected persons\nsuch as those in the hands of the Occupying Power.353 Such persons shall be protected against\nall acts of violence or threats thereof.354 Confining a protected person without lawful reason\nis prohibited.355 An Occupying Power shall treat all protected persons with the same\nconsideration without any distinction based on, among other factors, political opinion. 356 It\nis prohibited to compel inhabitants of an occupied territory to swear allegiance to the\nOccupying Power.357 Further, an Occupying Power may not compel protected persons to\nserve in its armed or auxiliary forces, and no pressure or propaganda which aims at securing\nvoluntary enlistment is permitted.358"},{"id":"a-hrc-52-crp-4-p0671","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"671","seq":673,"section":"1. Overview","text":"The Commission has found that the holding of the so-called referendums, with\ndisregard to relevant provisions of the Ukrainian legislation, was in violation of international\nhumanitarian law. Moreover, it assessed that the preparation and unfolding of the so-called\nreferendums, in a general climate of fear and coercion, were also in violation of international\nhumanitarian law and did not respect relevant international standards. It notes that\ninternational bodies and States widely condemned the so-called referendums and the ensuing\nillegal annexation of these regions to the Russian Federation."},{"id":"a-hrc-52-crp-4-p0672","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"672","seq":674,"section":"1. Overview","text":"After annexation “treaties” between the Russian Federation and the de-facto\nauthorities of the occupied territories of the four regions granted Russian citizenship to\npersons residing in these areas, the Commission was informed of situations in which local\nresidents felt compelled to apply for Russian passports, which can be in violation of\ninternational humanitarian law. The Commission also documented instances in which\nRussian authorities used coercion against school personnel to force them to apply Russian\ncurricula, and against parents, to force them to enrol their children in schools operating under\nthe Russian education system. Furthermore, it collected testimonies indicating that Russian\nauthorities unlawfully confined local officials and public service employees to force them to\ncooperate and that they also carried out unlawful military conscription."},{"id":"a-hrc-52-crp-4-p0673","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"673","seq":675,"section":"1. Overview","text":"Due to security reasons and a lack of access, the Commission faced considerable\nchallenges in conducting investigations in Russian-occupied territories. It managed to carry\nout interviews with victims and witnesses from these areas, including interviews with victims\nand witnesses who have fled to other countries."},{"id":"a-hrc-52-crp-4-p0674","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"674","seq":676,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"On 16 March 2014, the Russian Federation had organized a so-called referendum on\nthe incorporation of Crimea and the city of Sevastopol in the Russian Federation and\nproceeded to their illegal annexation on 18 March 2014 (see para. 55).359 Less than two\nmonths later, on 11 May 2014, Russian-backed de facto authorities organized so-called\nreferendums on the “self-rule” of the Donetsk and Luhansk regions360 and declared the\nindependence of the then so-called Donetsk and Luhansk People’s Republics (see para.\n59).361"},{"id":"a-hrc-52-crp-4-p0675","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"675","seq":677,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"In July 2022, Russian-backed de facto authorities in some of the occupied territories\nundertook preparations to conduct so-called referendums on acceding to the Russian\nFederation.362 On 20 September 2022, Dmitri Medvedev, former Russian President and vice-\nchairman of the Russian Federation’s National Security Council, stated on his telegram\nchannel that “[r]eferendums in Donbass are of great importance, not only for the systemic\nprotection of the inhabitants of the LNR, DNR and other liberated territories, but also for the\nrestoration of historical justice”.363 On the same day, the Russian-backed heads of the four\ntemporarily occupied regions364 simultaneously announced that so-called referendums on the\njoining of the Russian Federation would be held shortly and enacted legislation and decrees\non their modalities.365 On 21 September 2022, in his address to the nation announcing a\npartial mobilization, President Putin stated: “The parliaments of the people’s republics of\nDonbass, as well as the military-civilian administrations of the Kherson and Zaporozhye\nregions decided to hold referendums on the future of these territories and appealed to us,\nRussia, to support such a step.” He added: “[w]e will do our best to ensure safe conditions\nfor holding referendums so that people can express their Will”. 366"},{"id":"a-hrc-52-crp-4-p0676","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"676","seq":678,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"Between 23 and 27 September 2022, the Russian-backed de facto authorities held the\nso-called referendums in the four regions. The respective ballot question could be answered\nby “yes” or “no”. For example, in Donetsk region, a ballot stated: “Are you in favour of the\nDonetsk People’s Republic entry into the Russian Federation as a subject of the Russian\nFederation?”. In Kherson region, the ballot stated: “Are you in favour of the Kherson region\nsecession from Ukraine, the formation of an independent state by the Kherson region and its\nentry into the Russian Federation as a subject of the Russian Federation?”."},{"id":"a-hrc-52-crp-4-p0677","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"677","seq":679,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"Already in the morning of 28 September 2022, Russian media announced the results,\nclaiming that from 87 to more than 99 per cent of the voters in the four regions had voted in\nfavor of joining the Russian Federation.367 On the same day, the Russian-backed heads of\noccupied territories of Kherson, Luhansk and Zaporizhzhia regions addressed separate,\nthough identical, requests to President Putin for their regions to be integrated in the Russian\nFederation. The head of the so-called Donetsk People’s Republic had already on 20\nSeptember 2022 expressed a similar appeal, addressed to President Putin, “I ask you to\nconsider the issue of the Donetsk People’s Republic’s joining the Russian Federation as soon\nas possible in the event of a positive decision on the results of the referendum, which we have\nno doubt about.”368 On 30 September 2022, President Putin and the de facto authorities of\nthe four regions signed “treaties” regarding their “accession” to the Russian Federation. 369\nOn 3 October 2022, the Russian Parliament adopted bills on the same. 370"},{"id":"a-hrc-52-crp-4-p0678","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"678","seq":680,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"International organizations condemned the so-called referendums and the illegal\nannexation. On 30 September 2022, the European Union “firmly reject[ed] and\nunequivocally condemn[ed] the illegal annexation by Russia of Ukraine’s Donetsk, Luhansk,\nZaporizhzhia and Kherson regions”.371 On the same day, the Council of Europe leaders\npublished a similar statement.372 On 12 October 2022, the United Nations General Assembly\nadopted a resolution declaring that the “[...] illegal so-called referendums [...] and the\n“Law on the referendum of the Donetsk People’s Republic on joining the Russian Federation as a\nsubject of the Russian Federation”, No 411-III, 20 September 2022; so-called Luhansk People’s\nRepublic, “Decree of the head of the Luhansk People’s Republic on the announcement of days off”,\nDNR No UG-886/22, 20 September 2022;\nFor the occupied territories in the Zaporizhzhia region, Yevgen Balitsky, Telegram message\nannouncing the organization of the “referendum”; decree on the “referendum”.\nsubsequent attempted illegal annexation of these regions, have no validity under international\nlaw and do not form the basis for any alteration of the status of these regions of Ukraine”.373\nb)     Unlawful so-called referendums"},{"id":"a-hrc-52-crp-4-p0679","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"679","seq":681,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"The Commission has found that, under international humanitarian law, the holding of\nso-called referendums in the occupied territories of the Donetsk, Kherson, Luhansk, and\nZaporizhzhia regions was unlawful. In addition to the illegal holding of such referendums,\nthe conduct of them violated international standards on referendums."},{"id":"a-hrc-52-crp-4-p0680","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"680","seq":682,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"In virtue of international humanitarian law, at the relevant times, the Russian\nFederation was the Occupying Power of the four Ukrainian territories.374 An Occupying\nPower must respect the laws in force in the territory it occupies, unless absolutely prevented.\nThe Occupying Power “shall take all the measures in his power to restore, and ensure, as far\nas possible, public order and safety, while respecting, unless absolutely prevented, the laws\nin force in the country”.375"},{"id":"a-hrc-52-crp-4-p0681","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"681","seq":683,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"The organization of a referendum in Ukraine is regulated by the Constitution, which\nstipulates that “altering the territory of Ukraine are resolved exclusively by an All-Ukrainian\nreferendum”.376 To initiate the referendum process, the Constitution requires the signatures\nof no less than three million citizens of Ukraine eligible to vote from at least two-thirds of\nthe regions, with at least 100,000 signatures in each region. It also states that the Parliament\n(the Verkhovna Rada) or the President of the country shall call an All-Ukrainian referendum,\nin accordance with their authority determined by the Constitution. 377 The Commission\nconsidered that none of the constitutional requirements were followed in the organization of\nthe so-called referendums. It has therefore concluded that the holding of so-called\nreferendums did not comply with the laws of Ukraine and violated the Occupying Power’s\nobligations under international humanitarian law."},{"id":"a-hrc-52-crp-4-p0682","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"682","seq":684,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"More generally, pursuant to principles of international law, no territorial acquisition\nresulting from the threat or use of force shall be recognized as legal, and they also recognize\nthat the territorial integrity and political independence of a State are inviolable.378 The\nCommission has established that the use of armed force by the Russian Federation against\nUkraine was an act of aggression as defined in United Nations General Assembly resolution\n3314 (XXIX) (see paras. 100-107). In this regard, the resolution holds that “[n]o territorial\nacquisition or special advantage resulting from aggression is or shall be recognized as\nlawful”.379"},{"id":"a-hrc-52-crp-4-p0683","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"683","seq":685,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"Further, pursuant to international humanitarian law, protected persons in occupied\nterritories shall not be deprived of the benefits of international humanitarian law by any\nchange introduced into the institutions or government of the occupied territory including by\nany annexation.380 Therefore, if the outcome of a referendum required changes to the\ninstitutions or government of the occupied territory that would reduce the protection afforded\nto such persons, any such measures would be without legal effect under international\nhumanitarian law."},{"id":"a-hrc-52-crp-4-p0684","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"684","seq":686,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"The Commission has also considered the circumstances in which the so-called\nreferendums were organized in light of the Revised Code of Good Practice on Referendums\nfrom the European Commission for Democracy through Law (Venice Commission). The\nCode underlines that “[t]he use of referendums must comply with the legal system as a whole.\nIn particular, referendums cannot be held if the Constitution or a statute in conformity with\nthe Constitution does not provide for them [...].”381 The Code covers different aspects of the\nholding of referendums, such as the requirements that electoral registers are to be reliable,\nwhich, inter alia, involves that they must be constantly updated, made public, and that an\nadministrative or judicial procedure should allow voters to register. It foresees that\nadministrative authorities should hold a neutral attitude and that freedom of the press and\nbalanced press coverage is guaranteed. The Code also states that voters should be able to\nform an opinion freely, which involves that administrative authorities observe a duty of\nneutrality and that an impartial body exercises prior scrutiny on the clarity of the question\nand provides balanced information. Finally, it prescribes that observers must be allowed to\nbe present and that the body organizing the referendum is to establish the result in an accurate\nand transparent manner.382"},{"id":"a-hrc-52-crp-4-p0685","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"685","seq":687,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"When examining the circumstances in which the so-called referendums were\norganized and held, it appears that none of the elements prescribed by the Code were in place\nin any of the four regions and that therefore none meets the international standards for\ncredible referendums. First, considering that they were announced with a short notice, in a\ncontext marked by armed conflict, in which thousands of civilians were displaced, killed or\nmissing, it is unlikely that genuine electoral registers could have been held and updated.\nAlthough Russian media claimed that the so-called referendums were held in the presence of\ninternational observers,383 no internationally recognized electoral observation bodies had\nbeen invited. International bodies in fact strongly condemned the so-called referendums.\nMoreover, as outlined below, the Commission examined credible reports according to which\npeople were not free to cast their votes but were rather placed in a general situation of fear\nand coercion.\nc)     Coercion during the preparation and the holding of referendums"},{"id":"a-hrc-52-crp-4-p0686","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"686","seq":688,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"The Commission interviewed civilians who were in Russian-occupied areas during\nthe period in which so-called referendums were prepared and organized. Their accounts show\nthat these were held in a general climate of coercion, intimidation, and fear."},{"id":"a-hrc-52-crp-4-p0687","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"687","seq":689,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"International humanitarian law states that no physical or moral coercion shall be\nexercised against protected persons, such as civilians.384 Additionally, they shall be protected\nagainst all acts of violence or threats thereof and against insults, and an Occupying Power\nshall treat all protected persons with the same consideration without any distinction based on,\namong other factors, political opinion.385"},{"id":"a-hrc-52-crp-4-p0688","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"688","seq":690,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"Some interlocutors reported that Russian-backed de facto authorities carried out\napartment visits ahead of the so-called referendums, which created a climate of fear. As\nreported to the Commission, an older woman resident of Melitopol city, Zaporizhzhia region,\nexplained that Russian authorities requested heads of apartment buildings to carry out rounds\nto ask people what they would do in relation to the referendum and that soldiers were doing\nrounds in private residential houses. The woman was of the opinion that many voted “yes”\nout of fear. One man from the Kherson region stated, “I know of a few acquaintances who\nvoted during the referendum, but I do not know one single person who voted on their own\nfree will.”"},{"id":"a-hrc-52-crp-4-p0689","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"689","seq":691,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"Many interlocutors said that, as a sign of passive resistance, they did not vote. The\nmajority stayed inside their homes during the five days of the so-called referendums, to avoid\nbeing coerced to vote by the de facto authorities. Many noted that they did not switch the\nlights on after dark in order not to raise suspicion about their presence."},{"id":"a-hrc-52-crp-4-p0690","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"690","seq":692,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"Residents also reported that mainly older persons voted in the so-called referendums,\nas they were generally more likely than younger persons to remain in occupied territories due\nto family obligations and physical conditions. Many of them were deprived of sources of\nincome. In June 2022, Maryna Lazebna, Minister of Social Policy of Ukraine, announced\nthat 300,000 pensioners would no longer be able to receive pensions in occupied territories\nand areas affected by armed conflict, due to the inability to deliver funds there. 386 The older\nwoman resident of Melitopol (see para. 688) stated that during rounds ahead of the\nreferendum, the head of the apartment building presented her with papers to sign. When she\nasked, “do I have a choice?”, he replied, “well, you still want to get your pension, right?”.\nAccording to her, everyone said “yes” because they feared for themselves."},{"id":"a-hrc-52-crp-4-p0691","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"691","seq":693,"section":"2. Unlawful annexation following unlawful so-called referendums","text":"In most cases, interlocutors saw through their windows or in the street “electoral staff”\ncarrying ballot boxes accompanied by armed personnel. Others heard those “mobile voting\nteams” knocking on their doors but did not open and the teams left. The Commission also\nreviewed open-source reports on the intimidating atmosphere during the period of the so-\ncalled referendums. Several videos from surveillance systems featuring two or three civilians\ncarrying ballot boxes and accompanied by armed military personnel could be seen knocking\non doors in apartment buildings and calling “referendum, referendum”. The Commission\ninterviewed a woman who stated that two men in military uniforms and a civilian woman\nwith a ballot box came to her son’s house in Kakhovka city, in the Kherson region, and\ndetained him after he refused to vote."},{"id":"a-hrc-52-crp-4-p0692","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"692","seq":694,"section":"3. Imposition of Russian Federation citizenship in the newly Russian-occupied areas","text":"The Commission has found that in the areas that Russian authorities occupied since\nFebruary 2022, and where they held so-called referendums, they created conditions in which\nsome categories of residents felt compelled to apply for Russian passports. This was the case\nin the occupied territories of Kherson and Zaporizhzhia regions, and the city of Mariupol,\nDonetsk region. On 30 September 2022, “treaties” on the “annexation” of the four occupied\nregions to the Russian Federation387 automatically recognized Ukrainian citizens and\nstateless persons permanently residing in these areas as Russian citizens. Exception was made\nfor the persons who, within one month, declared their “wish” to retain their existing\ncitizenship. 388"},{"id":"a-hrc-52-crp-4-p0693","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"693","seq":695,"section":"3. Imposition of Russian Federation citizenship in the newly Russian-occupied areas","text":"According to international humanitarian law, it is prohibited to compel inhabitants of\nan occupied territory to swear allegiance to the Occupying Power. 389 Moreover, the\nOccupying Power must respect the laws in force in the country, unless absolutely\nprevented.390 Compelling or imposing foreign citizenship upon Ukrainian citizens would,\namong other things, be counter to national laws and may impact the rights of affected persons\nas Ukrainians.391"},{"id":"a-hrc-52-crp-4-p0694","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"694","seq":696,"section":"3. Imposition of Russian Federation citizenship in the newly Russian-occupied areas","text":"The Commission interviewed interlocutors from Kherson and Zaporizhzhia regions,\nand Mariupol city, Donetsk region, who reported that some categories of people feared that\nwithout a Russian passport, they would lose or not have access to social benefits or\nemployment. Others stated that Russian authorities advertised incentives according to which\nthose applying for a Russian passport would receive 10,000 rubles and said that such\napplicants would not need to renounce Ukrainian citizenship."},{"id":"a-hrc-52-crp-4-p0695","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"695","seq":697,"section":"3. Imposition of Russian Federation citizenship in the newly Russian-occupied areas","text":"The same interlocutors told the Commission that particularly civilians at retirement\nage wishing to receive or to continue to receive a pension from the Russian-backed de facto\nauthorities, have applied for Russian passports. As mentioned above, Ukrainian authorities\ndeclared that thousands of pensioners in these areas would be cut off from their existing\npensions (see para. 690). Many of these also received promises that Russian authorities would\npay pensions, and therefore carried out formalities to obtain a Russian passport. As of\nDecember 2022, de facto authorities in Mariupol, for example, reportedly paid pensions,\nprovided that there had been a prior registration. Holding a Russian passport was until then\nnot an underlying condition to receive pensions. Nevertheless, a Ukrainian official from\nKherson region told the Commission that Russian-backed de facto authorities announced that\nto continue receiving pensions residents would have to hold a Russian passport by 1 March\n2023. A Russian draft law on “pensions in new regions”, presented in January 2023,\nstipulates that from 1 March 2023, pensions for their residents “will be appointed on the basis\nof applications, according to Russian standards”.392"},{"id":"a-hrc-52-crp-4-p0696","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"696","seq":698,"section":"3. Imposition of Russian Federation citizenship in the newly Russian-occupied areas","text":"Similarly, according to local sources, civil servants and other people wanting to keep\ntheir employment under the de facto authorities of the Russian-occupied areas had to request\na Russian passport. In one example, in a city of Kherson region, civil servants at the city\ncouncil were reportedly requested to apply for a Russian passport as a condition to maintain\ntheir positions. In another example, in a different city of Kherson region, Russian-backed de\nfacto authorities appointed a new head doctor who cooperated with them in a hospital. A\nworker of the hospital said to the Commission that the new head doctor subsequently forced\nthe other staff of the hospital to work with the de facto authorities. They were reportedly\ninformed that in order to receive their next salaries, they would have to apply for a Russian\npassport, resign from their current contracts with the hospital, and re-register through the\nadministration run by the de facto authorities. Also in the Kherson region, one school\nprincipal who had been detained by Russian authorities for his refusal to cooperate, was told\nthat he would remain in detention indefinitely, unless he agreed to apply for a Russian\npassport."},{"id":"a-hrc-52-crp-4-p0697","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"697","seq":699,"section":"3. Imposition of Russian Federation citizenship in the newly Russian-occupied areas","text":"A Ukrainian authority from Enerhodar city, Zaporizhzhia region, told the Commission\nthat in the spring of 2022, a “passport desk” had been opened at the Zaporizhzhia Nuclear\nPower Plant and that some workers applied for passports willingly, while others were forced.\nIn November and December 2022, several employees of the facility reported to him that in\naddition to the demand that they sign contracts with the Russian State Atomic Energy\nCorporation (Rosatom), employees were told that access to the facility’s premises would\nhenceforth only be granted to holders of a Russian passport. An employee of the Zaporizhzhia\nNuclear Power Plant who had been detained by Russian authorities told the Commission that\nhe received information that as of November 2022, access badges to the plant premises of\nthose without a Russian passport were blocked."},{"id":"a-hrc-52-crp-4-p0698","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"698","seq":700,"section":"4. Coercion and threats towards education personnel","text":"The Commission has documented instances of coercion, threats, and intimidations\nissued by Russian authorities and persons closely cooperating with them towards teachers in\nRussian-controlled areas in the Kherson and Zaporizhzhia regions to secure their observance\nof the new educational regulations imposed by the Occupying Power. According to school\npersonnel from these areas, Russian authorities, or local residents supporting them, carried\nout home visits or school visits to seek their cooperation. Interlocutors reported threats to\ndetain them, expel them from their localities, harm their families, or confiscate their houses.\nHome visits and fear of being detained created psychological pressure and led some teachers\nto decide to leave for territories under Ukrainian Government control. The Commission is of\nthe view that this issue deserves closer examination."},{"id":"a-hrc-52-crp-4-p0699","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"699","seq":701,"section":"4. Coercion and threats towards education personnel","text":"International humanitarian law prohibits physical or moral coercion against protected\npersons such as those in the hands of the Occupying Power. 393 Additionally, such persons\nshall be protected against all acts of violence or threats thereof.394"},{"id":"a-hrc-52-crp-4-p0700","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"700","seq":702,"section":"4. Coercion and threats towards education personnel","text":"One school principal stated that in late March 2022, in Melitopol city, in the\nZaporizhzhia region, armed men visited his house. He referred to them as “Russian\noccupation police”. They ordered his family to go outside with one of the armed men, while\nthe others threatened to detain him if he did not cooperate. A deputy principal of a school in\na village in the Zaporizhzhia region informed the Commission that, in July 2022, after he had\nrefused to cooperate with the de-facto authorities, two teachers came to her house to convey\nthat the principal – who had decided to cooperate – told her that she should hand over the key\nto her house. Some days later, after she had fled from the area, Russian armed forces came\nto her house, searched it, and detained her husband in a police station where reportedly\nmembers of the Russian Federal Security Service interrogated him and released him on\ncondition that he would convince her to come back and collaborate."},{"id":"a-hrc-52-crp-4-p0701","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"701","seq":703,"section":"4. Coercion and threats towards education personnel","text":"The Commission also documented cases in which Russian authorities visited schools\nto threaten educators with eviction from the localities in which they resided unless they\nagreed to collaborate and apply newly imposed curricula. A schoolteacher told the\nCommission that after Russian authorities took control of Melitopol city, Zaporizhzhia\nregion, during a round of visits to schools, persons dressed in civilian clothes and wearing\nmasks who presented themselves as Russians, told school staff to choose between teaching\nthe Russian program or leaving the town and sell their apartments and properties. During a\nsubsequent visit, these patrols warned school staff that they had one day to leave the town\nunless they agreed to collaborate."},{"id":"a-hrc-52-crp-4-p0702","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"702","seq":704,"section":"5. Coercion of parents to force them to send their children to schools","text":"The Commission received testimonies showing that Russian authorities threatened,\nintimidated and used psychological pressure against parents to coerce them to send their\nchildren to schools run in conformity with the Russian system in the territories which came\nunder their control. It documented such cases in Kharkiv, Kherson, and Zaporizhzhia regions."},{"id":"a-hrc-52-crp-4-p0703","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"703","seq":705,"section":"5. Coercion of parents to force them to send their children to schools","text":"School personnel and parents informed the Commission of situations in which, during\ndoor-to-door home visits, Russian authorities requested parents to send their children to\nschools run by them and threatened to otherwise impose a fine, to rescind their parental rights,\nor to send their children away to institutions. Such messages were also communicated by\nschool personnel, who chose to cooperate with the de facto authorities, via text messages or\nat school meetings. Some parents were offered 10,000 rubles if their children went to such\nschools."},{"id":"a-hrc-52-crp-4-p0704","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"704","seq":706,"section":"5. Coercion of parents to force them to send their children to schools","text":"One principal of a school in a village of Zaporizhzhia region told the Commission that\nin July and August 2022, Russian authorities and school administrators who chose to support\nthe de facto authorities invited parents for meetings. There, they told the parents that if they\ndid not send their children to school, they would separate them and send them to the Russian\nFederation to receive education; they also said that those who did not collaborate would be\nconsidered traitors and would find a hand grenade in their yards. The principal of a school in\nanother village of the Zaporizhzhia region informed the Commission that she received voice\nmessages from around ten pupils asking if they would be treated as traitors if they attended\nschool. These students informed her that Russian armed forces had visited their homes to\nrequest them to attend schools run by Russian authorities and told parents that children would\nbe moved to orphanages and forced to dig trenches in case of non-compliance. One teacher\nstated to the Commission that students called in distress, as they feared that they would be\nseparated from their parents."},{"id":"a-hrc-52-crp-4-p0705","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"705","seq":707,"section":"5. Coercion of parents to force them to send their children to schools","text":"The Commission received reports regarding children who were terrified that they\ncould be caught attending Ukrainian school online. Parents in Enerhodar city, Zaporizhizhia\nregion, described situations where Russian soldiers questioned children they saw in the\nstreets; therefore, the children tried to stay indoors. Parents and children created fake\naccounts and cleared their phones out of fear that they could be searched."},{"id":"a-hrc-52-crp-4-p0706","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"706","seq":708,"section":"5. Coercion of parents to force them to send their children to schools","text":"As a result of such threats and intimidations, some parents in territories under Russian\ncontrol had, out of fear, enrolled their children in schools providing Russian education.\nOthers enrolled their children in schools operating under the Russian system because that\nwas the only option for in-person school attendance, while some may have been favourable\nto such education."},{"id":"a-hrc-52-crp-4-p0707","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"707","seq":709,"section":"6. Unlawful confinement of local officials and other public service employees","text":"The Commission has documented cases in which public officials and education\npersonnel were confined by Russian authorities in areas which came under their control in\nthe Kharkiv, Kherson, and Zaporizhzhia regions. Detention of public officials occurred\nfollowing refusal to cooperate with Russian authorities. Detention of education personnel\noccurred after accusations that they refused to cooperate in implementing the Russian-\nimposed curricula or to teach Russian language in school. Both women and men were\naffected. In one case, a schoolteacher was detained together with her 16-year-old daughter\n(see paras. 611)."},{"id":"a-hrc-52-crp-4-p0708","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"708","seq":710,"section":"6. Unlawful confinement of local officials and other public service employees","text":"In international humanitarian law, confining a protected person, such as a civilian,\nwithout lawful reason, is prohibited.395 Such confinement is also a violation of the right to\nliberty and security of person, under international human rights law.396 The detaining\nauthority is under an obligation to fulfil procedural requirements, such as promptly informing\ndetainees, in a language they understand, of the reasons why the measures have been taken. 397\nConfined persons shall be treated humanely and protected from life-threatening conditions.398\nMore broadly, international humanitarian law prohibits physical or moral coercion against\nprotected persons, such as those in the hands of the Occupying Power. 399 Additionally, such\npersons shall be protected against all acts of violence or threats thereof.400"},{"id":"a-hrc-52-crp-4-p0709","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"709","seq":711,"section":"6. Unlawful confinement of local officials and other public service employees","text":"The Commission investigated two cases of elected public officials confined by\nRussian authorities in Kherson and Zaporizhzhia regions. One is the Mayor of Melitopol,\nZaporizhzhia region, and the other is head of a territorial community in Kherson region (see\npara. 496). According to the victims, the perpetrators were Russian armed forces, including\nreportedly Russian Federal Security Service personnel. In both cases, victims were\nblindfolded when taken away and not informed of the reasons for their arrest. They reported\nlong interrogations during detention, no physical violence, but psychologic pressure.\nPerpetrators requested their cooperation or that they sign resignation documents. According\nto one of the victims, interrogation sessions were carried out in the presence of an electric\nshocker, while the perpetrators repeatedly requested collaboration with the Russian armed\nforces. Perpetrators stated that, “Ukrainians are Nazis that we came to liberate” and “if you\nlike the Ukrainian Armed Forces so much, we will drop you in the middle of a mine field for\nyou to join them”. The Commission collected allegations regarding other situations in which\nlocal officials have been detained."},{"id":"a-hrc-52-crp-4-p0710","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"710","seq":712,"section":"6. Unlawful confinement of local officials and other public service employees","text":"The Commission documented situations in which Russian authorities detained\neducation personnel during visits at their homes or in schools. They searched houses of the\nvictims and their telephones, and confiscated telephones, identity documents, keys, and\nmoney. Perpetrators were members of the Russian armed forces, soldiers of the former so-\ncalled Donetsk and Luhansk People’s Republics, and local residents who supported them.\nReportedly, Russian Federal Security Service personnel participated in some of the\ndetentions and the interrogations sessions. Detention occurred both in makeshift facilities and\nat police stations. Some of the victims had bags placed on their heads. During confinement,\nperpetrators interrogated and threatened the victims and requested their cooperation. In the\ncase mentioned above, in which Russian armed forces detained a schoolteacher together with\nher 16-year-old daughter, they threatened to rape the girl (see para. 611). In some situations,\nperpetrators transferred the detained victims out of their municipalities and dropped them\nnear areas under Ukrainian armed forces control. One victim of such a transfer reported that\nRussian armed forces told several of transferred civilians to go onwards without turning,\notherwise they will be shot at. This is a violation of international humanitarian law (see\npara. 518). Military operations were ongoing at that time and this in addition exposed the\nvictims to significant risks."},{"id":"a-hrc-52-crp-4-p0711","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"711","seq":713,"section":"6. Unlawful confinement of local officials and other public service employees","text":"According to a school principal from Kharkiv region, two Russian soldiers came to\nher home, asked her why she refused to work with Russian-appointed administration, told\nher that “she had to follow the rules of Putin” and detained her. During confinement,\nperpetrators requested her, together with two other detainees, to declare on camera:\n“Zelenskyy is an awful President” and “[w]e thank the Russian Federation for the liberation\nof our town.” Another women detained in the same facility reported having been asked to\nmake similar statements in front of a camera, together with the former victim. In a distinct\ncase, in which a teacher was detained at his workplace in a school, allegedly by members of\nthe FSB, and confined in a police station, also in Kharkiv region, during interrogation\nperpetrators offered him to cooperate with Russian armed forces; one of them told him “we\nare here, and if you don’t like it, go away.”"},{"id":"a-hrc-52-crp-4-p0712","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"712","seq":714,"section":"7. Unlawful and forced conscription","text":"Ahead of the 24 February 2022 Russian Federation invasion of Ukraine, on 19\nFebruary 2022, Russian-backed de facto authorities of the former so-called Donetsk and\nLuhansk People’s Republics announced a “general mobilisation”.401 The mobilization\nconcerned all men aged 18 to 55. The Commission interviewed and reviewed allegations\nrelating to over 65 situations in which men in this age group were forcibly conscripted by\nRussian authorities in the former self-proclaimed ‘republics’. In the majority of situations\nreviewed, enlistment occurred between 19 February and 1 March 2022. They were prisoners\nof war in Ukraine-controlled territories at the time they were interviewed."},{"id":"a-hrc-52-crp-4-p0713","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"713","seq":715,"section":"7. Unlawful and forced conscription","text":"Under international humanitarian law, an Occupying Power may not compel protected\npersons to serve in its armed or auxiliary forces, and no pressure or propaganda which aims\nat securing voluntary enlistment is permitted.402"},{"id":"a-hrc-52-crp-4-p0714","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"714","seq":716,"section":"7. Unlawful and forced conscription","text":"The Commission interviewed the wife of a 48-year-old Ukrainian citizen resident\nof so-called Luhansk People’s Republic. She said that her husband was conscripted by\nRussian-backed de facto authorities. On 24 February 2022, he received a telephone call from\nthe head of the village council requesting him to present himself to the conscription office.\nHe was threatened to lose his salary and pension in case of refusal. He never received a\nwritten summons but reported for duty within two hours. Reportedly, he was sent to dig\ntrenches in the occupied territory of Kharkiv region."},{"id":"a-hrc-52-crp-4-p0715","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"715","seq":717,"section":"1. Overview","text":"Governments, international, regional and local organizations, and media have\nreported on situations of transfers and deportations of Ukrainian children by Russian\nauthorities since the outset of the armed conflict on 24 February 2022. Ukrainian and Russian\nofficial declarations pointed to large-scale transfers, of hundreds of thousands of children,\nwith figures that vary greatly. In June 2022, President Zelenskyy stated that more than\n200,000 Ukrainian children had been “deported” so far.403 During the same month, Russian\nauthorities informed that 307,423 children had been “evacuated” to the Russian Federation\nsince 24 February 2022.404 However, a data collection system maintained by the Government\nof Ukraine based on citizens’ reports of individual situations had recorded 16,221\ndeportations of children as of the end of February 2023.405 Both Russian and Ukrainian\nauthorities have stated that the majority of transfers of children occurred from the Luhansk\nand Donetsk regions in Ukraine.406"},{"id":"a-hrc-52-crp-4-p0716","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"716","seq":718,"section":"1. Overview","text":"Russian officials have promoted transfers407 of children from Ukraine to the Russian\nFederation, describing them as a humanitarian undertaking to rescue them from war zones\nand bring them to safety.408 Official communications illustrate that Russian officials have put\nin place dedicated legislative and policy measures, such as the granting of Russian citizenship\nand the placement of children in foster families, which are indicative of a strategy to\naccommodate certain categories of children from Ukraine in the Russian Federation for a\nlonger term or permanently. Ms. Maria Lvova-Belova, the Russian Federation’s Presidential\nCommissioner for Children’s Rights, has spearheaded a wide range of initiatives aimed at\ntransferring and accommodating Ukrainian children in the Russian Federation. She has also\ntravelled to Russian-controlled territories of Donetsk and Luhansk regions, inter alia, to\ncoordinate transfers and placements of children in Russian families."},{"id":"a-hrc-52-crp-4-p0717","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"717","seq":719,"section":"1. Overview","text":"States condemned these undertakings and imposed sanctions targeting Ms. Lvova-\nBelova.409 In response, President Putin stated, “it is only natural that she evacuated children\nfrom the zone of combat operations or dangerous areas in Donbass. What is wrong about it?\nWe should thank her for that and make a low bow to her”.410"},{"id":"a-hrc-52-crp-4-p0718","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"718","seq":720,"section":"1. Overview","text":"Ukrainian authorities have also condemned, in the strongest terms, the transfers of\nUkrainian children to the Russian Federation. President Zelenskyy declared that Russian\narmed forces “abducted” Ukrainian children.411 The Office of the Prosecutor General of\nUkraine had been leading investigations into this matter with the aim of building an\nindictment for genocide.412 In August 2022, Ukraine’s Ministry of Foreign Affairs stated,\n“[t]he Russian Federation continues to abduct children from the territory of Ukraine and\narrange their illegal adoption by Russian citizens.” 413"},{"id":"a-hrc-52-crp-4-p0719","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"719","seq":721,"section":"1. Overview","text":"The Commission has identified a variety of situations in which Russian authorities\nhave transferred children from territories that came under their control in Ukraine toother\noccupied areas in Ukraine or deported them to the Russian Federation. These concerned\nchildren who lost a parent or temporarily lost contact with them during the hostilities;\nchildren whose parents had been detained at filtration points; children in institutions, and\nchildren who had travelled to vacation camps."},{"id":"a-hrc-52-crp-4-p0720","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"720","seq":722,"section":"1. Overview","text":"International humanitarian law414 states that individual or mass forcible transfers, as\nwell as deportations of protected persons from occupied territory to the territory of the\nOccupying Power or to that of any other country, occupied or not, are prohibited, regardless\nof their motive. However, the Occupying Power may undertake total or partial evacuation of\na given area if the security of the population or imperative military reasons so demand, but\nthis may not involve the displacement outside the occupied territory, unless it is unavoidable;\nevacuations should be temporary. International humanitarian law 415 also holds that no Party\nto the conflict shall arrange for the evacuation of children, other than its own nationals, to a\nforeign country except for a temporary evacuation where compelling reasons of the health or\nmedical treatment of the children or, except in occupied territory, their safety, so require. The\nwritten consent of parents or legal guardians is required, and if they cannot be found, of the\npersons primarily responsible for the care of the children."},{"id":"a-hrc-52-crp-4-p0721","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"721","seq":723,"section":"1. Overview","text":"The Commission has found that certain situations of transfers of children which it has\nreviewed generally did not fulfil the requirements set forth by international humanitarian law.\nIn most cases, transfers did not appear to have been justified by a valid reason, such as a\nsafety requirement or a medical reason. In the situations examined, there is no information\nthat the Russian authorities sought the consent of the children’s parents, legal guardians, or\nthose who are legally responsible for the children, as required by law. In addition, due to a\nvariety of circumstances, many transfers became prolonged. Children and their families\nencountered an array of difficulties in establishing contact and reuniting with their families,\nwhich resulted in long-lasting family separations. The Commission received reports that in\nsome situations, during transfers, social services told the children that they would be placed\nfor adoption, or with foster parents, or in an institution."},{"id":"a-hrc-52-crp-4-p0722","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"722","seq":724,"section":"1. Overview","text":"In this regard, international humanitarian law requires that the parties to the conflict\nfacilitate in every possible way the reunion of families dispersed as a result of armed\nconflicts.416 An unjustifiable delay in the repatriation of civilians is a war crime. 417 Under\ninternational human rights law, if a child is separated from one or both parents as result of\ndetention, deportation or death, state parties shall, upon request, provide the parents, the child\nor, if appropriate, another member of the family with the essential information concerning\nthe whereabouts of the absent member(s) of the family unless the provision of the information\nwould be detrimental to the well-being of the child.418 International humanitarian law also\nstates that an Occupying Power may not, in any case, change the personal status of\nchildren.419 Under international human rights law, the child has the right to preserve his or\nher identity, including nationality, name and family relations as recognised by law without\nunlawful interference.420"},{"id":"a-hrc-52-crp-4-p0723","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"723","seq":725,"section":"1. Overview","text":"In most of the situations of transfers of children which the Commission has examined,\nRussian authorities did not appear to have attempted to facilitate family reunifications. In the\ncases reviewed, children themselves or their families took the initiative to establish contact.\nRussian authorities required parents and relatives to travel in person to pick up the children,\nwhich came with considerable logistical, financial, and security difficulties, as outlined\nbelow. In addition, in some of the reviewed situations, parents and relatives informed the\nCommission that the children were accommodated in camps and institutions where\nconditions were inadequate, with poor food, hygiene, and medical care, as well as bad\ntreatment by the local staff. Family members or legal guardians who have retrieved children\nafter transfers reported that uncertainties regarding the prospects of finding and reuniting\nwith parents or relatives led to immense psychological suffering. This experience has deeply\naffected the children and they expressed a profound fear of being permanently separated from\nparents, guardians, or relatives.\n414 Geneva Convention IV, article 49.\n415 Additional Protocol I to the Geneva Conventions, article 78(1).\n416 Additional Protocol I to the Geneva Conventions, article 74.\n417 Additional Protocol I to the Geneva Conventions, article 85(4)(b), (5).\n418 Convention on the Rights of the Child, article 9(4). This provision should be read in conjunction\nwith article 10 of the Convention. In addition, article 38 (1) and (4) of that Convention provide for\ngeneral protection measures for children in line with international humanitarian law applicable to the\nstates involved."},{"id":"a-hrc-52-crp-4-p0724","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"724","seq":726,"section":"1. Overview","text":"The Commission has concluded that certain situations of transfers of children which\nit has examined amount to the war crime of unlawful transfers and deportations of children. 421\nIt also found that in those situations, the Russian authorities violated their obligation under\ninternational humanitarian law to facilitate in every possibly way the reunion of families\ndispersed as a result of the armed conflict,422 which may amount to the war crime of\nunjustifiable delay in the repatriation of civilians.423 This in addition violated the right of the\nchild to not be separated from parents and to family environment.424 Measures aimed at\ngranting Russian citizenship to certain categories of children are in addition violating\ninternational humanitarian law, which prohibits the Occupying Power to change the personal\nstatus of children, and the right of a child to preserve their identity, including nationality, as\nrecognised by international human rights law.425"},{"id":"a-hrc-52-crp-4-p0725","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"725","seq":727,"section":"1. Overview","text":"Investigating situations of transfers of children has been particularly challenging. A\nfundamental obstacle has been the lack of access to direct victims and witnesses, and in\nparticular to foster families and childcare institutions within the Russian Federation, as well\nas the absence of a response from the Russian Federation to the Commission’s queries. This\nfactor, in combination with the security situation of vulnerable interlocutors, has limited the\nCommission’s possibility to access first-hand sources of information. The Commission also\nregrets that it did not receive a response from Ukraine to its requests for detailed information\nregarding figures and specific cases of transfers of children."},{"id":"a-hrc-52-crp-4-p0726","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"726","seq":728,"section":"2. Situations in which child transfers took place","text":"The Commission has reviewed in detail several situations involving the transfer of\nchildren from Donetsk, Kharkiv, and Kherson regions, and has received credible allegations\nregarding numerous other such instances. These incidents concerned children aged four to 17\nand occurred in different types of circumstances, affecting children who temporarily lost\ncontact with parents or legal guardians due to the armed conflict, or lost a parent due to the\nfighting, or after the confinement of a parent at a filtration point, as well as children in\ninstitutions. In the situations examined, Russian authorities transferred the children to areas\noccupied by the Russian Federation in Ukraine, including Donetsk and Luhansk regions,\nCrimea, or deported them to regions in the Russian Federation, such as Moscow or\nKrasnodar. There, Russian authorities temporarily accommodated the children in hospitals,\nsocial institutions, or camps. In some of the reviewed situations, children transited through\nseveral places during transfers."},{"id":"a-hrc-52-crp-4-p0727","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"727","seq":729,"section":"2. Situations in which child transfers took place","text":"The Commission also interviewed parents from Kharkiv and Kherson regions whose\nchildren travelled with their initial consent to Crimea or the Russian Federation to participate\nin vacation camps, together with hundreds of other school children. When these areas\nreturned to Ukrainian control, Russian authorities did not facilitate the return of the children\nand required individual parents or legal guardians to travel in person to pick them up."},{"id":"a-hrc-52-crp-4-p0728","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"728","seq":730,"section":"2. Situations in which child transfers took place","text":"International humanitarian law states that individual or mass forcible transfers, as well\nas deportations of protected persons from occupied territory to the territory of the Occupying\nPower or to that of any other country, occupied or not, are prohibited, regardless of their\nmotive.426 However, the Occupying Power may undertake the total or partial evacuation of a\ngiven area if the security of the population or imperative military reasons so demand.427 Such\nevacuations may not involve the displacement of protected persons outside the bounds of the\noccupied territory except when for material reasons it is impossible to avoid such\ndisplacement.428 Persons thus evacuated shall be transferred back to their homes as soon as\nhostilities in the area in question have ceased.429 Moreover, international humanitarian law\nholds that no Party to the conflict shall arrange for the evacuation of children, other than its\nown nationals, to a foreign country except for a temporary evacuation where compelling\nreasons of the health or medical treatment of the children or, except in occupied territory,\ntheir safety, so require.430 Where the parents or legal guardians can be found, their written\nconsent to such evacuation is required.431 If these persons cannot be found, written consent\nto such evacuation of the persons who by law or custom are primarily responsible for the care\nof the children is required.432 Furthermore, under international humanitarian law, transferring\nor deporting a protected person such as a civilian to another location within the current\nterritory or to another State without a lawful basis is a war crime.433"},{"id":"a-hrc-52-crp-4-p0729","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"729","seq":731,"section":"2. Situations in which child transfers took place","text":"The Commission evaluated the circumstances of the transfers of children it examined\nin light of the applicable law and paid particular attention to the underlying reasons or\ncircumstances of the transfers, whether consent had been given, and whether the measures\nwere temporary. The Commission generally made the following findings:"},{"id":"a-hrc-52-crp-4-p0730","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"730","seq":732,"section":"2. Situations in which child transfers took place","text":"First, with some exceptions, the Commission has no indications that the transfers were\njustified by a safety or a medical reason; that the Russian authorities sought alternative\npossibilities, which could avoid the transfer of unaccompanied children to Russian-controlled\nareas or to the Russian Federation; or – in some cases – that there were material reasons\nmaking it impossible to allow the children to relocate to other parts of occupied territory or\nto territory controlled by the Government of Ukraine. In two incidents in which Russian\nauthorities transferred and accommodated the children in hospitals, this could have been\njustified for medical reasons, as in both situations the children had been injured and required\nmedical attention. However, also in these situations, there is no available information that the\nadditional legal requirements relating to consent and temporariness were fulfilled."},{"id":"a-hrc-52-crp-4-p0731","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"731","seq":733,"section":"2. Situations in which child transfers took place","text":"Second, Russian authorities do not appear to have sought the consent of the parents,\nlegal guardians, or those who are legally responsible for the children, as prescribed by law.\nWhile in some situations, consent could not be sought because the children had lost contact\nwith their parents at the moment of the events, or the parent was deceased or arrested, the\nCommission is not aware of Russian authorities having sought the consent of other relatives\nor of the Ukrainian authorities. In some incidents, transfers occurred regardless of the explicit\nrefusal of the parents or the children."},{"id":"a-hrc-52-crp-4-p0732","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"732","seq":734,"section":"2. Situations in which child transfers took place","text":"Third, due to a variety of reasons, many of the transfers were not temporary, as\nrequired by international law. Parents and children encountered considerable challenges in\nestablishing contact and achieving family reunification and the return of the children to\nUkraine. This led to prolonged separations, as outlined below."},{"id":"a-hrc-52-crp-4-p0733","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"733","seq":735,"section":"2. Situations in which child transfers took place","text":"In conclusion, the Commission has found that the three above-mentioned legal\nconditions were mostly not fulfilled. It has therefore concluded that some of the transfers of\nchildren that it has examined amount to unlawful transfers within Ukraine or to deportations\nto the Russian Federation, respectively, which are war crimes.\n3.     Prolonged duration of transfers of children and difficulties in establishing contact and\nrecovering children"},{"id":"a-hrc-52-crp-4-p0734","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"734","seq":736,"section":"2. Situations in which child transfers took place","text":"As mentioned above, in most of the examined situations of transfers of children, the\nstay of the children in Russian-occupied areas or in the Russian Federation has been\nprolonged, owing to a variety of reasons. Regardless of the large number of transfers of\nchildren which have been reported, the Commission is not aware of measures taken by\nRussian authorities to facilitate the establishment of family contacts or to facilitate the return\nof the children to territories controlled by the Government of Ukraine. The onus of finding\nfamily members rested upon the children themselves or their families. When contacts were\nestablished, Russian authorities required individual family members to pick up their children\nin person. This involved long and complicated travel, with considerable security and\nlogistical difficulties. These factors prolonged the duration of the family separations. In some\nsituations, it took weeks and up to several months, for children and families to be reunited.\nTherefore, each individual situation of transfers of children developed in a different way and,\nwhile in some situations family reunification has taken place, a solution leading to the child’s\nreunification with his or her relatives was not found in each case."},{"id":"a-hrc-52-crp-4-p0735","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"735","seq":737,"section":"2. Situations in which child transfers took place","text":"In this regard, international humanitarian law requires that the parties to the conflict\nfacilitate in every possible way the reunion of families dispersed as a result of armed\nconflicts.434 An unjustifiable delay in the repatriation of civilians is a war crime.435 Further,\ninternational humanitarian law emphasizes the importance of maintaining family unity and\nprovides that each Party to the conflict shall facilitate inquiries made by members of families\ndispersed owing to the war, with the object of renewing contact with one another and of\nmeeting, if possible.436 A prolonged separation of children from their families is in violation\nof the child’s right to family life and is not in the child’s best interests, pursuant to the\nConvention on the Rights of the Child.437 The child has the right to be cared for by his or her\nparents438, and States Parties to the Convention must ensure that a child shall not be separated\nfrom his or her parents against their will except in accordance with applicable law and\nprocedures.439 Where such separation results from any action initiated by a State Party, such\nas the detention, imprisonment, exile, deportation, or death of one or both parents or of the\nchild, that State Party shall, upon request, provide the parents, the child or, if appropriate,\nanother member of the family with the essential information concerning the whereabouts of\nthe absent member(s) of the family, unless such information would be detrimental to the well-\nbeing of the child.440 In all actions concerning children, the best interests of the child shall be\na primary consideration.441"},{"id":"a-hrc-52-crp-4-p0736","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"736","seq":738,"section":"2. Situations in which child transfers took place","text":"In the cases of transfers which the Commission has documented, children, parents, or\nrelatives encountered significant difficulties in establishing contact. In several situations, the\nchildren took the initiative and managed to locate their family members. In some incidents,\nfamily members only learned about the children’s whereabouts through media reports.\nWitnesses informed the Commission that some of the children transferred to institutions in\nRussian-occupied areas or deported to camps in the Russian Federation have not been able\nto establish contact with their families. The Commission is concerned that this may lead to\nindefinite or permanent separation. In this regard, younger children are particularly\nvulnerable, as they are less likely to be able to contact their parents, and therefore they face\na higher risk of losing contact with their families indefinitely."},{"id":"a-hrc-52-crp-4-p0737","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"737","seq":739,"section":"2. Situations in which child transfers took place","text":"In several of the incidents examined, parents or relatives informed the Commission\nthat, during the period of separation, social services in Russian-occupied territories or in the\nRussian Federation told the children that they would be placed for adoption, or with foster\nparents, or in an institution. This was a source of considerable psychological pressure and\nfear for the children. In some situations, parents additionally conveyed to the Commission\nthat in places of transfer, children were screamed at, that meals were poor, and that children\nwere otherwise not provided with adequate accommodation or hygiene. Some children with\ndisabilities did not receive adequate care and medication, which can be life threatening in\nsome situations."},{"id":"a-hrc-52-crp-4-p0738","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"738","seq":740,"section":"2. Situations in which child transfers took place","text":"Parents and relatives encountered serious challenges in organizing travel to pick up\ntheir children, due to the dire security situation and logistical difficulties. In many incidents,\ntravel was long and complicated, up to one week one way, at times requiring transit through\nthe Russian Federation, and several other countries. Some family members lacked financial\nmeans, adequate travel documents, or were afraid of being detained in the Russian\nFederation. Some parents or relatives of children who travelled to Russian vacation camps\nfaced criticism for their decisions and were reluctant to seek help from the Ukrainian\nGovernment, out of fear of being accused of collaboration."},{"id":"a-hrc-52-crp-4-p0739","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"739","seq":741,"section":"2. Situations in which child transfers took place","text":"In several of the incidents reviewed by the Commission, Ukrainian authorities have\nassisted parents, legal guardians, or family members in the endeavour to establish the\nnecessary contacts and prepare the travel to fetch the children, notably through the issuance\nof required documents. Some organizations have offered to facilitate such travel of parents\nor relatives through logistic or financial means. In some cases, family members of transferred\nchildren or Ukrainian authorities have managed to establish contact with Russian authorities\nor de facto authorities in Russian-occupied territories to obtain their authorisation and\nfacilitation of the arrival of a parent or relative to pick-up a transferred child."},{"id":"a-hrc-52-crp-4-p0740","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"740","seq":742,"section":"2. Situations in which child transfers took place","text":"Parents, relatives, and legal guardians interviewed emphasized that such situations\nhave a severe impact on children. The uncertainty and fear of being permanently and forcibly\nseparated from their loved ones in a foreign country, is highly traumatising. The children\nwho had been transferred reported how they missed their parents, relatives, and friends in\nUkraine. Studies on children separated from their parents during wartime, with the intention\nof sparing them from hostilities, show that the trauma of separation is often more harmful\nand long lasting than remaining with the families and enduring war related traumas together.\n442"},{"id":"a-hrc-52-crp-4-p0741","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"741","seq":743,"section":"2. Situations in which child transfers took place","text":"In conclusion, in the situations examined by the Commission, a lack of information\nand structures to facilitate the establishment of family contacts and reunifications led to\nprolonged separation of children from their families, and even bore risks for permanent\nseparation for some of the children. The Commission has found that Russian authorities\nviolated their obligation under international humanitarian law to facilitate in every possibly\nway the reunion of families dispersed as a result of the armed conflict.443 This may amount\nto the war crime of unjustifiable delay in the repatriation of civilians. 444 Such conduct is also\nin violation of a child’s right to family environment and is not in the best interests of the\nchild.445"},{"id":"a-hrc-52-crp-4-p0742","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"742","seq":744,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The Commission has followed official statements and media coverage regarding legal\nand policy measures adopted by Russian officials regarding the deportations of some\ncategories of children from Ukraine to the Russian Federation and their status. Such measures\nappear to affect children from the Donetsk and Luhansk regions in Ukraine. Initiatives relate\nin particular to the placement of children in Russian foster families and measures facilitating\nsuch placements, notably the granting of the Russian citizenship to some categories of\nchildren and the coordination of transfers of children with the Russian-backed de facto\nauthorities in Donetsk and Luhansk regions. These undertakings are indicative of an intent to\naccommodate some of the children transferred from Ukraine on a longer-term basis, or even\npermanently, in the Russian Federation. An intent of permanence has been also stated in\nseveral official declarations, as outlined below."},{"id":"a-hrc-52-crp-4-p0743","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"743","seq":745,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In March 2022, during a meeting with President Putin regarding “families evacuated\nfrom Donbass and children”, Ms. Lvova-Belova discussed the possibility for Russian\nfamilies to temporarily accommodate orphan children and raised the issue of legislative\ndelays linked to their citizenship. President Putin replied that relevant changes to the\nlegislation would be made.446 In May 2022, he signed a decree introducing modifications in\nthe existing legislation, providing that orphans and children without parental care, who are\n“citizens” of the former so-called Donetsk and Luhansk People’s Republics, and of Ukraine,\ncan acquire Russian citizenship in a simplified way. The process, among other things,\ninvolves a guardian or custodian, along with the respective authorities or organizations,\napplying on behalf of the individuals.447"},{"id":"a-hrc-52-crp-4-p0744","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"744","seq":746,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"International humanitarian law states that an Occupying Power may not, in any case,\nchange the personal status of children.448 Under the Convention on the Rights of the Child, a\nchild has the right to preserve his or her identity, including nationality, name, and family\nrelations as recognised by law without unlawful interference.449"},{"id":"a-hrc-52-crp-4-p0745","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"745","seq":747,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"Subsequent to this legislative amendment, in June 2022, Ms. Ksenia Mishonova, the\nOmbudsperson for Children’s Rights in the Moscow Region, referring to children from the\nso-called Donetsk People’s Republic, stated that a presidential decree on citizenship “will\nremove the last obstacles for children to live and be brought up in Russian families.” 450 In a\nmedia interview in July 2022, Ms. Lvova-Belova declared: “now that the children have\nbecome Russian citizens, temporary guardianship can become permanent”.451 Also in July\n2022, she stated that the transfer of children “was preceded by a large and painstaking work,\nwhich was carried out taking into account the legislative features of the interested states, and\nwas connected with the preparation of documents, the choosing of regions capable of creating\nthe necessary conditions, the search, and selection of families ready to adopt children with\ndisabilities or a large family group at once – 4-9 children each”.452"},{"id":"a-hrc-52-crp-4-p0746","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"746","seq":748,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"During official visits to the former so-called Donetsk and Luhansk People’s\nRepublics, Ms. Lvova-Belova discussed, among other issues, transfers and placements of\nchildren in Russian families. In May 2022, she said in a media interview that “[t]emporary\nguardianship is now the only way to accommodate such children in families. But the format\nof temporary guardianship does not cover all the needs of children. They need Russian\ncitizenship. This will help not only to arrange them in the family constantly, but also provide\nall social guarantees […]. Therefore, agreements are being prepared with the LPR and the\nDPR on guardianship and trusteeship and on the adoption of children, and then amendments\nto the legislation of the LPR and the DPR will be initiated, which will allow Russian citizens\nto adopt and take custody of children from these territories.”"},{"id":"a-hrc-52-crp-4-p0747","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"747","seq":749,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In August 2022, Ms. Lvova-Belova travelled to the so-called Donetsk People’s\nRepublic, where she met with the de facto authorities and “agreed to continue working on\nthe placement of children from social institutions in Russian foster families”. Also in August\n2022, she visited the so-called Luhansk People’s Republic and discussed legal issues for\n“regulating the process of transferring children from the so-called Luhansk People’s Republic\nto the Russian families”. She stressed the importance of creating a database of orphans and\nchildren left without parental care in the former so-called Luhansk People’s Republic, which\nwould accelerate and improve the quality of the work of relevant agencies in selecting foster\nfamilies for these children. 453 In September 2022, Ms. Lvova-Belova also stated that, if,\nbased on the results of referendums in the Donetsk, Kherson, Luhansk, and Zaporizhzhia\nregions, “a decision is made to join Russia, a clear algorithm for the placement of children\nwill be obtained”. She added, “[n]ow such a wave is active on the part of our families who\nare ready to take these children, it will be available for them, because these children will first\nget into regional data banks, then into federal ones. And they will be able to find each other\nwithout our help and without those difficulties that we had.”454"},{"id":"a-hrc-52-crp-4-p0748","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"748","seq":750,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"Several official statements and events illustrated how groups of children transferred\nfrom the former so-called Donetsk and Luhansk People’s Republics to the Russian Federation\nwere granted citizenship and accommodated in Russian families. In July 2022, Ms. Lvova-\nBelova referred to a group of almost 200 children from Ukraine who were to receive Russian\ncitizenship.455 In September 2022, she stated that she brought 125 additional children orphans\nfrom the so-called Donetsk People’s Republic, who had already received Russian citizenship,\nfor placement in Russian families, and that 104 children from the so-called Luhansk People’s\nRepublic are preparing for travel.456 In September 2022, during a press briefing of the Civic\nChamber of the Russian Federation, Ms. Lvova-Belova said that she had also hosted one\nUkrainian boy in her family: “One of the boys ended up in my own family. And I see before\nmy own eyes how this integration began to happen…You see, there is some negativity. At\nfirst, it is there, but then the love is formed – the love for Russia.”457"},{"id":"a-hrc-52-crp-4-p0749","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"749","seq":751,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"After international condemnation regarding the placements of Ukrainian children with\nRussian families in the Russian Federation, in October 2022, Ms. Lvova-Belova published\nan explanation of the foster placement process, as follows: “Currently, about 300 orphans\nand children left without parental care have been placed in the care of Russian families. All\ndecisions on family arrangements were made by the authorised bodies of the republics,\nexclusively with the consent of the children, in full compliance with the requirements of\ninternational law. Families were selected taking into account the individual characteristics of\neach child, his state of health, and needs, with the necessary experience”. 458"},{"id":"a-hrc-52-crp-4-p0750","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"750","seq":752,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The Commission is highly concerned that such measures may have a profound\nimplication on a child’s identity and found them to be in violation of the right of a child to\npreserve his or her identity, including nationality, name and family relations without unlawful\ninterference, as recognised by international human rights law. 459\nCase descriptions"},{"id":"a-hrc-52-crp-4-p0751","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"751","seq":753,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"As stated above, the Commission has examined situations in which Russian\nauthorities have transferred children to territories they occupied in Ukraine or to the Russian\nFederation. The case descriptions outlined below are based on the detailed accounts of\nparents, personnel of specialised institutions, at times accompanied by the children who had\nbeen the victims of transfers. Testimonies provided descriptions of the circumstances of the\ntransfers and, in some occasions, of the conditions in which the children were accommodated.\nIn several of these incidents, interlocutors listed examples of other children who were in a\nsimilar situation and had not yet been recovered by family members or had been unable to\nestablish contact with them.\nTransfers of children after separation from parents or legal guardians due to hostilities"},{"id":"a-hrc-52-crp-4-p0752","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"752","seq":754,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In a first category of incidents, Russian authorities transferred to Russian-controlled\nareas in the Donetsk region children who lost contact with their legal guardians or lost their\nparents during the ongoing hostilities. The children were transferred to hospitals in Donetsk\ncity. In the situations reviewed, Russian authorities did not seem to have searched for a way\nto facilitate their evacuation to territory controlled by the Ukrainian government. They also\ndid not appear to have made any proactive attempts to find the parents or relatives of the\nchildren or to notify the Ukrainian authorities. The children and their families took the\ninitiative to establish contact. Family members had to undertake long and complicated travel,\nthrough several countries, to retrieve the children. A combination of these factors has resulted\nin separations of children from their families lasting one to two months. According to\nwitnesses, some children in similar situations had not been able to locate their families.\nTransfer of 17 children evacuating from Mariupol\n455 Mordovmedia, “In early July, 200 children from Donbass will receive Russian citizenship”, 28 June\n2022. (available only in Russian)\n456 Official website of the Russian Federation’s Presidential Commissioner for Children’s Rights,\n“Maria Lvova-Belova brought 125 orphans from the DPR to be placed in Russian families”, 16\nSeptember 2022. (available only in Russian)\n457 Civic Chamber of the Russian Federation, “Press briefing on the work of the Public Situation Center\nfor Monitoring Referendums in the DPR, LPR, Zaporozhye and Kherson regions”, 27 September\n2022. (available only in Russian)\n458 Official website of the Russian Federation’s Presidential Commissioner for Children’s Rights, “The\nHRC sent a refutation of fakes about the forced removal of Ukrainian children to international\norganizations”, 19 October 2022. (available only in Russian)\n459 Convention on the Rights of the Child, article 8(1)."},{"id":"a-hrc-52-crp-4-p0753","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"753","seq":755,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In a situation widely covered in the media, as the fighting broke out in Mariupol city\nin February 2022, 17 children aged four to 17 years who were on vacation in a health resort\nthere, lost contact with their families and attempted to join them in Ukraine-controlled areas.\nAccording to media interviews, Russian-backed authorities at a checkpoint denied their\npassage and instead the children ended up in a hospital in Donetsk city.460"},{"id":"a-hrc-52-crp-4-p0754","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"754","seq":756,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The foster mother of six of these children informed the Commission that during their\nstay at the hospital, her children had been pushed, slapped, insulted, screamed at, called\nnames, and given bad food. Three among them who had disabilities were not provided with\nadequate medicine. She said: “[they] constantly told my children that they would be given to\nother families, so that they forget their own parents and that [they] were making documents\nof the [former so-called] Donetsk People’s Republic for them”."},{"id":"a-hrc-52-crp-4-p0755","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"755","seq":757,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"Russian-backed de facto authorities did not appear to take measures to reunite the\nchildren with their families and guardians. Only in June 2022 volunteers managed to assist\ntwelve of these children to be reunified with their foster parents. The Commission has\nreceived information that at least one of the 17 children was subsequently deported to the\nRussian Federation and placed in a foster family.\nTransfer of three boys evacuating from Mariupol"},{"id":"a-hrc-52-crp-4-p0756","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"756","seq":758,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In March 2022, in Mariupol city, three boys aged 15 and 16, who attended school\ntogether, lost contact with their legal guardians as the shelling intensified and electricity and\nmobile connection were disrupted. They attempted to leave the area with a convoy. At a\ncheckpoint, when authorities of the so-called Donetsk People’s Republic noticed that the\nchildren were unaccompanied, they handed them to the police department of the former so-\ncalled Donetsk People’s Republic, who brought them to a hospital in Donetsk city. From the\nhospital, the boys managed to establish contact with Ukrainian authorities and find their legal\nguardian; they had been in touch with him during their stay. According to their legal guardian,\nrepresentatives of armed groups provided the children with promises of a better life and\nprovided some criticism of their legal guardian. At the beginning of June 2022, he travelled\nto pick them up. This involved a long and complicated journey through the Russian\nFederation and three other countries.\nTransfer of injured boy after the death of the mother in Mariupol"},{"id":"a-hrc-52-crp-4-p0757","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"757","seq":759,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In March 2022, in Mariupol city, a shell that landed not far from a shelter injured a\n10-year-old boy in the leg and killed his mother. The boy’s grandmother told the Commission\nthat Russian armed forces transported the boy to a hospital in Donetsk city, where he received\ntreatment for his leg. She learned about her grandson’s situation through the media. The boy\nsubsequently managed to contact her with a phone borrowed from a volunteer at the hospital.\nHe told her that, at the hospital, two men approached him and asked him if he wanted to go\nto Moscow, but he refused. The boy was issued with a so-called Donetsk People’s Republic\ncertificate. At the end of April 2022, the grandmother managed to travel through the Russian\nFederation and two other countries and was reunified with her grandson.\nChildren transfers following the arrest of the parent at a filtration point"},{"id":"a-hrc-52-crp-4-p0758","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"758","seq":760,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In a second category of incidents, Russian authorities transferred children to Russian-\ncontrolled territories in the Donetsk region after the detention of a parent at a filtration point.\nSocial services accommodated the children in an institution or a hospital. The Commission\nis not aware of any attempts by Russian authorities to establish contacts or seek alternative\ncare options by family members, or by Ukrainian authorities, while the parents of the children\nwere in detention. In one of the incidents, the children were further transferred to the Russian\nFederation, without clear reasons for the transfer. Family members had to undertake long and\ncomplicated travel to fetch the children. As a result of these combined factors, the separation\nof the children and their families lasted two to three months. Family members who travelled\n460 For example, BBC, “Ukraine war: Why I never gave up trying to find my children, 18 July 2022”;\nSarah El Deeb, Anastasiia Shvets, Elizaveta Tilna (Associated Press), “How Moscow grabs Ukrainian\nkids and makes them Russians”, first published on 13 October 2022.\nto retrieve children, reported that they saw other children in a similar situation, and that some\nof them had not been able to locate family members.\nTransfer of three children after the detention of their father at a filtration point"},{"id":"a-hrc-52-crp-4-p0759","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"759","seq":761,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In April 2022, a former member of the Ukrainian armed forces attempted to leave\nMariupol in an evacuation convoy with his two daughters, aged seven and nine, and son\naged 12. He told the Commission that at a filtration point, he was detained and transferred to\nthe Olenivka penal colony. Meanwhile, social services of the so-called Donetsk People’s\nRepublic transferred the children to a children’s home and then to a hospital in the Donetsk\nregion. In mid-May 2022, the children were further deported by plane to the Russian\nFederation, together with almost 30 other children, and were accommodated in a camp near\nMoscow. The father found out that his children had been transferred to the Russian\nFederation upon his release from detention at the end of May 2022. According to media\ncoverage, in early June 2022, the boy called his father to convey that the siblings were\ninformed that they would be placed in a foster family or an institution. 461 During the second\nhalf of June 2022, the father managed to travel to the Russian Federation to pick up his\nchildren, after a challenging trip, with multiple security and logistical constraints. The family\nsaw other Ukrainian children in the camp, who told them that they were to be accommodated\nin Russian families.\nTransfer of one child after the detention of his mother at a filtration centre"},{"id":"a-hrc-52-crp-4-p0760","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"760","seq":762,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In late March 2022, on the outskirts of Mariupol, a 11-year-old boy, was injured by\nshrapnel in the eye and his mother brought him to a neighbouring steel and iron plant, where\nhe could benefit from the assistance of military paramedics. According to the boy’s\ngrandmother, after Russian armed forces took control of the plant, they transported the\ncivilians present at the plant to a filtration camp. The mother was taken for interrogation to a\nseparate room. Russian soldiers also interrogated the boy and screamed at him. The family\nhas not seen the mother again. Social services subsequently took the boy to a hospital in\nDonetsk city. In the hospital, the boy managed to borrow a phone and establish contact with\nhis grandmother."},{"id":"a-hrc-52-crp-4-p0761","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"761","seq":763,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"He asked several other times people to lend him a phone to call her. Social services\nof the so-called Donetsk People’s Republic told the grandmother to pick up her grandson as\nthey could not keep him any longer. At the same time, hospital staff told the boy that if his\ngrandmother did not come, he would be transferred to a children’s home. The grandmother\nmanaged to obtain the necessary official documents to retrieve the boy and at the end of June\n2022, she travelled via the Russian Federation and two other countries, which took over one\nweek. She stated that in the hospital in Donetsk city, the doctors said that it was too late to\nperform surgery on the boy’s eye. However, upon return to Ukrainian-controlled territory, he\nunderwent eye surgery and treatment. She also told the Commission that when fetching her\ngrandson, she became aware of two other situations of unaccompanied children transferred\nto the same hospital.\nTransfers of children in institutions"},{"id":"a-hrc-52-crp-4-p0762","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"762","seq":764,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In a third category of incidents, Russian authorities transferred children from certain\ninstitutions in Kharkiv and Kherson regions to Crimea and Luhansk region, or to the Russian\nFederation; generally this took place because of nearby hostilities. Parents, legal guardians,\npersonnel of institutions told the Commission that they did not consent to such transfer and\nthat the children themselves had expressed strong objections. In two situations, Russian\nauthorities prevented heads of institutions from evacuating to territory controlled by the\nGovernment of Ukraine. In one incident, children from an institution and their legal guardian\nwere left without accommodation after transfer, while in another incident, children appear to\nhave been treated inadequately and did not receive the care required for children with special\nsupport needs. According to witnesses, these experiences had been highly traumatic for many\nof the children and risk having long-term physical and psychological consequences. In cases\n461 See, for example, “‘We hugged for a long time’: the Ukrainian father who rescued his children from\nMoscow”, The Guardian, 19 March 2023; Meduza, “Dad, you have five days before they adopt us”, 4\nNovember 2022.\nwhere parents could establish contact, they had to undertake long and complicated travel to\nfetch them. Due to these combined factors, family separations lasted up to three months.\nWitnesses reported that also numerous other children were in this situation and did not have\nthe possibility to establish family contacts.\nTransfer of 15 children from an institution in Mykolaiv region"},{"id":"a-hrc-52-crp-4-p0763","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"763","seq":765,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"As the armed conflict broke out in February 2022, the head of a boarding school in\nMykolaiv region facilitated the return of most of the children from the institution to their\nfamilies. However, she remained with 15 children orphaned or deprived of parental care, with\na mild disability, under her care and legal guardianship. Regardless of her efforts, she did not\nmanage to evacuate the children to a territory controlled by the Government of Ukraine\nbecause of security and logistical constraints. Russian armed forces repeatedly visited the\ninstitution and told her to evacuate to Crimea, at times using threatening language or\nbehaviour, which she refused, as she told them that the children had relatives in Ukrainian-\ncontrolled territories. In July 2022, after Russian authorities learnt that she was attempting to\nevacuate the children to a territory under Ukrainian control, they told her that they had now\ndecided to evacuate her. Russian armed forces transferred the children and the head of\ninstitution to a rehabilitation centre in the Kherson region, which was then under Russian\ncontrol, despite the fact that all of them repeatedly objected to the transfer."},{"id":"a-hrc-52-crp-4-p0764","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"764","seq":766,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In October 2022, as Russian armed forces were about to lose control of numerous\nareas in the Kherson region and ordered evacuations of civilians, a Russian-appointed\nadministration official gave the same head of institution ten minutes to prepare the children\nfor further evacuation. Russian armed forces transferred the group to Crimea, where they left\nthem without accommodation or any option for return to Ukraine. Local emergency services\ntold the head of institution to proceed, by train, to a camp in the Russian Federation. She said\nthat children were crying, and “every child from her group wanted to go back to Ukraine\nbecause they had relatives there”. They were very afraid of being forcibly separated from\ntheir legal guardian and being forced to remain in the Russian Federation. In November 2022,\nthe group managed to move to a third country with the help of a volunteer.\nTransfer of 80 children from an institution in the Kherson region"},{"id":"a-hrc-52-crp-4-p0765","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"765","seq":767,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"Starting in February 2022, when Russian authorities took control of areas in the\nKherson region, a boarding school hosting about 85 children and young adults with\ndisabilities found itself in territory under Russian control. As the institution contemplated an\nevacuation, the police came to the school and said, “if we hear that you are trying to evacuate,\nyou will have problems”, and removed Ukrainian flags and insignia from the premises.\nChildren in this institution had mobility and mental disabilities, with about 40 bedridden and\nsome in wheelchairs. Around half of them were orphans, some had been abandoned, and\nothers had been placed there by their parents to receive special education and adequate care."},{"id":"a-hrc-52-crp-4-p0766","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"766","seq":768,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"In October 2022, according to the staff of the institution, as the former director refused\nto collaborate, Russian authorities appointed a new director. During the same month, Russian\nauthorities undertook the transfers of the children and young adults from this institution to\nRussian-controlled territories, which occurred in three groups. The official reason given for\nthe transfer was temporary rest, treatment, and rehabilitation. In October 2022, the first group\nof 16 children was brought by bus to a hospital in Simferopol, in Crimea. In November 2022,\n12 additional children and young adults were transferred by bus to the same hospital. On\nthese two occasions, medics from Crimea came to fetch the children and accompanied their\ntransfer. Also in November 2022, the third group of over 50 residents of the institution with\nthe most severe disabilities, was transferred to a kindergarten in another location of the\nKherson region."},{"id":"a-hrc-52-crp-4-p0767","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"767","seq":769,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"A former staff member of the institution stated that prior to evacuation, parents were\ncalled and asked for their consent. However, some parents could not be reached due to the\nabsence of telephone connection and internet in some areas, and the children were evacuated\nregardless of the absence of consent. They reported that some of the children opposed the\ntransfer and cried."},{"id":"a-hrc-52-crp-4-p0768","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"768","seq":770,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The mother of a 13-year-old girl residing in this institution, who had a disability and\nused a wheelchair, told the Commission that when asked, she did not consent to her\ndaughter’s transfer, unless it was to a Ukrainian-controlled area. Nevertheless, in November\n2022, she received a call informing her that her daughter had been transferred despite her\nlack of consent. She was told that Russian armed forces took the children without giving\nthem time to pack. During the same month, she travelled through Georgia to Crimea to fetch\nher daughter. She found that her wheelchair was broken, that she was dirty, with clothes and\nshoes missing, and had received very poor food. After her return, the girl had repeated\nnightmares and avoided talking about her experience in Crimea.\nTransfer of 13 children from an institution in Kharkiv region"},{"id":"a-hrc-52-crp-4-p0769","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"769","seq":771,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The Commission interviewed the mother of a 15-year-old boy with a disability, who\nwas transferred as part of a group of 13 children with disabilities attending a boarding school\nin the Kharkiv region, in September 2022, at a moment when Ukrainian armed forces were\nrecovering control of numerous localities. When she went to pick-up her son at the school, a\nsecurity guard informed her that the children had been picked up by a bus led by Russian\narmed forces, after a decision by the school director. She had not been informed of the\ntransfer and only learned about the whereabouts of her son through a video circulated on the\nmedia. Her son later informed her that the transfer was organized by Russian armed forces\nand that the children were brought to a boarding school and then to a children institution in\nthe Luhansk region. Subsequently, the principal of the institution called her to ask her to\ncome and fetch her child. Three months after the initial transfer, she managed to travel\nthrough the Russian Federation and two other countries to reach Luhansk region. She stated\nthat other children in a similar situation cried when she left, as she could not take them home.\nShe also noted that the condition of her son had become more acute since the transfer, that\nhe needed treatment, and was waking up screaming at night.\nTravel of children with parental consent"},{"id":"a-hrc-52-crp-4-p0770","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"770","seq":772,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The Commission also reviewed situations in which numerous children from areas that\ncame under Russian Federation control in Kharkiv, Kherson, and Zaporizhzhia regions\ntravelled temporarily to vacation camps in Crimea or the Russian Federation. 462 Radio and\ntelevision channels informed residents of the possibilities for children to spend vacations of\nup to three weeks in summer camps in the Russian Federation. Parents of children who\ntravelled to such camps explained to the Commission that they consented to the children’s\ntravel and stay in the camps, as they believed that such vacations would be a good opportunity\nfor the children to take a break from the armed conflict. However, since numerous areas in\nthese regions returned to Ukrainian armed forces control, Russian authorities did not organize\nthe return the children and required individual parents or legal guardians to travel in person\nto pick them up.463 Travel to the locations of the camps implied significant logistic, financial,\nand security constraints, and the crossing of several international borders, which in turn led\nto long family separations. Some parents had no financial means to cover the costs of the trip,\nlacked travel documents, or feared that they would not be able to return from the Russian\nFederation and were therefore unable to travel. On some occasions, the Government of\nUkraine has issued the necessary documents, local administrations have helped raise funds\nto cover the travel costs, and a local organization has helped parents to organize their travel."},{"id":"a-hrc-52-crp-4-p0771","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"771","seq":773,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The Commission met with the head of an institution who saw hundreds of children\nfrom the Kherson region, together with their teachers, in a summer camp in the Russian\nFederation. She said that the groups had travelled voluntarily. Those who were from the areas\nof Kherson region which remained under Russian control, managed to return to Ukraine,\naccompanied by their teachers. The teachers from areas recovered by Ukrainian armed forces\nfeared being accused of collaboration and were reluctant to return. In addition, numerous\nfamilies from those areas had been displaced. These factors resulted in prolonged family\nseparations for some of the children."},{"id":"a-hrc-52-crp-4-p0772","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"772","seq":774,"section":"4. Measures put in place by the Russian Federation regarding certain categories of","text":"The mother of a 14-year-old boy from Kherson city told the Commission that her son\ntravelled with her consent to join a vacation camp in Crimea for about two weeks. However,\nthe teachers at the camp informed her twice that due to the insecurity, the children’s return\n462 See, for example, TASS, “4500 children from Kherson and Zaporizhzhia regions will rest in\nsanatoriums and camps of Crimea”, 15 October 2022. (available only in Russian); “Weeks turn to\nmonths as children become stuck at camps in Crimea”, The Guardian, 27 December 2022.\n463 See, for example, Svyatoslav Khomenko, Nina Nazarova, “Parent’s personal problem”. Dozens of\nUkrainian children separated from their families remain in camp in Russia”, BBC Russian Service, 17\nOctober 2022, (available only in Russian).\nhad been postponed. They also said that if parents wished to pick up the children, they could\ndo so, but in such case they could not return to Kherson, because of security constraints. Such\ntravel would be long and complicated, and would involve crossing several international\nborders. At the moment of the interview, she did not have the required documents and\nfinancial means to undertake such travel."},{"id":"a-hrc-52-crp-4-p0773","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"773","seq":775,"section":"E. Genocide","text":"Genocide is one or more specified acts committed with intent to destroy, in whole or\nin part, a national, ethnical, racial or religious group. Enumerated acts include, among others,\nkilling members of the group and forcibly transferring children of the group to another group.\nUnder the Genocide Convention, several acts are punishable, including direct and public\nincitement to commit genocide.464"},{"id":"a-hrc-52-crp-4-p0774","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"774","seq":776,"section":"E. Genocide","text":"The Commission is concerned about allegations of genocide in Ukraine. It has not,\nbased on available evidence, reached a conclusion whether there is genocide in Ukraine. The\nCommission’s investigations are an ongoing process. Certain allegations raise issues under\nthe Genocide Convention. For instance, some of the rhetoric transmitted in Russian state and\nother media may constitute direct and public incitement to commit genocide."},{"id":"a-hrc-52-crp-4-p0775","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"775","seq":777,"section":"1. Overview","text":"The ongoing armed conflict has had devastating effects on every aspect of life in\nUkraine. The wide array of grave violations, abuses and crimes committed in the context of\nthe armed conflict are a source of immense human suffering and destruction. The effects on\nthe enjoyment of almost all human rights by people living in Ukraine are considerable, with\nboth present and long-term ramifications. This will in turn lead to significant delays in the\nfulfilment of the Sustainable Development Goals.465"},{"id":"a-hrc-52-crp-4-p0776","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"776","seq":778,"section":"1. Overview","text":"In addition to the human losses, the armed conflict in Ukraine has caused a population\ndisplacement not seen in Europe since the Second World War. As of 21 February 2023,\naccording to the UNHCR, relying on national authorities’ data, there were about eight million\nrefugees from Ukraine across Europe, with about 4.8 million registered for temporary\nprotection.466 Due to the martial law preventing men between the ages of 18 to 60 from\nleaving the country but for some exceptions, about 90 per cent of the refugees are women\nand children.467 In a protection profiling and monitoring exercise conducted by UNHCR and\nits partners between May and December 2022 in eight countries hosting Ukrainian refugees,\n63 per cent of the respondents reported plans to stay in their current host country citing safety,\nfamily ties, employment and asylum procedure as the main reasons. 468"},{"id":"a-hrc-52-crp-4-p0777","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"777","seq":779,"section":"1. Overview","text":"In its update on 23 January 2023, the International Organization for Migration\nestimated that 5.4 million people are displaced across Ukraine, after reaching a peak of over\neight million in May 2022.469 Half of the respondents surveyed reported that their habitual\nresidence had been completely destroyed (five per cent) or damaged (45 per cent).470 Women\nand girls represent about 55 per cent of internally displaced persons. 471 Displaced households\naverage over three people with 73 per cent of them having at least one vulnerable member.472\nIn addition, some persons have moved several times, including since 2014. 473"},{"id":"a-hrc-52-crp-4-p0778","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"778","seq":780,"section":"1. Overview","text":"The destruction of essential infrastructure, schools, health facilities, residential\nbuildings, and others has had an immense impact on people’s lives and on their enjoyment\nof a wide range of human rights, placing special burdens on the vulnerable. While the\nenjoyment of certain rights is affected only temporarily, some of the long-term effects of this\narmed conflict are clearly visible. In addition to the many physical injuries that will need time\nto heal, deteriorating mental health will have long-lasting, multi-generational effects.474 In\naddition, many places in Ukraine will remain unsafe because of unexploded ordnance and\nexplosive remnants of war. Demining will take years. 475 In August 2022 the Minister of\nEnvironmental Protection and Natural Resources of Ukraine estimated that 27 per cent of\nUkraine’s territory would need to be cleared of mines and explosives. 476 Similarly, the full\nrange and severity of the environmental consequences of the armed conflict will need to be\nverified and assessed, but preliminary monitoring indicates significant impacts on urban and\nrural environments that could leave the country and the region with a toxic legacy for\ngenerations to come.477"},{"id":"a-hrc-52-crp-4-p0779","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"779","seq":781,"section":"1. Overview","text":"This section describes some of the consequences of the armed conflict on the rights to\nlife, health, education, adequate housing, food and water, which the Commission has\ndocumented during its investigations, and the impact on some vulnerable groups. It does not\nconstitute an exhaustive list of the legacies left by the conflict in its wake. Most of the effects\nand consequences of the armed conflict described are believed to be still ongoing and are\nlikely to continue in a longer term."},{"id":"a-hrc-52-crp-4-p0780","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"780","seq":782,"section":"2. Right to life","text":"The armed conflict in Ukraine has killed thousands of civilians. As of 15 February\n2023, OHCHR had recorded 8,006 civilians killed and 13,287 injured in Ukraine since 24\nFebruary 2022.478 Those killed included 3,533 men, 2,096 women, 256 boys, and 200 girls.\nThose injured included 3,460 men, 2,361 women, 394 boys, 290 girls. Most of the civilian\ncasualties were caused by the use of explosive weapons with wide area effects, including\nshelling from heavy artillery, multiple launch rocket systems, missiles and air strikes.\nOHCHR believes that the actual figures of civilians killed and injured are considerably\nhigher.479"},{"id":"a-hrc-52-crp-4-p0781","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"781","seq":783,"section":"2. Right to life","text":"These figures also do not take into account the indirect victims of the armed conflict.\nLack of access to regular health care, reduced living standards, including limitations on\naccess to food, water, and housing, particularly in areas where hostilities are taking place,\nhave likely increased mortality rates. The overall effects of the attacks on the energy\ninfrastructure, for example, ripple across health, sanitation, food security, education,\nemployment, and other areas, and will become clear only over time."},{"id":"a-hrc-52-crp-4-p0782","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"782","seq":784,"section":"2. Right to life","text":"International human rights law states that every human being has the inherent right to\nlife, and no one shall be arbitrarily deprived of his life.480 Rules of international humanitarian\nlaw may be relevant for the interpretation and application of the relevant international human\nrights law norm when the situation calls for their application. Both spheres of law are\ncomplementary, not mutually exclusive.481"},{"id":"a-hrc-52-crp-4-p0783","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"783","seq":785,"section":"2. Right to life","text":"The armed conflict has also killed and injured thousands of Ukrainian and Russian\nsoldiers, but estimates are difficult to establish because of the confidential character of this\ninformation. The impact of the loss of thousands of people in their prime will be long-lasting.\nThe process of rehabilitating those left physically and psychologically harmed by war is costly\nand long."},{"id":"a-hrc-52-crp-4-p0784","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"784","seq":786,"section":"3. Right to health","text":"The armed conflict has had a significant impact both directly on people’s physical and\nmental health and on access to healthcare, particularly in areas close to the frontlines, and\nwhere health facilities have been destroyed or damaged, or otherwise became inaccessible.\nIn many cases, civilians suffered life-changing injuries, long-lasting psychological trauma,\nand had to cope with deep anxiety and fear."},{"id":"a-hrc-52-crp-4-p0785","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"785","seq":787,"section":"3. Right to health","text":"Every human being is entitled to the enjoyment of the highest attainable standard of\nphysical and mental health.482"},{"id":"a-hrc-52-crp-4-p0786","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"786","seq":788,"section":"3. Right to health","text":"The hostilities have caused a deterioration in the level of access to health-care services\nand medicines. According to a World Health Organization assessment, this has been in\nparticular the case for people living in regions close to the front line, in areas that are not\nfully controlled by Ukraine, and for people who have been internally displaced. 483"},{"id":"a-hrc-52-crp-4-p0787","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"787","seq":789,"section":"3. Right to health","text":"Fighting and attacks have affected a large number of medical facilities. The World\nHealth Organization recorded 611 attacks by heavy weapons on medical facilities between\n24 February 2022 and 1 February 2023.484 In December 2022, the Deputy Ministry of Health\nof Ukraine reported that over 1,000 medical facilities in Ukraine had been damaged, and 144\nhad been completely destroyed.485 The Commission investigated the damage or destructions\nof some of them."},{"id":"a-hrc-52-crp-4-p0788","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"788","seq":790,"section":"3. Right to health","text":"Among the medical facilities that were damaged or destroyed were maternity\nhospitals, such as the Primary Medical and Sanitary Aid Centre No. 3 in Mariupol, better\nknown as Maternity Ward No. 3, whose maternity and children’s wing was significantly\ndamaged during an airstrike, while several women were either waiting to give birth or had\njust done so. In several maternity hospitals across Ukraine, women have had to give birth in\nbasements.486 This situation raises concern, as it was reported that caesarean deliveries\nincreased due to stress and disruption to prenatal services, especially for internally displaced\npersons, as well as an increase of complicated deliveries and miscarriages. 487"},{"id":"a-hrc-52-crp-4-p0789","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"789","seq":791,"section":"3. Right to health","text":"The World Health Organization also found that, while the situation has been\nimproving, access to health and medicine has been challenging, especially for people close\nto frontlines and in areas which returned to Ukrainian control. 488 It identified cost and time\nconstraints to get to and from health facilities, as well as limited transportation options, as\nthe main barriers to accessing health care. For access to medicines, the top three barriers\nconsisted of the increase in price, unavailability and long queues in local pharmacies.489 The\nHealth Cluster in Ukraine also reported that the armed conflict has disrupted the supply\nchains for medicines and medical supplies.490"},{"id":"a-hrc-52-crp-4-p0790","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"790","seq":792,"section":"3. Right to health","text":"The above-mentioned factors have exacerbated the burden of chronic disease.491\nPeople living close to frontlines and in Russian-controlled territories have been particularly\naffected. For instance, one woman told the Commission that during a time when Ivankiv\nvillage, Chernihiv region, was under Russian control, chemotherapy was not accessible to\npeople suffering from cancer. It should also be noted that the World Health Organization\nfound that women with chronic conditions were less likely than men not to receive the\nmedical care they needed.492"},{"id":"a-hrc-52-crp-4-p0791","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"791","seq":793,"section":"3. Right to health","text":"The armed conflict has left numerous persons with long-lasting injuries and trauma.\nMany victims of attacks with explosive weapons, including landmines, had to undergo\namputations, sometimes of several limbs, requiring long rehabilitation. Others sustained\nsevere injuries, such as one woman who suffered significant loss of sight, damage to her\nhearing, and scaring across her face and body when a missile struck near her apartment\nbuilding in Kharkiv city."},{"id":"a-hrc-52-crp-4-p0792","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"792","seq":794,"section":"3. Right to health","text":"Persons who remained in basements or in crowded spaces also suffered from illnesses\nand disease, sometimes leading to death. In a case in which Russian armed forces confined\n365 civilians, including older persons, over 70 children and five persons with disabilities, in\na basement in Yahidne village, Chernihiv region, during 28 days, 10 older people died\nbecause of the inhuman conditions. Victims suffered from infections, bedsores, and\nhallucinations (see paras. 541-543). One woman who, because of heavy fighting, had to\nspend the night in the basement of a hospital in Chernihiv city together with patients, persons\nfrom the neighbourhood, and wounded soldiers, told the Commission that there were too\nmany persons there, including those infected with COVID-19, and that it was very cold."},{"id":"a-hrc-52-crp-4-p0793","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"793","seq":795,"section":"3. Right to health","text":"The armed conflict has had a major impact on the mental health of the population.\nAccording to the Minister of Health of Ukraine, more than 90 per cent of Ukrainians have\none or more symptoms of post-traumatic stress disorder due to the ongoing armed conflict. 493\nDuring a survey by the International Organization for Migration in November-December\n2022, 27 per cent of internally displaced persons asked for the number to the organization’s\nfree psychological support hotline. The percentage among older persons reached 35. 494 A\n487 World Health Organization (Health Cluster in Ukraine), Public Health Situation Analysis (PHSA) –\nLong-form, 1 August 2022, p. 42.\n488 World Health Organization, WHO response to the Ukraine crisis, March 2023 Bulletin, Situation\nReport, 15 May 2023; World Health Organization (Health Cluster in Ukraine) “The Health Cluster in\nUkraine – 1 year after the war”, press release, 26 April 2023; World Health Organization, WHO\nresponse to the Ukraine crisis; February 2023 Bulletin, Situation Report, 27 March 2023.\n489 Word Health Organization, Health needs assessment of the adult population in Ukraine: survey\nreport, September 2022, 13 January 2023, pp. 24-25.\n490 Word Health Organization, Health needs assessment of the adult population in Ukraine: survey\nreport, September 2022, 13 January 2023, p. 9.\n491 United Nations, Office for the Coordination of Humanitarian Affairs, “Ukraine Humanitarian Needs\nOverview 2023”, 28 December 2022, p. 24.\n492 Word Health Organization, Health needs assessment of the adult population in Ukraine: survey\nreport, September 2022, 13 January 2023, p. 10.\n493 Neil Bowdler (Radio Free Europe radio Liberty), “Psychologists battle to help Ukraine’s shell-\nshocked population”, video, 11 October 2022.\n494 International Organization for Migration, “Ukraine – Internal Displacement Report – General\nPopulation Survey Round 11 (25 November – 5 December 2022)”, 2 February 2023 (25 November-5\nDecember 2022), 13 December 2023.\npsychologist shared that suicidal thoughts have been mentioned by patients more often than\nbefore the armed conflict."},{"id":"a-hrc-52-crp-4-p0794","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"794","seq":796,"section":"3. Right to health","text":"During its investigations, the Commission witnessed first-hand some of the\npsychological effects of the armed conflict. Interlocutors showed visible signs of trauma and\nrecalled the psychological impact on family members, including children. The death of close\nrelatives significantly affected the survivors. When asked about the impact of the death of\nher 7-year-old daughter and her 67-year-old father, one woman in Sumy region told the\nCommission: “I know for sure that my war will never end.”"},{"id":"a-hrc-52-crp-4-p0795","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"795","seq":797,"section":"3. Right to health","text":"The mental impact of the death of a family member was in many cases compounded\nby the lack of a proper burial according to cultural and religious rituals, either due to security\nconcerns, because armed forces prevented it, or because the bodies were never found. There\nare reports that Russian armed forces in several places prevented relatives and local residents\nfrom burying bodies lying in the street, leaving them there for days or even weeks. 495 In\nMariupol city, Donetsk region, and Rubizhne city, Luhansk region, for example, people laid\nloved ones to rest on a patch of soil near apartment building entrances, school grounds,\ngardens, and parks when hostilities were ongoing. When circumstances allowed it, the\nexhumation, the forensic examination, and the re-burial of their loved ones added to their\ngrief and trauma."},{"id":"a-hrc-52-crp-4-p0796","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"796","seq":798,"section":"3. Right to health","text":"Several survivors of explosive weapons attacks reported how they experienced panic\nattacks and anxiety in the aftermath and reported the same about their children. A woman\nfrom Kharkiv explained that her 11-year-old daughter, who received minor injuries during\nan air raid, continued to have panic attacks for a long time after they had reached safety,\nwhenever she heard an air raid alarm. A resident of Mariupol city remained traumatized by\nthe sound of airplanes several months after her evacuation from the city, while a father of an\n8-year-old boy, also from Mariupol city, explained that his son continued to have panic\nattacks triggered by the sound of airplanes or by power cuts. A psychologist said that she had\nobserved air raid sirens triggering physical reactions with children; for instance, their hands\nstarted to shake.496 One victim recounted that she is now scared of thunder and fireworks,\neven when she is outside of Ukraine, and that she sits in the corridor, just in case."},{"id":"a-hrc-52-crp-4-p0797","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"797","seq":799,"section":"3. Right to health","text":"According to United Nations and media reports, stress provoked by the armed conflict\nhas impacted pregnant women and increased the risks of premature births. Premature babies\nare more likely to develop medical complications which require incubators and ventilation\ndevices, which rely on the availability of power.497"},{"id":"a-hrc-52-crp-4-p0798","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"798","seq":800,"section":"3. Right to health","text":"The mental health toll has also affected volunteers and medical personnel who respond\nto mass casualty events or support in the exhumation or care of bodies.498 A doctor who\ntreated injured people in Kremenchuk city, Poltava region, after a missile struck a shopping\ncentre killing 21 persons and injuring dozens, noted the psychological impact on his staff,\nand in particular the traumatic effect of interacting with desperate relatives who were\nsearching for their loved ones. Psychiatrists and psychologists have also been directly\nimpacted by the armed conflict and have been overwhelmed because of the increased\nworkload; some had to take refuge outside the country.499"},{"id":"a-hrc-52-crp-4-p0799","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"799","seq":801,"section":"3. Right to health","text":"The general feeling that violations were committed with impunity has been an\nimportant source of fear and anxiety. For instance, the wife of a detained person said that the\nfear of being shelled and killed aside, the knowledge that one can be detained and killed at\nany moment, or that you can live without the respect of the rule of law, was terrifying. One\nman explained that, when his family hears the sound of a vehicle at night, they wonder if\npeople are “coming for them”. Another man told the Commission that he feared the return of\nRussian armed forces, if they are not held accountable. A psychologist explained that some\nof her patients were reluctant to report crimes, fearing retaliation from people cooperating\nwith the Russian authorities."},{"id":"a-hrc-52-crp-4-p0800","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"800","seq":802,"section":"3. Right to health","text":"Survivors of human rights violations and related crimes have suffered both physical\nand psychological effects. One woman who was unlawfully detained said “seven months past,\nit is still aching, and I still feel humiliation and fear […] I have flashbacks”."},{"id":"a-hrc-52-crp-4-p0801","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"801","seq":803,"section":"4. Right to education","text":"The armed conflict has deeply affected children and their right to education. The use\nof explosive weapons in populated areas has led to the damage and destruction of numerous\neducational institutions across many of the regions affected by hostilities. It has forced\nchildren living in the concerned areas to spend considerable time in shelters. Large-scale\ndisplacement has further compounded these challenges. Online education also came with a\nrange of difficulties. The psychological effect of the armed conflict, fear and anxiety, have\nimpacted the children’s ability to focus on their studies. Occupation of territories by Russian\narmed forces has also led to changes in the type of education provided."},{"id":"a-hrc-52-crp-4-p0802","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"802","seq":804,"section":"4. Right to education","text":"The right to education is universal.500 International human rights law provides that\neducation shall be directed to, among other things, the full development of the human\npersonality and the sense of its dignity, and shall strengthen the respect for human rights and\nfundamental freedoms.501 It also states that education shall be directed to the development of\nrespect for the child’s parents, his or her own cultural identity, language and values, for the\nnational values of the country in which the child is living, the country from which he or she\nmay originate, and for civilisations different from his or her own. 502"},{"id":"a-hrc-52-crp-4-p0803","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"803","seq":805,"section":"4. Right to education","text":"The current armed conflict has led to the damage and destruction of over 3000\neducational institutions.503 Through witness accounts and reviews of photographs and video\nfootage, the Commission has examined reports regarding the damage or destruction of 30\ninstitutions and has inspected five of them in person. Several of the schools it visited had\nbeen completely destroyed."},{"id":"a-hrc-52-crp-4-p0804","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"804","seq":806,"section":"4. Right to education","text":"Because of the damage to and destruction of schools, the lack of electricity, heating\nand sometimes water in schools as a consequence of the armed conflict, the lack of\nappropriate bomb shelters, as well as dangers related to fighting and the presence of mines\nand unexploded ordnance, a significant number of children had to enrol in online education\n(see para. 277). As of November 2022, almost half of operational schools in Ukraine were\nfunctioning online, while a third was operating in a hybrid online/in-person regime, according\nto the Ukrainian Ministry of Education and Science.504"},{"id":"a-hrc-52-crp-4-p0805","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"805","seq":807,"section":"4. Right to education","text":"A key problem was the frequent need, at times for prolonged periods, to go to shelters\nor basements, which disrupted the conduct of classes. While out of 95 per cent of the\neducational institutions checked by the Ministry of Education and Science in December 2022,\n68 per cent had approved shelters, 56 per cent of schools did not have the capacity to deliver\nlessons in-person inside the shelters.505 A 17-year-old girl who wrote to the Commission said\n“as soon as there’s an air raid warning the studying process stops and everybody goes to the\nshelter. Sometimes you can sit the half of the school day in the shelter.”506"},{"id":"a-hrc-52-crp-4-p0806","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"806","seq":808,"section":"4. Right to education","text":"As outlined above, the armed conflict in Ukraine has resulted in a massive\ndisplacement of populations, both across the borders and within Ukraine. Refugees and\ninternally displaced persons include primarily children, women, and older persons. Large\nnumbers of students and educators are among the displaced persons and this has had a\nsignificant impact on education service delivery.507 While authorities and educators have\nmade efforts to adapt and continue with the education process during the armed conflict, it\nhas not been a full-fledged substitute for in-person education. The armed conflict has also\naffected online education. In a survey by the Office of the Education Ombudsman of Ukraine,\nparents invoked that in some areas, distance learning was organized partially or only for a\ncertain period of time – this was mainly the case for Donetsk, Dnipropetrovsk, Kharkiv and\nLuhansk regions – or was not organized at all. Online education was particularly challenging\nin Russian-occupied territories, where access to the internet was poor and many Ukrainian\nsites were blocked. Witnesses from those territories said that students faced the challenge of\nfinding locations that were both safe and with connectivity, to be able to submit their\nhomework. A 19-year-old student from occupied Nova Kakhovka city, in Kherson region,\ntold the Commission how she had to go outside and sit by a certain window to find\nconnectivity and send her exams from there."},{"id":"a-hrc-52-crp-4-p0807","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"807","seq":809,"section":"4. Right to education","text":"Parents also identified poor or no access to the internet and challenges related to the\nlack of devices508 as the main problem hampering children’s education.509 In some places,\nduring a power outage, there was no mobile internet and network connection, so the\neducational process was interrupted. Systematic attacks on the country’s energy\ninfrastructure compounded the challenges of organizing education remotely. A 17-year-old\nboy from Kharkiv region wrote to the Commission: “now due to attacks at power plants,\nelectricity is not always working, so Ukrainian children cannot even study online like it was\nbefore”.510"},{"id":"a-hrc-52-crp-4-p0808","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"808","seq":810,"section":"4. Right to education","text":"In the survey of the Office of the Education Ombudsperson of Ukraine, parents\nidentified the children’s emotional or psychological state as a main factor preventing them\nfrom studying. According to a mother interviewed by the Commission, her children had\npractically lost one year of schooling due to the electricity cuts, the need to stay in basements\nand due to displacements, and that after the children settled in Georgia, they found it very\ndifficult to concentrate and follow classes offline. Lack of socialization also has a toll on\nchildren´s well-being. An education assessment in Kharkiv region found that most teenagers\nwere fully dependent on their smartphones for learning and social communication, and due\nto the insecurity, many children had stayed indoors for almost the entire year. 511"},{"id":"a-hrc-52-crp-4-p0809","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"809","seq":811,"section":"4. Right to education","text":"The armed conflict has not only had an impact on access to education. The\nCommission documented instances in which Russian authorities used coercion against school\npersonnel to force them to apply Russian curricula, and against parents, to force them to enrol\ntheir children in schools operating under the Russian education system (see paras. 700-708).\nThis has affected children’s right to education, and notably the type of education available. 512"},{"id":"a-hrc-52-crp-4-p0810","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"810","seq":812,"section":"5. Right to adequate housing","text":"The armed conflict has affected civilians’ right to an adequate standard of living,\nincluding adequate housing. The use of explosive weapons with wide-area effects has\ndamaged or destroyed thousands of residential buildings across the country, particularly in\nareas close to the front line. This has had a worrisome toll on civilians, and in particular on\nthe most vulnerable groups."},{"id":"a-hrc-52-crp-4-p0811","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"811","seq":813,"section":"5. Right to adequate housing","text":"International human rights law recognises the right to an adequate standard of living,\nincluding adequate housing.513"},{"id":"a-hrc-52-crp-4-p0812","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"812","seq":814,"section":"5. Right to adequate housing","text":"The Commission has observed first-hand damage and destruction of houses and\nbuildings, as well as of schools and hospitals in most of the areas it visited. It has been\nconcerned by the level of destruction in several Ukrainian cities, including Chernihiv, Izium,\nKharkiv, and Mariupol. In many instances, buildings have been damaged beyond repair. In\nother cases, people had no other place to live than in partially demolished homes, despite\nfreezing temperatures. Entire sections or walls of apartment buildings have collapsed or\ndisappeared, which endangered their internal structure. Humanitarian organizations launched\nprogrammes to provide people with warm, safe and dignified living conditions. 514 However,\nmany persons, especially residents of small villages close to fighting or directly on frontlines,\ndid not have access to this type of support. Fighting has also been the most intense in the\nregions with the lowest temperatures.515"},{"id":"a-hrc-52-crp-4-p0813","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"813","seq":815,"section":"5. Right to adequate housing","text":"Civilians’ right to adequate housing has also been affected by the systematic attacks\non Ukraine’s energy-related infrastructure (see paras. 275-278). The attacks have put the\nUkrainian energy system under considerable pressure just as winter was setting in. They\ncaused disruptions not only impacting the electricity supply for the population, but also water,\nheating, sanitation, and telecommunication."},{"id":"a-hrc-52-crp-4-p0814","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"814","seq":816,"section":"6. Right to food and water","text":"The armed conflict has significantly compromised civilians’ access to food and water.\nThis has been particularly the case in areas affected by heavy fighting or under siege. Fighting\nor attacks led to damage of critical installation providing water and electricity, and civilians\ntook considerable risks while attempting to find basic supplies."},{"id":"a-hrc-52-crp-4-p0815","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"815","seq":817,"section":"6. Right to food and water","text":"International human rights law recognises the right to an adequate standard of living,\nincluding adequate food.516 Adequacy will differ for infants, children, adults and older\npersons.517 In the same vein, everyone has a right to water.518"},{"id":"a-hrc-52-crp-4-p0816","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"816","seq":818,"section":"6. Right to food and water","text":"According to the United Nations Office for Coordination of Humanitarian Affairs,\n11.1 million persons in Ukraine were in need of food assistance as at the end of 2022. 519\nIntense fighting in many areas meant that people were unable to look for food and water. For\ninstance, in Hostomel city, a few days after the outset of the armed conflict, there was already\nno electricity, limited water and gas, and people were struggling to find food. A resident of\nMariupol told the Commission that starting early March 2022, there was first no electricity,\nthen no water, and finally no gas and heating. She was cooking over a small stove in the yard.\nAirstrikes had also started in early March 2022. Another resident from Mariupol recounted\nthat together with his family, he spent nearly a month without most essential necessities,\nincluding water, electricity, heating, and communications. They cooked in the courtyard on\na grill, with a fire, and gathered water from open sources outside. One woman in Izium,\nKharkiv region, reported to the Commission that she did not eat for two days after shelling\nstruck her building, cutting it off from water, electricity and gas during intensive fighting in\nher area."},{"id":"a-hrc-52-crp-4-p0817","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"817","seq":819,"section":"6. Right to food and water","text":"Getting water was sometimes challenging. Residents from Kupiansk city, Kharkiv\nregion, and Mariupol city, Donetsk region, explained that they had to collect and boil water\nfrom rain or wells. Several people indicated that for some time, they only had access to non-\npotable water, which led to health issues."},{"id":"a-hrc-52-crp-4-p0818","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"818","seq":820,"section":"6. Right to food and water","text":"Civilians’ rights to food and water were particularly affected in towns and cities that\ncame under siege by Russian armed forces. Many people in these cities recounted the scarcity\nof food, especially when their ability to move was limited."},{"id":"a-hrc-52-crp-4-p0819","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"819","seq":821,"section":"6. Right to food and water","text":"Despite ongoing attack and considerable risks, civilians eventually had to leave their\nshelters to look for food and water. A woman farmer in Mala Rohan village, Kharkiv region,\nrecounted how she, at considerable risk because of ongoing shelling, distributed bread and\nmilk from her farm to older persons in the village because of the shortages. While she was\nnot injured, in several cases documented by the Commission, civilians were killed or injured\nbecause they went to search for food."},{"id":"a-hrc-52-crp-4-p0820","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"820","seq":822,"section":"6. Right to food and water","text":"Detained civilians and Ukrainian prisoners of war consistently described that they\nwere not provided adequate food and water during their detention, and that those who were\nsubject to prolonged detention often lost significant weight."},{"id":"a-hrc-52-crp-4-p0821","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"821","seq":823,"section":"6. Right to food and water","text":"In some places, restrictions imposed by Russian authorities seemed to aggravate the\nscarcity of food. Residents in Kharkiv and Kherson regions told the Commission that once\nRussian armed forces had occupied an area, they did not allow humanitarian aid from\nUkrainian controlled territory to enter or they controlled who received aid. Witnesses said\nthat humanitarian aid in territories controlled by Russian armed forces was scarce, of low\nquality, and sometimes subject to conditions, especially with the referendums approaching."},{"id":"a-hrc-52-crp-4-p0822","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"822","seq":824,"section":"6. Right to food and water","text":"For example, in Nova Kakhova city, Kherson region, it was reported that an official\nwas arrested in August 2022 and detained for almost two months because she had refused to\ncollaborate with the occupying authorities and was bringing humanitarian aid from\nUkrainian-controlled territory. Russian authorities reportedly insisted that only Russian-\nprovided aid should be distributed and that residents should refuse Ukrainian humanitarian\naid."},{"id":"a-hrc-52-crp-4-p0823","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"823","seq":825,"section":"7. Impact of the armed conflict on vulnerable groups","text":"While the current armed conflict is affecting the entire population in Ukraine, some\nindividuals have been more vulnerable than others. This includes older persons, persons with\ndisabilities, members of the LGBTI community, and persons belonging to a minority group.\nSome individuals present intersectional vulnerabilities, which puts them at even greater risk.\nPersons residing in social protection and education institutions may also be in a particularly\nvulnerable situation. The specific problems faced by persons belonging to these groups are\noften not visible, and therefore not addressed. This increases their vulnerability and affects\nthe full realization of their human rights.\na)    Older persons"},{"id":"a-hrc-52-crp-4-p0824","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"824","seq":826,"section":"7. Impact of the armed conflict on vulnerable groups","text":"Older persons have been particularly affected by the armed conflict. Many older\npersons living near or on frontlines, have been unable or unwilling to evacuate to safety and\nbecame trapped in the conflict zone.520 It is estimated that about 25 per cent of the population\nin Ukraine is older than 60 years. In the Donetsk and Luhansk regions alone, this proportion\nis estimated at 30 per cent. In June 2022, OHCHR, the United Nations Population Fund, the\nWorld Health Organization Regional Office for Europe and HelpAge International signed a\njoint statement highlighting the challenges faced by older persons related to health, housing,\nand financial and economic needs. The statement underlined that 60 per cent of older persons\nwho have been affected by the armed conflict are women.521"},{"id":"a-hrc-52-crp-4-p0825","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"825","seq":827,"section":"7. Impact of the armed conflict on vulnerable groups","text":"In smaller towns and villages, older persons told the Commission that they sheltered\nfrom explosive weapons in small cellars, usually used for food storage and often located\noutside the main dwelling, which exposed them to particular risks and hardship. One 62-year-\nold woman in Sumy region was injured in an explosion while running to her cellar – her\nhusband and an older couple staying with them were killed. A 75-year-old woman told the\nCommission that she spent 83 days taking cover in a small cellar, with her son and her three-\nyear-old grandson."},{"id":"a-hrc-52-crp-4-p0826","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"826","seq":828,"section":"7. Impact of the armed conflict on vulnerable groups","text":"Often dependent on distribution of aid or pensions, which required them to stand in\nqueue in the street, older persons were sometimes more vulnerable to the impact of attacks\nwith explosive weapons. In two cases documented by the Commission, older persons were\ndisproportionately represented among those killed and injured because they were standing in\nline outside when the attacks happened. This was the case of the 17 March 2022 attack in\nChernihiv city and the 16 July 2022 cluster munition attack in Izium city (see paras. 215-221\nand 255). The Commission received reports that in Russian-occupied territories, pensioners\nfelt compelled to apply for a Russian passport in order to receive social benefits. The\ndependence of older persons on pensions also played a role in their participation in the so-\ncalled referendums organized in temporarily occupied territories in September 2022 (see\npara. 690)\nb)    Persons with disabilities"},{"id":"a-hrc-52-crp-4-p0827","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"827","seq":829,"section":"7. Impact of the armed conflict on vulnerable groups","text":"Children and adults with disabilities have faced a disproportionate risk of death or\ninjuries in the armed conflict in Ukraine. Persons with a disability and those caring for them\nhave encountered considerable difficulties in seeking safety or fleeing from the hostilities, or\nthey have been unable to do so. Women and girls with disabilities, particularly women with\nintellectual and psychosocial disabilities, are facing a higher risk of sexual and gender-based\nviolence, and trafficking during armed conflict.522"},{"id":"a-hrc-52-crp-4-p0828","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"828","seq":830,"section":"7. Impact of the armed conflict on vulnerable groups","text":"Ratified by both the Russian Federation and Ukraine, the Convention on the Rights of\nPersons with Disabilities requires States to take all necessary measures to ensure the\nprotection and safety of persons with disabilities in situations of risk, including armed conflict\nand humanitarian emergencies.523 United Nations Security Council Resolution 2475(2019),\naddressing the disproportionate impact of armed conflict and related humanitarian crises on\npersons with disabilities, calls upon Member States and parties to armed conflict to, among\nother things, protect persons with disabilities and to ensure they have access to justice and\nbasic services on an equal basis with others.524"},{"id":"a-hrc-52-crp-4-p0829","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"829","seq":831,"section":"7. Impact of the armed conflict on vulnerable groups","text":"In mid-April 2022, the Committee on the Rights of Persons with Disabilities estimated\nthe number of persons with disabilities potentially affected by the armed conflict in Ukraine\nto be 2.7 million.525 In a special report released in September 2022,526 the same Committee\nexpressed its concerns related to the disproportionate risk of death or injury to which persons\nwith disabilities are exposed, as a result of indiscriminate attacks against the civilian\npopulation, the lack of involvement and meaningful participation of persons with disabilities\nin emergency preparedness and response, including in setting priorities for evacuation\nstrategies and aid distribution, or the lack of accessibility of information and alert\nmechanisms in evacuation procedures. It also expressed its grave concerns about the situation\n521OHCHR, United Nations Population Fund (UNFPA), World Health Organization Regional Office for\nEurope and HelpAge International. “Joint statement on the situation of older persons in Ukraine”, 14\nJune 2022.\nof persons with disabilities in areas under the control of the Russian Federation. The\nCommittee addressed the specific situation of children with disabilities in the same report. In\naddition, on 7 October 2022 together with the Committee on the Rights of the Child, it issued\na joint statement calling for urgent action to protect Ukrainian children with disabilities in\nresidential care institutions.527"},{"id":"a-hrc-52-crp-4-p0830","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"830","seq":832,"section":"7. Impact of the armed conflict on vulnerable groups","text":"Many persons living with disabilities are bedridden and most often unable to seek\nshelter during attacks.528 For instance, in Izium city, an older woman who was bedridden and\ncould not go to the shelter in the basement remained in her apartment on the third floor. The\nbuilding was destroyed in an airstrike and the woman was never found."},{"id":"a-hrc-52-crp-4-p0831","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"831","seq":833,"section":"7. Impact of the armed conflict on vulnerable groups","text":"Caregivers, mostly women, are often put in a very difficult situation where they have\nto choose between fleeing to safety or staying to care for their loved ones.529 In Mariupol\ncity, a woman became exposed to airstrikes because she had to help her 71-year-old uncle\nwho had a disability and was unable to leave his apartment. One man who was living with\nhis chronically ill mother in Mariupol city explained how he could not leave the city because\nof her.\nc)     Persons belonging to the LGBTI community"},{"id":"a-hrc-52-crp-4-p0832","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"832","seq":834,"section":"7. Impact of the armed conflict on vulnerable groups","text":"The armed conflict has also had a serious impact on the rights of persons belonging\nto the LGBTI community, who have notably been victims of discrimination. It has been\nreported that members of this community have lived in fear in territories under Russian\nFederation control because of the extreme views prevailing in the Russian Federation on\nLGBTI questions.530 On a positive note, in December 2022, several provisions prohibiting\ndiscrimination or harassment against individuals and groups of persons on the basis of,\namong other things, sexual orientation, have been introduced in the Ukrainian Media Law.531"},{"id":"a-hrc-52-crp-4-p0833","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"833","seq":835,"section":"7. Impact of the armed conflict on vulnerable groups","text":"The Commission has been informed of instances in which persons from the LGBTI\ncommunity have been discriminated against in collective displacement centres. As a\nconsequence, civil society organizations have organized private shelters for LGBTI displaced\npersons and their family members. At the beginning of the armed conflict, reports emerged\nthat transgender women were being turned back at the Ukrainian border when the gender on\ntheir identification documents did not match their actual gender or because Ukrainian border\nguards refused to let transgender women leave the country, despite identification documents\nstating they were women. Several feminist organizations have therefore engaged in the\nevacuation of transgender persons from Ukraine, particularly at the beginning of the\nconflict.532 Because of lack of access to hormone medicines, some internally displaced or\nrefugee transgender persons have had to pause their treatment, or had to ‘cook’ their own\nhormones with the inherent risks that this represents, leading some organizations to set up\nnetworks to find and distribute hormones and to support LGBTI refugees’ access to health\ncare and medicine.\nd)     Persons belonging to minorities"},{"id":"a-hrc-52-crp-4-p0834","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"834","seq":836,"section":"7. Impact of the armed conflict on vulnerable groups","text":"The situation of the Crimean Tatar community remains of serious concern. Since the\noccupation of Crimea by the Russian Federation in 2014, a range of human rights violations\ntargeted Crimean Tatars (see para. 58). For instance, since 2014 over 230 persons have\nreportedly been prosecuted in Crimea for violations of public order during mass gatherings;\n85 per cent of them are Crimean Tatars. In addition, since 24 February 2022, allegations of\ndetentions, abusive use of the law process against Crimean Tatar persons, including for\nopposing the Russian invasion, as well as of forced conscription, have emerged. The\nOrganization for Security and Co-operation in Europe has noted that several Crimean Tatar\nactivists have been arrested on dubious grounds, such as high treason or financial support of\nterrorism.533 According to OHCHR, Crimean Tatars have been disproportionately targeted\nby the police and under terrorist proceedings, which often fell short of human rights\nstandards.534 It reported that a school administration in Crimea refused to prolong a contract\nwith a female Crimean Tatar teacher following complaints by students’ parents, as she had\ndiscussed with her students alleged violations against civilians by the Russian armed forces\nin Ukraine. She was convicted for “discrediting the Russian Federation Armed Forces”,\nwhich was upheld by the Supreme Court of Crimea on 10 August 2022. She was fined 30,000\nRussian roubles and forced to seek employment in a different region. 535 Another example is\nthe case of Dzhemil Hafarov, who had been reportedly detained for several years and\nsentenced by a Russian court, in January 2023, to 13 years of imprisonment, despite very\npoor health. He died a few weeks later.536"},{"id":"a-hrc-52-crp-4-p0835","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"835","seq":837,"section":"A. Introduction and overview","text":"According to the Commission’s mandate, it shall “make recommendations, in\nparticular on accountability measures, all with a view to ending impunity and ensuring\naccountability, including, as appropriate, individual criminal responsibility, and access to\njustice for victims”.537"},{"id":"a-hrc-52-crp-4-p0836","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"836","seq":838,"section":"A. Introduction and overview","text":"“Accountability measures” is a broad term which can be interpreted in several ways.\nThe Commission’s main focus will be on three aspects: general recommendations with a\nview to criminal responsibility; specific recommendations individualising persons or entities\nthat appear to have committed criminal offences; and non-judicial accountability, including\nthe right to truth, reparation, and guarantees of non-recurrence."},{"id":"a-hrc-52-crp-4-p0837","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"837","seq":839,"section":"A. Introduction and overview","text":"Part I of this chapter covers investigatory mechanisms and criminal accountability\nmeasures. As described previously in this report, the Commission has found numerous\nviolations of international human rights and of international humanitarian law, as well as\nrelated crimes. The Commission will first consider existing and possible national measures\nin Ukraine (see B and C) as well as in other States investigating the violations (see D). Then\nfollows an overview of existing investigatory and criminal accountability alternatives at the\ninternational level (see E) before some issues of coordination between national and\ninternational measures (see F). Finally, the Commission considers proposed international\naccountability measures (see G)."},{"id":"a-hrc-52-crp-4-p0838","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"838","seq":840,"section":"A. Introduction and overview","text":"The purpose of part I of this chapter is twofold. First, to take stock and describe the\nexisting and proposed main accountability measures, as well as efforts to coordinate them to\nminimize both re-traumatisation of victims and unnecessary duplication of similar measures.\nSecond, to develop a basis for the Commission’s assessments."},{"id":"a-hrc-52-crp-4-p0839","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"839","seq":841,"section":"A. Introduction and overview","text":"In part II of this chapter, the Commission will consider non-judicial measures of\naccountability. Throughout its work, the Commission has consistently emphasized its victim-\ncentred approach, including the needs of the various groups of victims, integrating a gender\nperspective, the importance of accountability, as well as of measures of recognition,\nreparation, rehabilitation, reconstruction and guarantees of non-repetition. The\nCommission’s mandate explicitly refers to “access to justice for victims” when considering\nrecommendations on accountability. After an introduction (see H), discussions of reparations\nand truth follow (see I and J). Part II also contains the Commission’s assessments with respect\nto non-judicial accountability measures."},{"id":"a-hrc-52-crp-4-p0840","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"840","seq":842,"section":"A. Introduction and overview","text":"It follows from the above overview that this chapter is limited to accountability\nmeasures indicated in the Commission’s mandate. Many international organizations and\nmechanisms (courts, ombudspersons, committees, rapporteurs etc.) focus on state\nresponsibility. Their work, which is very important and supplements individual\naccountability, will not be described in this chapter. It is noted that such work is directly\nrelevant in order to reduce, avoid or remedy violations and abuses in connection with the\narmed conflict in Ukraine. Illustrations from the UN system are, for instance, the committees\noperating under the International Covenant on Civil and Political Rights, the Convention on\nthe Elimination of All Forms of Discrimination against Women, the Convention against\nTorture and Other Cruel, Inhuman or Degrading Treatment or Punishment, and the\nConvention on the Rights of the Child. Accountability measures also depend on the\ncontributions and efforts of civil society organizations that collect, preserve and present\nevidence to relevant mechanisms."},{"id":"a-hrc-52-crp-4-p0841","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"841","seq":843,"section":"A. Introduction and overview","text":"Furthermore, the European Court of Human Rights is considering a large number of\nindividual applications by victims in Ukraine, submitted both between 2014 and late\nFebruary 2022, and subsequently. It is also seized with five inter-state cases of relevance to\nthe armed conflict, of which four are between Ukraine and the Russian Federation.538 Another\nillustration is the case instituted by Ukraine against the Russian Federation before the\nInternational Court of Justice (ICJ) relating to the Genocide Convention of 1948, where the\nICJ ordered the Russian Federation to suspend its military operations.539\nPart I. Investigatory Mechanisms and Criminal Accountability Measures"},{"id":"a-hrc-52-crp-4-p0842","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"842","seq":844,"section":"B. Existing Ukrainian criminal accountability measures","text":"The main prosecution body in Ukraine is the Office of the Prosecutor General,\npursuant to, among others, article 131-1 of the Constitution of Ukraine.540 Since 1991, the\nOffice of the Prosecutor General has undergone several developments and reforms, including\nits constitutionally granted powers and organizational structure. As part of reforms in 2019,\nthe total number of prosecutors in Ukraine was planned to be reduced to less than 10,000,\nwhich was more in line with the per capita average of prosecutors in other European states. 541\nWithin the Office of the Prosecutor General is a central war crimes unit, as well as regional\nwar crimes units, that focus on investigating crimes related to the ongoing armed conflict. 542\nIn October 2022, the Ukrainian Prosecutor General stated that they are prioritizing “effective\ninvestigation and prosecution of war crimes, cases of treason and acts of collaboration”. A\nspecialized unit has also been established to deal with conflict-related sexual violence\ncrimes.543"},{"id":"a-hrc-52-crp-4-p0843","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"843","seq":845,"section":"B. Existing Ukrainian criminal accountability measures","text":"Two of the main Ukrainian authorities involved in investigating the conflict-related\ncrimes are the Security Service of Ukraine and the State Bureau of Investigation. The\nSecurity Service of Ukraine has the main responsibility for investigating war crimes. 544 The\nState Bureau of Investigation assists at the request of the Office of the Prosecutor General.\nThe two authorities collaborate on investigative activities. Generally, the State Bureau of\nInvestigation investigates allegations against, among others, senior Ukrainian officials and\nUkrainian military personnel. However, since 2014, the State Bureau of Investigation has\nbeen working on war crimes investigations."},{"id":"a-hrc-52-crp-4-p0844","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"844","seq":846,"section":"B. Existing Ukrainian criminal accountability measures","text":"One of the main challenges for the Office of the Prosecutor General is addressing the\nlarge number of registered cases relating to the armed conflict. As of 10 February 2023, the\nOffice of the Prosecutor General reported that it had registered 68,893 crimes of aggression\nand war crimes, pursuant to, among others, articles 436, 437 and 438 of the Criminal Code\nof Ukraine.545 For any prosecution office anywhere in the world, this number of registered\ncrimes would be a challenge to investigate and, if sufficient evidence exists, to prepare cases\nfor trial and subsequent legal proceedings. The crimes related to the armed conflict are in\naddition to the usual workload of domestic crimes that a public prosecution service would\nneed to handle."},{"id":"a-hrc-52-crp-4-p0845","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"845","seq":847,"section":"B. Existing Ukrainian criminal accountability measures","text":"Flowing from the above challenge is the need for enough prosecutors experienced or\ntrained in investigating international humanitarian law and international criminal law cases.\nGiven the specialized nature of the applicable legal provisions, training would not be limited\nto substantive law but likely include techniques on building cases concerning large, complex\ncrime bases, methods of organizing and assessing volumes of evidence, and means of\nobtaining evidence to connect suspects to crime bases. Further, as discussed below in the\nCommission’s assessment, there is a need for the articulation of a prosecutorial prioritization\nstrategy."},{"id":"a-hrc-52-crp-4-p0846","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"846","seq":848,"section":"B. Existing Ukrainian criminal accountability measures","text":"The Office of the Prosecutor General cooperates with Ukrainian agencies as well as\nnational bodies from other States and international bodies, such as the Office of the\nProsecutor at the International Criminal Court. Such collaboration aids in, among other\nthings, addressing the need to develop and enhance expertise within Ukraine, as well as\nproviding resources such as forensic investigative resources and information technology\ntools."},{"id":"a-hrc-52-crp-4-p0847","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"847","seq":849,"section":"B. Existing Ukrainian criminal accountability measures","text":"The challenges for the Security Service of Ukraine and the State Bureau of\nInvestigation are similar to those of the Office of the Prosecutor General, namely that the vast\nnumber of allegations and registered cases require sufficient personnel and resources.\nHowever, the authorities have been developing and strengthening their expertise since 2014\nregarding investigating crimes related to armed conflict. The authorities have also engaged\nwith experts from other States who have assisted with training and conducting specific\ninvestigations."},{"id":"a-hrc-52-crp-4-p0848","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"848","seq":850,"section":"B. Existing Ukrainian criminal accountability measures","text":"The Commission’s assessment: The Commission notes that the Office of the\nProsecutor General is pursuing justice in circumstances that would be challenging for any\npublic prosecution office. The sheer number of registered crimes calls for a comprehensive\ninvestigative and prosecutorial prioritization strategy that is feasible for the current situation\nand adaptable for the changing environment of the armed conflict. Such a strategy would\nneed to factor, among other things, division of labour and workflows among the Office of the\n542 Office of the Prosecutor General of Ukraine, “History of the prosecutor’s office” (available only in\nUkrainian); Office of the Prosecutor General of Ukraine, “Strategy for the development of the\nprosecutor’s office for 2021-2023” (available only in Ukrainian).\n543 International Bar Association, “The IBA interview: Andriy Kostin, Prosecutor General of Ukraine”,\n4 October 2022.\n544 Security Service of Ukraine, “Pre-trial investigation”\n545 Ukraine, Criminal Code of Ukraine, No. 2341-III, 5 April 2001; Office of the Prosecutor General of\nUkraine, “Crimes committed during full-scale invasion of the Russian Federation.(date accessed:10\nFebruary 2023)\nProsecutor General central and regional offices, and ways to filter and prioritize the cases.\nThe Commission understands that the Office of the Prosecutor General has been developing\nsuch a strategy and appreciates that certain aspects of it may need to remain confidential.\nThis said, the Commission encourages the Office of the Prosecutor General to publish its\nstrategy, at least those parts that are not confidential, in order to enhance facilitation of\nnational and international support for Ukraine’s investigations, as well as ensuring\ntransparency.546 Further, the Office of the Prosecutor General is encouraged to continue\nconsidering and implementing reforms to its office and practices (see para. 841) in order to\nenhance the rule of law."},{"id":"a-hrc-52-crp-4-p0849","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"849","seq":851,"section":"B. Existing Ukrainian criminal accountability measures","text":"While the Commission appreciates the Office of the Prosecutor General’s essential\nrole in pursuing the rule of law in Ukraine, it invites the Office of the Prosecutor General to\nenhance transparency about investigations into allegations of war crimes committed by\nUkrainian forces. For example, the Office of the Prosecutor General publishes updates about\nthe number of registered crimes under article 438 of the Criminal Code of Ukraine (violations\nof rules of the warfare), which stood at 66,845 as of 10 February 2023.547 In either a similar\nor different format, the Office of the Prosecutor General could provide timely and thorough\nupdates about its investigations into allegations pertaining to Ukrainian forces. Such\ntransparency and demonstrated willingness to apply the rule of law equally will only\nstrengthen the credibility of the Office of the Prosecutor General and engender further\nsupport for its investigations."},{"id":"a-hrc-52-crp-4-p0850","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"850","seq":852,"section":"B. Existing Ukrainian criminal accountability measures","text":"The Commission encourages the Office of the Prosecutor General to build-upon and\nenhance its victim-centred approach. The Commission understands that the Office of the\nProsecutor General is emphasizing the importance of such an approach in its specialized\nconflict-related sexual violence unit. This is highly commendable and such an approach\nshould be prominent in other areas of the Office of the Prosecutor General’s work. Elements\nof a victim-centred approach that can be operationalized or further enhanced include (i)\npractices and procedures to diminish retraumatizing victims, such as minimizing the number\nof victim interviews, and promoting the use of audio or video-recorded interviews or written\nsigned statements, as opposed to new oral testimonies each time; (ii) psychological, social\nand medical support for victims during and after legal processes; and (iii) keeping the victims\ninformed about the status and progress of the legal processes."},{"id":"a-hrc-52-crp-4-p0851","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"851","seq":853,"section":"B. Existing Ukrainian criminal accountability measures","text":"International partners and donors are to be commended for their support to the Office\nof the Prosecutor General, the Security Service of Ukraine and SBI. Moving forward, the\nfocus should be on updating the respective needs assessment for the Office of the Prosecutor\nGeneral and the investigative bodies and providing them with the requisite assistance. One\narea that appears to require particular attention is ensuring adequate support for forensic\ninvestigation capabilities. Other important aspects are coordination (see F below) and the\nprosecutorial prioritization strategy (see para. 847). International partners and donors should\nalso consider support that applies to justice needs that include, as well as go beyond, those\nrelated to the armed conflict. For example, support for victims (such as those mentioned in\npara. 849) and assistance in victim participation in judicial procedures.\nUkrainian judicial authorities"},{"id":"a-hrc-52-crp-4-p0852","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"852","seq":854,"section":"B. Existing Ukrainian criminal accountability measures","text":"The judicial system of Ukraine has undergone significant changes since Ukraine\ngained independence in 1991, including the reform of the judicial system in the Constitution\nof 1996.548 The structure also follows from the Law of Ukraine on the Judiciary and the Status\nof Judges. The Supreme Court is the highest court, with a separate Constitutional Court to\nresolve issues of compliance of the laws with the Constitution and to provide interpretation\nof the Constitution.549 Criminal cases related to the armed conflict will generally proceed by\nway of trial at a first instance court, then potential appeal to a Court of Appeal and finally\npossibly an appeal to the Supreme Court. In terms of ongoing reforms, the Ukrainian legal\nsystem overall is continuing to undertake such initiatives, including measures against\ncorruption, and they are supported by international partners, such as the European Union. 550"},{"id":"a-hrc-52-crp-4-p0853","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"853","seq":855,"section":"B. Existing Ukrainian criminal accountability measures","text":"The Commission is aware of various forms of criticism of the Ukrainian legal system\nin general and the judiciary specifically.551 For example, in November 2021, the United\nNations Human Rights Committee remained concerned about, among other things, the “lack\nof measures to fully ensure the independence of judges and prosecutors”, and the “challenges\nfaced during the qualification assessment of judges, including the lack of a transparent\nevaluation procedure, allegations of corruption in the assessment process and the resignation\nof a high number of judges during the qualification assessment process”. 552 It is important\nthat the abovementioned reform processes continue in order to reduce and eliminate such\ndeficiencies."},{"id":"a-hrc-52-crp-4-p0854","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"854","seq":856,"section":"B. Existing Ukrainian criminal accountability measures","text":"One of the main challenges for the judiciary is the expected influx of cases regarding\ncrimes related to the armed conflict. As of 23 February 2023, 26 individuals with the Russian\narmed forces had reportedly been convicted of such crimes, either while in custody or in\nabsentia.553 Based upon the Office of the Prosecutor General’s figures, it is expected that a\nsignificant number of cases will eventually make their way through the court system.\nThis development will be even more challenging in the context of the current number of\njudicial vacancies. While the Ukrainian authorities have improved in filling such vacancies\nbetween 2021 and 2022, there are still many to be filled, especially in the appellate courts. 554\nAdditionally, some of the court buildings and infrastructure have suffered damages due to\nthe ongoing armed conflict.555"},{"id":"a-hrc-52-crp-4-p0855","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"855","seq":857,"section":"B. Existing Ukrainian criminal accountability measures","text":"Another challenge is the applicable laws, in at least two perspectives. First, training is\nneeded for some members of the judiciary regarding international humanitarian law and\ninternational criminal law, including those filling vacant judicial posts. The judiciary is being\ncalled upon to apply competencies that were not needed during peacetime. The Commission\nunderstands that training programs have occurred and plan to be enhanced. 556 Second, there\nis a need to re-examine existing legislation or develop new legislation to address issues\nrelating to the investigation of conflict-related crimes and to ensure harmonization with\ninternational standards where it is not in conformity. For example, Ukrainian laws may need\nto be amended to better facilitate the use of evidence collected by experts sent from other\nStates, as well as that collected by international bodies. As another example, article 111-1 of\n549 Ukraine, Constitution of Ukraine, 28 June 1996, for example, articles 124-130 (Supreme Court),\n147-153 (Constitutional Court); Ukraine, Law of Ukraine on the Judiciary and the Status of Judges,\n23 December 2022.\n550 For example, European union Advisory Mission, “War against corruption is a priority on Ukraine’s\nway to EU membership”, 5 July 2022.\n551 See for instance Council of Europe, Group of States against Corruption (GRECO), Fourth\nEvaluation Round – Corruption prevention in respect of members of parliament, judges and\nprosecutors, Interim compliance report – Ukraine, GrecoRC4(2023)2, 24 March 2023, paras. 163-\n164; CCPR/C/UKR/CO/8, paras. 43-44; European Court of Auditors, Reducing grand corruption in\nUkraine: several EU initiatives, but still insufficient results, 23 September 2021, for example, paras.\n50-69.\n552 CCPR/C/UKR/CO/8, para. 43(a), (c).\n553 Léonie Chao-Fong., “Russia-Ukraine war at a glance: what we know on day 365 of the invasion”,\nThe Guardian, 23 February 2023.\n554 High Qualification Commission of Judges of Ukraine, Regarding the report of the High\nQualification Commission of Judges of Ukraine for 2022, 19 January 2023; High Qualification\nCommission of Judges of Ukraine, Regarding the report of the High Qualification Commission of\nJudges of Ukraine for 2021, 19 January 2022.\n555 William D. Meyer, Under Assault: A Status Report on the Ukrainian Justice System in Wartime,\n(Stockholm, International Legal Assistance Consortium, 2022), for example Annexes 1-2; ILAC, The\nUkrainian Justice System in Wartime – Areas liberated form Russian control or remaining under\noccupation, December 2022, for example p. 16 (Conclusions).\n556 Supreme Court of Ukraine, “SC Judges met with representatives of the UN Independent\nInternational Commission of Inquiry on Ukraine”, 1 December 2022.\nthe Criminal Code of Ukraine on “collaborative activity” warrants clarification, especially its\ndefinition, to avoid legal uncertainty and being overly broad."},{"id":"a-hrc-52-crp-4-p0856","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"856","seq":858,"section":"B. Existing Ukrainian criminal accountability measures","text":"The Commission’s assessment: The reform of the general deficiencies of the judicial\nsystem should continue (see paras. 851852). The Commission commends and encourages the\ninternational community to further support these efforts. Further, the Ukrainian authorities\nare encouraged to ensure that legislation related to conflict-related crimes are harmonized\nwith international standards where it is not already in conformity."},{"id":"a-hrc-52-crp-4-p0857","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"857","seq":859,"section":"B. Existing Ukrainian criminal accountability measures","text":"The Ukrainian judiciary plays a pivotal role in ensuring accountability and protecting\nrights, including the rights of the accused. In the context of the significant harms that the\nUkrainian people have suffered and the understandable consequential emotions, the judiciary\nis looked upon to demonstrate that Ukraine can apply the law fairly, objectively, and\nimpartially, including to accused who are considered as aggressors or collaborators. The\nCommission encourages the members of the judiciary to remain steadfast in their\ncommitment to the rule of law, as this will reflect national values to future Ukrainian\ngenerations, as well as the international community that supports and monitors Ukrainian\nlegal proceedings."},{"id":"a-hrc-52-crp-4-p0858","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"858","seq":860,"section":"C. Proposed new Ukrainian criminal accountability measures","text":"Several suggestions have been made with a view to enhancing judicial measures in\nUkraine to address the magnitude and specialized legal nature of the respective international\nhumanitarian law and international criminal law violations. Reflection processes that have\nnot resulted in specific public proposals will not be considered in this report.\nPublic International Law and Policy Group Draft Law for a Ukrainian High War Crimes\nCourt"},{"id":"a-hrc-52-crp-4-p0859","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"859","seq":861,"section":"C. Proposed new Ukrainian criminal accountability measures","text":"In July 2022, the Public International Law and Policy Group presented its Draft Law\nfor a Ukrainian High War Crimes Court (Draft Law). In advocating for this proposal, the\nPublic International Law and Policy Group stated that “history has shown that without\ninternational assistance and involvement it is inherently difficult to fairly and effectively\nprosecute foreign nationals and separatists in ordinary domestic courts during and in the\naftermath of an armed conflict”.557"},{"id":"a-hrc-52-crp-4-p0860","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"860","seq":862,"section":"C. Proposed new Ukrainian criminal accountability measures","text":"The proposed High War Crimes Court is meant to complement existing Ukrainian\ncourts, the International Criminal Court and any potential international tribunal for the crime\nof aggression. The Public International Law and Policy Group noted that international\nmechanisms generally prosecute a handful of high-level perpetrators, leaving domestic courts\nto try the vast majority of accused. The Draft Law provides a template for a specialized\nnational court based upon the Ukrainian Law on the High Anti-Corruption Court and best\npractices of internationalized domestic war crimes courts from other States. 558"},{"id":"a-hrc-52-crp-4-p0861","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"861","seq":863,"section":"C. Proposed new Ukrainian criminal accountability measures","text":"According to the Draft Law, the High War Crimes Court would be a highly specialized\ncourt within the Ukrainian judicial system composed of Trial Chambers and an Appeals\nChamber. Its jurisdiction would be for war crimes, crimes against humanity, genocide and\ncrimes of aggression committed in Ukraine since November 2013. Its subject-matter\njurisdiction would incorporate both articles of the Ukrainian Criminal Code and crimes from\ninternational legal instruments. While the judges would be Ukrainian, international legal\nadvisors would be appointed to assist and advise the court on international humanitarian law,\ninternational criminal law, and the experience of similar tribunals. The court would be funded\nby the Ukrainian national budget and international donations. 559"},{"id":"a-hrc-52-crp-4-p0862","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"862","seq":864,"section":"C. Proposed new Ukrainian criminal accountability measures","text":"The Commission’s assessment: The Ukrainian judiciary is being called upon to\ndevelop and apply competencies that were not required during peacetime, as described in\npara. 854. The Draft Law aims to bolster that transition by offering a specialized judicial\ninfrastructure building upon existing Ukrainian legal principles and practices.\nThe Commission encourages further discussion and exploration of the Draft Law and similar\nproposals for buttressing the Ukrainian legal system. The scale and nature of the respective\ncrimes require developing a long-term, dependable body of expertise in international\nhumanitarian law and international criminal law within Ukraine, in particular the judiciary\nand court system. In principle, the Draft Law and proposals like it offer feasible solutions\nbased upon lessons learnt from other internationalized and hybrid courts."},{"id":"a-hrc-52-crp-4-p0863","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"863","seq":865,"section":"D. Existing Third State investigative and criminal accountability measures","text":"As early as March 2022, third-party States publicly announced that they had begun\ninvestigative activities into alleged crimes related to the armed conflict in Ukraine.560 As of\n16 February 2023, at least 15 States had announced investigative activities. 561 Depending\nupon the State and its laws, an investigation may be based upon universal jurisdiction, 562 or\nrequire a connection to the investigating State such as the crime being committed by persons\nhaving the nationality of the State (nationality or active personality principle) or committed\nagainst nationals of the State (passive personality principle). 563 Investigative activities may\nalso be for the purpose of collecting information and evidence within a State’s territory for\nuse at the International Criminal Court or proceedings in other States.564"},{"id":"a-hrc-52-crp-4-p0864","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"864","seq":866,"section":"D. Existing Third State investigative and criminal accountability measures","text":"The nature of the investigations varies between States. Some States, at this time, are\nfocused on structural investigations.565 Such investigations may have slightly different\nconnotations in different jurisdictions or prosecution offices. Essentially, a structural\ninvestigation examines evidence of a crime but potential perpetrators have not yet been\nidentified; it focuses on structures related to the crime and groupings of potential\nperpetrators.566 Other States, instead of or in addition to a structural investigation, may have\na particular perpetrator or victim as the focus of their investigation.567"},{"id":"a-hrc-52-crp-4-p0865","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"865","seq":867,"section":"D. Existing Third State investigative and criminal accountability measures","text":"One of the main challenges for third-party State investigations is effective and\nefficient collection of evidence. Some States are primarily collecting evidence from people\nfleeing the armed conflict and seeking refuge in their respective territory, 568 while other\nStates are involved in evidence collection and sharing via bilateral or multilateral\ncoordination mechanisms (see F below regarding international coordination)."},{"id":"a-hrc-52-crp-4-p0866","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"866","seq":868,"section":"D. Existing Third State investigative and criminal accountability measures","text":"The Commission’s assessment: The Commission commends the international\ncommunity for its strong response in support of accountability measures for violations\ncommitted in Ukraine. It is encouraged by States dedicating resources to investigative\nactivities, including the collection, preservation and sharing of information and evidence. To\nutilize these resources efficiently and effectively – including minimizing duplication – robust\nand active coordination is needed, both bilaterally and multilaterally. The Commission\nencourages States to continue to actively participate in existing coordination mechanisms\nwith a view to strengthening practical and tangible means of coordinating efforts."},{"id":"a-hrc-52-crp-4-p0867","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"867","seq":869,"section":"D. Existing Third State investigative and criminal accountability measures","text":"During discussions with third-party State authorities, one of the interesting ideas that\nwas shared with the Commission was mapping the accountability actors who are involved in\nthe collection of evidence, including States and civil society organizations. One practical\noutcome of a mapping exercise could be to produce an index (catalogue) of sharable\ninformation and evidence that would be regularly updated. The index could include a brief\ndescription of an accountability actor’s investigative activities and the general overview of\nevidence that it has collected, such as at which locations in Ukraine the evidence relates to\nand during which timeframe, and the type of evidence (for example, witness evidence relating\nto alleged crimes in a particular oblast in March 2022). Such an index would allow State\nauthorities to become aware of which entities may possess information or evidence of\nrelevance to their respective investigations and case-building."},{"id":"a-hrc-52-crp-4-p0868","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"868","seq":870,"section":"E. Existing international investigatory and criminal accountability","text":"The International Criminal Court was established by The Rome Statute of 17 July\n1998, which came into force in 2002 after the 60 th State ratified the Statute. Presently, there\nare 123 State Parties to the Statute. The International Criminal Court is the sole permanent\ninternational court that investigates and, where warranted, tries individuals charged with the\nmost serious crimes of international concern, namely genocide, crimes against humanity, war\ncrimes and the crime of aggression. This section discusses the investigations of the Office of\nthe Prosecutor in relation to Ukraine as it is presently the main Court organ actively engaged\nin the situation."},{"id":"a-hrc-52-crp-4-p0869","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"869","seq":871,"section":"E. Existing international investigatory and criminal accountability","text":"The Office of the Prosecutor is an independent organ of the Court. It is responsible\nfor receiving referrals and any substantiated information on crimes within the jurisdiction of\nthe Court, for examining them and for conducting investigations and prosecutions before the\nCourt, pursuant to, among others, Article 42 of the Rome Statute."},{"id":"a-hrc-52-crp-4-p0870","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"870","seq":872,"section":"E. Existing international investigatory and criminal accountability","text":"Although neither Ukraine nor the Russian Federation are State Parties to the Rome\nStatute, the Court may exercise jurisdiction regarding allegations of genocide, crimes against\nhumanity and war crimes in Ukraine, including allegations of such acts committed on and\nafter 24 February 2022. This jurisdiction is based upon two declarations that Ukraine lodged\nwith the Court, in accordance with Article 12(3) of the Rome Statute. In its first declaration\nof 9 April 2014, Ukraine recognized the Court’s jurisdiction “for the purpose of identifying,\nprosecuting and judging the authors and accomplices of acts committed on the territory of\nUkraine within the period 21 November 2013 – 22 February 2014”.569 Ukraine’s subsequent\ndeclaration of 8 February 2015 accepted the “jurisdiction of the Court for the purpose of\nidentifying, prosecuting and judging the perpetrators and accomplices of acts committed in\nprobe filmmaker’s killing in Ukraine as war crime”, 5 April 2022; Baltic News Network, “Authorities\ncommence criminal procedure against Latvian for taking part in Russian aggression”, 4 January 2023.\nthe territory of Ukraine since 20 February 2014”.570 Both declarations were made for an\nindefinite duration."},{"id":"a-hrc-52-crp-4-p0871","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"871","seq":873,"section":"E. Existing international investigatory and criminal accountability","text":"Notwithstanding Ukraine’s two declarations, the Court may not exercise jurisdiction\nregarding allegations of the crime of aggression in Ukraine. In particular, the Court cannot\nexercise its jurisdiction over the crime when committed by nationals of a State that is not\nparty to the Rome Statute, pursuant to Article 15 bis(5) of the Statute. While allegations\nregarding the crime of aggression have been made against nationals of the Russian Federation\nand Belarus, neither is a State Party to the Rome Statute."},{"id":"a-hrc-52-crp-4-p0872","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"872","seq":874,"section":"E. Existing international investigatory and criminal accountability","text":"On 28 February 2022, the Prosecutor announced that he decided to proceed with\nopening an investigation into the situation in Ukraine. In view of an earlier preliminary\nexamination he confirmed that there was a reasonable basis to proceed with an investigation,\nin particular with respect to war crimes and crimes against humanity. Given the expansion of\nthe conflict in recent days, it was his intention that this investigation will also encompass any\nnew alleged crimes falling within the jurisdiction of the Office of the Prosecutor that are\ncommitted by any party to the conflict on any part of the territory of Ukraine. 571"},{"id":"a-hrc-52-crp-4-p0873","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"873","seq":875,"section":"E. Existing international investigatory and criminal accountability","text":"In the same announcement, the Prosecutor stated that a referral of the situation to his\nOffice by a State Party would expedite matters under the Rome Statute. Without a referral,\nthe Prosecutor would need to seek authorisation from the Pre-Trial Chamber to open\nan investigation, as required under Article 15(3). A referral of the situation by a State Party\nrequesting an investigation under Article 14 would dispense with the requirement to obtain\njudicial authorisation."},{"id":"a-hrc-52-crp-4-p0874","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"874","seq":876,"section":"E. Existing international investigatory and criminal accountability","text":"On 2 March 2022, the Prosecutor stated that 39 State Parties had referred the situation\nin Ukraine to his Office. He confirmed that the referrals enabled him to proceed with opening\nan investigation into allegations of war crimes, crimes against humanity and genocide\ncommitted on any part of the territory of Ukraine by any person. He stated that his Office’s\nwork in the collection of evidence had now commenced.572 As of the writing of this report,\nthe number of referrals had increased to 43.573"},{"id":"a-hrc-52-crp-4-p0875","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"875","seq":877,"section":"E. Existing international investigatory and criminal accountability","text":"The Office of the Prosecutor has been actively engaged in Ukraine, in particular since\nopening its investigation. The Office has been working with the General Prosecutor of\nUkraine and civil society interlocutors. On 25 April 2022, the Office became a participant in\nthe Joint Investigative Team composed of Estonia, Latvia, Lithuania, Poland, Romania,\nSlovakia and Ukraine (see paras. 899-902). In a presentation on 9 February 2023, hosted by\nthe Council of Europe, the Office indicated that its investigative priorities included (i)\ndeportation of civilians, including children; (ii) attacks on the civilian population and\ninfrastructure, including power grids; and (iii) torture, executions, filtration camps, unlawful\ntransfers, etc."},{"id":"a-hrc-52-crp-4-p0876","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"876","seq":878,"section":"E. Existing international investigatory and criminal accountability","text":"The Prosecutor may seek an arrest warrant or a summons from the Pre-Trial Chamber\nfor a person that he believes has committed a crime within the jurisdiction of the Court. For\neither an arrest warrant or a summons, the Chamber must be satisfied that, among other\nthings, there are reasonable grounds to believe that the person has committed such a crime,\npursuant to Article 58 of the Rome Statute. Following the person’s surrender to the Court or\nvoluntary appearance, one of the subsequent main steps is the confirmation of the charges\nbefore trial. At that stage, the Pre-Trial Chamber determines whether there is sufficient\nevidence to establish substantial grounds to believe that the person committed each of the\ncrimes charged, pursuant to Article 61.574\n570 International Criminal Court, Declaration of Ukraine, 8 February 2015.\n571 International Criminal Court, “Statement of ICC Prosecutor, Karim A.A. Khan QC, on the Situation\nin Ukraine: “I have decided to proceed with opening an investigation.””, 28 February 2022.\n572 International Criminal Court, “Statement of ICC Prosecutor, Karim A.A. Khan QC, on the Situation\nin Ukraine: Receipt of Referrals from 39 States Parties and the Opening of an Investigation”, 2 March\n2022.\n573 International Criminal Court, Situation in Ukraine.\n574 On 17 March 2023, after the submission of the Commission’s report to the Human Rights Council,\nthe ICC announced that a Pre-Trial Chamber had issued arrest warrants for Vladimir Putin, President\nof the Russian Federation, and Maria Lvova-Belova, Commissioner for Children’s Rights in the\nOffice of the President of the Russian Federation, for the alleged war crime of unlawful deportation of"},{"id":"a-hrc-52-crp-4-p0877","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"877","seq":879,"section":"E. Existing international investigatory and criminal accountability","text":"The Commission’s assessment: The ICC is the only permanent international court\ncovering genocide, crimes against humanity and war crimes. The Prosecutor, who is\nindependent, is investigating these crimes. In the Commission’s view, this eliminates the\nneed to establish a new ad hoc tribunal for Ukraine with the power to investigate and\nadjudicate these three international crimes, similar to the tribunals for the former Yugoslavia\nand Rwanda. As regards proposals to set up a possible special tribunal on aggression, see\nparas. 0-945."},{"id":"a-hrc-52-crp-4-p0878","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"878","seq":880,"section":"E. Existing international investigatory and criminal accountability","text":"It is a general experience that initial and ongoing outreach with victims and other\nstakeholders is important to the success of an investigatory and accountability mechanism.\nVictims and human rights defenders, who may have many questions for a mechanism, should\nbe treated as equal partners in seeking justice, and not only as providers of evidence. Setting\nexpectations at the start of a mechanism’s work is important. The Commission recommends\nthat the Prosecutor of the International Criminal Court ensure that regular and scheduled\noutreach meetings continue to be held with stakeholders including victims’ groups and\nhuman rights defenders. The Commission understands that the Office has been seeking an\nappropriately representative range of such stakeholders,575 and it encourages the Office to\ncontinue to formulate tailored strategies for engaging with them.\nUnited Nations Human Rights Monitoring Mission in Ukraine"},{"id":"a-hrc-52-crp-4-p0879","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"879","seq":881,"section":"E. Existing international investigatory and criminal accountability","text":"The United Nations Human Rights Monitoring Mission in Ukraine was deployed in\n2014 and has continued its work through the on-going armed conflict. Its mandate was to\n“monitor and report on the human rights situation throughout Ukraine and to propose\nrecommendations to the Government and other actors to address emerging human rights\nissues as well as the root causes of the situation that was unravelling”. 576 Its mandate is\nextended every six months. At present, the Mission has offices in Kyiv, Dnipro, Odesa,\nPoltava and Uzhorod. It also has satellite teams in Chisinau, Moldova and Krakow, Poland.\nThe Mission’s staff includes almost 90 persons.577"},{"id":"a-hrc-52-crp-4-p0880","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"880","seq":882,"section":"E. Existing international investigatory and criminal accountability","text":"Since 2014, the Mission has issued (by November 2022) 34 periodic reports, nine\nbriefing notes, seven thematic reports and four updates on the human rights situation in\nUkraine.578 It has also provided legal expertise and reviewed draft laws in Ukraine. Turning\nspecifically to the events after 24 February 2022, the Mission has increased the frequency of\nits public updates on civilian casualty figures, i.e., those killed and injured. 579 Based on its\ninvestigations, it has also issued reports and statements regarding accountability for\nviolations of international human rights law and international humanitarian law, both relating\nto specific periods and selected topics.580"},{"id":"a-hrc-52-crp-4-p0881","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"881","seq":883,"section":"E. Existing international investigatory and criminal accountability","text":"The Commission’s assessment: The Mission has extensive institutional knowledge\nand experience about the situation in Ukraine, having observed the situation from within the\ncountry since 2014. Its many thorough reports have contributed to informed discussions\nabout the situation in Ukraine, for instance within the UN system, by national decision-\nmakers, in the media, and amongst the public at large. The information contained in those\nreports are also important to shed light on the need for criminal as well as non-judicial\naccountability. It is therefore important that the Mission continues its work with sufficient\nresources.\npopulation (children) and that of unlawful transfer of population (children) from occupied areas of\nUkraine to the Russian Federation."},{"id":"a-hrc-52-crp-4-p0882","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"882","seq":884,"section":"E. Existing international investigatory and criminal accountability","text":"The Commission notes that the Mission has been granted access to the areas under the\ncontrol of the Ukrainian territories but not to the territories under the effective control of the\nRussian Federation. In view of the necessity to carry out full investigations, the Commission\nrecommends to the Russian Federation that the Mission, like other international investigating\nentities, be granted access to the former so-called Donetsk and Luhansk Peoples’ Republics\nand other occupied territories.\nMoscow Mechanism of the Organization for Security and Co-operation in Europe"},{"id":"a-hrc-52-crp-4-p0883","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"883","seq":885,"section":"E. Existing international investigatory and criminal accountability","text":"The Moscow Mechanism was developed at the Conference on the Human Dimension\nin Moscow in 1991. The Mechanism provides for the Organization for Security and Co-\noperation in Europe participating States to establish ad hoc missions of independent experts\nto assist in the resolution of a specific human dimension problem. The experts are expected\nto submit their observations as soon as possible, preferably within three weeks after the\nMechanism was established.581 The expert missions are supported by the Office for\nDemocratic Institutions and Human Rights of the Organization for Security and Co-operation\nin Europe, in Warsaw.582"},{"id":"a-hrc-52-crp-4-p0884","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"884","seq":886,"section":"E. Existing international investigatory and criminal accountability","text":"The events from 24 February 2022 onwards in Ukraine had, as of the submission of\nthe Commission’s report to the Human Rights Council, been the topic of two reports by the\nMoscow Mechanism, which was invoked on 3 March and 2 June 2022 by 45 participating\nStates of the Organization for Security and Co-operation in Europe. The mandates related to\npossible contraventions of the Organization for Security and Co-operation in Europe\ncommitments, and violations and abuses of international human rights law and international\nhumanitarian law. The mission was requested to collect, consolidate, and analyse this\ninformation with a view to presenting it to relevant accountability mechanisms, as well as\nexisting or future courts or tribunals.583"},{"id":"a-hrc-52-crp-4-p0885","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"885","seq":887,"section":"E. Existing international investigatory and criminal accountability","text":"The mandate of 3 March 2022 resulted in a report of 12 April 2022. Even if it had not\nbeen possible to verify all allegations, the three appointed experts found clear patterns of\ninternational humanitarian law violations by the Russian armed forces in their conduct of\nhostilities, and credible evidence that violations of even the most fundamental human rights\nhad been committed mostly in the areas under the effective control of the Russian Federation.\nSome violations and problems were also identified regarding practices of Ukraine, such as\nthe treatment of prisoners of war, originally considered criminals, and treated in ways that\nare incompatible with Geneva Convention III.584"},{"id":"a-hrc-52-crp-4-p0886","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"886","seq":888,"section":"E. Existing international investigatory and criminal accountability","text":"The second Moscow Mechanism mandate of 2 June 2022 built on the first report and\nincluded but was not limited to violations in certain cities and regions. It led to a report of\n14 July 2022 that largely confirmed the conclusions reached by the first mission. The experts\nfound clear patterns of serious violations of international humanitarian law attributable\nmostly to the Russian armed forces in many areas which its investigations referred to.\nInternational human rights law had been extensively violated in the conflict in Ukraine. Most,\nalbeit not all, violations had been committed in the territories under the effective control of\n581 Organization for Security and Co-operation in Europe, Moscow Mechanism.\n582 Organization for Security and Co-operation in Europe, Human dimension mechanisms. The OSCE\nSpecial Monitoring Mission to Ukraine, which started its activities on 21 March 2014, discontinued\nits operations on 31 March 2022 and is not included in this report.\n583 Organization for Security and Co-operation in Europe, Report on violations of international\nhumanitarian and human rights law, war crimes and crimes against humanity committed in Ukraine\nsince 24 February 2022 (Moscow’s Mechanism), 13 April 2022, pp. i and 1-2. On 4 May 2023, after\nthe submission of the Commission’s report to the Human Rights Council, a third Moscow Mechanism\nmission issued its report entitled Report on Violations and Abuses of International Humanitarian and\nHuman Rights Law, War Crimes and Crimes Against Humanity, related to the Forcible Transfer\nand/or Deportation of Ukrainian Children to the Russian Federation.\n584 Organization for Security and Co-operation in Europe, Report on violations of international\nhumanitarian and human rights law, war crimes and crimes against humanity committed in Ukraine\nsince 24 February 2022 (Moscow’s Mechanism), 13 April 2022, pp. i and 93.\nthe Russian Federation, including the territories of the former so-called Donetsk and Luhansk\nPeople’s Republics, and were largely attributable to the Russian Federation.585"},{"id":"a-hrc-52-crp-4-p0887","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"887","seq":889,"section":"E. Existing international investigatory and criminal accountability","text":"The Commission’s assessment: The two mandates of the Moscow Mechanism relating\nto the events from 24 February 2022 until the end of the Commission’s first mandate have\nbeen broad, both substantively and geographically. The reports provide extensive\ninformation about violations of international humanitarian law and human rights law in\nUkraine. The independent experts have collected and assessed information and evidence with\na view to presenting it to existing and future accountability mechanisms. The Commission\nhas taken this material into account during its work."},{"id":"a-hrc-52-crp-4-p0888","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"888","seq":890,"section":"E. Existing international investigatory and criminal accountability","text":"The short timeframe, preferably three weeks, and limited resources for such reports\nreduce the expert mission’s possibilities to conduct visits in Ukraine. Most of the information\nreferred to in the expert missions’ reports is based on documentary sources, even if they have\nconducted videoconferences and brief visits. On the other hand, there is now a large number\nof entities carrying out investigations on the ground in Ukraine, such as the International\nCriminal Court, the United Nations Human Rights Monitoring Mission in Ukraine, the\nOffice for Democratic Institutions and Human Rights of the Organization for Security and\nCo-operation in Europe, the Ukrainian Prosecutor General and prosecutorial authorities from\nother national jurisdictions. This has led to an increasing amount of information and evidence\nabout violations of international humanitarian law and human rights law."},{"id":"a-hrc-52-crp-4-p0889","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"889","seq":891,"section":"E. Existing international investigatory and criminal accountability","text":"It is for the participating States of the Organization for Security and Co-operation in\nEurope to decide whether to invoke the Moscow Mechanism. If this is considered, the\nCommission recommends that the mandate of an expert mission should be specific rather\nthan general and be formulated in view of the other investigative work that is carried out in\nUkraine. Such coordination between entities with similar mandates will reduce the risk of\nduplication of work and may contribute to increasing the total output of the investigations in\nUkraine.586\nOffice for Democratic Institutions and Human Rights of the Organization for Security and\nCo-operation in Europe"},{"id":"a-hrc-52-crp-4-p0890","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"890","seq":892,"section":"E. Existing international investigatory and criminal accountability","text":"Shortly after 24 February 2022, the Office for Democratic Institutions and Human\nRights of the Organization for Security and Co-operation in Europe launched its Ukraine\nMonitoring Initiative to monitor and document violations of international human rights law\nand international humanitarian law affecting the lives of civilians and prisoners of war. 587"},{"id":"a-hrc-52-crp-4-p0891","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"891","seq":893,"section":"E. Existing international investigatory and criminal accountability","text":"On 20 July 2022, after the second Moscow Mechanism report, the Office for\nDemocratic Institutions and Human Rights issued an interim report on reported violations of\ninternational humanitarian law and international human rights law in Ukraine, based on three\nmonitoring missions within Ukraine. According to its findings, the hostilities by the Russian\nFederation, during the reporting period, had been characterized by conduct a general\ndisregard for the basic principles of distinction, proportionality and precautions set out by\ninternational humanitarian law, which may amount to war crimes and crimes against\nhumanity. There were also indications that, to a much more limited extent, the Ukrainian\narmed forces failed to comply, during the reporting period, with specific international\nhumanitarian law rules on the conduct of hostilities. 588"},{"id":"a-hrc-52-crp-4-p0892","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"892","seq":894,"section":"E. Existing international investigatory and criminal accountability","text":"The Office for Democratic Institutions and Human Rights issued on updated\nassessment of alleged violations on 14 December 2022, generally focusing on events until 1\nNovember 2022. It largely confirmed and supplemented the findings of the first interim\nreport. At that point in time, the Office for Democratic Institutions and Human Rights had\nconducted 120 in-person interviews in Ukraine and Estonia with witnesses and survivors of\nalleged violations.589"},{"id":"a-hrc-52-crp-4-p0893","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"893","seq":895,"section":"E. Existing international investigatory and criminal accountability","text":"It should be added that the Office for Democratic Institutions and Human Rights now\nhas four main ongoing focuses in relation to accountability for the armed conflict in Ukraine.\nFirst, monitoring and documentation of violations (for instance, its July and December 2022\ninterim reports). Second, providing assistance to civil society organizations with monitoring\nof violations. Third, assisting Ukrainian authorities with capacity building. Fourth, offering\nassistance and expert advice to the judiciary and legal professionals on international standards\nrelevant to war crimes adjudication."},{"id":"a-hrc-52-crp-4-p0894","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"894","seq":896,"section":"E. Existing international investigatory and criminal accountability","text":"The Commission’s assessment: The Office for Democratic Institutions and Human\nRights has submitted two comprehensive reports on violations of international humanitarian\nlaw and human rights law in Ukraine, based on direct evidence, including interviews on the\nground. Such material may assist the work of existing and future accountability measures.\nThe mandates are broad and cover in principle the entire territory of Ukraine. The\nCommission recommends that the Office for Democratic Institutions and Human Rights\ncontinue to exchange information with other entities operating in the country with a view to\nincreased coordination of investigations.\nFact-Finding Mission regarding the 29 July 2022 Incident at Olenivka"},{"id":"a-hrc-52-crp-4-p0895","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"895","seq":897,"section":"E. Existing international investigatory and criminal accountability","text":"On 3 August 2022, the United Nations Secretary-General announced his decision to\nlaunch a three-member Fact-Finding Mission regarding the 29 July 2022 Incident at Olenivka\nfollowing requests from the Governments of Ukraine and the Russian Federation. The Fact-\nFinding Mission was supposed to ascertain the facts regarding the deaths of dozens of\nprisoners of war at a facility in Olenivka, and report to the Secretary-General upon\ncompletion of its work.590 One of the challenges for the Fact-Finding Mission was gaining\naccess to the Olenivka area, which is in the Donetsk region."},{"id":"a-hrc-52-crp-4-p0896","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"896","seq":898,"section":"E. Existing international investigatory and criminal accountability","text":"In early 2023, the United Nations Spokesperson announced that the Secretary-General\nhad decided to disband the Fact-Finding Mission in the absence of conditions required for\nthe deployment of the Mission to the site. Reference was made to the lack of solid and clear\nsafety and access guarantees from both sides. The Secretary-General stands ready to\nreconstitute the team should the necessary guarantees be provided.591"},{"id":"a-hrc-52-crp-4-p0897","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"897","seq":899,"section":"E. Existing international investigatory and criminal accountability","text":"The Commission’s assessment: The difficulties in connection with the Olenivka event\nemphasize how full cooperation of all relevant national authorities is indispensable for\nefficient fact-finding. This is also illustrated with respect to other entities, such as the\nproblems encountered by United Nations Human Rights Monitoring Mission in Ukraine and\nby this Commission to obtain access to the occupied territories (see paras. 881 and 32,\nrespectively). In order to have a full investigation, the Commission recommends that Ukraine\nand the Russian Federation provide solid and clear guarantees of safety and access to\nOlenivka."},{"id":"a-hrc-52-crp-4-p0898","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"898","seq":900,"section":"F. Coordination mechanisms for accountability actors","text":"Many entities are seeking to support accountability measures. Such accountability\nactors are diverse and include State and non-State entities, both national and international in\norigin. Shortly after the events of 24 February 2022, it was recognized that coordination of\naccountability actors was necessary and beneficial for several reasons. Principally, robust\ncoordination can minimize both victim re-traumatization from multiple actors engaging them\nand, in general, duplicative efforts, while increasing efficient use of finite resources during\nan ongoing armed conflict."},{"id":"a-hrc-52-crp-4-p0899","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"899","seq":901,"section":"F. Coordination mechanisms for accountability actors","text":"The following describes three of the main State-driven coordination mechanisms.\nSince the goal of such mechanisms is to work collaboratively on accountability measures,\nthe Commission considers it more beneficial to provide its assessment of coordination efforts\nin general, as opposed to separate assessments of the three mechanisms below.\nJoint Investigation Team"},{"id":"a-hrc-52-crp-4-p0900","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"900","seq":902,"section":"F. Coordination mechanisms for accountability actors","text":"On 25 March 2022, the Joint Investigation Team on alleged core international crimes\ncommitted in Ukraine was established through the European Union Agency for Criminal\nJustice Cooperation.592 In general, Joint Investigation Teams are common mechanisms for\ninternational cooperation regarding investigations; in 2021, there were 254 Joint\nInvestigation Team.593 Each Joint Investigation Team is based on an agreement between\nauthorities of two or more States for the purpose of carrying out a particular criminal\ninvestigation; usually composed of prosecutors and law enforcement authorities from the\nrespective States, whereas Eurojust provides operational, legal and financial support.594 Joint\nInvestigation Teams also have closer access to support from the European Network for\ninvestigation and prosecution of genocide, crimes against humanity and war crimes (also\nknown as the Genocide Network), which is hosted by European Union Agency for Criminal\nJustice Cooperation. The Genocide Network facilitates close cooperation between national\nauthorities specifically investigating and prosecuting cases of these core international\ncrimes.595"},{"id":"a-hrc-52-crp-4-p0901","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"901","seq":903,"section":"F. Coordination mechanisms for accountability actors","text":"Lithuania, Poland and Ukraine established the Joint Investigation Team for Ukraine\nand it was later joined by Estonia, Latvia, Slovakia and Romania. 596 For the first time, the\nOffice of the Prosecutor of the International Criminal Court joined a Joint Investigation\nTeam. The agreement with the Office of the Prosecutor is meant to enable real-time\ncoordination and cooperation with the seven States in connection with their respective\ninvestigations.597 Additionally, the European Union Agency for Criminal Justice Cooperation\nhas emphasized the need for coordination of all investigations regarding alleged core\ninternational crimes in Ukraine, including with non- Joint Investigation Team States.598\nDuring the Joint Investigation Teams’ first year, the European Union Agency for Criminal\nJustice Cooperation hosted 14 coordination meetings of the Joint Investigation Team and\nother national authorities.599"},{"id":"a-hrc-52-crp-4-p0902","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"902","seq":904,"section":"F. Coordination mechanisms for accountability actors","text":"The Joint Investigation Team for Ukraine will have access to Eurojust’s new Core\nInternational Crimes Evidence Database, which began operations on 23 February 2023.\nThe Core International Crimes Evidence Database is designed to support national and\ninternational investigations by securely preserving, storing and analysing evidence of core\ninternational crimes. Although the impetus for the Core International Crimes Evidence\nDatabase was the armed conflict in Ukraine, it is meant to assist investigations of crimes in\nvarious conflicts. Only national authorities from European Union Member States and\ncountries with Liaison Prosecutors at Eurojust will be able to submit information or evidence\non a voluntary basis to the Core International Crimes Evidence Database. According to\nEurojust, the Core International Crimes Evidence Database will be used to perform targeted\nsearches for evidence related to a specific event or location, identify parallel investigations,\nand prepare thematic reports on specific aspects of investigations such as sexual and gender-\nbased violence.600"},{"id":"a-hrc-52-crp-4-p0903","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"903","seq":905,"section":"F. Coordination mechanisms for accountability actors","text":"On 5 March 2023, the seven States involved in the Joint Investigation Team for\nUkraine amended their agreement to include, as a support structure, the newly created\nInternational Centre for the Prosecution of the Crime of Aggression. The International Centre\nfor the Prosecution of the Crime of Aggression, which is situated in The Hague, Netherlands,\nwill focus on supporting and enhancing investigations into the crime of aggression by\nsecuring evidence and facilitating case building.601 The creation of the International Centre\nfor the Prosecution of the Crime of Aggression was first announced on 2 February 2023 by\nthe President of the European Commission.602\nAtrocity Crimes Advisory Group"},{"id":"a-hrc-52-crp-4-p0904","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"904","seq":906,"section":"F. Coordination mechanisms for accountability actors","text":"On 25 May 2022, the European Union, the United States and the United Kingdom\nannounced the establishment of the Atrocity Crimes Advisory Group. Its overarching mission\nis to support the war crimes unit of the Office of the Prosecutor General in Ukraine. The\nAtrocity Crimes Advisory Group is an operational hub meant to coordinate their respective\nsupport for accountability efforts in Ukraine.603 In 2023, Canada joined the group.604"},{"id":"a-hrc-52-crp-4-p0905","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"905","seq":907,"section":"F. Coordination mechanisms for accountability actors","text":"Atrocity Crimes Advisory Group’s activities include two main elements: an Advisory\nGroup to the Office of the General and Mobile Justice Teams. The Advisory Group consists\nof, among others, experienced war crimes prosecutors, investigators and analysts, who\nprovide expertise, mentoring, advice and operational support to the Office of the Prosecutor\nGeneral, Mobile Justice Teams, State and non-State actors. The Mobile Justice Teams s are\ncomposed of international and Ukrainian experts and deploy at the Office of the Prosecutor\nGeneral’s request to assist Ukrainian investigators. In conjunction with these two main\nelements, the Atrocity Crimes Advisory Group operates through implementing partners such\nas the European Union Advisory Mission in Ukraine, Global Rights Compliance and the\nEuropean Union Project Pravo-Justice II.605\nDialogue Group on Accountability for Ukraine"},{"id":"a-hrc-52-crp-4-p0906","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"906","seq":908,"section":"F. Coordination mechanisms for accountability actors","text":"At the Ukraine Accountability Conference in The Hague on 14 July 2022, ministerial\nrepresentatives of 45 States discussed establishing a mechanism for coordination.606 The\nproposed mechanism – Dialogue Group on Accountability for Ukraine (Dialogue Group) –\nhas the “objective of promoting dialogue across the various national, European and\ninternational accountability and documentation initiatives relevant to the situation in Ukraine,\nas well as the identification of opportunities for enhanced coherence of action in these efforts,\nwhere appropriate”.607"},{"id":"a-hrc-52-crp-4-p0907","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"907","seq":909,"section":"F. Coordination mechanisms for accountability actors","text":"The Political Declaration issued at the end of the July 2022 conference also discussed\nother points, including completion of a comprehensive mapping process of the technical\nneeds of Ukraine; provision of additional capacity-building and other support to those\n600 Eurojust, Core International Crimes Evidence Database (CICED), 23 February 2023.\n601 Eurojust, “International Centre for the Prosecution of the Crime of Aggression made official at United\nfor Justice Conference in Ukraine”, press release, 5 March 2023.\n602 European Commission, Directorate-General for Neighbourhood and Enlargement Negotiations,\n“Statement by President von der Leyen at the joint press conference with Ukrainian President\nZelenskyy”, 2 February 2023. See also European Commission, “Statement by President von der Leyen\non the establishment of the International Centre for the Prosecution of Crimes of Aggression against\nUkraine”, 4 March 2023.\n603 European Union External Action Service, “Ukraine: The European Union, the United States, and the\nUnited Kingdom establish the Atrocity Crimes Advisory Group (ACA) for Ukraine”, press release, 25\nMay 2022.\n604 Global Affairs Canada, “Canada to increase support for security and stabilization efforts in Ukraine”,\npress release, 24 February 2023.\n605 European Union External Action Service, Questions and Answers: Atrocity Crimes Advisory Group\n(ACA) for Ukraine, 25 May 2022.\n606 Government of the Netherlands, “Ukraine Accountability Conference: a step towards justice”, press\nrelease, 14 July 2022.\n607 Government of the Netherlands, Political Declaration of the Ministerial Ukraine Accountability\nConference, 14 July 2022, para. 25.\nauthorities; and promotion of measures to align interventions from national, regional and\ninternational entities aimed at strengthening capacity and resources for investigations in\nUkraine. The Declaration emphasised that the Dialogue Group’s work should take into\naccount existing cooperation and coordination mechanisms such as Atrocity Crimes\nAdvisory Group and the Joint Investigation Team.608"},{"id":"a-hrc-52-crp-4-p0908","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"908","seq":910,"section":"F. Coordination mechanisms for accountability actors","text":"On 3 March 2023 at the United for Justice Conference in Lviv, Ukraine, the Dialogue\nGroup was launched. It will consist of four ‘work flows’, each with its own focus: (i) “the\nsupport of international parties for Ukraine”; (ii) “actions being taken by regional and\ninternational institutions”; (iii) “national investigations”, and (iv) “ongoing documentation\ninitiatives on the part of civil society”. The work of these streams will feed into an expert-\nlevel plenary Dialogue Group meeting and an annual ministerial-level meeting.609\nThe Commission’s Assessment"},{"id":"a-hrc-52-crp-4-p0909","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"909","seq":911,"section":"F. Coordination mechanisms for accountability actors","text":"From its early days, the Commission has shared the view that in such a crowded\naccountability space, coordination is needed among the many actors. Coordination\nmechanisms should be active, robust and visible. Importantly, practical and structured means\nof coordination should be a key output, such as European Union’s Judicial Cooperation\nUnit’s Core International Crimes Evidence Database and the suggested evidence index\ndescribed in this report (see paras. 866 and 902).610 The Commission provides the following\nmain observations to assist in strengthening existing coordination efforts."},{"id":"a-hrc-52-crp-4-p0910","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"910","seq":912,"section":"F. Coordination mechanisms for accountability actors","text":"First, coordination of the accountability actors is horizontal as opposed to hierarchical.\nThe actors are seen as equal partners, so this may require more time in reaching consensus.\nHowever, actors are encouraged to continue striving for compromise and common ground on\nissues such as practical ways to support investigative activities in Ukraine. As part of building\nconsensus, coordination mechanisms should ensure that their efforts are visible to all the\nrespective actors, albeit certain aspects may need to be confidential due to particular\ninvestigative activities. Horizontal coordination requires mechanisms to ensure that actors\nare aware of coordination efforts, which enhances the actors’ trust and reliance in the\nmechanism."},{"id":"a-hrc-52-crp-4-p0911","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"911","seq":913,"section":"F. Coordination mechanisms for accountability actors","text":"Second, mapping of the various accountability actors and their respective activities is\nan essential component of coordination. While mapping initiatives have begun, they should\nbe regularly updated as investigations progress, potential new actors become involved, and\nthe situation in Ukraine evolves. Based upon discussions with accountability actors and\na coordination mechanism, the Commission understands that actors have worked collegially\nwith each other, but there is a lack of full awareness about each other’s activities.\nFor example, during meetings hosted by the Commission both in-person and online, actors\nexpressed appreciation for the opportunity to share updates about their current work, to learn\nabout the latest work of other actors in the room, and to seek assistance or collaboration from\nthe other actors."},{"id":"a-hrc-52-crp-4-p0912","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"912","seq":914,"section":"F. Coordination mechanisms for accountability actors","text":"Third, coordination should take into consideration that accountability actors have\ndifferent roles and functions. It may be bilateral or multilateral, depending on the number of\nactors involved and the nature of the discussion. During a meeting with the Commission, a\nparticipant suggested viewing some of the accountability actors in two general categories:\nfirst, actors that have mandates to investigate, to make findings and/or to conduct criminal\nprosecutions (such as national authorities, the Commission or the International Criminal\nCourt); and second, actors who assist the first group (such as Eurojust or Global Rights\nCompliance). Those in the second group likely have a wider scope as they may also be\ninvolved in capacity-building and technical assistance. While there can be coordination of\nboth groups together, it may also be beneficial to have separate coordination within each\ngroup given their particular role and needs. The Dialogue Group appears to have taken into\naccount the different types of accountability actors in establishing its four ‘workflows’. The\nCommission looks forward to the outcomes of those workflows."},{"id":"a-hrc-52-crp-4-p0913","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"913","seq":915,"section":"1. Investigating or prosecuting authorities","text":"The International Humanitarian Fact-Finding Commission was established by\nArticle 90 of Additional Protocol I of 1977 to the Geneva Conventions. Its purpose is to: (i)\nenquire into any facts alleged to be grave or serious violations of the Conventions and the\nProtocol, and (ii) facilitate, through its good offices, the restoration of an attitude of respect\nfor the Conventions and the Protocol.611 Officially constituted in 1991, the Fact-Finding\nCommission is a permanent international body with 15 members elected by 76 States that\nrecognize its competence.612 Both Ukraine and the Russian Federation ratified Additional\nProtocol I. On 23 October 2019, the Russian Federation informed the Swiss Federal Council\nthat it had decided to withdraw its declaration recognizing ipso facto the competence of the\nFact-Finding Commission.613"},{"id":"a-hrc-52-crp-4-p0914","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"914","seq":916,"section":"1. Investigating or prosecuting authorities","text":"The Fact-Finding Commission has not been activated pursuant to Article 90. Separate\nfrom its treaty mandate, the Organization for Security and Co-operation in Europe requested\nthe Fact-Finding Commission to investigate the death of one paramedic and the injuries to\ntwo patrol members of the Organization for Security and Co-operation in Europe’s Special\nMonitoring Mission to Ukraine due to an explosion on 23 April 2017.614"},{"id":"a-hrc-52-crp-4-p0915","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"915","seq":917,"section":"1. Investigating or prosecuting authorities","text":"The Commission’s assessment: The Commission notes that the Fact-Finding\nCommission never has been activated under Article 90 of Additional Protocol I of 1977. As\nthe Russian Federation has withdrawn its ipso facto declaration, the only way to activate this\nprocedure in the present context would be through an ad hoc acceptance. Even if this is a\npossibility, the Commission does not consider this likely, at least not at the present stage. 615\nPermanent Independent Investigative Mechanism"},{"id":"a-hrc-52-crp-4-p0916","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"916","seq":918,"section":"1. Investigating or prosecuting authorities","text":"In the wake of the armed conflict in Ukraine, there have been renewed calls for\na permanent independent investigative mechanism that has the established resources to\nquickly collect and preserve evidence of, among other things, violations of international\nhuman rights and international humanitarian law. Civil society organizations616 and research\ninstitutes617, supported by some States, have proposed and supported such a mechanism with\nworld-wide scope focusing on evidence gathering, preservation and analysis for international\nand domestic criminal proceedings. These proposals are inspired by, among others, three\nrecent independent investigative mechanisms for Syria, Da’esh and Myanmar. 618 The\ndiscussions have resulted in two possible options."},{"id":"a-hrc-52-crp-4-p0917","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"917","seq":919,"section":"1. Investigating or prosecuting authorities","text":"The first option is to establish an Investigative Support Mechanism, independent of\nthe OHCHR. It would act as a service provider to other mandates concerned with\naccountability, and, when triggered by a competent United Nations body, act as an\ninvestigative mechanism of its own; fulfil a coordinating role and provide strategic advice.\nThe second option is to set up an Investigative Support Division within the OHCHR, which\nwould assist in the prompt recruitment and deployment of teams for each United Nations\nmandated investigation; serve as institutional memory and provide other forms of support.619"},{"id":"a-hrc-52-crp-4-p0918","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"918","seq":920,"section":"1. Investigating or prosecuting authorities","text":"The Commission’s assessment: These two options envisage the establishment of a new\npermanent entity, either independently of or within the OHCHR. Under the circumstances, it\nis unlikely that either option can be operationalised in the short-term for Ukraine.\nIndependent Investigative Mechanism for Ukraine"},{"id":"a-hrc-52-crp-4-p0919","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"919","seq":921,"section":"1. Investigating or prosecuting authorities","text":"On some occasions, it has been proposed that a United Nations independent\ninvestigative mechanism build upon the work of a commission of inquiry. For instance, with\nrespect to Syria and Myanmar, a precursor United Nations commission of inquiry and a fact-\nfinding mission, respectively, existed before the establishment of the International, Impartial\nand Independent Mechanism for Syria and the Independent Investigative Mechanism for\nMyanmar.620 These two mechanisms were established by the General Assembly and the\nHuman Rights Council, respectively.621"},{"id":"a-hrc-52-crp-4-p0920","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"920","seq":922,"section":"1. Investigating or prosecuting authorities","text":"Unlike a commission of inquiry that issues public findings based on the ‘reasonable\ngrounds to conclude/believe’ standard, an investigative mechanism primarily collects,\npreserves, and analyses evidence to a criminal law standard for the purposes of case-building\nand/or assisting international and domestic investigations and prosecutions, usually on a\nmore confidential basis. They may also have other functions, such as coordination and\ncooperation, as well as providing technical assistance to the State concerned and civil society\n(e.g., training judges, prosecutors, defence counsel, civil society organizations in\ninternational criminal law and international humanitarian law).622 An investigative\nmechanism may have protocols of cooperation with civil society organizations regarding,\namong other things, principles underlying collaboration, transfer of data to the mechanism,\nand transfer of data by the mechanism to investigative or prosecutorial authorities. 623"},{"id":"a-hrc-52-crp-4-p0921","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"921","seq":923,"section":"1. Investigating or prosecuting authorities","text":"The Commission’s assessment: It would be for the Human Rights Council to decide\nwhether a new investigative mechanism should be established for Ukraine. The Commission\nnotes that on 4 April 2023, the Council renewed the Commission’s mandate to continue its\ninvestigations. Furthermore, it is noted that new investigative mechanisms after precursory\ncommissions of inquiry have been established in two instances. As regards the specific\nsituation in Ukraine, a large number of national and international entities are presently\ncarrying out investigations there, such as the Prosecutor General of Ukraine, the International\nCriminal Court, the OHCHR Monitoring Mission, in addition to the Commission. Therefore,\nthe need for a new investigative mechanism for Ukraine is less than when the mechanisms\nfor Syria and Myanmar were created and the Commission does not recommend this solution."},{"id":"a-hrc-52-crp-4-p0922","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"922","seq":924,"section":"2. Judicial authorities","text":"According to Human Rights Council resolution. 49/1, the Commission shall\ninvestigate alleged violations of human rights and international humanitarian law, and related\ncrimes “in the context of the aggression” against Ukraine, see para. 11(a). The crime of\naggression is an international crime according to Article 8 bis of the Rome Statute. However,\neven though the International Criminal Court has received Ukraine’s two declarations\nrecognizing its jurisdiction, it does not have jurisdiction over alleged perpetrators with\nRussian nationality, as the Russian Federation is not a party to the Statute (see paras. 869870).\nNationals of non-State Parties cannot be prosecuted for the crime of aggression under Article\n15 bis(5) of the Rome Statute."},{"id":"a-hrc-52-crp-4-p0923","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"923","seq":925,"section":"2. Judicial authorities","text":"The Commission’s point of departure is that the International Criminal Court, with its\ngeneral mandate that includes 123 States from all continents, is now the most important\ncriminal court for the investigation and adjudication of international crimes. It is important\nthat States fully support its work – legally, politically, and practically. This includes various\nforms of cooperation and allocation of resources."},{"id":"a-hrc-52-crp-4-p0924","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"924","seq":926,"section":"2. Judicial authorities","text":"The International Criminal Court investigations in Ukraine, initiated by the\nProsecutor’s decision of 28 February 2022, are considering allegations of genocide, crimes\nagainst humanity and war crimes. As international criminal courts normally focus on persons\nin leadership position, it would not be surprising if this also forms part of the International\nCriminal Court prosecutorial strategy for Ukraine.624 Should the investigations result in trials\nagainst lead perpetrators based on genocide, crimes against humanity or war crimes, it may\nbe argued that evidence relating to acts of aggression can be taken into account during the\njudicial proceedings, both as context of the crimes and as an aggravating circumstance."},{"id":"a-hrc-52-crp-4-p0925","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"925","seq":927,"section":"2. Judicial authorities","text":"However, this course of action will not fully reflect the gravity of the crime of\naggression as such, which is a separate crime, different from the three other crimes. No other\nexisting international court can adjudicate allegations of the crime of aggression in the current\ncontext of Ukraine."},{"id":"a-hrc-52-crp-4-p0926","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"926","seq":928,"section":"2. Judicial authorities","text":"Several proposals have been launched for a special tribunal for the crime of aggression\nin Ukraine. The Commission’s main focus will be on three main public proposals for such a\ntribunal, in particular on the proposed way of establishing it. Several parliamentary\nassemblies and political leaders have, at least in principle, supported the idea of creating such\na tribunal.625"},{"id":"a-hrc-52-crp-4-p0927","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"927","seq":929,"section":"2. Judicial authorities","text":"This report does not contain an exhaustive review of all public proposals for a special\ntribunal and is not meant to diminish discussions of other initiatives. For instance, the Public\nInternational Law and Policy Group Draft Law for a High War Crimes Court within the\nUkrainian legal system, if adopted, would include the crime of aggression (see para. 860). It\nshould also be recalled that in other States with provisions relating to aggression, national\ncourts may consider this crime following investigations by the prosecuting authorities of their\ncountries."},{"id":"a-hrc-52-crp-4-p0928","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"928","seq":930,"section":"2. Judicial authorities","text":"The first of the three well-known public proposals (here referred to as option 1) was\nlaunched following Chatham House discussions on 4 March 2022.626 The initiators presented\na statement calling for the creation of a “Special Tribunal for the Punishment of the Crime of\nAggression against Ukraine”, including a draft declaration to be issued by States for the\nestablishment of the Special Tribunal.627 Subsequently, the statement has garnered over\n100 signatories such as former Heads of State and Government, and judges of international\ncourts.628"},{"id":"a-hrc-52-crp-4-p0929","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"929","seq":931,"section":"2. Judicial authorities","text":"The proposed special tribunal would be based on the same principles that guided the\nallies in establishing the International Military Tribunal and the Nuremburg trials. The special\ntribunal would be mandated to investigate acts of violence by the Russian Federation in\nUkraine and determine whether they constitute a crime of aggression. It is suggested that\ncountries should agree to grant jurisdiction arising under national criminal codes and general\ninternational law to a dedicated criminal tribunal and confer on its jurisdiction to investigate\nthe perpetrators of the crime of aggression with respect to Ukraine, including those who have\nmaterially contributed to or shaped the commission of that crime. 629"},{"id":"a-hrc-52-crp-4-p0930","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"930","seq":932,"section":"2. Judicial authorities","text":"A second proposal (option 2) focused on proceeding through the United Nations\nGeneral Assembly. On 22 June 2022, State representatives, academics and representatives of\ncivil society, at the invitation of the Permanent Missions of Latvia and Liechtenstein to the\nUnited Nations, met at the Yale Club in New York for a roundtable discussion exploring the\npolitical, technical and legal questions relevant for the creation of “A Special Tribunal for\nthe Crime of Aggression” via such a method. The proposal calls for the General Assembly to\nrecommend the creation of such a tribunal through an agreement between the United Nations\nand Ukraine, similar to the establishment of the Special Court for Sierra Leone and the\nExtraordinary Chambers in the Court of Cambodia. The United Nations Secretary-General\nwould operationalize such a recommendation by negotiating and concluding an agreement\nbetween the United Nations and Ukraine. Further details follow from the summary of the\ndiscussions, which refer to international judges and an international prosecutor, like in the\nad-hoc-tribunals established by the Security Council for the former Yugoslavia and Rwanda;\nit is not proposed to set up a hybrid tribunal with both international and national judges, as\nThere are also statements by national politicians, such as: Verkhovna Rada of Ukraine, “Resolution of\nthe Verkhovna Rada of Ukraine on the address of the Verkhovna Rada of Ukraine to the United Nations,\nthe European Parliament, the Parliamentary Assembly of the Council of Europe, the NATO\nParliamentary Assembly, the OSCE Parliamentary Assembly, the GUAM Parliamentary Assembly,\nand the national parliaments of foreign countries regarding the creation of a special international\ntribunal on the crime of aggression against Ukraine”, 7 October 2022 (available only in Ukrainian);\nGermany; Federal Foreign Office, “‘Strengthening international law in times of crisis’ – Speech by\nFederal Foreign Minister Annalena Baerbock in The Hague”, 16 January 2023.\nin the Special Court for Sierra Leone and Extraordinary Chambers in the Court of\nCambodia.630"},{"id":"a-hrc-52-crp-4-p0931","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"931","seq":933,"section":"2. Judicial authorities","text":"A third proposal (option 3) was launched by the Ukraine Task Force of the Global\nAccountability Network in September 2022. It is similar to option 2 in that it calls for the\nUnited Nations General Assembly to request the Secretary-General to negotiate an agreement\nwith Ukraine to create the tribunal. This proposal provides a draft United Nations General\nAssembly resolution and a draft statute for the tribunal modelled after the Special Court for\nSierra Leone – a hybrid tribunal with both international and national judges. The draft statute\ncontains detailed provisions. For instance, the tribunal’s temporal jurisdiction would be from\n20 February 2014 (Article 1). The United Nations Secretary-General would appoint the\nmajority of the judges whereas Ukraine would appoint the others with the concurrence of the\nSecretary-General (Article 8). That provision also contains alternative footnotes, according\nto which the Secretary-General would appoint all the judges, and with no reference to the\ndistinction between international and Ukrainian judges.631"},{"id":"a-hrc-52-crp-4-p0932","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"932","seq":934,"section":"2. Judicial authorities","text":"The discussions on the various proposals, and their specific elements, are on-going.\nOn 9 February 2023, at the Council of Europe, the Committee of Ministers’ Deputies held an\nexchange of views with the United Nations about accountability for human rights violations\nin Ukraine. On 3-5 March 2023, the Ukrainian authorities organized the United for Justice\nConference in the city of Lviv about accountability for core international crimes, focusing on\ninvestigations of the crime of aggression.632 The Commission has noted that the resolution\nadopted by the United Nations General Assembly on 24 February 2023 does not address the\nissue of a special tribunal.633 The Commission has also taken note that the Heads of State and\nGovernment of the Council of Europe in their Reykjavík Declaration of 17 May 2023\nwelcomed the progress towards the establishment of a special tribunal for the crime of\naggression as highlighted at the Summit of the Special Tribunal’s Core Group chaired by\nUkrainian President Zelenskyy.634"},{"id":"a-hrc-52-crp-4-p0933","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"933","seq":935,"section":"2. Judicial authorities","text":"In recent months, there have been discussions about an internationalized tribunal.\nOn 18 April 2023, the G7 Foreign Ministers supported exploring the creation of\nan internationalized tribunal based in Ukraine’s judicial system to prosecute the crime of\naggression against Ukraine.635 This follows the remarks on 27 March 2023 of the US\nAmbassador-at-Large for Global Criminal Justice announcing that the US supports the\ndevelopment of such a tribunal.636"},{"id":"a-hrc-52-crp-4-p0934","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"934","seq":936,"section":"2. Judicial authorities","text":"The Commission’s assessment: The proposals to set up a special tribunal to adjudicate\nthe crime of aggression have no equivalent in the ad hoc tribunals established since the 1990s,\nwhose powers did not cover that crime. The three options are all motivated by a wish to fill\nthe existing jurisdictional gap because the International Criminal Court cannot prosecute the\ncrime of aggression with respect to the armed conflict in Ukraine. Option 1 is based on States\ngranting jurisdiction to a dedicated tribunal, whereas options 2 and 3 are premised on the\ninvolvement of the General Assembly requesting the establishment of such a tribunal."},{"id":"a-hrc-52-crp-4-p0935","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"935","seq":937,"section":"2. Judicial authorities","text":"As mentioned above, the establishment of a new special court has received\nconsiderable general support by certain parliamentary assemblies and political leaders. 637\nThis said, most of these statements do not indicate a clear preference for any of the three\noptions. For instance, in the detailed report leading to the resolution adopted on 26 January\n630 A/ES-11/7-S/2022/616, Annex pp. 2-4. Further details related to Option 2 have been discussed by\nvarious international law academics and practitioners, see Just Security, U.N. General Assembly and\nInternational Criminal Tribunal for the Crime of Aggression Against Ukraine.\n631 Ukraine Taskforce of the Global Accountability Network, Proposal for a Resolution by the United\nNations General Assembly & Accompanying Proposal for a Statute of a Special Tribunal for Ukraine\non the Crime of Aggression, 7 September 2022, pp. 1, 7, 9-10. Lead writers were Hans Corell, Irvin\nCotler, David Crane and Lotta Lampela. See also Hans Corell, “A special tribunal on the crime of\naggression – The role of the U.N. General Assembly”, Just Security, 14 February 2023.\n632 Council of Europe, “Meeting of the Ministers’ Deputies on 8-9 February 2023”, press release.\n633 A/ES-11/L.7.\n634 Council of Europe, Reykjavík Declaration – United around our values, 16-17 May 2023, p. 5.\n635 Japan, Ministry of Foreign Affairs, G7 Japan 2023 Foreign Ministers’ Communiqué, 18 April 2023,\np. 2.\n636 United States of America, State Department, Ambassador Van Schaack’s Remarks on the U.S.\nProposal to Prosecute Russian Crimes of Aggression, 27 March 2023.\n637 See footnote 625 above.\n2023 by the Parliamentary Assembly of the Council of Europe, the view is expressed that, as\nthings stand, the final legal form of the instrument should be decided pragmatically, aiming\nto involve the largest possible number of States, ideally representative of different regions of\nthe world.638 Similarly, the European Parliament’s resolution of 19 January 2023 states that\nthe European Union should, in cooperation with other entities, try to find a legally sound,\ncommon way forward, and that the exact composition and method of operation of the special\ntribunal remain to be determined.639"},{"id":"a-hrc-52-crp-4-p0936","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"936","seq":938,"section":"2. Judicial authorities","text":"The on-going discussions have shown that the possible establishment of a special\ntribunal for aggression raises a wealth of issues; legal, political, technical and financial. The\nCommission is neither a political nor a legislative entity. However, being called upon to make\nrecommendations on accountability, and as an independent and impartial body, it will\nhighlight some considerations that in its view should be taken into account during the on-\ngoing reflection process."},{"id":"a-hrc-52-crp-4-p0937","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"937","seq":939,"section":"2. Judicial authorities","text":"As mentioned above, the International Criminal Court is the most important\ninternational criminal court, and the establishment of a special tribunal for aggression should\nnot affect its activities. There would be two independent courts with separate tasks; the crime\nof aggression is different from genocide, crimes against humanity and war crime. However,\nsome degree of cooperation and coordination between the two institutions may be advisable,\nfor instance with respect to sharing of evidence."},{"id":"a-hrc-52-crp-4-p0938","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"938","seq":940,"section":"2. Judicial authorities","text":"In parallel with the discussion of a possible special tribunal for aggression, it has been\nsuggested to revise Article 15 bis of the International Criminal Court Statute, which provides\nthat the crime of aggression may not be prosecuted against nationals of non-State Parties (see\npara. 870).640 The deletion of this limitation of the International Criminal Court’s jurisdiction\nwould reduce the need for special tribunals. It could also limit criticism based on selectivity\non the basis that special tribunals on aggression have not been set up in previous armed\nconflicts (see para. 939). On the other hand, the Commission notes that only 45 of the\n123 parties to the Statute have so far accepted Article 8 bis on the crime of aggression,641 and\nthat no reform proposals were made during the 21st session of the Assembly of State Parties\n(5-10 December 2022). A reform process will be complicated. Consequently, it is unclear if,\nor when, such a statutory amendment would come into force. There is also a question whether\nthe reform would make it legally possible for the International Criminal Court to investigate\nand prosecute allegations of crimes of aggression committed by nationals of the Russian\nFederation before the entry into force of the amendment.642"},{"id":"a-hrc-52-crp-4-p0939","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"939","seq":941,"section":"2. Judicial authorities","text":"Turning more specifically to a new special tribunal for aggression, the Commission\nemphasises the need to avoid doubts about its legitimacy, irrespective of which option that\nwill be chosen. This is important both with respect to the tribunal’s establishment and its\nfunctioning:"},{"id":"a-hrc-52-crp-4-p0940","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"940","seq":942,"section":"2. Judicial authorities","text":"The establishment of the special tribunal can be criticised as an expression of\nselectivity (“selective justice”), as there have been previous situations of aggression where\n638 Parliamentary Assembly of the Council of Europe (Committee on Legal Affairs and Human Rights),\nLegal and Human Rights aspects of the Russian Federation’s aggression against Ukraine, Report (Doc.\n15689), para. 22. This report led to the adoption by the Parliamentary Assembly of the Council of\nEurope of its resolution 2482 (2023) on 26 January 2023.\n639 European Parliament, Resolution 2022/3017 (RSP), paras. 3 and 6. See also, European Commission,\n“Ukraine: Commission presents options to make sure that Russia pays for its crimes”, press release, 30\nNovember 2022. The European Commission proposed alternative options: A special independent\ninternational tribunal based on a multilateral treaty, or a specialised court integrated in a national justice\nsystem with international judges – a hybrid court.\n640 See, for instance, Claus Kress, Stephan Hobe and Angelika Nussberger: “The Ukraine War and the\nCrime of Aggression: How to Fill the Gaps in the International Legal System”, Just Security, 23 January\n2023. Karim A.A. Khan KC, Prosecutor of the International Criminal Court, in his statement made on\n5 December 2022 to the opening plenary of the 21st session of the Assembly of States stated: “We don’t\nwant dilution, we want consolidation” (para. 21).\nno new institutions were set up, or it was not even proposed. 643 As regards aggression, there\nis, undeniably, some truth in this criticism. On the other hand, with respect to other crimes,\nthe international community did establish ad hoc tribunals because other courts, such as the\nInternational Criminal Court, did not exist or could not exercise jurisdiction. Well-known\nillustrations are the tribunals for the former Yugoslavia, Rwanda, Sierra Leone, and\nCambodia. A process aimed at amending the Rome Statute in parallel with the setting up a\nnew tribunal would demonstrate that the current conflict in Ukraine has shown “the\njurisdictional gap” in the International Criminal Court Statute and that the international\ncommunity is now seeking to fill it, based on a two-pronged approach."},{"id":"a-hrc-52-crp-4-p0941","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"941","seq":943,"section":"2. Judicial authorities","text":"A related legitimacy consideration is that a sufficient number of globally dispersed\nStates should support the establishment of a special tribunal.644 With respect to option 1, this\nwould require a satisfactory number of States granting jurisdiction to the new entity. As\nregards options 2 and 3, the main focus would be on the number and the regional distribution\nof votes behind a resolution by the General Assembly. The Commission is inclined to hold\nthe view that a resolution adopted by the United Nations General Assembly, based on\nprecedents from two previous ad hoc tribunals located outside Europe (Special Court for\nSierra Leone and the Extraordinary Chambers in the Court of Cambodia), would carry more\nweight, if supported by a sufficient number of regionally dispersed States. Furthermore,\nirrespective of the option chosen, it is necessary that Ukraine accept the final model."},{"id":"a-hrc-52-crp-4-p0942","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"942","seq":944,"section":"2. Judicial authorities","text":"As regards the functioning of a new tribunal, it is obvious that it must be independent,\nimpartial and observe all fair trial rights in international human rights conventions. In this\nreport, the Commission wants to address two aspects:"},{"id":"a-hrc-52-crp-4-p0943","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"943","seq":945,"section":"2. Judicial authorities","text":"The first issue relates to immunities of officials. There seems to be common ground\nthat international customary law on personal and functional immunities does not prevent that\nthe highest officials in a country are subject to criminal proceedings before international\ncourts.645 The Commission assumes that this issue will be considered carefully in connection\nwith the options at hand."},{"id":"a-hrc-52-crp-4-p0944","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"944","seq":946,"section":"2. Judicial authorities","text":"The second point is about trials in absentia, which are not prohibited by international\nhuman rights law, provided that certain conditions are met. 646 However, almost all\ninternational criminal tribunals have required the presence of the accused for trial, and for\nthe International Criminal Court this is stated explicitly in Article 63 of the Rome Statute.647\nSimilarly, in view of the gravity of the crime of aggression, as well as for legitimacy reasons,\nthe Commission recommends that a new special tribunal should adopt the same position."},{"id":"a-hrc-52-crp-4-p0945","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"945","seq":947,"section":"2. Judicial authorities","text":"More generally, principles of accountability and avoiding impunity call for\nan investigation and, based upon the evidence, prosecution of individual perpetrators,\naccused of international crimes, including the crime of aggression. This is important for the\nvictims, for society and the maintenance of international law.\n643  See previous International Criminal Court Prosecutor’s article: Luis Moreno Campo: “Ending\nSelective Justice for the International Crime of Aggression”, Just Security, 31 January 2023.\n644 See, for instance, European Parliament, Resolution 2022/3017 (RSP), paras. 3 and 4; Parliamentary\nAssembly of the Council of Europe, Resolution 2482 (2023), para. 6. See more generally about\nlegitimacy: Kai Ambos, “A Ukraine Special Tribunal with Legitimacy Problems?”, Verfassungsblog,\n6 January 2023.\n645 Arrest Warrant of 11 April 2000 (Democratic Republic of the Congo v. Belgium), Judgment, I.C.J.\nReports 2002, p. 3, para. 61; Special Court for Sierra Leone, Prosecutor v. Charles Ganthkay Taylor,\nCase No. SCSL-2003-01-I, Decision on Immunity from Jurisdiction, Appeals Chamber, 31 May\n2004, paras. 37-59; International Criminal Court, The Prosecutor v. Omar Hassan Ahmad Al-Bashir,\nJudgment in the Jordan Referral re Al-Bashir Appeal, Appeals Chamber, 6 May 2019, para. 113 (and\nmore generally, paras. 100-119). See also Advisory Committee on Public International Law,\nChallenges in prosecuting the crime of aggression: jurisdiction and immunities, Advisory report no.\n40, (The Hague, 2022), pp. 10-14 and 16.\n646 See, for instance, European Court of Human Rights, Poitrimol v. France, Application No. 14032/88,\nJudgment, 23 November 1993, para. 31; Sejdovic v. Italy, Application No. 56581/00, Judgment,\n1 March 2006, paras. 81-95; and Idalov v. Russia, Application 5826/03, Judgment, 22 May 2012 paras.\n169-174.\n647 Proposals have been made to amend the Rome Statute, such as implementing a timeframe for searching\nfor an accused who is the subject of an unsealed arrest warrant and for public announcements of the\ncharges, and then a procedure for possibly initiating proceedings in absentia."},{"id":"a-hrc-52-crp-4-p0946","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"946","seq":948,"section":"2. Judicial authorities","text":"Since there is currently no international court with jurisdiction to undertake this\nnecessary accountability measure, the Commission supports, in principle, the creation of a\ntribunal for the crime of aggression. The judicial proceedings would have to be in conformity\nwith international standards, take place before independent and impartial judicial institutions,\nand be perceived as having the required integrity and legitimacy. 648 Decision-makers would\nalso have to take into account that the establishment of a new tribunal will be time-\nconsuming, that it may be costly, and that years may pass before accused persons in\nleadership positions, if apprehended, are brought before the tribunal. The Commission also\nsupports efforts to amend the Rome Statute to allow for broader jurisdiction of the crime of\naggression within the Statute.\nPart II. Non-Judicial Forms of Accountability"},{"id":"a-hrc-52-crp-4-p0947","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"947","seq":949,"section":"H. Introduction","text":"The previous section of this chapter addressed a very important and perhaps the most\nfamiliar dimension of accountability, namely, criminal accountability, which, of course, can\nonly be achieved through judicial means. International law, however, includes other types or,\nbetter, dimensions, of accountability, including truth, reparation, and guarantees of non-\nrecurrence. While the full satisfaction of these rights will have to await the cessation of the\nconflict, it is important to recall the existence of these substantive obligations, and that,\nprocedurally, there are measures that can be taken already to either lay the bases for the\neventual satisfaction of the corresponding rights, or in any case, to contribute to the well-\nbeing of victims and to the gradual satisfaction of their rights."},{"id":"a-hrc-52-crp-4-p0948","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"948","seq":950,"section":"H. Introduction","text":"The most effective way of apprehending the scope of accountability under\ninternational law is by reviewing the resolution adopted unanimously by the General\nAssembly in 2005 entitled, “Basic Principles and Guidelines on the Right to a Remedy and\nReparation for Victims of Gross Violations of International Human Rights Law and Serious\nViolations of International Humanitarian Law.”649 After a 17 year-long process of\ndeliberation, the Assembly, in this resolution identifies “mechanisms, modalities, procedures\nand methods for the implementation of existing legal obligations under international human\nrights law and international humanitarian law …”, therefore reaffirming existing\ninternational obligations rather than introducing new ones.650"},{"id":"a-hrc-52-crp-4-p0949","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"949","seq":951,"section":"H. Introduction","text":"Given the protracted nature of the process leading to the adoption of the Resolution,\nthe deliberations took note of a wide diversity of legal instruments and experiences, including\nvaluable ‘soft law’ initiatives, such as the Declaration of Basic Principles of Justice for\nVictims of Crime and Abuse of Power.651 The Resolution refers directly to ‘harder’ sources\nand significant experiences, for instance, importantly, the Rome Statute of the International\nCriminal Court.652 The Resolution, of course, also makes reference to older, international\nhumanitarian treaty law obligations, including The Hague Convention, and the Geneva\nConventions and their Additional Protocols.653"},{"id":"a-hrc-52-crp-4-p0950","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"950","seq":952,"section":"H. Introduction","text":"The least surprising part of the Resolution, especially recalling the experience of the\nthree international tribunals that preceded its drafting, is the unambiguous assertion of the\nvictims’ right to criminal accountability. It summarizes existing obligations saying, “In cases\nof gross violations of international human rights law and serious violations of international\nhumanitarian law constituting crimes under international law, States have the duty to\ninvestigate and, if there is sufficient evidence, the duty to submit to prosecution the person\nallegedly responsible for the violations and, if found guilty, the duty to punish her or him”\n(para. 4). It reminds Member States of the duty to collaborate with one another if they are not\nin a position to fulfil said obligation themselves, encourages them to adopt legislation to make\nthe prosecution of cases under the principle of universal jurisdiction possible, and reminds\nthem that under treaty obligations, statutes of limitation cannot be applied to gross violations\nof international human rights law and serious violations of international humanitarian law\nwhich constitute crimes under international law (para. 9)."},{"id":"a-hrc-52-crp-4-p0951","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"951","seq":953,"section":"I. Reparations","text":"For the sake of this report, the most relevant reminder in the resolution concerns the\nvictims’ right to reparation. Of course, inter-state reparations have a long history in\ninternational relations. The leading opinion in this regard was set out in the often-cited 1927\njudgment of the Permanent Court of International Justice in the Chorzow Factory case: “It is\na principle of international law that the breach of an engagement involves an obligation to\nmake a reparation in an adequate form.”654 Closer to the concerns of this report, are, however,\nother instruments cited by the Resolution, including international humanitarian treaty law\nobligations (stemming from treaties to which both Ukraine and the Russian Federation are\nparties) such as The Hague Convention, Article 3 of which reads, “A belligerent party which\nviolates the provisions of the said Regulations shall, if the case demands, be liable to pay\ncompensation. It shall be responsible for all acts committed by persons forming part of its\narmed forces.”655 The same obligation is reiterated by the Geneva Conventions and their\nadditional protocols. Article 91 of the Additional Protocol I reads “A Party to the conflict\nwhich violates the provisions of the Conventions or of this Protocol shall, if the case\ndemands, be liable to pay compensation. It shall be responsible for all acts committed by\npersons forming part of its armed forces.”656"},{"id":"a-hrc-52-crp-4-p0952","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"952","seq":954,"section":"I. Reparations","text":"The right to reparation for violations of human rights has by now also become firmly\nentrenched in international human rights law, based on instruments that include the Universal\nDeclaration of Human Rights (Article 8),657 the International Covenant on Civil and Political\nRights, Article 2(3) of which states that each State Party to the present Covenant undertakes:\n(a) To ensure that any person whose rights or freedoms as herein recognized are violated\nshall have an effective remedy, notwithstanding that the violation has been committed by\npersons acting in an official capacity; (b) To ensure that any person claiming such a remedy\nshall have his right thereto determined by competent judicial, administrative or legislative\nauthorities, or by any other competent authority provided for by the legal system of the State,\nand to develop the possibilities of judicial remedy; (c) To ensure that the competent\nauthorities shall enforce such remedies when granted."},{"id":"a-hrc-52-crp-4-p0953","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"953","seq":955,"section":"I. Reparations","text":"The Convention against Torture and other Cruel, Inhuman or Degrading Treatment or\nPunishment states in Article 14 that each State Party shall ensure in its legal system that the\nvictim of an act of torture obtains redress and has an enforceable right to fair and adequate\ncompensation, including the means for as full rehabilitation as possible."},{"id":"a-hrc-52-crp-4-p0954","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"954","seq":956,"section":"I. Reparations","text":"Other instruments such as the International Convention on the Elimination of Racial\nDiscrimination (Article 6), and the Convention on the Rights of the Child (Article 39) assert\nthe same right. They are all duly mentioned in the “Basic Principles” Resolution. 658"},{"id":"a-hrc-52-crp-4-p0955","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"955","seq":957,"section":"I. Reparations","text":"The growing body of jurisprudence on both the substantive and procedural dimensions\nof the right to reparation demonstrates the consolidation of the victims’ right to reparation in\ninternational law. Treaty bodies and national, regional and international courts, including the\nInternational Court of Justice, the Inter-American Court of Human Rights, and the European\nCourt of Human Rights, have considered a large number of both individual cases and group\nclaims arising from periods of mass violations, and have developed a rich jurisprudence. That\njurisprudence has confirmed that reparation is a broad concept, which includes different\ncategories of initiatives to which victims have rights, namely, restitution, compensation,\nrehabilitation, satisfaction, and guarantees of non-repetition.659"},{"id":"a-hrc-52-crp-4-p0956","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"956","seq":958,"section":"I. Reparations","text":"In the addition to the long history of state-to-state reparations, and in particular the ad\nhoc compensation mechanisms established since the 1990s, most of which included\nprocedures for addressing individual claims,660 valuable experience with victim-centred,\nadministrative reparations programs established during the last 40 years as part of transitional\njustice policies,661 can provide valuable lessons for an eventual reparations program in\nUkraine, the costs of which must be borne by the Russian Federation."},{"id":"a-hrc-52-crp-4-p0957","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"957","seq":959,"section":"I. Reparations","text":"Some of the important lessons from these experiences that should be kept in mind\ninclude the following: (i) There is no reparation without acknowledgement of responsibility.\n(ii) Just as there is a difference between development programs and reparations programs,\nthere is a difference between general reconstruction programs and reparations programs. (iii)\nVictims need to be consulted on the design and implementation of such programs. (iv)\n‘Complex’ and ‘coherent’ programs, that is, programs that distribute a wider variety of\nbenefits in a way that the benefits complement and support each other, prove to be more\nsatisfactory to victims and their impact more sustainable than mere compensatory\nmechanisms.662"},{"id":"a-hrc-52-crp-4-p0958","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"958","seq":960,"section":"I. Reparations","text":"Although discussions about criminal justice have dominated the discussions about\naccountability more generally, calls for different forms of reparations have been present since\nthe early stages of the conflict, and over time, action in this domain has started to take shape,\nboth at the international level and within Ukraine."},{"id":"a-hrc-52-crp-4-p0959","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"959","seq":961,"section":"I. Reparations","text":"On 20 May 2022, President Zelenskyy called upon States to establish an international\nclaims commission.663 Claims commissions are generally flexible instruments established to\nresolve mass claims arising from international situations. 664"},{"id":"a-hrc-52-crp-4-p0960","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"960","seq":962,"section":"I. Reparations","text":"On 14 November 2022, the United Nations General Assembly adopted resolution\nA/RES/ES-11/5 entitled “Furtherance of remedy and reparation for aggression against\nUkraine”.665 The resolution recommends the creation of an international register of damage\nto serve as a record of evidence and claims information regarding damage, loss or injury to\nindividuals, legal persons and the State of Ukraine due to the unlawful conduct of the Russian\nFederation. Member States are to create the register. It will not necessarily be part of the\nUnited Nations. The resolution states the following about the register:"},{"id":"a-hrc-52-crp-4-p0961","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"961","seq":963,"section":"I. Reparations","text":"Recommends the creation by Member States, in cooperation with Ukraine, of an\ninternational register of damage to serve as a record, in documentary form, of evidence and\nclaims information on damage, loss or injury to all natural and legal persons concerned, as\nwell as the State of Ukraine, caused by internationally wrongful acts of the Russian\nFederation in or against Ukraine, as well as to promote and coordinate evidence-gathering.666"},{"id":"a-hrc-52-crp-4-p0962","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"962","seq":964,"section":"I. Reparations","text":"On 30 November 2022, European Commission President von der Leyen proposed the\ncreation of an international agreement for a structure to manage and invest blocked and\nfrozen Russian assets with the proceeds going to Ukraine.667 She estimated at the time that\nthe damage suffered by Ukraine was 600 billion euros and the blocked and frozen assets\namounted to 319 billion euros.668 Furthermore, she stated that “once the sanctions are lifted,\nthese funds should be used so that the Russian Federation pays full compensation for the\ndamages caused to Ukraine”.669"},{"id":"a-hrc-52-crp-4-p0963","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"963","seq":965,"section":"I. Reparations","text":"On 12 May 2023, the Committee of Ministers of the Council of Europe, adopted a\nResolution, establishing the Register of Damages first mentioned in the United Nations\nGeneral Assembly Resolution.670 The resolution creates the administrative apparatus of the\nRegistry. According to the resolution, the Register “shall serve as a record, in documentary\nform, of evidence and claims information on damage, loss or injury caused, on or after 24\nFebruary 2022, in the territory of Ukraine within its internationally recognised borders,\nextending to its territorial waters, to all natural and legal persons concerned, as well as the\nState of Ukraine, including its regional and local authorities, state-owned or controlled\nentities, by the Russian Federation’s internationally wrongful acts in or against Ukraine”\n(Article 1)"},{"id":"a-hrc-52-crp-4-p0964","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"964","seq":966,"section":"I. Reparations","text":"While the Register has only documentary purposes, and is not meant to distribute any\nbenefits, the resolution goes into some detail defining for example the functions of the\nExecutive Director, the Board, and the ‘Conference of Participants’ (representatives of\nmember states that support the Register); (Articles 5-7)."},{"id":"a-hrc-52-crp-4-p0965","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"965","seq":967,"section":"I. Reparations","text":"Crucial decisions, about the final shape of a reparations program in Ukraine remain to\nbe taken, including the financing modalities of such a program. There is no question that as\nthe aggressor State, the Russian Federation bears responsibility for the costs of reparations.\nAs paragraph 2 of the General Assembly resolution puts it: “Recognizes that the Russian\nFederation must be held to account for any violations of international law in or against\nUkraine, including its aggression in violation of the Charter of the United Nations, as well as\nany violations of international humanitarian law and international human rights law, and that\nit must bear the legal consequences of all of its internationally wrongful acts, including\nmaking reparation for the injury, including any damage, caused by such acts”."},{"id":"a-hrc-52-crp-4-p0966","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"966","seq":968,"section":"I. Reparations","text":"The great difficulty is how to enforce that obligation on an unwilling State. Calls for\nthe use of Russian Federation assets that have been frozen abroad are frequent, but there is a\nbig step between freezing and confiscating assets, and this partly explains why frozen assets\nhave seldom been sources of financing for reparations efforts. 671"},{"id":"a-hrc-52-crp-4-p0967","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"967","seq":969,"section":"I. Reparations","text":"The Government of Ukraine has already taken some steps to assist victims that can be\ninterpreted in the key of reparations. It has, for example, provided pensions and other form\nof social assistance for families who have lost the breadwinner, for those with conflict-related\ndisabilities, and has also made available funeral assistance."},{"id":"a-hrc-52-crp-4-p0968","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"968","seq":970,"section":"I. Reparations","text":"Furthermore, three laws on reparations, one that would provide interim reparations for\nvictims of conflict related sexual violence; one to provide assistance for the reconstruction\nof houses and other properties; and a more general law on reparations for various categories\nof victims, have been submitted to the Ukrainian parliament. The latter law, for example,\nwould provide compensation for victims of death and disappearance, injuries, disability,\n666 Ibid., para. 4.\n667 European Union, “Statement by President Ursula von der Leyen on Russian accountability and the use\nof Russian frozen assets”, 30 November 2022.\n668 Ibid.\n669 Ibid.\n670 Council of Europe, Committee of Ministers, Resolution establishing the Enlarged Partial Agreement\non the Register of Damage Caused by the Aggression of the Russian Federation Against Ukraine,\nCM/Res(2023)3, 12 May 2023.\n671 Even when assets are seized by a state to be transferred to another, there is some reluctance to ’earmark’\nwhat the receiving state should do with the assets transferred. Victims’ reparations do not usually stack\nhigh in the list of priorities under these circumstances.\nvarious forms of conflict related violence including sexual violence, human trafficking,\ntorture, imprisonment, captivity, forced labour, deportation, child abduction and forced\ndisplacement, as well as psychological trauma.672"},{"id":"a-hrc-52-crp-4-p0969","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"969","seq":971,"section":"I. Reparations","text":"The Commission’s assessment: The Commission welcomes that planning for\nreparations both at the international and the national level have started. It would like,\nhowever, to offer the following observations and recommendations. While national\nreconstruction plans, property restitution, and victims reparations are related projects, they\nare not identical. The General Assembly and the Council of Europe resolutions on the\nRegister of Damages are not completely clear about the differences (and in their lack of\nreference to victims, lean more towards the tallying of damages characteristic of\nreconstruction and property restitution)."},{"id":"a-hrc-52-crp-4-p0970","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"970","seq":972,"section":"I. Reparations","text":"The reconstruction of Ukraine is, of course, going to be a gargantuan task especially\ntaking into account the long-standing attacks on the country’s civilian infrastructure (see\nparas. 267-272).673 Quite aside from the reconstruction project, which might take the familiar\nform of inter-state reparation, there is, as we have seen, a right of individual victims to\nreparations."},{"id":"a-hrc-52-crp-4-p0971","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"971","seq":973,"section":"I. Reparations","text":"Designing a full-fledged reparations program under conditions of ongoing conflict is\nvirtually impossible: it is impossible to plan for a program when the universe of victims keeps\ngrowing, it is impossible to engage in the sort of meaningful and sustained consultations with\nvictims that are necessary for the establishment of a successful program; and of course, the\nconditions for the provision of a complex set of reparative benefits do not obtain as the\ncountry’s infrastructure is under severe attack."},{"id":"a-hrc-52-crp-4-p0972","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"972","seq":974,"section":"I. Reparations","text":"Nevertheless, there are initiatives that can be started, some of which will help to lay\nthe bases of a future reparations program and make a contribution to the well-being of victims\n(without transferring the ultimate responsibility for bearing the costs of reparations from the\nRussian Federation to the Ukrainian government). The first is to establish a registry of victims\n(which is not the same as a registry of damages). There is no reparations program that can\nfunction without such registry. In this case, given the on-going nature of the conflict, the\nregistry per force must be open-ended. It must be ‘user-friendly,’ procedurally light on users,\nand initially concentrate on the harms and violations that are more central to the victims’\ndignity and well-being rather than on property issues.674"},{"id":"a-hrc-52-crp-4-p0973","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"973","seq":975,"section":"I. Reparations","text":"The Registry should not be conceived merely as a list but should ideally be\nan ‘institutional portal’ to organize various support initiatives already provided by the\ngovernment, but in a disaggregated and uncoordinated way. It is very difficult for victims to\nnavigate different bureaucratic hurdles, especially when they have suffered great harms and\nfor example, are internally displaced. It would make a big difference to them if there was a\n‘one-stop shop’ that would provide assistance with legal matters (e.g., lost documents),\neducational issues, health needs, interim economic support, etc. This does require\ninstitutional coordination, but it is not unfeasible at all, and it is something that the\ninternational community can support."},{"id":"a-hrc-52-crp-4-p0974","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"974","seq":976,"section":"I. Reparations","text":"Countries that have engaged in such efforts have found it necessary to establish inter-\nministerial groups led by either the Prime Minister’s or the President’s office, as the case\nmight be, in order to guarantee that the coordination indeed takes place. The Commission is\naware of the proposals made by the International Organization for Migration and by the\nInternational Claims and Reparations Project of Columbia Law School and is encouraged by\nthe fact that the topic of victims’ reparations is receiving some attention from the government.\nThe Commission however, encourages a step-wise process that takes full account of the fact\nthat under conflict situations a full-fledged reparation program cannot be designed, let alone\ndelivered. While the Commission encourages advance planning and the taking of preparatory\nsteps, it warns against awakening expectations on the part of victims in the absence of\ncertainty that those expectations can be fully satisfied. In particular, assumptions about\nsources of financing (e.g., recovered assets) that may not materialize, should temper the\nplanning and sequencing of the type of benefits and the classes of beneficiaries that may be\nserved by a reparations plan at any given point."},{"id":"a-hrc-52-crp-4-p0975","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"975","seq":977,"section":"I. Reparations","text":"Consistent with the idea of prioritizing benefits and beneficiaries, it would make a\nsignificant difference to the well-being of victims to work on the provision of mental health\nand psychosocial support—accessible through the same institutional portal just mentioned.\nThat there is a need for doing so there can be no doubt; “according to Ukraine’s Health\nMinistry, more than 90 per cent of Ukrainians have one or more symptoms of post-traumatic\nstress disorder due to the ongoing war. It is estimated that only three in every 100 Ukrainians\nwith post-traumatic stress disorder are receiving support.”675 The Commission has visited\ncivil society organizations that are providing such services in Ukraine. Given the magnitude\nof needs, however, such initiatives need to be scaled up significantly, coordinated, and\nultimately connected with the institutional network of the State (even if the end-providers\ncontinue to be civil society organizations)."},{"id":"a-hrc-52-crp-4-p0976","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"976","seq":978,"section":"I. Reparations","text":"Again, the Commission is aware of the operational roadmap entitled “Ukrainian\nPrioritized Multisectoral Mental Health and Psychosocial Support Actions During and After\nthe War” and is encouraged by the attention this topic is receiving.676 Making the roadmap a\nreality calls for the allocation of resources to the relevant services, and moreover, to\nenhancing coordination between service providers, establishing legal regulations, and the\nmeans for monitoring and evaluating services to be provided to an extremely vulnerable\npopulation at sufficient scale. This is another task where the international community would\nbe wise to spend some efforts and lend both expertise and resources. Making sure that\nUkrainian refugees are not left out of long-term support programming is also crucial. Support\nprograms are often short-term crisis interventions. However, the mental-health needs of the\nUkrainian population that moved abroad under duress and frequently after witnessing or\nexperiencing acts of violence do not cease."},{"id":"a-hrc-52-crp-4-p0977","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"977","seq":979,"section":"J. Truth","text":"In addition to the brief summaries of the rights of victims regarding criminal\naccountability and reparations even in cases of conflict when international humanitarian law\nor international human rights laws are violated, the Basic Principles critically reminds us that\nthere are other elements of accountability to which victims also have rights. Those include a\nright to truth, which the resolution puts succinctly in the following terms: “victims and their\nrepresentatives should be entitled to seek and obtain information on the causes leading to\ntheir victimization and on the causes and conditions pertaining to the gross violations of\ninternational human rights law and serious violations of international humanitarian law and\nto learn the truth in regard to these violations” (para. 24)."},{"id":"a-hrc-52-crp-4-p0978","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"978","seq":980,"section":"J. Truth","text":"The sources of the right to truth cited by the Basic Principles are, as in the case of the\nother rights the Resolution identifies, varied.677 They include treaty body commentaries,678\nHuman Rights Council Resolutions,679 Reports of Special Procedures,680 as well other\ninternational instruments, such as the Convention on the Protection of All Persons from\nEnforced Disappearances.681"},{"id":"a-hrc-52-crp-4-p0979","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"979","seq":981,"section":"J. Truth","text":"Regional Courts have developed ample jurisprudence relying upon and elaborating\nthe right to truth. The Inter-American Commission and Court of Human Rights were at the\nforefront of developing jurisprudence on the right to truth of the victim, his/her next of kin,\nand the whole of society. In relation to the collective nature of this right, the Commission\nobserved that “[e]very society has the inalienable right to know the truth about past events,\nas well as the motives and circumstances in which aberrant crimes came to be committed, in\norder to prevent repetition of such acts in the future”.682 In a more recent judgment, the Court\nframed the right to truth in the form of a positive State obligation stressing that “the next of\nkin of the victims and society as a whole must be informed of everything that has happened\nin connection with the said violations.”683 The African Commission on Human and Peoples’\nRights has recognized the right to truth as an aspect of the right to an effective remedy for a\nviolation of the African Convention.684 In connection with gross human rights violations\ncommitted in the context of countering terrorism, the European Court of Human Rights\nacknowledged the right to truth not only for victims and their families but for the general\npublic as well.685"},{"id":"a-hrc-52-crp-4-p0980","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"980","seq":982,"section":"J. Truth","text":"This substantive right to information is operationalized frequently in national conflicts\nvia the establishment of truth commissions. There is no single mechanism that has been used\nto turn this into a procedural right in the case of international conflicts, where a combination\nof fact-finding and investigatory commissions, along judicial fact-finding, as well as the\nunofficial efforts by civil society organizations, seek to contribute to the satisfaction of this\nright. For victims, truth (regarding various issues, foremost amongst which is the\nwhereabouts of people who have been disappeared) is essential. While vast experience has\nbeen accumulated by the more than 50 countries that have established truth commissions in\nthe wake of massive human rights abuses, sometimes in the context of internal conflict, in\ncases of international conflict there is much work to be done in order to satisfy the victims’\nright to truth."},{"id":"a-hrc-52-crp-4-p0981","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"981","seq":983,"section":"J. Truth","text":"The right to truth is another one the full realization of which will have to wait the\ncessation of the conflict and will also require the collaboration of Russian Federation\nauthorities. Again, a full reckoning cannot possibly be achieved under conditions of open and\nmassive conflict. Some truth is emerging from various sources official and unofficial, judicial\nand non-judicial. But these are fragments of a broader story, the full details of which need\nRussian sources and cooperation."},{"id":"a-hrc-52-crp-4-p0982","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"982","seq":984,"section":"J. Truth","text":"But just as the fact that the full realization of the right to reparation will need to await\nthe cessation of conflict and involves the satisfaction of legal obligations by the Russian\nFederation does not mean that there are no measures that can be initiated at present which\nwill contribute to the realization of that right, the same applies regarding the right to truth."},{"id":"a-hrc-52-crp-4-p0983","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"983","seq":985,"section":"J. Truth","text":"For example, all conflicts generate important needs concerning information about\nmissing persons.686 In contrast to, for example, other national conflicts between State forces\nand more or less informal non-State parties, there is no question that in the case of the\naggression against Ukraine, the Geneva Conventions apply. This means that provisions of\nthe Third Convention apply to prisoners of war and provisions of the Fourth Convention\napply to civilians."},{"id":"a-hrc-52-crp-4-p0984","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"984","seq":986,"section":"J. Truth","text":"Regarding the Third Geneva Convention, for purposes of contributing to the right to\ntruth, the full compliance with Articles 122 and 123 are most urgent. Both articles regulate\nthe establishment and functioning of instruments that collect and make available information\nregarding persons covered by Article 4 of the Convention, in this case persons under the\ncontrol of a Detaining Power. Article 122 mandates the establishment of, and regulates the\ninformation collection and flow by, Information Bureaux, and Article 123 calls for the\nestablishment of a Central Prisoners of War Information Agency in a neutral country. These\nmechanisms are intended to ensure that families know the fate and whereabouts of their\nrelatives and to prevent disappearances.687"},{"id":"a-hrc-52-crp-4-p0985","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"985","seq":987,"section":"J. Truth","text":"The Fourth Geneva Convention, in Articles 136-139 establishes parallel obligations\nconcerning protected persons held by parties to the conflict, including the establishment of\nInformation Bureaux."},{"id":"a-hrc-52-crp-4-p0986","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"986","seq":988,"section":"J. Truth","text":"The Convention on the Protection of All Persons from Enforced Disappearances also\nimposes obligations that are relevant to the urgent task of gathering information about\nmissing persons, and in this sense, relevant to the initial steps of satisfying the right to truth. 688\nArticle 3 of the Convention expresses the obligation on the part of States to investigate\ndisappearances both those associated to its own agents and those that may have been the\nresponsibility of others. The full set of obligations and corresponding rights are spelled out\nin the “Guiding principles for the search for disappeared persons,” adopted by the Committee\non Enforced Disappearances in 2018.689"},{"id":"a-hrc-52-crp-4-p0987","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"987","seq":989,"section":"J. Truth","text":"Ordinary judicial and investigative authorities are seldom adequate to the task of\naddressing the problem of missing persons left in the wake of conflict; part of the problem\nhas to do with the immense caseload, part of it with lack of the necessary competencies\n(including sufficient and appropriate forensic competencies), but also with functional factors;\njudicial and related investigative authorities, are by design, more interested in the\nidentification of perpetrators than on the resolution of the fate and whereabouts of the victims.\nRecalling that the resolution of missing person cases cannot be reduced to ‘finding and\nreturning bones,’ but that it involves sensitive issues including high levels of interactions\nwith relatives in order to collect ante mortem information, the investigation of facts that come\nfrom a wide variety of sources,690 (the sharing of post mortem information with family\nmembers, the culturally sensitive handling and return of remains, helps to understand the\nlimitations of ordinary judicial bodies in dealing with this problem. 691"},{"id":"a-hrc-52-crp-4-p0988","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"988","seq":990,"section":"J. Truth","text":"These limitations help explain why several countries have chosen to establish\nspecialized bodies (‘Missing Persons Units’) to address the challenges of missing persons.\nThese multidisciplinary entities become the point of contact between relatives and authorities\nand can be an important part (and in many cases, the entry point) to the ‘institutional portal’\nthat coordinates services and support to victims mentioned above. While their ad hoc nature\nmakes them independent and nimble, and usually more responsive to victims, they are no\n687 In practice, these functions are usually performed by the International Committee of the Red Cross\nCentral Tracing Agency, one of the many reasons why granting the institution untrammelled access to\nsensitive combat areas, including detention facilities is so crucial. See, for example, International\nCommittee of the Red Cross, Commentary on the Third Geneva Convention 2nd Edition, (Cambridge,\nCambridge University Press, 2021), Part V, especially pp. 1707-1765 on articles 122 and 123.\n688 United Nations, Treaty Series, vol. 2716, No. 48088, p. 3; The convention entered into force on 23\nDecember 2010.\n689 See, CED/C/7 (2018).\n690 Such sources include national authorities and institutions such as police, army, hospitals, cemeteries\nand forensic institutions; witnesses, anonymous or not; members of the families concerned; victims;\nthe adverse party or parties; or even the perpetrators themselves, as well as international bodies\nincluding multinational forces, international/regional organizations and entities, and\ninternational/foreign tribunals. Neither the large number nor some of these are the usual interlocutors\nof national judicial authorities. See Monique Crettol et al., “Establishing mechanisms to clarify the fate\nand whereabouts of missing persons”, p. 612.\n691 See, e.g., Mercedes Salado Puerto et al., “The search process: Integrating the investigation and\nidentification of missing and unidentified persons”, Forensic Science International: Synergy, Vol. 3,\n2021.\npanacea, but they do help, and when they do, constitute a first step in satisfying the right to\ntruth and providing additional support to victims. 692"},{"id":"a-hrc-52-crp-4-p0989","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"989","seq":991,"section":"J. Truth","text":"The Commission has concentrated in this section mainly in actionable first steps that\ncan start to give procedural reality to the substantive rights of victims beyond their right to\ncriminal justice, consistent with a well-established wide understanding of accountability that\nis victim-centred. It does not mean to suggest that these initial steps fully satisfy the rights to\nreparations and to truth. About the right to non-repetition, which as mentioned before, some\ntake to be a part of reparation, some an independent right, the Commission will make\nsimilarly initial recommendations in the section on the root causes of the conflict.\nVIII.    Conclusions and recommendations693"},{"id":"a-hrc-52-crp-4-p0990","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"990","seq":992,"section":"J. Truth","text":"The armed conflict in Ukraine has had devastating effects at various levels, most\nnotably on individuals, communities, the society, the environment, and the economy of\nUkraine. It has affected considerably the enjoyment of almost all human rights. People live\nin a climate of unbearable uncertainty and fear. Scores of survivors are coping with the\nimmediate consequences of violent events and large-scale damage. In addition to the many\nphysical injuries that will need time to heal, the deep psychological impact will have long-\nlasting effects."},{"id":"a-hrc-52-crp-4-p0991","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"991","seq":993,"section":"J. Truth","text":"The Commission is concerned with the number, the geographic spread, and the gravity\nof human rights violations and corresponding international crimes which it has documented\nduring its mandate. These have affected men, women, boys and girls of all backgrounds and\nages."},{"id":"a-hrc-52-crp-4-p0992","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"992","seq":994,"section":"J. Truth","text":"It has concluded that that Russian authorities have committed numerous violations of\ninternational humanitarian law and violations of international human rights law, in addition\nto a wide range of war crimes, including the war crime of excessive incidental death, injury,\nor damage, wilful killings, torture, inhuman treatment, unlawful confinement, rape, as well\nas unlawful transfers and deportations. The Commission has also found that the Russian\narmed forces attacks, starting 10 October 2022, on Ukraine’s energy-related infrastructure\nand the use of torture by Russian authorities may amount to crimes against humanity."},{"id":"a-hrc-52-crp-4-p0993","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"993","seq":995,"section":"J. Truth","text":"In a limited number of cases, the Commission has found that the Ukrainian armed\nforces were likely responsible for violations of international humanitarian law and human\nrights law, and for some incidents which qualify as war crimes. The former include\nindiscriminate attacks and two incidents of wounding and torture of Russian prisoners of war."},{"id":"a-hrc-52-crp-4-p0994","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"994","seq":996,"section":"J. Truth","text":"Beyond sharing their deep loss and trauma with the Commission, survivors have\nhighlighted the importance of identifying those responsible and bringing them to account.\nOne man, whose father was executed by Russian armed forces in the Izium region, told the\nCommission: “They punished innocent people; now those who are guilty, if they are still\nalive, need to be punished to the fullest extent.”"},{"id":"a-hrc-52-crp-4-p0995","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"995","seq":997,"section":"J. Truth","text":"The Commission recommends that the parties to the conflict:\n(a)    Respect and ensure compliance of all obligations stipulated in relevant treaties\nand customary international law regarding international humanitarian law, international\nhuman rights law and international criminal law;\n(b)    Comply with all the obligations enshrined in international humanitarian law,\nincluding keeping accurate records of all people under the control of each party and\nexchanging information on that basis;\n(c)    Ensure that the International Committee of the Red Cross has unrestricted\naccess to carry out its work in accordance with its mandate under international law;\n(d)    Protect and respect the space for humanitarian action from disinformation,\npolitization, and polarization;\n692 See, e.g., the useful comparative study of search commissions in Latin America by Verónica\nHinestroza, Iris Jave, and Rainer Huhle “Comisiones de búsqueda en América Latina” (Mexico,\nGIZ/FED, September 2021).\n693 The conclusions and recommendations of this report remain the same as those in the Commission’s\n16 March 2023 report to the Human Rights Council (A/HRC/52/62).\n(e)     Take all feasible measures, in line with international standards, to locate all\nthose disappeared or missing – women, men, girls and boys, establish their fate and ensure\ncommunication with their families;\n(f)     Ensure the timely, effective, thorough, independent, impartial and transparent\ninvestigation and prosecution of all allegations of international crimes, violations of human\nrights and international humanitarian law, including sexual and gender-based violence and\nviolence against children;\n(g)     Hold all perpetrators accountable through judicial proceedings in accordance\nwith international human rights standards;\n(h)     Take all necessary steps in order to ensure that all victims’ right to truth is\nsatisfied and that they eventually obtain redress and remedy, including compensation and\nrehabilitation;\n(i)     Ratify international instruments to which they are not yet party and which will\nstrengthen the protection of civilians in armed conflict."},{"id":"a-hrc-52-crp-4-p0996","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"996","seq":998,"section":"J. Truth","text":"The Commission recommends that the Russian Federation immediately:\n(a)    Cease aggression and all acts of violence committed against civilians in\nviolation of applicable international human rights and international humanitarian law and end\nthe use of torture and other forms of ill-treatment, including sexual and gender-based\nviolence;\n(b)    Take all feasible precautions to protect civilians and civilian infrastructure and\nend massive attacks against energy-related infrastructure in Ukraine;\n(c)    Provide reliable and comprehensive information about the number and the\nwhereabouts of all children that have been transferred within or deported from Ukraine to the\nRussian Federation for whatever reason; facilitate effective communication between children\nand their families, and promptly and proactively initiate their return to Ukraine in accordance\nwith their best interests and with international obligations using technical assistance from\ninternational organisations; and prevent any further transfers within and deportation of\nchildren from Ukraine.\n(d)    Release or return to Ukraine all Ukrainian civilians who have been deported to\nthe Russian Federation and are detained there as a consequence of the armed conflict."},{"id":"a-hrc-52-crp-4-p0997","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"997","seq":999,"section":"J. Truth","text":"The Commission further recommends that the Russian Federation:\n(a)     Ensure that all perpetrators, including commanders and other superiors, and\nthose ordering, soliciting or inducing the commission of international crimes, are held\naccountable;\n(b)     Take the necessary measures to prevent the commission of such violations and\ncrimes, in particular through unequivocal instructions to all branches of the armed forces and\nother entities participating in the armed conflict with a view to ensure that military discipline\nand respect for international human rights and humanitarian law is upheld along with the\nprinciple of command responsibility;\n(c)     Limit the use of private military and security companies in the conflict, as\nexperience shows that these, on the one hand, lying outside formal lines of command, and on\nthe other, having a great incentive to compete with one another, and with regular forces,\nfrequently engage in violations of international law, and are generally less accountable than\nregular forces;\n(d)     Respect international humanitarian law applicable to occupied territories and\nrefrain from placing any impediment to humanitarian assistance in those territories;\n(e)     Cooperate fully with all international monitoring and investigative bodies."},{"id":"a-hrc-52-crp-4-p0998","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"998","seq":1000,"section":"J. Truth","text":"The Commission recommends that Ukraine:\n(a)    As a preliminary step towards a comprehensive reparations program, establish\na victim registry as an ‘institutional portal’ for better coordination of available government\nservices to victims;\n(b)    In light of its “Operational Roadmap”, comprehensively address mental health\nand psychosocial needs resulting from the armed conflict by tackling access and allocation\nof resources to the relevant services as well as enhancing their institutional coordination,\nlegal regulation, monitoring, and evaluation;\n(c)      Harmonise its legislation related to war crimes where it is not in conformity\nwith international standards, and amend its criminal code to clarify the definition of\n\"collaborative activity\" to avoid legal uncertainty and harm to social cohesion;\n(d)      Taking into account both the enormous case load and limited resources,\ndevelop an investigatory and prosecutorial strategy, which will prioritise cases on the basis\nof clear criteria and ensure due process and transparent monitoring."},{"id":"a-hrc-52-crp-4-p0999","rec_id":"recossC69zLk92qJ6","symbol":"A/HRC/52/CRP.4","n":"999","seq":1001,"section":"J. Truth","text":"The Commission recommends that other States and regional and international\norganizations:\n(a)    Strengthen national, regional and international accountability mechanisms\n(both judicial and non-judicial), including by improving their coordination, and supporting\nthe effective participation of civil society and victims’ and survivors’ groups;\n(b)    Further integrate the human rights dimensions of the armed conflict in Ukraine\nmore fully into the Security Council’s agenda."},{"id":"a-hrc-52-62-u0000","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":null,"seq":0,"section":null,"text":"United Nations                                                                                    A/HRC/52/62\nGeneral Assembly                                                            Distr.: General\n25 September 2023","unnumbered":true},{"id":"a-hrc-52-62-u0001","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":null,"seq":1,"section":null,"text":"Summary\nIn the present report, submitted pursuant to Human Rights Council resolution 49/1,\nthe Independent International Commission of Inquiry on Ukraine outlines its main findings\nsince the outset of its mandate. The body of evidence collected shows that the authorities of\nthe Russian Federation have committed a wide range of violations of international human\nrights law and international humanitarian law in many provinces of Ukraine and in the\nRussian Federation. Many of these violations amount to war crimes and include wilful\nkillings, attacks on civilians, unlawful confinement, torture, rape and the forced transfer and\ndeportation of children.\nThe Commission concludes that the armed forces of the Russian Federation have\ncarried out attacks with explosive weapons in populated areas with an apparent disregard for\ncivilian harm and suffering. The Commission has documented indiscriminate and\ndisproportionate attacks and a failure to take precautions, in violation of international\nhumanitarian law.\nIn addition, the Commission finds that the waves of attacks by the armed forces of\nthe Russian Federation, starting on 10 October 2022, on the energy-related infrastructure of\nUkraine and the use of torture by the authorities of the Russian Federation may amount to\ncrimes against humanity. It recommends further investigations.\nThe Commission has documented a small number of violations committed by the\nUkrainian armed forces, including likely indiscriminate attacks and two incidents that\namount to war crimes.\nLastly, the Commission recommends that all violations and crimes be investigated\nand that those responsible be held accountable at either the national or the international level.\nIt calls for a comprehensive approach to accountability that includes both criminal\nresponsibility and the victims’ right to truth, reparation and non-repetition.","unnumbered":true},{"id":"a-hrc-52-62-p0001","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"1","seq":2,"section":"I. Introduction","text":"In its resolution 49/1 of 4 March 2022, the Human Rights Council established the\nIndependent International Commission of Inquiry to investigate all alleged violations and\nabuses of human rights and violations of international humanitarian law and related crimes\nin the context of the aggression against Ukraine by the Russian Federation. On 30 March\n2022, the President of the Human Rights Council appointed Jasminka Džumhur (Bosnia and\nHerzegovina), Pablo de Greiff (Colombia) and Erik Møse (Norway) to serve as independent\nmembers of the Commission, with Mr. Møse serving as Chair."},{"id":"a-hrc-52-62-p0002","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"2","seq":3,"section":"I. Introduction","text":"On 12 May 2022, the Human Rights Council, in its resolution S-34/1, requested the\nCommission to conduct an inquiry to address the events in Kyiv, Chernihiv, Kharkiv and\nSumy Provinces that had occurred in late February and in March 2022. The corresponding\nfindings are contained in the report submitted by the Commission on 18 October 2022 to the\nGeneral Assembly. 1 The present report reflects the findings of the Commission since its\ncreation."},{"id":"a-hrc-52-62-p0003","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"3","seq":4,"section":"I. Introduction","text":"In line with its independence and impartiality, the Commission has assessed whether\nthe situation in Ukraine is an act of “aggression against Ukraine by the Russian Federation”,\nas stated by the Human Rights Council in its resolution 49/1. In accordance with the\ndefinition of aggression approved by the General Assembly in its resolution 3314 (XXIX),\nthe Commission has found reasonable grounds to conclude that the invasion and attacks by\nthe armed forces of the Russian Federation2 against the territory and armed forces of Ukraine\nqualify as acts of aggression against Ukraine.3"},{"id":"a-hrc-52-62-p0004","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"4","seq":5,"section":"I. Introduction","text":"To conduct its investigation, the Commission travelled eight times to Ukraine and\nvisited 56 cities, towns and settlements. It also travelled to Estonia and Georgia to meet\npeople who had fled from areas affected by the armed conflict. The Commission conducted\n610 interviews with 595 persons (348 women and 247 men), in person and remotely;\ninspected sites of destruction, graves, places of detention and torture, and weapon remnants;\nand consulted documents, photographs, satellite imagery and videos."},{"id":"a-hrc-52-62-p0005","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"5","seq":6,"section":"I. Introduction","text":"The Commission is grateful for the access and written responses to its queries\nprovided by Ukrainian officials. It regrets that its attempts to establish meaningful\ncommunication with the Russian Federation have been unsuccessful, its notes verbales and\nletters remaining unanswered. A governmental institution of the Russian Federation referred\nmaterial to the Commission, which it has examined."},{"id":"a-hrc-52-62-p0006","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"6","seq":7,"section":"I. Introduction","text":"In its work, the Commission is guided by the principles of independence, impartiality,\nobjectivity and integrity. It has adopted a victim-centred approach and is committed to the\n“do no harm” principle. Consistent with the standard of proof followed by most international\ncommissions of inquiry, namely “reasonable grounds to conclude”, the Commission has\nreached determinations that, on the basis of a body of verified information, an objective and\nordinary prudent observer would also reach in concluding that the facts had taken place as\ndescribed."},{"id":"a-hrc-52-62-p0007","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"7","seq":8,"section":"I. Introduction","text":"Owing to the large number of relevant events, security and logistical constraints and\nchallenges relating to the investigation of certain issues, the Commission has concentrated\non samples of allegations and on cases that illustrate specific patterns."},{"id":"a-hrc-52-62-p0008","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"8","seq":9,"section":"I. Introduction","text":"The Commission expresses its gratitude to all those who shared testimonies and other\nvaluable information, responded to its call for submissions – including 38 teenagers who sent\nletters – and facilitated its work. It appreciates the assistance provided by Governments,\nUnited Nations agencies, other international organizations and non-governmental entities."},{"id":"a-hrc-52-62-p0009","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"9","seq":10,"section":"II. Legal framework","text":"Pursuant to resolution 49/1, international human rights law, international\nhumanitarian law and international criminal law constitute the law applicable to the mandate\nof the Commission."},{"id":"a-hrc-52-62-p0010","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"10","seq":11,"section":"II. Legal framework","text":"The Russian Federation and Ukraine are party to seven and eight core United Nations\ninternational human rights instruments respectively. They are also bound by various\ninternational humanitarian law instruments, including the four Geneva Conventions of\n12 August 1949. The situation in Ukraine is an international armed conflict, pursuant to\ncommon article 2 of the four Conventions."},{"id":"a-hrc-52-62-p0011","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"11","seq":12,"section":"II. Legal framework","text":"Neither the Russian Federation nor Ukraine is a State party to the Rome Statute of the\nInternational Criminal Court. However, the Court has jurisdiction in Ukraine, pursuant to two\ndeclarations lodged by Ukraine and referrals by States parties. The Rome Statute, and the\nElements of Crimes,4 provide detailed elements for some of the alleged crimes. Where the\nCourt was found to lack jurisdiction, the Commission has applied the elements of crimes as\nset out in the Rome Statute, as long as they reflect customary international law."},{"id":"a-hrc-52-62-p0012","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"12","seq":13,"section":"A. Political and military context","text":"On 24 February 2022, the President of the Russian Federation, Vladimir Putin,\nannounced his decision to conduct a “special military operation” in Ukraine to seek its\n“demilitarization and denazification”. On the same day, Russian troops crossed various\nborder points into Ukraine, including through Belarus, and launched attacks by land, air and\nsea."},{"id":"a-hrc-52-62-p0013","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"13","seq":14,"section":"A. Political and military context","text":"International and regional bodies and States condemned in the strongest terms the\ninvasion and imposed far-reaching economic sanctions.5 They also expressed serious concern\nabout the risks of spread or escalation of the armed conflict and the unacceptable nuclear\nrhetoric used by Russian officials. 6 Condemnation of Belarus, which allowed the Russian\nFederation to use its territory and infrastructure to conduct hostilities in Ukraine, was also\nvoiced.7"},{"id":"a-hrc-52-62-p0014","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"14","seq":15,"section":"A. Political and military context","text":"Ukrainian cities and localities became the scenes of heavy warfare. Humanitarian\nrelief teams had great difficulty reaching the areas most affected by the fighting, leaving the\nbasic needs of civilians unmet. Mariupol was one of the worst-hit cities, with thousands\nestimated to have been killed and large sectors of the city destroyed. Some attacks, including\nthose targeting the country’s critical infrastructure, have affected the entire country, including\nareas far from the front lines."},{"id":"a-hrc-52-62-p0015","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"15","seq":16,"section":"A. Political and military context","text":"Populations under occupation reported grave human rights violations. Amid\nwidespread condemnation of the events in Bucha, in Kyiv Province, the General Assembly\nadopted a resolution calling for the suspension of the Russian Federation from the Human\nRights Council.8"},{"id":"a-hrc-52-62-p0016","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"16","seq":17,"section":"A. Political and military context","text":"In September, the authorities of the Russian Federation 9 in the occupied areas of\nDonetsk, Kherson, Luhansk and Zaporizhzhia Provinces held so-called referendums on the\nincorporation of those provinces into the Russian Federation. On 30 September 2022,\nMr. Putin and the de facto authorities of the four provinces signed “treaties” regarding their\n4 ICC-ASP/1/3 and ICC-ASP/1/3/Corr.1, part II.B\n5 See, for example, General Assembly resolution ES-11/1.\n6 See https://press.un.org/en/2022/sc15036.doc.htm and https://news.un.org/en/story/2022/11/1130722.\n7 See https://www.consilium.europa.eu/en/policies/sanctions/restrictive-measures-against-belarus.\n8 General Assembly resolution ES-11/3.\n9 For the purposes of the present report, the term “authorities of the Russian Federation” is used to refer\nto military and civilian occupying authorities of the Russian Federation and all associated de facto\nauthorities, armed groups and private military and security companies.\n“accession” to the Russian Federation. 10 The General Assembly found the attempted\nannexation illegal and called for its immediate reversal.11"},{"id":"a-hrc-52-62-p0017","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"17","seq":18,"section":"A. Political and military context","text":"On 10 October 2022, Mr. Putin announced attacks on the energy infrastructure of\nUkraine. Since then, waves of missile and drone attacks have affected the gas, heating and\nelectricity infrastructure of the country."},{"id":"a-hrc-52-62-p0018","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"18","seq":19,"section":"A. Political and military context","text":"The Zaporizhzhia nuclear power plant remains under the control of the armed forces\nof the Russian Federation. The deployment of military personnel and assets at the facility, in\naddition to shelling in close proximity, has sparked fears of a major nuclear accident. 12"},{"id":"a-hrc-52-62-p0019","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"19","seq":20,"section":"A. Political and military context","text":"Attempts to engage the Russian Federation and Ukraine in meaningful negotiations\nhave not yielded success, with each party rejecting the conditions put forward by the other."},{"id":"a-hrc-52-62-p0020","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"20","seq":21,"section":"B. Impact on the civilian population","text":"In one year, the armed conflict has taken a devastating toll on the civilian population.\nAs at 15 February 2023, according to the Office of the United Nations High Commissioner\nfor Human Rights (OHCHR), 8,006 civilians had been killed and 13,287 injured in Ukraine\nsince 24 February 2022. Of adult civilian casualties whose sex was known, 61.1 per cent\nwere men and 39.9 per cent were women. OHCHR believes that the actual figures are\nconsiderably higher.13 In addition to the human losses, the armed conflict in Ukraine has\ncaused a population displacement not seen in Europe since the Second World War. As at\n21 February 2023, the Office of the United Nations High Commissioner for Refugees\n(UNHCR) had reported approximately 8 million refugees from Ukraine across Europe, of\nwhich approximately 90 per cent were women and children.14 In addition, approximately\n5.4 million people are currently displaced across Ukraine. 15 Nearly 18 million people in\nUkraine are in need of humanitarian assistance, and endured particularly harsh conditions\nduring the winter months. 16 The conflict has affected people’s right to health, education,\nadequate housing, food and water. Some vulnerable groups, such as older persons, children,\npersons with disabilities and persons belonging to minority groups, have been particularly\naffected. No region of the country has been spared by the conflict."},{"id":"a-hrc-52-62-p0021","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"21","seq":22,"section":"IV. Violations of international law","text":"The Commission’s aim was to ensure broad thematic and geographic coverage in its\ninvestigation. It focused on behaviour during the conduct of hostilities and violations of\npersonal integrity, including summary executions, torture and ill-treatment, detention, and\nsexual and gender-based violence. The Commission also looked into violations of the laws\naddressing occupation and the transfer of children. It found that violations of human rights\nand international humanitarian law and related crimes had been committed across Ukraine\nand in the Russian Federation."},{"id":"a-hrc-52-62-p0022","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"22","seq":23,"section":"IV. Violations of international law","text":"In all the cases examined, the Commission sought to identify individual perpetrators\nof violations and crimes, the units deployed in the areas concerned and their chain of\ncommand. It attempted to determine whether the crimes had been committed in furtherance\nof orders or policies at a higher level. The Commission developed a separate list of\nperpetrators and military units identified as responsible for crimes and violations."},{"id":"a-hrc-52-62-p0023","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"23","seq":24,"section":"1. Overview","text":"The Commission investigated 25 individual attacks with explosive weapons in\npopulated areas in nine provinces of Ukraine, in both territory controlled by the Government\nof Ukraine and areas controlled by the authorities of the Russian Federation. All those attacks\ninvolved weapons that predictably cause civilian harm in populated areas and affect civilians\nor civilian objects. Many of the attacks were determined to have been indiscriminate as,\namong other things, they entailed a method or means that could not be directed at a specific\nmilitary objective or their effects could not be limited as required. The armed forces of the\nRussian Federation launched or likely launched the majority of the attacks. Several attacks\nwere disproportionate, as they were initiated with an apparent disregard for the presence of\nlarge concentrations of civilians or objects with special protection, causing excessive harm\nand suffering. A small number of indiscriminate attacks were likely committed by the\nUkrainian armed forces.17"},{"id":"a-hrc-52-62-p0024","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"24","seq":25,"section":"1. Overview","text":"The Commission also documented the barrage of attacks targeting the energy\ninfrastructure of Ukraine, which started on 10 October 2022. It found these attacks to have\nbeen disproportionate, widespread and systematic."},{"id":"a-hrc-52-62-p0025","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"25","seq":26,"section":"1. Overview","text":"Furthermore, the Commission investigated instances in which parties to the armed\nconflict failed to protect civilians or civilian objects against the effects of the hostilities."},{"id":"a-hrc-52-62-p0026","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"26","seq":27,"section":"1. Overview","text":"The use of explosive weapons with wide-area effects in populated areas was one of\nthe main causes of civilian casualties. OHCHR estimated that 90.3 per cent of the civilian\ncasualties were caused by explosive weapons. 18 Such attacks damaged or destroyed\nthousands of residential buildings, more than 3,000 educational institutions, 19 and more than\n600 medical facilities. 20 The systematic targeting of energy-related installations deprived\nlarge portions of the civilian population of electricity, water and sanitation, heating and\ntelecommunications during certain periods and hampered access to health and education."},{"id":"a-hrc-52-62-p0027","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"27","seq":28,"section":"1. Overview","text":"In all the places that it visited, the Commission documented considerable civilian\nharm and observed first-hand the damage to buildings and infrastructure. It was struck by the\nextent of the destruction in the cities of Kharkiv, Chernihiv and Izium. While it was unable\nto visit the city of Mariupol, it interviewed more than 30 civilians who had been in the city\nduring the siege and bombardment by the armed forces of the Russian Federation. They\nreported intensive shelling and air strikes, including on civilian buildings, and described the\nuse of explosive weapons during the period as “constant” and “never-ending”. Photographs,\nvideos and satellite imagery corroborated the widespread destruction of residential areas. In\naddition, civilians were left without basic services during that period."},{"id":"a-hrc-52-62-p0028","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"28","seq":29,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The Commission investigated attacks carried out with explosive weapons in populated\nareas controlled by the Ukrainian authorities.21 Some of these attacks were conducted in the\ncontext of attempts by the armed forces of the Russian Federation to capture towns or cities,\nwhile others struck areas far from the front lines. The attacks investigated were a small\nfraction of the total number."},{"id":"a-hrc-52-62-p0029","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"29","seq":30,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"According to international humanitarian law, indiscriminate attacks are those which\nare not directed at a specific military objective, employ a method or means of combat that\ncannot be directed at a specific military objective, or employ a method or means of combat\n17 For the purposes of the present report, the term “Ukrainian armed forces” is used to refer to all\ncombatants who have been identified as such or as directly affiliated with the Ukrainian armed forces.\n18 See https://www.ohchr.org/en/press-releases/2023/02/turk-deplores-human-cost-russias-war-against-\nukraine-verified-civilian.\n19 See https://www.unicef.org/ukraine/en/press-releases/war-has-hampered-education.\n20 World Health Organization, figures for the period 24 February 2022–1 February 2023, Surveillance\nSystem for Attacks on Health Care. Available at https://extranet.who.int/ssa/Index.aspx.\n21 For the purposes of the present report, the term “Ukrainian authorities” is used to refer to Ukrainian\ncivilian and military authorities and all associated persons and groups.\nwhose effects cannot be limited. 22 The documented attacks affected civilian objects,\nincluding residential buildings, hospitals, schools, a hotel, shops, a theatre, a pharmacy, a\nkindergarten and a train station."},{"id":"a-hrc-52-62-p0030","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"30","seq":31,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"In some of the situations examined, the Commission could not identify a military\nobjective. When objects of military value that might have been the intended targets of the\nattacks were present in the vicinity of some of the impact sites, the Commission generally\nfound that the armed forces of the Russian Federation used weapons that struck both military\nand civilian objects without distinction. It identified four types of weapons whose use in\npopulated areas led to indiscriminate attacks: unguided bombs dropped from aircraft;\nlong-range anti-ship missiles of the Kh-22 or Kh-32 type, which have been found to be\ninaccurate when striking land targets; cluster munitions, which, by design, spread small sub-\nmunitions over a wide area; and multiple-launch rocket systems, which cover a large area\nusing inaccurate rockets."},{"id":"a-hrc-52-62-p0031","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"31","seq":32,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The circumstances of the attacks launched or likely launched by the armed forces of\nthe Russian Federation that the Commission investigated led it to determine that the majority\nof them were indiscriminate. These attacks included such widely reported instances as the\nattack of 16 March 2022 carried out during the siege of Mariupol on the city’s drama theatre,\nwhich killed and injured a large number of people; the attack of 8 April 2022 on the\nKramatorsk train station, which killed 59 people and injured 92; and the attack of 27 June\n2022 on a shopping mall in Kremenchuk, which killed 21 people and injured dozens."},{"id":"a-hrc-52-62-p0032","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"32","seq":33,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The Commission found that in several attacks, the armed forces of the Russian\nFederation had failed to take feasible precautions to verify whether civilians were present. 23\nHundreds of civilians had gathered in the areas affected by the attacks on the Kramatorsk\ntrain station and the Mariupol drama theatre. Similarly, hundreds of civilians were in the\nresidential areas of Chernihiv during attacks of 3 March 2022, which killed at least 20 people\nand injured many others. Irrespective of whether there was a military objective, an\nassessment of the targets should have alerted the armed forces of the Russian Federation to\nthe presence of large numbers of civilians."},{"id":"a-hrc-52-62-p0033","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"33","seq":34,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"That the attacks affected civilian buildings, such as functioning medical institutions,\nalso manifests a failure to take precautions. Such attacks include that of 9 March 2022 on the\nMariupol Primary and Sanitation Aid Centre No. 3, also referred to as Maternity Ward No. 3,\nin which at least one pregnant woman and her unborn child were killed. Even if the armed\nforces of the Russian Federation had military objectives in conducting the attacks, the special\nprotected status of medical institutions should have led them to take extra care."},{"id":"a-hrc-52-62-p0034","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"34","seq":35,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The Commission concluded that the armed forces of the Russian Federation\ncommitted, and in some cases likely committed, indiscriminate and disproportionate attacks,\nin violation of international humanitarian law.24 The multiple examples of such attacks and\nthe failure to take feasible precautions show a pattern of disregard on the part of the armed\nforces of the Russian Federation for the requirement to minimize civilian harm."},{"id":"a-hrc-52-62-p0035","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"35","seq":36,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The Commission also assessed whether the bombardment of Mariupol and the\nconduct of the siege in the city may have constituted a crime against humanity. 25 However,\nas the Commission did not have access to Donetsk Province, including Mariupol, it did not\nhave a sufficient basis on which to make such a determination. It recommends further\ninvestigations in this regard.\n3.        Unlawful attacks in areas controlled by the armed forces of the Russian Federation"},{"id":"a-hrc-52-62-p0036","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"36","seq":37,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The Commission found instances in which the Ukrainian armed forces likely used\ncluster munitions and rocket-delivered anti-personnel landmines to carry out attacks in Izium,\nin Kharkiv Province, from March to September 2022, when it was controlled by the armed\nforces of the Russian Federation. Ukraine, unlike the Russian Federation, is a State party to\nthe Convention on the Prohibition of the Use, Stockpiling, Production and Transfer of\nAnti-Personnel Mines and on their Destruction, which bans all use of anti-personnel\nlandmines."},{"id":"a-hrc-52-62-p0037","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"37","seq":38,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"The following three examples illustrate the use of weapons that bear the characteristics\nof cluster munitions in the Izium during that period. On 9 May 2022, an attack struck a\nresidential area, killing three people and injuring six. On 14 July 2022, an attack hit the area\naround the central market, injuring two older women. On 16 July 2022, several sub-munitions\nhit a residential area, including a kindergarten, where about 250 people had sought shelter,\nkilling two older persons."},{"id":"a-hrc-52-62-p0038","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"38","seq":39,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"Witness testimonies also indicated that anti-personnel high-explosive landmines were\nused in populated areas from July 2022, specifically before the withdrawal of the armed\nforces of the Russian Federation. They caused grave civilian injuries. After inspecting\nunexploded landmines, photographs and weapon remnants, the Commission identified them\nas anti-personnel high-explosive landmines, known as “PFM” or “butterfly mines”, likely\ndelivered by Uragan rocket-launcher. The Ukrainian armed forces were at that time stationed\nwithin the striking distance of such rockets."},{"id":"a-hrc-52-62-p0039","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"39","seq":40,"section":"2. Unlawful attacks in territory controlled by the Government of Ukraine","text":"After considering the context of these incidents, notably the fact that the attacks struck\nan area during a period when it was controlled by the armed forces of the Russian Federation,\nthe weapons systems used, and the fact that the attacks were repeated and affected civilians\nor civilian objects, the Commission found it likely that the Ukrainian armed forces committed\nindiscriminate attacks, in violation of international humanitarian law. 26"},{"id":"a-hrc-52-62-p0040","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"40","seq":41,"section":"4. Attacks against Ukrainian energy-related infrastructure","text":"The Commission investigated the barrage of attacks on energy-related installations in\nUkraine launched by the armed forces of the Russian Federation, starting on 10 October 2022.\nCritical energy-related infrastructure in Ukraine had come under attack from the early stages\nof the invasion, but on that date, Mr. Putin declared the following: “This morning, at the\nproposal of the Defence Ministry and in accordance with the plan of [the] General Staff, a\nmassive strike was launched with long-range precision air-, sea- and land-based weapons\nagainst Ukrainian energy, military and communications facilities.” 27 After that declaration,\nthe attacks changed in several important ways."},{"id":"a-hrc-52-62-p0041","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"41","seq":42,"section":"4. Attacks against Ukrainian energy-related infrastructure","text":"First, the intensity of attacks increased significantly, with at least 13 waves of attacks\nbetween 10 October 2022 and 1 February 2023 using hundreds of long-range missiles and\ndrones equipped with explosives. Second, the geographical scope widened, with attacks\naffecting 20 of the 24 provinces in Ukraine. Lastly, while attacks prior to 10 October 2022\nhad been focused mainly on fuel installations and electric infrastructure related to the railway\nsystem, attacks after that date systematically targeted power plants and other infrastructure\ncritical for the transmission of electricity and the generation of heat across Ukraine. On the\nbasis of these factors, the Commission found that the attacks on energy infrastructure since\n10 October 2022 were widespread and systematic and that the objective was to disrupt the\nenergy system of the entire country, with the predictable effects on the heating system."},{"id":"a-hrc-52-62-p0042","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"42","seq":43,"section":"4. Attacks against Ukrainian energy-related infrastructure","text":"The disruption of electrical substations, power plants and other installations used to\nproduce the energy and heating indispensable to the survival of the population inflicted\nsignificant harm on civilians. Entire regions and millions of people were for periods left\nwithout electricity or heating, particularly during the winter, and consequently with impaired\naccess to, notably, water, sanitation, food, health care and education. Despite the availability\nof public information about the civilian harm after the first few attacks, the armed forces of\nthe Russian Federation continued to target energy infrastructure."},{"id":"a-hrc-52-62-p0043","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"43","seq":44,"section":"4. Attacks against Ukrainian energy-related infrastructure","text":"The Commission concluded that these attacks by the armed forces of the Russian\nFederation were disproportionate and that they constituted the war crime of excessive\n26   Protocol I Additional to the Geneva Conventions of 1949, art. 51 (4) and (5).\n27   President of Russia, “Meeting with permanent members of the Security Council”, 10 October 2022.\nAvailable at http://www.en.kremlin.ru/events/president/transcripts/deliberations/69568.\nincidental death, injury or damage. 28 It also found that the attacks were widespread and\nsystematic and may have amounted to the crime against humanity of other inhumane acts.\nFurther time and resources are needed to investigate the attacks to clarify whether their\naccumulated impact becomes comparable, as it might give their magnitude, to one of the\nenumerated acts of crimes against humanity, and the extent to which the policy was directed\nagainst the civilian population.29"},{"id":"a-hrc-52-62-p0044","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"44","seq":45,"section":"5. Endangering civilians","text":"During the conduct of hostilities, the armed forces of the Russian Federation exposed\ncivilians to significant risks. The Commission found that, on repeated occasions, they\ndeliberately positioned their troops or equipment in residential areas and, at times, forced\ncivilians to remain there or in the proximity of their positions."},{"id":"a-hrc-52-62-p0045","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"45","seq":46,"section":"5. Endangering civilians","text":"Military operations near or from within the Zaporizhzhia nuclear power plant, in\nEnerhodar, in Zaporizhzhia Province, have significantly endangered the plant, creating the\nrisk of a serious nuclear incident. On 4 March 2022, the armed forces of the Russian\nFederation launched an attack on the facility and heavy fighting erupted as they attempted to\ntake control of it. Videos show that a fire broke out as a consequence of the attack and\ninflicted damage to parts of the plant. In addition, the armed forces of the Russian Federation\nplaced military equipment in and near the facility and have been launching attacks from there.\nSatellite imagery from 29 August 2022 appears to show military equipment less than\n150 metres from a reactor."},{"id":"a-hrc-52-62-p0046","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"46","seq":47,"section":"5. Endangering civilians","text":"The Commission also documented that, in territory controlled by the Ukrainian armed\nforces, on some occasions, there was a lack of separation between the armed forces and\ncivilians, which placed civilians at risk. For example, in the city of Chernihiv, the Ukrainian\nTerritorial Defence Forces set up headquarters at school 18 and stationed some of their\nmembers at school 21. Those schools were also used to distribute humanitarian aid to the\npopulation. On 3 March 2022, an air strike hit both schools and killed civilians and military\npersonnel.30"},{"id":"a-hrc-52-62-p0047","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"47","seq":48,"section":"5. Endangering civilians","text":"The Commission concluded that the parties endangered civilians by not taking the\nrequisite precautions to the maximum extent feasible, such as avoiding locating military\nobjectives within or near densely populated areas, and thereby violated international\nhumanitarian law. 31 Additionally, it follows from international humanitarian law that the\narmed forces of the Russian Federation must avoid locating any military objectives in the\nvicinity of a nuclear power plant, and that the plant should not be made the object of attack\nby either party.32"},{"id":"a-hrc-52-62-p0048","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"48","seq":49,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission documented patterns of wilful killings, unlawful confinement,\ntorture, rape and unlawful transfers of detainees in the areas under the control of the\nauthorities of the Russian Federation in Ukraine. Violations were also committed against\npersons deported from Ukraine to the Russian Federation."},{"id":"a-hrc-52-62-p0049","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"49","seq":50,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission noted certain elements that were common to the different patterns\nof violations that it identified, as detailed in the following paragraphs."},{"id":"a-hrc-52-62-p0050","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"50","seq":51,"section":"1. Violations of personal integrity committed by the authorities of the","text":"In cases of summary execution and torture, the perpetrators targeted persons mostly\nfor any form of real or perceived support of the Ukrainian armed forces, 33 or for any action\ndirected against the armed forces of the Russian Federation."},{"id":"a-hrc-52-62-p0051","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"51","seq":52,"section":"1. Violations of personal integrity committed by the authorities of the","text":"During the initial control by the armed forces of the Russian Federation of localities\nin Ukraine, many of the cases of wilful killing, unlawful confinement, rape and sexual\nviolence were committed in the context of house-to-house searches aimed at locating\nsupporters of the Ukrainian armed forces or finding weapons."},{"id":"a-hrc-52-62-p0052","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"52","seq":53,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Furthermore, when the authorities of the Russian Federation controlled areas for\nlonger periods of time, they established dedicated detention facilities, used more diverse\nmethods of torture and targeted persons who refused to cooperate. A wider array of\nperpetrators were involved in the commission of unlawful confinement, torture and sexual\nand gender-based violence, according to victims and witnesses, including perpetrators from\nthe Federal Security Service of the Russian Federation, the National Guard of the Russian\nFederation and its subordinate units, and armed groups aligned with the Russian Federation\nfrom the so-called Donetsk People’s Republic and Luhansk People’s Republic.\n(a)         Summary executions"},{"id":"a-hrc-52-62-p0053","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"53","seq":54,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Evidence collected showed a widespread pattern of summary executions in areas that\nthe armed forces of the Russian Federation controlled in 17 localities of Chernihiv, Kharkiv,\nKyiv and Sumy Provinces, with the highest number in Kyiv Province, including in the city\nof Bucha. The Commission confirmed the execution of 65 men, 2 women and a 14-year-old\nboy. Most of the cases documented in the areas visited by the Commission took place during\nthe first few months of the armed conflict."},{"id":"a-hrc-52-62-p0054","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"54","seq":55,"section":"1. Violations of personal integrity committed by the authorities of the","text":"In more than half of the executions investigated, witnesses had last seen the victims\nin the custody of the armed forces of the Russian Federation. In a few cases, eyewitnesses\nhad seen the armed forces of the Russian Federation carry out the executions. The\nCommission concluded that the armed forces of the Russian Federation were responsible in\nthose cases. In the remaining cases, the victims’ bodies were found at or near locations that\nthe armed forces of the Russian Federation had used as bases. The Commission also\nconcluded that the armed forces of the Russian Federation were likely responsible in those\ncases."},{"id":"a-hrc-52-62-p0055","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"55","seq":56,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Detention, interrogation, torture or ill-treatment often preceded execution. Some\nvictims had been found with their hands or feet tied. According to medical records and\nphotographs, the most common method of killing was a gunshot to the head at close range."},{"id":"a-hrc-52-62-p0056","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"56","seq":57,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission concluded that the armed forces of the Russian Federation\ncommitted wilful killings of civilians or persons hors de combat in areas that came under\ntheir control, constituting war crimes and violations of the right to life. 34\n(b)         Attacks against civilians on the move"},{"id":"a-hrc-52-62-p0057","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"57","seq":58,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission found a pattern of attacks against civilians on the move in Kharkiv,\nKyiv and Sumy Provinces when they were under the control of the armed forces of the\nRussian Federation. It documented 18 such cases in February and March 2022, in which\n14 men, 8 women, 3 boys and 1 girl were killed and 6 other civilians injured. Among the\ncases examined, most were committed in Kyiv Province. In many of these instances, the\nCommission found enough evidence to conclude that the armed forces of the Russian\nFederation were responsible for these attacks."},{"id":"a-hrc-52-62-p0058","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"58","seq":59,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The attacks occurred while civilians were trying to evacuate or were carrying out\nroutine activities. In all the cases, the victims were wearing civilian clothes, were unarmed\n33 Persons involved in the former Anti-Terrorist Operation, which was run in parts of Donetsk and\nLuhansk Provinces between 2014 and 2018, and members of the Ukrainian Territorial Defence Forces\nwere among those specifically targeted.\n34 For example, Geneva Convention relative to the Protection of Civilian Persons in Time of War\n(Fourth Geneva Convention), art. 147, and International Covenant on Civil and Political Rights,\nart. 6 (1).\nand were driving civilian cars, some with signs on the windows indicating that children were\non board. Several attacks occurred in or around the same location, such as the E40 highway\nin Kyiv and Kharkiv Provinces. The Commission interviewed survivors of attacks and\nwitnesses and relatives of those killed, and reviewed video footage showing yet more\ndamaged cars on the highway where the attacks had taken place. The attacks were thus not\nisolated, suggesting that some military units were responsible for multiple incidents. Some\nof the attacks seem to have been deliberate, such as when soldiers opened fire on civilian cars\nthat posed no risk because they had stopped or were driving away. In other cases, there were\nno indications that the attackers had taken steps to verify whether the target was a military\nobjective.35"},{"id":"a-hrc-52-62-p0059","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"59","seq":60,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission concluded that the armed forces of the Russian Federation\ncommitted or likely committed indiscriminate attacks against civilians and civilian objects,\nwhich are violations of international humanitarian law and violations of the right to life. 36 In\nsome cases, they did not do everything feasible to verify that the objectives to be attacked\nwere not civilians or civilian objects. The attacks that appear to have intentionally targeted\ncivilians amount to war crimes.37\n(c)        Unlawful confinement"},{"id":"a-hrc-52-62-p0060","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"60","seq":61,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission established a pattern of widespread unlawful confinement in areas\ncontrolled by the armed forces of the Russian Federation targeting broad categories of\npersons. Victims were men and women of all ages and children. The Commission identified\ndetention facilities where the authorities of the Russian Federation detained large numbers of\npeople for long periods of time in Chernihiv, Donetsk, Kharkiv, Kherson, Kyiv and\nZaporizhzhia Provinces of Ukraine and in the Russian Federation. It focused its investigation\non 14 such places. Procedural requirements for detention were not met. Conditions of\ndetention were consistently inhuman. In numerous cases, the confinement was prolonged,\nwith the longest instance over nine months. Relatives were not informed and the reasons for\nconfinement were not properly communicated."},{"id":"a-hrc-52-62-p0061","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"61","seq":62,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The authorities of the Russian Federation confined persons of different occupations,\nwith the majority being young or middle-aged men, including any person formerly associated\nwith Ukrainian armed forces, 38 local officials, State personnel, current and former law\nenforcement officials, activists and journalists, education personnel, employees of the\nZaporizhzhia nuclear power plant, volunteers evacuating civilians, and others. They also\nconfined people who were influential in their communities, in order to coerce them and the\nlocal residents to cooperate. Some were confined together with their relatives, including\nchildren, or as a group."},{"id":"a-hrc-52-62-p0062","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"62","seq":63,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Unlawful confinement started at checkpoints or filtration points staffed by the armed\nforces of the Russian Federation, or on the street. The authorities of the Russian Federation\nalso detained people during house-to-house searches (see para. 51) or at their workplace.\nDetention was often a precursor to torture and execution."},{"id":"a-hrc-52-62-p0063","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"63","seq":64,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Perpetrators generally accused the detainees of real or perceived assistance to the\nUkrainian armed forces or found something that, in their view, looked suspicious during\nphone searches. In numerous cases, the authorities of the Russian Federation detained people\non invalid grounds, such as having relatives in Ukrainian security or law enforcement\nagencies, refusing to cooperate, participating in protests against the occupation, holding\npro-Ukrainian views or having certain types of tattoos."},{"id":"a-hrc-52-62-p0064","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"64","seq":65,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Among the detention facilities that the Commission identified, some were improvised.\nSuch facilities were more common during the first weeks of the occupation. Others were\nestablished in permanent structures, such as police stations. Conditions were poor in all the\nfacilities. Cells were overcrowded, with people forced to sleep on the floor or to take turns to\nsleep. At times, men, women and children were held together. A lack of light and ventilation,\ndifficulty breathing and the absence of heating in freezing temperatures were reported.\nSanitary conditions were inadequate, with, at times, buckets or a bottle used as a toilet and\nlimited or no possibility of washing. In one case, 10 older people died as a consequence of\nthe inhuman conditions in a school basement, while the other detainees, including children,\nhad to share the same space with the bodies of the deceased."},{"id":"a-hrc-52-62-p0065","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"65","seq":66,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Such conditions of detention can disproportionately affect people depending on their\ngender. Some women restricted their water and food intake out of shame at having to use the\ntoilet in front of others. When water was available, there was no privacy. Menstruating\nwomen suffered because of a lack of hygiene, which can lead to serious infections and\ndiseases."},{"id":"a-hrc-52-62-p0066","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"66","seq":67,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Numerous persons detained in areas that were under the control of the Russian\nFederation are still missing. Family members who reached out to the authorities of the\nRussian Federation reported that they most often received no response or were not informed\nof the whereabouts of the victims."},{"id":"a-hrc-52-62-p0067","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"67","seq":68,"section":"1. Violations of personal integrity committed by the authorities of the","text":"On the basis of the large number of cases that it documented, the Commission\nconcluded that the authorities of the Russian Federation unlawfully detained wide categories\nof civilians and other protected persons, frequently in the absence of valid reasons or without\nrespecting procedural requirements. Detention conditions were generally inhuman. Such\nconfinements constitute war crimes and are violations of the right to liberty and security of\npersons.39\n(d)         Unlawful transfer and deportation of detainees"},{"id":"a-hrc-52-62-p0068","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"68","seq":69,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission reviewed situations in which the armed forces of the Russian\nFederation transferred detainees within Ukraine or deported them to the Russian Federation. 40\nVictims were both men and women. In the Russian Federation, some of the detainees were\nconfined in pretrial facilities in Bryansk and Kursk Provinces. A large number of Ukrainians\nwere detained there. According to former detainees, the authorities of the Russian Federation\nlabelled some of the detained persons as prisoners of war. However, after reviewing their\ncircumstances, the Commission found that they retained their civilian status."},{"id":"a-hrc-52-62-p0069","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"69","seq":70,"section":"1. Violations of personal integrity committed by the authorities of the","text":"In its investigations, the Commission identified several instances of transfer and\ndeportation in March 2022. In two cases, the victims were first detained in a makeshift\ndetention facility in the town of Dymer and then transferred to another such facility at\nHostomel Airport, both in Kyiv Province, and subsequently deported with other detainees\nthrough Belarus to the Russian Federation, to a detention facility in Bryansk Province. In\nanother case, a young woman was first detained in a makeshift detention facility in the village\nof Novyi Bykiv, in Chernihiv Province, and subsequently deported with other detainees to\nthe Russian Federation, to a detention facility in Kursk Province. Upon arrival, the three\nvictims were interrogated, accused of providing support to the Ukrainian armed forces and\nsubjected to torture. In two further cases, concerning three men, the victims were first\nconfined in a makeshift detention facility in the village of Boromlia, in Sumy Province, and\nsubsequently deported with other detainees to the Russian Federation, to a place not far from\nthe border. The authorities of the Russian Federation held them there, in a basement with\nother detainees from Ukraine, and interrogated them."},{"id":"a-hrc-52-62-p0070","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"70","seq":71,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission concluded that the authorities of the Russian Federation committed\nunlawful transfers within Ukraine and deportations to the Russian Federation of civilians and\nof other protected persons, constituting war crimes.41\n(e)        Torture and inhuman treatment"},{"id":"a-hrc-52-62-p0071","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"71","seq":72,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission found a widespread pattern of torture and inhuman treatment\ncommitted by the authorities of the Russian Federation against people that they detained in\nChernihiv, Donetsk, Kharkiv, Kherson, Kyiv, Sumy and Zaporizhzhia Provinces of Ukraine\n39 Fourth Geneva Convention, art. 147, and International Covenant on Civil and Political Rights,\nart. 9 (1).\n40 A/77/533, para. 80.\n41 For example, Fourth Geneva Convention, art. 147.\nand in the Russian Federation. The use of torture was prevalent against certain categories of\npeople. Most victims were men, and both civilians and prisoners of war were tortured. The\nCommission found that, as the authorities of the Russian Federation consolidated control\nover certain areas, more diverse but similar methods of torture were used systematically in\ndetention facilities across various provinces of Ukraine."},{"id":"a-hrc-52-62-p0072","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"72","seq":73,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Torture was particularly severe against current or former members of the Ukrainian\narmed forces and associated persons and their relatives. Local officials, law enforcement\npersonnel, employees of the Zaporizhzhia nuclear power plant and civilians with\npro-Ukrainian views were also victims of torture."},{"id":"a-hrc-52-62-p0073","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"73","seq":74,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The aim was to obtain information about the Ukrainian armed forces, extract\nconfessions, force victims to cooperate, or inflict punishments. Torture was usually combined\nwith long interrogation sessions. Victims often had their hands tied or handcuffed, their legs\ntied and their eyes covered with tape or with a hood, clothes or a bag placed over their head.\nAccording to some former detainees, the authorities of the Russian Federation referred to\nthem as “Nazis”, “fascists” and “terrorists” and forced them to undergo “denazification\nsessions” consisting of severe beatings."},{"id":"a-hrc-52-62-p0074","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"74","seq":75,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The perpetrators inflicted severe physical and mental pain and suffering. Victims\ndescribed instances of beatings with rifle butts or batons, electric shocks with taser guns, rape\nand prolonged exposure to cold that had taken place during the first weeks of the armed\nconflict and in makeshift detention facilities in Ukraine. In some cases, torture was followed\nby execution (see para. 55)."},{"id":"a-hrc-52-62-p0075","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"75","seq":76,"section":"1. Violations of personal integrity committed by the authorities of the","text":"In areas under the prolonged control of the Russian Federation and in more permanent\ndetention facilities, additional methods of torture were used. One such method involved\nelectric shocks administered using a military phone known as a “Tapik” connected to an\nelectric cable with clips that were applied to the feet, the fingers or men’s genitals. The\nperpetrators referred to this procedure as the “call to Lenin” or “call to Putin”. Other methods\nincluded hanging detainees from the ceiling with their hands tied in the so-called “parrot”\nposition, strangling them with cables, suffocating them with plastic bags or gas masks, and\nrape and other sexual violence (see paras. 81 and 82). Victims witnessed the death of\nco-detainees following severe torture."},{"id":"a-hrc-52-62-p0076","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"76","seq":77,"section":"1. Violations of personal integrity committed by the authorities of the","text":"In the Russian Federation, confinement at times started with an abusive “acceptance\nprocedure”. Victims reported electric shocks with taser guns, beatings with batons,\nsuffocation with plastic bags, and forced nudity in front of others. A former detainee reported\nundergoing beatings as punishment for speaking Ukrainian and for not remembering the\nlyrics of the national anthem of the Russian Federation. One woman said that she had passed\nout a few times from beatings, but that the perpetrators had woken her and continued."},{"id":"a-hrc-52-62-p0077","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"77","seq":78,"section":"1. Violations of personal integrity committed by the authorities of the","text":"On the basis of the cases that it documented, the Commission concluded that the\nauthorities of the Russian Federation committed acts of torture and cruel or inhuman\ntreatment, constituting war crimes and violations of the prohibition of torture and other cruel,\ninhuman or degrading treatment or punishment.42 In addition, given the targeting of specific\ncategories of persons and the consistent use of the same methods of torture across several\nprovinces that the authorities of the Russian Federation controlled in Ukraine for extended\nperiods of time, the Commission concluded that the authorities of the Russian Federation\nused torture in a systematic and widespread manner. These circumstances, which also\ninvolved elements of planning and resource availability, indicate that the authorities of the\nRussian Federation may have committed torture constituting crimes against humanity. The\nCommission recommends further investigations to ascertain whether the torture of detainees\nby the authorities of the Russian Federation in detention facilities that they held in Ukraine\nand of detainees deported from Ukraine to the Russian Federation was committed in\nfurtherance of a specific policy.43\n(f)        Sexual and gender-based violence"},{"id":"a-hrc-52-62-p0078","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"78","seq":79,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission documented cases of sexual and gender-based violence involving\nwomen, men and girls, aged 4 to 82 years, in nine provinces of Ukraine and in the Russian\nFederation. 44 It found that the authorities of the Russian Federation committed sexual\nviolence in two main situations: during house-to-house searches and against victims whom\nthey had confined. In addition, the Commission documented situations in which the\nauthorities of the Russian Federation imposed forced nudity in detention, at checkpoints and\nat filtration points."},{"id":"a-hrc-52-62-p0079","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"79","seq":80,"section":"1. Violations of personal integrity committed by the authorities of the","text":"As the armed forces of the Russian Federation took control of localities in Ukraine\nand undertook house-to-house searches to find people who had supported the Ukrainian\narmed forces (see para. 51), in some instances, soldiers committed acts of rape and sexual\nviolence when they broke into the victims’ houses. The Commission documented such\nviolations in Chernihiv, Kharkiv, Kherson and Kyiv Provinces, with the majority in Kyiv\nProvince, mainly during the first two months of the armed conflict. Most victims were women\nalone at home."},{"id":"a-hrc-52-62-p0080","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"80","seq":81,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Acts of rape were committed at gunpoint with extreme brutality and with acts of\ntorture, such as beatings and strangling. The perpetrators at times threatened to kill the victim\nor her family if she resisted. In some cases, more than one soldier raped the same victim or\nthe same victim was raped several times. In one incident, the victim was pregnant and begged\nthe soldiers to spare her, in vain; she had a miscarriage a few days later. The perpetrators, in\nsome instances, executed or tortured husbands and other male relatives. Family members,\nincluding children, were sometimes forced to watch the perpetrators rape their loved ones."},{"id":"a-hrc-52-62-p0081","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"81","seq":82,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The Commission found numerous instances of sexual and gender-based violence\ncommitted by the authorities of the Russian Federation during unlawful confinement in\nDonetsk, Kharkiv, Kherson, Kyiv and Luhansk Provinces of Ukraine and in the Russian\nFederation (see paras. 74 and 75). The cases of sexual and gender-based violence in\nconfinement affected mostly men, both civilians and prisoners of war. The evidence collected\nshowed that sexual violence amounting to torture, and the threat of such, were important\naspects of the torture exercised by the authorities of the Russian Federation, with methods\nincluding rape, electric shocks on genitals, traction on the penis using a rope and\nemasculation. The Commission also analysed signs of such acts on the bodies of deceased\nvictims. According to survivors, the perpetrators aimed to extract information or confessions,\nforce cooperation or punish, intimidate or humiliate victims as individuals or as a group."},{"id":"a-hrc-52-62-p0082","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"82","seq":83,"section":"1. Violations of personal integrity committed by the authorities of the","text":"Among the incidents documented by the Commission were those of two women,\ninterviewed separately, who had been detained in facilities maintained by the authorities of\nthe Russian Federation in two different locations in Kharkiv Province. They described how\nsoldiers had ordered them to undress fully, touched them all over their bodies and raped them.\nThe Commission also analysed a video showing how the armed forces of the Russian\nFederation had emasculated and then shot a captured Ukrainian soldier."},{"id":"a-hrc-52-62-p0083","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"83","seq":84,"section":"1. Violations of personal integrity committed by the authorities of the","text":"The armed forces of the Russian Federation inflicted forced nudity in a variety of\nsituations, ordering people to undress and remain naked, including for prolonged periods of\ntime, which can constitute a form of sexual violence. Cases were identified in Donetsk,\nKharkiv and Kyiv Provinces of Ukraine and in the Russian Federation. Victims were men,\nwomen and, in one case, a 17-year-old boy. Such acts were committed during confinement\nor at filtration points and checkpoints, in order to humiliate the victims during torture and\ndetention or to verify the presence of tattoos, among other reasons. The forced nudity went\nbeyond what would be acceptable in the framework of a security verification."},{"id":"a-hrc-52-62-p0084","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"84","seq":85,"section":"1. Violations of personal integrity committed by the authorities of the","text":"For example, the Commission documented instances of hours-long forced nudity\nimposed in a humiliating way on new detainees upon their arrival at the Olenivka penal\ncolony in Donetsk Province and in detention facilities in the Russian Federation. In another\nsituation, the armed forces of the Russian Federation detained a priest, fully undressed him,\nbeat him and ordered him to parade naked for one hour through the streets of his village.\n44   A/77/533, paras. 88–98."},{"id":"a-hrc-52-62-p0085","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"85","seq":86,"section":"1. Violations of personal integrity committed by the authorities of the","text":"On the basis of the evidence that it collected, the Commission concluded that some\nmembers of the armed forces of the Russian Federation, in areas that they controlled,\ncommitted the war crime of rape and sexual violence, which can amount to torture. 45 Rape\nand torture constitute war crimes and violations of the corresponding human rights\nobligations. Acts of forced nudity can be a form of sexual violence and may constitute the\nwar crime of outrages upon personal dignity.46"},{"id":"a-hrc-52-62-p0086","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"86","seq":87,"section":"2. Violations of personal integrity committed by the Ukrainian authorities","text":"The Commission has previously described two incidents, in Mala Rohan, in Kharkiv\nProvince, and in Dmytrivka, in Kyiv Province, in which the Ukrainian armed forces shot,\nwounded and tortured captured soldiers of the armed forces of the Russian Federation. 47 In a\nletter to the Commission on this issue, dated 27 January 2023, the Office of the Prosecutor\nGeneral of Ukraine noted that it had initiated pretrial investigations into those cases. It further\nstated that no objective data supporting the involvement of Ukrainian military service\npersonnel had been gathered at that time, but that the investigations were continuing. The\nCommission, however, found that the persons responsible for the violations either belonged\nofficially to the Ukrainian armed forces or were fighting closely with them at the time of the\nincidents.\n(b)        Alleged torture and ill-treatment of collaborators"},{"id":"a-hrc-52-62-p0087","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"87","seq":88,"section":"2. Violations of personal integrity committed by the Ukrainian authorities","text":"Since 24 February 2022, the Ukrainian authorities have opened thousands of\ninvestigations into allegations of collaboration and treason in the context of the armed\nconflict.48 The Commission collected dozens of accounts from lawyers, former detainees and\ndetainees’ relatives relating to cases of detention on charges of high treason, collaborative\nactivity and support for the aggressor State. Allegations were made that the Ukrainian\nauthorities committed torture and ill-treatment against detainees, violated their procedural\nrights and detained them in inhuman conditions."},{"id":"a-hrc-52-62-p0088","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"88","seq":89,"section":"2. Violations of personal integrity committed by the Ukrainian authorities","text":"Witnesses reported beatings, mock executions and threats to harm the detainee or the\ndetainee’s family. Reportedly, no arrest warrants were produced in some cases, and some\ndetainees were held incommunicado, sometimes for several days. Sleep and food deprivation\nwas also reported."},{"id":"a-hrc-52-62-p0089","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"89","seq":90,"section":"2. Violations of personal integrity committed by the Ukrainian authorities","text":"The Commission is concerned about these allegations. However, at the time of the\nwriting of the present report, it was not in a position to corroborate them. It recommends\nfurther investigations."},{"id":"a-hrc-52-62-p0090","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"90","seq":91,"section":"C. Violations of the laws of occupation","text":"The Commission examined the context and circumstances in which the authorities of\nthe Russian Federation organized and held so-called referendums between 23 and\n27 September 2022 in the occupied areas of Donetsk, Kherson, Luhansk and Zaporizhzhia\nProvinces concerning the annexation of the provinces to the Russian Federation. It found that\nthe holding of the so-called referendums was in disregard for the Ukrainian Constitution,\nwhich regulates the organization of referendums in Ukraine. 49 The referendums were\ntherefore held in violation of international humanitarian law, which prescribes that an\noccupying Power must respect the laws in force in the territory that it occupies. 50 Moreover,\nthe Commission concludes that the annexation of the four provinces was unlawful on the\nbasis of principles of international law that no territorial acquisition resulting from the threat\nor use of force may be recognized as legal. 51"},{"id":"a-hrc-52-62-p0091","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"91","seq":92,"section":"C. Violations of the laws of occupation","text":"In addition, the Commission found that the so-called referendums were held in a\ngeneral climate of fear and coercion. Some interlocutors reported that, prior to the vote, the\nauthorities of the Russian Federation had carried out visits to private residences to ask people\nwhat they would do in relation to the referendum. On voting days, interlocutors had seen\n“electoral staff” accompanied by armed personnel going from door to door with ballot boxes."},{"id":"a-hrc-52-62-p0092","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"92","seq":93,"section":"C. Violations of the laws of occupation","text":"Pursuant to the so-called annexation “treaties” between the Russian Federation and\nthe four occupied provinces, citizenship of the Russian Federation was granted in the areas\nconcerned. The Commission was informed of situations in which local residents had felt\ncompelled to apply for passports of the Russian Federation. Civilians of retirement age, in\nparticular, had applied for passports after receiving messages from representatives of the\nauthorities of the Russian Federation suggesting that they would need to do so in order to\nreceive or continue to receive pensions. Civil servants and other employees of State services\nwho sought to retain their employment under the administration of the Russian Federation\nwere required to apply for passports as a condition for maintaining their positions."},{"id":"a-hrc-52-62-p0093","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"93","seq":94,"section":"C. Violations of the laws of occupation","text":"According to testimonies, the authorities of the Russian Federation detained local\nofficials and employees in the occupied areas to force them to cooperate. In March 2022, the\nMayor of Melitopol, in Zaporizhzhia Province, was detained at the Palace of Culture in\nMelitopol. Furthermore, in August 2022, the head of a rural community in Kherson Province\nwas detained by the armed forces of the Russian Federation, who broke into her home. The\nCommission obtained the names of 27 heads of territorial communities in Kherson Province\nwho were reportedly detained by the authorities of the Russian Federation. There were also\ncases in which school principals and teachers were detained, subjected to ill-treatment and\nexpelled from their hometowns to force them to apply the curricula of the Russian Federation\nin schools. Threatening and intimidating messages were sent to parents to force them to enrol\ntheir children in schools operating under the system of the Russian Federation in occupied\nareas."},{"id":"a-hrc-52-62-p0094","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"94","seq":95,"section":"C. Violations of the laws of occupation","text":"The Commission concluded that the authorities of the Russian Federation exercised\nphysical and moral coercion against civilians in occupied areas, in violation of international\nhumanitarian law.52 In addition, they unlawfully confined persons, constituting a war crime.53"},{"id":"a-hrc-52-62-p0095","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"95","seq":96,"section":"D. Forced transfer and deportation of children","text":"The Ukrainian authorities and the authorities of the Russian Federation have declared\nthat hundreds of thousands of children have been transferred from Ukraine to the Russian\nFederation since 24 February 2022, citing figures that vary greatly. A data-collection system\nmaintained by the Government of Ukraine indicated that 16,221 children had been deported\nto the Russian Federation up to the end of February 2023.54 The Commission was unable to\nverify these figures."},{"id":"a-hrc-52-62-p0096","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"96","seq":97,"section":"D. Forced transfer and deportation of children","text":"According to statements and media reports, the authorities of the Russian Federation\nhave taken legal and policy measures regarding Ukrainian children transferred to the Russian\nFederation. These measures include the granting of citizenship and the placement of children\nin foster families, which appear to have created a framework under which some of the\nchildren may end up remaining permanently in the Russian Federation. In this regard, in May\n2022, Mr. Putin signed a decree facilitating applications for citizenship of the Russian\nFederation for some categories of children.55 In July 2022, Maria Lvova-Belova, Presidential\n51 See General Assembly resolution 2625 (XXV), annex. See also Assembly resolution 3314 (XXIX),\nannex, art. 5 (3).\n52 Fourth Geneva Convention, art. 31.\n53 Ibid., art. 147.\n54 See https://childrenofwar.gov.ua.\n55 Available at http://publication.pravo.gov.ru/Document/View/0001202205300008 (in Russian only).\nCommissioner for Children’s Rights, declared that “now that the children have become\nRussian citizens, temporary guardianship can become permanent”.56"},{"id":"a-hrc-52-62-p0097","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"97","seq":98,"section":"D. Forced transfer and deportation of children","text":"The Commission identified three main situations in which the authorities of the\nRussian Federation transferred Ukrainian children from one area that they controlled in\nUkraine to another or to the Russian Federation. The transfers affected children who had lost\nparents or had temporarily lost contact with them during hostilities, children who had been\nseparated following the detention of a parent at a filtration point, and children in institutions.\nThe Commission reviewed incidents concerning the transfer of 164 children, 4 to 18 years of\nage, from Donetsk, Kharkiv and Kherson Provinces."},{"id":"a-hrc-52-62-p0098","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"98","seq":99,"section":"D. Forced transfer and deportation of children","text":"Under international humanitarian law, no party to the armed conflict may arrange for\nthe evacuation of children, other than its own nationals, to a foreign country except for a\ntemporary evacuation where compelling reasons of the health or medical treatment of the\nchildren or, except in occupied territory, their safety so require, and the written consent of\nthe children’s parents or legal guardians is required. 57 In none of the situations that the\nCommission examined did transfers of children appear to have satisfied the requirements set\nforth by international humanitarian law. The transfers were not justified by safety or medical\nreasons. There seems to be no indication that it was impossible to allow the children to\nrelocate to territory under the control of the Government of Ukraine. It also does not appear\nthat the authorities of the Russian Federation sought to establish contact with the children’s\nrelatives or with the Ukrainian authorities. While the transfers were supposed to be\ntemporary, for a variety of reasons most became prolonged, and parents or legal guardians\nand children encountered an array of obstacles in establishing contact, achieving family\nreunification and returning the children to Ukraine."},{"id":"a-hrc-52-62-p0099","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"99","seq":100,"section":"D. Forced transfer and deportation of children","text":"In a separate situation, large numbers of children from areas that had come under the\ncontrol of the Russian Federation in Kharkiv, Kherson and Zaporizhzhia Provinces travelled\ntemporarily, with parental consent, to vacation camps in the Russian Federation or in the\nAutonomous Republic of Crimea and the city of Sevastopol, Ukraine. According to the\nparents and children concerned, when the three provinces returned to the control of the\nGovernment of Ukraine, the authorities of the Russian Federation required parents or legal\nguardians to travel in person to pick up their children. As this involved long and complicated\njourneys and security risks, not all parents were able to do so, which led to prolonged or even\nindefinite family separation."},{"id":"a-hrc-52-62-p0100","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"100","seq":101,"section":"D. Forced transfer and deportation of children","text":"Parents and children told the Commission that during the children’s stay in the\nRussian Federation or in areas of Ukraine that were controlled by the Russian Federation,\nsocial service workers had in some cases told the children that they would be placed in\ninstitutions, accommodated in foster families or adopted. Parents also told the Commission\nthat in some places to which their children had been transferred, the children wore dirty\nclothes and were screamed at and called names. Meals were poor and some children with\ndisabilities did not receive adequate care and medication. Children expressed a profound fear\nof being permanently separated from their parents, guardians or other relatives."},{"id":"a-hrc-52-62-p0101","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"101","seq":102,"section":"D. Forced transfer and deportation of children","text":"In all the incidents examined by the Commission, the onus to trace and find parents\nor other relatives fell primarily on the children. Parents and relatives encountered\nconsiderable logistical, financial and security challenges in retrieving their children. In some\ncases, it took weeks or months for families to be reunited. Witnesses told the Commission\nthat many of the smaller children transferred have not been able to establish contact with their\nfamilies and might, as a consequence, lose contact with them indefinitely."},{"id":"a-hrc-52-62-p0102","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"102","seq":103,"section":"D. Forced transfer and deportation of children","text":"The Commission concluded that the situations that it examined concerning the transfer\nof children within Ukraine and the deportation of children to the Russian Federation violated\ninternational humanitarian law and amounted to war crimes.58 It found that the authorities of\nthe Russian Federation violated their obligation under international humanitarian law to\nfacilitate in every possible way the reunion of families dispersed as a result of the armed\nconflict.59 Such conduct could also amount to the war crime of unjustifiable delay in the\nrepatriation of civilians.60 In addition, the citizenship and family-placement measures, which\ncould have profound implications for the identity of the children concerned, were in violation\nof the children’s right to preserve their identity, including nationality, name and family\nrelations, without unlawful interference, as recognized under international human rights\nlaw.61"},{"id":"a-hrc-52-62-p0103","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"103","seq":104,"section":"V. Accountability measures","text":"The Commission is mandated to make recommendations on, in particular,\naccountability measures.62 The term “accountability measures” is broad in scope, covering\nnot only criminal responsibility, but also non-judicial measures."},{"id":"a-hrc-52-62-p0104","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"104","seq":105,"section":"V. Accountability measures","text":"The International Criminal Court is investigating alleged war crimes, crimes against\nhumanity and genocide in Ukraine.63 The Court does not have jurisdiction over the crime of\naggression in Ukraine. Suggestions have been made to establish a special tribunal on\naggression. Any such tribunal would have to coordinate with the Court. Furthermore, it\nshould have the required international legitimacy with respect to both its establishment and\nits functioning. Discussions about a new tribunal should be combined with efforts to amend\nthe Rome Statute, so that the Court’s jurisdiction over the crime of aggression is identical to\nits jurisdiction over the other three crimes."},{"id":"a-hrc-52-62-p0105","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"105","seq":106,"section":"V. Accountability measures","text":"In addition to judicial measures, other dimensions of accountability include truth,\nreparations and guarantees of non-repetition.64 The full satisfaction of victims’ rights will be\nimpossible before the cessation of hostilities, but measures can be taken already to contribute\nto the eventual satisfaction of those rights. Priority should be given to a victims’ registry and\nto institutional support, including mental health and psychosocial services."},{"id":"a-hrc-52-62-p0106","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"106","seq":107,"section":"V. Accountability measures","text":"The Commission encourages the robust coordination of the many national and\ninternational accountability actors. Minimizing duplication and the retraumatization of\nvictims while increasing the efficient use of resources is achievable. Practical steps include\nmapping the various actors conducting investigations, which could facilitate the\nestablishment of an index of shareable evidence."},{"id":"a-hrc-52-62-p0107","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"107","seq":108,"section":"VI. Conclusions and recommendations","text":"The armed conflict in Ukraine has had devastating effects at various levels, most\nnotably on individuals and communities and on the society, environment and economy\nof Ukraine. It has had a considerable effect on the enjoyment of almost all human rights.\nPeople are living in a climate of unbearable uncertainty and fear. Scores of survivors\nare coping with the immediate consequences of violent events and large-scale damage.\nIn addition to the many physical injuries that will take time to heal, the deep\npsychological impact will have long-lasting effects."},{"id":"a-hrc-52-62-p0108","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"108","seq":109,"section":"VI. Conclusions and recommendations","text":"The Commission is concerned about the number, geographic spread and gravity\nof the human rights violations and the corresponding international crimes that it has\ndocumented under its mandate, which have affected men, women, boys and girls of all\nbackgrounds and ages."},{"id":"a-hrc-52-62-p0109","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"109","seq":110,"section":"VI. Conclusions and recommendations","text":"The Commission has concluded that the authorities of the Russian Federation\nhave committed numerous violations of international humanitarian law and\ninternational human rights law, in addition to a wide range of war crimes, including the\n59 Protocol I Additional to the Geneva Conventions of 1949, art. 74.\n60 Ibid., art. 85 (4) (b) and (5).\n61 Convention on the Rights of the Child, art. 8 (1).\n62 Human Rights Council resolution 49/1, para. 11 (e).\n63 International Criminal Court, “Statement of ICC Prosecutor, Karim A.A. Khan, QC, on the situation\nin Ukraine: receipt of referrals from 39 States parties and the opening of an investigation“,\n2 March 2022.\n64 See General Assembly resolutions 60/147 and 40/34.\nwar crime of excessive incidental death, injury or damage, wilful killings, torture,\ninhuman treatment, unlawful confinement, rape, and unlawful transfer and\ndeportation. The Commission has also found that the waves of attacks by the armed\nforces of the Russian Federation, starting on 10 October 2022, on the energy-related\ninfrastructure of Ukraine and the use of torture by the authorities of the Russian\nFederation may amount to crimes against humanity."},{"id":"a-hrc-52-62-p0110","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"110","seq":111,"section":"VI. Conclusions and recommendations","text":"In a limited number of cases, the Commission has found that the Ukrainian\narmed forces were likely responsible for violations of international humanitarian law\nand international human rights law and for some incidents that qualify as war crimes,\nincluding indiscriminate attacks and two incidents of wounding and torture of prisoners\nof war of the Russian Federation."},{"id":"a-hrc-52-62-p0111","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"111","seq":112,"section":"VI. Conclusions and recommendations","text":"Beyond sharing with the Commission their deep loss and trauma, survivors have\nhighlighted the importance of identifying those responsible and bringing them to\naccount. One man, whose father was executed by the armed forces of the Russian\nFederation in a village in Kharkiv Province, told the Commission: “They punished\ninnocent people; now those who are guilty, if they are still alive, need to be punished to\nthe fullest extent.”"},{"id":"a-hrc-52-62-p0112","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"112","seq":113,"section":"VI. Conclusions and recommendations","text":"The Commission recommends that the parties to the conflict:\n(a)    Respect and ensure compliance with all obligations stipulated in relevant\ntreaties and customary international law regarding international humanitarian law,\ninternational human rights law and international criminal law;\n(b)   Comply with all the obligations enshrined in international humanitarian\nlaw, including keeping accurate records of all people under the control of each party\nand exchanging information on that basis;\n(c)     Ensure that the International Committee of the Red Cross has\nunrestricted access to carry out its work in accordance with its mandate under\ninternational law;\n(d)   Respect the space for humanitarian action and protect it from\ndisinformation, politicization and polarization;\n(e)    Take all feasible measures, in accordance with international standards, to\nlocate all disappeared or missing persons, including women, men, girls and boys,\nestablish their fate and ensure communication with their families;\n(f)   Ensure the timely, effective, thorough, independent, impartial and\ntransparent investigation and prosecution of all allegations of international crimes and\nviolations of international human rights law and international humanitarian law,\nincluding sexual and gender-based violence and violence against children;\n(g)   Hold all perpetrators accountable through judicial proceedings, in\naccordance with international human rights standards;\n(h)    Take all the measures necessary to ensure that the right to truth of all\nvictims is satisfied and that they eventually obtain redress and remedy, including\ncompensation and rehabilitation;\n(i)   Ratify international instruments to which they are not yet party that will\nstrengthen the protection of civilians in armed conflict."},{"id":"a-hrc-52-62-p0113","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"113","seq":114,"section":"VI. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation immediately:\n(a)    Cease aggression and all acts of violence committed against civilians in\nviolation of applicable international human rights law and international humanitarian\nlaw and end the use of torture and other forms of ill-treatment, including sexual and\ngender-based violence;\n(b)   Take all feasible precautions to protect civilians and civilian\ninfrastructure and end massive attacks against energy-related infrastructure in\nUkraine;\n(c)    Provide reliable and comprehensive information about the number and\nwhereabouts of all children who have, for whatever reason, been transferred within\nUkraine or deported to the Russian Federation; facilitate effective communication\nbetween such children and their families, and promptly and proactively initiate the\nreturn to Ukraine of children deported to the Russian Federation, in accordance with\ntheir best interests and with international obligations, using technical assistance from\ninternational organizations; and prevent any further transfers of children within or\ntheir deportation from Ukraine;\n(d)    Release or return to Ukraine all Ukrainian civilians who have been\ndeported to the Russian Federation and are being detained there as a consequence of\nthe armed conflict."},{"id":"a-hrc-52-62-p0114","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"114","seq":115,"section":"VI. Conclusions and recommendations","text":"The Commission further recommends that the Russian Federation:\n(a)    Ensure that all perpetrators, including commanders and other superiors\nand those ordering, soliciting or inducing the commission of international violations and\ncrimes, are held accountable;\n(b)    Take the measures necessary to prevent the commission of such violations\nand crimes, in particular through unequivocal instructions to all branches of the armed\nforces and other entities participating in the armed conflict, with a view to ensuring that\nmilitary discipline and respect for international human rights law and international\nhumanitarian law are upheld along with the principle of command responsibility;\n(c)   Limit the use of private military and security companies in the conflict, as\nexperience has shown that they frequently engage in violations of international law and\nare generally less accountable than regular forces since they lie outside the formal lines\nof command and have a great incentive to compete with one another and with regular\nforces;\n(d)   Respect international humanitarian law applicable to occupied territories\nand refrain from placing any impediment to humanitarian assistance in those\nterritories;\n(e)    Cooperate fully with all international monitoring and investigative bodies."},{"id":"a-hrc-52-62-p0115","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"115","seq":116,"section":"VI. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)   Establish a victims registry as an institutional portal for better\ncoordination of available government services to victims, constituting a preliminary\nstep towards a comprehensive reparations programme;\n(b)   Comprehensively address the mental health and psychosocial needs\nresulting from the armed conflict by tackling access and the allocation of resources to\nthe relevant services and enhancing their institutional coordination, legal regulation,\nmonitoring and evaluation, in the context of the Ukrainian operational road map on\nprioritized multisectoral mental health and psychosocial support actions during and\nafter the war;\n(c)    Harmonize its legislation relating to war crimes where it is not in\nconformity with international standards and amend its criminal code to clarify the\ndefinition of “collaborative activity” to avoid legal uncertainty and harm to social\ncohesion;\n(d)    Develop an investigatory and prosecutorial strategy that prioritizes cases\non the basis of clear criteria and ensure due process and transparent monitoring, taking\ninto account both the enormous caseload and the limited resources."},{"id":"a-hrc-52-62-p0116","rec_id":"recXaNYqw5G1g6GC0","symbol":"A/HRC/52/62","n":"116","seq":117,"section":"VI. Conclusions and recommendations","text":"The Commission recommends that other States and regional and international\norganizations:\n(a)    Strengthen national, regional and international accountability\nmechanisms, both judicial and non-judicial, including by improving their coordination\nand supporting the effective participation of civil society and groups representing\nvictims and survivors;\n(b)     Integrate the human rights dimensions of the armed conflict in Ukraine\nmore fully into the agenda of the Security Council."},{"id":"a-78-540-u0000","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":null,"seq":0,"section":null,"text":"United Nations                                                                            A/78/540\nGeneral Assembly                                                      Distr.: General\n19 October 2023","unnumbered":true},{"id":"a-78-540-u0001","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":null,"seq":1,"section":null,"text":"The Secretary-General has the honour to transmit to the General Assembly the\nreport of the Independent International Commission of Inquiry on Ukraine, submitt ed\nin accordance with paragraph 19 of Human Rights Council resolution 52/32, on the\nsituation of human rights in Ukraine stemming from the Russian aggression.","unnumbered":true},{"id":"a-78-540-u0002","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":null,"seq":2,"section":null,"text":"Summary\nThe present report is submitted to the General Assembly by the Independent\nInternational Commission of Inquiry on Ukraine pursuant to Human Rights Council\nresolution 52/32, by which the Council renewed the Commission’s initial mandate for\none additional year.\nAs the armed conflict continues in its second year, it has further contributed to\nsuffering and hardship for thousands of affected civilians. The Commission has found\nnew evidence that Russian authorities have committed violations of international\nhuman rights and international humanitarian law, and corresponding crimes, in areas\nthat came under their control in Ukraine. It documented additional indiscriminate\nattacks by Russian armed forces, which have led to deaths and injuries of civilians\nand the destruction and damage of civilian objects.\nThe collected evidence further shows that Russian authorities have committed\nthe war crimes of wilful killing, torture, rape and other sexual violence, and the\ndeportation of children to the Russian Federation. The Commission’s investigations\nconfirmed its previous finding that Russian authorities had used torture in a\nwidespread and systematic way in various types of detention facilities that they\nmaintained. Interviews with victims and witnesses illustrated a profo und disregard\ntowards human dignity by Russian authorities in those circumstances. The\nCommission also documented cases in which Russian soldiers burst into houses of\nvillages that they occupied, raped women and a girl, and committed additional war\ncrimes against the victims and their family members.\nIn three cases, investigations found that Ukrainian authorities had committed\nviolations of human rights against persons whom they had accused of collaboration\nwith the Russian authorities.\nThe Commission is concerned at the gravity of the documented violations and\ncrimes and their impact on victims, survivors and the affected communities. It calls\nupon the conflict parties concerned to halt war crimes and violations of human rights.\nThe Commission also reiterates the importance of accountability, in all its\ndimensions, with full respect for the rights of and care for the victims.","unnumbered":true},{"id":"a-78-540-p0001","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"1","seq":3,"section":null,"text":"On 4 March 2022, the Human Rights Council, by its resolution 49/1, established\nan independent international commission of inquiry on Ukraine to investigate all\nalleged violations and abuses of human rights and violations of international\nhumanitarian law, and related crimes, in the context of the Russian Federation’s\naggression against Ukraine. After the submission by the Independent International\nCommission of Inquiry on Ukraine of its comprehensive report dated 15 March 2023\nto the Council at its fifty-second session, 1 the Council, by its resolution 52/32,\nextended the Commission’s mandate for a further period of one year."},{"id":"a-78-540-p0002","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"2","seq":4,"section":null,"text":"Since March 2022, Erik Møse (Norway) and Pablo de Greiff (Colombia) have\nbeen serving as members of the Commission, with Mr. Møse as Chair. After the\ncompletion of the mandate of Jasminka Džumhur (Bosnia and Herzeg ovina), the\nPresident of the Human Rights Council appointed, on 28 June 2023, Vrinda Grover\n(India) to serve as a member of the Commission."},{"id":"a-78-540-p0003","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"3","seq":5,"section":null,"text":"The Commission abides by the principles of independence, impartiality,\nobjectivity and integrity. It adopts a victim-centred approach and adheres to the “do\nno harm” principle. It applies the standard of proof of “reasonable grounds to\nconclude” and reaches determinations when, on the basis of a body of verified\ninformation, an objective and ordinary prudent observer would conclude that the facts\ntook place as described."},{"id":"a-78-540-p0004","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"4","seq":6,"section":null,"text":"The present report, submitted to the General Assembly at its seventy -eighth\nsession, as mandated by the Human Rights Council in its resolution 52/32, builds on\nthe Commission’s March 2023 report and its detailed conference room paper released\non 29 August 2023 (A/HRC/52/CRP.4). It outlines preliminary findings since the\nrenewal of its mandate. Owing to the large number of relevant events and security\nand logistical constraints, the Commission focused on samples of allegations and\ncases that illustrate specific patterns. In preparing the present report, it visited 32\nsettlements in nine regions of Ukraine, a majority in Kherson and Zaporizhzhia\nProvinces, and travelled to Poland. It relied on 466 interviews with 445 persons (222\nwomen and 223 men), inspected sites of attacks and places where detention and torture\nwere committed, and compiled and examined documents, photographs and videos."},{"id":"a-78-540-p0005","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"5","seq":7,"section":null,"text":"The Commission appreciates the access and cooperation extended by the\nGovernment of Ukraine. It regrets that its efforts to engage with the Russian\nFederation proved unsuccessful. The Commission addressed to Russian officials 19\nwritten requests for meetings, access and information, without receiving any answer.\nIt also consistently expressed in public an interest in establishing meaningful\ncommunication with Russian officials."},{"id":"a-78-540-p0006","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"6","seq":8,"section":null,"text":"The Commission expresses its gratitude for the valuable testimonies and other\ninformation that it received from victims, witnesses, other interlocutors and\norganizations.\nII. Legal framework"},{"id":"a-78-540-p0007","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"7","seq":9,"section":null,"text":"International human rights law, international humanitarian law and international\ncriminal law constitute the law applicable to the mandate of the Commission."},{"id":"a-78-540-p0008","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"8","seq":10,"section":null,"text":"The Russian Federation and Ukraine are party to seven and eight United Nations\ncore international human rights instruments, respectively. They are also bound by\nvarious international humanitarian law instruments, including the four Geneva\nConventions of 1949. The situation in Ukraine is an international armed conflict,\npursuant to common article 2 of said Conventions. Neither Ukraine nor the Russian\nFederation is a State party to the Rome Statute of the International Criminal Court.\nHowever, the Court has jurisdiction in Ukraine, pursuant to two declarations lodged\nby Ukraine and referrals by States parties. The Rome Statute and its Elements of\nCrimes provide detailed elements for some of the alleged crimes. Where the Court\nwas found to lack jurisdiction, the Commission applied the elements of crimes within\nthe Rome Statute so long as they reflected customary international law."},{"id":"a-78-540-p0009","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"9","seq":11,"section":"III. Background: political and military context","text":"The armed conflict has continued to affect millions of persons in Ukraine, with\nconsiderable regional and international ramifications. In 2023, armed hostilities have\nbeen concentrated in large part on south-eastern Ukraine, in particular in Donetsk,\nKherson, Luhansk and Zaporizhzhia Provinces. Early in June 2023, Ukraine launched\na counteroffensive focusing primarily on Donetsk and Zaporizhzhia Provinces. Heavy\nlosses have been reported on both sides."},{"id":"a-78-540-p0010","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"10","seq":12,"section":"III. Background: political and military context","text":"Other provinces of Ukraine, further from the frontline, have also been affected\nby explosive weapons hitting residential buildings and other civilian structures.\nRussian armed forces continued to launch large-scale attacks targeting infrastructure\nacross Ukraine. Shelling of border areas in the Russian Federation an d drone attacks\ndeeper in the country, including in Moscow, have been reported. Ukrainian official\nsources claimed responsibility for some of the attacks."},{"id":"a-78-540-p0011","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"11","seq":13,"section":"III. Background: political and military context","text":"In the meantime, there have been no immediate prospects for an end to the armed\nconflict through political and diplomatic means. At the General Assembly, many\ndelegates urged intensified efforts to bring both parties to the negotiating table. 2 As\nthe armed conflict approached the one-year mark, the Assembly, in its resolution\nES-11/6, demanded “that the Russian Federation immediately, completely and\nunconditionally withdraw all of its military forces from the territory of Ukraine within\nits internationally recognized borders, and calls for a cessation of hostilities”."},{"id":"a-78-540-p0012","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"12","seq":14,"section":"III. Background: political and military context","text":"Several States presented proposals for a settlement through diplomatic means.\nThe President of the Russian Federation, Vladimir Putin, and Russian officials blamed\nUkraine for rejecting talks and continued to justify the armed invasion in Ukraine\nthrough the self-defence clause of the Charter of the United Nations. 3 More broadly,\nofficials of the Government of the Russian Federation further accused “the West” for\nfuelling conflict in Ukraine. 4"},{"id":"a-78-540-p0013","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"13","seq":15,"section":"III. Background: political and military context","text":"The President of Ukraine, Volodymyr Zelenskyy, has promoted the 10 -point\npeace formula that he first outlined in November 2022. 5 During an open debate on\nUkraine held on 20 September 2023 at the Security Council, he reiterated that only\nthe complete withdrawal of Russian armed forces and the full restoration of Ukraine’s\ncontrol over its territories would result in the complete cessation of the hosti lities\n(S/PV.9421 p. 8)."},{"id":"a-78-540-p0014","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"14","seq":16,"section":"III. Background: political and military context","text":"The Initiative on the Safe Transportation of Grain and Foodstuffs from\nUkrainian Ports (Black Sea Initiative) was one of the few areas in which t he Russian\nFederation and Ukraine had managed to reach an agreement. The Russian\nFederation’s refusal to extend its participation in July 2023 was widely condemned."},{"id":"a-78-540-p0015","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"15","seq":17,"section":"III. Background: political and military context","text":"The armed conflict has continued to have devastating consequences for the\ncivilian population of Ukraine. As at 10 September 2023, the Office of the United\nNations High Commissioner for Human Rights had recorded 27,149 civilian\ncasualties (9,614 killed and 17,535 injured). The actual number is likely higher. In\naddition to 6,204,600 persons who had left the country (as at 3 October 2023),\n5,088,000 are internally displaced (as of June 2023). The Office for the Coordination\nof Humanitarian Affairs estimated that 17.6 million people in Ukraine were in need\nof humanitarian assistance, and access for humanitarian assistance to areas affected\nby the fighting has proved to be challenging. In addition to physical and psychologic al\ntrauma, the armed conflict has resulted in severe limitations on the enjoyment of some\nof the most basic human rights.\nIV. Violations of international law"},{"id":"a-78-540-p0016","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"16","seq":18,"section":"III. Background: political and military context","text":"The Commission gathered new evidence of violations of international human\nrights law and international humanitarian law, and corresponding crimes committed\nby the Russian authorities 6 in Ukraine. It has investigated unlawful attacks with\nexplosive weapons and their impact on civilians, torture, sexual and gender-based\nviolence, and transfers and deportations of children."},{"id":"a-78-540-p0017","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"17","seq":19,"section":"III. Background: political and military context","text":"It found three incidents in which violations of human rights had been committed\nby Ukrainian authorities 7 and is further investigating these and other allegations of\nsuch violations.\nA.       Violations committed during the conduct of hostilities"},{"id":"a-78-540-p0018","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"18","seq":20,"section":"III. Background: political and military context","text":"The Commission documented additional individual attacks with explosive\nweapons. It condemns again attacks that affect civilians and civilian objects,\nincluding those in which large numbers of civilians were present."},{"id":"a-78-540-p0019","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"19","seq":21,"section":"III. Background: political and military context","text":"It examined numerous reports of attacks in territory under the control of the\nGovernment of Ukraine. The Commission found reasonab le grounds to conclude that\nthe strike of a residential building in Uman, Cherkasy Province, on 28 April 2023, as\nwell as strikes that affected a supermarket and a gas station in Kherson city, Kherson\nProvince, on 3 May 2023, were indiscriminate attacks pe rpetrated by Russian armed\nforces, in violation of international humanitarian law. The attacks led to considerable\nloss of civilian life, injuries and destruction. In both cases, the Commission concluded\nthat Russian armed forces had failed to take feasible precautions to ensure that the\nobjects affected were not civilian."},{"id":"a-78-540-p0020","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"20","seq":22,"section":"III. Background: political and military context","text":"The Commission also investigated two attacks in areas that were under the\ncontrol of Russian authorities. It was unable to reach a conclusion owing to lack of\naccess."},{"id":"a-78-540-p0021","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"21","seq":23,"section":"III. Background: political and military context","text":"It continued its consideration of the cumulative impact on civilians of the large -\nscale attacks on Ukraine’s energy infrastructure launched by Russian armed forces\nthat started on 10 October 2022."},{"id":"a-78-540-p0022","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"22","seq":24,"section":"III. Background: political and military context","text":"Lastly, the Commission initiated investigations concerning the circumstances of\nthe breach at the Kakhovka dam."},{"id":"a-78-540-p0023","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"23","seq":25,"section":"1. Impact of attacks with explosive weapons","text":"Attacks with explosive weapons in populated areas remained the leading cause\nof deaths and injuries among the civilian population. As at 10 September 2023, the\nOffice of the United Nations High Commissioner for Human Rights estimated that\n8,062 persons had been killed and 16,610 injured in such attacks. The actual number\nis likely higher. The Commission visited sites of attacks and spoke with survivors."},{"id":"a-78-540-p0024","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"24","seq":26,"section":"1. Impact of attacks with explosive weapons","text":"In addition to the deep trauma incurred by the loss of loved ones in the aftermath\nof attacks, the population has to cope with considerable challenges in securing\nhousing and access to essential services and supplies. During a visit to Uman, the\nCommission spoke with the residents of the apartment building that had been hit by\na missile. The strike led to a high number of casualties, mainly women and children,\nand substantial damage to the affected block and neighbouring buildings. Survivors\nshared their traumatic experiences and the hardships that they faced owing to the\ndevastation caused by the attack."},{"id":"a-78-540-p0025","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"25","seq":27,"section":"1. Impact of attacks with explosive weapons","text":"Other examples from the Commission’s investigations also illustrate the vast\nchallenges in locations affected by attacks. In Dnipro, Dnipropetrovsk Prov ince, a\nfunctioning clinic providing psychological care, including for trauma relating to the\narmed conflict, was destroyed in an attack on 26 May 2023, during working hours,\nand had to close. This led to the killing of 4 persons and the injury of more tha n 30\nothers, including patients and medical staff. The destruction of a clinic providing\npsychological care to people already scarred by the conflict predictably leads to\nretraumatization."},{"id":"a-78-540-p0026","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"26","seq":28,"section":"1. Impact of attacks with explosive weapons","text":"In Kramatorsk, Donetsk Province, a restaurant was hit on 27 Jun e 2023, during\nits busiest working hour, leading to the death of at least 11 civilians, including 3 girls,\nand many injuries. In Kherson city, a major retailer had to close after it was affected\nby an attack on 3 May 2023, limiting the availability of places where the population\ncould get essential supplies. Those attacks represent only a small sample among the\nmultitude of situations affecting the lives of the civilian population."},{"id":"a-78-540-p0027","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"27","seq":29,"section":"2. Individual attacks with explosive weapons","text":"In international humanitarian law, indiscriminate attacks are those that are not\ndirected at a specific military objective or employ a method or means of combat that\ncannot be directed at a specific military objective or the effects of which cannot be\nlimited. The Commission has recently documented attacks that affected civilian\nobjects, such as residential buildings, a railway station, shops and a warehouse for\ncivilian use, leading to numerous casualties. It is further investigating attacks that hit\ncivilian objects."},{"id":"a-78-540-p0028","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"28","seq":30,"section":"2. Individual attacks with explosive weapons","text":"Weapons employed include missiles and rockets that, when used in populated\nareas, have a wide impact that can cause harm and damage to civilians and critical\ninfrastructure."},{"id":"a-78-540-p0029","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"29","seq":31,"section":"2. Individual attacks with explosive weapons","text":"In most incidents, the Commission has been unable to identify a military\npresence in the locations affected by the attacks. It also found that, in some situations,\nadequate precautions had not been taken to verify the targets. This was, for example,\nthe case of the above-mentioned attack on a residential building in Uman, which\nstruck objects that had not served a military purpose for more than two decades.\n(a)       Attacks with explosive weapons carried out by Russian armed forces"},{"id":"a-78-540-p0030","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"30","seq":32,"section":"2. Individual attacks with explosive weapons","text":"The Commission documented additional indiscriminate attacks committed by\nRussian armed forces in territory controlled by the Government of Ukraine. Below\nare detailed descriptions of two cases that it investigated.\nUman city, Cherkasy Province, 28 April 2023"},{"id":"a-78-540-p0031","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"31","seq":33,"section":"2. Individual attacks with explosive weapons","text":"On 28 April 2023, between 4.20 and 4.30 a.m., two missiles struck an apartment\nbuilding on Zakhysnykiv Ukrainy street 25 and a warehouse in Uman city, Cherkasy\nProvince. The attack resulted in the killing of 24 civilians (14 women, 4 men, 3 boys\nand 3 girls) and the injury of many others, in the residential building affected directly\nand in two neighbouring buildings. Consequently, 45 apartments became uninhabitable\nand many others have been severely damaged, with shattered windows, ripped doors\nand balconies, and gas and electricity cuts as a consequence of the atta ck."},{"id":"a-78-540-p0032","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"32","seq":34,"section":"2. Individual attacks with explosive weapons","text":"The Commission focused its investigation on the residential building. The attack\nwas part of a large-scale strike with long-range missiles carried out by Russian armed\nforces. Russian authorities acknowledged carrying out a large -scale strike during that\nnight. 8 On the basis of the available evidence, the weapon used appears to be a Kh-101\ncruise missile, which Russian armed forces possess in their stockpile. These missiles\nare not known to be part of the Ukrainian stockpile."},{"id":"a-78-540-p0033","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"33","seq":35,"section":"2. Individual attacks with explosive weapons","text":"The Commission investigated whether the strike on the building may have been\nthe result of an interception by Ukrainian air defence, which may have potentially\ncaused the incoming missile to deviate from its course. However, on the basis of\nexpert analysis of available documents and other technical information obtained, the\nCommission found that this was unlikely."},{"id":"a-78-540-p0034","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"34","seq":36,"section":"2. Individual attacks with explosive weapons","text":"No military presence was identified in either of the areas affected by the strikes.\nAccording to residents’ accounts and reviewed documents, more than 20 year s ago\nthe warehouse served as a military maintenance base, whereas the apartment building\nwas a dormitory for civilians and military working there. Both were hit within a few\nminutes of each other. The residential building was privatized around 2002 and, a t the\ntime of the attack, was a civilian object with more than 99 apartments."},{"id":"a-78-540-p0035","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"35","seq":37,"section":"2. Individual attacks with explosive weapons","text":"The Commission concluded that Russian armed forces, in violation of\ninternational humanitarian law, had conducted an indiscriminate attack on a\nresidential building in Uman city and failed to take feasible precautions to ensure that\nthe objective was not civilian.\nKherson city, Kherson Province, 3 May 2023"},{"id":"a-78-540-p0036","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"36","seq":38,"section":"2. Individual attacks with explosive weapons","text":"On 3 May 2023, starting at 10 a.m., a succession of attacks with explosive\nweapons took place over the course of several hours and struck various locations in\nKherson city, including an ATB supermarket, an OKKO gas station, the railway\nstation, an Epicentr hypermarket and a residential building. Ukrainian authorities\nrecorded casualties at 10 impact sites in Kherson city and its surroundings, with 21\ncivilians killed (12 men and 9 women) and dozens injured."},{"id":"a-78-540-p0037","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"37","seq":39,"section":"2. Individual attacks with explosive weapons","text":"The Commission focused its investigations on three of the impacted sites,\nnamely, the ATB supermarket, the OKKO gas station and the railway station. On the\nbasis of witness statements and an analysis of photographs and videos of weapon\nremnants, it determined that the three sites had been hit with rocket artillery systems.\nPhotographs taken in the aftermath of the strikes at the ATB supermarket and at the\nOKKO gas station showed remnants that appear to be BM-21 MLRS Grad rockets."},{"id":"a-78-540-p0038","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"38","seq":40,"section":"2. Individual attacks with explosive weapons","text":"No military presence was identified at the locations hit. Witness declarations,\nan analysis of the position of remnants and of the damage at the ATB supermarket and\nthe OKKO gas station indicated that the strikes had come from a southern direction.\nA similar analysis of the impact site at the railway station led the Commission to\nassess that the strike had come from a likely southern direction. The left bank of the\nDnipro River in the Kherson city area was under the control of Russian armed forces\nat the time of the attack, within striking distance of the BM -21 MLRS Grad missile\nsystem."},{"id":"a-78-540-p0039","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"39","seq":41,"section":"2. Individual attacks with explosive weapons","text":"The Commission concluded that Russian armed forces had carried out\nindiscriminate attacks on the ATB supermarket and the OKKO gas station, had likely\nalso carried out the attack that hit the railway station, all in Kherson city, and had\nfailed to take precautions to verify that the objectives were not civilian.\n(b)   Attacks carried out in areas under the control of Russian authorities"},{"id":"a-78-540-p0040","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"40","seq":42,"section":"2. Individual attacks with explosive weapons","text":"The Commission investigated two reported incidents with the use of explosive\nweapons in areas of the Donetsk and Luhansk Provinces that are under the control of\nRussian authorities. It sent requests for information to both parties to the armed\nconflict and did not receive a response from the Russian Federation. Two previous\nrequests for access to the Russian-appointed authorities of the so-called Donetsk and\nLuhansk People’s Republics have remained unanswered."},{"id":"a-78-540-p0041","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"41","seq":43,"section":"2. Individual attacks with explosive weapons","text":"According to media reports, on 28 January 2023 an attack struck the Novoaidar\ngeneral hospital in Novoaidar, Luhansk Province, leading to the death of 14 persons\nand the injury of many others. One institution from the Russian Federation informed\nthe Commission of the attack. It reviewed publicly available photographs and videos\nof the damage and confirmed that these showed the Novoaidar general hospital.\nSatellite imagery also confirmed damage to one wing of the hospital. Information\navailable suggests that the hospital was functional at the time of the incident. The\nUkrainian authorities informed the Commission that they had opened a pretrial\ninvestigation into the shelling."},{"id":"a-78-540-p0042","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"42","seq":44,"section":"2. Individual attacks with explosive weapons","text":"In addition, the Commission examined information that appeared from January\nto April 2023 on social media concerning incidents involving anti-personnel high-\nexplosive landmines known as “PFM-1” or “butterfly mines”, in two western suburbs\nof Donetsk city. In total, 11 injuries were reported. One Russian institution shared\ninformation about injuries in March and April 2023. The locations concerned are in\ntwo populated areas west of Donetsk city, close to the line of contact, where heavy\nfighting took place at that time."},{"id":"a-78-540-p0043","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"43","seq":45,"section":"2. Individual attacks with explosive weapons","text":"The Commission has been unable to proceed with its investiga tion of both\nsituations because it has no access to the relevant areas. It recommends further\ninvestigations and reiterates the importance of access to pursue all investigations\nrequired pursuant to its mandate."},{"id":"a-78-540-p0044","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"44","seq":46,"section":"3. Impact of the attacks on the energy infrastructure of Ukraine","text":"In a previous report, the Commission had expressed concern at the impact on\ncivilians of the large-scale waves of attacks on energy infrastructure launched by the\nRussian armed forces starting on 10 October 2022 ( A/HRC/52/62, paras. 40–43). It\nis examining in further detail the consequences of the attacks for the civilian\npopulation. Prevalent during the colder months, the attacks hit electricity -related\ninstallations, causing temporary outages, which sometimes affected millions of people.\nThese, in turn, resulted in electricity, heating and water cuts, with consequences for\nthe operation of services."},{"id":"a-78-540-p0045","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"45","seq":47,"section":"3. Impact of the attacks on the energy infrastructure of Ukraine","text":"From the Commission’s interviews, Kyiv and Odesa were among the provinces\nparticularly hit. Two residents of Odesa reported recurrent power outages, of up to\nthree days, during the winter. Owing to the scarcity of power, at times electricity\nsupply was available only during pre-established and limited periods of time.\nReportedly, persons living on higher floors had challenges with water supply. Those\nrequiring constant medical treatment with electric devices faced specific difficulties.\nPersons who were older or had disabilities were particularly v ulnerable, with some of\nthem confined in their apartments without power. Social workers also had to cope\nwith difficult working conditions in the absence of electricity."},{"id":"a-78-540-p0046","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"46","seq":48,"section":"3. Impact of the attacks on the energy infrastructure of Ukraine","text":"These are only some of the most obvious and immediate consequences of the\nattacks. The Commission will continue its investigations."},{"id":"a-78-540-p0047","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"47","seq":49,"section":"4. Impact of the breach at Khakovka dam","text":"The Commission is investigating the cause of the breach at the Kakhovka dam\non 6 June 2023. The discharge of water and flooding caused by the breach had\ndetrimental consequences for the fulfilment of basic human rights of the population\nin the affected area and triggered additional displacement. The floods caused loss of\nlives and a threat to the health of the population. According to the most recent\ninformation received from the Government of Ukraine in the aftermath of the events,\n33 persons died, 28 were injured and more than 40 persons were missing. The Russian\nFederation did not respond to the Commission’s questions regarding the impact of the\nbreach on the areas that are under its control. The floods led to the destruction and\ndamage of houses and other buildings and to challenges in gaining access to potable\nwater, food and basic services. Several persons from the localities concerned stated\nthat they were forced to flee because the water had reached their properties. The\nbreach is also expected to have a long-term harmful impact on the economy and the\necology of the region. The Commission will further investigate its short - and long-\nterm consequences.\nB. Personal integrity violations"},{"id":"a-78-540-p0048","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"48","seq":50,"section":"1. Torture committed by Russian authorities","text":"In its report to the Human Rights Council, the Commission found that torture\nwas widely used by Russian authorities in seven provinces of Ukraine and in the\nRussian Federation and detailed how it was practiced in detention facilities (ibid.,\nparas. 71–77). During its second mandate, the Commission has continued to\ndocument the use of torture against numerous persons in additional detention centres\nin Ukraine. It had focused on areas of Kherson and Zaporizhzhia Provinces, which\nwere controlled by Russian authorities for long periods of time. The new evidence is\nconsistent with and reinforces the Commission’s previous finding that the Russian\nauthorities’ use of torture was widespread and systematic."},{"id":"a-78-540-p0049","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"49","seq":51,"section":"1. Torture committed by Russian authorities","text":"In the cases investigated, perpetrators tortured mainly persons whom they\naccused of passing information to the Ukrainian authorities or of otherwise supporting\nthe Ukrainian armed forces. Victims were men and women of age s ranging from 29\nto 57. Russian authorities, in general, committed torture during interrogation sessions.\nOften held repeatedly, these were aimed mostly at extracting information from the\nvictims. Former detainees reported the existence of rooms allocated specifically to\ninterrogation and torture. Consistent with its previous conclusions, the Commission\nfound that similar methods of torture had been used across various detention facilities\nthat it examined."},{"id":"a-78-540-p0050","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"50","seq":52,"section":"1. Torture committed by Russian authorities","text":"The use of torture in additional detention facilities across Ukraine confirms the\nCommission’s previous finding that it was widespread. The targeting of specific\ncategories of persons, combined with common elements in the purpose of\ninterrogation sessions and the way in which torture was practised, led the Commission\nto further conclude that its use was systematic."},{"id":"a-78-540-p0051","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"51","seq":53,"section":"1. Torture committed by Russian authorities","text":"Victims of torture recounted how severe physical and mental pain and suffering\nwas inflicted upon them during confinement and interrogation. Torture often led to\nlong-term physical and psychological trauma for the victims and their loved ones. A\nvictim who had been subjected to electric shocks stated, “Every time I answered that\nI didn’t know or didn’t remember something, they gave me electric shocks … I don’t\nknow how long it lasted. It felt like an eternity”. The victim reported not being able\nto walk properly for days and suffering from deep anxiety in the aftermath. The\nhusband of a victim, confined in a neighbouring cell while she was tortured, said, “I\nwill never forget her screaming of pain”."},{"id":"a-78-540-p0052","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"52","seq":54,"section":"1. Torture committed by Russian authorities","text":"The testimonies collected by the Commission show the perpetrators’ profound\ndisregard for the life and the dignity of the victims. Witnesses reported situations in\nwhich torture had been committed with such brutality that it led to death. I n a\ndetention facility in a school in Biliayivka village, Kherson Province, co -detainees\nrequested medical care when a victim presented signs of respiratory distress\nimmediately after being tortured. However, Russian armed forces refused, and the\nvictim died less than one hour later. The Commission found in that case that, in\naddition to torture, the conduct of the perpetrators amounted to unlawful killing. In\nthe same facility, another detainee died in the cell, apparently as a consequence of\ntorture, dehydration and hunger. One day later, Russian soldiers dragged his body out\nof the cell by the feet. In this case, the Commission concluded that, in addition to\ntorture, Russian armed forces had violated the victim’s right to life and caused his\ndeath by way of torture, ill-treatment and inhuman conditions."},{"id":"a-78-540-p0053","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"53","seq":55,"section":"1. Torture committed by Russian authorities","text":"Several victims and witnesses stated that interrogation sessions and torture had\nbeen conducted by personnel of the Federal Security Service of the Russian Federation. 9\nOne victim, formerly detained in the police department of Nova Kakhovka city,\nKherson Province, noted, “Everyone in that detention facility knew that whenever the\nwhite-coloured bus of the Federal Security Service of the Russian Federation arrived,\nit meant that people would be tortured”. Victims also reported that interrogations and\ntorture had been committed by Russian armed forces, personnel of the National Guard\nof Russia, 10 soldiers of the so-called Donetsk People’s Republic and personnel of the\nWagner Group.\nDetention facilities"},{"id":"a-78-540-p0054","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"54","seq":56,"section":"1. Torture committed by Russian authorities","text":"The Commission documented additional detention facilities in which Russian\nauthorities routinely used torture (A/HRC/52/CRP.4, paras. 534–566). Some of these\nwere improvised, for example, in schools or in a kindergarten, while ot hers were held\nin established structures, such as police and penitentiary centres. Among the detention\nfacilities investigated were a school in Biliayivka village and the police department\nin Nova Kakhovka city, both in Kherson Province, and the police dep artment and\nPrymorsk correctional facility No. 145, both in Berdiansk city, in Zaporizhzhia\nProvince. The Commission found that inhuman conditions and the use of torture were\nprevalent in all."},{"id":"a-78-540-p0055","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"55","seq":57,"section":"1. Torture committed by Russian authorities","text":"Several victims mentioned the existence of “torture rooms” or “interrogation\nrooms”. One witness described how he was brought to a room where he saw tools\napparently used for torture; he mentioned pliers, knives, saws, cutters and a metal\ndevice with wires for electrocution."},{"id":"a-78-540-p0056","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"56","seq":58,"section":"1. Torture committed by Russian authorities","text":"In the majority of cases, detainees were held in inhuman conditions, confirming\na previous pattern identified by the Commission ( A/HRC/52/62, para. 64). Many of\nthe detention periods were prolonged, with some lasting more than 100 days. The\ncells were small and frequently overcrowded, with no windows and, therefore,\ninsufficient ventilation and no light. According to former detainees, in some cases\nvictims were not provided with food or water, or were given i nsufficient quantities,\nto the point that some of them drank water from the pipes of the radiator or their own\nurine and suffered from severe weight loss. Some had no access to toilets and used a\nbottle or a bucket or dug a ditch."},{"id":"a-78-540-p0057","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"57","seq":59,"section":"1. Torture committed by Russian authorities","text":"The Commission noted situations in which detainees were unlawfully transferred\nto one or more detention facilities after initial detention. It investigated cases in which\ntorture was used in at least one of those locations. This was the case, for example, of\ntwo victims detained briefly in a makeshift facility in a kindergarten, then transferred\nfor approximately one week to a detention centre in the school of Biliayivka village,\nwhere they were tortured, subsequently transferred for one day to a detention facility\nin a medical institution in another village, and finally detained for one -and-a-half\nmonths in the police department in Nova Kakhovka city, all in Kherson Province (see\npara. 54 above). Some victims were ill-treated or tortured in several of the facilities\nin which they were detained.\nTargeting of specific categories of persons"},{"id":"a-78-540-p0058","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"58","seq":60,"section":"1. Torture committed by Russian authorities","text":"Russian authorities used torture principally against persons whom they suspected\nof providing any form of support to the Ukrainian authorities. Others were tortured\nafter they were found to be holding pro-Ukrainian or anti-Russian views or if they\nrefused to cooperate with Russian authorities. One of the victims was a public official,\ntortured in order to coerce him into cooperating."},{"id":"a-78-540-p0059","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"59","seq":61,"section":"1. Torture committed by Russian authorities","text":"The majority of victims were men. In some of the cases documented in rural\nareas, victims stayed behind to take care of their older relatives and properties as their\nfamilies fled to safer areas."},{"id":"a-78-540-p0060","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"60","seq":62,"section":"1. Torture committed by Russian authorities","text":"According to victims and witnesses, many of the victims of torture were\nconfined initially after Russian authorities had found content deemed suspicious on\ntheir phones. In some cases, the identification of some types of tattoos led to torture.\nSome victims of torture had been confined during house searches. In some instances,\nperpetrators appeared to have been actively looking for specific individuals, for\nexample, after a tip-off by local residents cooperating with Russian authorities. In two\ncases, victims reported that perpetrators stormed their houses with the apparent aim\nof detaining them."},{"id":"a-78-540-p0061","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"61","seq":63,"section":"1. Torture committed by Russian authorities","text":"Some of the victims admitted that they supported Ukrainian armed forces.\nHowever, regardless of whether this was the case, international law prohibits torture\nin all circumstances. 11\nInterrogation sessions and torture methods"},{"id":"a-78-540-p0062","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"62","seq":64,"section":"1. Torture committed by Russian authorities","text":"In detention facilities, perpetrators, in general, used torture during interrogation.\nSome of the victims had to undergo repeated sessions of interrogation and torture.\nAccording to victims and witnesses, interrogation was aimed mainly at extracting\ninformation but was also used to force the victims to cooperate with the occupying\nauthorities, or as a punishment. Perpetrators, for example, requested victims to reveal\ndetails about their purported cooperation with Ukrainian armed forces or about the\nlatter’s positions and plans. Some victims outlined how torture continued, regardless\nof the answers provided. A victim stated, “It was so painful … I thought I would die\nthere. It was lasting for two hours. I kept saying ‘Boys, I don’t know why you are\ndoing that; I don’t know anything’”. A man, who was severely beaten together with\nanother detainee, said, “No matter what [we] responded, the man was beating [us].”"},{"id":"a-78-540-p0063","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"63","seq":65,"section":"1. Torture committed by Russian authorities","text":"Perpetrators often blindfolded the victims with a hood, bag or tape, handcuffed\ntheir hands behind their backs or tied them with rope and tied their legs."},{"id":"a-78-540-p0064","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"64","seq":66,"section":"1. Torture committed by Russian authorities","text":"With regard to torture methods, the Commission documented severe beatings in\nall detention facilities that it examined. According to witness accounts, these were\ncarried out using a variety of objects, such as batons, bats, rifle butts, a machine gun,\na wooden hammer and a plastic pipe. Perpetrators also hit the victims with their knees\nand feet. Two victims stated that they were lying face down on the floor during\nbeatings. One woman told the Commission that she lost her teeth after the soldiers\nhad banged her head against the wall. A former detainee recounted that, during a\nsession in which he was beaten heavily, together with his friend, the perpetrator asked\nthem to choose “which … of the knees they were ready to sacrifice”."},{"id":"a-78-540-p0065","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"65","seq":67,"section":"1. Torture committed by Russian authorities","text":"The Commission had found previously that the administering of electric shocks\nwith the use of a military field phone called “Tapik”, referred to, among other terms,\nas a “call to Putin”, was used by Russian authorities in several detention facilities\n(ibid., para. 75). The Commission’s further investigations confirmed that the use of\nelectric shocks was prevalent in the more established detention f acilities that it\ninvestigated. In some cases, the same victim was subjected repeatedly to electric\nshocks. Victims reported that perpetrators had connected wires or clamps to earlobes,\nankles, hands, toes or genitals. Some perpetrators referred to this me thod as a “call to\nStalin” or a “ride on a tram”. According to victims, in some cases water was poured\non them or otherwise used to amplify the effect of electric shocks. A woman who\nendured the electric shocks stated, “It was so painful that I could not s top screaming\nlike crazy, I was crying”. Her co-detainee described that, as a consequence, the victim\ncould barely walk and was “lying for a day as she could not move”. A man explained\nthat, during torture through electric shocks, his teeth bit the insides of his cheeks and\ntongue. His co-detainee confirmed that the victim could not eat owing to an injured\ntongue."},{"id":"a-78-540-p0066","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"66","seq":68,"section":"1. Torture committed by Russian authorities","text":"The Commission received reports regarding other methods of torture, which\nhave not been used consistently but were mentioned in relation to o ne or several\nfacilities. These included mock executions, placing a victim’s head in a barrel of\nwater, called “drowning”, the slashing on various parts of the body, depriving\ndetainees of their sleep, forcing a victim to inhale or the injecting of an unkn own\nsubstance. Two victims died after the latter two practices."},{"id":"a-78-540-p0067","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"67","seq":69,"section":"1. Torture committed by Russian authorities","text":"Victims also shared accounts concerning the use of derogatory terms, including\nof a sexual nature, psychological pressure and threats. In some cases, perpetrators\ncalled the victims “Nazis”. One perpetrator called the victim derogatory names,\nincluding “Nazi”, and said that “such people should be killed”. Some of the former\ndetainees were forced to learn by heart and sing the Russian anthem. Others had to\nmake declarations on video, including self-incriminating statements or negative\nutterances against President Zelenskyy. Victims reported threats to the life of their\nloved ones."},{"id":"a-78-540-p0068","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"68","seq":70,"section":"1. Torture committed by Russian authorities","text":"The Commission is investigating allegations of rape committed during\ndetention. Several former detainees, men and women, reported threats of rape and\nother sexual violence against themselves and their families and loved ones. For\nexample, a young woman stated that, during interrogation, a Russian authority warned\nthat, if she did not reveal names of informants of Ukrainian armed forces, he would\nbring 20 to 30 men to rape her. A man was told that his fiancée would be gang -raped\nif he did not provide the required information. One former male detainee received\nthreats to be thrown among regular prisoners, who would rape him. Another former\ndetainee mentioned threats of having his genitals cut off."},{"id":"a-78-540-p0069","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"69","seq":71,"section":"1. Torture committed by Russian authorities","text":"Victims and witnesses shared accounts regarding the profound impact that\ntorture had on them, their families and their environment. One illustration from recent\ninvestigations includes a case in which torture had the immediate effect of worsening\na chronic medical condition from which a woman was suffering and of which the\nperpetrators were aware. Co-detainees requested a doctor for the victim, but, given\nthe circumstances, the doctor was unable to help her. In addition to the physical\ntrauma, torture has led to long-term psychological suffering and distress. One victim\nreported that he had attempted suicide twice while in detention, including during a\n“drowning” session. Another victim committed suicide several months after his\ndetention and torture. His family, devastated by the loss, stated that he could not cope\nwith the psychological impact of what he had gone through."},{"id":"a-78-540-p0070","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"70","seq":72,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In its previous report, the Commission recommended further investigations into\nallegations concerning the treatment of alleged collaborators 12 by Ukrainian authorities\n(A/HRC/52/62, paras. 87–89). Since then, it has documented three such cases: two in\nMarch 2022 and a third in March 2023. The victims were men. On the basis of the\navailable information for each incident, the Commission found that, in all three cases,\nthe victims had been arrested arbitrarily, that, in two of the cases, the detention was\nalso arbitrary and that, in one of the cases, the detention was incommunicado. The\nCommission concluded that, in at least one case, torture had been used against the\nvictim. It continues to investigate additional allegations regarding these incidents, as\nwell as other cases."},{"id":"a-78-540-p0071","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"71","seq":73,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In one of the cases, on 2 March 2022 in Kyiv Province, a man reported that\napproximately 10 armed men in camouflage uniform and masks arrested him in the\nstaircase of his apartment building, handcuffed him and searched his flat. According\nto the victim, on the same day the perpetrators brought him to the main building of\nthe Security Service of Ukraine in Kyiv city and further detained and interrogated\nhim there. The protocol of arrest was made on 4 March 2022. There is no material to\nsuggest that the victim was advised of the basis of the arrest and charges brought\nagainst him before that date. The Commission therefore concluded that the arrest and\nthe detention, at least from 2 to 4 March 2022, were arbitrary."},{"id":"a-78-540-p0072","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"72","seq":74,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In another case, on 4 March 2022, also in Kyiv Province, a man was arrested by\nat least eight men dressed in camouflage uniforms. They brought him to the premises\nof the Security Service of Ukraine in Kyiv city and detained him there, without\nallowing him to communicate with the outside world. On 14 March 2022, the arrest\nand the detention were recognized officially. The Comm ission found that, from 4 to\n14 March 2022, the arrest and the detention of the victim were arbitrary and that the\ndetention was incommunicado."},{"id":"a-78-540-p0073","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"73","seq":75,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"On 23 March 2023, in Odesa Province, four men in camouflage uniforms and\nmasks arrested a man on the street, handcuffed him and put him in their vehicle. They\nkicked him and beat him with a rifle butt while asking him to confess that he was a\nspy. He suffered at least two broken ribs as a consequence of the beating.\nSubsequently, they drove the victim to his house, where they handed him over to two\nmen who introduced themselves as members of the Security Service of Ukraine and\nconducted a search. They later brought him to the premises of the Security Service of\nUkraine in Odesa city. The victim reported that he was requested to sign documents\nand threatened with further beatings in case of refusal. The Commission found, in that\ncase, that the perpetrators had committed torture and arrested the victim arbitrarily,\nin violation of international human rights law.\nC.   Sexual and gender-based violence"},{"id":"a-78-540-p0074","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"74","seq":76,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission had previously documented cases of sexual and gender-based\nviolence committed by Russian authorities in nine provinces of Ukraine and in the\nRussian Federation (ibid., paras. 78–85). It focused its recent investigations on\nKherson and Zaporizhzhia Provinces and found evidence that Russian authorities had\ncommitted rape and sexual violence in a district of Kherson Province. Rape and\nsexual and gender-based violence constitute crimes and violations of human rights\nand were often committed with additional crimes and other grave human rights\nviolations."},{"id":"a-78-540-p0075","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"75","seq":77,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The cases of rape documented occurred between March and July 2022, in small\nvillages in Kherson Province mostly during Russian authorities’ incursions in the\nhomes of the victims. Some took place in the same village. Other reported situations\nof sexual violence or threats thereof occurred in detention facilities maintained by\nRussian authorities (see para. 68 above)."},{"id":"a-78-540-p0076","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"76","seq":78,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In the cases investigated, the victims of rape were a 16-year-old girl and women\naged from 19 to 83. Most of them were in a vulnerable situation. One of the victims\nwas a 16-year-old pregnant girl, three were older women and some were living alone\nor with young children, or with a family member living with a disability. The victims\nwere among the women who had remained in their villages when Russian armed\nforces took control of the area, while many had fled, to care for relatives who were\nolder or lived with a disability or to look after their belongings or because they could\nnot flee."},{"id":"a-78-540-p0077","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"77","seq":79,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The documented cases of rape were perpetrated with the use of force or\npsychological coercion. Most of the incidents occurred after the perpetrators had\nbroken into the victims’ homes. Victims reported rapes at gunpoint and threats of\nkilling or of inflicting other serious harm to the victims or their relatives. In some\ninstances, perpetrators had visited the victims’ houses before the crime, including on\nseveral occasions, and displayed abusive behaviour."},{"id":"a-78-540-p0078","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"78","seq":80,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In some cases, the same perpetrator raped the victim two or more times. In two\ncases, perpetrators gang-raped the victims. One of the victims and her husband were\nshot dead by Russian soldiers after they had reported the rape."},{"id":"a-78-540-p0079","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"79","seq":81,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Perpetrators committed additional acts of violence against the victims of rape,\nincluding severe beatings, strangling, suffocating, slashing and shooting next to the\nvictim’s head. Most of these acts are in themselves crimes and violations of human\nrights, in addition to sexual and gender-based violence. In several cases, the\nCommission concluded that those acts amounted to torture."},{"id":"a-78-540-p0080","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"80","seq":82,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In a number of cases, family members were present when the rape took place.\nThere are instances in which perpetrators also committed crimes and violations\nagainst them, including killing, attempted killing and torture."},{"id":"a-78-540-p0081","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"81","seq":83,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Victims stated that the crimes and violations had been committed by Russian\nsoldiers and, in some cases, specified that perpetrators belonged to units from the\nso-called Donetsk and Luhansk People’s Republics. Some perpetrators were\nintoxicated. In two separate cases, victims named the same perpetrator. In several\ncases, the behaviour displayed by the perpetrators suggested that they did not fear\naccountability. This is illustrated, for example, by repeated visits to the houses of the\nvictims and by the multiple threats and violations committed against them and their\nfamily members. One victim stated that, when Russian soldiers deployed to their\nvillage, they first enquired about women living alone. One victim of rape reported\nthat, after one soldier raped her, he was drinking on her terrace together with fellow\nsoldiers and greeted her the next day. One witness of rape reported that, while a\nsoldier was raping her pregnant daughter, he said: “It’s not scary, everyone does it”.\nHowever, the interviews of the Commission also showed that other soldiers behaved\ndifferently and that, in a small number of cases, superiors took action against those\ncommitting rape or fellow soldiers attempted to stop the perpetrators or to assist the\nvictim.\nCase descriptions"},{"id":"a-78-540-p0082","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"82","seq":84,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission describes in detail below a few of the cases of rape and sexual\nviolence committed by Russian armed forces during house visits in Kherson Province ."},{"id":"a-78-540-p0083","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"83","seq":85,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In March 2022, a Russian soldier came to the house of an 83 -year-old woman\nand forced her to open the door. He questioned her on whether she knew persons who\ncooperated with the Ukrainian armed forces and beat her with his rifle. The soldier\nordered her to undress, raped her and continued to rape and beat her for several hours.\nHe threatened to rape the woman’s husband, who lived with a disability and was\npresent in the house. The soldier stole some belongings. The Commission found that,\nin addition to rape, the war crime of torture had been committed against the victim."},{"id":"a-78-540-p0084","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"84","seq":86,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In March and April 2022, several groups of Russian soldiers visited the house\nand the shop of a married couple on multiple occasions. The victim reported that the\nsoldiers looted, forced her to cook for them, took showers and slept in her house.\nDuring one visit in April 2022, Russian soldiers locked the husband in a room. One\nsoldier threatened to kill the 59-year-old woman and sexually harassed her, while he\nreloaded his rifle repeatedly. Later in April 2022, three Russian soldiers broke into\nthe house at night and shot at the husband but missed. Two of the soldiers beat the\nwoman with their pistols and kicked her, threatened to shoot her, ripped off her clothes\nand gang-raped her. She attempted to escape, but they caught her, dragged her into\nthe house and raped her again. The Commission found that, in addition to rape, torture\nhad been used against her and attempted wilful killing had been committed against\nher husband."},{"id":"a-78-540-p0085","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"85","seq":87,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In May 2022, three Russian soldiers came to the house of a married couple who\nhad stayed behind to look after the grandmother. They beat the 52 -year-old man and\nall three perpetrators raped the 50-year-old woman in turns. The couple reported the\nrape to the Russian armed forces commander. Neighbours recounted that, after this,\nthree different soldiers “were looking for a woman who reported the rape”, went to\nthe couple’s house and shot dead both of them. The Commission found that, in\naddition to the rape of the woman, the war crimes of wilful killing and torture had\nalso been committed against both victims."},{"id":"a-78-540-p0086","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"86","seq":88,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In July 2022, a Russian soldier came to the house of a 75-year-old woman, where\nshe stayed alone to protect her property. The soldier attacked her, hit her on her face,\nchest and ribs and strangled her as he was interrogating her. He ordered her to undress\nand when she refused, he ripped off her clothes, cut her abdomen with a small sharp\nobject and raped her several times. The next morning, he raped her and beat her again.\nThe victim had several broken ribs and teeth knocked out as a result. The Commission\nfound that, in addition to rape, the war crime of torture had also been committed\nagainst the victim."},{"id":"a-78-540-p0087","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"87","seq":89,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"These and other cases took place in a context of multiple forms of violence\nexperienced by the victims and their families. Fear, trauma, physical and psychological\nharm, and damage to livelihoods are experienced in parallel, as evidenced in victims’\naccounts. These factors contributed to accentuating th e vulnerability of the victims.\nFor example, a woman who lived alone with her children reported that, after Russian\nauthorities had taken control of the village, she felt compelled to move in with a man\nin order to seek safety. Taking advantage of the situ ation, he mistreated the children,\ntook the social aid that she was receiving and aided her rape by Russian soldiers."},{"id":"a-78-540-p0088","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"88","seq":90,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The crimes documented have severe and long-term consequences for the\nphysical and mental health of the victims and are highly traumati zing for their family\nmembers. The victims were residents of small villages. In proximity to the front line,\nmedical help was not easily available. Some victims reported that they suffered from\nshame and stigma and appeared to blame themselves."},{"id":"a-78-540-p0089","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"89","seq":91,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"One victim, describing how she felt after the crime, stated, “I am scared all the\ntime. I forgot what normal sleeping means. My husband felt worse since that day. I\nam afraid of everyone, when police officers came and I was reporting the incident to\nthem, I was shaking. I realized I am afraid of men in uniforms. I don’t know how to\nlook people in the eyes”. Another victim, after telling how she had attempted to flee,\nas two perpetrators were raping her, shared that she was “hoping for a rifle shot, so\nthat she would not suffer anymore”. She also stated, “I just don’t know why I deserved\nit, what did I do to survive that?”\nD.   Transfers and deportations of children"},{"id":"a-78-540-p0090","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"90","seq":92,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"In its report to the Human Rights Council, the Commission identified three main\nsituations in which Russian authorities had transferred Ukrainian unaccompanied\nchildren from one area that they controlled in Ukraine to another or to the Russian\nFederation. Transfers affected children who had lost parents or contact with them\nduring hostilities, who were separated following the detention of a parent, and who\nwere in institutions (ibid., para. 97). It found that, in some of the cases that it\ninvestigated, such transfers had occurred in violation of international humanitarian\nlaw and qualified as unlawful transfers or deportations, which is a war crime."},{"id":"a-78-540-p0091","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"91","seq":93,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission investigated further reports regarding transfers of\nunaccompanied children by Russian authorities to the Russian Federation or to areas\nthat they occupied in Ukraine. Notably, it documented the transfer of 31 children from\nUkraine to the Russian Federation in May 2022 and concluded that it was an unlawful\ndeportation and a war crime (see paras. 98–99 below)."},{"id":"a-78-540-p0092","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"92","seq":94,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"It is stated in international humanitarian law that no party to the conflict shall\narrange for the evacuation of children, other than its own nationals, to a foreign\ncountry except for a temporary evacuation where compelling reasons of the health or\nmedical treatment of the children or, except in occupied territory, their safety s o\nrequire. The written consent of parents or legal guardians is required, and, if they\ncannot be found, of the persons primarily responsible for the care of the children. 13"},{"id":"a-78-540-p0093","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"93","seq":95,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Gaining an understanding of the larger extent of transfers of unaccompanied\nchildren that may be in violation of the requirements set forth under international\nhumanitarian law has proved to be challenging with the information and data\npresently available. One factor that appears as a source of confusion is the fact that a\nvariety of distinct situations concerning children have been considered together. The\nRussian Federation and Ukraine have publicized different figures concerning the\nscale of transfers of children from Ukraine since the outset of the armed conflict in\n2022. In Ukraine, interlocutors from government agencies appeared to have diverse\napproaches concerning this issue. The official website maintained by the Government\nof Ukraine as “the only platform that provides up -to-date, consolidated information”\non children who suffer as a result of the armed conflict recorded 19,546 “deported\nand/or forcibly displaced persons” as at the end of September 2023. 14 Two Ukrainian\ngovernment officials clarified that this included figures of children who had crossed\nthe border to the Russian Federation together with parents. One official stated that\nchildren sent voluntarily by their parents to summer camps were included in this\nfigure. Two non-governmental organizations monitoring the issue also noted that the\nfigure comprised various categories of children, including those who had not been\nseparated from their parents. Those interlocutors also highlighted risks of duplication\nof some cases."},{"id":"a-78-540-p0094","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"94","seq":96,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Furthermore, the Commission has been unable to find reliable data from the\nRussian Federation about transfers of children. It took note of public information. For\nexample, in 2023, a bulletin issued by the office of the Russian Commissioner for\nChildren’s Rights, Maria Lvova-Belova, reported that, from April to October 2022,\n380 orphan children from the so-called Donetsk and Luhansk People’s Republics had\nbeen transferred and placed in foster families in the Russian Federation. 15 The same\ndocument noted that some 2,000 orphans and children left without parental care living\nin boarding institutions in the so-called Donetsk and Luhansk People’s Republics had\nbeen transferred to the Russian Federation in February 2022. It was further stated that,\namong those children, those from the so-called Donetsk People’s Republic were\nplaced in foster care or in institutions. 16"},{"id":"a-78-540-p0095","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"95","seq":97,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission is concerned at reports regarding measures that have the\napparent aim of allowing some children to remain for prolonged periods in the\nRussian Federation. It has reviewed information regarding the placement of children\nin foster families in the Russian Federation, including the above -mentioned bulletin,\ninterviews with family members or legal representatives of children in such\nsituations, and media coverage."},{"id":"a-78-540-p0096","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"96","seq":98,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Ukrainian government officials undertook initiatives to facilitate the return and\nreunification of some children separated from their parents or relatives, and Russian\nofficials reportedly cooperated in some cases. However, as of the end September\n2023, there was no mechanism for the return of transferred children in place between\nboth States. On 23 September 2023, the Minister for Foreign Affairs of the Russian\nFederation, Sergey Lavrov, stated, “If those families are found, we will assist with\nthe reunification of those children”. 17 In addition, it was noted in the above-mentioned\nbulletin that, if a child “has a parent with full parental rights, the family has every\nopportunity to be reunited”. 18 However, apart from a few examples, the Commission\nhas not been informed of Russian initiatives to proactively facilitate all returns. It has,\nto date, received information regarding returns that took place on an individual basis,\nat the initiative of parents, legal guardians or of children themselves, with the support\nof Ukrainian authorities, private organizations and other initiatives. This often entails\nrisky, very complicated and costly travel through several countries."},{"id":"a-78-540-p0097","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"97","seq":99,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"As outlined above, transfers of children to Russian-occupied areas and across\nthe border to the Russian Federation have occurred in a variety of situations. A well -\nfunctioning return process should be oriented around the best interests of the child\nand should consider the circumstances of each situation. However, in the absence of\na rigorous recording and verification system, clarity cannot be shed on the true extent\nof transfers of children in each situation. The lack of clarity and transparency\nregarding the circumstances and categories of children transferred is an impediment\nto a well-functioning return process. Moreover, to aid the reunification of children\ntransferred at a young age, it would be prudent to establish a DNA bank with samples\nfrom parents or relatives.\nIndividual situations of deportations of children"},{"id":"a-78-540-p0098","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"98","seq":100,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission has continued to document individual cases concerning the\ntransfers of children to the Russian Federation. One of these concerns the transfer, on\n27 May 2022, by Russian authorities of 31 children from the children’s social centre\nof the administration of Donetsk city, Donetsk Province, to the Russian Federation.\nThe children included 16 boys and 15 girls from 7 to 17 years of age. They had been\nin a variety of situations prior to their accommodation in the centre. Some of them\nwere orphans or deprived of parental care and were in State institutions, while others\nhad lost contact with their parents or foster parents owing to the ongoing hostilities.\nIn an official document obtained by the Commission, it was stated that the transfer\nhad been authorized for “recreational” purposes and was to be carried out temporarily,\nuntil 27 June 2022. Consent had been given by the acting director of the centre\nappointed by the occupying authorities. In the Russia n Federation, the children were\naccommodated in the Polyany boarding house in the Moscow region."},{"id":"a-78-540-p0099","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"99","seq":101,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"From information collected by the Commission, apart from three children who\nhad been brought back by their father, it appears that most of those children r emained\nin the Russian Federation beyond the one-month period. According to a witness\ntestimony and media coverage, after having spent several months in the Russian\nFederation, including in a foster family, one additional boy managed to return on his\nown to Ukraine, through Belarus. One boy from that group of children was placed in\nMs. Lvova-Belova’s family. On 21 September 2022, Ms. Lvova-Belova stated\npublicly that the boy had been given a Russian passport and that he was now “ours”,\nshowing an apparent intention to keep him in the Russian Federation on a long-term\nbasis. In a bulletin issued by her office in 2023, Ms. Lvova -Belova further stated that\n6 children of that group had been placed in family centres, and almost all of them,\nsubsequently, in foster families, and that 22 had been placed in provisional\nguardianship by residents of the Moscow region. 19 These combined elements are in\ncontravention of the legal requirement that evacuations of children should be\ntemporary, and the transfer of the children therefore amounts to an unlawful\ndeportation, which is a war crime.\nConditions in which children were held in camps"},{"id":"a-78-540-p0100","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"100","seq":102,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission examined reports that, in some situations in which children\nfrom Ukraine had been sent to camps in Crimea with prior authorization of their\nparents, conditions in which they were held were inadequate. One example concerns\na family from Kherson city, which agreed to send three siblings to a camp in Crimea\nin October 2022, for three weeks. However, owing to frontline developments and\nevacuations carried out by Russian authorities from Kherson city, the children were\ninstead relocated to a different camp in Crimea, where they remained for six months.\nOne of the children, a 15-year-old girl, told the Commission that, during their stay\nthere, camp personnel had decided to send her 10 -year-old brother to a psychiatric\nhospital in Crimea as a punishment following a quarrel with another child and after\nhe “was crying because he missed his mother”, separating him from his two other\nsiblings who were in the camp."},{"id":"a-78-540-p0101","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"101","seq":103,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Three teenage children who had stayed in such camps in Crimea reported\nseparately to the Commission that staff of the camp placed children in a room called\nan “isolator” if they considered that the children misbehaved. For example, a 16-year-\nold boy stated that camp staff placed him, together with two other children, in the\n“isolator” for four days after they had overheard the children listening to the\nUkrainian anthem. A 17-year-old boy mentioned that he was “locked up” for five days\nafter he had removed a Russian flag."},{"id":"a-78-540-p0102","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"102","seq":104,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Children who had stayed in camps in Crimea also reported distress after camp\npersonnel had told them that they would be placed in a children’s home or in foster\nfamilies. One 16-year-old girl reported that a teacher had hit her and said, “I can put\nyou in a foster family and your mother wouldn ’t find you; you would be homeless\nand beg for food”. Children reported being required to sing the Russian anthem and\nto write letters to Russian soldiers. One girl noted that children from Kherson\nProvince were bullied and told to go back to their “fascist country”. The mother of a\n16-year-old boy, whose time in a similar camp in Crimea was also prolonged owing\nto frontline developments, stated that he was transferred to a village under Russian\ncontrol in Kherson Province and told by the teachers there that “soon they would be\ngiven arms and would be standing at checkpoints”.\nV. Conclusions and recommendations"},{"id":"a-78-540-p0103","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"103","seq":105,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"During its second mandate, the Commission found evidence showing that\nRussian authorities had continued to commit numerous violations of\ninternational human rights law and international humanitarian law in the\ncontext of their armed aggression in Ukraine. It concluded, among others, tha t\nRussian authorities had committed indiscriminate attacks against civilians and\nthe war crimes of torture, wilful killing, rape and other sexual violence, and\ndeportation of children, which are also violations of human rights. It has received\nnumerous other allegations, and its investigations are continuing."},{"id":"a-78-540-p0104","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"104","seq":106,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission also documented three cases in which Ukrainian\nauthorities had committed human rights violations against persons whom they\naccused of collaborating with Russian authorities."},{"id":"a-78-540-p0105","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"105","seq":107,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"This armed conflict, as with all others, continues to leave in its wake\nconsiderable physical and mental trauma. The population faces hardship\nfollowing the loss of lives, injuries and the destruction and devastation caused by\nthe conflict. The Commission further documented the impact on the civilian\npopulation of violations and events relating to the conflict. This is notably the\ncase of the large-scale attacks against Ukraine’s infrastructure carried out by\nRussian armed forces and of individual attacks affecting civilian objects."},{"id":"a-78-540-p0106","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"106","seq":108,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"Lastly, the Commission strongly condemns violations and corresponding\ncrimes. Similar to its previous reports, it reiterates the paramount importance of\nensuring that perpetrators are held accountable. In addition to judicial\nmeasures, it also emphasizes the importance of other dimensions of\naccountability, including truth, reparations and guarantees of non-recurrence."},{"id":"a-78-540-p0107","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"107","seq":109,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission considers that the recommendations that it made in its\nreport to the Human Rights Council remain relevant to a very large extent\n(A/HRC/52/62, paras. 112–115). Accordingly, it reiterates them and makes\nadditional recommendations, following its latest investigations, to strengthen\naccountability and for the prevention of further violations."},{"id":"a-78-540-p0108","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"108","seq":110,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission recommends that the parties to the conflict:\n(a) Ensure the timely, effective, thorough, independent, impartial and\ntransparent investigation and prosecution of all allegations of international\ncrimes, violations of international human rights law and international\nhumanitarian law, including sexual and gender-based violence and violence\nagainst children;\n(b) Ratify international instruments to which they are not yet party and\nthat will strengthen the protection of civilians in armed conflict."},{"id":"a-78-540-p0109","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"109","seq":111,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission recommends that the Russian Federation immediately:\n(a) Cease aggression and all acts of violence committed against civilians\nin violation of applicable international human rights and international\nhumanitarian law and end the use of torture, sexual and gender-based violence,\nand other forms of ill-treatment;\n(b) Take all feasible precautions to protect civilians and civilian\ninfrastructure, including energy-related infrastructure that was damaged\nseverely after the massive attacks that targeted them from October 2022 to\nMarch 2023;\n(c) Comply strictly with international humanitarian law and respect the\ntemporary nature of any transfer or evacuation of children by ensuring their\nexpeditious return;\n(d) Release or return to Ukraine all Ukrainian civilians who have been\ndeported to the Russian Federation and are detained there as a consequence of\nthe armed conflict."},{"id":"a-78-540-p0110","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"110","seq":112,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission further recommends that the Russian Federation:\n(a) Ensure that all perpetrators, in particular commanders and other\nsuperiors, and those ordering, soliciting or inducing the commission of\ninternational crimes, are held accountable in accordance with international\nhuman rights standards;\n(b) Take the measures necessary to prevent the commission of such\nviolations and crimes, in particular through unequivocal instructions to all\nbranches of the armed forces and other entities participating in the armed\nconflict, with a view to ensuring that military discipline and respect for\ninternational human rights and humanitarian law are upheld along with the\nprinciple of command responsibility;\n(c) Respect international humanitarian law applicable to occupied\nterritories and refrain from placing any impediment to humanitarian assistance\nin those territories;\n(d)   Cooperate fully with all international monitoring and investigative\nbodies."},{"id":"a-78-540-p0111","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"111","seq":113,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission recommends that Ukraine:\n(a) As a preliminary step towards a comprehensive reparations\nprogramme, establish a victims’ registry as an “institutional portal” for better\ncoordination of government services to victims;\n(b) Comprehensively address mental health and psychosocial needs\nresulting from the armed conflict by addressing access and allocation of\nresources to the relevant services and enhancing their institutional coordination,\nlegal regulation, monitoring and evaluation;\n(c) Consider establishing a DNA registry that would aid in the\nidentification and recovery of missing children;\n(d) Harmonize its legislation relating to war crimes where it is not in\nconformity with international standards and amend its criminal code to clarify\nthe definition of “collaborative activity” to avoid legal uncertainty and harm to\nsocial cohesion;\n(e) Taking into account both the enormous caseload and limited\nresources, finalize an investigatory and prosecutorial strategy, which will\nprioritize cases on the basis of clear criteria and ensure due process and\ntransparent monitoring."},{"id":"a-78-540-p0112","rec_id":"rectWzP7iekU235fu","symbol":"A/78/540","n":"112","seq":114,"section":"2. Arbitrary arrest, detention and ill-treatment of alleged collaborators by","text":"The Commission recommends that other States and regional and\ninternational organizations:\n(a) Strengthen national, regional and international accountability\nmechanisms, both judicial and non-judicial, including by improving their\ncoordination and supporting the effective participation of civil society and\ngroups representing victims and survivors;\n(b) Ensure that recognizably necessary national reconstruction\nprogrammes or property restitution programmes are not designed to the\ndetriment of victims’ reparations;\n(c) Further integrate the human rights dimensions of the armed conflict\nin Ukraine more fully into the Security Council’s agenda."},{"id":"a-hrc-55-66-u0000","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":null,"seq":0,"section":null,"text":"United Nations                                                                                    A/HRC/55/66\nGeneral Assembly                                                           Distr.: General\n18 March 2024","unnumbered":true},{"id":"a-hrc-55-66-u0001","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":null,"seq":1,"section":null,"text":"Summary\nThe Independent International Commission of Inquiry on Ukraine hereby submits its\nreport, pursuant to Human Rights Council resolution 52/32, in which the Council decided to\nextend the Commission’s mandate for a further period of one year.\nTwo years after the full-scale invasion of Ukraine by the Russian Federation, civilian\nsuffering from the hardships of the armed conflict continues to mount, notably resulting from\nthe disregard of basic principles of humanitarian law and human rights obligations. The\nCommission has found new evidence that Russian authorities have committed violations of\ninternational human rights and international humanitarian law and corresponding war crimes\nin areas that came under their control in Ukraine.\nThe Commission is concerned by the continued use of explosive weapons in civilian\nareas. It has assessed the grave impact on civilians of the fighting and the siege in the city of\nMariupol at the outset of the full-scale invasion.\nMore recent indiscriminate attacks violating international humanitarian law\ncommitted by Russian armed forces have led to civilian casualties and the destruction and\ndamage of civilian objects, including of protected objects, such as hospitals and cultural\nproperty. Often, Russian armed forces failed to take feasible precautions to verify that the\naffected objects were not civilian. The Commission confirms its previous conclusion that the\nmultiplicity of such attacks shows a pattern of disregard by Russian armed forces for possible\nharm to civilians.\nNew evidence strengthens the Commission’s previous findings that torture used by\nRussian authorities in Ukraine and in the Russian Federation has been widespread and\nsystematic. It describes cases of horrific treatment of Ukrainian prisoners of war in several\ndetention facilities in the Russian Federation.\nThe report documents incidents of rape and other sexual violence committed against\nwomen and a girl in circumstances which also amount to torture. It also details incidents of\ntorture with a sexualized dimension and threats of rape against male prisoners of war.","unnumbered":true},{"id":"a-hrc-55-66-u0002","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":null,"seq":2,"section":null,"text":"* The present report was submitted to the conference services for processing after the deadline so as to\ninclude the most recent information.\n** The annex to the present report is circulated as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-55-66-u0003","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":null,"seq":3,"section":null,"text":"In its investigations, the Commission found additional evidence concerning the\nunlawful transfer of children to areas under Russian control.\nThe report also documents a few violations of human rights by Ukrainian authorities\nagainst persons suspected of collaboration with Russian authorities.\nThe Commission is concerned at the scale, continuation and gravity of violations and\ncrimes it has investigated and the impact on victims and the affected communities. It\nreiterates the importance of accountability in all its dimensions.","unnumbered":true},{"id":"a-hrc-55-66-p0001","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"1","seq":4,"section":"I. Introduction","text":"The Independent International Commission of Inquiry on Ukraine submits the present\ncomprehensive report to the Human Rights Council at its fifty-fifth session pursuant to\nCouncil resolution 52/32, in which the Council renewed the Commission’s initial mandate\nfor one year."},{"id":"a-hrc-55-66-p0002","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"2","seq":5,"section":"I. Introduction","text":"Since March 2022, Erik Møse (Norway) and Pablo de Greiff (Colombia) have been\nserving as members of the Commission, with Mr. Møse serving as Chair. In June 2023, the\nPresident of the Human Rights Council appointed Vrinda Grover (India) as a member of the\nCommission."},{"id":"a-hrc-55-66-p0003","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"3","seq":6,"section":"I. Introduction","text":"The present report reflects the Commission’s findings during its second mandate. It\nsupplements its 2023 report to the Human Rights Council, which was elaborated on in its\nconference room paper of August 2023, and its 2023 report to the General Assembly.1"},{"id":"a-hrc-55-66-p0004","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"4","seq":7,"section":"I. Introduction","text":"During its current mandate, the Commission travelled to Ukraine 16 times, visited 34\nsettlements in nine provinces and travelled to Poland and the Kingdom of the Netherlands. It\nhas relied on interviews with 422 women and 394 men, inspected sites of attacks and places\nwhere incidents took place, and examined documents, expert and forensic reports,\nphotographs and videos. Over its two mandates periods, the Commission has travelled to\nUkraine 26 times, visited a total of 90 settlements and interviewed 770 women and 641 men."},{"id":"a-hrc-55-66-p0005","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"5","seq":8,"section":"I. Introduction","text":"The Commission abides by the principles of independence, impartiality, objectivity\nand integrity. It adopts a victim-centred approach, placing victims’ safety and security at the\nforefront of its work. The Commission applies the standard of proof of “reasonable grounds\nto conclude” and reaches determinations when, on the basis of a body of verified information,\nan objective and ordinary prudent observer would conclude that the facts took place as\ndescribed. Its legal analysis is based on relevant provisions of international human rights law,\ninternational humanitarian law and international criminal law. 2"},{"id":"a-hrc-55-66-p0006","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"6","seq":9,"section":"I. Introduction","text":"Consistent with its mandate, the Commission strived to consider all allegations of\nviolations and corresponding crimes and presents examples that illustrate key patterns.\nWhere possible, it has attempted to identify those responsible and continues to compile a list\nof such individuals."},{"id":"a-hrc-55-66-p0007","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"7","seq":10,"section":"I. Introduction","text":"The Commission appreciates the cooperation extended by the Government of\nUkraine. It regrets that its efforts to engage with the Russian Federation remained\nunsuccessful. The Commission has addressed to Russian officials 23 written requests for\nmeetings, access and information, without receiving any answer. It consistently expressed an\ninterest in establishing meaningful communication with Russian officials. This lack of\ncooperation, in addition to dire security conditions, have impeded access to certain areas of\nUkraine."},{"id":"a-hrc-55-66-p0008","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"8","seq":11,"section":"I. Introduction","text":"The Commission reiterates its deep gratitude to victims and witnesses for sharing their\noften traumatic experiences, as well as to all other interlocutors and organizations for the\ninformation provided."},{"id":"a-hrc-55-66-p0009","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"9","seq":12,"section":"II. Violations of international law","text":"Years of armed conflict have gravely affected the population of Ukraine. As at\n15 February 2024, the Office of the United Nations High Commissioner for Human Rights\n(OHCHR) had recorded 30,457 civilian casualties (10,582 killed and 19,875 injured). The\nactual number is likely higher. Civilians have been forced to cope with the loss of loved ones,\nhomes and other irreplaceable possessions, massive displacement, constant fear and critical\nshortages, all of which have had a deep impact on their enjoyment of basic human rights.\n1 A/HRC/52/62; conference room paper of the Independent International Commission of Inquiry on\nUkraine, available at https://www.ohchr.org/sites/default/files/2023-\n08/A_HRC_52_CRP.4_En%20%28003%29.pdf; and A/78/540.\n2 A/78/540, paras. 7 and 8."},{"id":"a-hrc-55-66-p0010","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"10","seq":13,"section":"II. Violations of international law","text":"During its second mandate, the Commission gathered evidence of continued\nviolations of international human rights law and international humanitarian law and\ncorresponding crimes committed by the Russian authorities3 in Ukraine. The present report\nprovides an account of the severe impact on civilians of the siege and intense fighting during\nthe early stages of the armed conflict in Mariupol, Donetsk Province. The Commission also\nfound evidence of new attacks with explosive weapons committed in violation of\ninternational humanitarian law. For the first time, it is reporting on attacks affecting cultural\nobjects and historical sites and on the seizure of cultural objects. It has documented additional\ncases of wilful killings, torture (with emphasis on prisoners of war), rape and other sexual\nviolence, and transfers of children."},{"id":"a-hrc-55-66-p0011","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"11","seq":14,"section":"II. Violations of international law","text":"The present report contains information on two cases of human rights violations\nagainst alleged collaborators committed by the Ukrainian authorities.4"},{"id":"a-hrc-55-66-p0012","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"12","seq":15,"section":"A. Violations committed during the conduct of hostilities","text":"The Commission has continued to investigate attacks with explosive weapons in\npopulated areas that led to civilian deaths and injuries and the damage or destruction of\ncivilian objects. It documented attacks committed in territories under Ukrainian Government\ncontrol and in areas that were under the control of Russian authorities. The Commission had\nno access to Mariupol, but managed to interview survivors, who, despite continuing trauma\nand fear for family members remaining in the area, provided information for its investigation."},{"id":"a-hrc-55-66-p0013","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"13","seq":16,"section":"1. The siege of Mariupol","text":"Starting on 24 February 2022, Russian armed forces attacked Mariupol from various\ndirections, and encircled it by 1 March 2022. Heavy street fighting ensued, causing immense\nsuffering to the residents. Ukrainian armed forces fought from within the city and ultimately\ntook shelter at the Azovstal steel plant. The siege of Mariupol continued until 20 May 2022,\nwhen Russian authorities declared the “complete liberation” of the city. 5\nSignificant loss of life and destruction of civilian buildings"},{"id":"a-hrc-55-66-p0014","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"14","seq":17,"section":"1. The siege of Mariupol","text":"The Commission interviewed 50 women and 33 men, who shared their horrific\nexperiences during the siege. Residents described periods of relentless shelling and aerial\nbombardments. While satellite imagery indicates that 15,555 structures were affected\n(831 destroyed, 5,877 severely damaged and 8,847 moderately damaged), the actual damage\nwas likely more significant (see annex). Residents saw buildings and houses collapsing under\nthe shelling, in some instances killing and injuring loved ones, and whole areas of the city in\nruins. Two residents, for instance, witnessed tanks firing rounds at civilian residences. A\nwoman recollected that an airstrike hit a nine-storey building near hers, and people living\nthere jumped out of windows."},{"id":"a-hrc-55-66-p0015","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"15","seq":18,"section":"1. The siege of Mariupol","text":"Ukrainian authorities estimated that thousands of civilians died in Mariupol during\nthat period. After constant fighting, residents emerging from shelters saw dead bodies strewn\non the streets and in the rubble of houses. They recognized relatives, neighbours and\nacquaintances. A woman who evacuated an injured man described her way to the hospital:\n“It was hell. Explosions. Destroyed buildings. Houses on fire. Wounded people crying.” In\nthe hospital, she saw three rooms full of dead bodies, and more in the corridor. Others also\nrecollected seeing large numbers of dead bodies in the city’s hospitals.\nImpact on medical facilities"},{"id":"a-hrc-55-66-p0016","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"16","seq":19,"section":"1. The siege of Mariupol","text":"The fighting in Mariupol damaged or destroyed at least 58 medical buildings,\naccording to data sets obtained. This affected those who sought urgent treatment or attempted\nto shelter in hospitals. The Commission interviewed residents who witnessed and suffered\nfrom the damage or the destruction of medical facilities."},{"id":"a-hrc-55-66-p0017","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"17","seq":20,"section":"1. The siege of Mariupol","text":"Around 13 March 2022, a T-72M3-variant main battle tank fired at hospital No. 2,\nleading to civilian casualties and damage to its fourth and fifth floors. The hospital was\ntreating injured persons and sheltered dozens. The Commission interviewed several\nwitnesses who suffered the impact of the attack and had observed a tank with the letter “Z”\nmark used by Russian armed forces stationed in front of the building. One eyewitness saw\nthe tank firing on the hospital. Interlocutors reported that Russian armed forces had taken\ncontrol of the hospital the previous day and conducted a search. The Commission concluded\nthat the Russian armed forces had committed an attack that was indiscriminate 6 and\nconstituted the war crime of excessive incidental death, injury or damage. 7 It assessed that it\nwas disproportionate to fire on a functioning hospital with civilians, as well as Russian\nsoldiers, inside. Hospitals also have special protection under international humanitarian law."},{"id":"a-hrc-55-66-p0018","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"18","seq":21,"section":"1. The siege of Mariupol","text":"The Commission previously found that on 9 March 2022, Russian armed forces had\nconducted an indiscriminate air attack that hit maternity hospital No. 3. 8 For the present\nreport, the Commission interviewed additional civilians who were injured in the strike. A\nyoung woman waiting to give birth lost contact with her parents, who were both injured in\nthe attack, and had to evacuate to another maternity hospital. There, she gave birth to a boy\nin a freezing room, with no water. She stated: “This was supposed to be the happiest moment\nin my life, but it was one of the scariest.”"},{"id":"a-hrc-55-66-p0019","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"19","seq":22,"section":"1. The siege of Mariupol","text":"Residents from Mariupol also reported that there was a shortage of medical personnel\nand of essential supplies for urgent assistance to the injured. A medical practitioner told the\nCommission that she saw an endless number of wounded people coming in. A woman\nwaiting for her son to be operated on said that limbs had to be amputated without anesthesia.\nAn injured patient stated that medications had run out and injured persons were dying of their\nwounds. A woman sheltering in a hospital described the stairway as the “pathway of death”.\nShe saw severely injured people, with missing body parts, asking for water. Even that could\nnot be provided.\nLack of access to basic necessities"},{"id":"a-hrc-55-66-p0020","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"20","seq":23,"section":"1. The siege of Mariupol","text":"As the fighting intensified, energy facilities and supply lines were damaged. Satellite\nimagery shows damage to 11 power stations. According to residents from Mariupol, water,\npower and heating went off on 2 March 2022, one day after the siege started. A few days\nlater, gas was no longer available. Around mid-March 2022, water and food also became\nscarce. Shops that could open had limited products. Despite the ongoing shelling, residents\nhad no choice but to go outdoors to look for food and to cook. Some were killed and injured\nas a result. Residents stated that they were forced to melt snow or to drink water from\nradiators and boilers. Witnesses described suffering intensely from the cold. Living\nconditions were particularly harsh in crowded shelters in the basements of hospitals and\ncultural or administrative buildings, where dozens of people sought refuge, often without\nbasic necessities.\nTakeover by Russian armed forces and evacuation"},{"id":"a-hrc-55-66-p0021","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"21","seq":24,"section":"1. The siege of Mariupol","text":"Many residents of Mariupol reported that, at the height of the fighting, the mobile\nphone signal was virtually non-existent and residents were cut off from information about\nevacuation corridors. Interlocutors reported that they had attempted to flee on their own\ninitiative, risking their lives. Some residents witnessed Russian combat vehicles and soldiers\nfiring at civilians who were attempting to flee by car.\n6 Protocol Additional to the Geneva Conventions of 12 August 1949, and relating to the Protection of\nVictims of International Armed Conflicts (Protocol I), art. 51 (4) and (5).\n7 Ibid., art. 85 (3) (b).\n8 Conference room paper of the Commission of Inquiry, paras. 195–200."},{"id":"a-hrc-55-66-p0022","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"22","seq":25,"section":"1. The siege of Mariupol","text":"As Russian armed forces took gradual control of parts of the city, they carried out\nso-called “clearings” (“зачистки”),9 which included searching the area. Residents sheltering\nin a hospital reported that Russian soldiers intimidated and shot at persons during this\nprocess. Sometimes, they ordered civilians to leave immediately the locations where they had\nsheltered. Russian armed forces allowed or ordered evacuations to areas they controlled.\nCivilians had to cross multiple checkpoints and filtration points. According to interlocutors,\nduring lengthy controls, some persons were forced to undress so they could be checked for\ntattoos, and some were detained. To reach territories under Ukrainian Government control,\nmany had to flee through the Russian Federation and several other countries."},{"id":"a-hrc-55-66-p0023","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"23","seq":26,"section":"1. The siege of Mariupol","text":"Survivors from Mariupol described the trauma and fear that haunted them. When\nasked about justice, one young woman replied: “We lived happily in wonderful Mariupol …\nbut someone’s decision caused us to lose everything, our lives, our friends, our houses, our\nrelatives … nothing could replace our loss … all this cannot be returned”."},{"id":"a-hrc-55-66-p0024","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"24","seq":27,"section":"1. The siege of Mariupol","text":"The Commission previously found that Russian armed forces had committed\nindiscriminate attacks affecting the Mariupol Drama Theater 10 and maternity ward No. 3, in\nviolation of international humanitarian law. During the current mandate, the Commission\nfound that Russian armed forces had committed an indiscriminate attack and the war crime\nof excessive damage affecting hospital No. 2. In these cases, Russian armed forces failed to\ntake all requisite feasible precautions under international humanitarian law. The current\nfindings confirm the need to continue investigations, including regarding whether the\nconduct of hostilities and the siege may constitute crimes against humanity.11"},{"id":"a-hrc-55-66-p0025","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"25","seq":28,"section":"2. Attacks with explosive weapons","text":"During its second mandate, the Commission continued its examination of attacks with\nexplosive weapons in populated areas. It documented examples of such attacks, which caused\nnumerous civilian casualties and affected civilian objects such as residential buildings,\nfunctioning medical institutions, historical buildings, including churches, a railway station, a\nrestaurant, a café, supermarkets, a warehouse for civilian use and a gas station. 12"},{"id":"a-hrc-55-66-p0026","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"26","seq":29,"section":"2. Attacks with explosive weapons","text":"Attacks with explosive weapons in populated areas remain the leading cause of death\nand injury among the civilian population in Ukraine. As at 15 February 2024, 8,898 had been\nkilled and 18,818 injured in such attacks, according to OHCHR. The actual number is likely\nhigher."},{"id":"a-hrc-55-66-p0027","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"27","seq":30,"section":"2. Attacks with explosive weapons","text":"Particularly tragic was the attack that hit a café in the village of Hroza, Kharkiv\nProvince, on 5 October 2023, killing 36 women, 22 men and 1 boy, at a time when a large\nnumber of civilians had gathered for a memorial service. 13 The Commission interviewed\ndevastated villagers who knew most of the persons who had perished and lost several family\nmembers in the strike."},{"id":"a-hrc-55-66-p0028","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"28","seq":31,"section":"2. Attacks with explosive weapons","text":"Also significant was the 29 December 2023 wave of attacks, one of the largest in the\npast two years, which affected locations in at least eight cities across Ukraine and led to the\nkilling of over 50 persons, according to reports. The next day, a strike in central Belgorod, in\nthe Russian Federation, reportedly killed 25 persons."},{"id":"a-hrc-55-66-p0029","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"29","seq":32,"section":"2. Attacks with explosive weapons","text":"For the present report, the Commission investigated attacks affecting cultural objects,\nwhich are protected under international humanitarian law.14 Two waves of attacks, on 20 and\n23 July 2023, in Odesa Province damaged 29 cultural buildings, according to Ukrainian\nauthorities (see paras. 41–45). Most of the buildings affected were located within the\nperimeter of the historic centre of the city of Odesa, which is inscribed on the World Heritage\nList. Another attack, on 6 July 2023, in Lviv, struck a building and damaged several others\nwithin the historical perimeter, which is also inscribed on the World Heritage List, killed 8\nwomen and 1 man, and injured 45 civilians."},{"id":"a-hrc-55-66-p0030","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"30","seq":33,"section":"2. Attacks with explosive weapons","text":"Explosive weapon attacks affecting health-care facilities have both an immediate and\na long-lasting impact and deprive communities of much-needed health services. The\nCommission describes such attacks in Dnipro, Dnipropetrovsk Province (see paras. 38 and\n39) and Mariupol (see para. 17), and collected information regarding an attack that reportedly\ndamaged a hospital in Donetsk city (see para. 48).\n3.         Attacks with explosive weapons in territories under Ukrainian Government control"},{"id":"a-hrc-55-66-p0031","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"31","seq":34,"section":"2. Attacks with explosive weapons","text":"The Commission found that the attacks it investigated, which are detailed below, were\nindiscriminate, in violation of international humanitarian law, as, among other things, they\nwere not directed at specific military objectives. In most incidents, the Commission identified\nno military presence at the sites of the attacks or in their immediate vicinity. In the case of\nthe attack in Kramatorsk, Donetsk Province, the Commission found that, while there was\nsome military presence, the attack caused a combination of loss of civilian lives, injury to\ncivilians and damage that was excessive in relation to a possible military advantage, and it\nwas therefore disproportionate. In all cases, the attacking forces failed to take feasible\nprecautions, such as verifying that the object attacked was not civilian, in violation of\ninternational humanitarian law."},{"id":"a-hrc-55-66-p0032","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"32","seq":35,"section":"2. Attacks with explosive weapons","text":"The Commission concluded that almost all of the attacks were committed by the\nRussian armed forces. The attack in Sloviansk, Donetsk Province, was likely committed by\nthe Russian armed forces. In each case, the Commission carefully considered a range of\nfactors in reaching its conclusions."},{"id":"a-hrc-55-66-p0033","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"33","seq":36,"section":"2. Attacks with explosive weapons","text":"Based on photographs of the weapon remnants, the Commission found that different\ntypes of missiles were used in each attack. Missiles have a wide area effect when fired in\npopulated areas and can cause harm and damage to civilians and civilian objects. The\nCommission considered whether the damage described could have resulted from a physical\ninterception by Ukrainian armed forces and, on examining the available evidence for each\ncase, it determined that this was unlikely.\n(a)         Attacks affecting civilian objects\nSloviansk, 14 April 2023"},{"id":"a-hrc-55-66-p0034","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"34","seq":37,"section":"2. Attacks with explosive weapons","text":"On 14 April 2023, around 4 p.m., strikes with explosive weapons in Sloviansk killed\n6 men, 3 women and 1 boy, injured 13 persons at various locations and damaged various\nbuildings. According to Ukrainian authorities, a total of seven projectiles were fired. The\nCommission’s investigation focused on a residential building at Parkovyi Lane 6, where the\ntwo top floors were destroyed and the deaths occurred. It determined that the likely weapon\nused was a 5V55 anti-aircraft guided missile launched from an S-300 air defence missile\nsystem. Such missile systems were found in both States’ arsenals. Recent credible reports\nindicate that the Russian armed forces adapted the system for ground targets. Based on a\nrange of factors, the Commission concluded that Russian armed forces likely committed the\nattack.\nKryvyi Rih city, 13 June 2023"},{"id":"a-hrc-55-66-p0035","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"35","seq":38,"section":"2. Attacks with explosive weapons","text":"On 13 June 2023, after 3 a.m., missiles hit four sites in Kryvyi Rih, Dnipropetrovsk\nProvince, killing 8 men, 2 women and 1 adolescent boy and injuring over 30 persons. The\nCommission focused its investigation on the attack at a warehouse, which was staffed at the\ntime and was severely damaged. The Ministry of Defence of the Russian Federation reported\nthat a wave of attacks was carried out during that night.15 The Commission determined that\nthe likely weapon was a Kh-101 cruise missile. Such missiles were used by the Russian armed\nforces and were not known to be part of the Ukrainian stockpile. Ukrainian armed forces\n15   Russian Federation, Ministry of Defence, Telegram post, 13 June 2023, available at\ndeclared that they had intercepted 10 of the 14 missiles launched that night. 16 The\nCommission determined that it was unlikely that the damage to the warehouse was caused\nby physical interception.\nKramatorsk, 27 June 2023"},{"id":"a-hrc-55-66-p0036","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"36","seq":39,"section":"2. Attacks with explosive weapons","text":"On 27 June 2023, around 7.30 p.m., a strike hit Ria Pizza Restaurant located at Vasylia\nStusa Street 45, in Kramatorsk, killing 4 men, 4 women and 3 girls and injuring 64 persons;\nit destroyed the premises. According to a variety of sources, a mixed group of civilians and\nmilitary personnel were present in the restaurant at its busiest hour. The Ministry of Defence\nof the Russian Federation reported having carried out a strike in Kramatorsk on that day. 17\nSome days later, Sergey Lavrov, the Minister for Foreign Affairs of the Russian Federation,\ndeclared: “If we spot ‘meetings’ of this sort (like the one held in Kramatorsk the other day),\nwe will destroy them.”18 The Commission determined that the likely weapon of the attack\nwas a 9M727 cruise missile of the Iskander-K type. Such missiles were used by the Russian\narmed forces and were not known to be part of the Ukrainian stockpile.\nConclusion"},{"id":"a-hrc-55-66-p0037","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"37","seq":40,"section":"2. Attacks with explosive weapons","text":"The Commission concluded that the Russian armed forces attack affecting the\nrestaurant in Kramatorsk was disproportionate and violated international humanitarian law.\nIt further found that Russian armed forces committed an indiscriminate attack affecting a\ncivilian warehouse in Kryvyi Rih, in violation of international humanitarian law, and likely\ncommitted such an attack hitting a residential building in Sloviansk.\n(b)        Attacks affecting protected objects: a medical institution\nDnipro, 26 May 2023"},{"id":"a-hrc-55-66-p0038","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"38","seq":41,"section":"2. Attacks with explosive weapons","text":"The Commission finalized its investigation into the attack that struck a medical clinic\nat Universal’nyi Lane 6 in Dnipro on 26 May 2023 at about 10.30 a.m., killing 3 men and 1\nwoman and injuring over 30 others, including patients and medical staff. 19 The attack\ndestroyed the clinic and a neighbouring veterinary unit. The clinic was providing\npsychological care, including to patients suffering from conflict-related stress. The\nCommission determined that the attack was carried out with an Iskander-K cruise missile.\nSuch missiles were used by Russian armed forces in Ukraine and were not known to be part\nof the Ukrainian stockpile."},{"id":"a-hrc-55-66-p0039","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"39","seq":42,"section":"2. Attacks with explosive weapons","text":"The Commission concluded that Russian armed forces committed an indiscriminate\nattack affecting a functional clinic in Dnipro, in violation of international humanitarian law,\nunder which, as a medical clinic, it also has special protection.\n(c)        Attacks affecting protected objects: cultural objects"},{"id":"a-hrc-55-66-p0040","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"40","seq":43,"section":"2. Attacks with explosive weapons","text":"The Commission investigated two waves of attacks which affected, among other\nthings, objects located within the perimeter of the historic centre of Odesa city, which was\ninscribed on the World Heritage List. Such places have special protection under international\nhumanitarian law (see para. 29).\nOdesa city, 20 July 2023"},{"id":"a-hrc-55-66-p0041","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"41","seq":44,"section":"2. Attacks with explosive weapons","text":"On 20 July 2023, after 1 a.m., a wave of attacks hit Odesa Province, severely\ndamaging, among other things, a building at Kanatna Street 1B, in Odesa city. The blast\naffected neighbouring buildings, namely, the Archaeological Museum, the Literature\nMuseum and a kindergarten. All of them were located within the historic centre. The attacks\nkilled one man and injured two men, one woman and one boy."},{"id":"a-hrc-55-66-p0042","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"42","seq":45,"section":"2. Attacks with explosive weapons","text":"The Ministry of Defence of the Russian Federation reported that a wave of attacks had\nbeen carried out during that night.20 The Commission determined that the attack at Kanatna\nStreet was carried out with a Kalibr-type cruise missile. Such missiles were used by Russian\narmed forces in Ukraine and were not known to be part of the Ukrainian stockpile. According\nto Ukrainian armed forces, the strike involved 38 missiles and unmanned aerial vehicles, of\nwhich 18 were destroyed.21 In the attack in question, the Commission determined that it was\nunlikely that the damage described was caused by physical interception.\nOdesa city, 23 July 2023"},{"id":"a-hrc-55-66-p0043","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"43","seq":46,"section":"2. Attacks with explosive weapons","text":"On 23 July 2023, starting at approximately 1 a.m., another wave of explosions hit\nseveral locations in Odesa Province and damaged 44 buildings, most of which were historical\nbuildings in the historic centre of Odesa city. The Commission’s investigations focused on\nthe attacks at the Transfiguration Cathedral at Soborna Square 3 and two residential\nbuildings, at Preobrazhenska Street 4 and Viyskovyy Descent 18, respectively, which were\nseverely damaged. The attacks killed 1 man and 1 woman and injured 19 others, including 3\nchildren."},{"id":"a-hrc-55-66-p0044","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"44","seq":47,"section":"2. Attacks with explosive weapons","text":"The Ministry of Defence of the Russian Federation reported having launched a wave\nof attacks. 22 It also posted a message regarding the attack affecting the Transfiguration\nCathedral, stating that the “most probable cause of its destruction was the fall of a Ukrainian\nanti-aircraft guided missile”.23 The Commission determined that, for the three sites, the likely\nweapons employed were Onyx anti-ship cruise missiles. Such missiles were used by Russian\narmed forces and were not known to be part of the Ukrainian stockpile. Ukrainian authorities\nstated that, of 19 missiles, 9 had been destroyed. In the attacks in question, the Commission\ndetermined that it was unlikely that the damage described was caused by a physical\ninterception.\nConclusion"},{"id":"a-hrc-55-66-p0045","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"45","seq":48,"section":"2. Attacks with explosive weapons","text":"The Commission found that the Russian armed forces committed indiscriminate\nattacks affecting several buildings and the Transfiguration Cathedral in Odesa city, which\nwere all located within the historic centre. An aggravating feature was that the attacks hit\ncultural objects that have special protection under international humanitarian law.\n(d)         Concluding observations"},{"id":"a-hrc-55-66-p0046","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"46","seq":49,"section":"2. Attacks with explosive weapons","text":"In each of its reports, the Commission has reviewed multiple cases of attacks with\nexplosive weapons committed by the Russian armed forces that constituted violations of\ninternational humanitarian law. Those attacks were indiscriminate, including some being\ndisproportionate. The Commission also found that Russian armed forces failed to take\nfeasible precautions to, among other things, verify that the objects of the attacks were not\ncivilian. Certain attacks amounted to the war crime of excessive incidental death, injury or\ndamage. The continuation of such attacks, for over two years of armed conflict, further\ndemonstrates a pattern of disregard for the requirement to maintain the distinction between\nmilitary objectives and civilians, as previously underscored by the Commission.\n20 Russian Federation, Ministry of Defence, Telegram post, 20 June 2023, available at\nhttps://t.me/mod_russia_en/8495.\n21 General Staff of the Armed Forces of Ukraine, Facebook post, 21 July 2023, available at\nhttps://m.facebook.com/story.php?story_fbid=pfbid0S1iZQpiQDwAuQFn3Rf7HFQLg159vdUerYPv\nTY7JxTAmSQhWm3V12c98vY3DN7Sbml&id=100069092624537.\n22 Russian Federation, Ministry of Defence, Telegram post, 23 July 2023, available at\nhttps://t.me/mod_russia_en/8547.\n23 Russian Federation, Ministry of Defence, Telegram post, 23 July 2023, available at"},{"id":"a-hrc-55-66-p0047","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"47","seq":50,"section":"2. Attacks with explosive weapons","text":"The Commission has previously found that the repeated waves of attacks on the\nenergy infrastructure, starting in October 2022, were systematic, widespread and part of a\npolicy, citing, among other things, statements by the highest authorities of the Russian\nFederation, and therefore that they might amount to a crime against humanity. 24 The\nCommission is not in a position at this point to reach that conclusion, but it encourages further\ninvestigation to determine the accumulated impact on the civilian population of the attacks,\nand to what extent the policy was directed against the civilian population.25"},{"id":"a-hrc-55-66-p0048","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"48","seq":51,"section":"4. Attacks carried out in areas under the control of Russian authorities","text":"The Commission has continued to examine attacks with explosive weapons that have\naffected areas under Russian control. According to information received from a Russian\nauthority and open sources, on 16 April 2023, an attack hit the Central Market and other\nlocations in Donetsk city, killing one woman and injuring four persons. In addition, according\nto open sources, on 28 April 2023, an attack affected the Donetsk Regional Trauma Hospital,\na passenger bus and several other locations in Donetsk city, killing seven persons. As\nmentioned above, hospitals have special protection under international humanitarian law."},{"id":"a-hrc-55-66-p0049","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"49","seq":52,"section":"4. Attacks carried out in areas under the control of Russian authorities","text":"Videos and photographs circulating in the aftermath show damage or destruction at\nvarious locations, including the hospital, which appears consistent with the effect of\nexplosive weapons. Based on those images, the Commission assessed that BM-21 Grad-type\nrockets, present in both parties’ stockpiles, were likely used for both waves of attacks. An\nanalysis of footage of the impact sites also revealed that in both situations the attacks likely\ncame from a north-western direction, where, at that time, both parties were positioned on the\nline of contact."},{"id":"a-hrc-55-66-p0050","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"50","seq":53,"section":"4. Attacks carried out in areas under the control of Russian authorities","text":"The Commission has been unable to conclude its investigations of the attacks because\nit has no access to the relevant areas and its requests for information from the Russian\nFederation have remained unanswered (see para. 7). It recommends further investigation into\nthose incidents. The Commission reiterates the importance of access to relevant locations of\nevents and information. It takes the opportunity to remind States of the international legal\nobligation to ensure the protection of civilian lives and objects."},{"id":"a-hrc-55-66-p0051","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"51","seq":54,"section":"5. Unlawful seizure of cultural property","text":"The Commission has examined information related to the seizure of cultural property\nby Russian authorities in areas under their control, and documented two cases in Kherson\ncity, Kherson Province. Investigations show that from the end of October 2022 to early\nNovember 2022, during the last days of the occupation of Kherson city, Russian authorities\ntransferred cultural objects from the Kherson Regional Art Museum and archival documents\nfrom the State Archives of Kherson Province to the Autonomous Republic of Crimea\n(Crimea). According to estimates of staff of both institutions, over 10,000 objects from the\nMuseum and 70 per cent of the documents from the main building of the State Archive, were\nremoved. Several Russian-appointed local authorities publicly confirmed the transfers,\nstating that their aim was to preserve the objects from the effects of the armed conflict. For\ninstance, on 30 October 2022, the Russian-run Ministry of Culture of Kherson Province\ndeclared that it had actively contributed to the evacuation of the valuables of the museums of\nKherson Province and that “if such measures are not taken, the culture and history of our\nMotherland could be erased by the actions of the Kiev regime”.26"},{"id":"a-hrc-55-66-p0052","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"52","seq":55,"section":"5. Unlawful seizure of cultural property","text":"However, in the case concerning the removal of the archival documents, the\nCommission did not find any indication that Russian authorities engaged with the Ukrainian\nauthorities regarding the purported preservation measures, as legally required.27 Furthermore,\non 18 March 2023, the Russian Federation adopted a law 28 which stipulated that museum\ncollections and archival documents, among others things, of the territories of Donetsk,\nKherson, Luhansk and Zaporizhzhia Provinces29 would become part of the Museum Fund\nand the Archival Fund of the Russian Federation. The law has the effect of appropriating\nsuch objects. The Commission concluded that Russian authorities violated international\nhumanitarian law relating to cultural property and committed the war crime of seizing the\nenemy’s property.30"},{"id":"a-hrc-55-66-p0053","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"53","seq":56,"section":"B. Personal integrity violations","text":"During its second mandate, the Commission gathered further evidence of violations\nand crimes committed by Russian authorities in areas they controlled. It has documented the\nwar crimes of torture, wilful killing, rape and other sexual violence, and unlawful\nconfinement, as well as the corresponding human rights violations. One victim was subjected\nto forced labour."},{"id":"a-hrc-55-66-p0054","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"54","seq":57,"section":"B. Personal integrity violations","text":"Consistent with previously described patterns, a majority of violations and crimes\noccurred during or after house searches, as Russian authorities looked for persons supporting\nthe Ukrainian armed forces. Interlocutors reported that Russian armed forces at times\nconducted searches using lists of names prepared in advance."},{"id":"a-hrc-55-66-p0055","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"55","seq":58,"section":"B. Personal integrity violations","text":"The Commission has also investigated cases in which Ukrainian authorities\ncommitted human rights violations against persons suspected of collaboration with Russian\nauthorities."},{"id":"a-hrc-55-66-p0056","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"56","seq":59,"section":"1. Wilful killings","text":"The Commission has continued to collect and examine credible reports of wilful\nkillings committed by Russian authorities. It investigated the summary executions of four\ncivilian men from 38 to 52 years of age, in Novopetrivka village, Mykolaiv Province. The\nvictims were last seen in the custody of members of the Russian armed forces, who had\npreviously visited their houses and suspected them or their relatives of cooperating with the\nUkrainian armed forces. The victims’ bodies were found later with gunshot injuries to the\nhead and other body parts. Two of them had their hands tied behind their backs. The body of\none of the victims was found almost one year later. The victim’s wife had asked the Russian\narmed forces at least twice about his fate, but they did not provide her with information. In\nthat case, in addition to the war crime of wilful killing, the Russian armed forces also\ncommitted the human rights violation of enforced disappearance.31"},{"id":"a-hrc-55-66-p0057","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"57","seq":60,"section":"1. Wilful killings","text":"Furthermore, the Commission found that the victims were subjected to the war crime\nof torture or inhuman treatment prior to execution. Russian soldiers beat two of the victims\nat their house. In another case, Russian soldiers interrogated the victim and tortured him,\nincluding by using tools to file his teeth and pliers on his fingers. In a third case, the victim’s\nbody was found with multiple traumas, bruises, fingers cut, cuts on the torso and burn marks\non one hand."},{"id":"a-hrc-55-66-p0058","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"58","seq":61,"section":"2. Torture","text":"The Commission previously found that Russian authorities had committed torture in\nseven provinces of Ukraine and in the Russian Federation. 32 It has continued to gather\nevidence of widespread and systematic use of torture by Russian authorities, in both Ukraine\nand the Russian Federation. The Commission has documented additional cases in Kherson,\nKyiv, Mykolaiv and Zaporizhzhia Provinces of Ukraine and in Belgorod, Kursk and Tula\nProvinces of the Russian Federation. The victims were men and women, with the majority\n29 The concerned territories of the four provinces had been unlawfully annexed by the Russian\nFederation in 2022 (A/HRC/52/62, para. 90).\n30 Convention for the Protection of Cultural Property in the Event of Armed Conflict, arts. 4 and 5;\nGeneva Convention relative to the Protection of Civilian Persons in Time of War (Fourth Geneva\nConvention), art. 147; and Regulations respecting the Laws and Customs of War on Land, arts. 23 (g)\nand 56.\n31 Declaration on the Protection of All Persons From Enforced Disappearance.\n32 A/HRC/52/62, para. 71.\nbeing men from 21 to 58 years of age. Most victims of wilful killings and rape had also been\nsubjected to torture (see paras. 57 and 86)."},{"id":"a-hrc-55-66-p0059","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"59","seq":62,"section":"2. Torture","text":"During its current mandate, the Commission focused on cases of torture in 11\ndetention facilities, 7 in areas under Russian control in Ukraine and 4 in the Russian\nFederation. 33 It examined credible reports concerning torture in numerous additional\ndetention places in areas under Russian control. The geographic spread of those locations\ndemonstrated and confirmed the Commission’s previous finding that the practice of torture\nwas widespread."},{"id":"a-hrc-55-66-p0060","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"60","seq":63,"section":"2. Torture","text":"The Commission continued to document cases of torture against civilians and\nprisoners of war. In the present report, it has focused on prisoners of war. Russian authorities\ntortured civilians they suspected of cooperating with Ukrainian armed forces, to extract\ninformation. In the case of prisoners of war, perpetrators also used torture to punish and\nintimidate. The Commission found similar methods of torture across different detention\nfacilities. These elements taken together confirmed that Russian authorities used torture\nsystematically."},{"id":"a-hrc-55-66-p0061","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"61","seq":64,"section":"2. Torture","text":"Finally, the Commission continued its investigations on whether torture was\ncommitted in furtherance of a policy.\n(a)        Torture of Ukrainian prisoners of war"},{"id":"a-hrc-55-66-p0062","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"62","seq":65,"section":"2. Torture","text":"In most cases investigated, Russian armed forces confined large groups of Ukrainian\nprisoners of war as they seized control of localities in Ukraine. They transferred and detained\nthem for periods spanning from 9.0 to 15.5 months, in up to seven different locations in the\nRussian Federation and in Ukraine. In the Russian Federation, these included pre-trial\ndetention facility No. 1 (SIZO-1) in Kursk city, Kursk Province;34 pre-trial detention facility\nNo. 2 (SIZO-2) in Staryi Oskol city and correctional colony No. 6 in Valuyki town, both in\nBelgorod Province; and correctional colony No. 1 in Donskoy town, Tula Province. Credible\nreports regarding such treatment in additional places of detention were also examined."},{"id":"a-hrc-55-66-p0063","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"63","seq":66,"section":"2. Torture","text":"Victims explained that in Ukraine, torture was perpetrated by the Russian armed\nforces. In the Russian Federation, members of the special purpose units of the Federal\nPenitentiary Service of the Russian Federation and regular personnel of that Service, referred\nto as prison guards, committed torture. The victims stated that interrogations were led, in\naddition, by members of the Federal Security Service35 of the Russian Federation."},{"id":"a-hrc-55-66-p0064","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"64","seq":67,"section":"2. Torture","text":"Victims’ accounts disclose relentless, brutal treatment, inflicting severe pain and\nsuffering for almost the entire duration of their detention, with blatant disregard for human\ndignity, leading to long-lasting physical and mental trauma. One Ukrainian soldier, who was\ndetained and tortured by Russian authorities in several detention facilities, recounted his\nexperience in correctional colony No. 1 in Donskoy town. He stated that Federal Penitentiary\nService personnel beat him on the way to and from interrogation, which broke his collarbone.\nThey forced him to do repeated jumps regardless of a surgery to his foot. He developed\ngangrene. They beat him on his buttocks in the isolation ward, causing bleeding from his\nanus. In the yard, they beat him on his face and injured foot, leading to bleeding. They\nknocked out some of his teeth. He begged them to kill him. Another time, they beat him until\nhe could not feel his feet and was unable to stand. He was bleeding. He said “I lost any hope\nand will to live” and that he had attempted suicide in his cell using his uniform. Perpetrators\nfound him and beat him until he had a broken tailbone and toe and was bleeding. He was also\ntortured with electric shocks for two weeks. As of January 2024, he had undergone\n36 hospitalizations since his release."},{"id":"a-hrc-55-66-p0065","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"65","seq":68,"section":"2. Torture","text":"In most facilities, the prisoners of war underwent a brutal “admission procedure”, with\nbeatings and electric shocks. One victim recalled being greeted with “welcome to hell”.\nTorture occurred during interrogation sessions, where detainees were questioned about the\nUkrainian armed forces and their military units. Torture was also employed to intimidate and\npunish. Victims reported torture “everywhere”, in cells, corridors, the courtyard and the\nbathhouse. A perpetrator told a victim: “We will now teach you how to fight against the\nRussians.” Another victim heard a prison guard stating: “Our goal is that you never return to\nwar.” According to detainees, particularly harsh treatment was inflicted on prisoners of war\nfrom Mariupol or western Ukraine, on those who were not fluent in Russian and when\nRussian armed forces lost control of areas in Ukraine."},{"id":"a-hrc-55-66-p0066","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"66","seq":69,"section":"2. Torture","text":"Methods of torture used recurrently included severe and repeated beatings with\nvarious instruments on different parts of the body. One victim recounted that during beatings,\nperpetrators said: “When will you finally die?” Electric shocks using various tools were\nadministered on various parts of the body, including when detainees went to the bathhouse\nand were wet. Another victim stated that he was in shock, as was every other fellow prisoner\nof war: “It was barbaric. It was unbearably painful. I was almost all the time on the floor, as\nmy wounds were bleeding, but those animals were laughing and ordering me to stand up.”"},{"id":"a-hrc-55-66-p0067","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"67","seq":70,"section":"2. Torture","text":"Former male detainees reported threats of rape, objectionable touching during\ninvasive body searches and torture on the genitals. One victim of beatings and electric shocks\nto the genitals said that one of the perpetrators told him: “I will beat everything out of you,\nso you can’t make children.” A similar statement was made to another detainee. A victim\nrecounted perpetrators’ attempts to cut his penis, in order to “prevent him from having more\nchildren”. Victims reported additional methods of torture used repeatedly and for months in\nthe documented detention facilities."},{"id":"a-hrc-55-66-p0068","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"68","seq":71,"section":"2. Torture","text":"In several of the facilities investigated, conditions of detention were inhuman or\ndegrading. Medical support was mostly denied or inadequate. The food was poor and scarce\nand, in some places, only 2 to 7 minutes were allowed for eating. Victims reported deep\nsuffering from hunger and resorted to eating worms, soap, paper and remnants of dog food,\nleading to a sharp decline in body weight. In some of the facilities, access to showers and\ntoilets was limited, or a hole in the ground served as the toilet."},{"id":"a-hrc-55-66-p0069","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"69","seq":72,"section":"2. Torture","text":"As a consequence of torture, former prisoners of war reported difficulties breathing,\nsleeping and walking; broken bones and teeth; bleeding, swelling and infected or gangrened\nbody parts; poor eyesight; and trauma to body organs. Victims developed post-traumatic\nstress disorder and anxiety, and some attempted suicide. One former detainee stated: “No\ncreature alive deserves to be treated like Russians treat Ukrainians in their detention facilities.\nOver there, you don’t feel like a human being anymore.”\nPerpetrating entities"},{"id":"a-hrc-55-66-p0070","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"70","seq":73,"section":"2. Torture","text":"Interviews with prisoners of war, persons who declared themselves to be former\nmembers of a special purpose unit operating under the Federal Penitentiary Service, and a\nformer Russian soldier indicated that the treatment of prisoners of war appeared to have been\nencouraged, or at a minimum tolerated, by higher-ups within the respective organizational\nhierarchies and that there was an apparent sense of impunity."},{"id":"a-hrc-55-66-p0071","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"71","seq":74,"section":"2. Torture","text":"One former member of a special purpose unit recounted that, at an early stage of the\nfull-scale invasion, a general who was the regional head of the Federal Penitentiary Service\nheld a meeting with staff members to be deployed to facilities in the Russian Federation\nwhere Ukrainian prisoners of war were detained. He stated that “Nazis aren’t humans” and\ninstructed them to “work harshly and with no pity”(“работать жестко и не жалеть”).\nThe interlocutor clarified that this implied the use of physical violence against detainees, such\nas beatings with rubber batons, electrocution with tasers and other methods. Based on his\nfamiliarity with the workings of the Service, he reported that such treatment could not have\nhappened without his unit commander’s permission because of the hierarchical nature of the\npenitentiary service."},{"id":"a-hrc-55-66-p0072","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"72","seq":75,"section":"2. Torture","text":"Another former member of a special purpose unit was aware that the above-mentioned\nregional head of the Federal Penitentiary Service had held a meeting with staff before their\ndeployment. Separately, he heard how a commander of a special purpose unit had said that\n“fascists” would be brought to a detention facility in the Russian Federation and that the\nspecial purpose unit “will need to work with them harshly”(“надо с ними жестко\nпоработать”). The interlocutor also heard how the head of another special purpose unit\nmentioned that he had just returned from deployment at a detention facility in the Russian\nFederation and described the ruthless use of force against Ukrainian detainees by his unit,\nstating that everything was allowed and that they worked on detainees as on a boxing bag."},{"id":"a-hrc-55-66-p0073","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"73","seq":76,"section":"2. Torture","text":"A former prisoner of war detained in the Russian Federation stated that, regardless of\nrotations of Federal Penitentiary Service personnel, torture continued “again and again”.\nAnother victim heard newly arrived Service members asking if they were allowed to treat the\ndetainees from Ukraine brutally. The response of outgoing personnel was: “green light to\ndestroy them”."},{"id":"a-hrc-55-66-p0074","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"74","seq":77,"section":"2. Torture","text":"The above-mentioned former Russian soldier reported that he saw the deputy\ncommander of his military unit beat and carry out multiple mock executions of Ukrainian\nprisoners of war at a makeshift location in Ukraine. He underscored that the deputy\ncommander did not try to hide this treatment and other military officers seemed well-aware\nof his treatment of prisoners of war. The witness noted that a Federal Security Service officer\nwas involved in interrogations and that he also seemed aware of the treatment of the prisoners\nof war.\n(b)        Torture of civilians in Ukraine"},{"id":"a-hrc-55-66-p0075","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"75","seq":78,"section":"2. Torture","text":"In Ukraine, the Commission continued to gather evidence of torture committed by\nRussian authorities in areas they controlled. Many of the victims were detained in the context\nof house searches. Perpetrators were generally looking for persons they suspected of\ncollaborating with or supporting the Ukrainian authorities. In addition to the detention\nfacilities identified previously,36 the Commission investigated torture committed in the police\ndepartment in Melitopol city and the district police in Vasylivka town, both in Zaporizhzhia\nProvince; in the temporary detention centre in Kherson city, Kherson Province; and in other\nplaces of detention. According to former detainees, perpetrators of torture were Russian\narmed forces, members of the Federal Security Service and detention facility guards."},{"id":"a-hrc-55-66-p0076","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"76","seq":79,"section":"2. Torture","text":"In detention, torture was committed to extract information about the Ukrainian armed\nforces and persons cooperating with them. Perpetrators used torture methods which the\nCommission has described in its previous reports, including beatings using various tools and\nthe administration of electric shocks with tasers and the so-called “tapik”.37 The Commission\nhas also investigated incidents of rape of women in detention (see, for instance, paras. 86, 87\nand 92).\nPerpetrating entities"},{"id":"a-hrc-55-66-p0077","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"77","seq":80,"section":"2. Torture","text":"The Commission has previously reported that in areas under Russian control for\nlonger periods, victims mentioned that special services from the Russian Federation had\noperated in some of the detention facilities, and notably that members of the Federal Security\nService had led interrogations and inflicted torture.38 The Commission further confirmed this\npattern, for instance in the temporary detention centre in Kherson city. A victim tortured there\nnoted that the way in which interrogations were held and torture was committed was part of\na “well-established procedure that they repeated with everyone”."},{"id":"a-hrc-55-66-p0078","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"78","seq":81,"section":"2. Torture","text":"According to former detainees, around July 2022, prison guards from the Russian\nFederation that looked “professional” replaced the Russian armed forces who had initially\nrun the facility and members of the Federal Security Service, referred to as “investigators”,\nconducted the interrogations. They gave orders to the guards concerning treatment to be\ninflicted on the detainees, including in preparation for interrogations, which mainly meant\nbeating and administering electric shocks. For instance, one victim overheard conversations\nin which representatives of the Federal Security Service instructed the guards to “work” with\na detainee, after which he understood that the guards would submit the detainee to such\ntreatment. Another victim heard an order being given to “do what is needed to prepare them”,\nafter which he was submitted to beatings and electric shocks. On the next day, he was brought\nfor interrogation and asked whether he was ready to talk.\n(c)        Concluding observations"},{"id":"a-hrc-55-66-p0079","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"79","seq":82,"section":"2. Torture","text":"Over the course of its two mandates, the Commission has reported on the widespread\nand systematic use of torture by Russian authorities, both in Ukraine and in the Russian\nFederation. In the present report, it provides new findings about the torture of prisoners of\nwar, which is a war crime."},{"id":"a-hrc-55-66-p0080","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"80","seq":83,"section":"2. Torture","text":"The consistency of the evidence regarding the torture of both civilians and prisoners\nof war, throughout its reports, as well as the common elements observed in the documented\ncases, show the systematic nature of the practice. Practices and techniques used across\ndifferent detention centres – including commonly used names for certain torture methods and\ndevices – all of which are designed to cause immense pain and degradation, are routinely\napplied to detainees. Their use in several provinces of Ukraine and of the Russian Federation,\nmainly in various detention facilities, demonstrates the widespread nature of the torture."},{"id":"a-hrc-55-66-p0081","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"81","seq":84,"section":"2. Torture","text":"The evidence collected appears to show practices that call for organization and a\ndivision of labour involving different institutions. Recently analysed information is\nsuggestive of the hierarchical nature of the services involved in the commission of torture,\nthe knowledge of superiors and a prevailing sentiment of impunity. These are elements in the\nCommission’s ongoing investigations of whether torture was committed pursuant to a policy,\nto determine, as a consequence, whether it may amount to a crime against humanity. The\nCommission recommends further investigations.\n3.         Arbitrary arrest, detention and ill-treatment of alleged collaborators by Ukrainian\nauthorities"},{"id":"a-hrc-55-66-p0082","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"82","seq":85,"section":"2. Torture","text":"The Commission has previously expressed concern about the treatment of alleged\ncollaborators and has outlined three such cases.39 For the current report, it investigated two\nadditional cases in which victims were arbitrarily arrested and detained, and one of them was\nalso ill-treated, in violation of international human rights law."},{"id":"a-hrc-55-66-p0083","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"83","seq":86,"section":"2. Torture","text":"On 7 March 2022, in a village of Kyiv Province, armed persons came to the house of\na man whom they suspected of cooperating with Russian authorities, arrested him and took\nhim to an office of the Security Service of Ukraine in Kyiv city. According to the victim, at\nthe time of the arrest and initial detention, perpetrators did not inform him of the reasons for\nthe arrest and of the charges brought against him. The arrest of the victim was officially\nregistered only on 14 March 2022. On the next day, he was transferred to a detention facility.\nThe Commission found that the victim was arbitrarily arrested and detained, at least from 7\nto 14 March 2022, and that members of the Security Service of Ukraine were involved."},{"id":"a-hrc-55-66-p0084","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"84","seq":87,"section":"2. Torture","text":"In the second case, on 14 March 2022, in Kyiv city, a woman who was critical of\nhuman rights violations allegedly committed by the Ukrainian authorities was arrested at a\nrelative’s apartment by men in uniform, who brought her to a police station. According to the\nvictim, at the time of the arrest and initial detention, perpetrators did not inform her of the\nreasons for the arrest and of the charges brought against her. At the police station, after she\nasked for the protocol of arrest and to see her lawyer, the perpetrators hit her repeatedly and\nconducted a mock execution to coerce her to share the password of her phone. She was\ndetained in several locations until 16 March 2022, when she was transferred to another\ndetention facility and provided with an arrest protocol. At times during her detention, the\nSecurity Service of Ukraine was involved. The Commission found that the victim was\narbitrarily arrested and detained, at least from 14 to 16 March 2022, and ill-treated."},{"id":"a-hrc-55-66-p0085","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"85","seq":88,"section":"4. Sexual and gender-based violence","text":"The Commission has previously documented cases of sexual and gender-based\nviolence by Russian authorities in nine provinces of Ukraine and in the Russian Federation.40\nDuring the current mandate, it investigated additional cases in Kherson, Kyiv, Mykolaiv and\nZaporizhzhia Provinces in Ukraine. Victims were girls and women from 15 to 83 years of\n39   A/HRC/52/62, para. 89, and A/78/540, paras. 70–73.\n40   A/HRC/52/62, para. 78.\nage. 41 Consistent with patterns identified previously, members of the Russian authorities\ncommitted rapes and other sexual violence during house searches and in detention."},{"id":"a-hrc-55-66-p0086","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"86","seq":89,"section":"4. Sexual and gender-based violence","text":"In the cases investigated, of which examples are given below, the Commission found\nthat the war crime of rape, and in some cases the war crime of sexual violence, had been\ncommitted. Those acts also amounted to torture. Perpetrators committed additional acts of\nviolence against all the victims and a family member, which also amounted to torture. Those\nacts also constituted human rights violations. In addition, one victim was unlawfully\nconfined, transferred and subjected to forced labour in violation of international human rights\nlaw and international humanitarian law.42"},{"id":"a-hrc-55-66-p0087","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"87","seq":90,"section":"4. Sexual and gender-based violence","text":"Russian authorities, mostly in groups, conducted house searches, sometimes on\nmultiple occasions. Some of the soldiers were intoxicated. They threatened and intimidated\nvictims and their family members with weapons, including by shooting near their heads or\nlegs. Perpetrators raped the victims in their homes, or forcibly took them to premises they\nhad occupied in the vicinity or to locations they used as a temporary base, or raped them\nduring confinement. Russian authorities also voiced threats of rape towards men in detention\n(see para. 67). Some of the victims were subjected to rape repeatedly, sometimes by the same\nperpetrator and sometimes by a group of perpetrators. In most cases, in addition to rape and\nsexual violence, perpetrators beat, kicked or otherwise inflicted severe pain on the victims."},{"id":"a-hrc-55-66-p0088","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"88","seq":91,"section":"4. Sexual and gender-based violence","text":"As previously documented, Russian authorities were searching for persons suspected\nof cooperating with Ukrainian armed forces or of having a pro-Ukrainian position. In two\ncases, the circumstances suggested that the women were subjected to sexual violence as\npunishment for support to the Ukrainian authorities.\nCase descriptions"},{"id":"a-hrc-55-66-p0089","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"89","seq":92,"section":"4. Sexual and gender-based violence","text":"In March 2022, in a village in Kyiv Province, two Russian soldiers broke into a house\nand took turns repeatedly raping a 42-year-old woman who was three months pregnant and\nthe 17-year-old girlfriend of her son. They used weapons to threaten the victims and their\nfamily members. The soldiers subsequently returned with the woman’s son, ordered all three\ninto a room and again took turns raping the woman and the girl, while forcing the young man\nto witness the rapes. They fired two shots near his head. Perpetrators later took the three\nvictims to an empty house, threatened the young man with a knife and again raped the woman\nand the girl."},{"id":"a-hrc-55-66-p0090","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"90","seq":93,"section":"4. Sexual and gender-based violence","text":"In April 2022, in a village in Kherson Province, a Russian armed forces officer came\nto a house, searched it, grabbed a 15-year-old girl who lived there, stated that he needed to\ninterrogate her and ordered her to accompany him. He drove her to an abandoned shop, forced\nher to undress and drink alcohol, punched her in the face and raped her."},{"id":"a-hrc-55-66-p0091","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"91","seq":94,"section":"4. Sexual and gender-based violence","text":"In September 2022, in another village in Kherson Province, three Russian soldiers\ncame to the house of a married couple, looking for a 54-year-old woman who lived there, and\ndirected her to follow them to a house which they used as their base. There, one soldier told\nher: “We will make sure to show you what happens to the Nazis and Ukrainian armed forces\nfans like you.” They beat her and administered electric shocks. Then two of the soldiers raped\nher in turns. According to the victim, this lasted for hours."},{"id":"a-hrc-55-66-p0092","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"92","seq":95,"section":"4. Sexual and gender-based violence","text":"In October 2022, in a city in Zaporizhzhia Province, Russian authorities searched the\nhouse of a 50-year-old woman whose husband served in the Ukrainian armed forces. They\nconfined her in a police station, invoking her pro-Ukrainian position and her husband’s role.\nDuring interrogation, they asked her to provide information, beat her, placed a plastic bag\nover her head, strangled her with a wire, undressed her fully, touched her and threatened to\nrape her. The victim stated that she was “shivering with shame”. After being transferred to a\ndetention facility in a different village, she was interrogated by the head of the police\ndepartment. He ordered her to undress, beat her, then raped her with a stick and threatened\nto kill her. In January 2023, Russian authorities transferred her to a checkpoint and subjected\nher to forced labour digging trenches. According to the victim, two Russian soldiers took her\nto another house and raped her at least five times."},{"id":"a-hrc-55-66-p0093","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"93","seq":96,"section":"4. Sexual and gender-based violence","text":"These crimes left victims with serious physical and mental health challenges,\nlong-lasting trauma, stigmatization and feelings of shame, including towards their own\nfamilies. While some victims said that they had received much-needed support, others spoke\nof blame and stigma by some community members and decided not to report the crimes. Two\nvictims who reported the crimes stated that the interrogation by the Ukrainian police was\ndisrespectful and intimidating, and a source of additional trauma. They consequently\nwithdrew their complaints."},{"id":"a-hrc-55-66-p0094","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"94","seq":97,"section":"4. Sexual and gender-based violence","text":"These incidents have also been highly traumatizing for family members. Some of\nthem felt a deep sense of guilt for not having been able to protect their loved ones. Such\nviolent events have also ruptured family relations. One victim broke up with her fiancé\nbecause he stigmatized her after the rape. Another victim who was raped while her fiancé\nwas forced to watch, could no longer look at him, and she ended the relationship."},{"id":"a-hrc-55-66-p0095","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"95","seq":98,"section":"5. Transfers of children","text":"The Commission has continued to investigate allegations concerning the transfer and\ndeportation of children from Ukraine to the Russian Federation or to Russian-occupied areas\nin Ukraine.43 It has focused on the transfer of 46 children from Kherson Regional Children’s\nHome to Crimea on the orders of Russian authorities on 21 October 2022. The institution\nhosted children, from infants to children 5 years of age. On a video filming the transfer of the\nchildren, Igor Kastyukevich, a Russian politician, stated that the children were being\nevacuated for safety reasons.44 In Crimea, a large number of the children were accommodated\nin the Yolochka orphanage in Simferopol. The mother of one of them stated that she had not\nbeen informed of the transfer. She succeeded in travelling to Crimea to bring back her son in\nOctober 2023."},{"id":"a-hrc-55-66-p0096","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"96","seq":99,"section":"5. Transfers of children","text":"Several social media declarations made by Russian authorities in 2023 referred to the\ncontinuous presence of a group of children from Kherson Regional Children’s Home in\nCrimea months after the initial transfer. On 26 July 2023, a social media post of the\nRussian-run Ministry of Labour and Social Protection of Kherson Province referred to a\nrecent visit by the Russian-appointed Minister of Labour and Social Policy of Kherson\nProvince to the Yolochka orphanage in Simferopol. In the post, it was stated that: “In October\n2022, our children were evacuated from Kherson to Crimea to undergo rehabilitation in local\nsanatoriums and medical institutions … A major renovation of a building is planned in the\nKherson region. In the future, our children will be accommodated there after their return from\nCrimea.”45 The ministry posted again about the children in Crimea on 6 August 2023. In\nNovember 2023, a Ukrainian authority informed the Commission that, except for isolated\ncases, the majority of the children had not yet returned to a territory under Ukrainian\nGovernment control."},{"id":"a-hrc-55-66-p0097","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"97","seq":100,"section":"5. Transfers of children","text":"The Commission, on examination of this and other sources of information, concludes\nthat the transfer of a group of children from the Kherson Regional Children’s Home to\nCrimea was not temporary and hence amounted to the war crime of unlawful transfer."},{"id":"a-hrc-55-66-p0098","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"98","seq":101,"section":"C. Incitement to commit genocide","text":"The Commission has previously expressed concerns about allegations of genocide in\nUkraine. Its investigations are ongoing. It has examined allegations that raise issues under\nthe Convention on the Prevention and Punishment of the Crime of Genocide, in particular\nwhether the rhetoric transmitted in Russian state and other media constitutes direct and public\nincitement to commit genocide. The Commission has reviewed many public statements that\n43 A/HRC/52/62, paras. 95–102.\n44 Igor Kastyukevich, Telegram post, 21 October 2022, available at https://t.me/kastyukevich_live/2480\n(in Russian).\n45 Kherson Province, Ministry of Labour and Social Protection, Telegram post, 26 July 2023, available\nat https://t.me/socialpolitics_ks/1782 (in Russian).\nuse dehumanizing language and call for hate, violence and destruction. It is concerned about\nstatements by individuals supporting the full-scale invasion of Ukraine by the Russian\nFederation and calling for the killing of a large number of persons. The Commission\nrecommends continued investigations into this important matter and underlines the\nresponsibility of States to prevent such utterances."},{"id":"a-hrc-55-66-p0099","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"99","seq":102,"section":"III. Conclusions and recommendations","text":"During its second mandate, the Commission has found further evidence that, in\nthe context of their full-scale invasion of Ukraine, Russian authorities have committed\na wide array of violations of international human rights law and international\nhumanitarian law, as well as war crimes. These included indiscriminate attacks\naffecting civilians and civilian objects, in violation of international humanitarian law,\nand the war crimes of torture, wilful killing, rape and sexual violence, and the transfer\nof children, which violate international human rights law. The evidence gathered\nreinforced the Commission’s previous findings that Russian authorities had used\ntorture in a widespread and systematic way."},{"id":"a-hrc-55-66-p0100","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"100","seq":103,"section":"III. Conclusions and recommendations","text":"The Commission documented a few cases in which Ukrainian authorities\ncommitted human rights violations against persons they accused of collaborating with\nRussian authorities."},{"id":"a-hrc-55-66-p0101","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"101","seq":104,"section":"III. Conclusions and recommendations","text":"The armed conflict, the loss of life, and the damage and destruction and\nconsequent deprivation of the most basic necessities have continued to deeply affect\ncivilians. In the present report, the Commission has provided an initial assessment of\nthe impact of the heavy fighting in and siege of Mariupol, which led to large-scale death,\ninjury and destruction, as well as unbearable suffering."},{"id":"a-hrc-55-66-p0102","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"102","seq":105,"section":"III. Conclusions and recommendations","text":"The Commission strongly condemns the violations and corresponding crimes. It\nreiterates the importance of ensuring that perpetrators are identified and held\naccountable. The Commission also underscores the importance of other dimensions of\naccountability, such as truth, reparations and guarantees of non-recurrence. Due\nconsideration of the rights and needs of the victims should be at the centre of these\nprocesses."},{"id":"a-hrc-55-66-p0103","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"103","seq":106,"section":"III. Conclusions and recommendations","text":"The Commission considers that the recommendations that it made previously\nremain relevant to a very large extent. 46 The Commission makes additional\nrecommendations, as set out below, with a view to strengthening accountability and\npreventing further violations."},{"id":"a-hrc-55-66-p0104","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"104","seq":107,"section":"III. Conclusions and recommendations","text":"The Commission recommends that the parties to the armed conflict:\n(a)    Ensure the timely, effective, thorough, independent, impartial and\ntransparent investigation of all allegations of international crimes and violations of\ninternational human rights law and international humanitarian law, including sexual\nand gender-based violence and violence against children, and the prosecution of such\ncrimes and violations;\n(b)   Ratify international instruments to which they are not yet party to\nstrengthen the protection of civilians in armed conflict."},{"id":"a-hrc-55-66-p0105","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"105","seq":108,"section":"III. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation immediately:\n(a)     Cease aggression and all acts of violence committed against civilians and\nprisoners of war in violation of applicable international human rights and international\nhumanitarian law;\n(b)   End the use of torture and other forms of ill-treatment against both\ncivilians and prisoners of war;\n(c)    Take all possible measures to prevent sexual and gender-based violence\nperpetrated against civilians and prisoners of war;\n(d)   Take all feasible precautions to protect civilians, considering that the\nleading cause of death since the beginning of the full-scale invasion remains the use of\nexplosive weapons;\n(e)   Cease attacks affecting civilian infrastructure, particularly protected\nobjects such as health-care facilities and cultural property;\n(f)  Comply strictly with international humanitarian law and respect the\ntemporary nature of any transfer or evacuation of children by ensuring their\nexpeditious return and refrain from adopting measures that would have a contrary\neffect;\n(g)    Release or return to Ukraine all Ukrainian civilians who have been\ndeported to or detained in the Russian Federation."},{"id":"a-hrc-55-66-p0106","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"106","seq":109,"section":"III. Conclusions and recommendations","text":"The Commission further recommends that the Russian Federation:\n(a)    Ensure that all perpetrators, in particular commanders and other\nsuperiors and those ordering, soliciting or inducing the commission of international\ncrimes, are held accountable in accordance with international human rights standards;\n(b)    Take the necessary measures to prevent the commission of such violations\nand crimes, in particular through unequivocal instructions to all branches of the armed\nforces and other entities participating in the armed conflict, with a view to ensuring that\nmilitary discipline and respect for international human rights and international\nhumanitarian law are upheld, along with the principle of command responsibility;\n(c)    Refrain from placing any impediment to humanitarian assistance in\noccupied territories;\n(d)     Abide by international humanitarian law applicable to occupied\nterritories, including respect for cultural objects;\n(e)     Cooperate fully with all international monitoring and investigative bodies,\nwith a view to enabling investigations into violations and related crimes committed by\nall parties in the occupied territories and on the territory of the Russian Federation."},{"id":"a-hrc-55-66-p0107","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"107","seq":110,"section":"III. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)   Comprehensively address mental health and psychosocial needs resulting\nfrom the armed conflict by ensuring access to the relevant services, allocating resources\nto those services and enhancing their institutional coordination, legal regulation,\nmonitoring and evaluation;\n(b)    Ensure that its efforts towards a comprehensive reparations programme\nare harmonized with regional and international initiatives on the establishment of a\nfuture international compensation mechanism, including the Register of Damage\nCaused by the Aggression of the Russian Federation against Ukraine, established by\nthe Council of Europe, and that emerging programmes are designed through\nmeaningful consultations with victims;\n(c)    Continue building capacity for gender-sensitive and survivor-centred\nlegal processes of accountability and provide reparative justice, including medical and\npsychosocial support to all victims, prioritizing victims of sexual and gender-based\nviolence;\n(d)   Finalize an investigatory and prosecutorial strategy, building on its\nStrategic Plan on the Implementation of Powers of the Office of the Prosecutor General\nin the Area of Prosecution for International Crimes for 2023–2025, and ensure due\nprocess and transparent monitoring;\n(e)   Harmonize its legislation relating to war crimes where it is not in\nconformity with international standards and amend its criminal code to clarify the\ndefinition of “collaborative activity” to avoid legal uncertainty and harm to social\ncohesion."},{"id":"a-hrc-55-66-p0108","rec_id":"recsSTV76B4zKE8f6","symbol":"A/HRC/55/66","n":"108","seq":111,"section":"III. Conclusions and recommendations","text":"The Commission recommends that other States and regional and international\norganizations:\n(a)    Strengthen national, regional and international accountability\nmechanisms, both judicial and non-judicial, including by improving their coordination\nand supporting the effective participation of civil society and groups representing\nvictims and survivors;\n(b)    Ensure meaningful consultations with victims in the operationalization of\nthe Register of Damage Caused by the Aggression of the Russian Federation against\nUkraine, established by the Council of Europe;\n(c)     Integrate the human rights dimensions of the armed conflict in Ukraine\nmore fully into the agenda of the Security Council."},{"id":"a-79-549-u0000","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":0,"section":null,"text":"United Nations                                                                            A/79/549\nGeneral Assembly                                                      Distr.: General\n25 October 2024","unnumbered":true},{"id":"a-79-549-u0001","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":1,"section":null,"text":"The Secretary-General has the honour to transmit to the General Assembly the\nreport of the Independent International Commission of Inquiry on Ukraine, submitted\nin accordance with paragraph 23 of Human Rights Council resolution 55/23, on the\nsituation of human rights in Ukraine stemming from the Russian aggression.","unnumbered":true},{"id":"a-79-549-u0002","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":2,"section":null,"text":"Summary\nIn its third report to the General Assembly, the Independent International\nCommission of Inquiry on Ukraine outlines its new findings concerning torture,\nsexual violence, attacks with explosive weapons that have affected civilians and\ncivilian objects and attacks on energy-related infrastructure.\nFor over two mandates, the Commission has consistently found that Russian\nauthorities have used torture – as a war crime and the corresponding human rights\nviolation – against Ukrainian civilians and prisoners of war, in the context of their\nfull-scale invasion of Ukraine.\nThe Commission’s recent findings demonstrate that Russian authorities have\ncommitted torture in all provinces of Ukraine where areas have come under Russian\ncontrol and in the detention facilities investigated in the Russian Federation. This\nconfirms that torture has been widespread. Additional common patterns in the way in\nwhich torture has been committed have shown that it was systematic. These patterns\nconcern the categories of persons targeted, the commonality of methods employed,\nthe aim for which torture has been used and the transposition of violent practices\ncommon in Russian Federation detention facilities to similar facilities in areas under\nRussian control in Ukraine.\nThe cases documented illustrate that Russian authorities have deployed or\nrecruited personnel who have acted in a coordinated manner and according to a\ndivision of labour in the commission of torture. Testimonies collected describe the\ninvolvement of officials of the Federal Penitentiary Service and the Federal Security\nService of the Russian Federation, as well as Russian armed forces officers; witnesses\nhave referred to orders to commit torture and a prevailing sense of impunity.\nSexual violence as a form of torture has been prevalent in detention facilities\nheld by Russian authorities, and medical assistance to detainees has been often\ndenied. The Commission of Inquiry outlines illustrative cases where Russian\nauthorities have committed sexual violence as a form of torture during detention,\nwhich amounts to torture.\nThe overall findings lead the Commission to consider that it has sufficient\nevidence to determine that the Russian authorities have acted pursuant to a\ncoordinated State policy and have therefore committed crimes against humanity of\ntorture.\nVictims have described the physical pain and trauma, with long-lasting or\nirreparable consequences, and have emphasized the immense psychological\nchallenges they face. The cases documented demonstrate an egregious and profound\ndisregard by the Russian authorities for physical integrity and human dignity.\nThe Commission has investigated explosive weapons attacks that struck\ncivilians and civilian objects, including medical and cultural objects, which are\nprotected under international humanitarian law, on both sides of the front line.","unnumbered":true},{"id":"a-79-549-u0003","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":3,"section":null,"text":"Continuous, massive waves of attacks carried out by the Russian Federation\nagainst the energy-related infrastructure of Ukraine have resulted in blackouts, at\ntimes affecting millions of civilians. The power cuts have, among other consequences,\ncurtailed the enjoyment of the rights to health and education, with severe effects on\nchildren, older persons and persons living with a disability or a medical condition.\nPersons affected have described feelings of distress, anxiety and isolation and the\nrepercussions on their security and health.\nIn its conclusions, the Commission reiterates the importance of judicial and\nnon-judicial accountability, while taking into account victims’ needs, to end the\nculture of impunity. Many victims have expressed a vital need for justice to be done.","unnumbered":true},{"id":"a-79-549-p0001","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"1","seq":4,"section":null,"text":"In its third mandate, the Independent International Commission of Inquiry on\nUkraine submits the present report to the General Assembly, 1 at its seventy-ninth\nsession, pursuant to Human Rights Council resolution 55/23. The Commission has\ncontinued its work with the same membership. 2"},{"id":"a-79-549-p0002","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"2","seq":5,"section":null,"text":"Since its establishment, the Commission has interviewed 849 women and 818\nmen, and examined documents, expert and forensic reports, photographs and videos.\nDuring the current mandate, the liquidity crisis at the United Nations has severely\naffected the staffing of the secretariat of the Commission and its ability to travel.\nNevertheless, it has been able to continue its investigations, notably relying on remote\ninterviews with victims and witnesses and other sources, applying its usual standard\nof proof."},{"id":"a-79-549-p0003","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"3","seq":6,"section":null,"text":"In its work, the Commission has continued to abide by its well-established\nprinciples of independence, impartiality, objectivity and integrity, as well as its\nvictim-centred approach. 3"},{"id":"a-79-549-p0004","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"4","seq":7,"section":null,"text":"The Commission reiterates its deep gratitude to victims and witnesses for\nsharing experiences and to organizations for the information provided."},{"id":"a-79-549-p0005","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"5","seq":8,"section":null,"text":"It appreciates the cooperation of the Government of Ukraine. It regrets that 26\nwritten requests to the Russian Federation for access, information and meetings\nremain unanswered, as it continues not to recognize the Commission.\nII. Violations of international law"},{"id":"a-79-549-p0006","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"6","seq":9,"section":null,"text":"A third year of armed conflict in Ukraine has continued to cause civilian\ncasualties and destruction across the country, in particular in territories controlled by\nthe Government of Ukraine, including areas far from front lines. As of September\n2024, the toll of the armed conflict had raised to at least 11,743 the number of civilians\nkilled and 24,614 those injured, according to the Office of the United Nations High\nCommissioner for Human Rights. Hostilities have led to new displacements and\ndisruptions to access to basic services. The Commission has also followed the\ndevelopments in Kursk Province of the Russian Federation."},{"id":"a-79-549-p0007","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"7","seq":10,"section":null,"text":"In its previous reports, the Commission concluded that Russian authorities had\ncommitted a wide array of violations and corresponding crimes during their full-scale\ninvasion of Ukraine. For the present report, it has focused on the impact of attacks on\nthe energy-related infrastructure of Ukraine, individual attacks with explosive\nweapons affecting civilians and civilian objects in populated areas, torture, and sexual\nand gender-based violence. In its work, the Commission has identified common\npatterns of violations and crimes. The cases documented and the examples outlined\nbelow are only a sample of the large number of allegations it has investigated.\nA.        Attacks with explosive weapons"},{"id":"a-79-549-p0008","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"8","seq":11,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"In its March 2023 report to the Human Rights Council, the Commission\nexamined in detail the large-scale waves of attacks that the Russian Federation had\nlaunched on the energy-related infrastructure of Ukraine since 10 October 2022. It\nrecorded at least 13 large-scale attacks between that time and the end of January 2023\nand found that they had been widespread and systematic. 4 Since then, and until\nSeptember 2024, at least nine additional massive waves of attacks have significantly\naffected the country’s energy infrastructure. According to Ukrainian authorities’\nreports, each wave was launched using at least 90, and up to 470, projectiles,\nincluding missiles, drones and air-dropped bombs. More attacks, on a smaller scale,\nhave also affected the energy infrastructure of Ukraine. The attacks have hit, among\nother objects, power plants and substations, equipment and transmission li nes, and\nhave had a substantial impact on the country’s electricity and thermal generation,\ntransmission and distribution."},{"id":"a-79-549-p0009","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"9","seq":12,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"The Commission has also recorded individual attacks reported in open sources\nthat have affected such objects as oil installations, refineries and depots, situated in\nRussian-controlled areas in Ukraine or in the Russian Federation.\n(b)       Impact on civilians of attacks against the energy-related infrastructure of Ukraine"},{"id":"a-79-549-p0010","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"10","seq":13,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"In its March 2023 report, the Commission found that the attacks affecting the\nenergy-related infrastructure of Ukraine had been disproportionate due to the\nconsiderable civilian harm that they had inflicted. It determined that the Russian\narmed forces had committed the war crime of excessive incidental death, injury or\ndamage. 5 Further large-scale attacks throughout 2023 and 2024 have continued to\nhave a severe impact on civilians, causing power outages, at times affecting millions,\nsometimes over long periods. The Commission has continued its investigations,\nincluding interviews, in eight provinces of Ukraine, namely, Dnipropetrovsk, Ivano-\nFrankivsk, Kharkiv, Kyiv, Lviv, Odesa, Poltava and Zakarpattia."},{"id":"a-79-549-p0011","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"11","seq":14,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"In the present report, the Commission focuses on the impact of the attacks on\nthe enjoyment of the rights to health and education. The evidence collected shows\nthat the large-scale power cuts have had a differentiated impact on distinct categories\nof the population. Older people, in particular older women, as well as adults and\nchildren with disabilities and displaced children, have been most affected. In many\ncases, the additional work of caregiving has been a burden that has fallen primarily\non women.\nImpact on the right to health"},{"id":"a-79-549-p0012","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"12","seq":15,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"According to the Ministry of Health and regional hospital administrators,\nmedical institutions have generally been able to continue to operate with the use of\ngenerators and thanks to the efforts of personnel. Staff have had to plan activities\naround power cuts and have thus been unable to provide the full range of services\npreviously available. Medical facilities are just one area to consider when assessing\nthe realization of the right to health, which also includes access to drinking water,\nadequate sanitation, safe food, healthy environmental conditions and other elements,\nall of which have been affected by the power cuts."},{"id":"a-79-549-p0013","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"13","seq":16,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Electricity cuts have affected the refrigeration of medications and have led to\ninterruptions in the use of life-support electrical devices at home, including oxygen\nconcentrators, nebulizers and ventilators, dialysis machines, feeding and drug pumps,\nhoists and lifting devices, as well as pressurized mattresses. For instance, one woman\nwith whom the Commission spoke, a wheelchair user, needed peritoneal dialysis four\ntimes a day using a device at home. She was dependent on electricity for her survival\nand had only been able to continue her treatment due to the power supply unit\nprovided by an aid organization."},{"id":"a-79-549-p0014","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"14","seq":17,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Lack of electricity has created additional health and security risks, particularly\nfor older persons living alone. Social workers informed the Commission of incidents\nthat had occurred in this context. One older man, who had mistaken his medication in\nthe dark during a power cut, became ill and had to be hospitalized. Two older women\nfell during power cuts and were found at home alone, lying on the ground and unable\nto get up. These are only some of the ways in which electricity cuts threaten the well -\nbeing of vulnerable persons."},{"id":"a-79-549-p0015","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"15","seq":18,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"When air alerts have coincided with power outages, persons with reduced\nmobility have experienced higher risks to their safety and considerable stress due to\ntheir inability to reach shelters. For instance, a couple using wheelchairs explained to\nthe Commission that they could not reach a bomb shelter and remained in their\napartment during shelling, observing the “rule of two walls” as their only security\nmeasure. A woman with reduced mobility told the Commission, “I go to a corridor,\nsit there and listen to some blasts … when there is no light, it is even scarier, I feel\nreally helpless”."},{"id":"a-79-549-p0016","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"16","seq":19,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Electricity cuts have also led to increased isolation, affecting mental health.\nIsolation has been compounded by a lack of Internet, mobile phones and television.\nPersons with disabilities and older persons have felt trapped and lost, due to the\nincreased barriers in maintaining contact with the outside world. For instance, a social\nworker reported to the Commission how a 94-year-old woman, afraid of getting stuck\nin the elevator, only went out using the stairs when she visited her, and spent the rest\nof her time at home alone. Another woman, a wheelchair user, who could not get out\nwhen there was no electricity, referred to a recent long power cut, and said, “It’s awful\nwhen you don’t even know what your day will be like. Can you work? Will you eat\nsomething? Will you be able to go out … or will you sit at home?”"},{"id":"a-79-549-p0017","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"17","seq":20,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"The frequent disruptions of online education due to power cuts and the resulting\nisolation, have posed mental health challenges for children. Persons with learning\ndisabilities or autism have also encountered particular difficulties. Two women with\nautistic sons told the Commission that their children struggled to understand the\ndisruptions. Both studied online and their lessons were frequently interrupted.\nRepeated schedule changes due to electricity cuts and noise from generators were\nsources of distress."},{"id":"a-79-549-p0018","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"18","seq":21,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Carers, mostly women, of people in all of the above-mentioned categories have\nborne additional burdens. For instance, a team of social workers made up entirely of\nwomen, over 85 per cent of whom were of pension age, reported to the Commission\nthat they had continued to visit clients during blackouts but had encountered\nchallenges. Often, they had to climb 10 floors or more in the absence of functioning\nelevators. Their work has been emotionally and physically draining.\nImpact on the right to education"},{"id":"a-79-549-p0019","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"19","seq":22,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Schools in Ukraine have had to adapt to the circumstances created by the full -\nscale invasion, with some opting for online or hybrid education, owing to security\nconsiderations or, in the case of displaced children, to maintain links with the schools\nof origin. Regardless of the format, all schools have been negatively affected by\nelectricity cuts. In the case of schools that require full-time presence, lessons have\nneeded to be adapted during blackouts, and students have struggled to complete\nhomework without electricity. The quality of education and skills acquired by the\nchildren has inevitably suffered."},{"id":"a-79-549-p0020","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"20","seq":23,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Online students have been particularly affected by power cuts as lessons have\nbeen frequently interrupted or cancelled, at times on a daily basis. The situation has\nbeen more challenging when teachers and students are not in the same region, as the\nblackouts may not coincide. The consequences have been even more serious for\nhouseholds that lack devices such as power banks and alternative Internet\nconnections, with children missing education as a result."},{"id":"a-79-549-p0021","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"21","seq":24,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Children from internally displaced families and children with disabilities are\nmore likely to enrol in online education and have therefore been particularly affected.\nInternally displaced children have faced additional difficulties when their devices\nused for online education have been confiscated at Russian-controlled checkpoints."},{"id":"a-79-549-p0022","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"22","seq":25,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"Frequent disruptions have also placed additional burdens on teachers, who have\nhad to adapt to the schedules of power outages and, as a consequence, work longer\nhours. Teachers have also had to prepare alternative remedial courses to be used\noffline. As younger children and children with disabilities require support in gaining\naccess to online learning, an adult, usually the mother, has had to assist them, thereby\nmissing out on economic opportunities. These burdens have sometimes provided an\nincentive for the institutionalization of children.\n(c)   Concluding observations"},{"id":"a-79-549-p0023","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"23","seq":26,"section":"1. Large-scale attacks on Ukrainian energy-related infrastructure","text":"The present report illustrates that large-scale power outages have had a\ndetrimental impact on everyone, but that the effects on the physical and mental health,\nsecurity, education and well-being of certain categories of persons, including children\nand older persons, as well as persons with a disability or a medical condition, have\nbeen particularly severe. Regular power outages have led to a series of obstacles for\nthese categories of persons in the fulfilment of their rights to health and education.\nThe Commission has also found that the primary carers of those categories of persons,\nmostly women, have been seriously affected. The full impact on civilians is not yet\nknown, and the Commission recommends that further investigations be made into this\nimportant matter. The Commission is also concerned about the upcoming colder\nmonths, when households will need electricity and heating."},{"id":"a-79-549-p0024","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"24","seq":27,"section":"2. Individual attacks with explosive weapons","text":"Attacks with explosive weapons have continued to cause numerous civilian\ncasualties, damage and destruction of civilian objects across Ukraine, in particular in\nGovernment-controlled territories. The Commission has analysed information from\nopen sources concerning attacks that have occurred in the Russian Federation and in\noccupied territories in Ukraine that have appeared to hit civilian objects, but has not\nbeen able to complete its investigations owing to lack of access, despite its requests\nto the Russian Federation."},{"id":"a-79-549-p0025","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"25","seq":28,"section":"2. Individual attacks with explosive weapons","text":"The Commission is concerned by the impact of attacks that have affected objects\nprotected under international humanitarian law, notably medical facilities. It has\ninitiated investigations relating to the 8 July 2024 wave of attacks carried out by the\nRussian Federation, affecting, among other sites, the Okhmatdyt Children’s Hospital\nin Kyiv, that led to the deaths of two adults, the injuring of over 30 persons and the\nemergency evacuation of over 600 children who had been receiving treatment at the\nhospital. The Commission is investigating the attack, part of the same wave that\naffected the Adonis and Isida medical clinics, also in Kyiv city, in which seven\npersons, mainly medical personnel, were killed. It has not yet completed its\ninvestigations into the attacks."},{"id":"a-79-549-p0026","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"26","seq":29,"section":"2. Individual attacks with explosive weapons","text":"Previously, the Commission reported on five other attacks carried out by\nRussian armed forces in violation of international humanitarian law that struck\nmedical institutions in various provinces of Ukraine. 6 It has examined credible\ninformation concerning numerous additional attacks affecting medical institutions.\nThese attacks represent only a small sample of those that have been launched."},{"id":"a-79-549-p0027","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"27","seq":30,"section":"2. Individual attacks with explosive weapons","text":"Recently, the Commission investigated attacks affecting cultural objects, which\nalso enjoy special protection under international humanitarian law. For instance, an\nexplosive weapons attack carried out by Russian armed forces on 5 November 2023\nhit Odesa in two locations and led to the damage of Odesa National Art Museum.\nAccording to Ukrainian authorities, a total of seven monuments of cultural heritage\nwere damaged following attacks carried out on that day, and one man was injured."},{"id":"a-79-549-p0028","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"28","seq":31,"section":"2. Individual attacks with explosive weapons","text":"The Commission has further focused on attacks that hit a shopping centre, a\nhypermarket and an outdoor market, all of which were in operation. Two of those\nattacks occurred at times of the day when many civilians were present, leading to\nnumerous casualties. The Commission has previously investigated attacks that struck\nfour other shopping centres or supermarkets in different provinces of Ukraine, 7\ncausing multiple civilian casualties.\n(b)       Attacks with explosive weapons in territories under the control of the\nGovernment of Ukraine"},{"id":"a-79-549-p0029","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"29","seq":32,"section":"2. Individual attacks with explosive weapons","text":"The Commission found that the Russian armed forces’ attacks affecting a\nshopping centre in Dnipro, Dnipropetrovsk Province, and a hypermarket in Kharkiv,\nKharkiv Province, had been indiscriminate, in violation of international humanitarian\nlaw.\nDnipro, 29 December 2023"},{"id":"a-79-549-p0030","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"30","seq":33,"section":"2. Individual attacks with explosive weapons","text":"On 29 December 2023, at around 7 a.m., one of the largest waves of attacks\nlaunched by the Russian Federation since 24 February 2022 hit, among other places,\nthe Appolo Shopping Centre in Dnipro. 8 Two men and one woman were killed, and\nthree men were injured. Part of the affected building and nearby infrastructure were\ndamaged. The Ministry of Defence of the Russian Federation declared that it had\n“inflicted 50 group strikes and one massive strike” during that period. On the basis of\nthe available evidence, the Commission determined that the weapon used had the\ncharacteristics of a Kh-101 cruise missile. Such missiles are used by Russian armed\nforces in Ukraine and are not known to be part of the Ukrainian stockpile. The\nCommission determined that the damage caused by the attack was unlikely to have\nbeen caused by physical interception.\nKharkiv, 25 May 2024"},{"id":"a-79-549-p0031","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"31","seq":34,"section":"2. Individual attacks with explosive weapons","text":"On 25 May 2024, at about 4 p.m., two strikes with explosive weapons hit an\nEpicentre hypermarket in Kharkiv city, killing 11 men, 6 women, a 12-year-old girl\nand a 17-year-old boy. The Commission’s investigations identified no military\npresence. Footage taken in the aftermath of the attack shows two impact sites inside\nthe shopping centre. On the basis of the available evidence, the Commission\ndetermined that the weapons used had the characteristics of UMPB D-30SN glide\nbombs. According to reports, Russian armed forces had started using such weapons\nin Ukraine in March 2024. These bombs are not known to be part of the Ukrainian\nstockpile. For the attack in question, the Commission determined that the damage was\nunlikely to have been caused by physical interception.\n(c)       Attacks with explosive weapons in areas under the control of Russian authorities"},{"id":"a-79-549-p0032","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"32","seq":35,"section":"2. Individual attacks with explosive weapons","text":"The Commission has further examined attacks with explosive weapons in areas\nunder Russian control in Ukraine. It reviewed reports concerning explosive weapons\nincidents on 21 January 2024, starting around 9 a.m., that affected several locations\nin the Kirovskyi district of Donetsk city, Donetsk Province. Publicly available videos\nand photographs show what appear to be two impact sites at an outdoor market and\nmultiple casualties in civilian clothes. In the available footage, damage to two\nresidential buildings is visible, as well as at least one casualty. Social media posts\nfrom that time reported both artillery shelling and physical interception by Russian\nair defence. An analysis of the impact sites suggests that some of the munitions could\nhave been artillery shells fired from a western direction, where the front line was. The\nCommission was unable to complete its investigations due to lack of access, despite\nits requests to the Russian Federation.\nB.        Torture and sexual and gender-based violence"},{"id":"a-79-549-p0033","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"33","seq":36,"section":"1. Torture","text":"During its first two mandates, the Commission reported on the widespread and\nsystematic use of torture by Russian authorities, both in Ukraine and in the Russian\nFederation. 9 The victims had been women and men, civilians and prisoners of war;\nthe majority had been civilians. Torture had been mainly committed in the context of\ndetention and in conjunction with other crimes and human rights violations, such as\nunlawful confinement, wilful killings and sexual violence. In the cases investigated,\nthe Commission had found that the use of torture had amounted to war crimes and the\ncorresponding human rights violations."},{"id":"a-79-549-p0034","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"34","seq":37,"section":"1. Torture","text":"The geographic spread of the locations where torture had been documented, in\nareas under Russian control in Ukraine and in the Russian Federation, as well as the\nlarge number of persons affected, established that the commission of torture had been\nwidespread. The consistency of the evidence regarding torture, throughout the\nCommission’s investigations, as well as the common elements observed in the\ndocumented cases, demonstrated that the commission of torture had also been\nsystematic. The common elements identified thus far had concerned the category of\npersons targeted, the aims for which torture had been used and the similarity of the\nmethods employed."},{"id":"a-79-549-p0035","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"35","seq":38,"section":"1. Torture","text":"Furthermore, the Commission examined whether there had been a State or\norganizational policy promoting or encouraging torture against the civilian population,\nin order to establish whether the Russian authorities had committed torture as a crime\nagainst humanity. 10"},{"id":"a-79-549-p0036","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"36","seq":39,"section":"1. Torture","text":"In its third mandate, the Commission has documented new cases of torture\nagainst civilians and prisoners of war, including in additional locations in areas under\nRussian control in Ukraine and in the Russian Federation. It has identified new\ncommon elements, notably concerning common practices used in detention facilities\nin the Russian Federation replicated in similar facilities in areas controlled by Russian\nauthorities in Ukraine. The Commission has also examined the organization and the\ndivision of labour between services operating in detention facilities where Russian\nauthorities have routinely used torture.\n(b)        Recent investigations on torture"},{"id":"a-79-549-p0037","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"37","seq":40,"section":"1. Torture","text":"Russian authorities have mostly used torture against civilians and prisoners of\nwar during confinement, including in facilities improvised at the location of military\ndeployments, in seized buildings, medium-sized detention facilities in police stations\nor filtration points, and well-established official penal colonies or pretrial detention\ncentres. In the present report, the Commission focuses on the well-established\ndetention facilities."},{"id":"a-79-549-p0038","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"38","seq":41,"section":"1. Torture","text":"The Commission has documented new cases of torture and confirmed the use of\ntorture by Russian authorities in additional detention facilities in areas under Russian\ncontrol in Ukraine and in the Russian Federation. With the new evidence collected,\nthe Commission has presently found cases of torture in all nine provinces where areas\nhave come under Russian control, in Ukraine and in the Autonomous Republic of\nCrimea, as well as in seven provinces and one republic of the Russian Federation. The\nannex to the present report contains an enumeration of the detention facilities where\nthe Commission has confirmed the use of torture."},{"id":"a-79-549-p0039","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"39","seq":42,"section":"1. Torture","text":"Ukrainian authorities have opened 872 investigations concerning cases of\ntorture in the context of the ongoing armed conflict and has issued indictments against\n125 persons. The Commission’s request to the Russian Federation, asking whether it\nhas conducted investigations concerning reports of torture by Russian authorities of\nUkrainian nationals, both in Ukraine and in the Russian Federation, remained\nunanswered.\n(c)        Common practices used by Russian authorities in penal colonies and pretrial\ndetention centres"},{"id":"a-79-549-p0040","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"40","seq":43,"section":"1. Torture","text":"Russian authorities have detained large numbers of persons in official facilities,\nsuch as penal colonies and pretrial detention centres, located in the Russian\nFederation and in occupied areas of Ukraine. Former detainees have described\nconsistently the same harsh practices used in those facilities, in the same sequence,\ndesigned to scare, break, humiliate, coerce and punish. Such practices have been\nenforced by regular personnel, as well as special-purpose units (referred to as\n“Spetsnaz”) of the Federal Penitentiary Service, 11 in many cases on a routine basis\nand throughout the duration of the confinement, leaving the victims with long-lasting\nphysical and mental trauma. Russian authorities have transposed these practices to\nsimilar detention centres in areas they have occupied in Ukraine."},{"id":"a-79-549-p0041","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"41","seq":44,"section":"1. Torture","text":"Detainees have been held in these locations for periods of over two years in\ncertain cases. Many have not yet been released, according to testimonies. The\nCommission has mainly interviewed civilians who had been detained in Ukraine and\nprisoners of war who had been detained in the Russian Federation. Interlocutors stated\nthat civilians and prisoners of war had generally been subjected to similar treatment.\nSome of the civilians had been reportedly given prisoner-of-war status, which is\nunlawful. 12"},{"id":"a-79-549-p0042","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"42","seq":45,"section":"1. Torture","text":"In the Russian Federation, these detention facilities are run by the Federal\nPenitentiary Service, which operates under the Ministry of Justice. In Crimea, a\nFederal Penitentiary Service facility was established in 2014. 13 In areas of Donetsk\nand Luhansk Provinces that have been under Russian control since 2014, such\ndetention facilities are run by services of the former so-called Donetsk and Luhansk\nPeople’s Republics. Following the illegal annexation of territories in Donetsk,\nKherson, Luhansk and Zaporizhzhia Provinces by the Russian Federation in\nSeptember 2022, detention facilities there came under the authority of official bodies\nof the Ministry of Justice of the Russian Federation, 14 and personnel of the Federal\nPenitentiary Service of the Russian Federation have been deployed (see para. 60).\n“Admission procedure”"},{"id":"a-79-549-p0043","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"43","seq":46,"section":"1. Torture","text":"Testimonies have included descriptions of a brutal, so-called “admission\nprocedure” 15 upon the arrival of detainees, with methods designed to instil fear and\nexert physical and psychological pressure. A former detainee recounted that, as\ndetainees were dragged out of the bus, managers of the facility and other personnel\nshouted, “If you ended up here, you must suffer. It is not Ukraine; it is a Russian\nprison”. Detainees were generally rushed into the premises, forced to run through a\ncorridor lined with personnel of the detention facility or in the yard, while being\nbeaten. Some were beaten again if they fell. Beatings were inflicted on various parts\nof detainees’ bodies, at times accompanied by electric shocks. Detainees received\norders to undress and to remain naked, for time periods going beyond possible\nsecurity requirements (see para. 48). 16 Some of them sustained serious injuries\nalready during this initial process.\nPractices imposed during detention"},{"id":"a-79-549-p0044","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"44","seq":47,"section":"1. Torture","text":"While imposing violent treatment, Federal Penitentiary Service personnel and\nspecial purpose units regularly referred to detainees as “Nazis”, or other derogatory\nnames, and blamed them for attacking the Russian Federation. Harsh practices were\nused routinely throughout the detention period. These mainly consisted of beatings\nsessions in the corridors or yards of the premises, in the showers, or during regular\nsearches of the cells. In many cases, special purpose units and regular personnel of\ndetention facilities beat detainees after lining them up in corridors in a “stretch\nposition”, with feet and hands apart. Some practices included the use of sexual\nviolence (see para. 49) and the administering of electric shocks. According to\ntestimonies, while violent practices mostly occurred in areas devoid of surveillance\ncameras, personnel of some facilities used violence in all parts of the premises,\nregardless of the presence of cameras."},{"id":"a-79-549-p0045","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"45","seq":48,"section":"1. Torture","text":"Personnel of detention facilities imposed a series of rules, such as a prohibition\nto sit or even lean against the wall during long periods, in some facilities also during\nthe night. They ordered detainees to squat, at times hundreds of times per day, or to\nremain in squat position for hours. Detainees had to walk hunched, with heads down\nat all times, to avoid looking at detention facility personnel. According to former\ndetainees, personnel monitored compliance with rules through surveillance cameras\ninstalled in the cells. They imposed severe collective punishment against all detainees\nfrom the same cell in the event of a perceived failure to respect rules and orders, for\ninstance, if a detainee did not exercise correctly, fell or attempted to sit. Pun ishment\noften consisted of beating detainees lined up in the corridor.\nInterrogation"},{"id":"a-79-549-p0046","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"46","seq":49,"section":"1. Torture","text":"While the aforementioned brutal practices were directed at all detainees, torture\nduring interrogation targeted specific categories of persons. 17 Interrogations were\naccompanied by some of the most violent treatment documented, including severe\nbeatings, sessions of electric shocks with tasers or wires attached to various body\nparts, at times in combination with water to amplify the effects, and bu rns to parts of\nthe body. In addition to extracting information, interrogations were aimed at eliciting\nfalse declarations implicating in crimes the detainees or persons they knew,\nparticularly in alleged killings of civilians in Mariupol. Several former detainees said\nthat some had made false confessions, under extreme pressure, which had resulted,\nhowever, in harsher treatment, including subsequent charges for crimes they had not\ncommitted and transfers to other detention facilities.\n(d)        Sexual violence in detention"},{"id":"a-79-549-p0047","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"47","seq":50,"section":"1. Torture","text":"Sexual violence as a form of torture has been prevalent in detention facilities\nheld by Russian authorities. Since its establishment, the Commission has collected\ntestimonies concerning acts that amount to sexual violence as a form of torture\ncommitted in 41 detention facilities of various types, in the Russian Federation and\nareas under Russian control in Ukraine. Such acts have included rape and attempted\nrape, sometimes with the use of objects, as well as beatings, electric shocks, burns or\nother attacks on genital organs, forced nudity going beyond possible security\nrequirements, threats of sexual mutilation and castration, and intrusive body searches.\nAccording to testimonies, in every detention facility held by Russian authorities\ndocumented so far, perpetrators have used at least one or a combination of several of\nthe above-mentioned methods. Some forms of sexual violence have been recurrent in\ncertain detention facilities. The victims have been men and women, civilians and\nprisoners of war; the majority have been men. Most prisoners of war that have been\ndetained by Russian authorities have reported being subjected to sexual violence."},{"id":"a-79-549-p0048","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"48","seq":51,"section":"1. Torture","text":"A common feature in the well-established detention facilities analysed for the\npresent report is the ordering of detainees to undress during the so-called “admission\nprocedure”. The imposed forced nudity goes beyond possible security requirements.\nWhile fully naked, detainees have been instructed to walk or run to various parts of\nthe facility, at times outdoors in the winter, and have been subjected to beatings and\nelectric shocks on various parts of their bodies, including as they attempt to dress. In\naddition, some detainees have described being forced to lie on the floor, kneel or\nsquat, while naked, and being beaten in those positions. Former detainees reported\nhumiliating, invasive body inspections."},{"id":"a-79-549-p0049","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"49","seq":52,"section":"1. Torture","text":"The Commission has collected testimonies regarding multiple other instances in\nwhich Russian authorities have used sexual violence as a form of torture in penal\ncolonies and pretrial detention centres, at times against groups of detainees. For\ninstance, one former detainee reported that personnel of the detention facility had\nrandomly chosen detainees in the corridors and had subjected them to deliberate\nbeatings on genitals, to inflict pain and humiliation. Another former detainee\nrecounted how detainees had been ordered to remove their clothes and lie in the\nposition of a “shrimp”, before being beaten and subjected to electric shocks. One\nemployee of the detention facility kicked him several times in his genitals while\nshouting, “Nazi! How do you like being beaten in your balls? This is because you\ncastrated our boys. You should be grateful that I am just kicking your balls. You dared\nto attack Russia.” Another former detainee stated that detention personnel would beat\ndetainees and administer electric shocks as they were in the shower of the facility,\nand that he had been subjected to electric shocks with a taser on his genitals at least\nsix times. Additional former detainees reported they had been subjected to beatings\nand electric shocks in the showers as they were naked and wet. In three facilities i n\nUkraine, former detainees described having received orders to undress, followed by\nprolonged squatting or beatings while naked. Victims reported difficulty in walking\nand long-lasting psychological trauma as a consequence of such treatment.\n(e)   Absence or denial of medical assistance during detention"},{"id":"a-79-549-p0050","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"50","seq":53,"section":"1. Torture","text":"The Commission found that, in detention facilities held by Russian authorities,\nthere had been a general absence or denial of medical assistance to detainees who\nwere injured or ill or had suffered traumas after torture. According to testimonies, in\nsome detention facilities, medical personnel had been involved in the violent\ntreatment of detainees or negligent acts. In rare instances where medical assistance\nwas provided, it often appeared insufficient or inadequate. Victims and witnesses\nreported the deterioration of the health of those affected, at times coupled with severe\ncomplications, and even death.\nFailure or denial of medical assistance"},{"id":"a-79-549-p0051","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"51","seq":54,"section":"1. Torture","text":"The Commission has documented numerous situations in which medical care\nwas not administered or was denied in detention facilities held by Russian authorities.\nSeveral situations at the Volnovakha Correctional Colony, known as Olenivka, in\nDonetsk Province, provide an egregious illustration. Former detainees, mostly captured\nin Mariupol, reported a general lack of medical assistance, despite many of them\nsuffering from multiple serious injuries. Detained Ukrainian military doctors, some\nof whom had been subjected to the violence inflicted in the colony, treated the injuries\nsustained in combat, and later the injuries sustained from torture in the colony, using\nthe small number of supplies that they carried with them. They stated that, eventually,\nRussian authorities had evacuated some of the injured to a hospital; at a later stage,\nsome visiting doctors had shared scarce and insufficient equipment or medicine."},{"id":"a-79-549-p0052","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"52","seq":55,"section":"1. Torture","text":"The violent “admission procedure” in the Olenivka colony has taken place\nregardless of visible injuries on many of the soldiers. Former detainees witnessed how\none Ukrainian soldier had collapsed during the beatings. Those in charge, including\nthe head of the colony, had been present and had not provided medical attention. The\ndetainee was pronounced dead when an ambulance came about 30 minutes later."},{"id":"a-79-549-p0053","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"53","seq":56,"section":"1. Torture","text":"Testimonies of former detainees who had been present in the Olenivka colony\non 29 July 2022, when a blast had led to the death of many Ukrainian prisoners of\nwar, indicated that no immediate medical support had been provided to dozens of\nothers severely injured. The Ukrainian military doctors detained in the same facility\nhad been asked to provide assistance only about one hour later, and had been the only\nones who had attempted to provide first aid. Again, they had had to rely on the\nsupplies from their own first-aid kits and had used bedsheets for bandages. Many of\nthe injured died before their eyes, while the leadership of the Olenivka colony had\nstood and watched. The only intervention the doctors witnessed had been trucks\ntaking away the dead and the heavily injured survivors on the next morning."},{"id":"a-79-549-p0054","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"54","seq":57,"section":"1. Torture","text":"In numerous other instances, medical assistance was not provided in detention\nfacilities held by Russian authorities. For instance, a Ukrainian soldier told the\nCommission that Russian authorities had confined him after he had suffered a serious\ninjury to his feet from a blast. His requests for medical assistance had been ignored.\nWhen he was ultimately transported to a hospital several weeks later, part of his foot\nhad had to be amputated. A civilian detainee recollected that, after a heavy blow from\nmembers of special purpose units, he had fallen and lost consciousness. His head was\nbleeding, and he suspected that his rib was broken, but detention facility personnel\nhad only provided him with a plaster and disinfectant. Two former detainees, who had\nbeen held in different facilities, each witnessed the death of a co -detainee after they\nhad been in visible distress, and no medical assistance had been provided.\nAbusive acts by medical personnel or against sick detainees"},{"id":"a-79-549-p0055","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"55","seq":58,"section":"1. Torture","text":"The Commission collected testimonies concerning the involvement of medical\npersonnel in violence or negligent acts against detainees in the Russian Federation.\nThree former detainees stated that, in a detention facility, a doctor had administered\nelectric shocks when detainees had asked for medicine. According to one of them, the\ndoctor had said, “How dare you ask for painkillers when you in Ukraine castrate our\nboys?”, as he applied a taser to his hand. Another witness stated that the doctor had\nused a taser instead of providing care and had commented that the detainees needed\nto be punished for complaining. One more former detainee reported that a doctor had\ninstructed personnel of the special purpose units to administer electric shocks while\ntaking blood from his vein, causing significant pain and swelling in his hand for one\nweek.\nInstructions regarding medical treatment or assistance to detainees"},{"id":"a-79-549-p0056","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"56","seq":59,"section":"1. Torture","text":"In interviews with the Commission, 18 a former employee of the Federal\nPenitentiary Service and a former Russian soldier provided information revealing that\nhierarchic superiors had ordered or encouraged such behaviour. The former employee\nof the Federal Penitentiary Service described that, based on his experience in\ndetention facilities in the Russian Federation, medical staff were only allowed to\nprovide assistance to detainees when they had received orders to do so, and any such\nassistance was minimal or inadequate. A doctor deployed in such a facility had told\nhim, referring to a prisoner of war from Ukraine, “that prisoner of war could be Azov,\nand Azov need to be beaten and crushed” (“гасить”). The interlocutor clarified that\nthis approach had originated from instructions of senior medical personnel, notably\nreferring to a meeting in which he had participated in 2022, prior to the deployment\nof doctors to detention facilities, amid a surge in needs owing to large numbers of\nUkrainian detainees. At the meeting, the regional head of the medical unit had\ndiscouraged the doctors from having sympathy towards prisoners of war, stating,\n“Don’t forget that prisoners are enemies. … Remember who these people are, what\nthey’ve done, and what they are capable of”."},{"id":"a-79-549-p0057","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"57","seq":60,"section":"1. Torture","text":"The above-mentioned former Russian soldier recounted that, at a makeshift\nlocation in Luhansk Province, in Ukraine, detained Ukrainian prisoners of war who\nhad been deemed to not be in a “presentable condition” for an exchange due to serious\ninjuries, had not been provided with medical aid. His testimony suggested that there\nhad been a practice in his unit whereby only prisoners of war in “presentable\nconditions” had been treated adequately. Having noticed that the health of the\nprisoners had been deteriorating, he had provided them with basic medical care\nbehind the commanders’ backs. After they had found out, they had accused him of\nbeing a spy, detained, interrogated and beaten him, and had assigned him to join an\nassault squad as punishment.\nConcluding observations"},{"id":"a-79-549-p0058","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"58","seq":61,"section":"1. Torture","text":"In addition to the many other common elements documented in the way torture\nhas been inflicted on detainees during confinement by Russian authorities, the above\nexamples demonstrate further disregard for the dignity and the rights of the detainees,\nand have, in some situations, led to unbearable consequences for the physical and\nmental health and for the survival of the persons concerned. Through such conduct,\nRussian authorities have violated the international humanitarian law provisions\nconcerning the health and integrity of detained civilians, 19 the medical attention for\nprisoners of war 20 and the detainees’ human right to health. 21 In addition, negligent or\nviolent actions committed by doctors are in breach of ethical standards to which they\nare bound. 22\n(f)        Perpetrating entities in penal colonies and pretrial detention centres"},{"id":"a-79-549-p0059","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"59","seq":62,"section":"1. Torture","text":"Another common element in the commission of torture emerges from the\nevidence pointing towards a coordinated use of personnel from specific services of\nthe Russian Federation who are involved in torture or ill-treatment in the well-\nestablished detention facilities that the Commission documented in the Russian\nFederation and in areas under Russian control in Ukraine.\nPersonnel deployed to the facilities routinely inflicting torture"},{"id":"a-79-549-p0060","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"60","seq":63,"section":"1. Torture","text":"Accounts of former detainees held in the investigated penal colonies and pretrial\ndetention facilities in the Russian Federation show that Federal Penitentiary Service\npersonnel of the Russian Federation are in charge of all routine operations. Special\npurpose units of the Service accompany the personnel in all their interactions with\ndetainees, and they undergo regular rotations. According to former detainees, such\ndetention facilities in Ukraine were initially staffed by guards recruited locally and\nworking under the Russian authorities. Several months after the onset of the full-scale\ninvasion, regular personnel and special purpose units of the Federal Penitentiary\nService were also deployed to such facilities in Ukraine and carried out the same\nfunctions as in the Russian Federation (see para. 42)."},{"id":"a-79-549-p0061","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"61","seq":64,"section":"1. Torture","text":"Multiple testimonies show that the personnel and units acted in coordination as\nthey ran the “admission procedure”, enforced the violent practices described above,\nbrought detainees to interrogations and inflicted torture during interrogations. They\nwere the main perpetrators of torture and ill-treatment during the various phases of\nthe detention. In well-established facilities in areas under Russian control in Ukraine,\nsuch violent practices were initially enforced by the locally recruited guards and, in\nmost situations, continued, in cooperation with the personnel and units deployed later\nfrom the Russian Federation."},{"id":"a-79-549-p0062","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"62","seq":65,"section":"1. Torture","text":"Former detainees emphasized the particular brutality of the special purpose units\nof the Federal Penitentiary Service, indicating that, regardless of their rotation, most\nunits behaved in the same way. In limited situations, former detainees stated tha t,\nwhile some members of the personnel of detention facilities used lower levels of\nviolence, special purpose units continued to mete out harsh treatment. In a rare\nexample, two former detainees reported that the head of a pretrial detention facility\nin the Russian Federation had prohibited the use of violence. However, personnel of\nthe special purpose units had disregarded those instructions and had continued to use\nbrutal practices in areas of the facility devoid of surveillance cameras. One former\ndetainee noted that, in response to a complaint concerning the treatment inflicted by\nthe special purpose units, the head of a penal colony run by Russian authorities in\nUkraine had replied that he was unable to intervene, as the units “were under\nMoscow’s command”.\nOrders or tolerance of torture"},{"id":"a-79-549-p0063","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"63","seq":66,"section":"1. Torture","text":"The Commission notes that the testimonies it has collected provide examples of\nsituations in which the leadership of detention facilities or other higher-ranking\nRussian authorities have ordered, encouraged, tolerated or taken no action to stop\ntorture or ill-treatment. On various occasions, the personnel of the facilities have\nmentioned orders to inflict such treatment."},{"id":"a-79-549-p0064","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"64","seq":67,"section":"1. Torture","text":"At several different detention facilities, former detainees noted the presence of\nthe leadership when severe beatings had taken place. A former detainee at a penal\ncolony in Ukraine described the arrival of a penitentiary official from the Russian\nFederation who had introduced himself to the detainees stating, “I broke everyone\nand will do the same to you”. At the same colony, a former detainee had witnessed a\nconversation between the head of the colony and another superior, who had bragged\nthat he had shared with military correspondents a humiliating photograph of a\ndetained Ukrainian officer. The head of colony had told the other superior, “He was\nbrought to you. You work on him”. 23 Several witnesses testified that the Ukrainian\nofficer had been tortured at the colony. In the Russian Federation, a former detainee\ntestified that he had overheard how, in a neighbouring cell, the head of colony had\nordered a detainee to put his hand against the wall and had instructed the personnel\nof the facility to “break it”. The screams of the detainee had followed. The official\nhad clarified that this had been punishment for breaking the rules."},{"id":"a-79-549-p0065","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"65","seq":68,"section":"1. Torture","text":"Orders to torture were mentioned or implied in various testimonies concerning\ndifferent detention facilities in the Russian Federation. For instance, a former detainee\nheard how regular personnel had told members of the special purpose units, “The\nadministration said to make the showers tougher”; consequently, the units had taken\nthe detainees into the shower, beaten them and subjected them to electric shocks. A\nformer detainee at a different detention facility quoted a member of personnel as saying,\n“We are sorry for causing so much pain, but we don’t have any other choice; we have\nto obey the orders”. A former detainee at another facility noted that an officer had\nmade reference to torture “according to the approved programme” when speaking to\nthe detainees. A former detainee at yet another detention facility stated that members\nof a specific rotation of the special purpose units that had been exceptionally lenient\nhad told detainees “Scream louder, we have orders from above; they need to hear how\nwe work”. At a detention facility in Ukraine, when detainees had questioned the\nreason for the beatings, a member of a special purpose unit replied, “This is our job”.\nDivision of labour during interrogations"},{"id":"a-79-549-p0066","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"66","seq":69,"section":"1. Torture","text":"Personnel of the Federal Security Service of the Russian Federation were in\ncharge of interrogations, held in the presence of the regular personnel and special\npurpose units of the Federal Penitentiary Service. Former detainees described the\ncoordinated actions of those Services concerning the treatment of detainees during\ninterrogations, under the authority of the Federal Security Service. Torture was\nusually carried out by personnel of the Federal Penitentiary Service, most often by\nspecial purpose units. One former detainee recounted that Federal Security Service\nagents had accused him of lying during interrogation, following which detention\npersonnel had inflicted torture on him. Another former detainee stated that his\ninterrogator had told members of the special purpose units, “Have a conversation with\nhim”, after which they had beaten the detainee. Former detainees also reported that\npersonnel of detention facilities had “prepared” them for interrogations, which\ninvolved torture, or had beaten them on the way to interrogations."},{"id":"a-79-549-p0067","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"67","seq":70,"section":"1. Torture","text":"Other services of the Russian Federation, including the Investigative Committee\nor the Office of the Prosecutor, have visited facilities to interrogate detainees. Most\nformer detainees reported that interrogations would be without violence in the\npresence of those services. Some former detainees, however, stated that members of\nthe Investigative Committee had ordered the personnel of detention facilities to\ntorture them when they were not satisfied with their answers, and at times had\nparticipated in torture themselves.\n(g)        Perpetrating entities in other detention locations in areas under Russian control\nin Ukraine"},{"id":"a-79-549-p0068","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"68","seq":71,"section":"1. Torture","text":"In its previous reports, the Commission found that, in the first few weeks after\nthe Russian invasion, torture had been mainly perpetrated by Russian armed forces.\nIn areas that Russian authorities controlled for longer periods, a combination of\nservices of the Russian Federation had been deployed in detention facilities, including\nthe Federal Security Service. Those services and forces had been jointly involved in\nthe commission of torture. 24 In interviews with the Commission, several former\nRussian soldiers stated that the interrogations of detained Ukrainian civilians or\nsoldiers had been led by security personnel operating either within the Russian armed\nforces units or jointly with them."},{"id":"a-79-549-p0069","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"69","seq":72,"section":"1. Torture","text":"The Commission interviewed a former Russian officer who, among other tasks,\nhad distributed ideological material to several hundred soldiers. He indicated that\nsuch material had reflected Russian official narratives, for instance, that “The goal is\nto de-Nazify and demilitarize Ukraine”, and that “Russia is not fighting against\nUkrainians, but against Nazis”. He noted that some soldiers had been motivated by\nthe propaganda and had volunteered to go to Ukraine “to kill Nazis”. The interlocutor\nand two other former Russian soldiers shared with the Commission examples of\nbrochures distributed to soldiers ahead of or during deployment to Ukraine, which\nincluded statements concerning the “de-Nazification” of Ukraine. One of the brochures,\ndated 12 December 2022 and entitled “Practical recommendations to the participant\nin combat actions”, had appeared on website of the Ministry of Defence of the Russian\nFederation. Under the heading “Who are Ukrainians?”, it mentions, “Someday, after\nde-Nazification, they will become Russians again, but for now they are enemies.\nCruel and treacherous. This means that we need to beat (“бить”) them until they put\ntheir hands up, without stopping, until our victory”. A Russian media outlet stated\nthat the brochure had been recommended to be distributed among recruiting stations. 25\nThe text, which appears to have been endorsed for wide distribution by the\nGovernment of the Russian Federation, may have fomented hatred and incited\nviolence against Ukrainian nationals. In the documented cases, perpetrators regularly\ncalled the detainees “Nazis” while inflicting torture. The Commission has reviewed\nnumerous other declarations by Russian authorities and public figures that used\ndehumanizing language, incited hatred and called for violence, and were circulated\nwidely in the context of the full-scale invasion of Ukraine."},{"id":"a-79-549-p0070","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"70","seq":73,"section":"1. Torture","text":"Testimonies recorded by the Commission showed instances where Russian\narmed forces officers had been involved directly in torture or had been aware that\ntorture was committed. A former Russian soldier stated that he had been assigned to\na local “commandant’s office” in Kherson Province, during his deployment to\nUkraine. He had witnessed how soldiers had beaten detainees and a Russian armed\nforces major had threatened two civilians with executions, while pointing his pistol\nat them, to force confessions. He noted that the soldiers had been driven by a feeling\nof power and impunity. The commander had been well aware of this situation, as he\nhad visited that office on several occasions. A Ukrainian prisoner of war recounted\nthat, during his detention, a lieutenant colonel had interrogated, beaten and subjected\nhim to electric shocks, while blaming him for killing civilians in Donetsk Province.\nA colonel had entered the premise, witnessed the beatings but left without intervening.\n(h)        A common practice"},{"id":"a-79-549-p0071","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"71","seq":74,"section":"1. Torture","text":"In addition to the wide array of cases documented in the context of the full-scale\ninvasion of Ukraine by the Russian Federation since 2022, numerous organizations\nhave documented torture and ill-treatment practised in the Russian Federation,\nnotably within its prison system. 26 Scores of complaints have been filed against the\nFederal Penitentiary Service and its personnel. In 2021 and 2022, Russian authorities\nalso acknowledged that the situation in detention facilities was a source of concern. 27\n(i)        Concluding observations"},{"id":"a-79-549-p0072","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"72","seq":75,"section":"1. Torture","text":"Since its appointment, the Commission has accumulated a body of evidence\nconcerning torture as a war crime and the corresponding violation of human rights\ncommitted by Russian authorities. In its documented cases, the victims of torture have\nbeen civilians and prisoners of war; the majority have been civilians. Torture has been\nprevalent during confinement. Victims have described treatment that has inflicted\nconsiderable pain and suffering, with often irreparable, long-term mental and physical\nharm. Consistent methods and harsh treatment used by Russian authorities have\ndemonstrated a blatant disregard for physical integrity and human dignity."},{"id":"a-79-549-p0073","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"73","seq":76,"section":"1. Torture","text":"The Commission has considered whether the acts documented amount to crimes\nagainst humanity. Crimes against humanity are enumerated acts that are committed\nas part of a widespread or systematic attack directed against any civilian population,\nwith knowledge of the attack, and pursuant to or in furtherance of a State or\norganizational policy. 28 The policy element requires that the State or organization\nactively promote or encourage such an attack. 29"},{"id":"a-79-549-p0074","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"74","seq":77,"section":"1. Torture","text":"The Commission has previously established that torture committed by Russian\nauthorities in the context of the armed conflict in Ukraine has been widespread and\nsystematic. Investigations during its third mandate have strengthened those findings.\nThe Commission has documented cases of torture in all provinces of Ukraine where\nRussian authorities have taken control of areas, whether briefly or for longer periods\nof time, and in the detention facilities it investigated in the Russian Federation. The\nspan of locations where torture has been committed confirms that it has been\nwidespread."},{"id":"a-79-549-p0075","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"75","seq":78,"section":"1. Torture","text":"The Commission has identified several shared patterns in the way in which\ntorture has been committed, reinforcing that it has been systematic (see para. 34).\nDuring the current mandate, it has documented additional common elements, notably\nconcerning violent practices used in official detention facilities in the Russian\nFederation, which have been transposed to such facilities in areas under Russian control\nin Ukraine. Other common elements concern the recurrent use of sexual violence as\na form of torture in all types of detention facilities investigated and the general\nabsence or denial of medical assistance in a context in which torture is committed."},{"id":"a-79-549-p0076","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"76","seq":79,"section":"1. Torture","text":"The evidence collected further demonstrates that Russian authorities have\ndeployed specific services and security forces from the Russian Federation to various\ndetention facilities in areas they controlled in Ukraine. Locally recruited personnel have\nworked under their authority. Those services and forces have acted in a coordinated\nmanner and according to a specific division of labour in the commission of torture."},{"id":"a-79-549-p0077","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"77","seq":80,"section":"1. Torture","text":"Victims and witnesses have made multiple references to the involvement of\nhigh-ranking detention facility officials, as well as to orders received by lower-ranking\npersonnel. Torture has been committed openly, with an apparent sense of impunity."},{"id":"a-79-549-p0078","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"78","seq":81,"section":"1. Torture","text":"These elements, combined, lead the Commission to consider that it has\nsufficient evidence to determine that the Russian authorities have acted pursuant to a\ncoordinated State policy to torture Ukrainian civilians and prisoners of war. The\nCommission therefore concludes that Russian authorities have committed crimes\nagainst humanity of torture in the context of their full-scale invasion of Ukraine."},{"id":"a-79-549-p0079","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"79","seq":82,"section":"2. Sexual and gender-based violence","text":"The Commission has documented new cases of sexual violence committed by\nRussian authorities in areas under their control. These violations and crimes were\ncommitted in similar circumstances, as highlighted by the Commission in its previous\nreports, during confinement and in the context of forced house searches.\n(a)   Sexual violence committed during confinement"},{"id":"a-79-549-p0080","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"80","seq":83,"section":"2. Sexual and gender-based violence","text":"The Commission has described above general patterns of sexual violence used\nas a form of torture during detention (see paras. 47–49) and has documented\nindividual cases, which it outlines in the present section. In those cases, the\nCommission has found that the war crime of sexual violence, which also amounted to\ntorture, was committed. In addition, it has found that the war crime of torture was\ncommitted. In each case, sexual violence was used, as a form of torture, to extract\ninformation from the victims or to punish them. All victims were men, both civilians\nand prisoners of war. The victims stated that the perpetrators had belonged to Russian\narmed forces or had been personnel of detention facilities operating under Russian\nauthorities. Two victims stated that the perpetrators had acted as if they had expertise\nin inflicting suffering. Three of the cases occurred in the same detention facility in\nKherson city, Kherson Province."},{"id":"a-79-549-p0081","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"81","seq":84,"section":"2. Sexual and gender-based violence","text":"In May 2022, in the Olenivka colony, as part of the torture of a young Ukrainian\nprisoner of war, personnel of the Federal Penitentiary Service and of the former so -\ncalled Donetsk People’s Republic inflicted burns on the man’s perineal area. He\nendured particular harsh treatment because he had held the rank of officer."},{"id":"a-79-549-p0082","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"82","seq":85,"section":"2. Sexual and gender-based violence","text":"In August 2022, in Kherson city, Russian soldiers confined a 33-year-old\ncivilian man in a detention facility for almost two weeks, accusing him of\n“pro-Ukrainian activism and organization of protests”. During interrogations,\nperpetrators administered electric shocks through wires connected to his genitals,\nstamped on his genitals, turned them with their hands and threatened to cut off his\ntesticles. During one session, perpetrators stripped the victim naked, ordered him to\nlie in a humiliating position, and brought in a man who, according to the victim, raped\nhim, using a pen. The perpetrators then took him back to his cell and left him naked\nfor 36 hours."},{"id":"a-79-549-p0083","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"83","seq":86,"section":"2. Sexual and gender-based violence","text":"In August 2022, in Kherson city, Russian soldiers confined a 49-year-old\ncivilian man in a detention facility, where they interrogated him about his affiliation\nwith Ukrainian authorities. The perpetrators subjected him to beatings and electric\nshocks with wires connected to his genitals, stripped him naked and attempted to rape\nhim with a rubber baton."},{"id":"a-79-549-p0084","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"84","seq":87,"section":"2. Sexual and gender-based violence","text":"In September 2022, in Kherson city, a Russian soldier and a man in civilian\nattire confined a man in a detention facility. During interrogation, perpetrators\nquestioned him about his loyalty to President Zelenskyy and subjected him to electric\nshocks with wires attached to his genitals. The victim was wet from having endured\nwaterboarding immediately before that."},{"id":"a-79-549-p0085","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"85","seq":88,"section":"2. Sexual and gender-based violence","text":"In addition to these cases, the Commission is investigating reports of sexual\nviolence in Kherson and Zaporizhzhia Provinces. All of the victims are civilian men\nin their early twenties or thirties and were subjected to torture committed during\nconfinement by Russian armed forces, to extract information. The victims were\nsubjected to, among other acts, threats of rape with an object and repeated electric\nshocks to the genitals. Another victim was forced to watch a video showing the\ncastration of a Ukrainian prisoner of war and threatened with the same.\n(b)   Sexual violence in the context of forced house searches"},{"id":"a-79-549-p0086","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"86","seq":89,"section":"2. Sexual and gender-based violence","text":"The Commission continued its investigation of cases in which victims had been\nsubjected to rape and sexual violence after Russian armed forces had broken into\nhomes in areas under their control. In recent cases, the victims have been women. The\nCommission found that the war crime of rape had been committed, which also\namounted to torture. The perpetrators were Russian soldiers, who had identified\nwomen in a vulnerable situation during one or several initial searches of their houses."},{"id":"a-79-549-p0087","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"87","seq":90,"section":"2. Sexual and gender-based violence","text":"In March 2022, in a village of Kyiv Province, after several searches of a house,\nRussian armed forces accused a 31-year-old woman living there of having suspicious\ncontent on her phone and directed her to come for interrogation. In a neighbouring\nhouse, one of the soldiers ordered her to undress, said that he was not interested in\nher phone and raped her. He raped her again in the same way on another day.\nAfterwards, the woman did her best to conceal what had happened as she did not want\nto distress her family."},{"id":"a-79-549-p0088","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"88","seq":91,"section":"2. Sexual and gender-based violence","text":"In April 2022, in the city of Balakliia, Kharkiv Province, Russian armed forces\nconducted a house search and noticed that a 33-year-old woman was at home with her\n6-year-old daughter. One of the soldiers returned during the night and ordered the\nwoman to come with him. She refused. The man assaulted her on the kitchen table\nand raped her repeatedly, at gunpoint, over several hours."},{"id":"a-79-549-p0089","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"89","seq":92,"section":"2. Sexual and gender-based violence","text":"The Commission investigated two incidents in which women had been raped in\nthe Beryslav District of the Kherson Province. It had previously documented 10 other\ncases of rape in the same district. In April 2022, a Russian soldier came to the house\nof a 68-year-old woman, locked her 25-year-old son in a room, threatened her and\nraped her. She stated that she did not resist, as she feared for her son, who was of\nfighting age, and also did not want her son to know what had happened. In August\n2022, Russian soldiers conducted a search of a house where a 69-year-old woman\nlived alone. One soldier returned, hit the woman several times and raped her twice.\nThe victim did not report the case and did not consult a doctor, as she did not want to\nburden her son and grandson, who were both on the front line.\n(c)   Consequences for the victims"},{"id":"a-79-549-p0090","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"90","seq":93,"section":"2. Sexual and gender-based violence","text":"In addition to physical trauma, victims reported the grave psychological impact\nof the violations and difficulties reintegrating into their families and into society.\nOne man, who attempted to commit suicide in his cell after he had been subjected to\nsexual violence, stated, “I thought I just wouldn’t survive this and would go crazy. …\nI felt broken, completely destroyed and no longer a man”. Victims mentioned\nsuffering from memory loss, difficulties in communicating, resorting to drinking, and\nseparations from family members as consequences of their ordeals. Relatives of\nvictims also shared sentiments of anxiety and suffering.\nIII. Conclusions and recommendations"},{"id":"a-79-549-p0091","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"91","seq":94,"section":"2. Sexual and gender-based violence","text":"During its third mandate, the Commission has collected new evidence of\nviolations of international humanitarian law and international human rights law,\nas well as crimes, committed by Russian authorities. Frequent blackouts caused\nby massive waves of attacks by the Russian Federation against the energy-related\ninfrastructure of Ukraine have curtailed aspects of the enjoyment of the rights\nto health and to education, particularly for certain categories of persons. This is\nlikely to worsen during the colder months. Also, the continued attacks with\nexplosive weapons has led to civilian casualties, damage and destruction."},{"id":"a-79-549-p0092","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"92","seq":95,"section":"2. Sexual and gender-based violence","text":"In its previous reports, the Commission found widespread and systematic\nuse of torture by Russian authorities against civilians and prisoners of war. It\nhas now established that torture has been committed in all provinces of Ukraine\nwhere Russian authorities have taken control of areas and in detention facilities\nin the Russian Federation. The Commission has documented new common\nelements in the way in which torture has been committed. They include the\ntransposition of violent practices used in official detention facilities in the\nRussian Federation to such facilities in areas under Russian control in Ukraine.\nOther common elements concern the recurrent use of sexual violence as a form\nof torture in detention facilities and the general absence or denial of medical\nassistance in a context in which torture is committed."},{"id":"a-79-549-p0093","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"93","seq":96,"section":"2. Sexual and gender-based violence","text":"Evidence demonstrates that services from the Russian Federation have\nbeen deployed to detention facilities held by Russian authorities in Ukraine, who\nhave acted in a coordinated manner and according to a division of labour in the\ncommission of torture. Testimonies also illustrate orders of superiors and a\nprevailing sense of impunity among perpetrators."},{"id":"a-79-549-p0094","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"94","seq":97,"section":"2. Sexual and gender-based violence","text":"The conjunction of these elements has led the Commission to conclude that\nRussian authorities have acted pursuant to a policy encouraging torture against\ncivilians and prisoners of war and have thereby committed torture as a crime\nagainst humanity."},{"id":"a-79-549-p0095","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"95","seq":98,"section":"2. Sexual and gender-based violence","text":"The victims have described physical pain and trauma, with long-term\ncomplications, including disability. They have emphasized their immense\npsychological challenges, with recurrent nightmares, anxiety, difficulties in\ncommunicating, including with family members, at times leading to separations,\nand challenges in reintegrating into society. They have conveyed their constant\nfear of being detained again and of being subjected to the same ordeal."},{"id":"a-79-549-p0096","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"96","seq":99,"section":"2. Sexual and gender-based violence","text":"In its reports, the Commission has emphasized the importance of all forms\nof accountability. Regarding criminal accountability, identifying and\nprosecuting perpetrators of crimes is key to ending the culture of impunity.\nVictims and their families have stressed this as an essential part of their sense of\njustice. The wife of a civilian man who was a victim of torture and sexual violence\nrecounted how he had struggled to cope after his release. She “urged all\nperpetrators to be held accountable and tried according to the law”,\nacknowledging that “it wouldn’t bring [her] husband back, but might provide\nsome solace”."},{"id":"a-79-549-p0097","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"97","seq":100,"section":"2. Sexual and gender-based violence","text":"The recommendations made by the Commission in its previous reports\nremain relevant. The Commission sets out below specific recommendations to\naddress issues developed in the present report."},{"id":"a-79-549-p0098","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"98","seq":101,"section":"2. Sexual and gender-based violence","text":"The Commission recommends that the Russian Federation immediately:\n(a) Cease aggression and all acts of violence committed against civilians\nand prisoners of war in violation of international human rights law and\ninternational humanitarian law;\n(b) End the use of torture and other forms of ill-treatment against\ncivilians and prisoners of war;\n(c) Take the measures necessary to prevent sexual and gender-based\nviolence."},{"id":"a-79-549-p0099","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"99","seq":102,"section":"2. Sexual and gender-based violence","text":"The Commission recommends that the Russian Federation:\n(a) Ensure that all perpetrators, in particular commanders and other\nsuperiors and those ordering, soliciting or inducing the commission of\ninternational crimes, are held accountable in accordance with international law;\n(b) Take the measures necessary to prevent the commission of such\nviolations and crimes, in particular through unequivocal instructions to all\nbranches of the armed forces, the Federal Security Service and the Federal\nPenitentiary Service, with a view to ensuring that discipline and respect for\ninternational human rights law and international humanitarian law are upheld,\nalong with the principle of superior responsibility;\n(c)   Cooperate fully with all international monitoring and investigative\nbodies;\n(d) Take all feasible precautions to protect civilians and civilian\ninfrastructure and end attacks against energy-related infrastructure in Ukraine."},{"id":"a-79-549-p0100","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":"100","seq":103,"section":"2. Sexual and gender-based violence","text":"The Commission recommends that Ukraine:\n(a) Comprehensively address mental health and psychosocial needs\nresulting from the armed conflict;\n(b) Continue building capacity for gender-sensitive and survivor-centred\nlegal processes of accountability and provide reparative justice, including\nmedical and psychosocial support, to all victims;\n(c) Keep up efforts to mitigate the effects of the damage caused by the\nattacks on the energy infrastructure by means of emergency measures and the\ncontinuation of innovative longer-term policies to diversify and decentralize\nenergy production, taking due account of the specific needs of vulnerable groups,\nin particular children, older persons, persons with disabilities and internally\ndisplaced persons."},{"id":"a-79-549-u0104","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":104,"section":"Annex","text":"Detention facilities in areas that were under Russian Federation\ncontrol in Ukraine and in the Russian Federation\nThe list below enumerates the detention facilities held by Russian authorities\nwhere the Commission has confirmed the use of torture through investigations since\nits appointment. Additional detention facilities are under investigation.","unnumbered":true},{"id":"a-79-549-u0105","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":105,"section":"Annex","text":"Detention facilities in areas under Russian Federation control\nin Ukraine\nKherson Province\n• Pretrial detention centre No. 2, Chonhar village\n• Temporary detention centre, Kherson city\n• Police department, Nova Kakhovka city\n• Temporary detention centre, Hola Prystan city\n• School (makeshift facility), Biliaivka village\n• Sanatorium (makeshift facility), Hola Prystan city","unnumbered":true},{"id":"a-79-549-u0106","rec_id":"rec1uYjjr0orynFeu","symbol":"A/79/549","n":null,"seq":106,"section":"Annex","text":"Zaporizhzhia Province\n• Correctional colony No. 77 (also known as Prymorsk colony No. 145),\nBerdiansk city\n• Police department, Berdiansk city\n• Police department, Enerhodar city\n• Police department, Melitopol city\n• District police, Vasylivka town","unnumbered":true},{"id":"a-hrc-58-67-u0000","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":null,"seq":0,"section":null,"text":"Summary\nIn its third mandate report to the Human Rights Council, the Independent\nInternational Commission of Inquiry on Ukraine continued to document grave violations of\ninternational human rights law and international humanitarian law, and corresponding\ncrimes, in the context of the Russian Federation’s armed aggression against Ukraine.\nThe Commission has concluded that Russian authorities committed enforced\ndisappearances and torture as crimes against humanity. Both were perpetrated as part of a\nwidespread and systematic attack against the civilian population and pursuant to a\ncoordinated state policy.\nIn areas that came under their control, Russian authorities detained large numbers of\ncivilians whom they perceived as a threat to their military objectives in Ukraine. They\ntransferred many of them to multiple detention facilities in areas they occupied in Ukraine\nor deported them to the Russian Federation, where they subjected them to additional\nviolations and crimes. Various Russian entities have systematically failed to communicate\nthe fate or whereabouts of those detained, leaving families in agonizing anguish. Many\ndisappearances have lasted for months and years; some of the victims died.\nIn detention facilities in Russian-occupied areas in Ukraine and in the Russian\nFederation, Russian authorities have systematically used torture against certain categories of\ndetainees to extract information, coerce, and intimidate. The most brutal forms of torture\nwere used during interrogations, which were often led by the Federal Security Service and\nthe Investigative Committee of the Russian Federation. The evidence shows that when\nFederal Security Service personnel were present in detention facilities, they exercised the\nhighest authority compared to all other services and forces, including heads of facilities, and\ngave orders.\nRussian authorities have systematically used sexual violence as a form of torture\nagainst male detainees. This report details additional cases of war crimes of rape and sexual\nviolence, committed as a form of torture, against female detainees.\nThe Commission examined a growing number of incidents concerning the killing or\nwounding by Russian armed forces of Ukrainian soldiers who were captured or attempted to","unnumbered":true},{"id":"a-hrc-58-67-u0001","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":null,"seq":1,"section":null,"text":"* The present report was submitted to the conference services for processing after the deadline so as to\ninclude the most recent information.\n** The annexes to the present document are reproduced as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-58-67-u0002","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":null,"seq":2,"section":null,"text":"surrender, which constitutes a war crime. Testimonies of soldiers who deserted from the\nRussian armed forces show multiple situations where commanders gave orders not to take\nprisoners but kill them instead, which indicates that they have acted pursuant to a policy to\nkill surrendering or captured soldiers, in violation of international humanitarian law.\nFurther, both parties to the armed conflict committed a war crime by killing or\nwounding injured soldiers, who were thus hors de combat, using drones.\nThe report also describes some violations of human rights law committed by\nUkrainian authorities against persons they accused of collaboration with Russian authorities.\nAfter three years of armed conflict, the profound scars left on the victims are\nincreasingly visible. Many have endured a combination of violations and crimes, in addition\nto other consequences of the armed conflict. They view the physical and psychological harm\ncaused to them, their families and their communities, as irreparable. The redress,\naccountability, rehabilitation, reparation, and reintegration in society, to which they are\nentitled, is particularly complex. In this context, the Commission underscores again the need\nfor justice to be done and to ensure that perpetrators of violations and crimes are held to\naccount.","unnumbered":true},{"id":"a-hrc-58-67-p0001","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"1","seq":3,"section":"I. Introduction","text":"The Independent International Commission of Inquiry on Ukraine submits its report\nto the Human Rights Council, at its fifty-eighth session, pursuant to resolution 55/23.1 The\npresent comprehensive report reflects the Commission’s findings of its third mandate and is\nto be read in conjunction with its October 2024 report to the General Assembly.2 The\nCommission is composed of Erik Møse (Chair), Pablo de Greiff, and Vrinda Grover."},{"id":"a-hrc-58-67-p0002","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"2","seq":4,"section":"I. Introduction","text":"The principles of independence, impartiality, objectivity, integrity, as well as a victim-\ncentered approach guide all aspects of the Commission’s work.3"},{"id":"a-hrc-58-67-p0003","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"3","seq":5,"section":"I. Introduction","text":"Since its establishment, the Commission has interviewed 929 women and 851 men,\nexamined documents, expert and forensic reports, photographs, and videos. During the\ncurrent mandate, the liquidity crisis at the United Nations has severely affected the\nstaffing of the secretariat of the Commission and its ability to travel. It has been able to\ncontinue its investigations relying on limited travel, as well as remote interviews, while\nmaintaining its usual standard of proof."},{"id":"a-hrc-58-67-p0004","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"4","seq":6,"section":"I. Introduction","text":"The Commission extends its deep gratitude to victims and witnesses for sharing\nexperiences, and to organizations, for the information provided."},{"id":"a-hrc-58-67-p0005","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"5","seq":7,"section":"I. Introduction","text":"It appreciates the cooperation of the Government of Ukraine. The Russian Federation\ncontinued not to recognise the Commission and 31 written requests for access, information,\nand meetings remained unanswered."},{"id":"a-hrc-58-67-p0006","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"6","seq":8,"section":"II. Violations of international law","text":"Three years of armed conflict in Ukraine have led to over 12,654 civilians killed and\nover 29,392 injured as of 24 February 2024, according to the Office of the High\nCommissioner for Human Rights (OHCHR). The actual number of casualties is likely\nconsiderably higher. The toll on civilian lives has been devastating. The Commission has\ncontinued to document a wide array of violations of international human rights law and\ninternational humanitarian law, as well as corresponding crimes, committed by Russian\nauthorities in the framework of their full-scale invasion of Ukraine. This report focuses on\nenforced disappearances, torture, rape and sexual violence, and the killing or wounding of\nsoldiers hors de combat."},{"id":"a-hrc-58-67-p0007","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"7","seq":9,"section":"II. Violations of international law","text":"The Commission’s most important findings during its third mandate are that Russian\nauthorities have committed crimes against humanity of torture and enforced disappearances.\nBoth crimes were perpetrated pursuant to a coordinated state policy, in a widespread and\nsystematic manner, in all provinces of Ukraine where areas came under Russian control, and\nwith the aim of furthering the Russian Federations’ military objectives. In the commission of\nthe crimes, Russian authorities have targeted categories of persons whom they perceived as\na threat or who refused to cooperate with them."},{"id":"a-hrc-58-67-p0008","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"8","seq":10,"section":"1. Overview","text":"Large numbers of civilians and military personnel have disappeared since the outset\nof the Russian Federation’s full-scale invasion of Ukraine in 2022.4 The Commission\npreviously highlighted a pattern of widespread unlawful confinement in areas that came\nunder the control of Russian authorities, often followed by deportations or transfers, with\nmany reported missing.5 It has examined in detail and corroborated a sample amounting to\nalmost 100 cases in which Russian authorities have committed enforced disappearances, on\na widespread scale, in all areas that came under their control in Ukraine (see map in annex\n1). Many persons have been missing for months, or years. Some have died. The Commission\nhas concluded that Russian authorities committed enforced disappearances as crimes against\nhumanity."},{"id":"a-hrc-58-67-p0009","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"9","seq":11,"section":"1. Overview","text":"As they took control of localities in Ukraine, Russian authorities detained numerous\ncivilians, including local authorities, civil servants, journalists, and persons expressing pro-\nUkrainian views, during comprehensive searches of houses and public spaces. Most victims\nwere civilian men of fighting age. They held them for indefinite periods of time, and further\ntransferred many of them to well-established, official detention facilities in Russian-occupied\nareas of Ukraine, or deported them to the Russian Federation. In most cases, the authorities\ncarrying out the detentions and a wide range of Russian entities systematically refused to\ndisclose the whereabouts of those missing when contacted by the families."},{"id":"a-hrc-58-67-p0010","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"10","seq":12,"section":"1. Overview","text":"Consequently, many families remained without information on their loved ones. They\ndescribed the anguish of seeing them being taken away and not receiving even basic\ninformation about them. Considerable efforts to locate those disappeared at the local level,\nas well as appeals to various institutions in the Russian Federation, involved risks to their\npersonal safety and costs. Their searches mostly led to incomplete information received\nmonths or years after the initial detention, or no information at all."},{"id":"a-hrc-58-67-p0011","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"11","seq":13,"section":"1. Overview","text":"The Commission has analyzed over 280 letters from various entities of the Russian\nFederation in response to inquiries by the families. The majority provided no information on\nthe fate or whereabouts of the disappeared. Some response letters from the Ministry of\nDefense of the Russian Federation acknowledged the detention of the victims, but failed to\ndisclose information on their whereabouts, invoking confidentiality."},{"id":"a-hrc-58-67-p0012","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"12","seq":14,"section":"1. Overview","text":"An enforced disappearance is a continuing violation, lasting as long as the fate and\nwhereabouts of the victim remain undetermined. At the time of writing this report, many\nwere still missing. The systematic refusal to disclose information about those who\ndisappeared placed them outside of the protection of the law and exposed them to risks of\nadditional violations and crimes."},{"id":"a-hrc-58-67-p0013","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"13","seq":15,"section":"1. Overview","text":"Some victims have died during their enforced disappearance. Even then, Russian\nauthorities failed to provide information to the families at the time of death. In a well-known\ncase, 27-year-old Ukrainian journalist Viktoriia Roshchyna disappeared in August 2023,\nduring a visit to Russian-occupied areas of Zaporizhzhia Province. After multiple inquiries,\nher family received a response from the Russian Federation’s Ministry of Defense with the\nfirst acknowledgement of her detention in the Russian Federation in April 2024, but without\ndetails on her whereabouts. In October 2024, in response to further inquiries, the Ministry of\nDefense sent a new letter stating that Roshchyna had died a month earlier, without any other\nexplanation. At the time of writing this report, the family has received neither information on\nthe cause of death, nor her remains."},{"id":"a-hrc-58-67-p0014","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"14","seq":16,"section":"1. Overview","text":"In another case, Yevhenii Matveev, former mayor of Dniprorudne city, in\nZaporizhzhia Province, disappeared in March 2022, after having been detained by Russian\nauthorities. Regardless of multiple inquiries, his family did not receive any information from\nthem on his fate or whereabouts. Former detainees attested to his presence in at least two\nRussian detention facilities. In 2023, Ukrainian authorities were able to confirm his detention\nin the Russian Federation. The family received a handwritten letter from him a year later.\nWithout further news, in November 2024, the family was informed by Ukrainian authorities\nthat the victim’s dead body had been returned from the Russian Federation as part of an\nexchange. The death certificate stated that the victim died due to a “closed blunt injury to the\ntorso with multiple fracture of the skeletal bones”. The Commission has documented other\ncases in which victims of enforced disappearances have been executed, died or are presumed\ndead."},{"id":"a-hrc-58-67-p0015","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"15","seq":17,"section":"2. Prolonged detentions, victims placed outside of the protection of the law","text":"Mainly during the initial stages of their operations in various Ukrainian localities, but\nalso later, Russian authorities detained a broad category of civilians during searches of\nhouses, public buildings, and verifications at checkpoints and filtration points. Persons\ntargeted include current and former local authorities, civil servants, law enforcement\npersonnel, journalists, persons whom they suspected of supporting the Ukrainian armed\nforces or authorities, or who are related to them, those who expressed pro-Ukrainian views,\nand volunteers helping civilians amid ongoing hostilities."},{"id":"a-hrc-58-67-p0016","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"16","seq":18,"section":"2. Prolonged detentions, victims placed outside of the protection of the law","text":"Families described the anguish of seeing their loved ones being detained by Russian\nsoldiers, without knowing the reason, where they would be held, and how they would be\ntreated. For instance, in March 2022, as Russian armed forces occupied a village in Kyiv\nProvince, they searched houses and detained a man and his 20-year-old son. The wife and\nmother of the victims cried, pleading for an explanation, ran after the military vehicle that\ntook them away, implored the soldiers to release them, or to share some information with\nher, but they ignored her. She has not seen them since that day, nor received any information\nabout their whereabouts. In another case, during a house search that occurred around the same\ntime and in the same province, Russian soldiers detained a man and his adult son, a journalist,\nin a local makeshift detention facility. After a few days, a Russian soldier took the son away.\nWhen his father asked where he was taking him, the soldier responded, “when the war is\nover, your son will come back”. The family has received no information about his\nwhereabouts since then."},{"id":"a-hrc-58-67-p0017","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"17","seq":19,"section":"2. Prolonged detentions, victims placed outside of the protection of the law","text":"Many of the victims were men who stayed behind in operational areas, to continue\ntheir work and take care of their properties, while women and children had fled. Families\nrecounted how they lost telephone contact with their loved ones, subsequently to learn from\nneighbours that they had been detained. They were forced to carry out complicated searches\nfrom afar, relying on indirect and scarce information, while fearing that their efforts may\ncomplicate their situation. The wife of one man who disappeared in an area marked by\nhostilities, explained, “I feared that if the Russians found out that someone was searching for\nhim, they might retaliate. […] It felt like a game of roulette - you never know if your efforts\nwill improve or worsen the situation for your loved ones in captivity.”"},{"id":"a-hrc-58-67-p0018","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"18","seq":20,"section":"2. Prolonged detentions, victims placed outside of the protection of the law","text":"Victims have disappeared for prolonged periods of time. From the abovementioned\nsample of verified cases (see para. 8), more than half of the disappearances have lasted for\nover two years. Russian authorities further transferred many of the victims to detention\nfacilities in Russian-occupied areas of Ukraine or deported them to the Russian Federation.\nIn some cases, multiple transfers between various Russian-held detention facilities followed.\nTransfers and deportations of civilians are war crimes. Moreover, Russian authorities\ncommitted additional violations and crimes against victims of enforced disappearances,\nincluding wilful killings, torture, sexual violence, and forced labour."},{"id":"a-hrc-58-67-p0019","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"19","seq":21,"section":"3. Failure to provide information to the families","text":"The initial detentions were mainly carried out by locally deployed Russian armed\nforces, but also by the Federal Security Service of the Russian Federation (referred to as\n“FSB” in Russian). They confined them in various detention facilities held by Russian\nauthorities in occupied areas of Ukraine and transferred or deported many of them to well-\nestablished, official detention facilities run by the Federal Penitentiary Service of the Russian\nFederation (referred to as “FSIN” in Russian). At the highest level, the Ministry of Defense\nof the Russian Federation was the competent authority that addressed requests concerning\nmissing persons (see para. 26).6"},{"id":"a-hrc-58-67-p0020","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"20","seq":22,"section":"3. Failure to provide information to the families","text":"Russian authorities systematically failed to inform the families on the fate and\nwhereabouts of those they were detaining. Various civil and military authorities based in\noccupied areas generally dismissed requests for information, referred families to other\nservices, who dismissed them again, and at times provided erroneous or contradictory\ninformation. Moreover, in a case where a local Ukrainian official was missing and his relative\nwent to inquire about his whereabouts at the Russian commandant’s office, an officer of the\nFederal Security Service told her, “If you are here to negotiate your uncle’s release, you are\nwasting your time, as your uncle was a local official and might be useful to us”."},{"id":"a-hrc-58-67-p0021","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"21","seq":23,"section":"3. Failure to provide information to the families","text":"Multiple transfers of the victims to different detention facilities in occupied areas or\nin the Russian Federation made searches by families particularly complicated. In the absence\nof official responses, families relied on information they could obtain from released\ndetainees. At times, they managed to confirm the presence of the victim in one facility but\nsubsequently discovered that the person was no longer there and were forced to reinitiate\ntheir search. In the case of a Ukrainian local official who had disappeared in June 2022,\nformer detainees released from six different detention facilities informed the family that they\nhad been detained with him at a certain period in time. Russian authorities have not\ncommunicated his whereabouts to the family."},{"id":"a-hrc-58-67-p0022","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"22","seq":24,"section":"3. Failure to provide information to the families","text":"The Commission has documented cases where Russian authorities not only failed to\ninform families of those disappeared, but also concealed the whereabouts of the victims and\nsubjected them to further violations and crimes. Starting in late 2022, Russian authorities\ntransferred several civilians they had detained to a military base in Verkhnia Krynytsia\nvillage, Zaporizhzhia Province. According to testimonies, with respect to at least five such\nformer detainees, perpetrators first staged a transfer to areas under Ukrainian Government\ncontrol, which they filmed or photographed. Instead, they transferred the victims to an\noperational area under their control, where they held them with over a dozen civilians, and\nforced them to dig trenches for hours, cook, and wash. Two of the victims were employees\nof the Zaporizhzhia Nuclear Power Plant, previously confined at their workplace. According\nto witnesses, after one of them started coughing blood, instead of providing medical care,\nRussian soldiers brought both employees of the plant to the trenches. They were never seen\nagain. Their families have not been able to trace them, despite multiple search efforts. The\nCommission determined that in these cases, in addition to enforced disappearances, Russian\nauthorities committed unlawful confinement and transfers as war crimes, endangered\ncivilians through forcing them to stay in an operational area, and subjected them to forced\nlabour, in violation of international humanitarian law.7"},{"id":"a-hrc-58-67-p0023","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"23","seq":25,"section":"3. Failure to provide information to the families","text":"As for the direct communication of detainees with their families, while some letters\nreached their destinations, others arrived with considerable delay, or never arrived. Former\ndetainees told the Commission that they were generally not allowed to contact their relatives\nand when this was permitted, they were instructed not to disclose the place of detention."},{"id":"a-hrc-58-67-p0024","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"24","seq":26,"section":"4. Response letters from the Russian authorities","text":"Many families sent written communications to a wide range of entities in Russian-\noccupied areas of Ukraine and in the Russian Federation to inquire about their loved ones,\nincluding security services, prosecutors’ offices, penitentiary institutions, and ministries. The\nCommission analyzed over 280 letters from various Russian authorities, none of which were\nsent on their initiative, but only in response to relatives’ requests for information. Most letters\nreached the families months or even years after the initial disappearances and provided\nincomplete or no information. Some lawsuits filed before Russian courts by relatives or\nlawyers of disappeared victims against the inaction of Russian authorities concerning their\nrepeated appeals, were rejected. The decisions of the courts used the same formulations as\nthe letters from the Ministry of Defense of the Russian Federation described below (see para.\n26)."},{"id":"a-hrc-58-67-p0025","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"25","seq":27,"section":"4. Response letters from the Russian authorities","text":"Response letters to families from the Federal Penitentiary Service, under whose\nauthority most victims were held, generally denied the presence of the disappeared persons\nin the detention facilities under their control, claiming not to have the competence, or\nredirected them to other services. Other institutions of the Russian Federation also largely\nfailed to provide relevant information to the families, some of them invoking lack of\ncompetence or confidentiality."},{"id":"a-hrc-58-67-p0026","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"26","seq":28,"section":"4. Response letters from the Russian authorities","text":"The Commission has analysed 50 replies to families from the Ministry of Defense of\nthe Russian Federation, the highest competent institution in this matter (see para. 19). Using\na standard formulation, some of the letters denied the detention of the disappeared persons in\nthe Russian Federation, noting that they are not on the lists of persons “detained for\ncountering the special military operation”. Other letters acknowledged that the victim was\ndetained in the Russian Federation. However, none of the reviewed letters from the Ministry\nof Defense revealed the whereabouts of the missing persons, many of them mentioning that\nthe detention location of individuals held for countering the special military operation is\nconfidential and cannot be disclosed to third parties. Many of these letters cite the Third\nGeneva Convention, which is not applicable to civilians but to prisoners of war. Depriving\ncivilians of their protected status is unlawful.8"},{"id":"a-hrc-58-67-p0027","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"27","seq":29,"section":"4. Response letters from the Russian authorities","text":"Some of the communications received from Russian authorities were inconsistent\nwith one another. For instance, in one letter, the Ministry of Defense of the Russian\nFederation denied the presence of a missing person on the above-mentioned lists,\ncontradicting information provided in three different letters by Russian authorities in\noccupied areas of Ukraine, confirming that person’s detention. In another case, the so-called\n“Ministry of Interior” of the occupied area of Kherson Province stated that a missing person\nwas detained in the Autonomous Republic of Crimea, which was denied by the so-called\n“Ministry of Interior” of Crimea one month later."},{"id":"a-hrc-58-67-p0028","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"28","seq":30,"section":"4. Response letters from the Russian authorities","text":"In rare cases, Russian authorities eventually informed the families about the\nwhereabouts of those disappeared, when charges or a conviction had been issued.\nNevertheless, even then, such information usually reached the families weeks or months after\nthe initial disappearance. The Russian authorities had thus committed the violation of\nenforced disappearance until the time they disclosed the fate and whereabouts of the victims\nto the family. However, after such official acknowledgement, some victims went missing\nagain."},{"id":"a-hrc-58-67-p0029","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"29","seq":31,"section":"5. Denial of the right to truth of the families","text":"The denial of information has violated the right to truth of the families of those\nmissing, who are recognized as victims of torture under international law. Families carried\nout considerable search efforts. Locally, they approached various Russian authorities\nstationed in occupied areas and visited different places of detention. They wrote multiple\nletters to different Russian authorities, hired lawyers, and some travelled to Russian-occupied\nareas in Ukraine or to the Russian Federation. They also appealed to Ukrainian authorities\nand non-governmental organizations. During their searches, families undertook significant\nrisks and expenses. In one case, a woman was subjected to heavy beatings and gang rape\nwhen she went to the local police to inquire about her relative (see para. 50). A young man\nwas detained and beaten when he went to a police office to inquire about his missing\ngirlfriend."},{"id":"a-hrc-58-67-p0030","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"30","seq":32,"section":"5. Denial of the right to truth of the families","text":"Regardless of their strenuous efforts, many families found no trace of their missing\nrelatives. They sent letters and parcels, often without knowing if they reached their loved\nones. They described this uncertainty as unbearable. The wife of a man who had been missing\nfor over two years, stated, “The despair is killing me. I don’t know what to do or how to help\nmy husband. There are so many other civilians detained. […] I don’t understand why the\nRussians keep them there.” The majority of missing victims being men, the cases highlight\nsome of the gendered dynamics and impact of enforced disappearances. Women often bore\nthe emotional and logistical burden of searching for missing male relatives, while navigating\ncomplex bureaucratic systems. The inability to visit some of the conflict-affected areas, poor\ncommunication infrastructure, and the proximity to active conflict further compounded these\nchallenges, leaving them isolated and reliant on hearsay to trace their loved ones. Moreover,\nthe missing men were often the main breadwinner of the family. Consequently, women had\nto single-handedly meet multiple challenges, manage the households, take care of children,\nwhile coping with limited resources and facing the hardships relating to the unfolding of the\narmed conflict."},{"id":"a-hrc-58-67-p0031","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"31","seq":33,"section":"6. Concluding observations","text":"The evidence demonstrates that Russian authorities have committed widespread\nenforced disappearances against large numbers of civilians and prisoners of war in the\ncontext of their full-scale invasion of Ukraine. They detained a broad category of civilians\nwhom they perceived as a threat to their military effort. Many of the victims have disappeared\nfor months and years and their fate and whereabouts remain unknown, leaving their families\nin agonizing uncertainty."},{"id":"a-hrc-58-67-p0032","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"32","seq":34,"section":"6. Concluding observations","text":"The cases documented by the Commission demonstrate the involvement of Russian\nauthorities at different levels. In areas that came under their control in Ukraine, the authorities\ncarrying out the initial detentions have systematically failed to provide information on the\nfate and whereabouts of those detained to the family members. Often, they transferred the\nvictims to multiple detention facilities in Russian-occupied areas in Ukraine or deported them\nto the Russian Federation. There, they subjected them to additional, grave violations and\ncrimes, notably torture and sexual violence. Many of those who disappeared in March 2022\nare still missing."},{"id":"a-hrc-58-67-p0033","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"33","seq":35,"section":"6. Concluding observations","text":"During all the stages of enforced disappearances, Russian authorities generally did not\ntake any steps to inform the families on the fate and whereabouts of the victims. Multiple\nresponse letters from different authorities also failed to provide such information. The\nMinistry of Defense of the Russian Federation, the competent authority in the matter, sent\nstandard response letters. While some of them denied the detention of the disappeared\npersons in the Russian Federation, other letters acknowledged their presence but refused to\nprovide any information on their whereabouts."},{"id":"a-hrc-58-67-p0034","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"34","seq":36,"section":"6. Concluding observations","text":"The widespread and systematic nature of the enforced disappearances; the sequenced\ninvolvement of various entities of the Russian Federation allocating and directing resources\nand efforts to detain large numbers of civilians in various facilities for prolonged periods of\ntime; the provision of standard responses to families, which systematically failed to\ncommunicate the fate or whereabouts of those disappeared during the three years of the armed\nconflict, point to a coordinated state policy. The failure to disclose the whereabouts of the\nvictims further shows the intention of the Russian authorities to deprive them of the\nprotection of the law."},{"id":"a-hrc-58-67-p0035","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"35","seq":37,"section":"6. Concluding observations","text":"The combination of these elements has led the Commission to conclude that Russian\nauthorities have committed enforced disappearances for a prolonged period of time as part of\na widespread and systematic attack against civilian populations, pursuant to a coordinated\npolicy, which amounts to a crime against humanity.9"},{"id":"a-hrc-58-67-p0036","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"36","seq":38,"section":"1. Overview","text":"Based on investigations carried out since its establishment, the Commission\nconcluded during its third mandate that Russian authorities have used torture pursuant to a\ncoordinated state policy and as crimes against humanity.10 They deployed personnel who\nacted in a coordinated manner and according to a division of labour in the commission of the\ncrimes. Regular personnel and special purpose units (referred to as ”Spetsnaz“ in Russian) of\nthe Federal Penitentiary Service were the main perpetrators of torture in well-established\ndetention facilities in Russian-occupied areas of Ukraine and in the Russian Federation,\nduring violent “admission procedures”, daily brutal practices and punishments, and\ninterrogations.11 Russian armed forces were the main perpetrators of torture in medium sized\nand makeshift detention facilities in Russian-occupied areas of Ukraine.12"},{"id":"a-hrc-58-67-p0037","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"37","seq":39,"section":"1. Overview","text":"In all investigated detention facilities, some of the most brutal forms of torture have\nbeen used during interrogations. These included severe beatings, electric shocks, burns,\nstrangling, suffocation, hanging, rape and other forms of sexual violence, as well as other\nacts. In addition to personnel running the detention facilities, the interrogations were often\nled by authorities referred to as “investigators” by former detainees. They were principally\n9   Rome Statute of the International Criminal Court, art. 7(1)(i) and 7(2)(i).\npersonnel from the Federal Security Service of the Russian Federation and, to a lesser extent,\nfrom the Investigative Committee of the Russian Federation. 13 The present report provides\nfurther information on the role of these services in the use of torture."},{"id":"a-hrc-58-67-p0038","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"38","seq":40,"section":"1. Overview","text":"As highlighted previously, perpetrators have targeted certain categories of civilians\nand prisoners of war.14 The Commission has documented new cases in which military\npersonnel from Mariupol who were captured by Russian armed forces, including members\nof the Azov brigade and associated personnel, were subjected to particularly harsh forms of\ntorture, including rape and sexual violence, as punishment, and to extract false confessions\nor testimonies implicating others. The Commission has updated the map of areas and the list\nof detention facilities where Russian authorities committed torture (see annex 2 and 3)."},{"id":"a-hrc-58-67-p0039","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"39","seq":41,"section":"2. Investigators’ involvement in torture","text":"The evidence gathered demonstrates that personnel of the Federal Security Service\nhave played a significant role in the systematic perpetration of torture in the context of\ndetention in Russian-occupied areas of Ukraine and in the Russian Federation. It has set up\noffices in occupied areas and carried out investigations concerning specific categories of\npersons, involving searches, arrests and interrogations accompanied by torture, and decisions\non their detention and release. According to multiple former detainees, when personnel of\nthe Federal Security Service were present in detention facilities, they exercised the highest\nauthority compared to all other services and forces, including heads of facilities, and gave\norders."},{"id":"a-hrc-58-67-p0040","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"40","seq":42,"section":"2. Investigators’ involvement in torture","text":"Victims’ accounts show that many of the initial arrests were carried out by personnel\nof the Federal Security Service, as they searched for specific persons or categories of persons,\nat their homes, during checks at filtration points, or in public places or buildings. In some\ncases, they immediately used torture or ill-treatment. For instance, a civilian woman whose\nbrother died fighting in the Ukrainian armed forces, recounted that in September 2023, in a\nvillage of Luhansk Province, a large group of Federal Security Service personnel stormed her\nhouse and informed her that she was under arrest. Without further explanation, they\nimmediately started beating her and took her away, blindfolded. During a subsequent\ninterrogation, the same group of Federal Security Service personnel administered electric\nshocks to her using a field phone, while asking questions about her connections with the\nUkrainian armed forces. Another young civilian woman stated that, in June 2022, four men\nintercepted her in a park in Berdiansk City, Zaporizhzhia Province, told her that they were\nfrom the Federal Security Service, and immediately started beating and kicking her, saying,\n“This is for what you did. You, bitch, were informing khokhols15 about the Russian armed\nforces’ positions, and our military bases.” They placed a bag over her head, dragged her to\ntheir vehicle, and brought her to a detention facility."},{"id":"a-hrc-58-67-p0041","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"41","seq":43,"section":"2. Investigators’ involvement in torture","text":"The Commission also investigated situations involving the detention of several\nemployees of the Zaporizhzhia Nuclear Power Plant at their workplace. One of them\nrecounted that in September 2022, two men who introduced themselves as personnel of the\nFederal Security Service arrested a senior staff member, took him to his home, beat him,\nsuffocated him, and applied a hot iron to his body, while questioning him."},{"id":"a-hrc-58-67-p0042","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"42","seq":44,"section":"2. Investigators’ involvement in torture","text":"Further, personnel of the Federal Security Service were the main interrogators in\ndetention facilities. In many cases, they inflicted torture themselves, to extract information,\ncoerce, or intimidate, or used threats of violence causing distress to the victims. In other\ncases, they ordered employees of the Federal Penitentiary Service, or of their special purpose\nunits, to commit torture. Detention personnel also perpetrated torture to prepare the detainees\nfor interrogations by the Federal Security Service. In some instances, the release of detainees\nwas at the discretion of the Federal Security Service. Interrogations were directed at obtaining\ninformation about Ukrainian authorities and armed forces, persons with pro-Ukrainian\npositions and those supporting protests, as well as persons suspected of passing information\nto the Ukrainian armed forces. In one case, a civilian man held in several detention facilities\nreported that in two of them, during regular interrogations led by officers of the Federal\nSecurity Service, they administered electric shocks to him using wires connected to his\nfingers and toes, while questioning him about his connections with Ukrainian authorities."},{"id":"a-hrc-58-67-p0043","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"43","seq":45,"section":"2. Investigators’ involvement in torture","text":"Personnel of the Federal Security Service also ordered torture to coerce detainees into\nconfessing participation in crimes or naming others. One former prisoner of war recounted\nthat during interrogations involving recurrent beatings targeting various parts of his body, an\ninterrogator of the Federal Security Service demanded that he confess to crimes committed\nin Mariupol. When he denied, the interrogator replied, “Incorrect answer. I need a response\nthat satisfies me and my superiors” and prompted the guard of the detention facility to resume\nthe beatings. A civilian woman recounted how, during an interrogation, guards beat her with\na baton on her chest, until she had difficulty in breathing. Officers of the Federal Security\nService pressured her to confess that she was a spy, promising to stop the beatings if she\ncomplied. Personnel of the Federal Security Service also forced detainees to sign documents\nwhich they did not have the opportunity to read and to make false declarations while being\nfilmed.\n(b)         Investigative Committee of the Russian Federation"},{"id":"a-hrc-58-67-p0044","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"44","seq":46,"section":"2. Investigators’ involvement in torture","text":"The Investigative Committee is directly answerable to the President of the Russian\nFederation. In the framework of the Russian Federation’s full-scale invasion, it has set up\noffices in Russian-occupied areas in Ukraine and was tasked with “documenting crimes\ncommitted by the Ukrainian regime against the civilian population” of Donetsk and Luhansk\nProvinces. 16 Personnel of the Investigative Committee interrogated detainees and formulated\ncharges against them for such offences as attempted coup d’etat, terrorism, high treason,\nespionage, or sabotage. Their interrogations focused on identifying persons responsible for\nalleged crimes. During some of the interrogations, members of the Investigative Committee\nordered the personnel of the Federal Penitentiary Services to commit torture to extract\nconfessions, and at times committed violence themselves. They also exerted psychological\nviolence, threatening that a refusal of cooperation would result in torture. In one case, an\nInvestigative Committee member told a former detainee, “Are you sure you’ve told me\neverything you know, or do you need some treatment in the neighbouring office?”, from\nwhere screams could be heard."},{"id":"a-hrc-58-67-p0045","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"45","seq":47,"section":"2. Investigators’ involvement in torture","text":"Personnel of the Investigative Committee forced detainees to sign documents that they\ndid not have the occasion to thoroughly read or had not read at all. Some former prisoners of\nwar from the Azov battalion held in Russian detention facilities told the Commission that\nthey were compelled to undergo trials in Russian Federation courts, after having been coerced\nto sign documents by personnel of the Investigative Committee under threats of torture."},{"id":"a-hrc-58-67-p0046","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"46","seq":48,"section":"3. Concluding observations","text":"The Commission’s findings show that personnel of the Federal Security Service and\nthe Investigative Committee have played a prominent role in ordering torture during\ninterrogations which involve the most brutal forms of torture. Personnel of the Federal\nSecurity Service have been overwhelmingly cited by former detainees for their role in the\ncommission or ordering of torture, during various stages of detentions. Their aim was to\nextract information, coerce and intimidate the detainees. Personnel of the Investigative\nCommittee have also ordered torture, albeit to a lesser extent, during interrogations which\nappear to have been aimed at issuing charges against the detainees."},{"id":"a-hrc-58-67-p0047","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"47","seq":49,"section":"3. Concluding observations","text":"The coordinated actions of these two services demonstrate how Russian authorities\nhave used torture systematically as a method of social control, ultimately designed at\nconsolidating their hold over areas that they occupied in Ukraine. Both services have a\nposition of authority with respect to other services and security forces involved in detention.\nThese findings further show the extent to which Russian Federation services have acted\npursuant to a policy and strengthen the Commission’s previous conclusion that they have\ncommitted torture as crimes against humanity."},{"id":"a-hrc-58-67-p0048","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"48","seq":50,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"The Commission has previously described the systematic use of sexual violence as a\nform of torture by Russian authorities in detention facilities, mostly against men. 17 In the\npresent report, it focuses on new cases of rape and sexual violence amounting to torture\nagainst detained women. The actions of the perpetrators, aimed at humiliating and degrading\nwomen in detention, highlight the gendered manifestations of violence in detention."},{"id":"a-hrc-58-67-p0049","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"49","seq":51,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"A 26-year-old female prisoner of war, who was detained for over two years by Russian\nauthorities after her surrender in May 2022, was subjected to multiple acts of violence in a\ndetention facility in the Russian Federation. During interrogations, personnel of the Federal\nPenitentiary Service tied her hands and severely beat her for hours on various parts of her\nbody. During one such session, they removed her top clothing, hung her by her arms and\nfurther beat her in that position. During another session, they stripped her naked, placed her\nface down, blindfolded. They tied her hands and ankles, and raped her with a rubber baton,\nwhile telling her that she deserved everything that had happened to her. The victim was\nbleeding, lost consciousness and could not stand or walk after that. She stated, “It was just\npain. I couldn’t even breathe. I couldn’t understand why they would do that to me, how they\ncould do that to someone”. The former detainee suffered other acts of abuse and humiliation\nand was ultimately placed in solitary confinement for eight months. After her release, she\nhad to undergo medical rehabilitation, two surgeries, and developed an additional serious\nmedical condition."},{"id":"a-hrc-58-67-p0050","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"50","seq":52,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"In another case, in April 2022, a 40-year-old civilian woman went to the Russian\nauthorities’ commandant office in Kherson city to inquire about a missing relative (see para.\n29). There, an officer of the Federal Security Service questioned her. Dissatisfied with her\nanswers, he stated that since she had not cooperated, he would have to call “professionals”.\nHe ordered three Russian soldiers to “talk to her normally, maybe she will remember\nsomething”. The soldiers took her to another room, where they took turns raping her. They\nalso raped her using a rubber baton. While questioning her, they beat her and struck her\ntailbone. Afterwards, the victim could barely walk and needed surgery."},{"id":"a-hrc-58-67-p0051","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"51","seq":53,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"Further, a civilian woman who had been confined in March 2022 in a detention facility\nin Zaporizhzhia Province, stated that during the night, five intoxicated soldiers took her from\nher cell and brought her to the interrogation room, where they beat her, burnt her foot with\ncigarettes, and undressed her. All five raped her, including with batons and other objects.\nAnother civilian woman, who had also been confined in March 2022 in another facility of\nthe same province, recounted that during the night, a soldier who appeared intoxicated came\nto her cell and ordered her to undress, touched various parts of her body, and raped her. She\nscreamed. Other soldiers, who approached, mocked her and encouraged the assailant. The\nnext night, two soldiers came to her cell, ordered her to remove her clothes waist up and to\nsquat and jump on a table, while they threw lit cigarettes at her and poured water over her."},{"id":"a-hrc-58-67-p0052","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"52","seq":54,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"Personnel of certain detention facilities in the Russian Federation and in occupied\nareas of Ukraine imposed forced nudity on groups of women. Former female detainees,\nprisoners of war, reported that upon their arrival at several detention facilities, they were\nordered to undress fully, after which they were examined thoroughly and photographed in\nthe presence of numerous onlooking male guards. One of the detainees added that they were\nforced to squat repeatedly while naked. A woman who underwent such degrading treatment\nin several detention facilities stated, “I was helpless, hopeless, humiliated, tired. I felt like a\nlittle monkey at the zoo, while those men stared at us.”"},{"id":"a-hrc-58-67-p0053","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"53","seq":55,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"Forced nudity was also imposed before and after showers. Several women detained\ntogether described how male guards, without any explanation, pushed a group of women,\nblindfolded, into the corridor. One of the guards remarked, “You will be executed\nnow,” while others laughed. Unknown to them, this was the first time they were going to be\nallowed to shower in weeks of detention. The perpetrators forced them to undress fully while\nmale guards and convicts lined the corridor, laughed and mocked them. After two minutes\nunder boiling hot water, the women, still naked, were ordered to parade back through the\nsame corridor full of male guards and convicts. One of the women stated, “It was such a\nhorrible event. […] I thought we were going to be executed, like in concentration camps.”\nAnother detainee said that such treatment felt “as violating and degrading as rape”. Women\nwho had been detained by Russian authorities in other detention facilities described similar\npractices, suggesting a common pattern. One of them recounted, in addition, that if they\nstayed in the shower for more than three minutes, guards accompanied by dogs electrocuted\nthem and beat them on the way back to the cells."},{"id":"a-hrc-58-67-p0054","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"54","seq":56,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"In several detention facilities, female detainees were subjected to inhuman conditions\nwhich affected them differently and disproportionately. Detention personnel refused to\nprovide them with hygiene pads during their menstruation. Instead, they mockingly\ninstructed them to tear the mattresses, bedsheets, or clothes, to use them as hygiene pads.\nConsequently, detained women suffered from reproductive health issues. A female detainee\nwho suspected that she was pregnant and requested medical assistance, was ignored by the\nguards. She collapsed and regained consciousness in a hospital. The Federal Security Service\nofficer who escorted her remarked, “Why didn’t you tell us you were pregnant? Well, not\nanymore, and that’s your fault.”"},{"id":"a-hrc-58-67-p0055","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"55","seq":57,"section":"C. Sexual violence as a form of torture and gender-based violence","text":"The Commission has previously found that Russian authorities have systematically\nused sexual violence as a form of torture in detention facilities, and that most of the victims\nwere men. The newly documented cases outlined in the present report demonstrate the\nparticular vulnerability of female detainees to forms of sexual violence and abuse that reflect\nthe gendered nature and impact of the treatment of women during detention. The Commission\nconcluded, in these cases, that Russian authorities committed the war crimes of rape or sexual\nviolence as a form of torture. The violent practices and the inhuman conditions described\ncaused long-term physical and psychological harm."},{"id":"a-hrc-58-67-p0056","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"56","seq":58,"section":"D. Killing or wounding persons hors de combat","text":"The Commission has investigated the killing or wounding, by parties to the armed\nconflict, of soldiers who were captured, injured, or attempted to surrender, and were thus\nhors de combat.18 It has compiled available video footage and photographs, and collected\ncorroborating and contextual information. The Commission has also interviewed soldiers\nwho have deserted from the Russian armed forces and described orders to kill\nsurrendering Ukrainian soldiers. The incidents reviewed occurred in two types of situations:\nthe killing or wounding soldiers while they were surrendering or were already captured, and\nthe killing or wounding already injured soldiers."},{"id":"a-hrc-58-67-p0057","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"57","seq":59,"section":"1. Killing or wounding captured or surrendering soldiers","text":"Since the outset of the full-scale invasion, Ukrainian authorities have conducted\npre-trial investigations in 57 criminal cases concerning the killing by Russian armed forces\nof over 196 Ukrainian soldiers. They have reported a sharp increase in the number of\nexecutions in 2024. The Commission has examined 32 incidents in which Russian soldiers\nkilled or wounded 101 surrendering or captured Ukrainian soldiers in 2022, 2023, 2024,\nand early 2025, in Donetsk, Luhansk and Zaporizhzhia Provinces of Ukraine, as well as in\nthe Kursk Province of the Russian Federation. It has noted an increase in reports concerning\nsuch incidents since late 2023."},{"id":"a-hrc-58-67-p0058","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"58","seq":60,"section":"1. Killing or wounding captured or surrendering soldiers","text":"The Commission previously reported about incidents in which Ukrainian armed\nforces shot at Russian soldiers as they were surrendering or had been captured, in 2022. 19\nIt is not aware of further allegations of this nature.\nIn most situations reviewed, Russian soldiers shot, with small arms and at close r ange,\nUkrainian soldiers as they were surrendering. The soldiers targeted were in a vulnerable\nsituation: unarmed, lying on the ground, kneeling, and some were partly naked. For\ninstance, video footage that circulated in February 2024, geolocated to the Bakhmut\nDistrict, Donetsk Province, shows eight Ukrainian soldiers as they come out from a trench\nand lay on the ground, in an apparent surrender. While some of them were still coming out\nof the pit, five Russian soldiers who surrounded the trench and held them at gunpoint, shot\nat them multiple times, including with an automatic weapon. Other footage that circulated\nin October 2024, also geolocated in Donetsk Province, shows Russian soldiers shoot three\nUkrainian soldiers after instructing them to lie down. In additional incidents, Russian\nsoldiers shot Ukrainian soldiers whom they had already captured, and in one incident\nRussian soldiers appear to use three Ukrainian soldiers as human shields, before shooting\nat least one of them."},{"id":"a-hrc-58-67-p0059","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"59","seq":61,"section":"1. Killing or wounding captured or surrendering soldiers","text":"The Commission also notes violent acts committed against Ukrainian soldiers or\ntheir dead bodies in some of the material circulated. For instance, photographs geolocated\nin Donetsk Province and dated August-September 2024, show a dead Ukrainian soldier,\ncovered in blood, with a spade bearing the writing “for Kursk” stuck in his chest. A video\nreleased by a Russian military unit and geolocated at the border crossing with the\nBelgorod Province in the Russian Federation shows a severed head, said to be that of a\nUkrainian soldier, impaled on a spike, with an audio message threatening that this will be\nrepeated at every future encounter. A video with similar content was circulated on Russian\ntelegram channels in January 2025.\nPerpetrators’ orders and instructions"},{"id":"a-hrc-58-67-p0060","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"60","seq":62,"section":"1. Killing or wounding captured or surrendering soldiers","text":"The Commission has interviewed 48 former soldiers who have deserted from the\nRussian armed forces. The majority participated in combat operations in Donetsk, Kharkiv,\nKyiv, Luhansk, and Zaporizhzhia Provinces. Eleven among them described direct orders or\ninstructions by their commanders not to take prisoners. In most cases, they also received\norders to kill them instead. Another fifteen of the interviewed soldiers heard accounts from\nfellow soldiers concerning such orders, instructions, or practices to not take prisoners."},{"id":"a-hrc-58-67-p0061","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"61","seq":63,"section":"1. Killing or wounding captured or surrendering soldiers","text":"The testimonies of the deserted Russian soldiers show that during meetings, both\nprior to and during deployment to Ukraine, Russian unit commanders instructed large\nnumbers of attending soldiers to not take prisoners. One former soldier stated that during\nsuch a meeting, a deputy brigade commander told the regiment, “Prisoners are not needed,\nshoot them on the spot” (“Πленные не нужны, расстреливать на месте”). Another\nformer soldier recalled that in a staff meeting of the assault squad, the regiment commander\nresponded to a question about prisoners, stating, “Don’t take them. Shoot.” (“Не брать.\nРасстреливать”). One more former soldier reported that, when answering a similar\nquestion, a battalion commander declared, “We don’t take prisoners. Those Nazis should not\nbe taken in captivity, they should be killed.” (“Мы не берем в плен. Этих нацистов нельзя\nбрать в плен, их надо убивать”)."},{"id":"a-hrc-58-67-p0062","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"62","seq":64,"section":"1. Killing or wounding captured or surrendering soldiers","text":"Orders were also given in operational situations, at times via radio messages. Two\ndeserted Russian soldiers deployed in different regions of Ukraine heard similar orders on\nthe radio. One of them spoke of general instructions of the regiment commander to all the\nsoldiers of the assault unit, saying, “When you go in the trenches, do not take prisoners”\n(“Когда заходите в окопы, пленных не брать”). Another former soldier heard how the\ncommander of the assault unit instructed, “Take no prisoners, kill everyone, take everything”\n(“Пленных не брать, всех убить, все отнять”). He also heard on the radio, how, in\nresponse to reports that a Ukrainian soldier was attempting to surrender without a weapon\nand waving a white cloth, the commander ordered to drop a grenade on him."},{"id":"a-hrc-58-67-p0063","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"63","seq":65,"section":"1. Killing or wounding captured or surrendering soldiers","text":"Some of those interviewed had witnessed fellow soldiers killing captured\nUkrainian soldiers. One of them recounted that an officer ordered, “Zero him!”\n(“Обнулить!”), referring to a captured soldier. He later saw the captured soldier’s\nbody. Finally, another deserted Russian soldier heard over the radio, how, after the\ncommander’s order to kill surrendered soldiers, one of them pleaded, crying, “I want to live”.\nNevertheless, gunshots followed."},{"id":"a-hrc-58-67-p0064","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"64","seq":66,"section":"2. Killing or wounding injured soldiers","text":"Videos and photographs of incidents where both parties to the conflict targeted\ninjured soldiers have widely circulated. The soldiers that were hit had often visible, grave\ninjuries and were unfit to continue combat. Perpetrators mainly used exploding drones or\nexplosives dropped by drones. Footage showing such incidents has circulated on telegram\nchannels run by servicemen of both parties or on telegram channels closely affiliated to\nthem. Many of the videos are particularly disturbing, set to loud music, styled like a video\ngame, with dismissive comments accompanying images of killings, grave injuries and\nintense suffering.\n(a)        Killing or wounding injured Ukrainian soldiers by Russian armed forces"},{"id":"a-hrc-58-67-p0065","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"65","seq":67,"section":"2. Killing or wounding injured soldiers","text":"The Commission has documented incidents in which Russian armed forces fired at\ninjured Ukrainian soldiers. Footage that circulated on 27 September and 8 October 2023, and\nreferred to frontline developments in Luhansk Province, shows an exploding drone targeting\na group of three Ukrainian soldiers carrying an injured soldier on a stretcher, severely injuring\none of them. One of the videos is titled “Destruction of the evacuation crew of the enemy”.\nIn another situation, videos disseminated on 16, 17, and 27 November 2023, and referring to\na frontline in Donetsk Province, show drones dropping explosives on six heavily wounded\nUkrainian soldiers. Two of them appear to wear tourniquets. In yet another incident, footage\ndated 22 November 2023, referring to operations in the Bakhmut District, Donetsk province,\nshows drones repeatedly dropping explosives on seven apparently injured Ukrainian soldiers.\n(b)        Killing or wounding injured Russian soldiers by Ukrainian armed forces"},{"id":"a-hrc-58-67-p0066","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"66","seq":68,"section":"2. Killing or wounding injured soldiers","text":"The Commission has also documented situations where Ukrainian armed forces\ntargeted injured Russian soldiers. For instance, a video compilation referring to frontline\ndevelopments on 24 May 2024, in Donetsk Province, shows how explosives are dropped by\ndrone on four Russian soldiers with visible and life-threatening injuries. On 4 December\n2024, a unit of the Ukrainian armed forces circulated a video, described as the aftermath of\noperations in Donetsk Province, which shows how drone operators allowed a severely\nwounded Russian soldier, wearing a tourniquet on a leg, to smoke a last cigarette before\ndropping explosives to kill him. The Commission reviewed other material about similar\nincidents, including a video compilation showing active combat, but also an explosive\ndropped from a drone on a visibly injured Russian soldier lying on a stretcher."},{"id":"a-hrc-58-67-p0067","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"67","seq":69,"section":"3. Concluding observations","text":"Based on the documented cases, the Commission has concluded that both parties\ncommitted the war crimes of killing or wounding injured soldiers20 and of outrages upon their\ndignity, through disseminating dehumanizing footage of injury and death, with loud music\nand offensive comments.21"},{"id":"a-hrc-58-67-p0068","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"68","seq":70,"section":"3. Concluding observations","text":"Further, the Commission has found that Russian armed forces committed the war\ncrime of killing or wounding soldiers who attempted to surrender or were captured. The\ndissemination of material concerning such incidents has increased significantly. The\ntestimonies of former Russian soldiers, showing that commanders of various units, at\ndifferent levels and in multiple locations, both prior to and during deployment or active\noperations, gave almost identical orders, combined with the wide number of incidents\ndocumented and their regular recurrence, indicate that the Russian armed forces have acted\npursuant to a policy to kill surrendering or captured soldiers, in clear violation of international\nhumanitarian law.22 Moreover, declaring that no quarter will be given is a war crime.23"},{"id":"a-hrc-58-67-p0069","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"69","seq":71,"section":"E. Violations committed by Ukrainian authorities against persons accused","text":"The Commission has previously found that Ukrainian authorities have committed\nsome violations of human rights against persons whom they have accused of collaboration\nwith the Russian authorities.24 During the present mandate, it has investigated four additional\nsuch cases, all concerning incidents in 2022, against male victims. The Commission\nconcluded that Ukrainian authorities committed the human rights violations of arbitrary arrest\nand detention in all of these cases. It also determined that the human rights violation of torture\nwas committed in two of them and the human rights violation of enforced disappearance in\none of them.25"},{"id":"a-hrc-58-67-p0070","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"70","seq":72,"section":"E. Violations committed by Ukrainian authorities against persons accused","text":"In one case, on 31 March 2022, men in uniform arrested a civilian man near Dymer\nsettlement, Kyiv Province, immediately beat him, shot near him, and detained him in the\nbuilding of the Security Service of Ukraine in the center of Kyiv city. There, according to the\nvictim, armed persons with masks interrogated him, beat and suffocated him, administered\nelectric shocks and burnt him with cigarettes, to force him to confess collaboration with the\nRussian armed forces. His arrest was officially recognized by court decision only on 16 April\n2022. Starting from the day after the arrest, the parents attempted, in vain, to locate him. They\nreceived information about the place of detention only on 19 April 2022. 26"},{"id":"a-hrc-58-67-p0071","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"71","seq":73,"section":"E. Violations committed by Ukrainian authorities against persons accused","text":"In another case, on 27 July 2022, persons in uniform arrested a member of the Security\nService of Ukraine near the building of the Security Service of Ukraine for Kharkiv region,\nin Kharkiv city, and immediately beat him. The Security Service of Ukraine released a video\npartially showing the arrest. During subsequent detention, according to the victim, persons\nin uniform interrogated him, beat and administered electric shocks to him, to extract a\nconfession, and threatened him with sexual violence and mutilation. A protocol made by the\nSecurity Service of Ukraine records his date of arrest on 29 July 2022."},{"id":"a-hrc-58-67-p0072","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"72","seq":74,"section":"E. Violations committed by Ukrainian authorities against persons accused","text":"The Commission previously referred to the legal uncertainty concerning the definition\nof “collaborative activity” and has recommended that the legislation be aligned with\ninternational standards.27 Since 2022, several draft amendments to the Criminal Code on this\nissue have been submitted to the parliament. In May and June 2024, the Office of the\nProsecutor General of Ukraine issued guidance letters concerning criminal prosecution for\n“collaborative activities”, instructing full compliance with the requirements of international\nhuman rights law and international humanitarian law, which is a positive development."},{"id":"a-hrc-58-67-p0073","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"73","seq":75,"section":"III. Conclusions and recommendations","text":"During its third mandate, the Commission has concluded that Russian\nauthorities committed the crime against humanity of enforced disappearances and the\ncrime against humanity of torture. These crimes have been carried out as part of a\nwidespread and systematic attack against the civilian population. Perpetrators have\ndetained large numbers of civilians in areas that came under their control in Ukraine\nand further transferred or deported many of them to detention facilities in occupied\nareas of Ukraine or in the Russian Federation. They committed additional violations\nand crimes during these prolonged detentions. Many victims have been missing for\nmonths and years, and some died in captivity. Various Russian authorities have\nsystematically failed to provide information on their whereabouts. This included the\nMinistry of Defense of the Russian Federation, which denied information on the\nwhereabouts of detainees, invoking confidentiality. The elements documented\ndemonstrate that Russian authorities have acted pursuant to a policy and with the\nintent to remove those disappeared from of the protection of the law. Prisoners of war\nhave also been victims of torture and of enforced disappearances, in violation of\ninternational humanitarian law."},{"id":"a-hrc-58-67-p0074","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"74","seq":76,"section":"III. Conclusions and recommendations","text":"Torture of detainees was particularly brutal during interrogations. The Federal\nSecurity Service and the Investigative Committee of the Russian Federation have been\namong the main authorities leading interrogations. Personnel of both entities have\nparticipated in or ordered torture and have issued threats of violence against the\nvictims. Evidence shows that the Federal Security Service had the highest authority,\nwhen present in detention facilities, and committed torture at various stages of the\ndetentions."},{"id":"a-hrc-58-67-p0075","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"75","seq":77,"section":"III. Conclusions and recommendations","text":"Russian authorities have systematically used sexual violence as a form of torture\nagainst men in detention facilities. The Commission documented new cases in which the\nwar crimes of rape and sexual violence were committed against female detainees."},{"id":"a-hrc-58-67-p0076","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"76","seq":78,"section":"III. Conclusions and recommendations","text":"The Commission further examined incidents involving the killing or wounding,\nby Russian armed forces, of captured or surrendering Ukrainian soldiers, which are\nwar crimes. Testimonies of soldiers who deserted from the Russian armed forces\nindicate that there is a policy not to take prisoners but to kill them instead."},{"id":"a-hrc-58-67-p0077","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"77","seq":79,"section":"III. Conclusions and recommendations","text":"Both parties to the armed conflict have killed or wounded injured soldiers on\nfrontlines, using drones, which are also war crimes."},{"id":"a-hrc-58-67-p0078","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"78","seq":80,"section":"III. Conclusions and recommendations","text":"Finally, the Commission documented some human rights violations committed\nby Ukrainian authorities against persons accused of collaboration."},{"id":"a-hrc-58-67-p0079","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"79","seq":81,"section":"III. Conclusions and recommendations","text":"Three years of armed conflict have had a devastating impact on the civilian\npopulation. Victims have often suffered from a complex combination of violations and\ncrimes, as well as from hardships owing to prolonged armed conflict. Many have\nendured deprivation of liberty, physical violence, and inhuman treatment;\ndisappearance, death, or separation from loved ones; loss or destruction of homes; and,\nconsequently, limitations of their basic rights to housing, food, education, and health.\nFamily members have been subjected to excruciating anxiety and suffering, while\ncoping with prolonged separations from their loved ones, and searching and waiting for\nthem. For many of the victims, the physical and moral losses are irreparable."},{"id":"a-hrc-58-67-p0080","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"80","seq":82,"section":"III. Conclusions and recommendations","text":"In this context, victims have faced numerous challenges in their recovery,\nrehabilitation, and reintegration in society. The Commission thus reiterates the\nimportance of non-judicial forms of accountability, including measures of truth,\nreparation, and guarantees of non-recurrence. It also emphasizes that judicial\naccountability remains key to ensuring that perpetrators of violations and crimes are\nidentified and held to account for their acts, and to end the cycle of impunity."},{"id":"a-hrc-58-67-p0081","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"81","seq":83,"section":"III. Conclusions and recommendations","text":"The recommendations made in previous reports remain relevant. The\nCommission sets out below specific recommendations to address issues developed in the\ncurrent report."},{"id":"a-hrc-58-67-p0082","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"82","seq":84,"section":"III. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation immediately:\n(a)    Cease aggression and all acts of violence committed against civilians and\nprisoners of war in violation of international human rights law and international\nhumanitarian law;\n(b)   End the widespread and systematic use of torture and other forms of ill-\ntreatment committed against civilian detainees and prisoners of war;\n(c)   Take all possible measures to prevent sexual and gender-based violence of\ncivilians and prisoners of war."},{"id":"a-hrc-58-67-p0083","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"83","seq":85,"section":"III. Conclusions and recommendations","text":"The Commission also recommends that the Russian Federation:\n(a)    End enforced disappearances, notably through informing families of the\nfate and whereabouts of all persons in their custody, ensuring that all those detained\nare registered, and provide legal review of the grounds of their detention;\n(b)    End transfers of civilians to Russian-occupied areas in Ukraine and\ndeportations of civilians to the Russian Federation;\n(c)    Release or return to Ukraine all Ukrainian civilians who have been\ndeported to the Russian Federation and are detained there as a consequence of the\narmed conflict;\n(d)    When a disappeared person dies, promptly return the remains of the\ndeceased to the family and inform them of the circumstances of the death;\n(e)    End killing or wounding prisoners of war and personnel hors de combat\nand ensure that all such allegations are duly investigated;\n(f)     Ensure that all perpetrators, in particular commanders and other\nsuperiors and those ordering, soliciting or inducing the commission of crimes under\ninternational law, are held accountable in accordance with international standards;\n(g)    Take the measures necessary to prevent the commission of such violations\nand crimes, in particular through unequivocal instructions to all branches of the armed\nforces, the Federal Security Service, the Federal Penitentiary Service and the\nInvestigative Committee, with a view to ensuring that discipline and respect for\ninternational human rights law and international humanitarian law are upheld, along\nwith the principle of command responsibility."},{"id":"a-hrc-58-67-p0084","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"84","seq":86,"section":"III. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)   End killing or wounding injured personnel hors de combat and ensure\nthat all such allegations are duly investigated and that those responsible are held\naccountable;\n(b)    Take the measures necessary to prevent the commission of such violations\nand crimes, in particular through unequivocal instructions to all branches of the armed\nforces;\n(c)    Examine the various proposed amendments to its criminal code in order\nto clarify the crime of collaboration, in conformity with international law, to ensure\nlegal certainty and prevent harm to social cohesion;\n(d)    Continue comprehensively addressing mental health and psychosocial\nneeds resulting from the armed conflict by ensuring access to the relevant services,\nallocating resources to those services and enhancing their institutional coordination,\nlegal regulation, monitoring and evaluation."},{"id":"a-hrc-58-67-p0085","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":"85","seq":87,"section":"III. Conclusions and recommendations","text":"The Commission recommends that other States and regional and international\norganizations:\n(a)   Strengthen their support to judicial and non-judicial accountability\nmechanisms, the latter including measures of truth, reparation, and guarantees of non-\nrecurrence;\n(b)     Provide comprehensive support for the rehabilitation and reintegration of\nvictims of violations and crimes, including health, psycho-social support, and housing."},{"id":"a-hrc-58-67-u0088","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":null,"seq":88,"section":"Annex III","text":"Detention facilities in areas that were under Russian Federation control in Ukraine\nand in the Russian Federation\nThe list below enumerates the detention facilities held by Russian authorities where the\nCommission has confirmed the use of torture through investigations since its appointment.\nAdditional detention facilities are under investigation.\nKherson Province\n- Pre-trial detention centre No. 2, Chonhar village\n- Temporary detention centre, Kherson city\n- Police department, Nova Kakhovka city\n- Temporary detention centre, Hola Prystan city\n- School (makeshift facility), Biliayivka village\n- Sanatorium (makeshift facility), Hola Prystan city","unnumbered":true},{"id":"a-hrc-58-67-u0089","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":null,"seq":89,"section":"Annex III","text":"Zaporizhzhia Province\n- Correctional Colony No. 77 (aka Prymorsk Colony no.145), Berdiansk city\n- Police department, Berdiansk city\n- Police Department, Enerhodar city\n- Police Department, Melitopol city\n- District police, Vasylivka town","unnumbered":true},{"id":"a-hrc-58-67-u0090","rec_id":"recnkiaWE3B1FiOOY","symbol":"A/HRC/58/67","n":null,"seq":90,"section":"Annex III","text":"Donetsk Province\n- Volnovakha Correctional Colony No.120, known as Olenivka, in Molodizhne village\n- Kalinin Correctional Colony No. 4 (previously No. 27), Horlivka city\n- Pre-trial detention centre, Donetsk city","unnumbered":true},{"id":"a-hrc-59-crp-2-u0000","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":null,"seq":0,"section":null,"text":"Summary\nIn the present conference room paper, the Independent International Commission of\nInquiry on Ukraine concludes that Russian armed forces have committed the crimes against\nhumanity of murder and the war crimes of attacking civilians, through a months-long pattern\nof drone attacks targeting civilians on the right bank of the Dnipro River in Kherson\nProvince, in Ukraine. It also found that these acts were committed with the primary purpose\nto spread terror among the civilian population, in violation of international humanitarian law.\nSince July 2024, Russian military drone operators based on the opposite side of the\nriver have systematically struck civilian persons, in various circumstances, mainly outdoors,\nwhile on foot or using transport. They also targeted ambulances, which have special\nprotection under international humanitarian law, often preventing them from reaching the\nvictims.\nThe Commission documented drone attacks against civilians in Kherson city and 16\nother localities stretching over 100 kilometres in river front areas under Ukrainian\nGovernment control. The attacks are continuing at the time of the publication of this paper.\nSo far, almost 150 civilians have been killed and hundreds more have been injured, according\nto official sources.\nIn its investigations, the Commission interviewed over 90 residents of the affected\nareas in Kherson Province, including victims and witnesses, geolocated over 120 publicly\ndisseminated videos of attacks, collected official documents, and reviewed hundreds of\nadditional videos and text posts available on open sources.\nThe perpetrators used civilian drones, widely commercially available, that they\nweaponized to drop explosives on targets. They also used suicide drones that explode upon\nimpact. The drone operators are able to track and aim at targets remotely via an embedded\ncamera.\nSeveral Russian Telegram channels with links to the perpetrating military units, some\nof them with thousands of followers, have disseminated hundreds of videos of the attacks\nfrom the original feeds of the drones. The footage posted shows that the perpetrators could\nclearly see the victims and leaves no doubt that they intended to target civilians. The same\nTelegram channels have regularly uploaded threatening text announcing further attacks in a\nwide geographic area, to which they refer as a “red zone”.\nThe individual drone attacks amount to the war crimes of intentionally directing\nattacks against civilians. The recurrence of these attacks for over 10 months, against multiple\ncivilian targets and in a wide geographic area, demonstrates that they are widespread and","unnumbered":true},{"id":"a-hrc-59-crp-2-u0001","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":null,"seq":1,"section":null,"text":"systematic and have been planned and organised, requiring the mobilisation and allocation\nof necessary resources. These and other elements led the Commission to conclude that\nRussian armed forces carried out drone attacks targeting civilians pursuant to an\norganisational policy and committed murder as a crime against humanity.\nThe Commission further found that Russian armed forces and those supporting them\nhave committed acts or threats of violence for the primary purpose to spread terror among\nthe civilian population in the targeted areas of Kherson Province, in violation of international\nhumanitarian law. The nature and broad range of the attacks, their specific civilian targets,\ntheir frequency, intensity, geographic spread, the circumstances in which they occur, have\nled to pervasive fear within the population. The public dissemination of videos of attacks and\nthreatening text announcing further attacks in the above-mentioned area referred to as a “red\nzone”, have exacerbated the fear of the population. A resident of Kherson Province who\nwitnessed eight drone attacks stated “they want to inflict horror on the city”. The posting on\nRussian Telegram channels of videos of civilians being killed and injured amounts to the war\ncrime of outrages upon personal dignity.\nIn the Commission’s view, the conduct of the perpetrators may amount to the crime\nagainst humanity of forcible transfer of population. The widespread and systematic character\nof the attacks, the terror instilled within the population, and the ensuing coercive\nenvironment, have compelled thousands to flee. In addition to attacking civilian persons,\ndrones have repeatedly targeted civilian objects and infrastructure, all means of transport,\nand emergency and rescue services. The damage and destruction of houses, the absence or\nlimitation of services, essential infrastructure, and transport, have rendered the affected areas\nunliveable and left many residents with no other choice than to seek safer locations. These\nelements combined suggest a coordinated state policy, on the part of the Russian authorities,\nto force the population to leave.\nThe Commission also examined allegations by Russian authorities of drone attacks\nby Ukrainian armed forces against civilian targets in Kherson Province. However, it was\nunable to corroborate them because of lack of cooperation by Russian authorities.","unnumbered":true},{"id":"a-hrc-59-crp-2-p0001","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"1","seq":2,"section":"I. Introduction","text":"In its resolution 49/1,1 adopted on 4 March 2022, the Human Rights Council decided\nto urgently establish an Independent International Commission of Inquiry to investigate\nalleged violations and abuses of human rights and violations of international humanitarian\nlaw, and related crimes in the context of the Russian Federation’s aggression against Ukraine.\nThe Commission’s mandate was most recently extended on 4 April 2025.2 It is composed of\nErik Møse (Chair), Pablo de Greiff, and Vrinda Grover."},{"id":"a-hrc-59-crp-2-p0002","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"2","seq":3,"section":"I. Introduction","text":"In all aspects of its work, the Commission is guided by the principles of independence,\nimpartiality, objectivity, and integrity. It adopts a victim-centred approach and a strict respect\nof the “do no harm” principle, in particular regarding guarantees of confidentiality of the\ninformation received and the safety and the protection of victims and witnesses, and other\ninterlocutors."},{"id":"a-hrc-59-crp-2-p0003","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"3","seq":4,"section":"I. Introduction","text":"In the context of the situation in Kherson city and other localities on the right bank of\nthe Dnipro River in Kherson Province, where recurrent drone attacks against civilians by\nRussian armed forces have been going on for months, the Commission is presenting a special\nreport on this matter. It has interviewed 91 persons from the areas affected by attacks (43\nwomen and 48 men). Interlocutors included victims, witnesses, local authorities, medical\npersonnel, and humanitarian workers. The Commission has examined over 300 publicly\navailable videos of attacks, of which it has geolocated 124, as well as over 600 text posts on\nTelegram channels. During its investigations, the Commission has identified victims of the\nattacks shown in these videos and interviewed them as well as witnesses. It has also collected\nrelevant documents, including death certificates and medical reports."},{"id":"a-hrc-59-crp-2-p0004","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"4","seq":5,"section":"I. Introduction","text":"The Commission also examined allegations, as reported by Russian authorities, 3 of\ndrone attacks by Ukrainian armed forces against civilian targets in Kherson Province. Such\nclaims could not be corroborated because of lack of information and access due to the absence\nof cooperation by Russian authorities."},{"id":"a-hrc-59-crp-2-p0005","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"5","seq":6,"section":"I. Introduction","text":"The Commission expresses its gratitude to all those who shared their experiences,\ntestimonies and other valuable information. It appreciates the cooperation of the Government\nof Ukraine. The Russian Federation continued not to recognise the Commission and did not\nrespond to any of the Commission’s questions concerning drone attacks."},{"id":"a-hrc-59-crp-2-p0006","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"6","seq":7,"section":"II. Military and political context","text":"Kherson was the first major city captured by Russian armed forces in the early stages\nof the 2022 full-scale invasion. On 30 September 2022, the Russian Federation unilaterally\ndeclared the annexation of Kherson Province, together with Donetsk, Luhansk, and\nZaporizhzhia provinces. This is illegal under international law. 4 Vladimir Putin, the President\nof the Russian Federation, subsequently signed a Constitutional Law on the Accession\nof the Kherson Region to the Russian Federation.5 On 11 November 2022, a Ukrainian\narmed forces counteroffensive retook control of Kherson city and the surrounding area on\nthe right bank of the Dnipro River (see map, figure 1). The Russian armed forces and the\nRussian civil administration, which had been set up in Kherson city, withdrew to the left\nbank. Since then, both armed forces have conducted ground, air or riverine military\noperations from opposite sides of the river, including with drones. Localities in the area have\nexperienced shelling and drone attacks. 6"},{"id":"a-hrc-59-crp-2-p0007","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"7","seq":8,"section":"II. Military and political context","text":"Despite the loss of the provincial capital, on 11 November 2022, Dmitry Peskov, the\nSpokesperson of the President of the Russian Federation, in response to a question of the\npress on whether the withdrawal of Russian troops meant that Kherson city will no longer be\nthe administrative centre of the province, declared, “Other decisions have not been taken”. 7\nConcerning Kherson Province, he noted, “This is a constituent entity of the Russian\nFederation, this is a status given and strengthened by law. There can be no changes here.” 8\nThe Russian Federation has consistently reiterated its claims to the entirety of the Kherson\nProvince, as well as to the other three illegally annexed provinces, referring to the so-called\nreferendums which the Russian Federation held in the occupied territories of the four\nUkrainian provinces in violation of international humanitarian law in 2022. 9 On 14 June\n2024, the President of the Russian Federation declared, “The residents of Kherson\nand Zaporozhye have expressed their position in referendums, and Kherson and Zaporozhye\nregions, as well as the Donetsk and Lugansk People’s Republics, have become part\nof the Russian Federation. And there can be no talk of disturbing our state unity.\nThe people’s will to be with Russia shall be inviolable. This matter is closed forever and is\nno longer a matter for discussion.”10\nFigure 1. Map of the relevant area in Kherson province"},{"id":"a-hrc-59-crp-2-p0008","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"8","seq":9,"section":"III. Overview","text":"Drones of various types have been used extensively against military targets by both\nparties during the armed conflict in Ukraine. Starting from July 2024, Russian armed forces\nsystematically attacked civilians with drones in Kherson city and other localities on the\nUkrainian-controlled right bank of Dnipro River, in Kherson Province.11 They targeted\ncivilian persons, in various circumstances, mainly when they were outdoors, both on foot or\nwhile using any type of vehicles; they also targeted ambulances. These attacks have resulted\nin the death and injury of men, women, and children, mostly men, and have also led to\npsychological trauma and fear. 12"},{"id":"a-hrc-59-crp-2-p0009","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"9","seq":10,"section":"III. Overview","text":"Such attacks became part of the daily lives of the residents of Kherson city and other\nriver front localities of Kherson Province. The area affected stretches across more than 100\nkilometres along the right bank of Dnipro River. The frequency and the geographic spread\nof the drone attacks intensified during autumn 2024. They were still continuing at the time\nof the publication of this paper. Residents saw or heard the drones flying in from the other\nside of the river, where the Russian armed forces are based. In the incidents investigated, the\ntargets were visibly civilian and no military personnel or equipment were identified at the\ntimes and locations of the attacks."},{"id":"a-hrc-59-crp-2-p0010","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"10","seq":11,"section":"III. Overview","text":"During these attacks, Russian armed forces mostly used civilian drones that are widely\ncommercially available, after modifying them into weaponized drones. The weaponized\nversions of these drones allow their operators, via an embedded camera, to remotely track,\naim, and drop explosives on targets. They can return to their point of origin to be reused.\nOccasionally, perpetrators employed suicide drones that are also equipped with cameras but\nthat explode upon impact on their targets."},{"id":"a-hrc-59-crp-2-p0011","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"11","seq":12,"section":"III. Overview","text":"Several Russian Telegram channels have played an instrumental role in supporting\nthe acts of the perpetrators and in enhancing their effects. Such channels have regularly\ndisseminated video footage recorded by the attacking drones, as well as text with dismissive\nor violent comments and threats of further attacks. One officially registered Telegram\nchannel, with thousands of followers, has been uploading such material on a daily basis for\nmonths. Other channels have shared similar content. These Telegram channels have been\nlinked to military units implicated in the attacks. The video footage that they posted displays\nthe attacks and the resulting death, injury, damage, or destruction, and is styled like video\ngames, often accompanied by background music and threatening text. In hundreds of videos\nreviewed by the Commission, it is evident that the perpetrators had a good visibility of targets\nand were thus aware of their civilian character. They nevertheless proceeded with the attacks,\nwhich demonstrates their intentional character."},{"id":"a-hrc-59-crp-2-p0012","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"12","seq":13,"section":"III. Overview","text":"Many victims of drone attacks described how drones suddenly appeared overhead,\nchased them, at times over long distances, and dropped explosives on them. In November\n2024, a 40-year-old employee of a Kherson city hospital was killed by an explosive dropped\nby drone on her car as she was arriving at work. Her husband was injured in this blast. In\nJanuary 2025, a 47-year-old woman from Antonivka settlement told the Commission that\nduring that month, she was walking her dog in the street and suddenly saw two drones\napproaching. She tried to hide under a bush, but the drones nevertheless dropped two\nexplosives that landed to her left and right, causing a concussion, as well as shrapnel wounds."},{"id":"a-hrc-59-crp-2-p0013","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"13","seq":14,"section":"III. Overview","text":"The number, frequency, intensity, and geographic spread of the drone attacks against\ncivilians, as well as the permanent threat of further attacks, have spread terror among the\npopulation living in the affected areas. Residents described feeling constant fear that any\nmovement outdoors involves serious safety risks. A victim of a drone attack said, “Their\ntask is to terrorize us, to break us”. Russian Telegram channels have, for months, posted\ntext exhorting the population to leave the area. Local authorities and multiple interlocutors\nreported a stark decrease of the population as a direct consequence of the attacks. The\npermanent danger, the climate of terror, the damage and destruction of civilian objects, the\nresulting reduction of essential services, have all rendered life in the affected areas\nunbearable. Many felt they had no other choice than to relocate to safer areas. A resident of\nAntonivka settlement told the Commission, “Drones were attacking everything; minibuses,\ncars, pedestrians etc… every time you went out of the house, you had to check the sky and\nlook out for a buzzing sound and, in any case, run.” He left the area, because of the increase\nof drone attacks.\n12 According to the Office of the Prosecutor General of Ukraine, from June 2024 to 10 March 2025, 146\ncivilians have been killed and 1,405 injured as a result of the drone attacks in Kherson and Beryslav\nDistricts of Kherson Province."},{"id":"a-hrc-59-crp-2-p0014","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"14","seq":15,"section":"IV. Widespread and systematic attacks","text":"For months, the Russian armed forces on the left bank of the Dnipro River have carried\nout drone attacks in localities on the right bank of the river. Civilians were hit while they\ncarried out daily life activities, mainly outdoors, near their homes, as they were walking or\nstanding in the street, going or returning from work, visiting relatives, waiting for the bus, or\ntravelling by bicycle or motorcycle. They also targeted various types of vehicles, stationed\nor on the move, public transport, as well as ambulances and fire trucks. Almost 150 civilians\nhave been killed and hundreds more injured as a result of the attacks, including men, women,\nand children, mostly men. Many of the victims were older persons with reduced mobility,\nwho had difficulties in escaping pursuit by a drone. Survivors suffered from grave injuries,\nat times leading to amputations, cuts, and concussions. Limitations in the response of\nemergency services due to the constant risk of attacks have aggravated the situation of those\ninjured, and in some cases led to death."},{"id":"a-hrc-59-crp-2-p0015","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"15","seq":16,"section":"IV. Widespread and systematic attacks","text":"The attacks were committed in areas stretching over more than 100 kilometres along\nthe right bank of the Dnipro River, in the part of Kherson Province that remains under\nUkrainian control. The area comprises multiple urban and rural settlements. The Commission\nfound such incidents in Kherson city and 16 additional localities (see map, figure 2). The\nnumber of victims targeted and the span of the area affected demonstrate that the attacks have\nbeen widespread."},{"id":"a-hrc-59-crp-2-p0016","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"16","seq":17,"section":"IV. Widespread and systematic attacks","text":"For over ten months, the drone attacks have been carried out recurrently. Residents\nreported attacks occurring daily, even several times a day. According to them, everyone in\nthe area knows someone who has been targeted by a drone, and some persons or objects have\nbeen attacked several times. Most of the attacks occurred during daylight, when visibility\nwas good, leaving no possible doubt as to the nature of the target. The deliberate and regular\nrepetition of this criminal conduct, using the same methods, over a prolonged period of time,\ndemonstrates its systematic character.\nFigure 2. Map of documented pattern of drone attacks, Kherson province"},{"id":"a-hrc-59-crp-2-u0018","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":null,"seq":18,"section":"V. Videos and text posts on Russian Telegram channels","text":"“Kherson. Red zone. Civilians did not yet understand that they do not have long to live with\nsuch an approach to security. But everyone choses when and where to die at war.”\nPost on a Russian Telegram channel, 3 February 2025","unnumbered":true},{"id":"a-hrc-59-crp-2-p0017","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"17","seq":19,"section":"V. Videos and text posts on Russian Telegram channels","text":"The widespread and systematic character of the attacks is further demonstrated by the\ndaily dissemination of videos of attacks and threatening texts on some Russian Telegram\nchannels. The content of the videos is such that it could have only come from the original\nfeed of the attacking drones. They show how drones chase civilians and drop explosives on\nthem, causing injury or death. One of the Telegram channels which uploads such material\nhas over 50,000 followers and has been officially registered in the Russian Federation. It has\nbeen posting videos of attacks and accompanying threatening text virtually every day since\nthe end of August 2024. Several other channels have disseminated similar posts. These\nTelegram channels appear to be operated by the perpetrating military units or persons closely\nrelated to them (see para. 49)."},{"id":"a-hrc-59-crp-2-p0018","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"18","seq":20,"section":"V. Videos and text posts on Russian Telegram channels","text":"An analysis of hundreds of videos of attacks shows that perpetrators had a good\nvisibility of the targets at the time of the attacks. In the samples reviewed by the Commission,\na remote pilot can see via the drone’s camera, in real time, select targets, and release one or\nseveral explosives on them. Occasionally, suicide drones with similar camera features but\nthat explode upon impact have also been employed. In the videos documented by the\nCommission, the targets were visibly civilian. The drones nevertheless chased and struck\nthem, demonstrating that the attacks on civilians were deliberate."},{"id":"a-hrc-59-crp-2-p0019","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"19","seq":21,"section":"V. Videos and text posts on Russian Telegram channels","text":"These Telegram channels posted text – accompanying the videos or as separate posts\n– that announced attacks over a broad geographic area. The text was often titled, “Kherson.\nRed zone”, referring to the area targeted by attacks. Some posts displayed a map of about\n45.5 square kilometres coloured in red. On 6 October 2024, a post with a map stated,\n“Residents of this locality, which is marked as a red zone on the map, in these areas our\nteams will destroy any transport – this is one of our primary objectives. […]”. Such\nthreatening texts have been reposted regularly. The area affected by attacks is even larger\nthan the one indicated on the map, which further demonstrates their widespread character."},{"id":"a-hrc-59-crp-2-p0020","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"20","seq":22,"section":"V. Videos and text posts on Russian Telegram channels","text":"The recurrent dissemination of the above-described videos with violent and disturbing\ncontent, generated by the drones, and of text with threats of further attacks, demonstrate the\nintent of the perpetrators and those associated with them, to kill or harm civilians, as well as\nto spread fear and alarm among the population. For instance, a 30 July 2024 post on Telegram\nstated, “[…] Civilians moving within the red zone do so at their own risk, by definition, any\nmovement is a target [sic] […]”. A video disseminated on 15 September 2024, showed an\nexplosive being dropped on a person dressed in civilian clothes, with the accompanying text,\n“[…] Mission accomplished. Target hit.” On 1 December 2024, a post with a video of a\ndrone attack on three civilians repairing a roof, noted “Once again. Everything that moves\nwill be destroyed. […]” Similar posts have been published regularly."},{"id":"a-hrc-59-crp-2-p0021","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"21","seq":23,"section":"VI. Case descriptions","text":"The examples and incidents outlined in this paper focus on attacks on civilian persons\nand various forms of civilian transport, as well as ambulances. They are only a small sample\nof the incidents examined by the Commission.\nAttacks targeting civilian persons outdoors"},{"id":"a-hrc-59-crp-2-p0022","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"22","seq":24,"section":"VI. Case descriptions","text":"The drone attacks targeted civilian persons around their houses, on the street, or when\nthey travelled by bicycles or motorcycles. A man from Kherson city described that in August\n2024, he was in the courtyard of his building together with his 54-year-old neighbour and\nheard the sound of a drone. He immediately ran into the building. The drone dropped an\nexplosive, fatally injuring his neighbour, who had not managed to get inside. An older woman\nwith low mobility was sitting in the yard at that time and was also injured."},{"id":"a-hrc-59-crp-2-p0023","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"23","seq":25,"section":"VI. Case descriptions","text":"A woman from Poniativka village recounted that in September 2024, she was walking\nhome with her 54-year-old husband and suddenly heard a drone. It was already above their\nheads and immediately dropped an explosive, giving them no time to seek shelter. Both were\ninjured. Her husband suffered from intense bleeding and died before an ambulance arrived,\nwith significant delay, due to the danger of drone attacks. The woman said, “My husband\ndied in my arms, bleeding to death, because the ambulance did not arrive on time. I tried to\nstop the bleeding with a T-shirt, but it was not enough. […]”."},{"id":"a-hrc-59-crp-2-p0024","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"24","seq":26,"section":"VI. Case descriptions","text":"A 23-year-old-woman stated that in September 2024, she was biking from Antonivka\nsettlement to the centre of Kherson city and noticed a drone following her. She tried to escape,\nbut the drone dropped an explosive in her proximity, injuring her leg. A video of the attack\nwas posted on a Telegram channel with the text, “[…] This individual has been eliminated\nwith precision. […]” It further stated that the person was “for now” severely injured, yet the\nrescue services were not allowed to approach, with a smiley face."},{"id":"a-hrc-59-crp-2-p0025","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"25","seq":27,"section":"VI. Case descriptions","text":"A woman from Antonivka settlement told the Commission that in December 2024,\nher 67-year-old husband went outside with his bicycle and was killed by a drone, just 100\nmeters away from their house. Her neighbours came to tell her that her husband was lying,\ndead, on the street. She rushed out, recognised him, and stressed, “I stayed with my husband’s\nbody from 9:30 am until 4 pm, where he was killed. He was lying face down with a hole to\nhis head. […]”. At least twice during that time, she had to take refuge in the neighbours’\npremises due to approaching drones. The morgue services managed to come only at 4 pm."},{"id":"a-hrc-59-crp-2-p0026","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"26","seq":28,"section":"VI. Case descriptions","text":"A 33-year-old man from Kherson city told the Commission that in January 2025, he\nwas walking on the street and saw a drone following him. He hid under a tree. The drone\nstopped above him. He managed to jump to the side just before the drone dropped an\nexplosive that caused five serious injuries in his leg. He required hospitalisation and\ncontinues to suffer from the consequences of the attack (see Telegram post, figure 3).\nFigure 3. Post on Russian Telegram channel, 11 January 2025\nThe sequence of screenshots from a video published in this post shows a drone dropping an\nexplosive near the civilian man, in a street of Kherson city (see para. 26)\nAttacks targeting civilian cars"},{"id":"a-hrc-59-crp-2-p0027","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"27","seq":29,"section":"VI. Case descriptions","text":"A large number of drone attacks have targeted all types of civilian cars on the move,\noften leading to the killing or injury of their drivers and passengers. In some of the incidents,\ndrone operators waited for the cars to stop and the passengers to open the doors before\ndropping the explosive. This likely augmented the lethal effect of the blast. Videos of such\nattacks have often been disseminated by Telegram channels with the generic message, “[…]\nAny transport in the red zone is a legitimate target.”"},{"id":"a-hrc-59-crp-2-p0028","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"28","seq":30,"section":"VI. Case descriptions","text":"A 63-year-old man from Antonivka settlement told the Commission that in August\n2024, he was hit by an explosive dropped from a drone as he stepped out of his vehicle. He\nwas injured and suffered from severe complications to his leg. After 30 days of\nhospitalisation and three surgeries, he had still not fully recovered and received disability\nstatus. A video of the attack was posted online, reiterating the above-mentioned message."},{"id":"a-hrc-59-crp-2-p0029","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"29","seq":31,"section":"VI. Case descriptions","text":"A 60-year-old man stated that in August 2024, he was driving through Poniativka\nvillage to distribute humanitarian aid and saw a drone dropping an explosive on his car. He\nfainted as a consequence of the blast. After regaining consciousness, he noticed that he could\nnot hear but managed to drive to his home village to seek help. He fainted again upon\nreaching the village. He had a concussion, needed hospitalisation and surgery to his ear, and\nsuffered from hearing impairment."},{"id":"a-hrc-59-crp-2-p0030","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"30","seq":32,"section":"VI. Case descriptions","text":"A woman from Kherson city recounted that in September 2024, she was driving\ntogether with her 60-year-old husband through Antonivka settlement when a drone hit their\nvehicle. Her husband died and she lost an eye as a result of the strike (see Telegram post,\nfigure 4).\nFigure 4. Post on Russian Telegram channel, 2 September 2024\nThe sequence of screenshots from a video published in this post shows the drone dropping\nan explosive on the civilian vehicle in Antonivka settlement (see para.30).\nAttacks targeting public transport"},{"id":"a-hrc-59-crp-2-p0031","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"31","seq":33,"section":"VI. Case descriptions","text":"Drones were also used to target public transport, including buses, minibuses, and\ntaxis, which led to civilian deaths and injuries. Footage of such attacks has been disseminated\non Telegram channels, often with the text, “Any transport in the red zone will be considered\na legitimate target” (see similarly para. 27)."},{"id":"a-hrc-59-crp-2-p0032","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"32","seq":34,"section":"VI. Case descriptions","text":"A 61-year-old woman from Poniativka village stated that in September 2024, she\nheard drones flying overhead when she was waiting at a bus stop. A minibus arrived, and as\nshe was stepping in, the drone dropped an explosive that fell nearby and injured her. She\nsuffered two fractures and needed hospitalisation."},{"id":"a-hrc-59-crp-2-p0033","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"33","seq":35,"section":"VI. Case descriptions","text":"A woman from Kherson city reported that in December 2024, her 41-year-old friend\nwas killed by a drone strike on a minibus. This was confirmed in a message posted by the\nGovernor of Kherson Province."},{"id":"a-hrc-59-crp-2-p0034","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"34","seq":36,"section":"VI. Case descriptions","text":"The Commission has examined and geolocated other videos, disseminated by Russian\nTelegram channels, of drone attacks targeting passenger buses as they were moving. For\ninstance, in September 2024, a Telegram channel released a video showing a drone dropping\nan explosive that detonated near the front right side of a bus. It came with the text, “Our\nhunters have been working since early morning”. In October 2024, the same channel posted\na video of a drone releasing an explosive on a bus and noted, “Today another smart guy\ndecided to slip through on a bus near the hunters. Target hit”. In November 2024, a Telegram\nchannel posted a video of a drone dropping an explosive hitting the middle of the roof of a\nbus. In January 2025, another video shows a drone releasing an explosive on a bus."},{"id":"a-hrc-59-crp-2-p0035","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"35","seq":37,"section":"VI. Case descriptions","text":"The drone attacks also targeted taxis. The Commission documented several videos of\nattacks on civilian cars, released in August, September, and October 2024, that were posted\nwith texts stating that taxis will be targeted, or which included threatening comments\nconcerning taxi drivers. A post uploaded on a Russian Telegram on 30 August 2024 displayed\na video of an attack on a civilian car and the text, “Another “taxi driver” who will not be\nfinishing any more rides”. A post uploaded on 4 October 2024, showing a drone strike on a\ncar, came with the text, “We gonna kill 'em all those taxi drivers, they ain't normal, to hell\nwith them”\nAttacks on ambulances"},{"id":"a-hrc-59-crp-2-p0036","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"36","seq":38,"section":"VI. Case descriptions","text":"Perpetrators also used drones to target ambulances, which have special protection\nunder international humanitarian law.13 As a result of attacks, ambulances could not\neffectively serve the most affected areas and were sometimes unable to promptly assist\npersons in dire need."},{"id":"a-hrc-59-crp-2-p0037","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"37","seq":39,"section":"VI. Case descriptions","text":"A 50-year-old woman from Veletenske village stated that in October 2024, after she\nhad been injured during the shelling of her neighbourhood and was losing a lot of blood, an\nambulance came but was unable to help her as it had been hit by a drone. A second ambulance\narrived later. She then saw one more drone that flew above her. It dropped an explosive near\nher and missed and dropped another explosive on the front of the ambulance, which caught\nfire. The woman saw how a nurse managed to escape, but the driver burnt in the ambulance."},{"id":"a-hrc-59-crp-2-p0038","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"38","seq":40,"section":"VI. Case descriptions","text":"A 45-year-old man from Stanislav village recounted that in November 2024, a drone\ndropped an explosive near him as he was riding a moped, badly injuring his leg. An\nambulance arrived, and while he was receiving first aid, a drone dropped two explosives on\nthe ambulance."},{"id":"a-hrc-59-crp-2-p0039","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"39","seq":41,"section":"VI. Case descriptions","text":"Two staff members of Kherson’s Oncology Hospital reported that in November 2024,\ntwo ambulances parked on the grounds of the hospital were destroyed by drone attacks. The\nexplosions caused a fire which burnt the ambulances. Around the day of the attack, Russian\nTelegram channels posted videos of the attack and one photograph of two visibly burnt\nambulances, with the titles, “Kherson. Red Zone. Oncology. […]” Photographs shared by\nstaff of the hospital and Ukrainian authorities confirm the destruction of the same\nambulances."},{"id":"a-hrc-59-crp-2-p0040","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"40","seq":42,"section":"VI. Case descriptions","text":"The Commission also examined videos dated August and October 2024, which show\ndrones aiming at ambulances while they are driving on the road (see Telegram post, figure\n5).\nFigure 5. Post on Russian Telegram channel, 28 August 2024\nThe sequence of screenshots from a video released in this post shows a drone attack\ntargeting an ambulance that slows down and stops in a street of Kherson city, and\npassengers running out of the ambulance (see paras. 36-40)."},{"id":"a-hrc-59-crp-2-p0041","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"41","seq":43,"section":"VII. Consequences for the life of civilians in the affected areas","text":"The population of Kherson city and other localities along the right bank of Dnipro\nRiver has been living for months in a climate of permanent fear due to the recurrent attacks.\nInterlocutors described severe psychological effects and a sense that any movement outside\ninvolves serious risks for personal safety. Several residents called the road running through\nKherson city to Antonivka settlement “the road of death”. A woman stated that on her way\nto work, she regularly sees drones dropping explosives, “we walk and we risk it – it is\nawful!”. A man said that drones “target anywhere there is movement”. Residents stay\nindoors as much as possible, go out on cloudy days, or hide under the foliage of trees, to\navoid being spotted by drones. A woman, however, said that even then, “drones are still\nattacking people no matter what”."},{"id":"a-hrc-59-crp-2-p0042","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"42","seq":44,"section":"VII. Consequences for the life of civilians in the affected areas","text":"In addition to the explicit videos of attacks mentioned above, text disseminated by\nRussian Telegram channels issuing threats of attacks against any form of movement or\ntransport across a large urban area have contributed to spreading terror among the population\n(see paras. 19, 27, and 31). Some of the posts refer to drone attacks as “hunting”, which is\nalso how residents experience the attacks. On 19 August 2024, a video of a drone that chased\na civilian car and injured the passenger was posted with the text, “The hunt is in full swing”\n(see also Telegram post, figure 6). A senior practitioner of a Kherson city hospital stated,\n“Russian Federation soldiers behave like this is a safari […]; they are simply chasing and\nhunting civilians who are on their way to work or walking their dogs. They drop explosives\nfrom drones like it is a video game. […].” One of the Telegram channels, in its general\nchannel description, even states “We instil fear in the Kherson direction” (“Наводим страх\nна Херсонском направлении”).\nFigure 6. Post on Russian Telegram channel, 22 September 2024\nScreenshot of a Telegram post with a video of an attack on a bus and text stating,\n“Kherson. Red zone. Good morning, friends! Our hunters are working since early\nmorning.” (see para. 42)"},{"id":"a-hrc-59-crp-2-p0043","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"43","seq":45,"section":"VII. Consequences for the life of civilians in the affected areas","text":"In addition, Russian armed forces have targeted many objects and sites with drones,\nresulting in killing or injuring civilians present there, as well as damage or destruction of\ncivilian buildings, houses, and vehicles, as well as infrastructure, including for power\ngeneration and transmission, and gas installations. They targeted internet antennas, depriving\npeople of means of communication and information. Drones also hit hospitals, including the\ngrounds of Kherson’s Oncology Hospital, regardless of their protected status under\ninternational humanitarian law."},{"id":"a-hrc-59-crp-2-p0044","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"44","seq":46,"section":"VII. Consequences for the life of civilians in the affected areas","text":"The recurrent attacks and risks thereof led to the closure or the limited functioning of\nshops and services that are essential for the daily life of the residents. In addition to\nambulances, drones attacked fire trucks, emergency, and repair crews. According to\nresidents, many areas were no longer supplied with electricity, gas, heating, or water. In some\nsituations, residents undertook repairs themselves, bearing considerable risks. In other cases,\nrepairs were impossible."},{"id":"a-hrc-59-crp-2-p0045","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"45","seq":47,"section":"VII. Consequences for the life of civilians in the affected areas","text":"Public transport has no longer been able to operate in certain areas or was forced to\nreduce its services. Even taxis have stopped serving areas at risk of attacks. Parked cars have\nalso been targeted. The systematic attacks on all forms of transport have led to an absence of\nany means of transport in the affected areas, prompting residents to go on foot, at times over\nlong distances, exposing them to risks of attacks (see paras. 14 and 22-26)."},{"id":"a-hrc-59-crp-2-p0046","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"46","seq":48,"section":"VII. Consequences for the life of civilians in the affected areas","text":"Local authorities and residents living along the right bank of Dnipro River also\nreported that drones had been dropping mines in various localities, as well as on the roads\nconnecting them. This poses additional dangers to civilians. According to a local authority,\na 71-year-old man stepped on a mine, due to which part of his leg had to be amputated.\nAnother local authority recounted that in November 2024, while helping with the evacuation\nof two men injured by drone, she stepped on a mine and lost the lower part of her leg."},{"id":"a-hrc-59-crp-2-p0047","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"47","seq":49,"section":"VII. Consequences for the life of civilians in the affected areas","text":"Russian Telegram channels regularly upload posts calling for the civilian population\nto leave the area altogether (see Telegram post, figure 7). Such text started to appear in\nAugust 2024 and has been shared with an increased frequency since October 2024. For\ninstance, on 27 August 2024, a Telegram channel posted, “Our advice. Get out of here. Or\nwait. We will definitely come.” On 3 October 2024, another Telegram post stated, “[…] Get\nout of the city before the leaves fall, you who are destined to die. Save yourselves.” The\nfollowing standard message has been reposted for months, “Civilians to be alert and careful.\nLimit your movement and leave the area if possible.”"},{"id":"a-hrc-59-crp-2-p0048","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"48","seq":50,"section":"VII. Consequences for the life of civilians in the affected areas","text":"The recurrent character of the attacks, the spread of terror among the population, the\ndamage caused to civilian objects and infrastructure by drones, and the absence or limited\nfunctioning of services, have rendered most of the affected areas unlivable, forcing many to\nflee. Some relocated to places deemed safer within Kherson Province, further away from the\nriver front. Interlocutors described buildings that are almost empty. According to residents,\nthose who did not leave are mainly older persons who had nowhere to go, or those who\nneeded to care for their relatives.\nFigure 7. Post on Russian Telegram channel, 22 September 2024\nScreenshot of a Telegram post with text stating, “Kherson. Red zone. Get out of the city\nbefore the leaves fall, you who are destined to die. Save yourselves. Or, as a last resort,\nmove to the northern district, beyond the railway.” (see para. 47)"},{"id":"a-hrc-59-crp-2-p0049","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"49","seq":51,"section":"VIII. Perpetrators and weapons used","text":"The Commission is not aware of any steps taken by Russian authorities to halt\nmonths-long drone attacks against civilians in various localities of Kherson Province and the\npublic dissemination of violent content. The Russian Telegram channels that have posted\nfootage of attacks and threatening text have mentioned drone units of the 18th Combined\nArms Army and the “Dnepr” Group of Forces of the Russian armed forces as responsible for\nmany of the drone attacks. The Commission’s investigations have confirmed that these\nmilitary entities have been operating in Kherson Province and have identified some of their\ncommanders, as well as some drone units involved in the attacks."},{"id":"a-hrc-59-crp-2-p0050","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"50","seq":52,"section":"VIII. Perpetrators and weapons used","text":"Several Russian Telegram channels have contributed to spreading terror among the\npopulation by posting videos showing drones chasing civilians, the resulting harm to body\nand health, as well as threatening text. The Telegram channel that has been the most active\nin regularly disseminating material and has 50,000 subscribers has been officially registered\nwith the Federal Service for Supervision of Communications, Information Technology and\nMass Media, as legally prescribed in the Russian Federation for channels with over 10,000\nsubscribers (see para. 17).14 Several other Telegram channels have disseminated similar\nmaterial. Many posts shared on these channels point to links between them and units of the\nabove-mentioned 18th Combined Arms Army and the “Dnepr” Group of Forces."},{"id":"a-hrc-59-crp-2-p0051","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"51","seq":53,"section":"VIII. Perpetrators and weapons used","text":"The same Telegram channels have uploaded posts showing the drones used by\nRussian army units in Kherson Province. Several types of drones have been used. The ones\nmost frequently visible are drones manufactured by Da-Jiang Innovations (DJI), recognizable\nby their frame, remote controllers, and original packaging that can be regularly seen in\nTelegram posts spread over months. Many of the videos of drone attacks have head-up\ndisplays matching those of DJI models. DJI drones are civilian drones that are widely\ncommercially available. Their use by both parties during the armed conflict in Ukraine has\nbeen widely reported,15 for reconnaissance and surveillance, or after modifications into\nweaponized drones that can drop explosives on targets."},{"id":"a-hrc-59-crp-2-p0052","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"52","seq":54,"section":"VIII. Perpetrators and weapons used","text":"DJI is a Chinese-registered company. It has declared that its products are not designed\nfor military applications.16 The company stated that on 26 April 2022, it had suspended all\ncommercial activities in the Russian Federation and Ukraine, in light of the ongoing\nhostilities, and contractually forbade any sales by dealers to either country and for combat\nuse.17 In addition, in 2023 and in 2024, the People’s Republic of China implemented\ntemporary export controls on specific drones.18"},{"id":"a-hrc-59-crp-2-p0053","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"53","seq":55,"section":"VIII. Perpetrators and weapons used","text":"Concerning suicide drones, some of the same Telegram channels reported that drone\noperators have been using VТ-40 drones produced by the Russian Federation (see para. 10)."},{"id":"a-hrc-59-crp-2-p0054","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"54","seq":56,"section":"IX. Conclusions and recommendations","text":"Russian armed forces have carried out attacks that killed or injured civilians,\nusing drones, in Kherson city and other localities of Kherson Province, in violation of\nthe fundamental principle of international humanitarian law that attacks may only be\ndirected at military objectives.19 The drone operators used video feeds transmitted in\nreal time by the cameras embedded in the drones, focused on targets that were visibly\ncivilian, and dropped explosives on them. The evidence collected leaves no doubt that\nthe perpetrators intended to carry out those acts. The Commission has therefore\nconcluded that Russian armed forces have perpetrated the war crimes of intentionally\ndirecting attacks against civilians in Kherson and other settlements of the right bank of\nKherson Province.20 It has also concluded that the publishing of videos of civilians being\nkilled and injured amounts to the war crime of outrages upon personal dignity. 21"},{"id":"a-hrc-59-crp-2-p0055","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"55","seq":57,"section":"IX. Conclusions and recommendations","text":"The drone attacks committed by Russian armed forces have been widespread\nand systematic (see paras. 14-16). They have repeatedly targeted multiple civilian\ntargets, for months, in several localities situated across a wide geographic area. The\nattacks followed a regular pattern and the same modus operandi, demonstrating that\nthey were planned, directed and organized, and thus part of an organisational policy.\nTheir recurrence since July 2024 indicates that Russian authorities have developed the\nnecessary capacities, as well as mobilised and allocated resources in terms or personnel\nand materiel. Moreover, Russian Telegram channels have disseminated hundreds of\nvideos displaying the crimes, as well as posts with text announcing more attacks.\nConsidering that the footage is generated by the drones themselves, this and other\nfactors mentioned above illustrate that the commission of attacks against civilians was\nencouraged and promoted. There is no information suggesting that the Russian military\nand civil authorities have taken any steps to prevent or stop the crimes during this long\nperiod. The combination of these elements leads the Commission to conclude that\nRussian authorities have committed murder of civilians in Kherson Province, as part\nof a coordinated state policy, and hence, as crimes against humanity.22"},{"id":"a-hrc-59-crp-2-p0056","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"56","seq":58,"section":"IX. Conclusions and recommendations","text":"The civilian population in the areas affected by drone attacks lives in constant\nfear. No one feels safe as a consequence of the nature and broad range of targets of\nattacks, and the circumstances in which they occur, their frequency, intensity, and\ngeographic spread. Residents take risks every time they go outside and have been in\nsituations where they had to run and seek cover as drones were chasing them. Many\nwait for cloudy days to go out, or seek cover under trees, where possible. The fear is\ncompounded as emergency services are often unable to reach in time due to drone\nattacks. Russian Telegram channels have disseminated posts announcing further\nattacks using the term “hunting”. They referred to a wide geographic area, which they\ncall red zones, where any form of movement will be targeted. 23 The circumstances of\nthe attacks, the videos, and the explicit threatening text demonstrate that Russian\narmed forces and those supporting them have committed acts or threats of violence the\nprimary purpose of which is to spread terror among the civilian population, in violation\nof international humanitarian law.24"},{"id":"a-hrc-59-crp-2-p0057","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"57","seq":59,"section":"IX. Conclusions and recommendations","text":"Finally, the conduct of the perpetrators had the effect of forcing large numbers\nof the population of different affected localities to leave.25 The scale and intensity of the\ndrone attacks against civilians and civilian objects, their widespread and systematic\ncharacter, the prevailing climate of fear, and the ensuing coercive environment, have\ncompelled thousands to flee. The destruction of houses and of basic infrastructure, the\ntargeting of all means of transport, and attacks against emergency and rescue services,\nhave rendered the affected areas unliveable and left many residents with no other choice\nthan to seek safer locations. Moreover, Russian Telegram channels have repeatedly\ndisseminated videos showing the attacks and posts explicitly exhorting the population\nto leave. These elements combined suggest a coordinated state policy, on the part of the\nRussian authorities, to force the population of Kherson city and the other targeted\nlocalities along the right bank of the Dnipro River, to leave the area. The Commission\ntherefore concludes that Russian armed forces may have committed the crime against\nhumanity of forcible transfer of population.26"},{"id":"a-hrc-59-crp-2-p0058","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"58","seq":60,"section":"IX. Conclusions and recommendations","text":"Based on the findings in the current paper, the Commission sets out its\nrecommendations below."},{"id":"a-hrc-59-crp-2-p0059","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"59","seq":61,"section":"IX. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation:\n(a)       Immediately end the drone attacks against civilians;\n(b)       Immediately end drone attacks on civilian objects, in particular those with\nspecial protection under international humanitarian law, such as hospitals and medical\ntransports;\n(c)       Immediately stop any acts that spread terror among the civilian\npopulation and that lead to forcible displacement;\n(d)      Ensure that all perpetrators involved in the commission of such crimes, in\nparticular commanders and other superiors and those ordering, soliciting or inducing\ntheir commission, are held accountable, in accordance with international standards;\n(e)      Ensure that all those who broadcasted videos of attacks, photographs, and\nthreatening text, and thereby committed or contributed to the commission of the above-\nmentioned crimes, are held accountable, in accordance with international standards."},{"id":"a-hrc-59-crp-2-p0060","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"60","seq":62,"section":"IX. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)      Ensure that the victims of drone attacks are included in the current\nsupport systems;\n23 See for example, ICTY, The Prosecutor v. Milosevic, Appeal Judgement, 12 November 2009, paras.\n52-54.\n24 Additional Protocol I to the Geneva Conventions, art. 51(2).\n25 See for example ICC, The Prosecutor v. Bosco Ntaganda, Judgment, Case No. ICC-01/04-02/06 , 8\nJuly 2019, paras. 1056, 1060, 1061, and 1067.\n(b)      Make available the best possible physical and mental healthcare services\nclose to the most affected areas to ensure that those who still live there can receive\nadequate treatment;\n(c)     Provide comprehensive support to those who were displaced as a\nconsequence of drone attacks."},{"id":"a-hrc-59-crp-2-p0061","rec_id":"recuDQl6wBnWJRbIS","symbol":"A/HRC/59/CRP.2","n":"61","seq":63,"section":"IX. Conclusions and recommendations","text":"The Commission recommends that other States and regional and international\norganizations:\n(a)      Contribute both financially and with technical advice to the government\nof Ukraine for the provision of comprehensive support for victims and their families,\nand for persons that have been victims of or were displaced following drone attacks,\nincluding health, housing and psycho-social support."},{"id":"a-80-497-u0000","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":null,"seq":0,"section":null,"text":"Note by the Secretary-General*\nThe Secretary-General has the honour to transmit to the General Assembly the report\nof the Independent International Commission of Inquiry on Ukraine, submitted in accordance\nwith paragraph 27 of Human Rights Council resolution 58/24, on the situation of human\nrights in Ukraine stemming from the Russian aggression.","unnumbered":true},{"id":"a-80-497-u0001","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":null,"seq":1,"section":null,"text":"Summary\nThe Independent International Commission of Inquiry on Ukraine submits the present\nreport to the 80th session of the General Assembly.\nThe Commission’s latest investigations have established that in two types of\nsituations, Russian authorities have systematically coordinated actions in order to drive out\nUkrainian civilians from their place of residence.\nFirst, the evidence collected demonstrates that recurrent attacks with short-range\ndrones by Russian armed forces against civilians in frontline areas have killed and injured\nmany, caused large-scale destruction, and created a coercive environment compelling\nthousands to flee. The Commission has concluded that these acts amount to the crimes\nagainst humanity of murder and of forcible transfer of population. Second, the Commission\nhas also found that deportations and transfers of civilians from areas occupied by Russian\nauthorities constitute war crimes.\nFor over one year, Russian armed forces have been directing drone attacks against an\nextensive range of civilian targets, in an area spanning over 300 kilometres along the right\nbank of the Dnipro River, across Dnipropetrovsk, Kherson, and Mykolaiv oblasts. The\nattacks targeted civilian persons, houses or buildings, humanitarian distribution points, and\ncritical energy infrastructure servicing civilians. They even hit first responders – including\nambulances and fire brigades, regardless of their special protection under international\nhumanitarian law, obstructing their intervention. Many of the attacks struck the same objects\nrepeatedly, deliberately setting them on fire. Residents of the targeted localities described\nlife conditions as unbearable. A man stated, “we are hit every day, drones fly at any time -\nmorning, evening, day or night, constantly”.\nThe cases documented demonstrate that military units of Russian armed forces\ndeployed over a large geographic area and operating from the left bank of the Dnipro River,\nunder a centralized command, have used the same modus operandi to intentionally target\ncivilians and civilian objects and cause harm and destruction.\nConsistent with the findings outlined in its May 2025 conference room paper, the\nCommission has concluded that Russian armed forces’ short-range drone attacks, in a wider\ngeographic area than previously established, amount to the crime against humanity of murder\nand the war crimes of intentionally directing attacks against civilians and civilian objects.\nThe Commission has further concluded that these attacks were committed as part of a\ncoordinated policy to drive out civilians from those territories and amount to the crime\nagainst humanity of forcible transfer of population. The attacks have spread terror among the\ncivilian population and violated the human right to life and other fundamental human rights.\nAs regards the second issue investigated, the Commission has documented that\nRussian authorities have coordinated actions to deport or transfer civilians from areas that\ncame under their control in Zaporizhzhia Oblast. This amounts to war crimes.\nIn 2022 and 2023, Russian authorities transferred civilians to territories under\nUkrainian Government control, after accusing them of carrying out activities against the\nRussian Federation. They brought the victims to a checkpoint then positioned at the end of\nthe area they controlled. There, they forced them to walk through a 10 to 15 km-wide highly\ndangerous operational area to reach the Ukrainian checkpoint.\nIn 2024 and 2025, Russian authorities deported Ukrainian civilians from occupied\nareas in Zaporizhzhia Oblast to Georgia, referring to Russian Federation legislation on the\nlegal status of certain categories of foreign citizens. Perpetrators transported them to the\nborder between the Russian Federation and Georgia and ordered them to cross.","unnumbered":true},{"id":"a-80-497-u0002","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":null,"seq":2,"section":null,"text":"With respect to both deportations and transfers, perpetrators usually detained the\nvictims, subjected some of them to torture, and confiscated their documents and belongings.\nThese acts have inflicted severe mental pain and suffering and amount to inhuman treatment\nas a war crime and a violation of human rights.\nThe circumstances of the documented cases demonstrate a profound disregard for\nhuman life and dignity. Many of the victims have endured physical trauma and all reported\npsychological shock. The victims have been forced to separate, at times on very short notice,\nor no notice at all, from their families, residences, work, and belongings. They described an\nunbearable feeling of having lost everything and having to restart their lives from scratch.\nVictims felt acute anguish for the members of their families who were left behind.\nThe Commission also examined allegations by Russian authorities of drone attacks\nby Ukrainian armed forces against civilian targets in Russian occupied areas. It was unable\nto conclude its investigation due to lack of access to the territory, concerns relating to the\nsafety of witnesses, and in the absence of response to its questions to the Russian authorities.","unnumbered":true},{"id":"a-80-497-p0001","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"1","seq":3,"section":"I. Introduction","text":"In April 2025, the Human Rights Council extended the mandate of the Independent\nInternational Commission of Inquiry on Ukraine through resolution 58/24. 1 The Commission\nis composed of Erik Møse (Chair), Pablo de Greiff, and Vrinda Grover."},{"id":"a-80-497-p0002","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"2","seq":4,"section":"I. Introduction","text":"The Commission’s work is guided by the principles of independence, impartiality,\nobjectivity, and integrity. It adopts a victim-centred approach and a strict respect of the “do\nno harm” principle."},{"id":"a-80-497-p0003","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"3","seq":5,"section":"I. Introduction","text":"The present report to the General Assembly is to be read in conjunction with the\nCommission’s May 2025 conference room paper.2 The Commission travelled to Ukraine and\nrelied on interviews with 226 persons (117 women and 109 men), including victims,\nwitnesses, local authorities, medical personnel, first responders, humanitarian workers, local\norganisations, and experts. In addition, it has examined over 500 publicly available videos of\ncrimes described in this report, of which it geolocated 247, as well as photographs, satellite\nimagery, and relevant documents."},{"id":"a-80-497-p0004","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"4","seq":6,"section":"I. Introduction","text":"The Commission expresses its gratitude to all those who shared valuable information.\nIt appreciates the cooperation of the Government of Ukraine. The Russian Federation\ncontinued not to recognise the Commission and 35 written requests for access, information,\nand meetings, remained unanswered."},{"id":"a-80-497-p0005","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"5","seq":7,"section":"II. Overview","text":"Over three years of armed conflict had a devastating toll on civilian life and population\nin Ukraine. This is particularly the case in frontline areas, where 69 per cent of the civilian\ncasualties have occurred, according to the recent update of the Office of the High\nCommissioner for Human Rights (OHCHR). 3 The Commission has continued to document\ngrave crimes and corresponding human rights violations. Its recent investigations focused on\nareas in the vicinity of the Dnipro River and on occupied areas. The Commission found that\nin two types of situation, Russian military and civilian authorities have systematically\ncoordinated actions to drive out the Ukrainian civilian population."},{"id":"a-80-497-p0006","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"6","seq":8,"section":"II. Overview","text":"The frontline along the Dnipro River has been largely static for almost three years.\nThe Russian armed forces have carried out attacks with short-range drones on the right bank\nof the river, which is under Ukrainian Government control, with full disregard for the civilian\npopulation, killing and injuring civilians and causing damage and destruction. The ensuing\ncoercive environment compelled thousands of civilians to flee. The Commission has\nconcluded that the Russian armed forces have committed the crime against humanity of\nforcible transfer of populations (see part A).4"},{"id":"a-80-497-p0007","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"7","seq":9,"section":"II. Overview","text":"In areas of Zaporizhzhia Oblast which came under Russian control, Russian\nauthorities have coordinated actions to deport or transfer civilian persons to third states or to\nterritories under Ukrainian Government control. These acts demonstrate that the Russian\nauthorities have driven civilian persons from their places of residence and amount to war\ncrimes (see part B).5"},{"id":"a-80-497-p0008","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"8","seq":10,"section":"A. Drone attacks against civilian targets on the right bank of the Dnipro","text":"In its May 2025 conference room paper, the Commission concluded that widespread\nand systematic drone attacks against civilians, in an area stretching over 100 km in Kherson\nOblast, amount to the crime against humanity of murder, the war crimes of attacking civilians\nand of outrages upon personal dignity, and that they have been committed with the primary\npurpose to spread terror among the civilian population.6 At the time of the publication of the\npresent report, Russian armed forces continued to attack civilians with remotely piloted short-\nrange drones in the Ukrainian-controlled right bank of Dnipro River, in Kherson Oblast."},{"id":"a-80-497-p0009","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"9","seq":11,"section":"A. Drone attacks against civilian targets on the right bank of the Dnipro","text":"Building on its previous findings, the Commission’s new investigations show that\nRussian armed forces have used drones to target civilians in a much larger area than\npreviously reported. It stretches over 300 km along the Dnipro River and over the Dnipro\nGulf, across Dnipropetrovsk, Kherson, and Mykolaiv oblasts. In this area, the river generally\nconstitutes a natural separation between both forces. In addition to attacking persons, Russian\narmed forces have relentlessly struck a wide array of civilian objects with drones, including\ncivilian houses, buildings, gathering points, humanitarian distribution points, and objects of\ncritical infrastructure that service civilians. The attacks have often targeted the same objects\nrepeatedly, and have even released flammable substances, causing fires and large-scale\ndestruction. Drone operators have attacked first responders – ambulance crews, fire brigades,\nand their vehicles, regardless of their special protection under international humanitarian\nlaw,7 as well as repair crews."},{"id":"a-80-497-p0010","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"10","seq":12,"section":"A. Drone attacks against civilian targets on the right bank of the Dnipro","text":"These attacks with drones have continued for over one year and have intensified in\n2025. According to OHCHR’s latest updates, attacks with short-range drones near the\nfrontline became the leading cause of civilian casualties.8 According to local authorities,\nsince July 2024, over 200 civilians have been killed and over 2,000 civilians were injured in\nsuch attacks in the three oblasts; most victims are men. Almost 3,000 houses have been\ndamaged or destroyed, also by drones."},{"id":"a-80-497-p0011","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"11","seq":13,"section":"A. Drone attacks against civilian targets on the right bank of the Dnipro","text":"Russian military units deployed on the occupied left bank of the Dnipro River have\ncommitted the attacks. The Commission has identified several drone units, their operators,\nand associated military units and commanders, as well as other persons cooperating with\nthem. All the types of short-range drones used in these attacks are equipped with live\nstreaming cameras that focus on particular targets, leaving no doubt about the knowledge and\nintent of the perpetrators. Russian Telegram channels have continued to disseminate videos\nof the attacks, as well as mocking text posts with threats of further attacks."},{"id":"a-80-497-p0012","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"12","seq":14,"section":"A. Drone attacks against civilian targets on the right bank of the Dnipro","text":"The documented cases demonstrate the intention of the perpetrators to kill and inflict\nharm and large-scale destruction. The attacks have spread terror among the population and\nhave rendered civilian life unbearable. Entire localities have suffered heavy structural\ndamage and have been temporarily or permanently deprived of services and basic utilities, as\nwell as of any form of emergency support when it is most needed. A woman from a\nparticularly affected area noted, “It is a lottery – will a drone fly in or not? You go to bed\nand you don’t know if you will be killed or wake up in the morning.” Survivors invoked\npsychological trauma and fear. The ensuing coercive environment has compelled thousands\nto leave."},{"id":"a-80-497-p0013","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"13","seq":15,"section":"A. Drone attacks against civilian targets on the right bank of the Dnipro","text":"The Commission has also investigated allegations by Russian authorities of drone\nattacks committed in Russian-occupied areas but has been unable to conclude its\ninvestigations due to lack of access to the territory, concerns relating to the safety of\nwitnesses, and in the absence of response to its questions addressed to the Russian\nFederation."},{"id":"a-80-497-p0014","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"14","seq":16,"section":"1. Attacks against a wide array of civilian targets","text":"Russian armed forces have continued to attack civilians with drones on the right bank\nof Dnipro River in Kherson Oblast. They chased them, at times over long distances, while\nthey were near their houses or in the street, on foot or using transport, and dropped explosives\non them or struck them with suicide drones. In addition, the Commission found new evidence\nthat Russian armed forces have committed attacks using the same tactic against civilians in\nwaterfront localities of Dnipropetrovsk and Mykolaiv oblasts. According to residents, in\ncertain areas, the attacks have intensified since the publication of the Commission’s May\n2025 report. Victims and witnesses pointed to drones flying even when the weather is bad, at\nnight, and increasingly striking in localities further away from the river front. In July 2025,\na resident stated, “we don’t have a day without injuries in Kherson”."},{"id":"a-80-497-p0015","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"15","seq":17,"section":"1. Attacks against a wide array of civilian targets","text":"In the three oblasts, drone operators have targeted, in addition to civilian persons, a\nwide array of civilian objects and critical infrastructure, as well as first responders and repair\ncrews. These findings provide further evidence of the widespread and systematic character\nof the attacks."},{"id":"a-80-497-p0016","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"16","seq":18,"section":"1. Attacks against a wide array of civilian targets","text":"Telegram channels run by perpetrating units or by persons close to them have\ncontinued to post videos of drone attacks on a broad range of targets that bear no indication\nof being other than civilian. Text posts on these channels have announced an expansion of\nthe targeted areas and exhorted the civilian population to leave. In May 2025, for instance, a\nTelegram channel posted a map of Kherson city and stated, “Kherson. Red zone. Friends,\ngreat news! From now on, each sector is unique and has specific tasks and designated teams.\nThe city will be dismantled – brick after brick – thanks to the successful 4049 command\nleadership. Stay tuned for updates.” In June 2025, a video showing a drone flying towards\nan electric substation, followed by a fire, came with the text, “[…] Substations are being\ntotally destroyed, maximum damage is being inflicted. The strike zone will expand along the\nborders of the region, the number will increase several times.[…]”."},{"id":"a-80-497-p0017","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"17","seq":19,"section":"1. Attacks against a wide array of civilian targets","text":"The Commission’s investigations found no indication of military presence at or in\nproximity to the targeted locations. The fact that drone operators carry out extensive\nobservation of the affected areas allows them to identify the civilian character of their targets."},{"id":"a-80-497-p0018","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"18","seq":20,"section":"2. Attacks against residential houses and apartment buildings","text":"The Commission has interviewed multiple witnesses of drone attacks on residential\nhouses and apartment buildings in the affected localities and has reviewed videos of attacks\nposted on Russian Telegram channels. Drones hit roofs, windows, or balconies and often set\nthe houses on fire. First responders and repair crews, themselves targeted by drones, were\noften unable to intervene (see paras. 29-33). The attacks led to the damage or destruction of\ncivilian residences; civilians present were killed or suffered from fractures, cuts, concussions,\nand burns, some of them with long-term consequences. Common elements of the investigated\nsituations demonstrate that perpetrators intended to hit, damage, and destroy civilian\nresidences: often, drones struck merely after spotting signs of movement around civilian\nresidences; frequently, several drones attacked the same house, together or in sequence; and\nmany of the attacks were clearly intended to cause fires."},{"id":"a-80-497-p0019","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"19","seq":21,"section":"2. Attacks against residential houses and apartment buildings","text":"Drones often hovered over the targeted areas for prolonged periods of time, observing.\nVictims and witnesses stated that at the time when drones hit their houses, they were engaged\nin ordinary activities such as spending time in their yards, gardening, caring for their animals,\ndisposing of trash, or parking their vehicles. A woman said, “There are attacks on houses,\nroofs. If they see that there are people living here, see something in the yard, then there will\ndefinitely be a drone strike”. She added that she cannot hang her laundry outside, because\nthis will show that “there are people living here”. In a video interview by the Russian media\n9 404 is a derogatory formulation sometimes used by Russian authorities and media to refer to\nUkraine.\nin February 2024, drone operators focusing on Kherson Oblast noted that they observe all\nterritories and destroy what could hinder them."},{"id":"a-80-497-p0020","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"20","seq":22,"section":"2. Attacks against residential houses and apartment buildings","text":"In some cases, drones pursued civilians to their homes and then attacked the houses.\nA woman from Veletenske village, Kherson Oblast, stated that in August 2024, she was\nparking her car at her home and noticed a drone above her head. She sought refuge in the\ngarage, but the drone dropped an explosive that hit the roof and injured her. She suffered a\nconcussion, cuts, and was temporarily deafened as a result of the blast. Later the same day,\ntwo more drones hit her house and badly damaged it. She moved out after the incident."},{"id":"a-80-497-p0021","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"21","seq":23,"section":"2. Attacks against residential houses and apartment buildings","text":"Perpetrators frequently attacked the same house or apartment with several drones in a\ncoordinated sequence, or slammed two or more suicide drones into the houses. In many of\nthe investigated situations, a first drone pierced a hole on the roof and a second one dropped\nan explosive through it, causing fires. Additional drones hovered over the area and obstructed\nefforts to extinguish them. According to local authorities, witnesses, and first responders,\nsome drones carried improvised incendiary mixtures in a bottle that they dropped during\nattacks, causing strong fires. A local authority from Dnipropetrovsk Oblast stated that such\nfires are “impossible to put out”."},{"id":"a-80-497-p0022","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"22","seq":24,"section":"2. Attacks against residential houses and apartment buildings","text":"A woman from Dobra Nadiia village, Dnipropetrovsk Oblast, told the Commission\nthat on 8 July 2025, a drone flew into her house through the window and dropped an\nincendiary device that lit a fire. She was then on her way to work, while her 60-year-old\nmother was working in the garden. The neighbours alerted her; she returned home\nimmediately, and they tried to extinguish the fire. However, it spread quickly and another\ndrone flew over, preventing their efforts. She stated, “drones do not allow us to put out fires\n– they keep watch, and they will drop an explosive on people”."},{"id":"a-80-497-p0023","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"23","seq":25,"section":"2. Attacks against residential houses and apartment buildings","text":"A 47-year-old woman from Dniprovske village, Mykolaiv Oblast, reported that\ndrones had struck her house on three occasions, and an ensuing fire destroyed it. She\ndescribed herself as homeless as a result. A first attack damaged three windows. During a\nsecond attack, the drone did not explode and was successfully removed. A third attack\noccurred in her absence, in August 2025. Her neighbour told the Commission that she heard\nthe drone flying, followed by a loud explosion. She tried to put out the fire, together with\nother neighbours, using buckets of water, without success. She stated, “I saw the house burn\ndown in front of my eyes and there was nothing I could do”."},{"id":"a-80-497-p0024","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"24","seq":26,"section":"2. Attacks against residential houses and apartment buildings","text":"Videos of attacks on houses posted on Russian Telegram channels show drones\ndropping explosives or suicide drones slamming into houses, followed by one or more\nobserver drones filming the fires. One such video was posted in December 2024, with the\nmessage, “We burnt another house” with a derogatory pig nose icon."},{"id":"a-80-497-p0025","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"25","seq":27,"section":"3. Attacks against non-residential civilian buildings and civilian gathering points","text":"The Commission has investigated incidents in which drone operators targeted non-\nresidential civilian buildings, their grounds, and gathering points for civilians. These include\nhospitals, other medical facilities, and humanitarian personnel, 10 that have special protection\nunder international humanitarian law, as well as a school, a market, and civil administration\nbuildings. The attacks led to injuries and deaths among civilians, and to temporary or\npermanent disruptions of the services provided in these places, thereby severely affecting the\ncivilian population."},{"id":"a-80-497-p0026","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"26","seq":28,"section":"3. Attacks against non-residential civilian buildings and civilian gathering points","text":"A local authority from Illinka village, Dnipropetrovsk Oblast, told the Commission\nthat in June 2025, a rural medical point had been struck and destroyed by a drone (see para.\n30). A doctor working in a hospital in Kherson Oblast reported that drone attacks hit the\nhospital and its immediate vicinity on several occasions in 2025, damaging the electrical\npower lines and the gas boiler. When drones flew too close, the medical staff were forced to\ninterrupt the work and take shelter."},{"id":"a-80-497-p0027","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"27","seq":29,"section":"3. Attacks against non-residential civilian buildings and civilian gathering points","text":"According to residents of a village in Kherson Oblast, attacks with drones targeted\nseveral times a “point of invincibility” – the only service that was still available in the village.\nCivilians gathered there to recharge phones, torches, and connect to the internet."},{"id":"a-80-497-p0028","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"28","seq":30,"section":"3. Attacks against non-residential civilian buildings and civilian gathering points","text":"Humanitarian distribution points and personnel, organized after the closure of\nnumerous shops, have also been attacked with drones. A woman from Solonchaky village,\nMykolaiv Oblast, told the Commission that in November 2024, a drone dropped an explosive\nin an area where civilians had gathered to receive humanitarian aid. Six civilians, including\none woman and five men, were injured following the explosion. One of them, a 30-year-old\nman who was distributing aid, died from his injuries. One of the witnesses stated that some\nshrapnel remains in her hand since that day."},{"id":"a-80-497-p0029","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"29","seq":31,"section":"4. Attacks against first responders","text":"Attacks with drones have recurrently targeted teams of first responders: medical staff\nand fire brigades, as well as ambulances and fire engines, regardless of visible distinctive\nmarks on vehicles and their special protection under international humanitarian law. The\nattacks occurred at their workplaces, on the road, and during interventions, and resulted in\ninjuries and deaths of personnel, as well as damage or destruction of specialized vehicles.\nFirst responders have often been unable to reach those in need, because of the permanent\nrisks, or the reduced availability of personnel and vehicles. This deprived the population from\nemergency response where it was most needed. A resident of Kherson city stated, “It is ‘a\nred zone’ and drones attack any transport. Police, State Emergency services, the fire brigade\n– if they came, a drone would attack immediately.” Civilians have often taken upon\nthemselves to organise evacuations of the injured and attempt to put out fires, but they have\nalso been targeted."},{"id":"a-80-497-p0030","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"30","seq":32,"section":"4. Attacks against first responders","text":"The head of a fire brigade in Dnipropetrovsk Oblast reported that in June 2025, he\ndrove with his team to extinguish a fire at a rural medical point in Illinka village that had\nbeen hit by drones. On the site, a drone dropped a grenade that damaged the fire engine,\ndespite it bearing distinctive visible marks (see para. 26)."},{"id":"a-80-497-p0031","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"31","seq":33,"section":"4. Attacks against first responders","text":"The head of an ambulance service in Kherson Oblast explained that most of their\nambulances had been hit by drones, and others by artillery. In July 2025, an ambulance that\nhad been repaired managed to operate for only 12 days until it was hit and damaged again."},{"id":"a-80-497-p0032","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"32","seq":34,"section":"4. Attacks against first responders","text":"Russian Telegram channels have posted videos showing attacks against first\nresponders often accompanied by the following threatening text or variants thereof, “[…] We\nwarn all special services involved in erasing the consequences [of attacks]. You will become\na priority target. Guaranteed.”"},{"id":"a-80-497-p0033","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"33","seq":35,"section":"4. Attacks against first responders","text":"In the absence of ambulances, civilians injured in attacks usually attempt to reach the\nclosest point where they can receive first aid. A man from Antonivka Settlement, Kherson\nOblast, who was injured by drones attacking his house stated that he had to walk for about\ntwo hours, covered in blood, to a place where an ambulance could pick him up."},{"id":"a-80-497-p0034","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"34","seq":36,"section":"5. Attacks against critical infrastructure","text":"In the same localities, attacks with drones have regularly targeted electric substations,\ntransformers, generators, gas installations, water installations, wind turbines, and mobile\ncommunication towers that serviced civilians. This led to electricity, water, and gas supply\ncuts of variable duration. Multiple posts uploaded by perpetrators or persons close to them\non Russian Telegram channels demonstrate that critical infrastructure has been a priority\ntarget. The text “[…] All objects of critical infrastructure are a legitimate target. […]” was\nrepeatedly disseminated, as well as videos showing and claiming attacks on various such\nobjects."},{"id":"a-80-497-p0035","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"35","seq":37,"section":"5. Attacks against critical infrastructure","text":"Residents from Dnipropetrovsk Oblast testified about drone attacks targeting\nelectrical transformers, sometimes leading to their full destruction. This has forced them to\nseek alternative sources of energy. In August 2024, the head of a fire brigade was inspecting\nan unexploded drone that landed on a transformer, when more drones flew in and hit the\ntransformer, setting it on fire. He was forced to hide under the transformer and was injured.\nHe recounted that it took the firefighters almost a whole day to put out the ensuing fire."},{"id":"a-80-497-p0036","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"36","seq":38,"section":"5. Attacks against critical infrastructure","text":"Drone attacks have targeted wind turbines. Two videos disseminated by Russian\nTelegram channels in June 2025 show drones aiming at the motor compartment of wind\nturbines. The video stops as the drones are about to hit, which is typical of suicide drones.\nOne of them was posted with the text, “Minus one more wind turbine. The guys worked well.\nWork, brothers.”"},{"id":"a-80-497-p0037","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"37","seq":39,"section":"5. Attacks against critical infrastructure","text":"In locations affected by electricity and water cuts, generators have been vital, both to\nprovide power and to pump water. However, they have also been regularly targeted by\ndrones. A woman from Kherson Oblast stated, “We hid the generators. If you left it in the\nmiddle of the yard, it would definitely be hit by a drone”."},{"id":"a-80-497-p0038","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"38","seq":40,"section":"5. Attacks against critical infrastructure","text":"Repairs of critical infrastructure installations in the aftermath of attacks have often\nbeen difficult or impossible, as drone attacks targeted repair crews. Residents attempted\nrepairs but even they faced the dangers of drone attacks. A man from Dnipropetrovsk Oblast\nnoted that drones come within 15 - 20 minutes if they observe repair works."},{"id":"a-80-497-p0039","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"39","seq":41,"section":"6. Perpetrators","text":"The attacks have been committed by drone units of the Russian armed forces based\non the left bank of Dnipro River, which is currently under Russian control, in Kherson and\nZaporizhzhia oblasts. Civilians who used to live in these localities stated that many fled after\nRussian armed forces deployed there. They said that Russian soldiers occupied vacant\nhouses, placed military equipment between civilian buildings, and operated drones from\nwithin civilian residences or administrative buildings, hospitals and schools."},{"id":"a-80-497-p0040","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"40","seq":42,"section":"6. Perpetrators","text":"The Commission has identified individual drone operators and drone units deployed\non the left bank of the river. Some of them have regularly disseminated videos showing drone\nattacks against civilians via Telegram channels. They are affiliated with various army units\nall of which are part of the “Dnepr” Group of Forces commanded by Colonel General Mikhail\nTeplinsky, who reports directly to the Chief of the General Staff Army General Valery\nGerasimov, the commander of all Russian troops operating in Ukraine. The “Dnepr” Group\nof Forces has an area of operations covering parts of the Kherson, Mykolaiv, and\nZaporizhzhia oblasts that are along the Dnipro River. In July 2025, during a visit of the\nMinister of Defence of the Russian Federation to the Headquarters of the Group of Forces,\nTeplinsky briefed him about the implementation of a drone control system that allowed the\ngroup of forces to use drones “according to a unified plan, reduce their losses, and also keep\ntrack of their usage”."},{"id":"a-80-497-p0041","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"41","seq":43,"section":"6. Perpetrators","text":"Moreover, witnesses and local authorities from some of the targeted localities in\nDnipropetrovsk Oblast reported that the drones came from the direction of or from within the\nproximity of the Zaporizhzhia Nuclear Power Plant, which was seized by the Russian\nFederation in 2022.11 This is in violation of international humanitarian law, that prescribes\nthat armed forces shall endeavour to avoid locating any military objectives in the vicinity of\nnuclear stations.12 One resident of Nikopol city, Dnipropetrovsk Oblast, stated, “they know\nthat nobody will shoot at the Zaporizhzhia Nuclear Power Plant”."},{"id":"a-80-497-p0042","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"42","seq":44,"section":"6. Perpetrators","text":"Among civil authorities appointed by the Russian Federation to the occupied areas,\nVolodymyr Saldo, the so-called “Governor” of the occupied areas of Kherson Oblast, has\nbeen actively supporting military units using drones on the frontlines in Kherson Oblast. In\nSeptember 2024, Saldo posted photos and text on his own Telegram channel stating that he\nhanded over drones to military personnel operating on the left bank of Kherson Oblast. In\n2025, also on his Telegram channel, Saldo posted updates about his support to a particular\ndrone unit operating in the north of Kherson, as well as recruitment advertisements for this\nunit, under the heading “Make Kherson’s history already today!”. In 2023 and 2025, he also\nreported on his Telegram channel about his visits to drone factories. During one such visit in\n2023, he discussed the delivery of drones and their possible production directly in Kherson\nOblast, while in 2025, he noted that drones produced by the factory are now “working en\nmasse on the front lines - in the area of responsibility of the ‘Dnepr’ troop grouping”."},{"id":"a-80-497-p0043","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"43","seq":45,"section":"7. Types of drones used in attacks","text":"There have been continuous innovations in the field of drones used during the armed\nconflict in Ukraine. Based on the testimony of local authorities and first responders, as well\nas on videos and photographs shared by witnesses and on Russian media or Telegram\nchannels, Russian armed forces have used several types of small, short-range, and low-cost\ndrones to hit civilians in the areas investigated. The models documented allow real time\nobservation and selection of targets via an embedded camera. Some of them have first-person\nview equipment that allows the operators to see from the perspective of the drones."},{"id":"a-80-497-p0044","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"44","seq":46,"section":"7. Types of drones used in attacks","text":"Drones of the Chinese Da-Jiang Innovations (DJI) company are frequently cited, in\nparticular the Mavic 3 type quadcopter series that are produced for civilian use but modified\nto enable the dropping of explosives. DJI has declared that its products are not designed for\nmilitary applications and stated that it suspended all commercial activities in the Russian\nFederation and Ukraine in light of the ongoing hostilities, and contractually forbade any sales\nby dealers to either country and for combat use. 13 The Commission has addressed questions\non this matter to the company."},{"id":"a-80-497-p0045","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"45","seq":47,"section":"7. Types of drones used in attacks","text":"Suicide drones that explode upon impact have been more commonly reported\nthroughout 2025, in connection with such attacks, notably the VT-40 quadcopter drone and\nthe fixed-wing Molniya drone. Both are Russian produced. Various types of explosives are\nusually attached to drones, including grenades, mortar rounds, RPG-7 cartridges, butterfly\nmines, repurposed anti-tank mines, as well as improvised flammable or explosive substances."},{"id":"a-80-497-p0046","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"46","seq":48,"section":"8. Drone attacks in areas controlled by Russian armed forces","text":"The Commission has attempted to verify allegations, as reported by Russian\nauthorities, of drone attacks in areas that are under Russian armed forces control on the left\nbank of the Dnipro River. The Commission has addressed letters to the Russian Federation,\nhas reviewed information posted online, and has interviewed residents from the relevant areas\nin Kherson and Zaporizhzhia Oblasts, provided that they were in safe conditions. All of the\ninterlocutors interviewed had left the areas concerned and had not directly witnessed attacks\nwith drones on civilian targets. Due to lack of access to the territory, concerns relating to the\nsafety of witnesses, and in the absence of response to its questions to the Russian Federation,\nthe Commission has not obtained a sufficient evidentiary basis to draw conclusions from its\ninvestigations (see para. 13)."},{"id":"a-80-497-p0047","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"47","seq":49,"section":"9. Consequences for the civilian population","text":"Drone attacks in the three affected oblasts have a devastating impact on civilians. The\nrampant presence of drones pursuing and striking civilians has not only led to deaths and\ninjuries, but has also created a permanent climate of terror and large-scale destruction.\nAlthough different localities have been affected to varying degrees, and some of the\ndestruction was a result of the combined action of drones and artillery, the systematic attacks\ntargeting civilian objects with drones has taken a heavy toll. Drone attacks have caused\nsignificant structural and permanent damage in most of the investigated localities. The attacks\nthat triggered fires have been frequent and particularly destructive. Survivors reported loss\nof homes, livelihoods, and belongings; they suffered a deep psychological shock, a traumatic\nfeeling of having lost everything. A local authority who inspected the aftermath of a drone\nattack, stated, “people are left with nothing after such fire – everything they own is\ndestroyed”."},{"id":"a-80-497-p0048","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"48","seq":50,"section":"9. Consequences for the civilian population","text":"Drone attacks have severely affected services. Most shops, pharmacies, transport, and\nmedical facilities have had to close. Systematic attacks on critical infrastructure have\ntemporarily or permanently deprived civilians of electricity, water, gas, and internet\nconnection. Drone attacks against first responders have prevented them from reaching those\nin need. A local authority noted, “we cannot provide […] any normal services – the village\ncouncil; the state emergency services; ambulances; fire brigades”."},{"id":"a-80-497-p0049","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"49","seq":51,"section":"9. Consequences for the civilian population","text":"These attacks have rendered life in the affected localities unbearable and compelled\nthousands to leave. Interlocutors invoked fear, stress, permanent risks, and therefore, the\nimpossibility to live in such conditions. A humanitarian worker stated, “we can’t take it\n13 See Da-Jiang Innovations, Statement On Military Use Of Drones, 21 April 2022; Da-Jiang\nInnovations, Reassesses Sales Compliance Efforts In Light Of Current Hostilities, 26 April 2022. See\nalso A/HRC/59/CRP.2, para. 51-52.\nanymore; it is getting worse and more frightening”. Residents of the targeted localities\npointed out that even if they had initially chosen to stay, despite of the gravity of the situation\nand the constant risks, drone attacks on their houses had been decisive in causing them to\nleave, as they had lost everything."},{"id":"a-80-497-p0050","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"50","seq":52,"section":"9. Consequences for the civilian population","text":"Local authorities reported a sharp decrease of the population as a consequence of the\ndrone attacks; and that some areas have been almost entirely vacated. Those who remained\nare mainly older people, those with reduced mobility, those who have no means to leave, or\nthose who had to take care of relatives or properties. According to a humanitarian worker\nnow even they started to leave."},{"id":"a-80-497-p0051","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"51","seq":53,"section":"10. Concluding observations","text":"Recurrent drone attacks carried out by the Russian armed forces have been directed at\nan extensive range of civilian targets in areas stretching over 300 kilometres, across Kherson,\nDnipropetrovsk, and Mykolaiv oblasts. The attacks have killed and injured civilians,\nincluding first responders, and have caused large-scale damage and destruction. The duration,\nfrequency and the geographic spread of the attacks confirm that they are part of a pattern and\nhave been widespread and systematic. Drone units based in a wide geographic area along the\nleft bank of the Dnipro River have carried out such attacks using the same modus operandi,\nwhich demonstrates that they acted pursuant to an organisational policy."},{"id":"a-80-497-p0052","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"52","seq":54,"section":"10. Concluding observations","text":"In continuance of its previous findings, the Commission concludes that drone attacks\nagainst civilians, in a much wider geographic area than previously established, amount to the\ncrime against humanity of murder,14 the war crimes of intentionally directing attacks against\ncivilians15 and civilian objects16. Further, launching attacks from the vicinity of a nuclear\npower plant is in violation of international humanitarian law. These attacks also violate a\nseries of fundamental human rights, amongst others, the right to life. 17"},{"id":"a-80-497-p0053","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"53","seq":55,"section":"10. Concluding observations","text":"The drone attacks against civilians have created a coercive environment. They were\ncommitted with the primary purpose to spread terror among the civilian population.18 They\nwreaked large-scale destruction and disrupted permanently or temporarily basic services, as\nwell as supply of electricity, gas, and water, rendering the concerned localities unliveable.\nThe recurrence of such drone attacks against a broad range of civilian targets, by various\nunits acting under a unified command, over a long period of time, left the population with no\nchoice but to flee and hampered the return of those who have fled."},{"id":"a-80-497-p0054","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"54","seq":56,"section":"10. Concluding observations","text":"This demonstrates that these attacks have been intentional and part of a coordinated\npolicy to drive civilians out of those territories. The Commission thus concludes that the\nconduct of the Russian armed forces amounts to the crime against humanity of forcible\ntransfer of populations.19"},{"id":"a-80-497-p0055","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"55","seq":57,"section":"B. Deportations and transfers of civilians from the occupied areas of","text":"Since its establishment in 2022, the Commission has documented different situations\nin which Russian authorities have deported or transferred civilians, adults and children, from\nterritories that came under their control in Ukraine.20 During recent investigations, it has\nfocused on deportations and transfers of adult civilians, men and women, from the Russian\noccupied areas of Zaporizhzhia Oblast. According to the Russian authorities, Zaporizhzhia\nOblast, together with Donetsk, Kherson, and Luhansk oblasts, became part of the Russian\nFederation following the so-called “treaties on accession” of 30 September 2022.21 Such\nannexation of territories is illegal under international law and has been widely condemned. 22"},{"id":"a-80-497-p0056","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"56","seq":58,"section":"B. Deportations and transfers of civilians from the occupied areas of","text":"In 2022 and 2023, Russian authorities in occupied areas of the Zaporizhzhia Oblast\nengaged in repeated instances of transfers of civilian adults to territories under Ukrainian\nGovernment control, through the Vasylivka checkpoint, which then marked the end of the\nRussian-controlled areas in the northern part of the oblast. At the checkpoint, Russian\nmilitary officers read out an order of transfer addressed to the victims, as a punitive measure\nfor alleged activities against the Russian Federation. They directed them to proceed on foot\nthrough a 10 to 15 km-long operational area, highly dangerous for civilians. The Russian\npress and Telegram channels have disseminated multiple videos, photos, and articles showing\nthe victims being transferred."},{"id":"a-80-497-p0057","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"57","seq":59,"section":"B. Deportations and transfers of civilians from the occupied areas of","text":"In 2024 and 2025, Russian authorities have deported civilian adults to Georgia, via\nthe Russian Federation, from the occupied areas of Zaporizhzhia Oblast.23 The perpetrators\nread or handed over deportation orders that refer to a decision not to allow “entry into the\nRussian Federation” for periods averaging 20 to 40 years. The Russian authorities then\ntransported the victims to the Verkhniy Lars border crossing between the Russian Federation\nand Georgia and ordered them to cross."},{"id":"a-80-497-p0058","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"58","seq":60,"section":"B. Deportations and transfers of civilians from the occupied areas of","text":"Arrests, detentions, various forms of violence – sometimes including torture –\nsearches, confiscations of documents and property, preceded the transfers or deportations.\nVictims were deported or transferred at very short notice, or without any prior notice, and\nthereby separated from all aspects of their daily lives, including families, homes, work, and\nbelongings. They had to restart their life from scratch, while they dealt with deep\npsychological trauma."},{"id":"a-80-497-p0059","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"59","seq":61,"section":"B. Deportations and transfers of civilians from the occupied areas of","text":"In the commission of these acts, security and other authorities of the Russian\nFederation in the occupied areas of Zaporizhzhia Oblast have acted in a coordinated manner.\nAlready in July 2022, Yevhen Balytskyi, then the Russian appointed “head of the temporary\ncivil-military occupation administration” of the of occupied areas of the Zaporizhzhia Oblast,\nissued a decree containing a list of prohibited manifestations of extremist activities\npunishable with forcible expulsion. These included: obstructing the work of the civil-military\nadministrations or the referendum commissions, discrediting the authorities of the Russian\nFederation, disseminating false information about the authorities of the Russian Federation. 24\nOn 24 February 2024, in an interview with the Russian media, Balytskyi, presently the\nRussian-appointed so-called “Governor” of the occupied areas of the oblast, stated, “We\nevicted a large number of families. […] We evicted those who, in one way or another, didn’t\nsupport the “Special Military Operation”, those who insulted the flag, the Russian anthem,\nthe president of the Russian Federation. […] We evicted entire families because we\nunderstood that these are people we couldn’t convince and that we would have to deal with\nthem in an even tougher manner."},{"id":"a-80-497-p0060","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"60","seq":62,"section":"1. Transfers to territories under Ukrainian Government control","text":"In 2022 and 2023, Russian authorities transferred men and women across different\nprofessions, backgrounds, and ages from the occupied areas of Zaporizhzhia Oblast to\nterritories under Ukrainian Government control. The Russian authorities accused them of\nfailing to cooperate, carrying out activities considered as destabilizing, or having a pro-\nUkrainian position."},{"id":"a-80-497-p0061","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"61","seq":63,"section":"1. Transfers to territories under Ukrainian Government control","text":"According to the victims and witnesses, members of the Federal Security Service or\nother Russian authorities arrested, detained, and interrogated them for periods of varying\nduration before the transfers. They searched their houses and confiscated documents, money,\nphones, vehicles, house keys, and other belongings. Many victims were subjected to violence\n21 See Russian Federation, “Agreement between the Russian Federation and the Zaporizhzhia Region\non the admission of the Zaporizhzhia Region to the Russian Federation and the formation of a new\nsubject within the Russian Federation”, 30 September 2022.\n22 A/HRC/52/CRP.4, para. 678.\n23 According to Ukrainian authorities, by 2025 the Ukrainian Embassy in Georgia has received more\nthan 540 appeals of civilians who reported to have been deported from Ukraine.\n24 Volodymyr Saldo (see para. 42) signed a similar decree for Kherson Oblast.\nor threats of violence, and were coerced to sign pre-printed or dictated documents or make\nself-incriminating declarations on camera. A victim of transfer stated that during his\ndetention, an investigator instructed him to sign a document addressed to Balytskyi, stating,\n“I do not agree with the referendum and do not want this territory to be the Russian\nFederation.” In another case, interrogators ordered a detained victim to write a letter to\nBalytskyi noting, “I am refusing to take a Russian passport and to support the Russian\nFederation. I am supporting Ukraine”."},{"id":"a-80-497-p0062","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"62","seq":64,"section":"1. Transfers to territories under Ukrainian Government control","text":"After different periods of detention, Russian authorities blindfolded the victims,\nindividually or in small groups, and transported them to the Vasylivka checkpoint (see para.\n55). Various Russian authorities were present there. A Russian military officer read out a\nprinted order, stating that the “expulsion from the Russian Federation” had been decided as\na punitive measure on such grounds as “discrediting the Russian Federation”, or “carrying\nout subversive activities”, or “acting against the Russian Government”. One of the orders\neven mentioned “lying on the internet” as a reason for expulsion."},{"id":"a-80-497-p0063","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"63","seq":65,"section":"1. Transfers to territories under Ukrainian Government control","text":"The transfers occurred in a coercive and dangerous environment. A victim reported\nthat the Russian officer told him to stay close to a ditch, remarking, “we don’t want to carry\nyou when you will be shot”, to scare him, and then ordered him to proceed. The victims had\nto walk through a “grey zone” averaging 10 to 15 km to reach the territory under Ukrainian\nGovernment control, in an operational area with landmines, trenches, and while hearing shots\nand shelling nearby. Some went missing following transfers. In several cases, the Russian\nauthorities staged the transfer, but instead transported the victims to Verkhnia Krynytsia\nvillage nearby, which was under Russian control, and subjected them to forced labour. 25"},{"id":"a-80-497-p0064","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"64","seq":66,"section":"1. Transfers to territories under Ukrainian Government control","text":"Victims noted the presence of representatives of Russian media at the checkpoint. The\nRussian press and Telegram channels have disseminated articles, photos and videos\nconcerning such transfers. The Commission has collected and examined open-source\nmaterial showing the victims and Russian officers wearing masks and reading transfer orders,\nin a location identifiable as the Vasylivka checkpoint. One victim even recounted that the\nscene had to be repeated, so that the journalists could record it."},{"id":"a-80-497-p0065","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"65","seq":67,"section":"2. Deportations","text":"In 2024 and 2025, Russian authorities in occupied areas of the Zaporizhzhia Oblast\nhave coordinated actions to deport civilian adult men and women across various professions,\nbackgrounds, and ages to Georgia, via the Russian Federation. The perpetrators accused the\nvictims of refusing to cooperate with the Russian authorities, refusing to acquire a Russian\npassport, or of holding pro-Ukrainian views."},{"id":"a-80-497-p0066","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"66","seq":68,"section":"2. Deportations","text":"Prior to the deportations, members of the Federal Security Service and other Russian\nauthorities usually arrested and detained the victims. In several cases, the Russian authorities\nstaged curfew violations: they brought the victims to public places after the curfew time,\nwhere the police drew up charges of curfew violations. Thereafter, local judges pronounced\nadministrative sanctions of detention in standardized judicial decisions. The Russian\nauthorities often repeated the same sequence of actions, leading to additional sanctions for\ncurfew violations."},{"id":"a-80-497-p0067","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"67","seq":69,"section":"2. Deportations","text":"The Russian authorities searched the victims’ homes and confiscated their identity\ndocuments and other belongings. In some cases, they forced the victims to sign documents\nstating that they refuse to apply for a Russian passport because of their political views. Left\nwith no documents, they felt compelled to apply for Russian passports. However, in situations\nwhere the documents had been confiscated by security services, the application process did\nnot yield results. Therefore, the victims remained without any nationality documents."},{"id":"a-80-497-p0068","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"68","seq":70,"section":"2. Deportations","text":"The deportations were ordered by the so-called “Directorate for Migration Affairs of\nthe Main Directorate of the Ministry of Internal Affairs of Russia for Zaporozhye Region”,\nestablished in 2023 by the Russian Federation. On the day of the deportations, Russian\nauthorities took the victims to the “Directorate for Migration Affairs”. Usually, the\nauthorities did not give the victims prior notice of the deportations. In most cases, they\n25 A/HRC/58/67, para. 22.\nnotified the deportation decisions with immediate effect, at the “Directorate for Migration\nAffairs”, or during detention or house searches."},{"id":"a-80-497-p0069","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"69","seq":71,"section":"2. Deportations","text":"The Commission has obtained copies of deportation decisions approved by senior\nofficials of the so-called “Ministry of Internal Affairs”, including the heads of the “Main\nDirectorate” and of the “Directorate for Migration Affairs of the Ministry of Internal Affairs”,\nand has identified these individuals.26 The documents refer to prior decisions by the Federal\nSecurity Service not to permit entry of the victims, Ukrainian citizens, into “the Russian\nFederation” for periods averaging 20 to 40 years. They communicated the decision to deport\nthe victims “from the territory of the Russian Federation” – while referring to the areas the\nRussian authorities have occupied in Ukraine. The decisions invoke the Russian Federation\nlegislation on the “legal status of certain categories of foreign citizens or stateless persons\nin the Russian Federation”."},{"id":"a-80-497-p0070","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"70","seq":72,"section":"2. Deportations","text":"Apart from these documents, the Russian authorities generally refused to\ncommunicate the reasons behind the deportations. A woman asked armed men who stormed\nher apartment, arrested her, and informed her of the upcoming deportation, about the reason.\nThey responded, “You were born in the wrong place”."},{"id":"a-80-497-p0071","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"71","seq":73,"section":"2. Deportations","text":"Employees of the “Directorate for Migration Affairs” and other Russian authorities\norganized transport and escorted groups of victims to the Verkhniy Lars border crossing from\nthe Russian Federation to Georgia. At the international border, they ordered the victims to\ncross over. The Russian authorities generally returned the previously confiscated Ukrainian\ndocuments at that time. However, they did not do so in all cases, and victims crossing without\ndocuments faced additional difficulties."},{"id":"a-80-497-p0072","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"72","seq":74,"section":"2. Deportations","text":"The deportations occurred in a threatening environment. A man who had been\ndeported stated that at the border crossing, a member of the deportation convoy warned him,\n“Go and better not come back. We have people who will not be free anytime soon. And some\ndisappear altogether, and no one will find them. Be glad that you are coming out alive and\nwell. It is not always like that, believe me.” A woman who had been deported stated that at\nthe crossing point a man of the convoy took her aside and told her, “Greetings from FSB.27\nYou are not dumb, and if you return, you will get a bullet to your head”."},{"id":"a-80-497-p0073","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"73","seq":75,"section":"3. Impact","text":"Russian authorities who carried out the deportations and transfers often gave the\nvictims very short notice, or no notice at all, giving them no opportunity to pack or even call\ntheir families before being taken away. The perpetrators generally returned the identification\ndocuments of the victims at time of the transfer or deportation, but this was not always the\ncase. In some situations, they confiscated passports, keys to houses or cars, and phones."},{"id":"a-80-497-p0074","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"74","seq":76,"section":"3. Impact","text":"Victims of deportations and transfers recounted the traumatizing character of having\nto restart their life from scratch. Those who had been deported faced additional challenges\nrelated to their arrival in a foreign country with almost nothing. Some of them only had\ndocuments and a phone, others did not even have that. They had to apply for documents, find\nurgent ways to survive; some had no choice but to work illegally; many relied on help from\nvolunteer organisations. Some returned to Ukraine, others travelled to Europe, and yet others\nchose to remain in Georgia for the time being."},{"id":"a-80-497-p0075","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"75","seq":77,"section":"3. Impact","text":"All victims expressed grave concern for their families in the occupied areas of\nUkraine, with whom they have only scarce or indirect contact because of security reasons.\nSome of the victims have learnt that Russian authorities had occupied their houses or affixed\nnotices stating “ownerless”. They are unable to claim their properties as this would require\ntravel to the occupied area from which they have been deported or transferred without a right\nto return.\n26 The Ukrainian authorities issued notices of suspicion against several involved officials.\n27 FSB is the Russian acronym for the Federal Security Service of the Russian Federation (FSB)."},{"id":"a-80-497-p0076","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"76","seq":78,"section":"4. Concluding remarks","text":"Unlawfully deporting or transferring civilians, recognised as protected persons under\ninternational law, to another State or another location, constitutes a war crime.28 International\nhumanitarian law allows evacuations for security or imperative military reasons, but these\nmay not involve the displacement of protected persons outside the bounds of the occupied\nterritory.29 In the investigated cases, Russian authorities have transferred or deported civilian\npersons outside of the occupied areas, after accusing them of carrying out activities against\nthe Russian Federation or considering them foreign nationals or persons without nationality,\nrespectively. These findings lead the Commission to conclude that Russian authorities have\ncommitted deportations and transfers as war crimes in the occupied areas of Zaporizhzhia\nOblast."},{"id":"a-80-497-p0077","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"77","seq":79,"section":"4. Concluding remarks","text":"The Commission also found that in both types of situations, Russian authorities have\nrepeatedly carried out such acts for prolonged periods of time. This indicates that they were\nsystematic. The evidence shows that various Russian entities, including senior officials, have\nacted in an organized and coordinated manner, and have thus committed transfers and\ndeportations pursuant to a state policy. Notably, the Russian-appointed “Governor” of the\noccupied areas of Zaporizhzhia Oblast issued a decree mandating expulsions (para. 58) and\nopenly admitted to such acts."},{"id":"a-80-497-p0078","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"78","seq":80,"section":"4. Concluding remarks","text":"Moreover, in the cases where Russian authorities confiscated the identity documents\nof the victims, they created conditions forcing them to apply for Russian passports. This is\ncontrary to the Law of Occupation, according to which an Occupying Power has the\nobligation to respect the laws in force in the country, unless absolutely prevented. 30\nCompelling foreign citizenship upon Ukrainian citizens violates international humanitarian\nlaw and the national laws of Ukraine, and therefore impacts the rights of affected persons as\nUkrainians.31"},{"id":"a-80-497-p0079","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"79","seq":81,"section":"4. Concluding remarks","text":"In this regard, it is noteworthy that a 20 March 2025 decree of the Russian Federation\nstated that citizens of Ukraine who do not have legal grounds for stay (residence) in the\nRussian Federation must leave the territory by 10 September 2025, or regularize their legal\nstatus.32 In practice, this requires that they obtain Russian identity documents or that they\nleave. This raises further concern."},{"id":"a-80-497-p0080","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"80","seq":82,"section":"4. Concluding remarks","text":"The acts of the perpetrators inflicted severe mental pain and suffering upon the victims\nand amount to inhuman treatment as a war crime and a human rights violation. 33 The\ndeprivation of liberty, the use of violence or threats of violence, the absence of a genuine\nlegal process, the separation from families, also constitute human rights violations."},{"id":"a-80-497-p0081","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"81","seq":83,"section":"IV. Conclusions and recommendations","text":"The Commission’s recent investigations found that recurrent attacks, by Russian\narmed forces, with short-range drones against multiple civilian targets on the right\nbank of the Dnipro River in Dnipropetrovsk, Kherson, and Mykolaiv oblasts, have\ncompelled thousands to flee from the targeted areas and amount to the crime against\nhumanity of forcible transfer of population. It also established that coordinated actions,\nby Russian authorities, to drive out civilians from occupied areas in Zaporizhzhia\nOblast, amount to the war crimes of deportations and transfers. On the basis of the\ndocumented cases, the Commission has further concluded that Russian authorities have\ncommitted the crime against humanity of murder, the war crimes of intentionally\ndirecting attacks against civilians and civilian objects, and of inflicting inhuman\ntreatment, as well as corresponding human rights violations."},{"id":"a-80-497-p0082","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"82","seq":84,"section":"IV. Conclusions and recommendations","text":"In the different investigated scenarios, various Russian authorities have\nsystematically coordinated actions to commit crimes and violations. Military units of\nthe Russian armed forces deployed over a geographic area stretching across three\noblasts, but operating under a centralized command, have targeted civilian persons and\nobjects with drones, for over one year. Russian civil authorities in the Zaporizhzhia\nOblast, including the Russian-appointed “Governor”, have acted together with\nmembers of the Federal Security Service to deport or transfer Ukrainian civilians."},{"id":"a-80-497-p0083","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"83","seq":85,"section":"IV. Conclusions and recommendations","text":"Drone attacks targeting localities in Dnipropetrovsk, Kherson, and Zaporizhzhia\noblasts killed and injured civilians, and caused large-scale damage and destruction,\nrendering many of these areas unlivable. The ensuing coercive environment, terror, and\ndevastation left thousands with no other choice than to flee. Civilians who have been\ntransferred or deported from Zaporizhzhia Oblast have been detained, at times\ntortured, and were placed in a coercive and threatening environment during the\ntransfers or deportations. In all cases, the victims have been forced to give up multiple\naspects of their daily lives, separated from their families and properties, while agonizing\nover their fate."},{"id":"a-80-497-p0084","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"84","seq":86,"section":"IV. Conclusions and recommendations","text":"The Commission reiterates, in this regard, the importance of judicial and non-\njudicial forms of accountability. The non-judicial forms of accountability, including\nmeasures of truth and reparation, can contribute towards providing much needed\nsupport to the victims’ efforts to recover from traumatic events and reintegrate in\nsociety. Concerning judicial forms of accountability, investigating and prosecuting\nthose responsible for crimes is key in ensuring accountability."},{"id":"a-80-497-p0085","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"85","seq":87,"section":"IV. Conclusions and recommendations","text":"Recommendations made in previous reports remain relevant. The Commission\nsets out below specific recommendations to address issues developed in the current\nreport."},{"id":"a-80-497-p0086","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"86","seq":88,"section":"IV. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation:\n(a)       Immediately end the drone attacks targeting civilians and civilian\nobjects;\n(b)       Immediately stop all acts that spread terror among the civilian\npopulation and that lead to forcible displacement;\n(c)      Ensure that all perpetrators involved in drone attacks targeting\ncivilians and civilian objects, including those ordering, soliciting or inducing them,\nare held accountable, in accordance with international standards;\n(d)      Immediately end transfer and deportation of civilians residing in\noccupied territories;\n(e)        Respect international law applying to protected persons living in\noccupied territories, notably through ending cruel and inhuman treatment; as well\nas through stopping to compel foreign citizenship and take due account of the\ninviolability of their rights under international humanitarian law."},{"id":"a-80-497-p0087","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"87","seq":89,"section":"IV. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)       Ensure that the victims of drone attacks receive the best possible\nphysical and mental healthcare services close to the most affected areas;\n(b)     Provide comprehensive support to persons who were displaced\nfollowing drone attacks;\n(c)     Provide comprehensive support to transferred and deported persons\nfrom occupied territories, that is tailored to their diverse situations, particularly\nfor those who find themselves stranded abroad."},{"id":"a-80-497-p0088","rec_id":"recfpYcoZVA1lSABR","symbol":"A/80/497","n":"88","seq":90,"section":"IV. Conclusions and recommendations","text":"The Commission recommends that other States and regional and international\norganizations:\n(a)      Contribute both financially and with technical advice to the Government\nof Ukraine and to civil society organisations, for the provision of comprehensive support\nfor victims and their families;\n(b)      For third States whose territory is the destination of persons deported\nfrom the occupied territories, undertake necessary efforts together with Ukrainian\nconsular services to support these persons."},{"id":"a-hrc-61-crp-8-u0000","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":null,"seq":0,"section":null,"text":"Summary\nThe present Conference Room Paper focuses on the latest findings of the Independent\nInternational Commission of Inquiry on Ukraine in its investigations concerning the unlawful\ndeportation and transfer of children from Ukraine by Russian authorities, to the Russian\nFederation or to areas they occupied in Ukraine, in the context of the Russian Federation’s\nfull-scale invasion.\nThe evidence collected leads the Commission to conclude that Russian authorities\nhave committed the crimes against humanity of deportation and forcible transfer, as well as\nof enforced disappearance of children. The Commission also confirms its previous finding\nthat Russian authorities have unlawfully deported and transferred children, as a war crime,\nand that they have unjustifiably delayed their repatriation, which is also a war crime. Further,\nmeasures taken with regard to deported or transferred children have violated international\nhumanitarian law and international human rights law provisions and were not guided by the\nbest interests of the child.\nRussian authorities have deported or transferred thousands of children from areas they\noccupied in Ukraine. The Commission has so far confirmed the deportation or transfer of\n1205 children. Russian authorities referred to these large-scale relocations as “evacuations”\njustified by the risks of the armed conflict. However, international humanitarian law\nmandates that evacuations must be temporary and take place for reasons of compelling\nhealth, medical treatment, or safety.\nFour years on, 80 per cent of the children deported or transferred in the cases\ninvestigated by the Commission have not returned. Russian authorities have failed to\nestablish a system facilitating the returns. Instead, they focused on long-term placements of\nthe children with families or in institutions in the Russian Federation.\nStarting from the days preceding the Russian Federation’s full-scale invasion, Russian\nauthorities have coordinated legislative, administrative, and practical measures to facilitate\ndeportations, transfers, and placements of the children in the Russian Federation. The\nevidence collected demonstrates that the authorities have acted pursuant to a policy\nconceived and executed at the highest level of the Russian Federation state apparatus. The\ninvolvement of Vladimir Putin, the President of the Russian Federation, including through\nhis direct authority over entities that have steered and executed this policy, has been visible\nfrom the outset.\nAs a consequence of the measures put in place, children deported from Ukraine have\nbeen given Russian citizenship, appeared on adoption databases, and have been placed in 21","unnumbered":true},{"id":"a-hrc-61-crp-8-u0001","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":null,"seq":1,"section":null,"text":"regions of the Russian Federation. Adoptions and long-term forms of placement have been\nprioritized, according to consistent Russian public statements.\nRussian authorities failed to inform the parents, legal guardians, or relatives of the\nfate and whereabouts of the children. Families and children have carried out their own efforts\nto locate one another. The returns that could be organized occurred after obstacles, delays,\nand security risks. After four years, many families are still looking for their children and\nattempting to secure their return. This leads to lengthy separation and suffering.\nThe coercive environment surrounding the deportations or transfers, the indefinite\nduration of the placements in the Russian Federation, combined with the considerable\ndifficulties the children face to find their family and travel back to Ukraine, has been a source\nof deep distress for the children. Arrangements established by Russian authorities led the\nchildren to be raised in a foreign environment, far from their families, sometimes thousands\nof kilometres away from Ukraine. Children reported trauma and fear of abandonment. A girl,\nrecounting the way the children were treated in an institution after transfer, said that staff\nwere telling her, “Your mom will not come, she has no money, she will not make it to the\nborder.”","unnumbered":true},{"id":"a-hrc-61-crp-8-p0001","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"1","seq":2,"section":"I. Introduction","text":"In its resolution 49/1, adopted on 4 March 2022, the Human Rights Council decided\nto urgently establish an Independent International Commission of Inquiry to investigate\nalleged violations and abuses of human rights and violations of international humanitarian\nlaw, and related crimes in the context of the Russian Federation’s aggression against Ukraine.\nThe Commission’s mandate was last extended on 4 April 2025. It is composed of Erik Møse\n(Chair), Pablo de Greiff, and Vrinda Grover."},{"id":"a-hrc-61-crp-8-p0002","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"2","seq":3,"section":"I. Introduction","text":"The Commission is guided in all aspects of its work by the principles of independence,\nimpartiality, objectivity, and integrity. It adopts a victim-centred approach and a strict respect\nof the “do no harm” principle, in particular regarding guarantees of confidentiality of the\ninformation received and the safety and the protection of victims and witnesses, and other\ninterlocutors."},{"id":"a-hrc-61-crp-8-p0003","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"3","seq":4,"section":"I. Introduction","text":"Considering the gravity and the continuous character of the crimes and violations\ncommitted in relation to children in the context of the Russian Federation’s full-scale\ninvasion of Ukraine since 2022, the Commission is presenting a conference room paper on\nthis matter. In its investigations, the Commission has relied on 232 interviews with parents,\nlegal guardians, boys and girls, and their relatives, staff of the affected institutions, experts,\nspecialised organisations, investigative journalists, and government authorities. It has\nexamined over 2,000 documents, including lists of affected institutions and deported\nchildren, identity documents of the children; 41 official documents of the Russian authorities\nor of the authorities cooperating with them in occupied areas of Ukraine; open-source\nmaterial such as statements and declarations, publications on government websites, public\nadoption databases, expert documents, videos, and posts on social media; as well as 42\nsubmissions to the Commission by non-governmental organisations."},{"id":"a-hrc-61-crp-8-p0004","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"4","seq":5,"section":"I. Introduction","text":"The Commission expresses its gratitude to all those who shared their experiences,\ntestimonies and other valuable information. It appreciates the cooperation of the Government\nof Ukraine. The Russian Federation has continued not to recognise the Commission and did\nnot respond to any of the Commission’s questions."},{"id":"a-hrc-61-crp-8-p0005","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"5","seq":6,"section":"II. Overview","text":"Already during its earlier mandates, the Commission investigated situations in which\nRussian authorities unlawfully deported children from areas they occupied in Ukraine to the\nRussian Federation or transferred them to other Russian occupied areas in Ukraine. It\nestablished that these acts amount to war crimes1 and that Russian authorities violated their\nobligation under international law to facilitate in every possible way the reunification of\nfamilies separated during the armed conflict.2"},{"id":"a-hrc-61-crp-8-p0006","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"6","seq":7,"section":"II. Overview","text":"During the present mandate, the Commission has: First, investigated additional cases\nconcerning the deportation and transfer of children by Russian authorities, from areas they\noccupied in Ukraine. Second, reviewed all the cases it has investigated so far, to assess the\nrate of return of the children, and to identify obstacles to returns. Third, tracked over time,\nthe movements and whereabouts of the children who have been deported or transferred.\nFourth, investigated initiatives by Russian authorities to facilitate the long-term placement,3\nincluding through adoption, of the children deported to the Russian Federation. Fifth,\nidentified individuals and entities responsible for the commission of the crimes and violations\noutlined in the present report."},{"id":"a-hrc-61-crp-8-p0007","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"7","seq":8,"section":"II. Overview","text":"The Commission has thus far documented cases concerning the deportation or transfer\nof a total of 1205 children by Russian authorities from areas that came under their control in\nfive oblasts of Ukraine, to the Russian Federation, or to other occupied areas in Ukraine.\nThese cases include the deportation or transfer of 210 children described in its previous\nreports, in the context of the ongoing armed conflict, as Russian armed forces gained and lost\ncontrol of territories in Ukraine."},{"id":"a-hrc-61-crp-8-p0008","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"8","seq":9,"section":"II. Overview","text":"Resulting from its recent investigations, the Commission has verified the deportation\nof 995 children from 11 institutions in the so-called Donetsk and Luhansk People’s Republics\nthat began shortly before the launch of the full-scale invasion of Ukraine in 2022. Russian\nauthorities referred to this large-scale relocation of children as an “evacuation” justified by\nan imminent security risk generated by the Government of Ukraine, at a time when Russian\narmed forces themselves had massed personnel and military equipment at Ukraine’s borders."},{"id":"a-hrc-61-crp-8-p0009","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"9","seq":10,"section":"II. Overview","text":"Most deportations and transfers of children investigated have not been temporary as\nrequired by law in the case of evacuation. On the contrary, Russian authorities at the highest\nlevels of government have coordinated actions to facilitate their long-term placement in the\nRussian Federation. The authorities first relocated the children to temporary transit centers\nin the Russian Federation or in areas they occupied in Ukraine. They further gradually\ndeported or transferred most of them to various locations in 21 regions of the Russian\nFederation, where they placed them indefinitely with families or in institutions. Children\nwere given Russian citizenship and their profiles appeared on adoption or foster placement\ndatabases. These acts amount to various violations of international humanitarian law and\ninternational human rights law, including war crimes and crimes against humanity."},{"id":"a-hrc-61-crp-8-p0010","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"10","seq":11,"section":"II. Overview","text":"In public statements and meetings, Russian authorities referred to adoptions as the\npreferred option for placement of the deported children and provided updates on legislative\nand administrative measures they undertook to make the adoptions possible. Some of the\nplacements the Commission has documented appear, indeed, to be adoptions. However,\naround the time of the issuance of warrants of arrest by the International Criminal Court in\nMarch 2023, Russian authorities backtracked on these statements, denied that adoptions of\nchildren from Ukraine have been taking place and emphasized instead foster placement in\ntheir public declarations."},{"id":"a-hrc-61-crp-8-p0011","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"11","seq":12,"section":"II. Overview","text":"Russian authorities had not sought the consent of parents, legal guardians4 or of the\nUkrainian authorities when they deported or transferred the children. Instead, they relied on\nthe consent of local authorities in occupied areas who cooperated with them or were\nappointed by them. Many parents and legal guardians remained unaware of the fate and\nwhereabouts of the children for months or years after the initial deportations or transfers,\ndespite sustained efforts to find them. This led to prolonged family separations."},{"id":"a-hrc-61-crp-8-p0012","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"12","seq":13,"section":"II. Overview","text":"Four years on, the Commission found that from the cases of deportations and transfers\nit has documented, 80% of the children have not yet been returned. Russian authorities have\nnot established a system facilitating the return the children, as required by international\nhumanitarian law. Children, parents, legal guardians, and relatives have carried out their own\nefforts to locate one another. The returns that could be organized occurred after encountering\nobstacles, delays, and security risks. Some family reunifications received wide coverage in\nofficial government communications and the media. However, the majority of children\ndeported or transferred have not returned, and many are still missing. Children from\ninstitutions, and in particular younger children,5 or those with disabilities, have almost no\nchance to return."},{"id":"a-hrc-61-crp-8-p0013","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"13","seq":14,"section":"II. Overview","text":"Deportations or transfers of children, their disappearance, and the ensuing prolonged\nseparation from families have been highly traumatic for all those involved. The children who\nmanaged to return reported psychological distress and fear of abandonment. Those who have\nnot returned are far from their family and the environment they came from. Some of the older\nchildren have reached the age of majority in the meantime. A mother who did not manage to\nfind her daughter, placed in an institution in the Russian Federation, stated, “[…] I am still\nlooking for my daughter, and I am terribly afraid of what she might think of me and how she\nsurvives there, where many people hate Ukrainians […]”."},{"id":"a-hrc-61-crp-8-p0014","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"14","seq":15,"section":"III. Widespread and systematic deportations and transfers of children","text":"The Commission has documented cases involving the deportation or transfer, by\nRussian authorities, of children then aged from 11 months to 17 years, from areas that had\ncome under their control in five oblasts of Ukraine, namely Donetsk, Kharkiv, Kherson,\nLuhansk, and Mykolaiv oblasts, to the Russian Federation or to other occupied areas in\nUkraine (see para. 7). In fact, these relocations of children began already during the week\nbefore the start of the 24 February 2022 full-scale invasion of Ukraine and continued as the\narmed conflict progressed. The deportations and transfers affected children who lost their\nparents or were separated from them in the context of the ongoing hostilities or were in\ninstitutions.6    Russian      authorities   first    deported     or     transferred    them\nto temporary transit centres in the Russian Federation or in the Russian occupied areas of\nUkraine. Starting April 2022 and throughout the coming months and years, Russian\nauthorities organized the further deportation or transfer of groups of these children, using\nbuses, trains, or planes, to place them for indefinite periods in different regions across the\nRussian Federation or in occupied areas of Ukraine (see map)."},{"id":"a-hrc-61-crp-8-p0015","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"15","seq":16,"section":"III. Widespread and systematic deportations and transfers of children","text":"Russian authorities referred to the deportations and transfers of children as\n“evacuations” that became necessary because of the dangers of the armed conflict. However,\ninternational humanitarian law states that a Party to the conflict cannot evacuate children,\nother than its own nationals, to a foreign country, except for a temporary evacuation for\ncompelling health, or medical treatment, or safety reasons. 7 Consistent with its previous\nfindings, the Commission has found that the relocation of children has generally not been\ntemporary. In the majority of cases, Russian authorities have not facilitated the return of the\nchildren to their families or country. On the contrary, they have taken measures aimed at their\nlong-term placement in the Russian Federation through foster placement or adoption (see\nparas. 25-35). In addition, the evidence does not suggest that health, medical treatment, or\nsafety reasons have been the principal motivating factor behind these relocations."},{"id":"a-hrc-61-crp-8-p0016","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"16","seq":17,"section":"III. Widespread and systematic deportations and transfers of children","text":"International humanitarian law also requires the consent of the parents or the legal\nguardians, and if they cannot be found, the consent of the persons who by law or custom are\nprimarily responsible for the care of the children.8 In June 2023, during a meeting with heads\nof delegations of African states, Vladimir Putin, the President of the Russian Federation,\ndeclared, “We evacuated entire orphanages, and it was done legally because the directors\nof those orphanages were legal guardians of the children”.9 However, in the cases\ndocumented, the Russian authorities did not seek the consent of directors of institutions\nappointed by the Ukrainian Government.10 Instead, they relied on the consent of local\nauthorities or directors cooperating with them. For instance, in the cases of two institutions\nfrom Kherson Oblast, Russian authorities dismissed directors who refused to cooperate and\nreplaced them with new directors who authorized the deportation or the transfer. In the case\nof an institution in Kharkiv Oblast, Russian armed forces proceeded to transferring the\nchildren in the absence of the acting director of the institution."},{"id":"a-hrc-61-crp-8-p0017","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"17","seq":18,"section":"III. Widespread and systematic deportations and transfers of children","text":"The repeated instances of deportation and transfer of children from locations in five\noblasts of Ukraine, following a consistent pattern of conduct, and the further deportations,\ntransfers and placements of these children, demonstrate the widespread and systematic\ncharacter of these acts. Russian authorities working at different levels have been involved in\nthese processes, including bodies directly answerable to Mr. Putin; other Government bodies\nand regional authorities in the Russian Federation; and local authorities in Russian occupied\nareas of Ukraine. These authorities organized and accompanied the transfers and deportations\nof the children; travelled to occupied oblasts in Ukraine; visited children’s institutions,\ntemporary transit centers, and foster families; worked in close cooperation with the\nauthorities in occupied areas of Ukraine, and carried out coordination meetings of different\nRussian government institutions to arrange logistical and administrative modalities\nconcerning the placement in the Russian Federation of the children deported or transferred\n(see paras. 45-51).\nMap of regions in Ukraine from where children were deported or transferred, transit\nlocations in the Russian Federation or Russian occupied areas in Ukraine, and regions of\nfurther placement with families or in institutions.\nCase description: deportations of children shortly before the full-scale invasion"},{"id":"a-hrc-61-crp-8-p0018","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"18","seq":19,"section":"III. Widespread and systematic deportations and transfers of children","text":"During the week preceding Russian Federation’s full-scale invasion of Ukraine, the\nRussian authorities engaged in a large-scale deportation of children from institutions in\nthe so-called Donetsk and Luhansk People’s Republics, to the Russian Federation.\nDifferent Russian authorities, operating at various levels, coordinated efforts to carry out\nthis early deportation wave. Between 16 and 18 February 2022, Denis Pushilin and Leonid\nPasechnik, the respective “heads” of the two so-called republics, called for a mass\nevacuation of the population, invoking a threat of an imminent attack by the Ukrainian\narmed forces. On 18 February 2022, Mr. Pushilin and the “Ministers of Education” of the\ntwo so-called republics further ordered the “evacuation” of all institutions holding children\nwithout parental care. Local authorities implemented these orders immediately, together\nwith the directors of these institutions, and transported hundreds of children from both\noblasts across the border into the Russian Federation.11"},{"id":"a-hrc-61-crp-8-p0019","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"19","seq":20,"section":"III. Widespread and systematic deportations and transfers of children","text":"Official declarations by Russian authorities, evacuation orders issued by the local\nadministration and directors of institutions, other official documents, interviews with\ndirectors of institutions to the press, media coverage, as well as verified lists of pupils,\nconfirm this large-scale relocation. The Commission has verified the deportation of\nchildren from seven institutions in the Donetsk Oblast: Donetsk Comprehensive Boarding\nSchool No. 1, Amvrosiivka Boarding School No. 4, Dokuchaevskaya Special\nComprehensive Boarding School No. 27, Vuhlehirsk Special Boarding School No. 6,\nDonetsk Pre-school Children’s Home N. 1 “Teremok”, Children’s Social Center of\nHorlivka City, and Children’s Social Center of Yenakiieve City. These institutions held a\ntotal of 701 children at the time of the deportation, according to official figures. The\nCommission has similarly verified the deportation of children from four institutions in\nLuhansk Oblast: Luhansk Children’s Home, Luhansk Republican Mother and Child\nHome, Lutuhyne Special Boarding School, and Perevalsk Special Boarding School. These\ninstitutions held a total of 202 children at the time of the deportation, according to official\nfigures."},{"id":"a-hrc-61-crp-8-p0020","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"20","seq":21,"section":"III. Widespread and systematic deportations and transfers of children","text":"The threat of an attack by Ukrainian armed forces invoked by the local authorities\nof both so-called republics did not materialise. Instead, the Russian Federation launched\nthe full-scale invasion against Ukraine later that week."},{"id":"a-hrc-61-crp-8-p0021","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"21","seq":22,"section":"III. Widespread and systematic deportations and transfers of children","text":"In the Russian Federation, the children were placed in temporary transit centres in\nKursk, Rostov, and Voronezh Oblasts. Already by mid-March 2022, over 1672 children\nwithout parental care were among those relocated, according to an official update by Ms.\nMaria Lvova-Belova, the Presidential Commissioner for Children’s Rights of the Russian\nFederation."},{"id":"a-hrc-61-crp-8-p0022","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"22","seq":23,"section":"III. Widespread and systematic deportations and transfers of children","text":"During the following months, Russian authorities at central and local levels, and in\ncoordination with the authorities of the two so-called republics, took further steps –\nincluding legislative amendments – to seek arrangements for the long-term stay of the\nchildren in the Russian Federation (see para. 29).12 In June 2022, a decision by the “head”\nof the so-called Donetsk People’s Republic instructed the local authorities to consent to\nthe placement with Russian families of children without parental care who had been\nevacuated to the Russian Federation and were given Russian citizenship. In September\n2022, the media-office of the “government” of the so-called Luhansk People’s Republic\ninformed about a similar, temporary decision. In September 2022, the “Ministry of Labour\nand Social Affairs” of the so-called Donetsk People’s Republic communicated a plan of\nthe Ministry of Education of the Russian Federation to relocate the evacuated children\nwithout parental care to institutions in other regions of the Russian Federation."},{"id":"a-hrc-61-crp-8-p0023","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"23","seq":24,"section":"III. Widespread and systematic deportations and transfers of children","text":"Many of the children were further transferred, often in groups, from the temporary\ntransit centres to different regions of the Russian Federation and placed with families or\nin institutions. Transfers within the Russian Federation occurred in the presence of senior\nofficials, including Ms. Lvova-Belova, local Russian governors, on some occasions with\nMs. Eleonora Fedorenko, the then “Adviser on Children’s Rights” to the “head” of the so-\ncalled Donetsk People’s Republic, and directors of the institutions from which they were\ndeported.13"},{"id":"a-hrc-61-crp-8-p0024","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"24","seq":25,"section":"III. Widespread and systematic deportations and transfers of children","text":"In April 2023, Ms. Lvova-Belova stated that the children who had been “evacuated”\nfrom the Donetsk Oblast were still in the Russian Federation.14 According to official\ndeclarations by Russian authorities and a record of placements in different regions, 288\namong these children were placed with Russian families, while others were placed in\ninstitutions in the Russian Federation. Many of these children remained in the Russian\nFederation at the time of writing the report. Further, according to Russian authorities, in\nMay 2022, the children deported from the Luhansk Oblast had been returned to the\ninstitutions from which they were transferred, but 92 were placed in Russian families.15"},{"id":"a-hrc-61-crp-8-p0025","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"25","seq":26,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"From the outset, Russian authorities have declared that the preferred option for family\nplacement of the children “evacuated” from Ukraine was adoption and that hundreds of\nRussian citizens had expressed their willingness to adopt them. 16 Already two days before\nthe full-scale invasion, Russian authorities started considering practical modalities to do so\nand coordinated actions to address legal and administrative challenges. On 22 February 2022,\nan update on the website of the Presidential Commissioner for Children’s Rights of the\nRussian Federation regarding a conference call between the children’s ombudspersons from\nvarious Russian regions, noted that particular attention was paid to children without parental\ncare who had been transported from institutions in Donetsk and Luhansk Oblasts to the\nRussian Federation. Ms. Lvova-Belova stressed that a “huge” number of citizens expressed\na desire to take children into their family, both temporarily and permanently, and stated “we,\nin turn, together with colleagues from other departments, will work out the issue of how this\ncan be done legally”.17 [“а мы в свою очередь, вместе с коллегами из других ведомств\nпроработаем вопрос, как это можно сделать на законных основаниях.”]"},{"id":"a-hrc-61-crp-8-p0026","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"26","seq":27,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Different Russian authorities raised the issue of legal challenges concerning the\npermanent placement of children with Russian families. The Family Code of the Russian\nFederation notes that in the case of adoption of a child who is a foreign citizen, the consent\nof the competent authority of the state of citizenship of the child is required. In March 2022,\na clarification on the website of the Presidential Commissioner for Children’s Rights of the\nRussian Federation regarding the placement of children relocated from Ukraine into Russian\nfamilies stated, “Since at the moment diplomatic relations with Ukraine are difficult, and the\nmechanism for transferring children, citizens of the Lugansk and Donetsk Republics, to\nfamily forms of upbringing has not yet been regulated within the framework of international\ntreaties, this category of children cannot be transferred to family forms of upbringing without\nthe consent of the guardianship authorities and authorities of the Republics.”18"},{"id":"a-hrc-61-crp-8-p0027","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"27","seq":28,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Also in March 2022, Mr. Putin and Ms. Lvova-Belova discussed the issue of\npermanent placement of orphans who had arrived from eastern Ukraine during a meeting.\nMs. Lvova-Belova stated, “There are simply legislative delays, which will then need to be\neliminated.” Mr. Putin responded, “You tell us which ones, we will eliminate them.”19 [“Вы\nскажите какие – будем их устранять.”] In May 2022, Mr. Putin approved a decree\nexpediting the acquisition of Russian citizenship for children without parental care from\nUkraine.20\n15 Presidential Commissioner for Children’s Rights of the Russian Federation, The Bulletin, Issue no.\n1, 4 April 2023; Presidential Commissioner for Children’s Rights of the Russian Federation, The\nBulletin, Issue no. 2, 13 October 2023.\n16 Official website of the Presidential Commissioner for Children’s Rights of the Russian Federation,\n“Maria Lvova-Belova discussed the family placement of orphans with the head of the DPR Denis\nPushilin”, 6 April 2022.\n17 Official website of the Presidential Commissioner for Children’s Rights of the Russian Federation,\n“We have never abandoned our own people - a conference call of children's ombudsmen on\nassistance to children and families from the LPR and DPR was held”, 22 February 2022. (in\nRussian)\n18 Official website of the Presidential Commissioner for Children’s Rights of the Russian Federation,\n“Answers on the family placement of orphans from the DPR and LPR in Russian families”, 16 May\n2022. (in Russian)"},{"id":"a-hrc-61-crp-8-p0028","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"28","seq":29,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Russian authorities systematically granted Russian citizenship to the children whom\nthey deported or transferred21 and have confirmed this in numerous official and public\ndeclarations.22 This is evident from testimonies of parents and returned children. The\nCommission also obtained copies of identity documents."},{"id":"a-hrc-61-crp-8-p0029","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"29","seq":30,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Further, during coordination visits and meetings, Russian authorities and the\nauthorities of the so-called Donetsk and Luhansk People’s Republics amended existing\nlegislation, prepared and signed agreements, and updated procedures to make adoptions\npossible.23 These legal and administrative measures have facilitated the placement of the\nchildren deported from Ukraine into Russian families."},{"id":"a-hrc-61-crp-8-p0030","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"30","seq":31,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Russian authorities have actively encouraged, promoted, and rewarded foster\nplacements and adoptions. Transfers and placements of children occurred in the presence of\nRussian officials and officials of the two so-called republics, in a festive environment, and\nwere widely covered in the Russian media. Various Russian officials have personally visited\nfamilies who have fostered children from Ukraine or met them during official ceremonies,\nhave handed them letters of gratitude and presents, including financial contributions,\naccording to documents, official communications, and the Russian media. Witnesses told the\nCommission that deported children who reached the age of majority have been offered\napartments in the Russian Federation."},{"id":"a-hrc-61-crp-8-p0031","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"31","seq":32,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In May 2022, in a meeting of the United Nations Security Council, Vasily Nebenzia,\nthe Russian Federation Ambassador to the United Nations, stated, “Approximately 1,200\nchildren came from orphanages in the Donetsk and Luhansk People’s Republics. We work\nclosely with the authorities of the Donetsk and Luhansk People’s Republics on the adoption\nof orphans”.24 During a meeting with Russian families on International Children’s Day, on\n1 June 2022, Mr. Putin, referring to orphans from eastern Ukraine, stated, “we will help\nchildren who have lost loved ones to find the same loving, friendly, generous families as\nyours”.25"},{"id":"a-hrc-61-crp-8-p0032","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"32","seq":33,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"The practice of relocating children from occupied areas of Ukraine and placing them\nin Russian families, including through adoption, had been documented since 2014. In this\nregard, the European Court for Human Rights noted in 2025 that it “is satisfied that a\ncontinuous sequence of acts in a pattern between 2014 and 2022 aimed at removing\nUkrainian children from occupied territory in Ukraine and integrating them potentially\nindefinitely in families or institutions in Russia has been demonstrated beyond reasonable\ndoubt”.26"},{"id":"a-hrc-61-crp-8-p0033","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"33","seq":34,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"However, around the time of the issuance in March 2023 of the warrants of arrest by\nthe International Criminal Court against Mr. Putin and Ms. Lvova-Belova for the war crime\nof unlawful deportation and transfer of children from Ukraine, the Russian authorities have\nstarted denying that adoptions of children deported from Ukraine took place and largely\nstopped referring to “adoption”. Subsequent official communications concerning children\nfrom Ukraine contradicted those made throughout 2022, and emphasised foster placement.27\nIn March 2023, in an interview with the Russian media, Ms. Lvova-Belova said, “Children\nfrom new regions of Russia are given to families under guardianship, and not for adoption\n[…]”. During an Arria-Formula meeting of the United Nations Security Council in April\n2023, Mr. Nebenzia noted, “that there was no such thing as forced “mass adoption”; that\nonly orphans and children who were left without parental care were placed under the\n“temporary preliminary care” or “temporary guardianship” of Russian citizens”.28"},{"id":"a-hrc-61-crp-8-p0034","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"34","seq":35,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Nevertheless, the Commission found evidence that Russian authorities have continued\nto place children deported from occupied areas of Ukraine in Russian families, in long-term\ntypes of arrangements, including adoption. Further, most of the placements that had already\noccurred in 2022 are continuing until today. Since 2022 until the time of writing of this report,\na Russian online adoption database has been uploading profiles of deported children,\nindicating that they can be adopted or placed in foster families. The Commission has\ndocumented the dissemination of such profiles in 14 regions of the Russian Federation."},{"id":"a-hrc-61-crp-8-p0035","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"35","seq":36,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"The        circumstances      described       above demonstrate the         intention and\nthe joint efforts carried out by Russian authorities, from the outset, to place the children they\ndeported from Ukraine with Russian families and to prioritize adoptions. Even if these\narrangements are no longer officially referred to as adoptions, the Commission’s\ninvestigations show that the children have been given Russian citizenship and have\nbeen placed with Russian families for long-term periods, with no measures\nto facilitate their return.\nCase descriptions: foster placements and adoptions"},{"id":"a-hrc-61-crp-8-p0036","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"36","seq":37,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"The Commission has tracked, where possible, the itinerary and the most recent\nwhereabouts of the children who have been deported or transferred from occupied areas\nin Ukraine. It has documented placements of these children with families in the Russian\nFederation. Some of the placements appear to be adoptions; in two cases, new Russian\ndocuments have changed the name and birthplace of the child. Children have also been\nplaced with Russian officials, including in Ms. Lvova-Belova’s family. Although Russian\nauthorities have emphasised that efforts are made to keep families together, the\nCommission has documented cases where children have been separated from siblings and\nrelatives."},{"id":"a-hrc-61-crp-8-p0037","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"37","seq":38,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In April 2022, a boy then aged 13 years, had been deported to the Russian Federation\nfrom the Amvrosiivka Boarding School No. 4 in the Donetsk Oblast (see para. 19) and\nplaced with a foster family in Moscow Oblast. The Commission obtained a placement\norder signed by an authority of the so-called Donetsk People’s Republic, dated April 2022,\nas well as a hand-over document. The foster mother declared to the media that the boy\nwas given Russian citizenship in an accelerated procedure. The boy has an older sister in\nDonetsk Oblast. At the time of writing of this report, he is reportedly still with the foster\nfamily in the Russian Federation, separated from his sister."},{"id":"a-hrc-61-crp-8-p0038","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"38","seq":39,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Also in April 2022, twin sister and brother aged 9 years and an older sister aged 12\nyears were deported to the Russian Federation from two different boarding schools in the\nDonetsk Oblast and placed in a foster family in Moscow Oblast. The two girls were in the\nAmvrosiivka Boarding School No. 4, and the boy was in the Vuhlehirsk Special Boarding\nSchool No. 6, according to a list of pupils (see para. 19). The Commission obtained a\nplacement order for the girls dated April 2022 and signed by an authority of the so-called\nDonetsk People’s Republic, as well as a hand-over document. A documentary on Russian\ntelevision in October 2022 shows the arrival of the siblings by train to Moscow and the\nfoster parents receiving them in the presence of Russian authorities. In October 2023, the\nsocial media page of a boarding school in Moscow Oblast posted a video showing the\nfoster mother and the boy. In September 2024, the social media page of the same school\nuploaded two videos of the boy playing Russian songs, mentioning that he is enrolled in\nthe school."},{"id":"a-hrc-61-crp-8-p0039","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"39","seq":40,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In June 2022, three boys who were then 16 years old were deported to the Russian\nFederation as part of a group of 31 children from the Donetsk Children’s Social Centre,\nin Donetsk city, to a temporary transit center in Moscow Oblast. 29 Each boy was\nsubsequently placed with a different foster family in the Russian Federation, even though\neach of them had family members or a legal guardian in Ukraine. One of them was placed\nin Ms. Lvova-Belova’s family and another boy in the family of Ms. Irina Rudnitskaya,\nhead and founder of an organization advocating for family values. During a meeting with\nMr. Putin, Ms. Lvova-Belova publicly declared that she had “adopted” a child from\nMariupol.30 All three boys were given Russian passports. Two of the boys have managed\nto return to Ukraine through their own efforts and support from Ukraine. The foster\nfamilies and Russian authorities have actively attempted to impede their return.\nTestimonies collected by the Commission demonstrate that foster placement had been\npsychologically draining for them. In 2025, Ms. Rudnitskaya was charged by Russian\nauthorities with child trafficking in connection with an unrelated incident."},{"id":"a-hrc-61-crp-8-p0040","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"40","seq":41,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"Starting in June 2022, five siblings then aged between 4 and 14 years, deported in\nthree different phases from Donetsk Oblast to the Russian Federation, were placed with a\nfoster family in Moscow Oblast. According to an official list of deported children and\nmedia reports, three among them were part of the group of 31 children deported from the\nDonetsk Children’s Social Centre in Donetsk city to a temporary transit center in Moscow\nOblast.31 Another sibling had been among the children first deported from institutions in\nDonetsk Oblast to Rostov Oblast, Russian Federation, and subsequently transferred again\nby plane to Moscow Oblast on 16 September 2022 (see para. 21). The fifth child was\npicked up in April 2023 by the Russian foster father from Donetsk Oblast. On her social\nmedia account, the foster mother posted photographs of the same children together with\nother children of the family. In 2022, official Russian social media channels reported that\nthe Governor of the Moscow Oblast expressed his gratitude to the family. In 2023, the\nmedia announced that the Ministry of Social Development of the Moscow Oblast handed\na letter of appreciation to the family through a local representative of the United Russia\nParty. An update on foster families in Moscow Oblast, posted on the website of the\nOmbudsperson for Children’s Rights for Moscow Region at the end of 2024, refers to the\nfive children as still being with the same family."},{"id":"a-hrc-61-crp-8-p0041","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"41","seq":42,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In September 2022, a then 11-month-old girl and a 2-year-old boy from Kherson\nChildren’s Home, in Kherson city, were deported to the Russian Federation and placed in\na family in Moscow Oblast.32 The Russian appointed director of Kherson Children’s Home\nhad authorised Ms. Inna Varlamova to accompany the infant children during travel. The\nCommission has obtained a copy of the electronic registration of an act of adoption for\nthe infant girl, with her original name and place of birth in Kherson Oblast, and a changed\nname and place of birth in Moscow Oblast. The document included the names of the\nadoptive parents, 72-year-old Mr. Sergei Mironov, parliamentary leader in the State Duma\nand a close ally of Mr. Putin, and his wife, the above-mentioned 57-year-old Ms.\nVarlamova. A copy of the girl’s new birth certificate and an electronic registration thereof\ncite only her changed name and place of birth and this couple as her parents. According\nto witness testimonies, the girl has two older siblings, a legal guardian and a biological\nmother in Ukraine. However, at the time of writing of this report, she has not been returned\nto Ukraine, despite multiple efforts. The Commission has no information concerning the\ncurrent whereabouts of the boy."},{"id":"a-hrc-61-crp-8-p0042","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"42","seq":43,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In November 2022, seven children between 11 and 17 years were deported from a\nfamily-type orphanage in Kherson Oblast to Krasnodar Krai, in the Russian Federation,\nby the director, who was cooperating with the Russian authorities. She abandoned them\nafter arrival in the Russian Federation. The children were placed in different institutions\nand families. Two siblings among them, aged 13 and 17 years at that time, were separated.\nThe older boy was placed with a family; the younger sister in an institution. The boy had\nreached the age of majority and continued to reside with the foster family. He managed to\nestablish contact with his biological mother in Ukraine, called her regularly, and told her\nthat he will be looking for ways to return to Ukraine. He committed suicide in January\n2024. The Commission obtained a copy of the death certificate and an extract from the\nofficial register of death. Afterwards, the family attempted to locate the younger sister,\nincluding through the efforts of an older brother who became her legal guardian, but\nRussian authorities refused to provide any information."},{"id":"a-hrc-61-crp-8-p0043","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"43","seq":44,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In July 2023, a boy then aged 5 years, was deported to the Russian Federation from\na children’s institution in Donetsk Oblast (see para. 19), further transferred to Moscow\nOblast, and adopted by a Russian woman through a judicial order. The boy can be\nidentified in photos of a group of children deported from Ukraine and transferred by plane\nto Moscow Oblast on 7 October 2022 (see para. 46). The Commission obtained the copy\nof an electronic registration of an act of adoption for the boy, similar to the document cited\nabove (see para. 41), with his name and original place of birth in Donetsk Oblast, and a\nchanged name and place of birth in Moscow Oblast, as well as the name of the adoptive\nmother. On her social media account, the mother posted pictures of the boy. He had\nreportedly several siblings. The adoptive mother told the media that she refused the\nrequest of an older sister, also deported from Donetsk Oblast, to be placed with the same\nfamily."},{"id":"a-hrc-61-crp-8-p0044","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"44","seq":45,"section":"IV. Long-term placement of children: foster placements or adoptions","text":"In January 2024, a boy then aged 7 years, was deported to the Russian Federation\nfrom the Donetsk Pre-school Children’s Home N. 1 “Teremok” (see para. 19) to an\ninstitution in Pskov Oblast, and later placed with a military family in the same oblast,\naccording to the media. The same sources reported that the foster father is a Russian\nmilitary officer participating in the armed conflict in Ukraine and the mother is the head\nof the regional committee of military families. The Governor of the Pskov Oblast invited\nthe family for the handing over of an award to the boy. The boy is recognisable in photos\nposted by the foster mother on her social media account in 2024 and 2025."},{"id":"a-hrc-61-crp-8-p0045","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"45","seq":46,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"The evidence collected by the Commission demonstrates that Russian authorities and\ninstitutions, at the highest level, at regional level, as well as in the occupied oblasts in\nUkraine, have organised the deportation or transfer of children from Ukraine to the Russian\nFederation or to occupied areas in Ukraine. These officials have coordinated a range of\nactions to facilitate the further deportation or transfer and the placement of these children, on\na long-term or permanent basis, in the Russian Federation."},{"id":"a-hrc-61-crp-8-p0046","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"46","seq":47,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"The direct involvement of Mr. Putin has been visible from the outset. He exercises\ndirect authority over entities that have steered and executed the policies relating to children\nas detailed in the present report. During official meetings, Mr. Putin received regular updates\nfrom Ms. Lvova-Belova, the Presidential Commissioner for Children’s Rights of the Russian\nFederation, who reports directly to him, on the situation of the children deported or\ntransferred from Ukraine. Mr. Putin has praised and encouraged efforts to enable the\npermanent placement of these children in the Russian Federation and has taken the necessary\nmeasures to advance this objective. He adopted a decree to simplify the manner of acquisition\nof the Russian citizenship for children without parental care from Ukraine (see para. 27).\nAlso, on 7 October 2022, an airplane traced to the Russian presidential fleet was used to\ntransfer 53 children who had been deported from Ukraine, to Moscow Oblast. 33"},{"id":"a-hrc-61-crp-8-p0047","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"47","seq":48,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"In the cases investigated, Ms. Lvova-Belova has played a leading and pivotal role in\ncoordinating the deportation and transfer of children, and organizing their transport,\nplacement in temporary transit centers, and further transfer and permanent placement in\ninstitutions or families. To this end, she has been working in close coordination with other\nRussian bodies and authorities, including ministries, members of the State Duma, regional\ngovernors, regional commissioners for children’s rights, and authorities in occupied oblasts\nof Ukraine. She has personally accompanied the children during transfers within the Russian\nFederation and has visited foster families who received children deported from Ukraine. In\nMarch 2024, the United Nations Committee on the Rights of the Child urged the Russian\nFederation “To investigate allegations of war crimes perpetrated by the Presidential\nCommissioner for Children’s Rights”.34"},{"id":"a-hrc-61-crp-8-p0048","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"48","seq":49,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"Some ministries of the Russian Government have also played a role in coordinating\nor implementing the policies described above. The Ministry of Defence of the Russian\nFederation has provided transport for the transfer within the Russian Federation of groups of\nchildren who had been deported from Ukraine. For instance, in September 2022, Russian\nauthorities transferred 77 children initially deported from Ukraine to Moscow Oblast, with a\nplane belonging to the Russian Aerospace Forces. 35 On that day, Ms. Lvova-Belova posted\non her Telegram channel an expression of gratitude to the Ministry of Defence, for providing\nthe transport, and the Ministry of Internal Affairs, for the processing of Russian citizenship\nfor the children. In some cases, Russian armed forces have conducted the actual transfer of\nthe children in Russian occupied areas of Ukraine. In April 2022, the Ministry of\nEducation had been developing an agreement to facilitate the placement in Russian families\nof children deprived of parental care who had been deported from the so-called Donetsk and\nLuhansk People’s Republics in Ukraine.36"},{"id":"a-hrc-61-crp-8-p0049","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"49","seq":50,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"The Investigative Committee of the Russian Federation, reporting directly to Mr.\nPutin, has also been involved in these deportations. Members of the Investigative Committee\nhave visited children who had been deported and placed in temporary transit centres in the\nKursk, Rostov, and Voronezh Oblasts, in the Russian Federation (see para. 21). A video\nposted by the Investigation Committee in March 2022, shows one such visit and states that\nits purpose was to support the children, and to inform them “about the possibility of enrolling\nand studying at educational institutions of the Investigative Committee”. On 30 May 2022,\nduring a visit to an institution in Moscow Oblast, where 31 children had been deported from\nthe Donetsk Oblast, Ms. Lvova-Belova noted, “Our colleagues from the Russian\nInvestigative Committee helped us bring 31 children from the Donbas there. ”37"},{"id":"a-hrc-61-crp-8-p0050","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"50","seq":51,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"Anna Kuznetsova, Deputy Chair of the State Duma of the Russian Federation, has\nbeen supporting plans for the placing of children deported from institutions in Ukraine with\nfamilies in the Russian Federation, including adoptions, through preparing agreements with\nthe two so-called republics and discussing amendments of their legislation. To this end, she\nheld meetings and discussions with the authorities of both so-called republics, visited\nchildren who had been deported and placed in temporary transit centres in the Russian\nFederation, and children in institutions in occupied areas of Ukraine. 38 In March 2022, Ms.\nKuznetsova posted a message on her Telegram channel stating, “From the first days of the\nevacuation, residents of Russian regions who want to take the children into their families\nbegan to come forward. But for this, it is necessary to make a change in the legislation of the\n[Luhansk People’s] Republic. It was agreed to start this work.” In May 2022, in an interview\nwith the parliamentary journal of the Russian Federation, Ms. Kuznetsova noted, “More than\na thousand children from orphanages were evacuated to Russia. Hundreds of Russian\nfamilies responded and offered their help in their adoption. Such a lively response is very\nvaluable. If minors have no relatives in Donbass who are ready to raise them, and there are\nno other obstacles, adoption into a Russian family is possible. But only after all the nuances\nare settled at the legislative level”.39 In October 2022, Ms. Kuznetsova further posted on her\nTelegram channel, “About 50 children from the Kherson region orphanage were evacuated\nto Crimea against all odds […]! Together with regional leaders and representatives of\nrelevant agencies, we succeeded!”. On the same day, Mr. Igor Kastyukevich, also a deputy\nof the Russian State Duma, who had been directing this transfer, thanked Ms. Kuznetsova\nand other authorities for “their participation in this important matter”.40"},{"id":"a-hrc-61-crp-8-p0051","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"51","seq":52,"section":"V. Coordinated actions by Russian authorities to deport, transfer, and","text":"The authorities in Russian occupied areas of Ukraine have cooperated with the\nRussian authorities and have played an instrumental role in authorising and implementing\nthe initial deportations or transfers of children. Subsequently, they have facilitated\nadministrative, practical, and logistical ways the long-term placements of the children in the\nRussian Federation or in Russian occupied areas of Ukraine. Mr. Pushilin and Mr. Pasechnik,\nthe respective “heads” of the so-called Donetsk and Luhansk People’s Republics, had ordered\nthe initial deportations of hundreds of children (see para. 18). The “Ministries of Education”\nof both so-called republics took measures to execute these orders. Ms. Fedorenko and Yulia\nNazarenko, the respective former “Children’s Rights Commissioners” of the so-called\nDonetsk and Luhansk People’s Republics have played a key implementation role. They\ncoordinated measures concerning the children deported to the Russian Federation with the\nRussian authorities. Ms. Fedorenko has personally ordered and facilitated deportations of\nchildren and accompanied children from the Donetsk Oblast during their further transfer and\nplacement in the Russian Federation."},{"id":"a-hrc-61-crp-8-p0052","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"52","seq":53,"section":"VI. Enforced disappearances","text":"Russian authorities failed to inform parents, legal guardians, or relatives about the\ndeportation or transfer of the children and their fate and whereabouts. Many remained\nunaware of the fate and whereabouts of the children for prolonged periods of time, lasting\nweeks, months, or years. In the case of children deported or transferred from institutions,\nparents or relatives recounted how they went to visit or retrieve them, only to discover that\nthey were missing. Rarely, sympathetic staff informally passed some information to the\nparents or legal guardians, or enabled telephone contacts with the children. In the case of\nchildren deported or transferred from institutions who were deprived of parental care and fell\nunder the guardianship of the heads of institutions and the Ukrainian State, the Ukrainian\nauthorities reported that they did not receive information from the Russian authorities on their\nfate and whereabouts."},{"id":"a-hrc-61-crp-8-p0053","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"53","seq":54,"section":"VI. Enforced disappearances","text":"Those who managed to establish the whereabouts of the children usually did so\nthrough their own, considerable efforts, using personal contacts, open-source information, or\nwith the assistance of the Ukrainian authorities, non-governmental organizations, and third\nparties. A grandmother whose grandson had been transferred from an institution, stated that\nshe had never been notified about his transfer and his whereabouts. She said, “I called\neverywhere, I went to all institutions, I asked my relatives in Crimea and Russia to enquire\nabout the whereabouts of my grandson. I found out by myself where he was”. In some cases,\nthe children themselves have attempted to locate their parents or relatives. However, many\nparents or legal guardians did not manage to establish the children’s fate and whereabouts at\nthe time of the writing of the report. Concerned families often resided in areas heavily\naffected by the armed conflict and faced difficulties in conducting searches across different\nsides of the frontlines."},{"id":"a-hrc-61-crp-8-p0054","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"54","seq":55,"section":"VI. Enforced disappearances","text":"These situations led to prolonged family separations, distress, and anxiety for the\nchildren and their families. A mother whose son was transferred from an institution, while\nshe was not informed, said, “I was calling the hotline every two days to find out where my\nson was, but nobody could give me any information”. A grandmother who has been unable\nto locate her grandson since his transfer in 2022, recalled that in November 2024, the police\nof Kherson city asked her to come and see if her grandson was among a group of recently\nreturned children. She stated, “I went to Kherson in the hope that my grandson was one of\nthe returned children, unfortunately [he] was not amongst them. It was devastating”."},{"id":"a-hrc-61-crp-8-p0055","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"55","seq":56,"section":"VII. Obstacles to return","text":"Even when families managed to establish the fate and whereabouts of the children\nwho had been deported or transferred, their return and reunification with their families have\nbeen marred with challenges. In the cases investigated, over 80% of the children have not yet\nreturned. In a bulletin issued in April 2023 by the Presidential Commissioner for Children’s\nRights of the Russian Federation, it is noted that if a child “has a parent with full parental\nrights, the family has every opportunity to be reunited”, and that the Commissioner’s office\n“assists all legal representatives of children”. Russian authorities allowed the return of\nchildren when parents or legal guardians themselves, or persons or organizations acting on\ntheir behalf, undertook strenuous efforts to locate a child, went through the bureaucratic steps\nimposed, and organized travel to retrieve them. Some examples of return and reunification\nhave received wide public coverage. However, these constitute a minority, while the majority\nof cases remain unresolved. The Russian authorities failed to set up a system to facilitate the\nexpeditious return of the children, as prescribed by international humanitarian law. 41"},{"id":"a-hrc-61-crp-8-p0056","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"56","seq":57,"section":"VII. Obstacles to return","text":"For individual parents, legal guardians, or family members, the return of children has\nbeen very challenging and generally took months or even years to organize. Russian\nauthorities requested official documents, including official extracts or judicial confirmations,\nthat took a long time to obtain. In some cases where a child had no parents or legal guardians,\nrelatives first acquired legal guardianship to facilitate their return, which is also time\nconsuming, and led to longer family separations."},{"id":"a-hrc-61-crp-8-p0057","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"57","seq":58,"section":"VII. Obstacles to return","text":"Due to the ongoing armed conflict, travel to the Russian Federation or to Russian-\noccupied areas in Ukraine is difficult and requires the crossing of multiple international\nborders, coupled with security risks and high costs. Some families were denied access to the\nterritory where the children were held. In one case, the Russian authorities told a mother who\nwas traveling to retrieve her child that she did not pass the filtration and prohibited her entry\nto the territory. In another situation, the Russian authorities accused a grandmother of\ncooperating with Ukrainian authorities, threatened to call the police, and did not allow her to\nretrieve her grandchild. Some of the returns were made possible with the assistance of the\nUkrainian government, non-governmental organisations, or intervention by third parties. For\nfamilies from poor economic backgrounds, this has been impossible without external support."},{"id":"a-hrc-61-crp-8-p0058","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"58","seq":59,"section":"VII. Obstacles to return","text":"Many parents, legal guardians, or relatives could not secure the return of their\nchildren. A grandmother who had not managed to find her grandson regretted that as time\npasses, the boy is being raised away from his family. The return of children without parental\ncare, who have been deported from institutions and have no parent or legal guardian to claim\ntheir return, has mostly not taken place."},{"id":"a-hrc-61-crp-8-p0059","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"59","seq":60,"section":"VII. Obstacles to return","text":"Several older children deported to the Russian Federation attempted to return on their\nown and faced considerable difficulties. A teenager boy who had been deported and placed\nwith a foster family in the Russian Federation, made several attempts to return to Ukraine,\nbut his foster family tried to dissuade him and alerted the authorities. On the first attempt,\nRussian authorities arrested and coerced him to make a false declaration on camera, stating\nthat he had been forced to return to Ukraine. The boy later wrote a letter to Ukraine’s\nPresident saying that he wanted to return. Ultimately, a relative in Ukraine became his legal\nguardian and he managed to return. Two other teenage boys made their way back through\nBelarus with external assistance (see para. 39)."},{"id":"a-hrc-61-crp-8-p0060","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"60","seq":61,"section":"VIII. Condition of the children upon return","text":"Family separations lasted weeks, months, or years. The children who have returned\nsuffered from trauma, anxiety, and fear of abandonment. Parents, legal representatives, and\nrelatives reported instances of emotional pressure and inadequate care in the institutions\nwhere the children were placed after deportation or transfer. A grandmother reunited with\nher grandson stated, “when he was there, I could not see a smile on his face. Now that he is\nback, he is smiling again”. A boy who was transferred and placed in an institution said that\nhe suffered from stress and panic attacks and when that occurred, the staff placed him in\nisolation. He stressed that he continues to have panic attacks as a consequence. A child who\nhad been deported to the Russian Federation and placed in a family, told the Commission\nthat documentaries showing how children from Ukraine were happily placed in foster\nfamilies in the Russian Federation were staged, adding that a major obstacle encountered by\nchildren who wish to return to Ukraine is that they are afraid to voice their opinion."},{"id":"a-hrc-61-crp-8-p0061","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"61","seq":62,"section":"VIII. Condition of the children upon return","text":"The needs of some of the deported or transferred children, who lived with a disability\nor a medical conditions, were not met in the institution where they were placed after transfer.\nParents or relatives reported that they had not received the medical care they had been\nprescribed and consequently suffered from health complications. They also stated that they\nhad not received sufficient food and nutrition. The same interlocutors said that the children\nlost significant weight, were hungry, or reported having suffered from hunger during their\ntime in the institution."},{"id":"a-hrc-61-crp-8-p0062","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"62","seq":63,"section":"VIII. Condition of the children upon return","text":"Families of children who were deported or transferred also reported instances of\nindoctrination. Some of the returned children stated that they were forced to listen to the\nRussian national anthem every day and that failure to do so resulted in threats and\npsychological pressure. A mother noted that by the time of his return, her child forgot to\nspeak in Ukrainian and told her that his favorite song was the Soviet Army song “The Soldier\nWalks the City”. Children transferred and placed in an institution reported that the staff there\ntold them that Ukraine would become part of Russia or that Ukraine no longer existed.\nAccording to one mother, the staff said to her son, “your country does not exist anymore,\neverything has burnt down, and your parents probably died”. Three years on, he still suffers\nfrom trauma related to his transfer and has trouble sleeping."},{"id":"a-hrc-61-crp-8-p0063","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"63","seq":64,"section":"IX. Conclusions and recommendations","text":"Russian authorities deported or transferred thousands of children from areas\nthey occupied in Ukraine to the Russian Federation or to other Russian occupied areas\nin Ukraine, stating that these were necessary evacuations because of the armed conflict.\nThe relocations have not been temporary, as provided under international\nhumanitarian law in the case of evacuations. On the contrary, Russian authorities have\narranged the long-term placement of many of the children in the Russian Federation or\nin occupied areas of Ukraine. Compelling health, medical treatment, or safety reasons\n– the only legally justifiable reasons for temporary evacuation of children – were not\nthe motivating factors for the deportations and transfers. In addition, Russian\nauthorities did not seek the consent of parents, legal guardians or of the Ukrainian\nauthorities. The removal of children from Ukraine thus cannot be qualified as an\n“evacuation” within the meaning of international humanitarian law, as claimed by the\nRussian authorities. Under international humanitarian law, deporting or transferring\nof a protected person without lawful basis is a war crime. 42 The Commission reaffirms\nits previous finding that Russian authorities have unlawfully deported and transferred\nchildren from Ukraine, which amounts to war crimes.43\nUnjustifiable delay in the repatriation of civilians as a war crime"},{"id":"a-hrc-61-crp-8-p0064","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"64","seq":65,"section":"IX. Conclusions and recommendations","text":"The Commission’s investigations have so far confirmed that Russian authorities\nhave deported or transferred 1205 children. Of these, the Russian authorities have\nfailed to return over 80%. Instead, they have taken legislative, administrative, and\npractical measures to facilitate the indefinite placement of the children with families or\nin institutions in 21 regions of the Russian Federation and in areas they occupied in\nUkraine. Russian authorities did not establish a system for the repatriation of the\nchildren.44 The arduous task of finding the children and seeking their return was left to\nthe families. Russian authorities have therefore continued to violate their obligation\nunder international humanitarian law to facilitate in every way the reunion of families\nseparated during the armed conflict,45 which amounts to the war crime of unjustifiable\ndelay in the repatriation of civilians. 46\nDeportation and forcible transfer as a crime against humanity"},{"id":"a-hrc-61-crp-8-p0065","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"65","seq":66,"section":"IX. Conclusions and recommendations","text":"The deportations and transfers of children from Russian occupied areas in\nUkraine have been widespread and systematic, as they affected a significant number of\nchildren, have been carried out in various locations spread across several oblasts of\nUkraine, and followed a well-established and consistent pattern of conduct. The Russian\nauthorities at the highest levels – including Mr. Putin and entities directly answerable\nto him, as well as authorities at the regional level, and in the Russian occupied areas of\nUkraine, have coordinated practical modalities to carry out these deportations and\ntransfers, and to further relocate the children in the Russian Federation. These acts\nhave been committed following a consistent and carefully organised plan and modus\noperandi, initiated already before the full-scale invasion of Ukraine. This demonstrates\nthe existence of a pre-established policy conceived and executed under the leadership of\nthe highest level of the Russian Federation state apparatus. The scale and the scope of\nthese crimes, as well as their commission pursuant to a policy, lead the Commission to\nconclude that Russian authorities have deported and forcibly transferred children as a\ncrime against humanity.47\nEnforced disappearance as a crime against humanity and a human rights violation"},{"id":"a-hrc-61-crp-8-p0066","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"66","seq":67,"section":"IX. Conclusions and recommendations","text":"In most cases investigated, Russian authorities have not informed the parents,\nlegal guardians, relatives, or the Ukrainian authorities of the fact of the deportation or\ntransfer of the children, have not sought their consent, and have not informed them of\nthe fate and whereabouts of the children. The Ukrainian authorities, who have the legal\nguardianship of children without parental care, stated that they have not received\ninformation on the fate and whereabouts of the children from the Russian authorities.\nIn cases investigated, information was deliberately withheld from families, the identities\nof children were concealed, and returns or reunifications were prevented."},{"id":"a-hrc-61-crp-8-p0067","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"67","seq":68,"section":"IX. Conclusions and recommendations","text":"Consequently, parents, legal guardians, and relatives have remained unaware of\nthe fate and whereabouts of the children for a prolonged period of time. This has led to\nlengthy separations, distress and suffering. In the case of younger children, this can\ncause irreversible harm and estrangement from their country and families. Despite the\nwide coverage given to the placement or the return of some of the children, such cases\nare a minority. Four years on, in numerous other cases the fate and whereabouts of the\nchildren remain unknown. Families have persisted with extraordinary efforts in the\nhope of finding and securing the return of their children."},{"id":"a-hrc-61-crp-8-p0068","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"68","seq":69,"section":"IX. Conclusions and recommendations","text":"The removal of the children from their families and country, without the consent\nof parents, legal guardians, or of the Ukrainian authorities, also constitutes an\nabduction.48 The coercive environment surrounding the deportations or transfers, the\nindefinite nature of the placements in the Russian Federation, as well as the\nconsiderable difficulties to find their family and travel back to Ukraine, make the\nsituation of the children in the Russian Federation to amount to a deprivation of\nliberty.49 The deprivation of liberty is also demonstrated by the Russian authorities’\nfailure to establish a repatriation system, and by deliberately organising long-term or\npermanent placements of the children in the Russian Federation. These arrangements\nforce the children to be raised in a foreign environment, far from parents, legal\nguardians, or relatives, sometimes thousands of kilometres away from Ukraine.\nMoreover, adoption has far-reaching implications for a child and drastically diminishes\nthe prospect for a child to return and reunite with their family."},{"id":"a-hrc-61-crp-8-p0069","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"69","seq":70,"section":"IX. Conclusions and recommendations","text":"These considerations have led the Commission to conclude that Russian\nauthorities have also committed enforced disappearances of the children they deported\nor transferred from Ukraine. These enforced disappearances have been widespread and\nsystematic, committed pursuant to a policy, and amount to a crime against humanity. 50\nThey also constitute human rights violations.51\nOther violations of international humanitarian law and international human rights law"},{"id":"a-hrc-61-crp-8-p0070","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"70","seq":71,"section":"IX. Conclusions and recommendations","text":"The Commission found that the actions of the Russian authorities, as described\nin the present report, have been contrary to several other provisions of international\nhumanitarian law and international human rights law, in particular the Convention on\nthe Rights of the Child and its optional protocols. The range of measures taken towards\nthe deported or transferred children have not been guided by the principle of best\ninterests of the child.52 Changes to the personal status of the children, such as name,\nplace of birth, and nationality, violate international humanitarian law 53 and\ninternational human rights law.54 The conduct of the Russian authorities further\nviolated the right of a child to family relations without unlawful interference, 55 the right\nto know and be cared for by his or her parents,56 and the right not to be separated from\nhis or her parents against their will. 57 It is considered that the separation of children\nfrom their families or caregivers has serious effects on their personal integrity, with a\nlasting impact, and causes great physical and mental harm. This leads to the violation\nof other rights of the child, such as the right to health and recovery.58"},{"id":"a-hrc-61-crp-8-p0071","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"71","seq":72,"section":"IX. Conclusions and recommendations","text":"The recommendations made in previous reports remain relevant. The\nCommission sets out below specific recommendations to address issues in the present\nconference room paper."},{"id":"a-hrc-61-crp-8-p0072","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"72","seq":73,"section":"IX. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation:\n(a)    Cease any deportation of children from Ukraine or transfers within\noccupied areas of Ukraine;\n(b)    Provide reliable and comprehensive information about all children who\nhave been deported to the Russian Federation or transferred within occupied areas of\nUkraine, including on their fate and whereabouts, legal status, well-being and health\nconditions. This should include information about placement of children in institutions\nor with Russian families, including through adoption, as well as any change of\ncitizenship;\n(c)    Restore and facilitate effective communication between all children who\nhave been deported to the Russian Federation or transferred within occupied areas of\nUkraine with their parents, legal guardians, families or caregivers;\n(d)    Promptly and proactively initiate the immediate, safe and unconditional\nreturn to Ukraine of children deported to the Russian Federation or transferred within\noccupied territories in Ukraine, in accordance with their best interests and in\nconformity with international law;\n(e)    Cooperate with Ukrainian authorities in their efforts in relation to a DNA\nregistry that would aid in the identification and recovery of children;\n(f)    Immediately cease any measure to change the legal status of any child\ndeported or transferred;\n(g)    Provide unimpeded access to United Nations entities and other relevant\ninternational monitoring and humanitarian organizations to verify the situation of\nUkrainian children, safeguard their rights and well-being, and take all measures\nnecessary to secure their immediate, safe and unconditional return to reunite with their\nparents, legal guardians, families or caregivers."},{"id":"a-hrc-61-crp-8-p0073","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"73","seq":74,"section":"IX. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)    Continue its work towards the verification of the identity and a complete\nlist of children who were deported to the Russian Federation or transferred within\noccupied areas of Ukraine;\n(b)    Strengthen its efforts in a relation to the DNA registry that would aid in\nthe identification and recovery of children;\n(c)    Ensure access to multidisciplinary, coordinated and comprehensive\nsupport and services to children and their families to address their specific immediate,\nshort-term and long-term needs, and ensuring the fulfilment of their rights."},{"id":"a-hrc-61-crp-8-p0074","rec_id":"recugxpx8PnTwalHJ","symbol":"A/HRC/61/CRP.8","n":"74","seq":75,"section":"IX. Conclusions and recommendations","text":"The Commission recommends that international community:\n(a)    Coordinate and reinforce its efforts to impress upon the Russian\nFederation the urgency to facilitate the return of children who have been deported to\nthe Russian Federation or transferred within occupied areas of Ukraine;\n(b)    Support Ukraine in responding to the needs of children, parents, legal\nguardians, relatives and caregivers;\n(c)    Contribute both financially and with technical assistance towards a range\nof multidisciplinary and coordinated efforts – including legal, social, psychological,\nmedical, educational, and rehabilitation and reintegration services – for children who\nhave returned."},{"id":"a-hrc-61-61-u0000","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":null,"seq":0,"section":null,"text":"Summary\nIn the present report, the Independent International Commission of Inquiry on\nUkraine presents its latest findings on crimes and violations committed during the full-scale\ninvasion of Ukraine by the Russian Federation.\nThe Commission has continued its investigations concerning the deportation or\ntransfer of children by Russian authorities to the Russian Federation or to Russian-occupied\nareas in Ukraine. Compelling evidence concerning the deportation and transfer of a total of\n1,205 children from five oblasts in Ukraine, verified by the Commission, has led it to\nconclude that these acts amount to crimes against humanity and war crimes of deportation\nand forcible transfer of children.\nThe Russian authorities have systematically failed to disclose the whereabouts of the\nchildren to parents or legal guardians and have kept them in coercive environments,\nobstructing their return. Instead of establishing a system facilitating the return of the children,\nthe authorities have sought their long-term placement with families or in institutions in the\nRussian Federation. Throughout 2022, Russian authorities declared that adoption was their\npreferred option for the placement of these children. The Commission has therefore also\nconcluded that Russian authorities have committed the crime against humanity of enforced\ndisappearance of the children deported or transferred from Ukraine, and the war crime of\nunjustifiable delay in their repatriation.\nFrom the cases investigated by the Commission, 80 per cent of the children have not\nyet been returned. Those who managed to organize returns encountered obstacles, delays and\nsecurity risks. Many parents and legal guardians remain unaware of the fate and whereabouts\nof their children and are still searching for them. Children suffered from trauma and anxiety.\nOne child who managed to return to Ukraine stated: “I was sad, I was scared. I worried that\nI would have to live in the Russian Federation.”\nThe Commission has also investigated the conduct of trials by courts in the Russian\nFederation and in Russian-occupied areas of Ukraine. Civilians and prisoners of war from\nUkraine were mainly charged with terrorism, espionage and violent seizure of power. The\nCommission finds that these courts have deprived the accused persons of fundamental fair","unnumbered":true},{"id":"a-hrc-61-61-u0001","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":null,"seq":1,"section":null,"text":"trial guarantees and have therefore committed grave breaches of international humanitarian\nlaw, which constitute war crimes.\nRussian authorities have systematically used evidence that they fabricated or obtained\nby means of torture or ill-treatment to incriminate the accused. The courts have disregarded\nthe fair trial guarantees concerning the presumption of innocence, the non-retroactivity of\nlaws, the right not to be compelled to confess guilt, the right to public proceedings and the\nright to defence. The evidence of the Commission points to a lack of independence and\nimpartiality of the courts, with predetermined verdicts and the guilt of the accused assumed\nfrom the outset.\nFurthermore, the Commission has investigated the circumstances of nationals from\n17 countries recruited to fight with the Russian armed forces in Ukraine. Many had been\ndeceived and lured from abroad through promises of civilian employment or other lucrative\narrangements. They were coerced to sign contracts written in Russian, which they did not\nunderstand, and assigned dangerous tasks on the front lines.\nIn addition, the Commission interviewed 85 soldiers who had served in the Russian\narmed forces in connection with the hostilities in Ukraine and had since deserted. Most of\nthem testified about violent practices used by commanders against soldiers. These included\nshooting soldiers on the spot, beating them, detaining them in a pit and tying them to a tree,\nas a punishment for refusing to participate in military assaults that would lead to certain death\nor for withdrawing from the front line when injured or lacking supplies. The accounts\ndemonstrate a total disregard for human life and dignity and suggest that the use of violence\nagainst subordinates is widespread and systematic within the Russian armed forces.\nRegarding Ukraine, the Commission recalls that that the overly broad definition of\nthe crime of “collaborative activities” in the country’s Criminal Code has led to prevailing\nlegal uncertainty. The Commission highlights that activities that do not endanger national\nsecurity may also be interpreted as falling within the scope of that crime. On analysing\nrulings of the Supreme Court of Ukraine on this issue, the Commission found that when\ndelineating activities considered lawful, the Supreme Court failed to consider applicable\ninternational humanitarian law, which obliges the occupying Power to ensure that essential\nservices in territories under its control continue to be provided to the civilian population.\nFinally, the Commission documented reports of violations perpetrated during\nmobilization for the Ukrainian armed forces. Such violations include irregular administrative\ndetention, lack of access to a lawyer and hurried examinations by military medical\ncommissions that disregard possible underlying medical issues. Instances of violence have\nbeen recorded against conscientious objectors who were taken by force to recruitment centres\nand military bases, regardless of any expressed readiness to carry out alternative civil service.","unnumbered":true},{"id":"a-hrc-61-61-p0001","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"1","seq":2,"section":"I. Introduction","text":"The Independent International Commission of Inquiry on Ukraine submits the present\nreport to the Human Rights Council pursuant to Council resolution 58/24. This\ncomprehensive report reflects the Commission’s findings of its fourth mandate. The\nCommission is composed of Erik Møse (Chair), Pablo de Greiff and Vrinda Grover."},{"id":"a-hrc-61-61-p0002","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"2","seq":3,"section":"I. Introduction","text":"The principles of independence, impartiality, objectivity and integrity and a victim-\ncentred approach guide all aspects of the Commission’s work.1"},{"id":"a-hrc-61-61-p0003","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"3","seq":4,"section":"I. Introduction","text":"Since its establishment, the Commission has interviewed 2,433 persons (women, men\nand children) and examined documents and open-source material. It has travelled to Ukraine\n27 times. The liquidity crisis at the United Nations has continued to severely affect the\nstaffing of the secretariat of the Commission."},{"id":"a-hrc-61-61-p0004","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"4","seq":5,"section":"I. Introduction","text":"The Commission extends its deep gratitude to victims and witnesses for sharing\nexperiences and to organizations for the information provided."},{"id":"a-hrc-61-61-p0005","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"5","seq":6,"section":"I. Introduction","text":"It appreciates the cooperation of the Government of Ukraine. The Russian Federation\ncontinued not to recognize the Commission, and 39 written requests for access, information\nand meetings remained unanswered."},{"id":"a-hrc-61-61-p0006","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"6","seq":7,"section":"II. Violations of international law","text":"Four years of armed conflict in Ukraine have had a devastating impact on civilians.\nAccording to the Office of the United Nations High Commissioner for Human Rights, as of\nFebruary 2026, over 15,000 civilians had been killed, and over 41,000 civilians injured, since\nthe Russian Federation launched its full-scale invasion in 2022. 2 The Commission has\ncontinued to collect evidence concerning a wide range of crimes and violations of\ninternational human rights law and international humanitarian law committed in the context\nof the ongoing armed conflict, which have a severe and long-lasting impact on women, men,\ngirls and boys. In the present report, the Commission concludes that Russian authorities have\ncommitted the crimes against humanity of deportation and forcible transfer and of enforced\ndisappearance, both targeting children. The Commission has also found evidence of war\ncrimes and other violations of international humanitarian law and international human rights\nlaw."},{"id":"a-hrc-61-61-p0007","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"7","seq":8,"section":"1. Deportation and transfer of children","text":"During its previous mandates, the Commission investigated situations in which\nRussian authorities unlawfully deported children from Russian-occupied areas in Ukraine to\nthe Russian Federation or transferred them to other Russian-occupied areas in Ukraine. The\nCommission has established that these acts amount to war crimes and that Russian authorities\nviolated their obligation under international law to facilitate in every possible way the\nreunification of families dispersed as a result of armed conflict. 3 Under the current mandate,\nthe Commission has investigated additional cases concerning such deportations and transfers\nby Russian authorities. The present report includes a summary of those investigations, while\ndetailed findings on this issue can be found in a conference room paper 4 posted by the\nCommission in March 2026."},{"id":"a-hrc-61-61-p0008","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"8","seq":9,"section":"1. Deportation and transfer of children","text":"The Commission has documented cases concerning the deportation or transfer of a\ntotal of 1,205 children, including the cases previously reported. In its recent investigations, it\nhas verified the deportation of 995 children from 11 institutions in the so-called Donetsk\nPeople’s Republic and the so-called Luhansk People’s Republic that took place shortly before\nthe launch of the full-scale invasion of Ukraine in 2022. Russian authorities claimed that this\nwas an evacuation justified by an imminent security risk emanating from the Government of\nUkraine, at a time when Russian armed forces themselves had massed personnel and military\nequipment at the country’s borders."},{"id":"a-hrc-61-61-p0009","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"9","seq":10,"section":"1. Deportation and transfer of children","text":"Most of the deportations and transfers of children investigated by the Commission\nhave not been temporary as required by law in the case of evacuation. On the contrary,\nRussian authorities at the highest levels of government have coordinated actions to facilitate\nthe long-term placement of the children in the Russian Federation. Russian authorities first\nrelocated the children to temporary transit centres in the Russian Federation or in Russian-\noccupied areas of Ukraine. They further gradually deported or transferred most of the\nchildren to various locations in 21 regions of the Russian Federation, and placed them\nindefinitely with families or in institutions. Children were given Russian citizenship and their\nprofiles appeared on adoption or foster-placement databases."},{"id":"a-hrc-61-61-p0010","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"10","seq":11,"section":"1. Deportation and transfer of children","text":"In public statements, Russian authorities referred to adoptions as the preferred option\nfor placement of the deported children and provided updates on legislative and administrative\nmeasures they undertook to make that possible. Some of the placements the Commission has\ndocumented appear, indeed, to be adoptions. However, around the time of the issuance of\nwarrants of arrest by the International Criminal Court in March 2023, Russian authorities\nbacktracked on those statements, denied that adoptions had been taking place and emphasized\ninstead foster placement in their public declarations. Long-term placements with families\nhave continued."},{"id":"a-hrc-61-61-p0011","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"11","seq":12,"section":"1. Deportation and transfer of children","text":"Four years on, the Commission has found that of the cases of deportations and\ntransfers it has documented, 80 per cent of the children have not yet been returned. Many\nparents and legal guardians 5 remained unaware of the children’s fate and whereabouts,\nmonths or years after the initial deportations or transfers. This has led to prolonged family\nseparations."},{"id":"a-hrc-61-61-p0012","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"12","seq":13,"section":"1. Deportation and transfer of children","text":"In most cases examined, Russian authorities did not establish a system to facilitate the\nreturn of the children to their families or country. Children, and parents and other relatives,\ncarried out their own efforts to locate each other. Returns that could be organized took place\nonly after a series of obstacles, delays and security risks. In this regard, children in\ninstitutions, and in particular younger children or those with disabilities, have almost no\nchance of returning."},{"id":"a-hrc-61-61-p0013","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"13","seq":14,"section":"1. Deportation and transfer of children","text":"Deportations or transfers of children, their disappearance and the ensuing prolonged\nseparation with families have been highly traumatic for all those involved. A mother who has\nnot managed to find her daughter, who had been placed in an unidentified institution in the\nRussian Federation, stated: “I am still looking for my daughter, and I am terribly afraid of\nwhat she might think of me and how she survives there, where many people hate Ukrainians.”\nConcluding observations"},{"id":"a-hrc-61-61-p0014","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"14","seq":15,"section":"1. Deportation and transfer of children","text":"Russian authorities have deported or transferred thousands of children from Ukraine,\nstating that these were evacuations necessitated by the armed conflict. These relocations have\nnot been temporary, as mandated under international humanitarian law. Compelling health,\nmedical treatment or safety reasons – the only legally justifiable reasons for temporary\nevacuation of children – were not the principal motivating factor. Russian authorities did not\nseek the consent of parents, legal guardians or the Ukrainian authorities, as required by law.\nThe removal of children from Ukraine can thus not be qualified as “evacuation” within the\nmeaning of international humanitarian law. The Commission therefore reaffirms its previous\nfinding that unlawful deportations and transfers of children from Ukraine by the Russian\nauthorities amount to war crimes.6"},{"id":"a-hrc-61-61-p0015","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"15","seq":16,"section":"1. Deportation and transfer of children","text":"Furthermore, the Russian authorities did not establish a system to facilitate the\nrepatriation of the children7 and the majority of the children have not returned. The burden\nto locate each other was placed entirely on the children and their families or guardians. This\nconfirms that the Russian authorities continued to violate their obligation under international\nhumanitarian law to facilitate in every possibly way the reunion of families separated during\nthe armed conflict,8 which amounts to the war crime of unjustifiable delay in the repatriation\nof civilians.9"},{"id":"a-hrc-61-61-p0016","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"16","seq":17,"section":"1. Deportation and transfer of children","text":"The deportations and transfers have originated from various locations across a wide\ngeographical area in Russian-occupied areas in Ukraine, following a well-established pattern\nof conduct, indicating that these acts have been widespread and systematic. Russian\nauthorities at the highest levels – including the President, Vladimir Putin, and entities directly\nanswerable to him – have coordinated practical modalities to carry out these deportations and\ntransfers and to further relocate the children in the Russian Federation. The Russian\nauthorities have committed these acts following a consistent and carefully organized plan and\nmodus operandi, initiated even before the full-scale invasion of Ukraine. This demonstrates\nthe existence of a pre-established policy, conceived at the highest level of the Russian State,\nand leads the Commission to conclude that Russian authorities have carried out deportations\nand forcible transfers of children also as a crime against humanity.10"},{"id":"a-hrc-61-61-p0017","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"17","seq":18,"section":"1. Deportation and transfer of children","text":"In most cases investigated, the Russian authorities have not informed the parents or\nother relatives, legal guardians or the Ukrainian authorities of the deportation or transfer of\nthe children and of their fate and whereabouts. Consequently, many of those searching\nremained unaware of the fate and whereabouts of children for months or years. The removal\nof the children from their families and country, without the consent of parents, legal guardians\nor the Ukrainian authorities, also constitutes an abduction.11 Given the coercive environment\nsurrounding the deportations or transfers, the indefinite nature of the placements in the\nRussian Federation and the considerable difficulties faced in finding their family and\ntravelling back to Ukraine, the situation of the children in the Russian Federation amounts to\ndeprivation of liberty.12 Moreover, adoption has far-reaching implications for a child and\ndrastically diminishes the prospect for children to return and reunite with their family.\nRussian authorities have thus committed acts of enforced disappearance against the deported\nor transferred children, which have been widespread and systematic and perpetrated pursuant\nto policy and thus amount to a crime against humanity.13 The acts also constitute human rights\nviolations.14"},{"id":"a-hrc-61-61-p0018","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"18","seq":19,"section":"1. Deportation and transfer of children","text":"The Commission also found that the actions of the Russian authorities, as described\nin the present report, were contrary to several other provisions of international humanitarian\nlaw and international human rights law.\n2.        Violation of fair trial guarantees and fabrication of evidence by Russian authorities\n(a)        Overview"},{"id":"a-hrc-61-61-p0019","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"19","seq":20,"section":"1. Deportation and transfer of children","text":"The Commission has investigated the conduct of trials by Russian Federation courts\nin the context of the full-scale invasion of Ukraine by the Russian Federation. The\nCommission relied on 128 interviews, 218 documents, 28 videos and 1,216 open-source\nreferences. The Commission focused on a sample of 72 trials by four courts in the Russian\nFederation and eight “courts” in Russian-occupied territories of Ukraine, concerning 68\ncivilians and 60 prisoners of war from Ukraine. Of these, 69 trials led to convictions and 3\nare still ongoing. The accused were charged under Russian criminal law, mostly for crimes\nrelated to terrorism, espionage or violent seizure of power, and most were sentenced to\nimprisonment ranging from 8 to 25 years; some have been sentenced to life imprisonment."},{"id":"a-hrc-61-61-p0020","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"20","seq":21,"section":"1. Deportation and transfer of children","text":"In the cases documented, the Commission found that the courts had violated fair trial\nguarantees set out in international human rights law and international humanitarian law,\nnotably the principles of the presumption of innocence, the non-retroactivity of laws, the right\nnot to be compelled to testify against oneself or to confess guilt and the right to be judged by\nan independent and impartial tribunal.15 Russian authorities have deported civilians to try\nthem in the Russian Federation, contrary to international humanitarian law. 16 They have\nrefused to recognize the status of prisoners of war for combatants from Ukraine, depriving\nthem of fair trial guarantees recognized by international humanitarian law. Russian criminal\nlegislation was imposed in the Russian-occupied areas of Ukraine and the jurisdiction of the\nRussian Federation was extended to those areas, contrary to international humanitarian law. 17"},{"id":"a-hrc-61-61-p0021","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"21","seq":22,"section":"1. Deportation and transfer of children","text":"Russian authorities have systematically fabricated evidence they presented in the\ntrials. Numerous testimonies, documents and videos obtained by the Commission\ndemonstrate that Russian investigators used torture and ill-treatment to extract confessions,\nrecord false statements and force signature of documents, which they presented in trials and\nshared with the media for propaganda purposes. During long periods of detention, Russian\nauthorities committed a wide range of violations and crimes against the accused, consistent\nwith the Commission’s past reports."},{"id":"a-hrc-61-61-p0022","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"22","seq":23,"section":"1. Deportation and transfer of children","text":"Witnesses described the trials before courts in the Russian Federation and in Russian-\noccupied areas of Ukraine as seriously vitiated by bias and unfairness, with predetermined\nverdicts. Judges systematically disregarded the rights of the accused and arguments advanced\nby them or on their behalf. One person tried and convicted in a Russian court, recalling her\ntrial, stated: “This was a theatre of farce, where we were mere observers. It was a one-sided\ngame. We couldn’t even speak. All petitions raised by our lawyers were dismissed.” Lastly,\nprior to and during the trials the accused were vilified in the eyes of the public through\npropaganda spread in the Russian pro-government media, creating prejudice against them.\n(b)        Persons subjected to trials in violation of international rules"},{"id":"a-hrc-61-61-p0023","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"23","seq":24,"section":"1. Deportation and transfer of children","text":"In the cases investigated by the Commission, the accused facing trial were men and\nwomen between the ages of 18 and 74 at the time of their arrest, as well as three 16-year-old\nboys and one 17-year-old girl. Most of the accused were men. They were prosecuted for acts\ncommitted in Russian-occupied areas of six oblasts of Ukraine, in the Autonomous Republic\nof Crimea, also in Ukraine, and the Kursk Oblast of the Russian Federation. The accused\nincluded persons who were specifically targeted by Russian authorities, such as employees\nof the Zaporizhzhia nuclear power plant, former members of the anti-terrorist operation,18\nrelatives of members of the Ukrainian armed forces, and prisoners of war of specific military\nunits of Ukraine."},{"id":"a-hrc-61-61-p0024","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"24","seq":25,"section":"1. Deportation and transfer of children","text":"Russian courts refused to recognize the status of prisoners of war for combatants from\nUkraine, holding that the Russian Federation was only conducting a “special military\noperation”. This deprived those persons of fair trial guarantees applicable to prisoners of war,\nwhich they are entitled to under international humanitarian law. 19 In the cases investigated,\ncourts convicted prisoners of war from the Azov, Aidar and Donbas military units of Ukraine\nand sentenced them to severe criminal penalties solely for their membership in those units,\nignoring that combatants participating in hostilities as part of the armed forces of their\ncountry cannot be criminally punished for that reason alone.20"},{"id":"a-hrc-61-61-p0025","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"25","seq":26,"section":"1. Deportation and transfer of children","text":"Furthermore, Russian authorities deported civilians and tried them in courts in the\nRussian Federation, including in military courts, raising concern for the respect of their fair\ntrial guarantees. 21 International humanitarian law requires the occupying Power to try\ncivilians in the occupied territory; deporting civilians is a war crime. 22"},{"id":"a-hrc-61-61-p0026","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"26","seq":27,"section":"1. Deportation and transfer of children","text":"In all the trials examined by the Commission, the courts applied Russian criminal law\nto acts committed in occupied territories of Ukraine, contrary to international humanitarian\nlaw. “Courts” in occupied areas of Ukraine delivered judgments “on behalf of the Russian\nFederation”, thereby extending the jurisdiction of the Russian Federation to the occupied\nterritories, which is also against international humanitarian law. 23\n(c)        Fabrication of evidence, and crimes and violations committed against the accused"},{"id":"a-hrc-61-61-p0027","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"27","seq":28,"section":"1. Deportation and transfer of children","text":"The trials occurred in an environment that was coercive for the accused at all stages\nof the proceedings. During the pretrial investigations and the trials themselves, and after the\ndelivery of the verdicts, Russian authorities committed a wide range of crimes and violations.\nThe accused were held in detention facilities where the Commission had previously\nestablished extensive use of torture. 24 Russian authorities subjected them to unlawful\nconfinement, deportation or transfer to detention facilities in the Russian Federation or in\nRussian-occupied areas of Ukraine; enforced disappearance; torture; sexual violence,\nincluding rape; ill-treatment; and inhuman or degrading treatment. 25 According to\ntestimonies, Russian authorities resorted to torture and ill-treatment while the trials were\nongoing, during transportation and in the court premises. Visible signs of violence on the\naccused were ignored and overlooked by judges and prosecutors."},{"id":"a-hrc-61-61-p0028","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"28","seq":29,"section":"1. Deportation and transfer of children","text":"Personnel of the Federal Security Service, of the Investigative Committee of the\nRussian Federation and others have systematically used torture or ill-treatment to fabricate\nevidence produced in courts. They have made video recordings of staged arrests and crime\nscenes, coercively extracted self-incriminating statements and testimonies incriminating\nothers, and forced the signature of documents. Such material was presented during trials and\nwas disseminated in Russian pro-government media."},{"id":"a-hrc-61-61-p0029","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"29","seq":30,"section":"1. Deportation and transfer of children","text":"In some cases, the dates of arrest listed in official documents were not consistent with\nthe actual dates. The accused spent periods of time in detention without any official record\nand their whereabouts were unknown. During that time, Russian authorities obtained and\nrecorded evidence against them, which was accepted by the courts. In some cases, witnesses\npointed to inconsistencies in the facts of the cases and stated that the accused could not have\ncommitted the alleged acts because they were not present in the place, or even oblast,\nconcerned at the time the incriminated action occurred."},{"id":"a-hrc-61-61-p0030","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"30","seq":31,"section":"1. Deportation and transfer of children","text":"Some of the testimonies against the accused were given by co-detainees after they had\nthemselves been subjected to violence or significant duress, by individuals whom the accused\nhad never met or by anonymous witnesses. A civilian woman was convicted by a court for\nthe murder of a man she said she had never met. After the trial, the main witness against the\naccused woman confessed to her that she had been directed to testify by the Federal Security\nService."},{"id":"a-hrc-61-61-p0031","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"31","seq":32,"section":"1. Deportation and transfer of children","text":"Russian authorities also compelled relatives of accused persons to contribute to the\nfabrication of evidence, through testimonies against their loved ones. To exert pressure on\nthe relatives, Russian authorities detained them, intimidated them and placed menacing\ntelephone calls. Authorities threatened to harm the accused if the relatives failed to cooperate."},{"id":"a-hrc-61-61-p0032","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"32","seq":33,"section":"1. Deportation and transfer of children","text":"Courts usually did not take into consideration the arguments raised by the accused or\non their behalf, including that their statements had been obtained by torture. In one judgment,\na court relied on the testimonies of law enforcement personnel involved in the pretrial\ninvestigation of the case to reject the defence of the accused that the incriminating evidence\nhad been obtained through torture.\n(d)        Violation of fundamental fair trial guarantees"},{"id":"a-hrc-61-61-p0033","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"33","seq":34,"section":"1. Deportation and transfer of children","text":"Courts in the Russian Federation and in Russian-occupied areas in Ukraine have\nsystematically violated a range of fair trial guarantees during criminal proceedings against\ncivilians and prisoners of war from Ukraine. The judges have not acted with independence\nand impartiality, nor have they respected the principles of presumption of innocence,\nindividual responsibility of the accused and non-retroactivity of the law. Judgments have\noften been written in a manner that, from the outset, presumed the guilt of the accused. Judges\nusually adopted the arguments of the prosecution, while ignoring the defence, and aligned\nwith the propaganda circulated in the media. One person who was tried and convicted by a\nRussian court stated: “For them – the so-called justice system in the Russian Federation – the\ndecision to accuse and sentence us was predetermined. I don’t understand why they bothered\nwith this farcical performance with unskilled actors. They did what they were ordered to do.\nFor us, though, these decisions and proceedings would change our lives and the lives of our\nfamilies.”"},{"id":"a-hrc-61-61-p0034","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"34","seq":35,"section":"1. Deportation and transfer of children","text":"A pre-existing bias and reliance on narratives commonly used in the Russian\nFederation are visible in the consideration of the cases. For instance, in almost identical\njudgments against prisoners of war from the Azov brigade, the court noted that the main\nideology of Azov was neo-Nazism and that the members of the brigade fulfilled the criminal\nobjectives of the organization. In another judgment, the court stressed: “The fact that the\nparticipants in the Azov battalion have been committing crimes of a terrorist character is\nwell-known”, in its reasoning concluding that the accused had joined the military unit with\nthe intention of participating in terrorist activity."},{"id":"a-hrc-61-61-p0035","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"35","seq":36,"section":"1. Deportation and transfer of children","text":"In cases concerning prisoners of war prosecuted for terrorism-related charges, courts\nconvicted them to severe penal sentences merely for belonging to military units of Ukraine,\nwithout substantiating their individual criminal responsibility. 26 In the case of prisoners of\nwar from the Azov brigade, the courts relied on a June 2016 decision of the “Supreme Court”\nof the so-called Donetsk People’s Republic that recognized the Azov brigade as a terrorist\norganization. However, the independence claims of the so-called Donetsk People’s Republic\nhave been declared unlawful internationally. Decisions of organs of the so-called republic27\nthus have no legal applicability in relation to Ukrainian citizens. The courts further relied on\na decision of the Supreme Court of the Russian Federation of August 2022, which declared\nthe Azov brigade to be a terrorist organization. This extends the jurisdiction of the occupying\nPower to the occupied territories, contrary to international humanitarian law. Moreover, the\nAugust 2022 decision has often been invoked by Russian courts with respect to facts that\noccurred between February and May 2022, in violation of the principle of non-retroactivity."},{"id":"a-hrc-61-61-p0036","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"36","seq":37,"section":"1. Deportation and transfer of children","text":"Trials, in whole or in part, were regularly conducted behind closed doors. Russian\nauthorities denied some of the accused the right to be defended by a lawyer or forced them\nto waive their right to legal representation under duress. Some of the State-appointed lawyers\ndid not provide an effective defence for the accused and sided with the prosecution.\n(e)   Media coverage and propaganda"},{"id":"a-hrc-61-61-p0037","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"37","seq":38,"section":"1. Deportation and transfer of children","text":"From the time of the arrests, the media and social media channels that are closely\naffiliated with the Government of the Russian Federation disseminated the version of the\ninvestigators without raising questions. Prior to the trials, the accused were vilified and\nconvicted in the eyes of the public through propaganda. This media campaign created\nprejudice against the accused and undermined their chances of receiving a fair trial."},{"id":"a-hrc-61-61-p0038","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"38","seq":39,"section":"1. Deportation and transfer of children","text":"The accused were referred to as “Nazis” and presented as persons capable of plotting\nheinous acts without remorse. In one case, after the arrest of a young prisoner of war, a\nmessage was posted on a Russian Telegram channel stating: “Our troops got their hands on\n… a Nazi and a serviceman of the Azov battalion (a terrorist organization banned in the\nRussian Federation). This jerk is 18 years old, and he has already been brainwashed and\nserves in a terrorist organization.” The post further adds that there is hope he will get the\nlongest possible sentence.\n(f)   Impact"},{"id":"a-hrc-61-61-p0039","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"39","seq":40,"section":"1. Deportation and transfer of children","text":"Being accused in criminal proceedings with no fair opportunity to defend themselves\nhas taken a deep toll on those prosecuted and convicted, and on their families. In its previous\nreports, the Commission has emphasized the severe impact of prolonged confinement,\nenforced disappearance, deportation, transfer and torture, as well as of sexual violence. In\naddition, convictions that carry lengthy prison terms leave the accused and their families with\nan unbearable uncertainty as to when, or even whether, they will see each other again. A\nwoman who saw photos of her son in court said that she could not stop crying. She had never\nseen him like that: he had lost significant weight and looked exhausted and scared. A small\nnumber of those convicted have managed to return as part of prisoner swaps. A mother whose\nson has been sentenced and is imprisoned in the Russian Federation stated: “Every time there\nare exchanges, I want to go – but I fear my heart wouldn’t survive the pain of not seeing my\nson among those returned.”"},{"id":"a-hrc-61-61-p0040","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"40","seq":41,"section":"1. Deportation and transfer of children","text":"The gendered impact of these cases highlights the suffering of families, most often\nwomen left behind in occupied areas, who face the emotional and economic fallout of the\nabsence of those accused or convicted. Those who manage to return suffer from deep physical\nand psychological consequences. If they are from occupied areas, they are usually unable to\nreturn to their residences owing to security risks, and are thus separated from family members\nand face challenges relating to reintegration into society, notably concerning work and\nhousing.\n(g)   Concluding observations"},{"id":"a-hrc-61-61-p0041","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"41","seq":42,"section":"1. Deportation and transfer of children","text":"The Commission’s investigations show that, in the context of the full-scale invasion\nof Ukraine, trials carried out by Russian courts or by “courts” run on their behalf in Russian-\noccupied territories in Ukraine have not respected fundamental fair trial guarantees outlined\nin international human rights law. The courts have disregarded the guarantees concerning the\npresumption of innocence, the non-retroactivity of laws, the right not to be compelled to\nconfess guilt, the right to public proceedings and the right to defence. The verdicts aligned\nwith the case of the prosecution, as the guilt of the accused was assumed from the outset,\ndemonstrating a lack of independence and impartiality of the courts."},{"id":"a-hrc-61-61-p0042","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"42","seq":43,"section":"1. Deportation and transfer of children","text":"In addition, the Russian authorities have not respected the obligations regarding fair\ntrial that they bear as an occupying Power. Russian criminal law was applied to occupied\nareas in Ukraine, and Russian Federation jurisdiction was extended to those areas. Russian\nauthorities have deported civilians to the Russian Federation, which is a war crime, and have\nsubjected them to trials in military courts. Russian authorities have systematically used\nevidence that they fabricated by means of torture or ill-treatment and ignored the arguments\nof the defence. By depriving civilians and prisoners of war of the right to a fair trial, Russian\nauthorities have committed grave breaches of international humanitarian law that constitute\nwar crimes.28"},{"id":"a-hrc-61-61-p0043","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"43","seq":44,"section":"1. Deportation and transfer of children","text":"The violations of fair trial guarantees and the crimes and violations committed during\npretrial investigations have followed a well-established pattern, demonstrating that they have\nbeen systematic.29 The recurrence and open commission of such violations for four years,\nand their wide public coverage, demonstrates that this modus operandi is commonly accepted\nby the Government of the Russian Federation. This raises serious concern regarding the fate\nof civilians and prisoners of war who have already been convicted, and that of those awaiting\ntrial in Russian courts."},{"id":"a-hrc-61-61-p0044","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"44","seq":45,"section":"3. Sexual and gender-based violence","text":"The Commission continued to investigate incidents of sexual and gender-based\nviolence committed since 2022 in areas that then came under Russian control in the\nChernihiv, Donetsk, Kharkiv, Luhansk, Mykolaiv and Zaporizhzhia Oblasts of Ukraine. In\nprevious reports, the Commission covered cases of sexual violence committed in the context\nof the Russian occupation. 30 Consistent with previously documented patterns, Russian\nauthorities have committed sexual violence against women and girls during break-ins into\ncivilian houses, have assaulted women and girls in occupied villages and have committed\nsexual violence against men and women in detention."},{"id":"a-hrc-61-61-p0045","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"45","seq":46,"section":"3. Sexual and gender-based violence","text":"The cases documented demonstrate the particular vulnerability of the victims to sexual\nand gender-based violence during military occupation. The acts of abuse were perpetrated in\na context in which large numbers of military personnel were deployed and took control of\nrecently captured localities, conducted systematic searches, imposed curfews, established\ncheckpoints and were searching for a place to live, food and supplies for themselves. Sexual\nviolence was perpetrated along with other violations and crimes. Its use as a tool of\ndomination and torture highlights its gendered dimension. The new cases illustrate the\ncontinued cruelty inflicted by the perpetrators against victims. In cases recently investigated\nby the Commission, the victims were civilian women and girls, one civilian man, and women\nprisoners of war; their ages ranged from 13 to 52 years."},{"id":"a-hrc-61-61-p0046","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"46","seq":47,"section":"3. Sexual and gender-based violence","text":"In one case, in April 2022, in a village of Kherson Oblast, Russian armed forces twice\ndetained a 26-year-old man who was a former contract soldier for the Ukrainian armed forces.\nThey interrogated him and held him in inhuman conditions in improvised detention facilities,\nincluding in a basement and in a cage. He was subjected to severe torture, consisting of\nrepeated beatings, mock executions, strangulation, and sexual violence by penetration with\nthe handle of a shovel. This caused grievous physical injury and required surgery. He stated:\n“They tortured me and left me to die. It’s a miracle I’m still alive. Those weeks changed my\nlife and my family’s forever. Nothing can make me strong and healthy again. I can never\nforgive them.”"},{"id":"a-hrc-61-61-p0047","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"47","seq":48,"section":"3. Sexual and gender-based violence","text":"In November 2022, in a village of Mykolaiv Oblast, Russian soldiers grabbed two\ngirls, then aged 13 and 15 years, as they were walking in a street. The soldiers placed bags\nover the girls’ heads, forced them into a car and kept them for three days in an apartment.\nThere, the soldiers compelled the girls to consume alcohol, raped them and beat one of them."},{"id":"a-hrc-61-61-p0048","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"48","seq":49,"section":"3. Sexual and gender-based violence","text":"In most cases, the perpetrators were military personnel from the Russian armed forces.\nSeveral among them have been identified by name, unit and call sign. In June 2025, in an\noccupied settlement in Zaporizhzhia Oblast, one perpetrator even admitted in an interview\nwith a journalist to sexual intercourse with two girls. The Commission established that the\ngirls were 14 and 15 years old at the time."},{"id":"a-hrc-61-61-p0049","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"49","seq":50,"section":"3. Sexual and gender-based violence","text":"In another case, attempts by the victim to report the situation to the military superiors\nwere met with denials, threats and cover-ups. In yet another incident, perpetrators were\nbriefly detained and then released. The Commission is not aware of any judicial prosecution\nby Russian authorities concerning such cases."},{"id":"a-hrc-61-61-p0050","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"50","seq":51,"section":"3. Sexual and gender-based violence","text":"Sexual violence has led to multifaceted harms. Victims suffered physical injuries –\nsome long-term or permanent – often requiring surgery and medical treatment, as well as\ndeep psychological trauma, including suicidal thoughts. Families have been shattered;\nvictims faced shame, stigmatization and family separations. Some no longer felt safe in their\nhomes and felt compelled to move, leaving their former lives behind."},{"id":"a-hrc-61-61-p0051","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"51","seq":52,"section":"3. Sexual and gender-based violence","text":"Such incidents have had a particular impact on girls, as victims, or on children, where\nthe mother was a victim of sexual violence. One woman relocated multiple times after she\nwas violently assaulted and repeatedly raped. Another victim became pregnant and has a\nchild as a result of the rape. Now, as she raises the child with love and strives to shield him\nfrom trauma or knowledge of the circumstances of his birth, she faces the dilemma of\nreporting the case to seek justice, but fears this could reopen wounds for herself and the child.\nThe Commission also examined reports concerning survival sex with Russian soldiers, for\nperceived protection, food or money."},{"id":"a-hrc-61-61-p0052","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"52","seq":53,"section":"3. Sexual and gender-based violence","text":"The trauma experienced by the victims is compounded by systemic shortcomings in\nprotection, training of investigators and reparations. Victims have many acute needs, which\nmay include housing, medical care and psychological support. In all those areas, survivor-\ncentred and child and gender-sensitive support mechanisms are key to providing much-\nneeded assistance and relief for victims and their families."},{"id":"a-hrc-61-61-p0053","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"53","seq":54,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"The Commission has investigated the situation of nationals from 17 countries who\nwere recruited, voluntarily or through deception, to fight together with the Russian armed\nforces in Ukraine. They include men from Azerbaijan, Belarus, Brazil, Cuba, Egypt, Ghana,\nIndia, Iraq, Kazakhstan, Kenya, Nepal, Somalia, Sri Lanka, Tajikistan, Türkiye, Uganda and\nYemen. The Commission collected their testimonies or those of family members. They were\nrecruited into the Russian armed forces under various circumstances, after being approached\nby Russian authorities or civilian persons on the authorities’ behalf. Most of the men had no\nmilitary experience and did not understand the Russian language. After training, usually\nlasting between one week and 30 days, they were forced to serve on front lines in Ukraine,\nand often were assigned extremely dangerous duties. The men were interviewed by the\nCommission after being captured by or having surrendered to Ukrainian armed forces. Some\nhad appealed to their embassies in Ukraine, but most received no assistance."},{"id":"a-hrc-61-61-p0054","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"54","seq":55,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"At the time of their recruitment, most of the men were already present in the Russian\nFederation. They joined the Russian armed forces voluntarily in the hope of regularizing their\nstay and to receive a salary. Others were recruited while they were serving sentences in\nRussian detention facilities, including after significant coercion. An inmate who had\nattempted to resist recruitment stated that a recruiting officer had told him: “I will do\neverything so that you end up in the special military operation.”"},{"id":"a-hrc-61-61-p0055","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"55","seq":56,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"Others found themselves in the Russian armed forces after having been deceived and\nlured from abroad through promises of civilian employment or other lucrative arrangements.\nTheir travel to the Russian Federation had been arranged by recruiters. They had been met at\na Russian airport by military personnel, brought to military bases and pressured into signing\ncontracts written in Russian, which they did not understand. One man recruited in this manner\nenquired about the civilian company that he thought had hired him, but was told: “No, it’s a\nmistake, in this place you are going to fight, you are going to the war – I can see your\ndocuments, your signature, your contract with the Russian army.”\n(b)        Violence committed during deployment"},{"id":"a-hrc-61-61-p0056","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"56","seq":57,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"The Commission interviewed 85 soldiers who had deserted from the Russian armed\nforces. Most of them had been deployed across front-line areas in seven oblasts in Ukraine\nand in the Kursk Oblast of the Russian Federation, where they had served between a few days\nto over three years. Of these soldiers, 61 had experienced or witnessed, or knew of, various\nforms of violent, cruel and inhuman treatment or deprivation of liberty practised or ordered\nby commanders against their subordinates, leading to death, serious injury and trauma. The\nCommission also collected 82 open-source documents demonstrating a similar pattern of\nviolations."},{"id":"a-hrc-61-61-p0057","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"57","seq":58,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"The testimonies analysed show that military commanders arbitrarily imposed,\npractised or tolerated extreme violence and coercion against soldiers as punishment for\nrefusing to participate in military operations that meant almost certain death, and for\nwithdrawing from the front line, even when this was justified by injury, lack of ammunition\nor lack of food and water. Punishment was also inflicted on those who dared to speak up\nagainst such practices or attempted to desert, and even for small infractions. Soldiers\ndescribed being treated like “cannon fodder” or “disposable material”, sent on so-called\n“meat assaults” without training, preparation, necessary equipment, artillery support or an\nevacuation plan, and forced to advance at all costs. They also reported the practice, ordered\nby the commanders, of shooting on the spot soldiers who withdrew without permission;\nsometimes by fellow soldiers."},{"id":"a-hrc-61-61-p0058","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"58","seq":59,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"Other forms of punishment included mock executions, shooting in or around legs and\nsevere beatings. A former soldier recounted that a man from his unit had been beaten to death\nwhen he refused to go on a military assault; his body was left at the entrance of the building\nfor three days, for everyone to see what happened to those who refused to obey orders."},{"id":"a-hrc-61-61-p0059","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"59","seq":60,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"Many interviewees reported that soldiers were detained in basements, pits dug in the\nground, containers or cages, in inhuman, completely unhygienic conditions, without food or\nwater for long periods. Several interviewees described the practice of tying soldiers to a tree.\nDeprivation of liberty was accompanied by violent treatment, threats and forced nudity.\nThere are also reports about commanders extorting money from soldiers, using violence and\nthreats.\n(c)        Concluding observations"},{"id":"a-hrc-61-61-p0060","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"60","seq":61,"section":"4. Violations committed during mobilization and against soldiers of the Russian armed","text":"The culture of violence and the absence of oversight within the Russian armed forces\nhad already been widely documented before the full-scale invasion of Ukraine. Arbitrarily\nimposed violent practices have continued and appear to be common in Russian armed forces\nunits deployed in different oblasts in Ukraine. The evidence collected demonstrates abusive\nbehaviour, cruelty, humiliation, inhuman treatment and a total disregard for human life and\ndignity, perpetrated with a sense of impunity. The soldiers interviewed by the Commission\ndescribed strikingly similar forms of ill-treatment, suggesting that the practice of using\nviolence against subordinates in the Russian armed forces is widespread and systematic. This\ncontributes to a further consolidation of the culture of violence that is bound to affect\ncivilians."},{"id":"a-hrc-61-61-p0061","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"61","seq":62,"section":"1. Judicial consideration of the crime of collaboration","text":"The Commission has previously found that Ukrainian authorities committed\nviolations of human rights against persons alleged to have collaborated with Russian\nauthorities. It has documented instances of arbitrary arrest and detention, torture, ill-\ntreatment, and enforced disappearance occurring prior to trial proceedings. 31 The\nCommission has further noted the prevailing legal uncertainty surrounding the definition of\n“collaborative activities” in article 111-1 of the Criminal Code of Ukraine, has considered it\noverly broad and has recommended that the legislative framework be harmonized with\ninternational standards.32"},{"id":"a-hrc-61-61-p0062","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"62","seq":63,"section":"1. Judicial consideration of the crime of collaboration","text":"As at 17 February 2026, the Office of the Prosecutor General of Ukraine had\nregistered 24,365 cases concerning crimes against national security, the majority (10,777) for\ncollaborative activities. In 2025 alone, courts convicted 1,115 individuals for collaborative\nactivities.33"},{"id":"a-hrc-61-61-p0063","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"63","seq":64,"section":"1. Judicial consideration of the crime of collaboration","text":"Article 111-1 lists seven different types of “collaborative activities”. Under the current\nmandate, the Commission has examined Supreme Court rulings to assess to what extent the\nCourt has addressed previously expressed concerns. The Commission has analysed all 33\nrelevant Supreme Court rulings and reviewed more than 100 decisions from courts of first\nand second instance."},{"id":"a-hrc-61-61-p0064","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"64","seq":65,"section":"1. Judicial consideration of the crime of collaboration","text":"The Commission underscores the need for clarification of article 111-1, especially its\ndefinitional elements, to avoid legal uncertainty and address its overly broad scope. Notably,\nactivities that do not in any way endanger national security may also fall within its scope. For\ninstance, human rights organizations have pointed out that Ukrainian courts found a violation\nof article 111-1 in cases of persons acting as a street representative 34 or a security guard for\na law-enforcement building.35"},{"id":"a-hrc-61-61-p0065","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"65","seq":66,"section":"1. Judicial consideration of the crime of collaboration","text":"In articulating the scope of “collaborative activities”, it is essential to ensure\nconformity with the international humanitarian law framework applicable in situations of\noccupation, obliging the occupying Power to ensure that essential services in territories under\nits control continue to be provided to the civilian population, such as medical services, public\nhealth or care and education of children.36 The occupying Power must cooperate with national\nand local authorities, and may also compel civilians under occupation to do work which is\nnecessary either for the needs of the army of occupation, or for the public utility services, or\nfor the feeding, sheltering, clothing, transportation or health of the population of the occupied\ncountry. However, the occupying Power shall not force protected persons to serve in its\narmed or auxiliary forces.37"},{"id":"a-hrc-61-61-p0066","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"66","seq":67,"section":"1. Judicial consideration of the crime of collaboration","text":"The role of the Supreme Court of Ukraine is limited to assessing whether first and\nsecond instances correctly applied substantive and procedural law; whether any significant\nprocedural violations occurred; and whether the punishment imposed is disproportionate.38\nThe Supreme Court cannot re-examine evidence, reassess the reliability of evidence or\nestablish new facts."},{"id":"a-hrc-61-61-p0067","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"67","seq":68,"section":"1. Judicial consideration of the crime of collaboration","text":"The Commission has analysed whether the Supreme Court has relied on international\nlaw when interpreting article 111-1 of the Criminal Code. Overall, the Court did not invoke\nrelevant international humanitarian law applicable to occupied territories. On the other hand,\nin some cases it made reference to the case law of the European Court of Human Rights,\nmainly concerning procedural matters, such as the conditions for handing down judgments\nin absentia."},{"id":"a-hrc-61-61-p0068","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"68","seq":69,"section":"1. Judicial consideration of the crime of collaboration","text":"Adding to legal uncertainty, in some cases first and second instance courts applied\nnational security provisions of the Criminal Code, including those in article 111-1,\nretroactively39 or failed to clearly establish the period during which the alleged offence took\n32 See https://www.ohchr.org/sites/default/files/2023-08/A_HRC_52_CRP.4_En%20%28003%29.pdf,\nparas. 855–857.\n33 Office of the Prosecutor General of Ukraine, “Collaborationism has consequences: 14 suspicions in a\nweek and more than a thousand verdicts in 2025”, 6 February 2026.\n34 A street representative is a community liaison who represents residents of a specific street in dealings\nwith local authorities. See Criminal Court of Cassation of Ukraine, Case No. 202/3884/23, 29 January\n2025. Available at https://reyestr.court.gov.ua/Review/124904191 (in Ukrainian).\nplace. Although none of the cassation appeals examined explicitly raised the issue of\nretroactive application of the law, Ukrainian law requires the Supreme Court to pay particular\nattention to this matter. 40 In one case reviewed by the Supreme Court, both the first and\nsecond court judgments and the decision of the Supreme Court stated that the collaborative\nactivity had begun on 24 February 2022, and that the circumstances and period of time of the\nactivity had not been established. Because the alleged criminal conduct began prior to 15\nMarch 2022 – the date on which the legislation establishing the crime entered into force –\nand continued for an undetermined period, this gives rise to uncertainty regarding the\nlegislation’s applicability overall.41"},{"id":"a-hrc-61-61-p0069","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"69","seq":70,"section":"1. Judicial consideration of the crime of collaboration","text":"The Supreme Court has attempted to clarify which activities fall outside what is\nunderstood as “collaborative activity”.42 However, it has relied on an interpretation that fails\nto consider the applicable international humanitarian law mentioned above. When delineating\nactivities considered lawful, the Supreme Court did not engage with the substantive nature\nof the acts as mentioned in international law but simply focused on the administrative and\ncontractual framework, in particular formal employment with the occupying Power. In one\ncase, the Supreme Court explicitly mentioned that “the specific nature or content of the work\nperformed by [the accused] in this particular case does not affect the legal qualification of his\nconduct.43 The Commission notes that, in a dissenting opinion in another case, one judge\nstressed that the court had failed to consider relevant international humanitarian provisions\nwhen evaluating the accused’s actions, which were aimed at supplying the population of the\noccupied territory with solid fuel for stove heating.44"},{"id":"a-hrc-61-61-p0070","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"70","seq":71,"section":"1. Judicial consideration of the crime of collaboration","text":"The interpretation of the Supreme Court likewise dominates the analysis of the\nexistence of a coercive environment in cases where the accused assumed an official position\nconsidered as a “collaborative activity”. In one situation, the accused became head of the\nsocial security department, performed organizational and administrative functions and\nreceived remuneration in currency of the Russian Federation. The Supreme Court held that\nthis could not be regarded as a means of survival under occupation, ignoring evidence\nregarding threats against the nephew of the defendant and the broader contextual\ncircumstance of the occupation, including the impossibility of gaining employment without\nsatisfying conditions imposed by the occupying Power.45"},{"id":"a-hrc-61-61-p0071","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"71","seq":72,"section":"1. Judicial consideration of the crime of collaboration","text":"The Commission noted a similar approach in several collaboration cases involving\npublic denial of armed aggression, or online activity, for instance reposts, likes or comments,\nprohibited under article 111-1. In one such case, the Supreme Court upheld the conviction of\na construction worker for denying the aggression by the Russian Federation against Ukraine\nand for sending a Viber message containing a similar opinion to a colleague. 46 The defence\nargued that private communication cannot be considered public denial, but the Supreme\nCourt upheld the lower court’s broad interpretation. In a dissenting opinion, one judge\nstressed that no evidence supported the offence and that a private message cannot be\nconsidered “public”.47"},{"id":"a-hrc-61-61-p0072","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"72","seq":73,"section":"1. Judicial consideration of the crime of collaboration","text":"The Supreme Court’s approach when reviewing the cases brought before it has not\nbeen conducive to remedying the most significant shortcomings of article 111-1 of the\nprovision. See Zhovtnevy District Court, Case No. 212/3835/22, 9 August 2022. Available at\nhttps://reyestr.court.gov.ua/Review/105646959 (in Ukrainian).\nCriminal Code; the Commission also acknowledges that the Court must decide within the\nlimits of its review mandate. This reinforces the Commission’s view that amendments to\nunclear provisions related to crimes against national security are needed to ensure compliance\nwith relevant international legal standards. Moreover, those provisions should be tailored to\nprotect national security without imposing an impossible burden on civilians."},{"id":"a-hrc-61-61-p0073","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"73","seq":74,"section":"2. Violations committed during mobilization","text":"The Commission has examined reports concerning violations committed during the\nmobilization process carried out by the Ukrainian armed forces in 14 oblasts of Ukraine. The\nCommission interviewed 75 persons, including men liable for military service, their relatives,\nwitnesses, lawyers and military personnel."},{"id":"a-hrc-61-61-p0074","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"74","seq":75,"section":"2. Violations committed during mobilization","text":"In the situations examined, men had been apprehended by police and staff of territorial\ncentres for recruitment. They were brought to a territorial centre for recruitment, held under\nadministrative detention without regard to the applicable rules, then hastily sent to military\nunits after examination by a military medical commission. The men reported that their\ntelephones had been confiscated, their relatives and employers had not been informed, and\nthey had not been given the opportunity to contact a lawyer. Relatives were unaware of the\nmen’s whereabouts and had faced difficulties in finding them."},{"id":"a-hrc-61-61-p0075","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"75","seq":76,"section":"2. Violations committed during mobilization","text":"Lawyers interviewed by the Commission consistently reported difficulties in gaining\naccessing to their clients in territorial centres for recruitment. This violates the right of\nindividuals to legal assistance and opens the door to other violations. The Commission notes\nsome efforts on the side of Ukrainian authorities to address this issue but information it has\ncollected indicates that challenges remain."},{"id":"a-hrc-61-61-p0076","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"76","seq":77,"section":"2. Violations committed during mobilization","text":"In several instances, military medical commissions, which establish whether an\nindividual is fit for military service, disregarded previous medical diagnoses that deemed the\nmen unfit to serve. Testimonies also mentioned hurried medical examinations. In some\ndocumented instances, the disregarding of a person’s medical condition apparently\ncontributed to health deterioration.\nSituation of conscientious objectors"},{"id":"a-hrc-61-61-p0077","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"77","seq":78,"section":"2. Violations committed during mobilization","text":"The Commission documented the particular situation of conscientious objectors who\nrefuse to join certain military activities due to their convictions. It interviewed men who were\nactive members of four different religious groups long before the onset of the full-scale\ninvasion. All of them have refused to carry out a military activity and have expressed\nreadiness to carry out alternative civil service."},{"id":"a-hrc-61-61-p0078","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"78","seq":79,"section":"2. Violations committed during mobilization","text":"Conscientious objectors interviewed reported that regardless of their express refusal\nto carry out any military activity, they had been taken by force to a territorial centre for\nrecruitment and further to a military camp. Several among them experienced or witnessed\nphysical violence, including beatings by territorial centre for recruitment staff and military\npersonnel. They reported that in the military camps they had been subjected to punishment\nand psychological pressure, such as mock executions, confinement for long periods in a pit\ndug in the ground, including in winter; threats of sexual violence; and denial of food."},{"id":"a-hrc-61-61-p0079","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"79","seq":80,"section":"3. Concluding observations","text":"The rapid manner in which men are mobilized for recruitment by the authorities, with\nlegitimate medical conditions or other impediments sometimes disregarded, combined with\nthe lack of access to legal assistance, makes it difficult for them to challenge the legality of\nthe process. It may be months before a court can rule on the legality of the mobilization, a\nperiod during which the person continues to serve in the armed forces. And even if the court\ndecides that a person was mobilized illegally, the mobilization is generally considered\nirreversible. Reports regarding violent treatment of conscientious objectors during\nmobilization are a source of concern."},{"id":"a-hrc-61-61-p0080","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"80","seq":81,"section":"3. Concluding observations","text":"Although Ukraine is operating under martial law and facing an armed conflict,\ncompliance with legal obligations in the context of mobilization remains essential to ensuring\nan appropriate balance between citizens’ rights and duties and to maintaining public trust in\nthe authorities."},{"id":"a-hrc-61-61-p0081","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"81","seq":82,"section":"III. Conclusions and recommendations","text":"The Commission is concerned at the wide array of crimes and violations it has\ninvestigated, and at their effects on the victims and their families. Russian authorities\nhave continued to commit numerous violations and crimes. In the present report, the\nCommission concludes that crimes against humanity and war crimes by Russian\nauthorities have targeted children, who are among the most vulnerable victims. These\ncrimes have irreversible consequences on those children’s lives and their future. The\nCommission has found more cases of sexual violence that has led to physical and\npsychological trauma. It has also documented trials held by Russian courts in the\ncontext of the full-scale invasion that deprived the accused of fundamental fair trial\nguarantees and led to unfair convictions with long sentences of deprivation of liberty.\nExtreme violence committed within the Russian armed forces further illustrates the\ndisregard for human life and dignity and contributes to a further consolidation of the\nculture of violence."},{"id":"a-hrc-61-61-p0082","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"82","seq":83,"section":"III. Conclusions and recommendations","text":"The Commission has emphasized the importance of a victim-centred approach.\nVictims have suffered physical and psychological trauma and have acute needs,\nincluding housing, medical care and psychological and reintegration support. In this\nregard, accountability – both judicial and non-judicial – is key to providing much-\nneeded relief."},{"id":"a-hrc-61-61-p0083","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"83","seq":84,"section":"III. Conclusions and recommendations","text":"Concerning Ukraine, the Commission has underscored that the overly broad\ndefinition of the crime of “collaborative activities” in the Ukrainian Criminal Code has\nled to prevailing legal uncertainty. Rulings of the Ukrainian Supreme Court illustrate\nthe risk that activities pertaining to essential services that must be provided to the\npopulation may fall within the scope of that provision. The Commission also\ndocumented violations reported during mobilization for the Ukrainian armed forces\nand against conscientious objectors."},{"id":"a-hrc-61-61-p0084","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"84","seq":85,"section":"III. Conclusions and recommendations","text":"The recommendations made in previous reports of the Commission remain\nrelevant. Comprehensive recommendations relating to violations and crimes targeting\nchildren can be found in the conference room paper prepared by the Commission in the\ncontext of the sixty-first session of the Human Rights Council. 48 The Commission sets\nout below specific recommendations to address issues developed in the present report."},{"id":"a-hrc-61-61-p0085","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"85","seq":86,"section":"III. Conclusions and recommendations","text":"The Commission recommends that the Russian Federation:\n(a)    Cease the prosecution of prisoners of war for lawful acts stemming\nexclusively from their direct participation in hostilities;\n(b)    Uphold, at all stages of criminal proceedings, for all accused – both\nprisoners of war and civilians – all applicable guarantees for a fair trial, including the\nright to an independent and impartial court, presumption of innocence, protection\nagainst self-incrimination, the right to present a defence and to have effective legal\nrepresentation, and non-retroactive application of the law;\n(c)    Put an end to all violations including torture, ill-treatment, inhuman or\ndegrading treatment and sexual violence, committed during criminal proceedings, as\nmethods of obtaining incriminating evidence;\n(d)    Respect international humanitarian law by discontinuing the application\nof Russian criminal law in the occupied territories of Ukraine and the extension of the\njurisdiction of the Russian Federation over those territories;\n(e)     Ensure that reporting by State-owned or State-sponsored media is free\nfrom influence or any form of biased commentary and that it does not in any way\nprejudice trials;\n(f)   Take all measures possible to prevent sexual and gender-based violence\nand ensure the effective and impartial investigation, as well as prosecution and\npunishment, of such crimes and violations;\n(g)    Cease the recruitment of foreign nationals – whether residing abroad or\nwithin the territory of the Russian Federation – into the Russian armed forces, in\nparticular recruitment through inducement, deception or any other means that vitiates\nfree and informed consent;\n(h)   Cease any form of violence, ill-treatment or torture against members of\nits armed forces and ensure impartial investigation and effective prosecution of all such\nviolations;"},{"id":"a-hrc-61-61-p0086","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"86","seq":87,"section":"III. Conclusions and recommendations","text":"The Commission recommends that Ukraine:\n(a)   Give renewed consideration to amending overly broad criminal provisions\nrelated to collaborative activities, with a view to tailoring them specifically to the\nprotection of national security and ensuring full compliance with relevant international\nlegal standards;\n(b)   Pursue capacity-building for lawyers, prosecutors and judges on\ndetermining the scope of collaborative activities while adhering to international legal\nstandards;\n(c)    Continue monitoring and reviewing the mobilization process for military\nservice, paying particular attention to the initial stage carried out by territorial centres\nfor recruitment, to ensure that all rights of mobilized persons, including the right to\nlegal assistance and conscientious objection, are respected;\n(d)    Prevent and cease any form of violence during the mobilization and\ndeployment process and ensure the effective and impartial investigation and\nprosecution of any violation."},{"id":"a-hrc-61-61-p0087","rec_id":"recFgrSZhEmSTQra7","symbol":"A/HRC/61/61","n":"87","seq":88,"section":"III. Conclusions and recommendations","text":"The Commission recommends that the international community:\n(a)    Strengthen advocacy of and support for independent monitoring of the\ndetention of and trial proceedings for Ukrainian civilian detainees and prisoners of war\nin the Russian Federation;\n(b)   Expand legal and humanitarian assistance to families in Ukraine of\nUkrainian detainees under the authority of the Russian Federation;\n(c)   Provide technical and material resources for multidisciplinary and\ncoordinated services – including legal, social, psychological, medical, rehabilitation and\nreintegration services, as well as livelihood support – for all civilian detainees and\nprisoners of war who have returned;\n(d)    Continue to support survivor-centred and gender-responsive\nprogrammes for victims of sexual and gender-based violence, ensuring confidential\naccess to comprehensive healthcare (including sexual and reproductive services),\ntrauma-informed psychosocial support, legal aid, safe shelters and livelihood\nassistance; and provide stigma-sensitive support to children born as a result of rape and\ntheir caregivers;\n(e)     Continue to build the capacity of lawyers, prosecutors and judges with\nrespect to international legal standards."}]});